export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: Record<string, string>;
  correctOption: string;
  correctAnswer: string;
  questionType: string;
  explanation?: any;
}

export const MCQ_BANK_2: MCQItem[] = [{"id":"P1_U2_MCQ_001","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_001","question":"A clothing factory pays its sewing machinists $3.00 for every completed jacket they produce, with no fixed basic salary. Which payment method is the factory using?","options":{"A":"Time-rate wage","B":"Piece-rate payment","C":"Annual salary","D":"Profit-sharing bonus"},"correctOption":"B","correctAnswer":"Piece-rate payment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because piece-rate payment rewards workers a fixed amount for each unit of output produced ($3.00 per jacket).","distractor_reasons":{"A":"Incorrect because time-rate wages pay workers based on hours worked rather than units produced.","B":"Correct selection.","C":"Incorrect because an annual salary is a fixed yearly amount paid regardless of exact output volume.","D":"Incorrect because profit-sharing distributes a percentage of overall company profits rather than a fixed rate per unit made."}}},{"id":"P1_U2_MCQ_002","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_002","question":"A logistics company converts temporary warehouse workers onto permanent employment contracts and provides full protective safety gear. According to Maslow's hierarchy of needs, which level of need is the company primarily satisfying?","options":{"A":"Self-actualization needs","B":"Esteem needs","C":"Safety and security needs","D":"Social needs"},"correctOption":"C","correctAnswer":"Safety and security needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because permanent job contracts provide financial/employment security while protective gear ensures physical workplace safety.","distractor_reasons":{"A":"Incorrect because self-actualization involves reaching one's full creative and personal potential.","B":"Incorrect because esteem needs involve recognition, status, and respect from others.","C":"Correct selection.","D":"Incorrect because social needs involve friendship, teamwork, and belonging at work."}}},{"id":"P1_U2_MCQ_003","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_003","question":"An electronics manufacturer upgrades its staff canteen, improves factory lighting, and ensures basic wages match industry averages. According to Herzberg's two-factor theory, what effect will these actions have on workers?","options":{"A":"They will act as long-term motivators that maximize employee creativity","B":"They will satisfy self-actualization needs and eliminate all staff turnover","C":"They will automatically double worker productivity on assembly lines","D":"They will act as hygiene factors that prevent job dissatisfaction without actively motivating higher effort"},"correctOption":"D","correctAnswer":"They will act as hygiene factors that prevent job dissatisfaction without actively motivating higher effort","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Herzberg classifies working conditions and basic pay as hygiene factors: improving them removes dissatisfaction, whereas true motivation requires motivators such as responsibility and achievement.","distractor_reasons":{"A":"Incorrect because Herzberg distinguishes hygiene factors from true motivators like recognition and promotion.","B":"Incorrect because self-actualization is a Maslow concept, and hygiene factors alone do not eliminate turnover.","C":"Incorrect because hygiene factors prevent dissatisfaction rather than directly driving higher productivity.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_004","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_004","question":"A bottling plant times every hand movement of its packing workers and introduces a strict piece-rate pay system linking earnings directly to bottles packed per hour. Which motivation theorist's ideas is management applying?","options":{"A":"F.W. Taylor","B":"Abraham Maslow","C":"Frederick Herzberg","D":"Elton Mayo"},"correctOption":"A","correctAnswer":"F.W. Taylor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because F.W. Taylor's scientific management advocated analyzing tasks into standardized steps and motivating workers primarily through financial piece-rate rewards.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Maslow proposed a five-tier hierarchy of psychological and physical needs.","C":"Incorrect because Herzberg argued money is a hygiene factor rather than a primary motivator.","D":"Incorrect because Elton Mayo emphasized social relations and teamwork rather than purely financial incentives."}}},{"id":"P1_U2_MCQ_005","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_005","question":"A boutique hotel empowers its front-desk receptionists to authorize complimentary room upgrades and resolve guest complaints independently without seeking manager approval. Which non-financial motivator is the hotel using?","options":{"A":"Job rotation","B":"Job enrichment","C":"Time-rate remuneration","D":"Autocratic supervision"},"correctOption":"B","correctAnswer":"Job enrichment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job enrichment adds higher-level responsibility, autonomy, and decision-making authority to a role.","distractor_reasons":{"A":"Incorrect because job rotation involves moving workers periodically between different tasks of similar skill level.","B":"Correct selection.","C":"Incorrect because time-rate remuneration is a financial payment method based on hours worked.","D":"Incorrect because autocratic supervision restricts worker autonomy rather than expanding it."}}},{"id":"P1_U2_MCQ_006","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_006","question":"A supermarket schedules its store assistants to spend two hours operating checkouts, two hours restocking shelves, and two hours preparing online grocery orders each shift. What is the main benefit of this job rotation?","options":{"A":"It guarantees higher basic hourly wages for store assistants","B":"It eliminates the need for any staff induction training","C":"It reduces task monotony and builds a multi-skilled workforce able to cover absences","D":"It gives assistants full managerial control over store budgets"},"correctOption":"C","correctAnswer":"It reduces task monotony and builds a multi-skilled workforce able to cover absences","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job rotation relieves boredom from repetitive tasks and cross-trains workers so they can cover colleagues during absences.","distractor_reasons":{"A":"Incorrect because switching between peer-level tasks does not automatically increase pay rates.","B":"Incorrect because rotating workers across different tasks actually requires broader training.","C":"Correct selection.","D":"Incorrect because budget control represents job enrichment or delegation, not job rotation."}}},{"id":"P1_U2_MCQ_007","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_007","question":"A warehouse technician is paid a basic time-rate wage of $12 per hour for a standard 40-hour week, plus an overtime rate of 1.5 times the basic rate for any additional hours worked. If the technician works 46 hours in one week, what is their total gross pay?","options":{"A":"$480","B":"$552","C":"$690","D":"$588"},"correctOption":"D","correctAnswer":"$588","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because standard pay = 40 hours × $12 = $480. Overtime hours = 6 hours × ($12 × 1.5 = $18) = $108. Total gross pay = $480 + $108 = $588.","distractor_reasons":{"A":"Incorrect because $480 is only the standard 40-hour pay, omitting the 6 overtime hours.","B":"Incorrect because $552 pays all 46 hours at the basic $12 rate ($46 × $12) without the 1.5x overtime premium.","C":"Incorrect because $690 applies the 1.5x overtime rate to all 46 hours ($46 × $18 = $828 or $46 × $15 = $690).","D":"Correct selection."}}},{"id":"P1_U2_MCQ_008","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_008","question":"An engineering firm operates an annual profit-sharing scheme that distributes 8% of net profits equally among all employees. What is a potential drawback of this financial motivator?","options":{"A":"Employees may feel demotivated if company profits fall due to an economic recession despite their hard work","B":"Employees will refuse to cooperate with colleagues in other departments","C":"The scheme forces the business to pay bonuses even when it makes a financial loss","D":"Individual high performers receive the exact same hourly basic wage as managers"},"correctOption":"A","correctAnswer":"Employees may feel demotivated if company profits fall due to an economic recession despite their hard work","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit-sharing payouts depend on overall firm profitability; if external market downturns reduce profits, workers receive little or no bonus despite high personal effort.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because company-wide profit sharing encourages inter-departmental cooperation rather than hindering it.","C":"Incorrect because profit-sharing payments are only made when net profits are generated.","D":"Incorrect because basic hourly wages or salaries remain separate from the profit-share pool."}}},{"id":"P1_U2_MCQ_009","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_009","question":"An automobile salesperson earns a fixed basic salary of $1,500 per month plus a 2% commission on the total value of vehicles sold. In October, the salesperson sells vehicles worth $45,000. What is their total gross income for October?","options":{"A":"$900","B":"$2,400","C":"$1,590","D":"$3,000"},"correctOption":"B","correctAnswer":"$2,400","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because commission = 2% of $45,000 = $900. Adding the basic salary of $1,500 gives a total gross income of $2,400.","distractor_reasons":{"A":"Incorrect because $900 is only the commission earned, omitting the $1,500 basic salary.","B":"Correct selection.","C":"Incorrect because $1,590 miscalculates 2% of $45,000 as $90 instead of $900.","D":"Incorrect calculation."}}},{"id":"P1_U2_MCQ_010","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_010","question":"An automotive assembly plant reorganizes its production line into small autonomous teams responsible for assembling complete engine modules and inspecting their own quality. How does this teamworking approach primarily motivate employees?","options":{"A":"By guaranteeing automatic annual promotions to senior executive roles","B":"By paying workers strictly on an individual piece-rate basis","C":"By fulfilling social needs for belonging and giving teams greater ownership over their work","D":"By eliminating all communication between workers and supervisors"},"correctOption":"C","correctAnswer":"By fulfilling social needs for belonging and giving teams greater ownership over their work","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because teamworking satisfies social belonging needs (Maslow) and enhances motivation through shared responsibility and autonomy.","distractor_reasons":{"A":"Incorrect because teamworking does not guarantee executive promotions.","B":"Incorrect because teamworking emphasizes collective group output rather than individual piece-rate pay.","C":"Correct selection.","D":"Incorrect because teamworking relies on active communication with supervisors and peers."}}},{"id":"P1_U2_MCQ_011","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_011","question":"On a regional department store's organizational chart, the General Manager directly supervises 14 department managers, each of whom oversees 10 sales associates. What is the General Manager's span of control?","options":{"A":"10 subordinates","B":"140 subordinates","C":"2 levels of hierarchy","D":"14 subordinates"},"correctOption":"D","correctAnswer":"14 subordinates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because span of control measures the number of subordinates reporting directly to a specific manager, which is 14 department managers.","distractor_reasons":{"A":"Incorrect because 10 is the span of control of each department manager, not the General Manager.","B":"Incorrect because 140 is the total number of indirect sales associates rather than direct reports.","C":"Incorrect because levels of hierarchy describe the chain of command rather than span of control.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_012","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_012","question":"In a manufacturing company, safety instructions are issued by the Operations Director, passed down to the Plant Manager, then to the Shift Supervisor, and finally to machine operators. What organizational concept does this route illustrate?","options":{"A":"Chain of command","B":"Span of control","C":"Informal grapevine","D":"Horizontal integration"},"correctOption":"A","correctAnswer":"Chain of command","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the chain of command is the formal line of authority through which orders and instructions are passed down from top management to lower levels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because span of control refers to the number of direct subordinates a single manager supervises.","C":"Incorrect because the informal grapevine involves unofficial peer-to-peer rumors rather than formal authority lines.","D":"Incorrect because horizontal integration refers to mergers between firms at the same production stage."}}},{"id":"P1_U2_MCQ_013","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_013","question":"A telecommunications company removes two layers of middle management, creating a flatter organizational structure. What is a likely operational result of this delayering?","options":{"A":"Managers will have narrower spans of control and fewer subordinates","B":"Communication between senior executives and frontline staff becomes faster and less distorted","C":"Annual management salary expenses will increase substantially","D":"Frontline employees will have fewer opportunities for delegation"},"correctOption":"B","correctAnswer":"Communication between senior executives and frontline staff becomes faster and less distorted","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because removing management layers shortens the chain of command, speeding up vertical communication and reducing message distortion.","distractor_reasons":{"A":"Incorrect because delayering widens spans of control as remaining managers oversee more direct reports.","B":"Correct selection.","C":"Incorrect because removing middle-management roles lowers overhead salary costs.","D":"Incorrect because wider spans of control encourage greater delegation to frontline staff."}}},{"id":"P1_U2_MCQ_014","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_014","question":"A Marketing Director gives a senior brand executive the authority to approve a $50,000 digital advertising campaign, while the Director retains final accountability for campaign performance. Which management practice is this?","options":{"A":"Abdication of responsibility","B":"Autocratic centralization","C":"Delegation","D":"Delayering"},"correctOption":"C","correctAnswer":"Delegation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegation involves passing authority to perform a task to a subordinate while the manager retains ultimate accountability.","distractor_reasons":{"A":"Incorrect because abdication occurs when a manager abandons responsibility entirely without oversight.","B":"Incorrect because centralization keeps all decision-making power at the top.","C":"Correct selection.","D":"Incorrect because delayering removes entire tiers of management from the hierarchy."}}},{"id":"P1_U2_MCQ_015","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_015","question":"During a sudden chemical spill at a factory, the Safety Manager issues immediate, non-negotiable evacuation orders without consulting shop-floor workers. Why is an autocratic leadership style appropriate in this situation?","options":{"A":"It encourages creative brainstorming among machine operators","B":"It maximizes long-term employee job enrichment","C":"It allows workers to vote democratically on the best evacuation route","D":"It enables rapid, decisive action in an emergency where lives are at risk"},"correctOption":"D","correctAnswer":"It enables rapid, decisive action in an emergency where lives are at risk","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because autocratic leadership allows fast unilateral decision-making when urgent crises require immediate compliance.","distractor_reasons":{"A":"Incorrect because autocratic leadership does not invite worker brainstorming.","B":"Incorrect because autocratic orders do not enrich employee roles.","C":"Incorrect because voting during an emergency wastes critical time (democratic style).","D":"Correct selection."}}},{"id":"P1_U2_MCQ_016","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_016","question":"A video game studio encourages designers, programmers, and artists to participate in open meetings and vote on new game features before production begins. What is a primary disadvantage of this democratic leadership style?","options":{"A":"Decision-making takes longer due to extensive consultation and discussion","B":"Employees feel alienated because their ideas are completely ignored","C":"Managers retain total centralized control over every minor creative choice","D":"Staff turnover rises because workers have zero input into their projects"},"correctOption":"A","correctAnswer":"Decision-making takes longer due to extensive consultation and discussion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because involving multiple employees in consultations slows down decision-making compared to autocratic leadership.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because democratic leadership actively values employee input.","C":"Incorrect because centralized unilateral control describes autocratic leadership.","D":"Incorrect because democratic participation typically improves morale and lowers turnover."}}},{"id":"P1_U2_MCQ_017","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_017","question":"A pharmaceutical research director sets broad annual drug-discovery objectives and leaves experienced PhD scientists free to organize their own laboratory experiments without interference. Which leadership style is being used?","options":{"A":"Autocratic leadership","B":"Laissez-faire leadership","C":"Paternalistic leadership","D":"Bureaucratic leadership"},"correctOption":"B","correctAnswer":"Laissez-faire leadership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because laissez-faire leadership delegates extensive freedom to skilled specialists to manage their own methods within broad objectives.","distractor_reasons":{"A":"Incorrect because autocratic leaders dictate exact instructions and closely control work.","B":"Correct selection.","C":"Incorrect because paternalistic leaders make decisions on behalf of staff in a parental manner.","D":"Incorrect because bureaucratic leaders enforce rigid procedural rules."}}},{"id":"P1_U2_MCQ_018","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_018","question":"At the end of each month, a Logistics Manager reviews delivery performance reports against target schedules and intervenes to fix bottlenecks on delayed routes. Which core management function is the manager performing?","options":{"A":"Planning future warehouse locations","B":"Organizing initial staff recruitment","C":"Controlling and monitoring performance against targets","D":"Commanding new hires during induction"},"correctOption":"C","correctAnswer":"Controlling and monitoring performance against targets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because controlling involves measuring actual output against established targets and taking corrective action when deviations occur.","distractor_reasons":{"A":"Incorrect because planning sets future goals and strategies rather than reviewing past results.","B":"Incorrect because organizing arranges resources and tasks before execution.","C":"Correct selection.","D":"Incorrect because commanding involves guiding and directing staff during operations."}}},{"id":"P1_U2_MCQ_019","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_019","question":"Workers at a steel manufacturing plant join an industry trade union to negotiate higher annual pay rises and improved heat-shield safety standards with management. What is the primary role of this trade union?","options":{"A":"To set retail steel prices for international export customers","B":"To appoint senior directors to the company's board","C":"To enforce government corporate tax collection","D":"To protect and improve the pay and working conditions of its members through collective bargaining"},"correctOption":"D","correctAnswer":"To protect and improve the pay and working conditions of its members through collective bargaining","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade unions represent employees collectively to negotiate better wages, benefits, and safe working conditions.","distractor_reasons":{"A":"Incorrect because product pricing is set by company management.","B":"Incorrect because shareholders appoint company directors.","C":"Incorrect because tax collection is performed by government revenue authorities.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_020","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_020","question":"A multinational insurance corporation operates with a tall organizational structure containing ten levels of hierarchy and narrow spans of control. What is a common disadvantage of this structure?","options":{"A":"Messages take a long time to travel up and down the chain of command and risk becoming distorted","B":"Managers are overwhelmed because each supervises hundreds of direct subordinates","C":"Employees have no clear line of authority or promotion pathway","D":"Senior executives are forced to handle every routine customer inquiry personally"},"correctOption":"A","correctAnswer":"Messages take a long time to travel up and down the chain of command and risk becoming distorted","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tall hierarchies create long chains of command, slowing communication and increasing the risk of message distortion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tall structures feature narrow spans of control with few direct subordinates per manager.","C":"Incorrect because tall structures provide clearly defined authority lines and many promotion steps.","D":"Incorrect because multiple management tiers delegate routine operational tasks downward."}}},{"id":"P1_U2_MCQ_021","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_021","question":"A luxury hotel chain promotes an experienced Assistant Front-Office Manager to become General Manager of one of its flagship properties. What is a major advantage of this internal recruitment decision?","options":{"A":"It brings completely new industry perspectives from competing hotel brands","B":"The candidate already understands company policies and the promotion motivates other staff","C":"It avoids creating any internal vacancy elsewhere in the hotel chain","D":"It gives the hotel access to a much wider external pool of applicants"},"correctOption":"B","correctAnswer":"The candidate already understands company policies and the promotion motivates other staff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because internal recruits are already familiar with company culture and procedures, require less induction, and show other staff that hard work leads to promotion.","distractor_reasons":{"A":"Incorrect because external recruitment brings outside ideas, whereas internal recruitment retains existing organizational practices.","B":"Correct selection.","C":"Incorrect because promoting an internal employee leaves their previous Assistant Manager role vacant.","D":"Incorrect because external recruitment provides a larger pool of applicants."}}},{"id":"P1_U2_MCQ_022","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_022","question":"A traditional brick-and-mortar clothing retailer recruits an experienced Digital Marketing Director from an outside e-commerce firm to launch its online store. Why did the retailer choose external recruitment?","options":{"A":"To eliminate all advertising and interview expenses","B":"To avoid spending any time inducting the new director into company routines","C":"To acquire specialist digital skills and fresh ideas not currently available within the existing workforce","D":"To guarantee that existing store managers feel motivated by internal promotion"},"correctOption":"C","correctAnswer":"To acquire specialist digital skills and fresh ideas not currently available within the existing workforce","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because external recruitment accesses specialized expertise and innovative ideas when existing staff lack those skills.","distractor_reasons":{"A":"Incorrect because external recruitment increases advertising and selection costs.","B":"Incorrect because external hires require thorough induction training.","C":"Correct selection.","D":"Incorrect because hiring externally can actually demotivate internal staff passed over for promotion."}}},{"id":"P1_U2_MCQ_023","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_023","question":"Before advertising a vacancy, an HR manager prepares a document detailing the job title, main daily duties, reporting relationships, and working hours for a Warehouse Coordinator. Which recruitment document is this?","options":{"A":"Person specification","B":"Curriculum vitae (CV)","C":"Contract of employment","D":"Job description"},"correctOption":"D","correctAnswer":"Job description","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a job description outlines the tasks, responsibilities, working conditions, and reporting lines of the role itself.","distractor_reasons":{"A":"Incorrect because a person specification lists the qualifications, skills, and personal qualities required of the applicant.","B":"Incorrect because a CV is submitted by a job applicant summarizing their own background.","C":"Incorrect because a contract of employment is a legally binding agreement signed after a candidate is hired.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_024","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_024","question":"An accounting firm drafts a document stating that applicants for a Senior Auditor position must hold a recognized CPA qualification, have at least four years of audit experience, and demonstrate strong analytical skills. Which document is this?","options":{"A":"Person specification","B":"Job description","C":"Induction checklist","D":"Disciplinary procedure"},"correctOption":"A","correctAnswer":"Person specification","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a person specification defines the essential and desirable qualifications, experience, and skills needed by the ideal candidate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a job description describes the duties and responsibilities of the job rather than candidate traits.","C":"Incorrect because an induction checklist is used to onboard new hires after selection.","D":"Incorrect because a disciplinary procedure governs workplace rule violations."}}},{"id":"P1_U2_MCQ_025","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_025","question":"A small neighborhood bakery needs to hire a part-time weekend counter assistant quickly and at minimal cost. Which advertising medium is most appropriate for this vacancy?","options":{"A":"A full-page advertisement in an international business magazine","B":"A notice displayed in the bakery's shop window and on a local community job board","C":"A prime-time national television commercial","D":"An executive headhunting agency specializing in corporate directors"},"correctOption":"B","correctAnswer":"A notice displayed in the bakery's shop window and on a local community job board","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local shop window notices and community boards reach nearby residents quickly and cheaply for low-skilled local retail roles.","distractor_reasons":{"A":"Incorrect because international business magazines are far too expensive and target executives rather than local part-time retail staff.","B":"Correct selection.","C":"Incorrect because national television advertising is prohibitively costly and reaches irrelevant audiences.","D":"Incorrect because headhunters are used for scarce senior executives, not entry-level bakery assistants."}}},{"id":"P1_U2_MCQ_026","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_026","question":"An HR officer receives 150 application forms for a Junior Graphic Designer vacancy and compares each applicant's portfolio and qualifications against the person specification to select 6 candidates for interview. What is this stage of recruitment called?","options":{"A":"Job analysis","B":"Induction training","C":"Shortlisting","D":"Redundancy consultation"},"correctOption":"C","correctAnswer":"Shortlisting","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because shortlisting narrows down a large pool of applicants to the most suitable candidates who meet the person specification for interview.","distractor_reasons":{"A":"Incorrect because job analysis occurs at the start of recruitment before writing the job description.","B":"Incorrect because induction training occurs after a candidate is hired.","C":"Correct selection.","D":"Incorrect because redundancy consultation occurs when terminating surplus roles."}}},{"id":"P1_U2_MCQ_027","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_027","question":"During the selection process for trainee air traffic controllers, an aviation authority requires shortlisted applicants to complete timed spatial-reasoning and stress-response simulations alongside face-to-face interviews. Why are these tests used?","options":{"A":"To replace the legal need for a written contract of employment","B":"To avoid checking candidate references from previous employers","C":"To reduce the starting salary offered to successful trainees","D":"To objectively measure candidates' specific cognitive abilities and suitability under realistic job pressures"},"correctOption":"D","correctAnswer":"To objectively measure candidates' specific cognitive abilities and suitability under realistic job pressures","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because aptitude and psychometric tests provide objective evidence of job-specific skills and temperament that interviews alone might miss.","distractor_reasons":{"A":"Incorrect because selection tests do not replace employment contracts.","B":"Incorrect because employers still verify references alongside testing.","C":"Incorrect because selection tests assess suitability rather than lower pay.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_028","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_028","question":"A busy coffee shop chain employs several part-time baristas working 16 hours per week during peak morning commuter periods. What is a key benefit of employing part-time staff for the business?","options":{"A":"Greater scheduling flexibility to match staffing levels with peak customer demand","B":"Lower staff turnover because part-time workers never seek other jobs","C":"Significantly lower training costs per hour worked compared to full-time staff","D":"Easier communication because all staff work the exact same full-day shift"},"correctOption":"A","correctAnswer":"Greater scheduling flexibility to match staffing levels with peak customer demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because part-time workers allow businesses to adjust labor hours flexibly around busy periods without paying idle full-time wages during quiet hours.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because part-time staff often have higher turnover rates than full-time staff.","C":"Incorrect because training costs per worker are similar regardless of hours worked, making cost per hour higher.","D":"Incorrect because staggered part-time shifts can make team communication harder."}}},{"id":"P1_U2_MCQ_029","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_029","question":"A corporate law firm prefers hiring full-time paralegals rather than part-time staff. What is a primary advantage of employing full-time workers?","options":{"A":"The firm is legally exempt from paying overtime or holiday benefits","B":"Employees generally show stronger commitment to the firm and provide a higher return on training investment","C":"The firm can cut staff hours instantly on quiet days without notice","D":"Full-time employees never require career progression or salary reviews"},"correctOption":"B","correctAnswer":"Employees generally show stronger commitment to the firm and provide a higher return on training investment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because full-time employees work more hours, build deeper client familiarity, and allow the firm to recover training costs over full working weeks.","distractor_reasons":{"A":"Incorrect because full-time staff are entitled to statutory benefits and overtime terms.","B":"Correct selection.","C":"Incorrect because full-time contracts guarantee fixed weekly hours.","D":"Incorrect because full-time staff expect regular appraisals and progression."}}},{"id":"P1_U2_MCQ_030","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_030","question":"A regional courier company fills all supervisory vacancies exclusively through internal promotion. What is a key limitation of relying solely on internal recruitment?","options":{"A":"Promoted employees take many months to learn basic company software","B":"Internal candidates always demand higher salaries than external recruits","C":"No fresh ideas or external industry best practices are brought into the organization","D":"The company must pay high fees to external recruitment agencies"},"correctOption":"C","correctAnswer":"No fresh ideas or external industry best practices are brought into the organization","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because relying purely on internal recruitment restricts the inflow of new perspectives, external expertise, and innovative practices.","distractor_reasons":{"A":"Incorrect because internal recruits already know company software.","B":"Incorrect because external recruits often command higher market salaries to attract them away from rivals.","C":"Correct selection.","D":"Incorrect because internal recruitment avoids external agency fees."}}},{"id":"P1_U2_MCQ_031","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_031","question":"On their first morning at a commercial bank, newly hired customer advisors attend a session covering fire evacuation routes, data privacy rules, IT login procedures, and introductions to branch colleagues. Which type of training is this?","options":{"A":"Off-the-job university degree sponsorship","B":"Remedial disciplinary coaching","C":"External executive leadership retreat","D":"Induction training"},"correctOption":"D","correctAnswer":"Induction training","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because induction training familiarizes new employees with workplace rules, safety procedures, facilities, and colleagues when starting a job.","distractor_reasons":{"A":"Incorrect because degree sponsorship is long-term off-the-job academic education.","B":"Incorrect because disciplinary coaching addresses performance or conduct failures.","C":"Incorrect because executive retreats are off-the-job strategic workshops for senior leaders.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_032","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_032","question":"A busy restaurant trains a newly hired junior chef by having them shadow and assist the Head Chef at the cooking station during regular service hours. What is a primary advantage of this on-the-job training?","options":{"A":"It is relatively inexpensive and tailored directly to the restaurant's exact menu and equipment","B":"The junior chef learns advanced culinary theory away from kitchen distractions","C":"The Head Chef's own cooking speed increases while supervising the trainee","D":"Customer food orders are never slowed down or affected by trainee mistakes"},"correctOption":"A","correctAnswer":"It is relatively inexpensive and tailored directly to the restaurant's exact menu and equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because on-the-job training avoids external course fees and teaches practical skills directly relevant to the firm's actual workplace.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because learning away from workplace distractions describes off-the-job training.","C":"Incorrect because supervising a trainee temporarily slows down the experienced trainer's own output.","D":"Incorrect because trainee mistakes during live service can affect customer orders."}}},{"id":"P1_U2_MCQ_033","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_033","question":"An aerospace engineering company sends ten technicians to a specialist technical college for three weeks to learn newly developed composite-material testing methods. What is a major disadvantage of this off-the-job training?","options":{"A":"Technicians cannot learn modern skills that do not yet exist inside the factory","B":"Course tuition fees are expensive and the company loses the technicians' output while they are away","C":"Technicians are constantly interrupted by routine factory assembly tasks during lessons","D":"The training relies on bad habits picked up from existing factory coworkers"},"correctOption":"B","correctAnswer":"Course tuition fees are expensive and the company loses the technicians' output while they are away","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because off-the-job training incurs external provider fees, travel/accommodation expenses, and lost workplace productivity during training hours.","distractor_reasons":{"A":"Incorrect because introducing new external expertise is actually a key advantage of off-the-job training.","B":"Correct selection.","C":"Incorrect because off-the-job training takes place away from workplace interruptions.","D":"Incorrect because picking up bad habits from coworkers is a drawback of on-the-job training."}}},{"id":"P1_U2_MCQ_034","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_034","question":"Due to a permanent decline in demand for printed newspapers, a publishing house closes two regional printing plants and terminates the employment of 85 press operators whose jobs no longer exist. What is this workforce reduction called?","options":{"A":"Summary dismissal for misconduct","B":"Natural wastage","C":"Redundancy (retrenchment)","D":"Job rotation"},"correctOption":"C","correctAnswer":"Redundancy (retrenchment)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because redundancy occurs when a business no longer needs a particular job role to be performed due to falling demand, closure, or automation.","distractor_reasons":{"A":"Incorrect because dismissal occurs when a worker is fired for unsatisfactory behavior or incompetence, whereas here the job role itself ceased to exist.","B":"Incorrect because natural wastage reduces staff numbers gradually by not replacing workers who resign or retire.","C":"Correct selection.","D":"Incorrect because job rotation moves existing employees between different tasks."}}},{"id":"P1_U2_MCQ_035","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_035","question":"A supermarket terminates a store supervisor's employment contract after security footage proves the supervisor repeatedly stole merchandise from the stockroom. How is this termination classified?","options":{"A":"Voluntary redundancy","B":"Early retirement","C":"Structural downsizing","D":"Dismissal"},"correctOption":"D","correctAnswer":"Dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dismissal occurs when an employee's contract is ended due to their own gross misconduct (theft) or unsatisfactory performance, while the job role remains needed.","distractor_reasons":{"A":"Incorrect because redundancy happens when the job role disappears, not when an employee commits theft.","B":"Incorrect because early retirement is an age-related exit, not disciplinary termination.","C":"Incorrect because downsizing shrinks overall workforce size due to lower demand.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_036","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_036","question":"An insurance company needs to reduce its administrative headcount by 12% over two years without harming staff morale or paying redundancy compensation. It decides not to recruit replacements whenever employees retire or resign voluntarily. Which workforce reduction method is this?","options":{"A":"Natural wastage","B":"Compulsory redundancy","C":"Unfair dismissal","D":"External recruitment"},"correctOption":"A","correctAnswer":"Natural wastage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because natural wastage gradually lowers headcount by leaving vacancies unfilled when employees leave voluntarily or retire.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because compulsory redundancy forces employees out and requires severance pay.","C":"Incorrect because unfair dismissal is an illegal termination of employment.","D":"Incorrect because external recruitment adds new workers rather than reducing headcount."}}},{"id":"P1_U2_MCQ_037","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_037","question":"A logistics firm fires a delivery driver immediately without prior warnings or investigation simply because the driver joined a legally recognized trade union. Which legal protection has the employer breached?","options":{"A":"Minimum wage legislation","B":"Protection against unfair dismissal","C":"Consumer product labeling laws","D":"Environmental emissions standards"},"correctOption":"B","correctAnswer":"Protection against unfair dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because employment laws protect workers from unfair dismissal, including being fired for lawful trade union membership.","distractor_reasons":{"A":"Incorrect because minimum wage laws regulate hourly pay floors rather than union membership dismissal.","B":"Correct selection.","C":"Incorrect because product labeling laws protect consumers rather than employees.","D":"Incorrect because emissions standards regulate environmental pollution."}}},{"id":"P1_U2_MCQ_038","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_038","question":"A hotel resort employs an average workforce of 200 staff during the year. Over the 12-month period, 30 employees resign and leave the resort. What is the hotel's annual labor turnover rate?","options":{"A":"30%","B":"6.7%","C":"15%","D":"85%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labor turnover rate = (number of staff leaving / average number of staff employed) × 100 = (30 / 200) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 30 is the raw headcount of leavers, not the percentage rate.","B":"Incorrect because 6.7% divides 200 by 30 (200 / 30 = 6.67).","C":"Correct selection.","D":"Incorrect because 85% represents the staff retention rate (100% - 15%)."}}},{"id":"P1_U2_MCQ_039","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_039","question":"Government inspectors fine a construction contractor for failing to provide safety harnesses for roofers and leaving high-voltage electrical cables exposed on site. Which area of employment law is being enforced?","options":{"A":"Equal opportunity and anti-discrimination law","B":"Statutory minimum wage regulations","C":"Patent and trademark protection law","D":"Health and safety at work legislation"},"correctOption":"D","correctAnswer":"Health and safety at work legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health and safety laws require employers to provide protective equipment, maintain safe machinery/sites, and protect workers from physical hazards.","distractor_reasons":{"A":"Incorrect because anti-discrimination laws prohibit bias based on gender, race, age, or religion.","B":"Incorrect because minimum wage laws govern pay rates rather than physical site safety.","C":"Incorrect because intellectual property laws protect inventions and brands.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_040","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_040","question":"The government raises the statutory national minimum wage by 15%, forcing a fast-food restaurant chain to increase hourly pay for all entry-level crew members. How is this legal change most likely to affect the business?","options":{"A":"Labor costs will rise, which may reduce profit margins unless offset by higher productivity or menu prices","B":"The chain will be legally permitted to eliminate paid annual leave for crew members","C":"Staff turnover will increase sharply because workers are paid more per hour","D":"The business will automatically receive a government subsidy covering 100% of wages"},"correctOption":"A","correctAnswer":"Labor costs will rise, which may reduce profit margins unless offset by higher productivity or menu prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a higher statutory minimum wage increases payroll expenses, squeezing margins unless the firm improves efficiency or raises prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws do not remove statutory holiday entitlements.","C":"Incorrect because higher wages generally improve morale and reduce staff turnover.","D":"Incorrect because businesses must fund statutory minimum wage increases themselves."}}},{"id":"P1_U2_MCQ_041","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_041","question":"A Production Supervisor sends an urgent message to the factory's Maintenance Team requesting immediate repair of a jammed packaging machine. Which category of communication is this?","options":{"A":"External communication","B":"Internal communication","C":"Public relations advertising","D":"Informal grapevine rumor"},"correctOption":"B","correctAnswer":"Internal communication","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because internal communication takes place between individuals or departments within the same organization.","distractor_reasons":{"A":"Incorrect because external communication occurs between the business and outside parties such as customers or suppliers.","B":"Correct selection.","C":"Incorrect because public relations targets external audiences and media.","D":"Incorrect because a formal maintenance request is an official operational message, not a rumor."}}},{"id":"P1_U2_MCQ_042","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_042","question":"An airline sends automated SMS text alerts and emails to passengers notifying them of a two-hour flight departure delay. Why is effective external communication critical in this scenario?","options":{"A":"It reduces the airline's corporate income tax rate","B":"It eliminates the need for airport ground staff","C":"It keeps customers informed, reduces frustration, and protects the airline's brand reputation","D":"It allows cabin crew to bypass aviation safety inspections"},"correctOption":"C","correctAnswer":"It keeps customers informed, reduces frustration, and protects the airline's brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because timely, accurate external communication with customers builds trust, manages expectations, and safeguards brand reputation.","distractor_reasons":{"A":"Incorrect because customer alerts have no impact on tax rates.","B":"Incorrect because ground staff are still required to manage boarding and assistance.","C":"Correct selection.","D":"Incorrect because safety inspections are mandatory regardless of passenger notifications."}}},{"id":"P1_U2_MCQ_043","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_043","question":"A manufacturing firm distributes a printed and digital Employee Handbook detailing formal grievance procedures, safety rules, and holiday entitlement rules to every worker. What is a primary advantage of written communication here?","options":{"A":"It guarantees immediate two-way facial feedback from every reader","B":"It is the fastest method for resolving an urgent factory fire emergency","C":"It completely prevents employees from misreading complex legal terms","D":"It provides a permanent, consistent written record that employees can refer back to at any time"},"correctOption":"D","correctAnswer":"It provides a permanent, consistent written record that employees can refer back to at any time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because written communication creates a permanent, verifiable reference document ensuring consistent policy details across all staff.","distractor_reasons":{"A":"Incorrect because written handbooks are one-way and lack immediate verbal/visual feedback.","B":"Incorrect because alarms and verbal instructions are faster in emergencies.","C":"Incorrect because readers can still misunderstand complex written language without clarification.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_044","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_044","question":"A Factory Manager holds a 15-minute face-to-face team briefing to explain a sudden change in daily shift handover routines. What is a major advantage of this verbal communication method?","options":{"A":"Workers can ask immediate questions and the manager can check understanding through body language","B":"It automatically generates a signed legal transcript for absent employees","C":"It eliminates the risk of workers forgetting verbal details weeks later","D":"It requires zero preparation or time away from production machines"},"correctOption":"A","correctAnswer":"Workers can ask immediate questions and the manager can check understanding through body language","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because face-to-face verbal communication allows instant two-way feedback, clarification of doubts, and observation of non-verbal cues.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because spoken briefings leave no automatic written record for absent staff.","C":"Incorrect because spoken instructions can be forgotten unless backed up in writing.","D":"Incorrect because team briefings require pausing work briefly to gather staff."}}},{"id":"P1_U2_MCQ_045","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_045","question":"A flat-pack furniture retailer includes step-by-step illustrated assembly diagrams without text inside every wardrobe box sold globally. What is a primary benefit of this visual communication method?","options":{"A":"It allows customers to negotiate lower retail prices with store managers","B":"It simplifies complex assembly sequences and overcomes language barriers across international markets","C":"It provides detailed written legal warranty terms in multiple languages","D":"It enables instant two-way video chat with factory engineers"},"correctOption":"B","correctAnswer":"It simplifies complex assembly sequences and overcomes language barriers across international markets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visual diagrams make technical assembly instructions easier to follow and eliminate translation errors across different languages.","distractor_reasons":{"A":"Incorrect because assembly diagrams do not affect product pricing.","B":"Correct selection.","C":"Incorrect because wordless diagrams do not convey written legal warranty clauses.","D":"Incorrect because printed diagrams are static visual aids, not live video tools."}}},{"id":"P1_U2_MCQ_046","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_046","question":"Senior managers at a consulting firm announce sensitive department redundancies solely via a brief mass email. What is a significant drawback of using electronic email for this message?","options":{"A":"Emails take several weeks to reach recipients in different offices","B":"Emails cannot be saved or archived on company servers","C":"The message lacks empathy and non-verbal tone, increasing anxiety and potential misinterpretation","D":"Sending a mass email costs more than printing and mailing individual letters"},"correctOption":"C","correctAnswer":"The message lacks empathy and non-verbal tone, increasing anxiety and potential misinterpretation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because electronic text messages lack personal empathy, facial expressions, and tone of voice, making them poorly suited for sensitive news.","distractor_reasons":{"A":"Incorrect because emails transmit almost instantaneously.","B":"Incorrect because emails automatically create digital records.","C":"Correct selection.","D":"Incorrect because email is far cheaper than physical printing and postage."}}},{"id":"P1_U2_MCQ_047","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_047","question":"During lunch breaks in the staff canteen, assembly workers share unverified rumors that the factory will cancel annual holiday bonuses. Which communication channel does this represent?","options":{"A":"Formal downward communication","B":"Official external press release","C":"Formal upward feedback","D":"Informal communication (the grapevine)"},"correctOption":"D","correctAnswer":"Informal communication (the grapevine)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because informal communication ('the grapevine') occurs through casual social interactions outside official organizational channels and often spreads unverified rumors.","distractor_reasons":{"A":"Incorrect because formal downward communication consists of official management instructions.","B":"Incorrect because press releases are official external statements to media.","C":"Incorrect because formal upward feedback involves structured employee reports to managers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_048","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_048","question":"An IT Systems Engineer sends a report packed with complex server acronyms and coding jargon to the Sales Team, leaving sales staff confused about when the CRM software will be back online. Which barrier to communication caused this failure?","options":{"A":"Use of technical jargon inappropriate for the receiver","B":"Physical distance across different time zones","C":"Failure of high-speed fiber internet cables","D":"Excessive use of simple visual charts"},"correctOption":"A","correctAnswer":"Use of technical jargon inappropriate for the receiver","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because using specialized technical jargon that the target audience does not understand prevents accurate decoding of the message.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the confusion stemmed from complex terminology rather than time zones.","C":"Incorrect because the report was delivered, but its wording was unclear.","D":"Incorrect because visual charts aid clarity rather than cause jargon confusion."}}},{"id":"P1_U2_MCQ_049","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_049","question":"In a large corporation with eight levels of management hierarchy, a verbal instruction from the Chief Executive passes through six intermediate managers before reaching retail store staff, arriving with altered details. What caused this communication barrier?","options":{"A":"Lack of internet access in the Chief Executive's office","B":"A long chain of command with too many intermediaries distorting the message","C":"Over-reliance on direct two-way video conferencing with store staff","D":"Use of a flat organizational structure with wide spans of control"},"correctOption":"B","correctAnswer":"A long chain of command with too many intermediaries distorting the message","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because passing messages through many hierarchical layers increases the likelihood of omission, filtering, and distortion.","distractor_reasons":{"A":"Incorrect because the issue resulted from multiple human intermediaries rather than internet hardware.","B":"Correct selection.","C":"Incorrect because direct video conferencing bypasses intermediaries and reduces distortion.","D":"Incorrect because eight management levels represent a tall structure, not a flat one."}}},{"id":"P1_U2_MCQ_050","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_050","question":"A multinational logistics hub employs warehouse workers speaking four different native languages. To prevent safety misunderstandings, management translates all hazard posters into all four languages and adds clear international warning symbols. Which barrier to communication does this overcome?","options":{"A":"High cost of external television advertising","B":"Lack of formal trade union representation","C":"Language and cultural differences between sender and receiver","D":"Excessive delegation of financial budgets"},"correctOption":"C","correctAnswer":"Language and cultural differences between sender and receiver","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because translating safety instructions and using universal visual symbols ensures workers of different linguistic backgrounds accurately understand safety messages.","distractor_reasons":{"A":"Incorrect because internal warehouse safety posters are unrelated to external TV advertising.","B":"Incorrect because translating posters addresses linguistic comprehension rather than union representation.","C":"Correct selection.","D":"Incorrect because budget delegation is unrelated to multilingual safety signage."}}},{"id":"P1_U2_MCQ_051","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_051","question":"A semiconductor plant pays its assembly technicians a fixed monthly salary plus a lump-sum payment at the end of each quarter if defect-free output exceeds 98%. Which financial motivator is the plant using?","options":{"A":"Performance-related bonus","B":"Piece-rate wage","C":"Sales commission","D":"Statutory minimum wage"},"correctOption":"A","correctAnswer":"Performance-related bonus","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bonus is an additional lump-sum payment awarded on top of basic pay when specific output or quality targets are achieved.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because piece-rate wages pay a fixed rate per individual unit produced with no fixed monthly salary.","C":"Incorrect because commission is paid to sales staff as a percentage of sales revenue generated.","D":"Incorrect because the statutory minimum wage is the legal hourly pay floor set by government, not a performance reward."}}},{"id":"P1_U2_MCQ_052","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_052","question":"A retail bank introduces an 'Advisor of the Quarter' trophy, displays winners' photos in the branch lobby, and awards them senior job titles. According to Maslow's hierarchy of needs, which level of need is being targeted?","options":{"A":"Physiological needs","B":"Esteem needs","C":"Safety and security needs","D":"Social needs"},"correctOption":"B","correctAnswer":"Esteem needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public recognition, status symbols, trophies, and prestigious job titles fulfill esteem needs for respect and achievement.","distractor_reasons":{"A":"Incorrect because physiological needs cover basic survival requirements such as food, shelter, and basic wages.","B":"Correct selection.","C":"Incorrect because safety needs relate to job security and safe working environments.","D":"Incorrect because social needs involve friendship, teamwork, and belonging within a group."}}},{"id":"P1_U2_MCQ_053","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_053","question":"A cybersecurity firm assigns its senior analysts challenging client investigations, recognizes their breakthroughs publicly, and offers clear promotion pathways. According to Herzberg's two-factor theory, how are these factors classified?","options":{"A":"Hygiene factors that only prevent dissatisfaction","B":"Scientific management piece-rate incentives","C":"Motivators that actively create job satisfaction and higher effort","D":"External macroeconomic push factors"},"correctOption":"C","correctAnswer":"Motivators that actively create job satisfaction and higher effort","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg identifies challenging work, recognition, responsibility, and advancement opportunities as true motivators that inspire higher performance.","distractor_reasons":{"A":"Incorrect because hygiene factors include company policies, supervision, working conditions, and basic pay rather than achievement and promotion.","B":"Incorrect because F.W. Taylor proposed financial piece-rate incentives, not Herzberg.","C":"Correct selection.","D":"Incorrect because internal job design elements are organizational motivators, not macroeconomic forces."}}},{"id":"P1_U2_MCQ_054","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_054","question":"To attract and retain experienced regional managers, a pharmaceutical distributor offers private medical insurance, a company car, and subsidized gym memberships alongside their salaries. What are these non-cash rewards called?","options":{"A":"Piece-rate supplements","B":"Overtime premiums","C":"Profit-sharing dividends","D":"Fringe benefits (perks)"},"correctOption":"D","correctAnswer":"Fringe benefits (perks)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fringe benefits are non-wage perks such as health insurance, company vehicles, or staff discounts provided in addition to basic pay.","distractor_reasons":{"A":"Incorrect because piece-rate payments are cash wages paid per unit produced.","B":"Incorrect because overtime premiums are extra hourly wages paid for working beyond standard contracted hours.","C":"Incorrect because profit-sharing distributes a cash share of company profits.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_055","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_055","question":"After switching its furniture carpenters from hourly wages to a piece-rate pay system, a workshop notices a sharp rise in customer complaints about uneven varnish and loose joints. What is the most likely cause of this problem?","options":{"A":"Workers rush production to maximize output volume at the expense of product quality","B":"Piece-rate pay eliminates any financial incentive to work quickly","C":"Carpenters are paid the same amount regardless of how many items they make","D":"Piece-rate pay forces carpenters to spend too much time inspecting finished furniture"},"correctOption":"A","correctAnswer":"Workers rush production to maximize output volume at the expense of product quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because piece-rate systems reward speed and quantity, which often tempts workers to cut corners and neglect quality control unless strict inspections exist.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because piece-rate pay creates a strong financial incentive to work as fast as possible.","C":"Incorrect because earnings under piece-rate vary directly with output volume.","D":"Incorrect because workers avoid uncompensated inspection time when paid strictly per unit made."}}},{"id":"P1_U2_MCQ_056","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_056","question":"A luxury Swiss watchmaker pays its master watchmakers a high hourly time-rate wage rather than a piece-rate payment. Why is time-rate pay more suitable for this business?","options":{"A":"Individual watch output is easy to maximize through rapid assembly-line speed","B":"Precision craftsmanship and meticulous quality are far more important than speed of output","C":"Time-rate pay guarantees that labor costs per watch fall automatically when workers work slowly","D":"Master watchmakers do not require any supervision or quality standards"},"correctOption":"B","correctAnswer":"Precision craftsmanship and meticulous quality are far more important than speed of output","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because time-rate wages remove pressure to rush, making them ideal where high quality, precision, or unquantifiable care is essential.","distractor_reasons":{"A":"Incorrect because luxury watchmaking relies on delicate craftsmanship rather than high-speed mass production.","B":"Correct selection.","C":"Incorrect because slower work under time-rate pay actually increases labor cost per unit.","D":"Incorrect because time-rate workers still require supervision to ensure steady productivity."}}},{"id":"P1_U2_MCQ_057","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_057","question":"A national supermarket chain pays all its branch managers a fixed annual salary divided into twelve monthly payments rather than an hourly wage. What is a major advantage of salaries for the employer?","options":{"A":"Managers must be paid 1.5 times extra whenever they stay late to handle store deliveries","B":"Salary costs automatically drop to zero during quiet trading weeks","C":"Monthly payroll expenses are predictable and managers are expected to complete duties even if extra hours are needed","D":"Salaried managers have no formal job descriptions or accountability"},"correctOption":"C","correctAnswer":"Monthly payroll expenses are predictable and managers are expected to complete duties even if extra hours are needed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because salaries provide stable, predictable monthly wage bills for budgeting and typically do not include separate overtime pay for occasional extra hours.","distractor_reasons":{"A":"Incorrect because salaried professionals rarely receive hourly overtime premiums.","B":"Incorrect because fixed salaries must be paid regardless of weekly sales fluctuations.","C":"Correct selection.","D":"Incorrect because salaried managers operate under clear job descriptions and performance targets."}}},{"id":"P1_U2_MCQ_058","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_058","question":"A kitchen cabinet maker pays assemblers $4.00 per completed cabinet for the first 30 cabinets in a week, and $5.50 for each additional cabinet above 30. If an assembler completes 38 cabinets in one week, what is their gross weekly wage?","options":{"A":"$152.00","B":"$209.00","C":"$132.00","D":"$164.00"},"correctOption":"D","correctAnswer":"$164.00","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the first 30 cabinets earn 30 × $4.00 = $120.00, and the extra 8 cabinets earn 8 × $5.50 = $44.00, giving a total gross wage of $164.00.","distractor_reasons":{"A":"Incorrect because $152.00 multiplies all 38 cabinets by $4.00 without applying the $5.50 bonus tier.","B":"Incorrect because $209.00 multiplies all 38 cabinets by $5.50.","C":"Incorrect because $132.00 miscalculates the additional 8 cabinets as 8 × $1.50 = $12.00 instead of $44.00.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_059","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_059","question":"An e-commerce warehouse expands a packer's role by adding barcode scanning and box labeling—tasks of the same skill level—without giving them any supervisory authority. Which non-financial method is being applied?","options":{"A":"Job enlargement","B":"Job enrichment","C":"Delegation of management authority","D":"Laissez-faire empowerment"},"correctOption":"A","correctAnswer":"Job enlargement","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enlargement adds more tasks of a similar skill and responsibility level ('horizontal loading') to reduce repetition.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because job enrichment adds higher-level decision-making and supervisory responsibility ('vertical loading').","C":"Incorrect because no managerial authority was transferred to the packer.","D":"Incorrect because laissez-faire leadership applies to self-directed specialists rather than adding routine packing tasks."}}},{"id":"P1_U2_MCQ_060","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_060","question":"A software startup notices that remote junior developers feel isolated, leading to declining morale. Management introduces weekly collaborative coding sprints and monthly team social lunches. Which level of Maslow's hierarchy does this primarily address?","options":{"A":"Physiological needs","B":"Social needs","C":"Safety and security needs","D":"Self-actualization needs"},"correctOption":"B","correctAnswer":"Social needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collaborative teamwork and social gatherings satisfy employees' social needs for friendship, interaction, and belonging.","distractor_reasons":{"A":"Incorrect because physiological needs concern basic survival necessities like wages for food and housing.","B":"Correct selection.","C":"Incorrect because safety needs involve job security and physical protection.","D":"Incorrect because self-actualization involves realizing one's highest creative potential."}}},{"id":"P1_U2_MCQ_061","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_061","question":"A newly appointed Operations Trainee studies the company's formal organizational chart on their first day. Which information can the trainee directly identify from this chart?","options":{"A":"The exact annual salary and bonus package of each department head","B":"Which employees socialize together via the informal grapevine","C":"Formal lines of authority, reporting relationships, and departmental divisions","D":"The personal leadership style used by each supervisor"},"correctOption":"C","correctAnswer":"Formal lines of authority, reporting relationships, and departmental divisions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an organizational chart visually maps formal hierarchy levels, spans of control, chains of command, and functional departments.","distractor_reasons":{"A":"Incorrect because confidential salary figures are not displayed on organizational charts.","B":"Incorrect because organizational charts show formal authority lines rather than informal social networks.","C":"Correct selection.","D":"Incorrect because leadership style cannot be read from structural boxes and lines."}}},{"id":"P1_U2_MCQ_062","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_062","question":"In a bottled-water plant, a single Shift Supervisor effectively manages a wide span of control of 28 line operators. Which factor best explains why such a wide span of control works well here?","options":{"A":"Every operator performs highly complex, customized scientific research","B":"The supervisor must approve every single bottle cap individually","C":"The operators are newly hired trainees with zero prior instruction","D":"The production tasks are standardized, repetitive, and well understood by experienced operators"},"correctOption":"D","correctAnswer":"The production tasks are standardized, repetitive, and well understood by experienced operators","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because wide spans of control are effective when tasks are routine, standardized, and workers require minimal close supervision.","distractor_reasons":{"A":"Incorrect because complex, non-routine tasks require closer guidance and narrower spans of control.","B":"Incorrect because micromanaging every unit would make supervising 28 workers impossible.","C":"Incorrect because untrained new hires need narrow spans of control and close coaching.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_063","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_063","question":"Every November, the senior leadership team of a retail chain sets revenue targets for the coming year, forecasts staffing requirements, and allocates departmental budgets. Which core management function is being carried out?","options":{"A":"Planning","B":"Controlling","C":"Commanding","D":"Recruiting"},"correctOption":"A","correctAnswer":"Planning","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because planning involves looking ahead, setting future organizational objectives, and determining the resources needed to achieve them.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because controlling evaluates actual past/current performance against set targets.","C":"Incorrect because commanding involves instructing and guiding employees during daily operations.","D":"Incorrect because recruiting is the HR process of hiring candidates, not strategic goal-setting."}}},{"id":"P1_U2_MCQ_064","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_064","question":"Before launching a new smartphone model, a Project Manager aligns the schedules of the R&D engineers, component buyers, factory assembly lines, and advertising agency so every stage finishes on time. Which management function does this represent?","options":{"A":"Disciplinary controlling","B":"Coordinating","C":"Redundancy selection","D":"Collective bargaining"},"correctOption":"B","correctAnswer":"Coordinating","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because coordinating brings together different departments and activities so they work harmoniously toward a shared launch deadline.","distractor_reasons":{"A":"Incorrect because controlling measures performance deviations rather than synchronizing cross-functional teams.","B":"Correct selection.","C":"Incorrect because redundancy selection deals with downsizing surplus jobs.","D":"Incorrect because collective bargaining refers to union-management pay negotiations."}}},{"id":"P1_U2_MCQ_065","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_065","question":"A busy Finance Director delegates routine monthly expense-claim approvals to an Assistant Accountant. How does this delegation directly benefit the Finance Director?","options":{"A":"It transfers all legal accountability for financial fraud away from the Finance Director","B":"It eliminates the need to supervise or review the Assistant Accountant's work","C":"It frees up the Director's time to focus on long-term strategic investment decisions","D":"It automatically reduces the Assistant Accountant's monthly salary"},"correctOption":"C","correctAnswer":"It frees up the Director's time to focus on long-term strategic investment decisions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegating routine operational decisions relieves senior managers' workloads so they can concentrate on high-level strategy.","distractor_reasons":{"A":"Incorrect because a manager retains ultimate accountability even after delegating authority.","B":"Incorrect because effective delegation still requires periodic monitoring and support.","C":"Correct selection.","D":"Incorrect because delegation increases subordinate responsibility rather than lowering pay."}}},{"id":"P1_U2_MCQ_066","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_066","question":"Despite working 65 hours a week, an Engineering Manager refuses to delegate any project scheduling tasks to qualified team leads. Which reason commonly explains a manager's reluctance to delegate?","options":{"A":"Delegation is prohibited under national employment contracts","B":"Team leads already have wider spans of control than the Chief Executive","C":"Delegating routine tasks always increases company fixed overhead costs","D":"The manager fears subordinates might make costly mistakes for which the manager remains accountable"},"correctOption":"D","correctAnswer":"The manager fears subordinates might make costly mistakes for which the manager remains accountable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because managers often hesitate to delegate due to lack of trust in subordinates' skills or fear of being blamed if mistakes occur.","distractor_reasons":{"A":"Incorrect because delegation is a standard, lawful management practice.","B":"Incorrect because team leads typically have narrower spans than senior executives.","C":"Incorrect because delegation redistributes existing workload without raising fixed overheads.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_067","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_067","question":"A newly opened retail store hires twenty inexperienced school-leavers, and the Store Manager adopts a laissez-faire leadership style with minimal instructions or oversight. What is the most likely outcome?","options":{"A":"Confusion, inconsistent customer service, and poor coordination due to lack of clear direction","B":"Immediate record-breaking store profitability driven by self-directed expertise","C":"Strict, uniform compliance with complex visual merchandising rules","D":"Faster centralized decision-making during busy weekend rushes"},"correctOption":"A","correctAnswer":"Confusion, inconsistent customer service, and poor coordination due to lack of clear direction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because laissez-faire leadership fails when inexperienced staff need clear structure, training, and active guidance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inexperienced trainees lack the expertise to self-manage effectively.","C":"Incorrect because laissez-faire managers do not enforce strict uniform rules.","D":"Incorrect because laissez-faire leadership avoids centralized control."}}},{"id":"P1_U2_MCQ_068","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_068","question":"A new Head of Design at an architecture firm makes every creative decision alone, rejects all suggestions from senior architects, and issues rigid daily commands. What is a likely consequence of this autocratic leadership style?","options":{"A":"Higher employee motivation and stronger creative ownership among senior architects","B":"Demotivation, resentment, and higher staff turnover among skilled professionals","C":"Slower decision-making caused by lengthy team consultations","D":"Complete loss of managerial control over project deadlines"},"correctOption":"B","correctAnswer":"Demotivation, resentment, and higher staff turnover among skilled professionals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because skilled professionals expect autonomy and input; dictatorial control stifles creativity and causes high turnover.","distractor_reasons":{"A":"Incorrect because autocratic exclusion reduces motivation and ownership.","B":"Correct selection.","C":"Incorrect because autocratic decisions are fast, whereas democratic consultations take longer.","D":"Incorrect because autocratic leaders maintain tight control over deadlines."}}},{"id":"P1_U2_MCQ_069","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_069","question":"After wage negotiations break down, a railway workers' trade union organizes a three-day strike across all regional passenger routes. What is an immediate impact of this industrial action on the railway operator?","options":{"A":"Increased passenger ticket sales and higher daily operating profit","B":"Permanent elimination of all union membership rights","C":"Halted train services, lost ticket revenue, and damaged customer goodwill","D":"Lower legal safety standards required on railway tracks"},"correctOption":"C","correctAnswer":"Halted train services, lost ticket revenue, and damaged customer goodwill","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because strike action stops operations, causing immediate revenue loss, penalty fines, and reputational harm.","distractor_reasons":{"A":"Incorrect because strikes stop services and reduce revenue rather than increasing sales.","B":"Incorrect because lawful strike action does not abolish employees' union rights.","C":"Correct selection.","D":"Incorrect because statutory safety laws remain unchanged."}}},{"id":"P1_U2_MCQ_070","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_070","question":"An automotive manufacturer signs a single-union agreement recognizing only one trade union to represent all factory floor employees. What is a major advantage of this arrangement for the employer?","options":{"A":"Employees are legally prohibited from ever requesting annual pay raises","B":"The company no longer needs a Human Resources department","C":"All employees are forced to work unpaid overtime shifts","D":"Management negotiates with just one representative body, saving time and preventing inter-union disputes"},"correctOption":"D","correctAnswer":"Management negotiates with just one representative body, saving time and preventing inter-union disputes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a single-union agreement streamlines collective bargaining and avoids conflicting demands from multiple rival unions.","distractor_reasons":{"A":"Incorrect because the recognized union still negotiates annual pay increases on behalf of members.","B":"Incorrect because HR is still needed for recruitment, training, payroll, and compliance.","C":"Incorrect because single-union agreements do not override overtime laws.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_071","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_071","question":"A growing solar-panel installer creates a brand-new Sustainability Compliance Officer role. Before drafting any job advertisements, the HR manager observes current workflows and interviews department heads to identify the exact duties and skills needed. What is this initial step called?","options":{"A":"Job analysis","B":"Shortlisting","C":"Induction training","D":"External headhunting"},"correctOption":"A","correctAnswer":"Job analysis","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job analysis systematically investigates the tasks, responsibilities, and skills required for a role before writing the job description and person specification.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shortlisting happens after receiving candidate applications.","C":"Incorrect because induction training takes place after a candidate is hired.","D":"Incorrect because headhunting is a recruitment method used to approach external candidates."}}},{"id":"P1_U2_MCQ_072","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_072","question":"A mid-sized accounting firm hires an external Partner from a competing practice rather than promoting an internal Senior Manager. What is a potential disadvantage of this external recruitment decision?","options":{"A":"No new clients or outside industry practices are brought into the firm","B":"High recruitment fees, longer settling-in time, and potential resentment from passed-over internal managers","C":"The external Partner already knows every internal software quirk on day one","D":"It leaves the firm with too few applicants to choose from"},"correctOption":"B","correctAnswer":"High recruitment fees, longer settling-in time, and potential resentment from passed-over internal managers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external recruitment is costly, requires longer induction, and can demotivate internal staff who hoped for promotion.","distractor_reasons":{"A":"Incorrect because bringing in fresh ideas and external experience is an advantage of external recruitment.","B":"Correct selection.","C":"Incorrect because external hires must spend time learning internal systems.","D":"Incorrect because external recruitment expands rather than shrinks the applicant pool."}}},{"id":"P1_U2_MCQ_073","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_073","question":"When a supermarket promotes its Senior Bakery Supervisor to Store Deputy Manager, the promotion creates an empty supervisor position in the bakery department that must now be filled. Which drawback of internal recruitment does this illustrate?","options":{"A":"Excessive fees paid to international executive search agencies","B":"The promoted supervisor has no knowledge of store safety policies","C":"Promoting an internal employee still leaves a vacant post elsewhere in the business","D":"External candidates are given unfair priority over existing employees"},"correctOption":"C","correctAnswer":"Promoting an internal employee still leaves a vacant post elsewhere in the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because filling a senior post internally shifts the vacancy down the hierarchy rather than adding a new person to total headcount.","distractor_reasons":{"A":"Incorrect because internal promotions do not involve external search agency fees.","B":"Incorrect because internal staff already understand store safety policies.","C":"Correct selection.","D":"Incorrect because internal recruitment prioritizes existing staff."}}},{"id":"P1_U2_MCQ_074","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_074","question":"A biotechnology laboratory needs to recruit a qualified Genetic Research Scientist with specialized gene-sequencing experience. Where is the most effective place to advertise this vacancy?","options":{"A":"A laminated poster taped to the laboratory's front reception door","B":"A local neighborhood supermarket bulletin board","C":"A general regional radio station during rush hour","D":"A specialist scientific journal and biotechnology careers website"},"correctOption":"D","correctAnswer":"A specialist scientific journal and biotechnology careers website","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because specialist trade journals and industry job boards directly reach qualified professionals possessing niche technical skills.","distractor_reasons":{"A":"Incorrect because a reception window notice will not reach specialized scientists across the country.","B":"Incorrect because local community boards suit entry-level local jobs rather than niche scientific roles.","C":"Incorrect because general radio broadcasts waste money on a broad, mostly unqualified audience.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_075","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_075","question":"A national hardware chain requires all applicants for retail assistant roles to complete a standardized online application form rather than submitting free-format CVs. What is the main advantage of using an application form?","options":{"A":"All candidates provide the exact same categories of information, making fair comparison and shortlisting easier","B":"It eliminates the need to conduct any interviews or check references","C":"Applicants can hide gaps in their employment history more easily than on a CV","D":"It guarantees that every applicant possesses strong public speaking skills"},"correctOption":"A","correctAnswer":"All candidates provide the exact same categories of information, making fair comparison and shortlisting easier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standardized application forms collect uniform data in a consistent layout, enabling objective comparison across many applicants.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shortlisted applicants still undergo interviews and reference checks.","C":"Incorrect because structured forms require specific dates, making it harder to omit employment gaps.","D":"Incorrect because written forms cannot assess verbal speaking ability."}}},{"id":"P1_U2_MCQ_076","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_076","question":"After interviewing shortlisted candidates for a Payroll Administrator role, an HR manager contacts the top candidate's two previous employers before issuing a formal job offer. What is the purpose of requesting these references?","options":{"A":"To negotiate a lower salary with the candidate's former manager","B":"To independently verify the candidate's past job performance, reliability, and honesty","C":"To fulfill statutory minimum wage reporting requirements","D":"To replace the candidate's induction training program"},"correctOption":"B","correctAnswer":"To independently verify the candidate's past job performance, reliability, and honesty","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because references provide confidential confirmation from former employers regarding an applicant's character, attendance, and claims on their CV.","distractor_reasons":{"A":"Incorrect because former employers have no role in setting the new employer's salary.","B":"Correct selection.","C":"Incorrect because minimum wage laws do not require reference checks.","D":"Incorrect because new hires still require induction training regardless of good references."}}},{"id":"P1_U2_MCQ_077","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_077","question":"A hospital uses a three-person interview panel—comprising the HR Manager, Head Nurse, and Ward Supervisor—to interview shortlisted nursing applicants. What is a primary benefit of a panel interview?","options":{"A":"It is always less intimidating for nervous candidates than a one-to-one chat","B":"It eliminates all financial costs associated with recruitment","C":"Multiple perspectives reduce individual interviewer bias and assess both technical and cultural fit","D":"It allows the hospital to hire candidates without checking nursing licenses"},"correctOption":"C","correctAnswer":"Multiple perspectives reduce individual interviewer bias and assess both technical and cultural fit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining HR and departmental specialists reduces personal bias and ensures a balanced assessment of clinical skills and team fit.","distractor_reasons":{"A":"Incorrect because panel interviews can actually feel more intimidating to candidates than one-on-one interviews.","B":"Incorrect because having three managers spend time interviewing carries significant opportunity cost.","C":"Correct selection.","D":"Incorrect because professional qualification checks remain mandatory."}}},{"id":"P1_U2_MCQ_078","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_078","question":"A bookstore chain relies heavily on part-time staff working 12 hours per week. What is a common operational disadvantage of employing a predominantly part-time workforce?","options":{"A":"The chain is forced to pay part-time workers higher hourly rates than senior managers","B":"Part-time workers are legally banned from operating cash registers","C":"Part-time staff cannot be scheduled during busy weekend shopping periods","D":"Training costs per hour worked are higher and communication across staggered shifts can be difficult"},"correctOption":"D","correctAnswer":"Training costs per hour worked are higher and communication across staggered shifts can be difficult","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed recruitment and training costs are spread over fewer weekly hours, and coordinating staff across split shifts complicates communication.","distractor_reasons":{"A":"Incorrect because part-time retail staff earn standard hourly rates lower than management salaries.","B":"Incorrect because part-time staff perform standard retail duties including checkout operation.","C":"Incorrect because covering weekend peaks is a primary reason retailers hire part-time staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_079","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_079","question":"A coastal seaside restaurant employs only full-time permanent chefs and waiters on 40-hour weekly contracts throughout the entire year, even during quiet winter months. What is the main drawback of this staffing approach?","options":{"A":"High fixed wage costs during off-peak periods when customer demand is low","B":"Staff lack familiarity with the restaurant's menu and regular customers","C":"Extremely high monthly recruitment costs from constant staff replacements","D":"Inability to keep the restaurant open for full-day lunch and dinner service"},"correctOption":"A","correctAnswer":"High fixed wage costs during off-peak periods when customer demand is low","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full-time permanent contracts obligate the business to pay full weekly wages even during slow seasonal periods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because permanent full-time staff know the menu and customers very well.","C":"Incorrect because permanent full-time staff typically have lower turnover than seasonal workers.","D":"Incorrect because full-time staff easily cover full-day operating hours."}}},{"id":"P1_U2_MCQ_080","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_080","question":"An online toy retailer hires 60 temporary warehouse pickers on eight-week fixed-term contracts to handle the surge in November and December holiday orders. Why is temporary staffing advantageous here?","options":{"A":"Temporary staff never require health and safety induction","B":"The business meets seasonal demand spikes without facing redundancy costs when sales drop in January","C":"Temporary workers always show higher long-term loyalty than permanent managers","D":"Fixed-term workers are exempt from statutory minimum wage laws"},"correctOption":"B","correctAnswer":"The business meets seasonal demand spikes without facing redundancy costs when sales drop in January","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fixed-term temporary contracts expire naturally after the peak season, avoiding costly redundancy payouts in quieter months.","distractor_reasons":{"A":"Incorrect because all workers—including temporary hires—must receive health and safety induction.","B":"Correct selection.","C":"Incorrect because short-term workers naturally have lower long-term organizational commitment.","D":"Incorrect because minimum wage laws apply equally to temporary and permanent staff."}}},{"id":"P1_U2_MCQ_081","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_081","question":"A telecommunications call center provides a structured three-day induction program for all new customer support agents before they take live calls. How does this induction training benefit the business?","options":{"A":"It eliminates the need to pay agents during their first month of employment","B":"It guarantees that agents will never request annual salary increases","C":"It helps new hires settle in quickly, reduces early errors, and lowers early staff turnover","D":"It replaces the need for ongoing performance appraisals"},"correctOption":"C","correctAnswer":"It helps new hires settle in quickly, reduces early errors, and lowers early staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective induction reduces new-starter anxiety, prevents costly early mistakes, and accelerates full productivity.","distractor_reasons":{"A":"Incorrect because employees must be paid during induction training.","B":"Incorrect because induction does not prevent future pay negotiations.","C":"Correct selection.","D":"Incorrect because induction is initial onboarding, whereas appraisals evaluate ongoing performance."}}},{"id":"P1_U2_MCQ_082","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_082","question":"A metal fabrication workshop trains new apprentices exclusively through on-the-job shadowing of senior machinists. What is a recognized drawback of this training method?","options":{"A":"The workshop must pay expensive external university tuition fees","B":"Apprentices are away from the workshop for several months at a time","C":"Training takes place on outdated simulation software unrelated to real machines","D":"Apprentices may copy unsafe shortcuts or bad habits from experienced workers while slowing down output"},"correctOption":"D","correctAnswer":"Apprentices may copy unsafe shortcuts or bad habits from experienced workers while slowing down output","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job trainers may pass on poor working habits and experience reduced output while supervising trainees.","distractor_reasons":{"A":"Incorrect because high external tuition fees are a drawback of off-the-job training.","B":"Incorrect because on-the-job trainees remain at the workplace.","C":"Incorrect because on-the-job training uses the firm's actual production equipment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_083","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_083","question":"An accounting firm sponsors its trainee auditors to attend an external institute's intensive tax-law course away from the office. What is a primary advantage of this off-the-job training?","options":{"A":"Trainees learn up-to-date specialist expertise from qualified instructors without daily office interruptions","B":"The firm avoids paying any course fees or travel expenses","C":"Trainees continue completing full client audit files during class hours","D":"The training relies entirely on informal observation of junior office clerks"},"correctOption":"A","correctAnswer":"Trainees learn up-to-date specialist expertise from qualified instructors without daily office interruptions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because off-the-job training provides expert instruction in new skills in a focused environment free from workplace distractions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because off-the-job courses typically involve significant tuition and travel costs.","C":"Incorrect because output is temporarily lost while trainees attend external classes.","D":"Incorrect because off-the-job training is led by specialist external educators."}}},{"id":"P1_U2_MCQ_084","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_084","question":"After installing automated robotic welders, an automotive parts factory must make 25 manual welders redundant. Management uses a fair selection matrix assessing skills, attendance, and disciplinary records rather than personal favoritism. Why is an objective redundancy selection process important?","options":{"A":"It allows the factory to avoid paying statutory redundancy compensation to long-serving staff","B":"It prevents costly unfair dismissal claims and maintains trust among the remaining workforce","C":"It forces redundant workers to work for free during their notice period","D":"It legally prohibits workers from applying for jobs at competing factories"},"correctOption":"B","correctAnswer":"It prevents costly unfair dismissal claims and maintains trust among the remaining workforce","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because transparent, objective redundancy criteria protect the firm against unfair dismissal lawsuits and preserve morale among surviving employees.","distractor_reasons":{"A":"Incorrect because eligible redundant employees are still legally entitled to statutory redundancy pay.","B":"Correct selection.","C":"Incorrect because employees must be paid normally during their notice period.","D":"Incorrect because redundancy selection criteria cannot bar workers from seeking new employment."}}},{"id":"P1_U2_MCQ_085","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_085","question":"Within two weeks of starting a new job, a graphic designer receives a legally binding written document specifying their job title, salary, working hours, holiday allowance, and notice period. What is this document?","options":{"A":"Person specification","B":"Internal job advertisement","C":"Contract of employment","D":"Memorandum of association"},"correctOption":"C","correctAnswer":"Contract of employment","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a contract of employment is the legally binding agreement setting out the rights, duties, pay, and conditions of both employer and employee.","distractor_reasons":{"A":"Incorrect because a person specification lists candidate requirements before recruitment.","B":"Incorrect because a job advert invites applications rather than establishing legal employment terms.","C":"Correct selection.","D":"Incorrect because a memorandum of association is a company incorporation document."}}},{"id":"P1_U2_MCQ_086","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_086","question":"A civil engineering firm rejects the highest-scoring candidate for a Site Project Manager vacancy solely because she is female, stating that 'construction sites are unsuitable for women.' Which employment law has the firm broken?","options":{"A":"Statutory minimum wage legislation","B":"Health and safety protective equipment rules","C":"Redundancy consultation notice regulations","D":"Equal opportunity and anti-discrimination legislation"},"correctOption":"D","correctAnswer":"Equal opportunity and anti-discrimination legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because anti-discrimination laws prohibit employers from rejecting or mistreating applicants based on gender, race, age, disability, or religion.","distractor_reasons":{"A":"Incorrect because minimum wage laws regulate pay floors rather than hiring bias.","B":"Incorrect because health and safety laws concern physical workplace hazards.","C":"Incorrect because redundancy laws govern job termination when roles disappear.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_087","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_087","question":"A bookstore chain closes three loss-making high-street branches and terminates its store managers' contracts with severance packages, while simultaneously firing another manager at a profitable branch for falsifying expense claims. Why are the first three managers entitled to redundancy pay while the fourth is not?","options":{"A":"The first three managers lost their jobs because their branches closed, whereas the fourth was dismissed for misconduct","B":"Managers at profitable branches are never covered by employment contracts","C":"Redundancy pay is only awarded to employees who commit disciplinary offenses","D":"Closing loss-making branches is classified as summary dismissal"},"correctOption":"A","correctAnswer":"The first three managers lost their jobs because their branches closed, whereas the fourth was dismissed for misconduct","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because redundancy occurs through no fault of the employee when the job disappears (triggering severance pay), whereas dismissal for gross misconduct forfeits redundancy compensation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all employees are covered by employment contracts regardless of branch profitability.","C":"Incorrect because disciplinary offenses lead to dismissal without redundancy compensation.","D":"Incorrect because branch closure results in redundancy, not dismissal."}}},{"id":"P1_U2_MCQ_088","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_088","question":"Under a company's redundancy policy, redundant staff receive $400 for each completed year of service plus 2 weeks' pay in lieu of notice. If an employee earning $600 per week is made redundant after 7 completed years of service, what is their total redundancy payout?","options":{"A":"$2,800","B":"$4,000","C":"$3,400","D":"$5,400"},"correctOption":"B","correctAnswer":"$4,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because service payout = 7 years × $400 = $2,800, and notice pay = 2 weeks × $600 = $1,200, giving a total payout of $4,000.","distractor_reasons":{"A":"Incorrect because $2,800 includes only the service-years payout and omits the $1,200 notice pay.","B":"Correct selection.","C":"Incorrect because $3,400 adds only 1 week of notice pay ($600) instead of 2 weeks ($1,200).","D":"Incorrect calculation (7 × $600 + 2 × $600 = $5,400)."}}},{"id":"P1_U2_MCQ_089","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_089","question":"A distribution warehouse employed an average of 150 staff during the year, and 27 employees left the company over the same 12-month period. What was the warehouse's annual labor turnover rate?","options":{"A":"27%","B":"5.6%","C":"18%","D":"82%"},"correctOption":"C","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labor turnover rate = (number of leavers / average workforce) × 100 = (27 / 150) × 100 = 18%.","distractor_reasons":{"A":"Incorrect because 27 is the absolute number of staff who left, not the percentage rate.","B":"Incorrect because 5.6% divides 150 by 27 (150 / 27 = 5.56).","C":"Correct selection.","D":"Incorrect because 82% is the staff retention rate (100% - 18%)."}}},{"id":"P1_U2_MCQ_090","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_090","question":"A chemical plant invests $120,000 in upgraded ventilation systems and protective respirators to comply with strict health and safety laws. How can this expenditure financially benefit the business over the long term?","options":{"A":"It exempts the plant from paying corporate taxes on chemical sales","B":"It allows the plant to reduce workers' hourly wages below the legal minimum","C":"It eliminates the need for any employee safety training","D":"It lowers absenteeism, avoids costly government fines, and boosts worker morale and productivity"},"correctOption":"D","correctAnswer":"It lowers absenteeism, avoids costly government fines, and boosts worker morale and productivity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because safe working environments reduce workplace accidents, sick-leave disruption, compensation claims, and regulatory penalties while improving morale.","distractor_reasons":{"A":"Incorrect because health and safety spending does not eliminate corporate tax liabilities.","B":"Incorrect because safety compliance never permits paying below statutory minimum wages.","C":"Incorrect because workers still require training on how to use protective equipment properly.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_091","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_091","question":"When introducing a new customer returns policy, a Store Manager holds an interactive Q&A meeting rather than simply pinning a notice on the wall. Why is two-way communication superior to one-way communication here?","options":{"A":"It allows the manager to confirm that staff understood the policy accurately and resolve unclear points immediately","B":"It takes significantly less time than posting a written notice","C":"It prevents staff from expressing any opinions or concerns","D":"It automatically creates a signed legal contract for each employee"},"correctOption":"A","correctAnswer":"It allows the manager to confirm that staff understood the policy accurately and resolve unclear points immediately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because two-way communication includes a feedback loop that verifies comprehension and makes employees feel valued.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because two-way discussions usually take more time than one-way notices.","C":"Incorrect because two-way communication actively invites employee questions and opinions.","D":"Incorrect because verbal Q&A sessions do not generate signed legal contracts."}}},{"id":"P1_U2_MCQ_092","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_092","question":"A Purchasing Manager at a bicycle manufacturer sends a formal purchase order via email to an overseas aluminum frame supplier confirming delivery quantities and payment terms. Which type of communication is this?","options":{"A":"Internal horizontal communication","B":"External written/electronic communication","C":"Informal grapevine communication","D":"Internal downward briefing"},"correctOption":"B","correctAnswer":"External written/electronic communication","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because communicating with an outside supplier is external communication, and sending a written order via email creates a permanent electronic record.","distractor_reasons":{"A":"Incorrect because internal communication occurs strictly between employees within the same business.","B":"Correct selection.","C":"Incorrect because a formal purchase order is an official commercial transaction, not an informal rumor.","D":"Incorrect because downward briefings go from managers to subordinates inside the firm."}}},{"id":"P1_U2_MCQ_093","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_093","question":"A global fashion retailer conducts its monthly merchandising review via live video conferencing with regional directors in London, Tokyo, and New York instead of flying everyone to headquarters. What is a primary benefit of this electronic communication method?","options":{"A":"It eliminates all differences in international time zones","B":"It works reliably even when corporate internet servers are offline","C":"It saves substantial international travel costs and executive time while allowing visual facial expressions","D":"It guarantees zero technical glitches during live presentations"},"correctOption":"C","correctAnswer":"It saves substantial international travel costs and executive time while allowing visual facial expressions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because video conferencing reduces airfare/hotel costs and travel downtime while preserving visual cues and real-time discussion.","distractor_reasons":{"A":"Incorrect because time-zone differences still exist and must be scheduled around.","B":"Incorrect because video conferencing requires active internet connectivity.","C":"Correct selection.","D":"Incorrect because video calls remain vulnerable to occasional network or audio glitches."}}},{"id":"P1_U2_MCQ_094","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_094","question":"Following two safety near-misses, a logistics warehouse posts updated forklift speed limits on official noticeboards and requires every driver to sign a written acknowledgment form. Why is written communication essential in this case?","options":{"A":"It allows drivers to debate and vote on whether to obey speed limits","B":"It is the quickest way to warn a driver about an immediate collision","C":"It eliminates the need for any visual speed-limit signs in the warehouse","D":"It provides permanent documentary proof that every driver received and acknowledged the safety rule"},"correctOption":"D","correctAnswer":"It provides permanent documentary proof that every driver received and acknowledged the safety rule","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because signed written notices provide verifiable legal evidence of compliance and ensure consistent rules for all staff.","distractor_reasons":{"A":"Incorrect because safety rules are mandatory policies rather than subjects for voting.","B":"Incorrect because verbal shouts or horns warn of immediate collisions faster than written notices.","C":"Incorrect because visual signs remain necessary reminders on the warehouse floor.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_095","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_095","question":"An Operations Director receives over 250 unprioritized internal emails every day and overlooks an urgent message from a supplier warning of a raw-material shortage. Which communication barrier caused this failure?","options":{"A":"Information overload preventing the receiver from identifying critical messages","B":"Use of overly simple visual diagrams","C":"Absence of electronic email software in the office","D":"A flat organizational structure with too few managers"},"correctOption":"A","correctAnswer":"Information overload preventing the receiver from identifying critical messages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive message volume ('information overload') overwhelms receivers and causes important communications to be missed or delayed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clear visual diagrams improve comprehension rather than cause overload.","C":"Incorrect because the director had email software, which was flooded with messages.","D":"Incorrect because email overload stems from excessive message volume rather than flat hierarchy."}}},{"id":"P1_U2_MCQ_096","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_096","question":"A site engineer calls a concrete supplier from a noisy highway construction zone with weak cellular reception, resulting in the supplier mishearing '14 cubic meters' as '40 cubic meters.' Which barrier to communication occurred?","options":{"A":"Cultural hostility between the engineer and supplier","B":"Physical noise and poor transmission medium distorting the spoken message","C":"Over-reliance on detailed written purchase contracts","D":"Excessive use of technical accounting jargon"},"correctOption":"B","correctAnswer":"Physical noise and poor transmission medium distorting the spoken message","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because background physical noise and weak mobile signal interfere with the communication channel and corrupt verbal accuracy.","distractor_reasons":{"A":"Incorrect because the error was acoustic/technical rather than caused by cultural conflict.","B":"Correct selection.","C":"Incorrect because a written order would have prevented the spoken mishearing.","D":"Incorrect because the confusion was between similar-sounding numbers rather than jargon."}}},{"id":"P1_U2_MCQ_097","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_097","question":"Factory workers ignore a new productivity poster from a Plant Manager who previously broke promises regarding overtime pay. Which barrier to effective communication is illustrated here?","options":{"A":"Failure of the factory's Wi-Fi network","B":"Inability of workers to read basic written text","C":"Lack of trust and poor sender-receiver relationship causing receivers to dismiss the message","D":"Excessive two-way consultation before printing the poster"},"correctOption":"C","correctAnswer":"Lack of trust and poor sender-receiver relationship causing receivers to dismiss the message","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because distrust or hostility toward the sender acts as a psychological barrier that leads receivers to ignore or disbelieve messages.","distractor_reasons":{"A":"Incorrect because a printed poster does not depend on Wi-Fi.","B":"Incorrect because workers dismissed the message due to distrust rather than illiteracy.","C":"Correct selection.","D":"Incorrect because genuine two-way consultation would have helped rebuild trust."}}},{"id":"P1_U2_MCQ_098","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_098","question":"After explaining complex machine calibration steps to a new technician, a Maintenance Supervisor asks the technician to summarize the procedure in their own words before starting work. How does this practice improve communication?","options":{"A":"It converts two-way verbal communication into a one-way written memo","B":"It eliminates the need for any safety equipment on the machine","C":"It lengthens the chain of command between managers and technicians","D":"It uses a feedback check to verify accurate understanding and prevent costly operational errors"},"correctOption":"D","correctAnswer":"It uses a feedback check to verify accurate understanding and prevent costly operational errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because asking the receiver to restate instructions provides immediate feedback confirming that the message was decoded accurately.","distractor_reasons":{"A":"Incorrect because paraphrasing back is an active two-way verbal feedback technique.","B":"Incorrect because safety equipment remains mandatory.","C":"Incorrect because direct supervisor-technician dialogue involves zero extra hierarchy layers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_099","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_099","question":"A hotel group introduces an anonymous digital suggestion portal and monthly staff forums so housekeepers and receptionists can report operational bottlenecks directly to senior directors. Which direction of formal communication does this strengthen?","options":{"A":"Upward communication from frontline employees to senior management","B":"Downward communication from directors to external shareholders","C":"External marketing communication to travel agencies","D":"Informal canteen gossip between competing hotel chains"},"correctOption":"A","correctAnswer":"Upward communication from frontline employees to senior management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because upward communication carries feedback, ideas, and frontline operational issues from lower-level staff up to decision-makers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because downward communication flows from senior managers down to subordinates.","C":"Incorrect because internal staff forums are directed at employees rather than external agencies.","D":"Incorrect because official suggestion portals are formal internal channels, not external gossip."}}},{"id":"P1_U2_MCQ_100","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_100","question":"During an annual shareholder presentation, a Finance Director replaces ten pages of dense accounting spreadsheets with color-coded bar charts comparing five years of regional profit growth. What is the main advantage of using visual charts here?","options":{"A":"Visual charts legally replace audited annual financial statements","B":"Visual data highlights key trends and comparisons rapidly, making complex figures easier to grasp","C":"Bar charts allow shareholders to negotiate product prices directly with factory workers","D":"Visual slides take zero time to prepare compared to raw numbers"},"correctOption":"B","correctAnswer":"Visual data highlights key trends and comparisons rapidly, making complex figures easier to grasp","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visual charts simplify complex numerical data so audiences can quickly spot trends, patterns, and comparisons.","distractor_reasons":{"A":"Incorrect because companies must still publish formal audited financial accounts.","B":"Correct selection.","C":"Incorrect because shareholder presentations do not involve price negotiations with workers.","D":"Incorrect because designing clear visual charts requires thoughtful preparation."}}},{"id":"P1_U2_MCQ_101","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_101","question":"A telecommunications retailer pays its store sales advisors a modest basic hourly wage plus a 4% commission on every mobile phone contract sold. What is a potential disadvantage of relying heavily on sales commission?","options":{"A":"Sales advisors may use aggressive, high-pressure selling tactics that damage long-term customer loyalty","B":"Sales advisors earn the exact same monthly income regardless of how many contracts they sell","C":"The business must pay high fixed commission costs even during months when zero contracts are sold","D":"Commission eliminates any financial incentive for staff to approach customers on the shop floor"},"correctOption":"A","correctAnswer":"Sales advisors may use aggressive, high-pressure selling tactics that damage long-term customer loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high commission incentives can encourage pushy selling or mis-selling products that do not suit customers, harming repeat business and brand reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commission causes income to fluctuate directly with sales volume.","C":"Incorrect because commission is a variable cost that only arises when sales occur.","D":"Incorrect because commission strongly motivates staff to actively pursue sales."}}},{"id":"P1_U2_MCQ_102","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_102","question":"An architectural design studio allows its senior architects to choose which sustainable building projects they lead and provides research budgets so they can pioneer innovative green materials. According to Maslow's hierarchy of needs, which highest-level need is being fulfilled?","options":{"A":"Physiological needs","B":"Self-actualization needs","C":"Safety and security needs","D":"Social belonging needs"},"correctOption":"B","correctAnswer":"Self-actualization needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because self-actualization sits at the top of Maslow's hierarchy and involves personal growth, creative autonomy, and realizing one's full potential.","distractor_reasons":{"A":"Incorrect because physiological needs concern basic survival necessities such as food, shelter, and basic pay.","B":"Correct selection.","C":"Incorrect because safety needs relate to physical safety and job security.","D":"Incorrect because social needs involve friendship, teamwork, and interpersonal acceptance."}}},{"id":"P1_U2_MCQ_103","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_103","question":"Workers at a garment factory complain that the sewing room is excessively hot and that supervisory rules are applied inconsistently. According to Herzberg's two-factor theory, how should management interpret this situation?","options":{"A":"Fixing the air conditioning and rules will permanently maximize worker productivity on its own","B":"Workers are complaining because they have already achieved self-actualization","C":"Poor hygiene factors are causing active job dissatisfaction and must be fixed before motivators can work","D":"Offering piece-rate bonuses will completely eliminate complaints about workplace heat"},"correctOption":"C","correctAnswer":"Poor hygiene factors are causing active job dissatisfaction and must be fixed before motivators can work","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg classifies physical working conditions and supervision as hygiene factors; when inadequate, they create dissatisfaction that blocks motivation.","distractor_reasons":{"A":"Incorrect because improving hygiene factors removes dissatisfaction but does not by itself create high motivation.","B":"Incorrect because self-actualization is a Maslow concept, and poor working conditions indicate unmet basic hygiene needs.","C":"Correct selection.","D":"Incorrect because Herzberg argued financial incentives cannot compensate for poor hygiene factors."}}},{"id":"P1_U2_MCQ_104","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_104","question":"A textile weaver is paid a basic time-rate wage of $10 per hour for a 38-hour standard week, plus a piece-rate bonus of $1.50 for every meter of fabric woven above 100 meters. In one week, the weaver works 38 hours and produces 140 meters of fabric. What is their total gross pay?","options":{"A":"$380","B":"$590","C":"$520","D":"$440"},"correctOption":"D","correctAnswer":"$440","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because basic time-rate pay = 38 hours × $10 = $380, and piece-rate bonus = (140 - 100 = 40 extra meters) × $1.50 = $60, giving a total gross pay of $440.","distractor_reasons":{"A":"Incorrect because $380 includes only the basic 38-hour wage and omits the $60 output bonus.","B":"Incorrect because $590 pays the $1.50 bonus on all 140 meters ($210) instead of only the 40 meters above target.","C":"Incorrect because $520 adds $140 (140 × $1.00) to $380.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_105","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_105","question":"A commercial printing company introduces an employee share-ownership scheme allowing staff to purchase company shares at a discounted price. How does this financial reward aim to motivate employees?","options":{"A":"It gives employees a direct financial stake in the company's long-term success and dividend growth","B":"It guarantees employees a fixed weekly cash bonus even if the company makes a loss","C":"It replaces the need to pay employees any regular monthly wages or salaries","D":"It allows individual machine operators to set retail printing prices for clients"},"correctOption":"A","correctAnswer":"It gives employees a direct financial stake in the company's long-term success and dividend growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because share ownership aligns employees' personal wealth with company profitability and share value, encouraging loyalty and higher effort.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share dividends and share prices fluctuate with company performance rather than guaranteeing fixed cash bonuses.","C":"Incorrect because share schemes supplement regular wages or salaries rather than replacing them.","D":"Incorrect because owning employee shares does not grant operational pricing authority."}}},{"id":"P1_U2_MCQ_106","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_106","question":"A customer service department suffers from high absenteeism because call-center agents repeat identical billing queries all day. Management trains agents to also handle technical troubleshooting and account upgrades, giving them authority to issue goodwill credits. Which motivator is management applying?","options":{"A":"Scientific time-and-motion piece rates","B":"Job enrichment","C":"Autocratic micromanagement","D":"Downsizing"},"correctOption":"B","correctAnswer":"Job enrichment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job enrichment upgrades a role with more varied, skilled tasks and greater decision-making authority (issuing goodwill credits).","distractor_reasons":{"A":"Incorrect because Taylor's piece-rate approach narrows tasks into simple repetitive steps.","B":"Correct selection.","C":"Incorrect because micromanagement removes worker autonomy rather than granting authority.","D":"Incorrect because downsizing reduces workforce headcount."}}},{"id":"P1_U2_MCQ_107","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_107","question":"According to F.W. Taylor's theory of scientific management, what is the primary factor that motivates factory workers to increase their daily output?","options":{"A":"Opportunities for creative self-expression and autonomous teamwork","B":"Public praise certificates and monthly social gatherings","C":"Financial rewards directly linked to individual units of output produced","D":"Participation in democratic boardroom strategy meetings"},"correctOption":"C","correctAnswer":"Financial rewards directly linked to individual units of output produced","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Taylor viewed workers as motivated primarily by money ('economic man') and advocated piece-rate pay tied to standardized output targets.","distractor_reasons":{"A":"Incorrect because creative self-expression reflects Maslow's self-actualization rather than Taylorism.","B":"Incorrect because non-financial praise and social needs belong to Maslow and Herzberg.","C":"Correct selection.","D":"Incorrect because Taylor favored strict management planning of tasks rather than worker participation in strategy."}}},{"id":"P1_U2_MCQ_108","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_108","question":"A regional supermarket chain invests in accredited retail management training courses for its floor supervisors so they can qualify for future branch manager vacancies. How does this non-financial motivator benefit the supermarket?","options":{"A":"It immediately lowers hourly wage rates for all trained supervisors","B":"It eliminates the need for any store security or stock control","C":"It prevents supervisors from ever applying for promotions","D":"It increases staff loyalty, improves operational competence, and reduces external recruitment costs"},"correctOption":"D","correctAnswer":"It increases staff loyalty, improves operational competence, and reduces external recruitment costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because investing in employee training boosts morale, raises skill levels, and builds an internal talent pipeline for senior roles.","distractor_reasons":{"A":"Incorrect because upskilled supervisors generally earn higher, not lower, compensation.","B":"Incorrect because training complements rather than replaces store controls.","C":"Incorrect because management training actively prepares supervisors for promotion.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_109","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_109","question":"A hospital laboratory rotates its biomedical technicians every month between blood testing, microbiology cultures, and sample intake reception. What is a potential limitation of this job rotation?","options":{"A":"Productivity may temporarily dip each time technicians switch stations and adjust to different tasks","B":"Technicians become permanently unable to cover for absent colleagues","C":"The laboratory must pay double hourly salaries whenever a technician changes stations","D":"Job rotation completely eliminates all boredom from repetitive laboratory procedures"},"correctOption":"A","correctAnswer":"Productivity may temporarily dip each time technicians switch stations and adjust to different tasks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because frequent task switching requires broader training and can cause brief efficiency drops as workers re-adjust to each station.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cross-training actually improves the team's ability to cover absences.","C":"Incorrect because rotating among peer-level duties does not double pay rates.","D":"Incorrect because rotating between several routine tasks reduces monotony but does not eliminate it entirely."}}},{"id":"P1_U2_MCQ_110","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_110","question":"A mid-sized software company notices that despite paying salaries well above the market average, skilled developers are resigning due to boring maintenance tasks and zero autonomy. Which motivation theorist best explains why high pay alone failed to retain them?","options":{"A":"F.W. Taylor, who argued high wages always guarantee maximum loyalty","B":"Frederick Herzberg, who showed that pay is a hygiene factor while interesting work and responsibility act as true motivators","C":"Henri Fayol, who defined the five administrative functions of management","D":"Adam Smith, who advocated extreme division of labor on pin assembly lines"},"correctOption":"B","correctAnswer":"Frederick Herzberg, who showed that pay is a hygiene factor while interesting work and responsibility act as true motivators","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Herzberg demonstrated that competitive pay only prevents dissatisfaction (hygiene), whereas long-term motivation requires meaningful work and autonomy.","distractor_reasons":{"A":"Incorrect because Taylor's view that money alone motivates contradicts the scenario where high pay failed.","B":"Correct selection.","C":"Incorrect because Fayol focused on management functions rather than hygiene vs. motivator factors.","D":"Incorrect because division of labor increases specialization rather than explaining non-financial motivation."}}},{"id":"P1_U2_MCQ_111","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_111","question":"A fast-growing e-commerce startup expands from 15 employees to 220 employees across warehousing, IT, marketing, and finance, causing confusion over who approves budgets and handles customer complaints. Why does the startup now need a formal organizational structure?","options":{"A":"To eliminate all communication between different departments","B":"To guarantee that the business never pays corporate income tax","C":"To clarify roles, establish clear lines of authority, and coordinate specialized departments effectively","D":"To replace all written employment contracts with verbal agreements"},"correctOption":"C","correctAnswer":"To clarify roles, establish clear lines of authority, and coordinate specialized departments effectively","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because as a business grows, a formal structure defines responsibilities, accountability, and reporting lines so departments work together smoothly.","distractor_reasons":{"A":"Incorrect because organizational structures facilitate structured inter-departmental coordination rather than blocking communication.","B":"Incorrect because organizational charts have no bearing on tax obligations.","C":"Correct selection.","D":"Incorrect because formal structures coexist with written employment contracts."}}},{"id":"P1_U2_MCQ_112","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_112","question":"In a commercial bank's wealth management division, each Senior Advisor has a narrow span of control of only 3 junior analysts. Why is a narrow span of control justified in this setting?","options":{"A":"The junior analysts perform identical, simple data-entry tasks requiring zero guidance","B":"A narrow span of control reduces the total number of managers needed in the bank","C":"Senior Advisors have no accountability for the accuracy of client investment portfolios","D":"Complex, high-risk financial analysis requires close supervision, coaching, and frequent review"},"correctOption":"D","correctAnswer":"Complex, high-risk financial analysis requires close supervision, coaching, and frequent review","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because narrow spans of control allow managers to provide close support, detailed quality checks, and mentoring on complex tasks.","distractor_reasons":{"A":"Incorrect because simple, repetitive tasks allow wide spans of control.","B":"Incorrect because narrow spans of control actually require more supervisory tiers and managers.","C":"Incorrect because Senior Advisors remain fully accountable for their team's client advice.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_113","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_113","question":"After winning a major construction contract, a Project Director assigns machinery to specific sites, groups engineers into structural and electrical teams, and allocates budgets to each team leader. Which management function is being performed?","options":{"A":"Organizing","B":"Controlling","C":"Appraising","D":"Retrenching"},"correctOption":"A","correctAnswer":"Organizing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organizing involves arranging people, equipment, and financial resources into structured teams to execute plans.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because controlling monitors actual progress against targets after work starts.","C":"Incorrect because appraising evaluates individual staff performance.","D":"Incorrect because retrenching refers to making surplus staff redundant."}}},{"id":"P1_U2_MCQ_114","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_114","question":"During a busy retail sales promotion, a Store Supervisor assigns cashiers to open checkout lanes, encourages staff to maintain friendly service, and resolves immediate queue bottlenecks on the shop floor. Which management function is this?","options":{"A":"Long-term strategic planning","B":"Commanding (directing and leading staff)","C":"External recruitment advertising","D":"Redundancy consultation"},"correctOption":"B","correctAnswer":"Commanding (directing and leading staff)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because commanding involves guiding, instructing, and motivating employees in their day-to-day duties so operational objectives are met.","distractor_reasons":{"A":"Incorrect because long-term planning sets multi-year objectives rather than directing live shop-floor shifts.","B":"Correct selection.","C":"Incorrect because external advertising recruits new applicants rather than leading current staff.","D":"Incorrect because redundancy consultation deals with downsizing surplus jobs."}}},{"id":"P1_U2_MCQ_115","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_115","question":"A Regional Sales Manager delegates responsibility for organizing a local trade exhibition to a Junior Marketing Officer. How does effective delegation motivate the Junior Marketing Officer?","options":{"A":"It guarantees that the officer will never be evaluated on the exhibition's outcome","B":"It removes all challenging duties from the officer's daily schedule","C":"It demonstrates trust, builds new organizational skills, and satisfies esteem and achievement needs","D":"It converts the officer's role into an unsupervised laissez-faire contract"},"correctOption":"C","correctAnswer":"It demonstrates trust, builds new organizational skills, and satisfies esteem and achievement needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegating meaningful tasks enriches subordinates' roles, signals managerial trust, and develops confidence for future career progression.","distractor_reasons":{"A":"Incorrect because subordinates remain responsible for carrying out the delegated task properly.","B":"Incorrect because delegation adds challenging responsibility rather than removing it.","C":"Correct selection.","D":"Incorrect because delegation includes clear objectives and managerial support."}}},{"id":"P1_U2_MCQ_116","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_116","question":"A national supermarket chain centralizes all supplier purchasing, store layouts, and product pricing at its head office, leaving individual branch managers with very little local decision-making power. What is a primary advantage of this centralized structure?","options":{"A":"Branch managers can instantly adapt product ranges to unique local neighborhood tastes","B":"Local store staff feel highly empowered to set their own promotional discounts","C":"Head office directors have zero involvement in operational standards","D":"Consistent brand standards across all stores and bulk-buying economies of scale"},"correctOption":"D","correctAnswer":"Consistent brand standards across all stores and bulk-buying economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because centralization ensures uniform policies across all branches and enables bulk purchasing discounts from suppliers.","distractor_reasons":{"A":"Incorrect because local responsiveness is an advantage of decentralization, not centralization.","B":"Incorrect because centralization restricts local pricing autonomy.","C":"Incorrect because head office executives control key decisions in a centralized firm.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_117","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_117","question":"An international hotel group decentralizes authority so that general managers in each country can tailor restaurant menus, local marketing campaigns, and room rates to regional market conditions. What is a key benefit of decentralization?","options":{"A":"Faster decisions tailored to local customer preferences and higher motivation for regional managers","B":"Complete uniformity of menus and pricing across every hotel worldwide","C":"Elimination of the need to recruit skilled regional general managers","D":"Lower risk of inconsistent service standards across different countries"},"correctOption":"A","correctAnswer":"Faster decisions tailored to local customer preferences and higher motivation for regional managers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decentralization empowers local managers to respond rapidly to local market needs without waiting for head-office approval.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because uniformity is achieved through centralization, whereas decentralization allows local variation.","C":"Incorrect because decentralization requires highly capable local managers to exercise authority safely.","D":"Incorrect because inconsistent standards across branches is actually a risk of decentralization."}}},{"id":"P1_U2_MCQ_118","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_118","question":"A long-standing family-owned manufacturing firm treats employees like extended family members—providing housing loans and subsidized meals—while senior owners make all business decisions 'in the workers' best interests' without consulting them. Which leadership style does this describe?","options":{"A":"Laissez-faire leadership","B":"Paternalistic leadership","C":"Democratic leadership","D":"Delegative leadership"},"correctOption":"B","correctAnswer":"Paternalistic leadership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because paternalistic leaders act like parental figures—caring for employees' welfare while retaining unilateral decision-making power.","distractor_reasons":{"A":"Incorrect because laissez-faire leaders leave employees to make their own decisions.","B":"Correct selection.","C":"Incorrect because democratic leaders actively consult employees and share decision-making.","D":"Incorrect because delegative leaders pass decision-making authority down to subordinates."}}},{"id":"P1_U2_MCQ_119","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_119","question":"During a pay dispute at a port terminal, dockworkers continue attending work normally but strictly refuse to work any voluntary overtime hours, slowing down ship unloading schedules. Which type of industrial action is the trade union using?","options":{"A":"All-out strike","B":"Lockout by management","C":"Overtime ban","D":"Redundancy retrenchment"},"correctOption":"C","correctAnswer":"Overtime ban","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overtime ban occurs when union members refuse to work beyond their standard contracted hours to pressure management while still earning basic wages.","distractor_reasons":{"A":"Incorrect because an all-out strike involves workers completely withdrawing their labor and staying away from work.","B":"Incorrect because a lockout is initiated by employers closing the workplace, not by workers.","C":"Correct selection.","D":"Incorrect because redundancy is job termination caused by falling labor demand."}}},{"id":"P1_U2_MCQ_120","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_120","question":"A retail employee faces an unfair disciplinary warning from their store manager and asks their trade union representative to accompany them to the formal hearing and provide legal guidance. How does union membership benefit the employee here?","options":{"A":"The union automatically pays the employee's full monthly salary for life","B":"The union can legally fire the store manager on the spot","C":"The union exempts the employee from following store health and safety rules","D":"The union provides expert representation, advice, and protection against unfair treatment by management"},"correctOption":"D","correctAnswer":"The union provides expert representation, advice, and protection against unfair treatment by management","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade unions support individual members during workplace grievances and disciplinary hearings with experienced representation and legal advice.","distractor_reasons":{"A":"Incorrect because unions do not pay members' lifetime salaries.","B":"Incorrect because hiring and firing managers belongs to company executives, not trade unions.","C":"Incorrect because all workers remain legally bound by workplace safety regulations.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_121","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_121","question":"When recruiting a new Chief Financial Officer, a publicly listed bank hires a specialist executive search agency to directly approach experienced finance directors at rival institutions. What is this recruitment method called?","options":{"A":"Headhunting","B":"Internal job posting","C":"Government job-center advertising","D":"Campus apprenticeship outreach"},"correctOption":"A","correctAnswer":"Headhunting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because headhunting involves specialist recruiters proactively identifying and approaching high-caliber senior executives currently employed elsewhere.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal job postings advertise vacancies only to existing staff.","C":"Incorrect because government job centers typically advertise entry-level or general local vacancies.","D":"Incorrect because campus outreach targets graduating students rather than senior CFOs."}}},{"id":"P1_U2_MCQ_122","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_122","question":"An HR assistant accidentally includes 'Must possess a valid heavy-goods driving license and five years of logistics experience' inside a Job Description rather than a Person Specification. Why is this a classification error?","options":{"A":"Driving licenses are illegal to require in transport job adverts","B":"Qualifications and candidate experience belong in the Person Specification, whereas the Job Description outlines job duties and conditions","C":"Job Descriptions are only written after a candidate has already been hired","D":"Person Specifications are legally binding employment contracts"},"correctOption":"B","correctAnswer":"Qualifications and candidate experience belong in the Person Specification, whereas the Job Description outlines job duties and conditions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a job description describes the role itself (tasks, hours, reporting lines), while a person specification defines the attributes required of the person.","distractor_reasons":{"A":"Incorrect because requiring a valid license is completely legal and essential for driving roles.","B":"Correct selection.","C":"Incorrect because both documents are prepared before advertising the vacancy.","D":"Incorrect because a person specification is a selection criterion tool, not a signed employment contract."}}},{"id":"P1_U2_MCQ_123","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_123","question":"A software development firm publishes a job advertisement on its corporate website and LinkedIn page for a Senior Cloud Architect. Which detail MUST be included in an effective job advertisement to attract suitable applicants?","options":{"A":"The confidential home addresses of all current company board directors","B":"The company's complete five-year tax audit history","C":"Job title, key responsibilities, required qualifications, salary/benefits range, and how to apply","D":"A list of every rejected applicant from previous recruitment rounds"},"correctOption":"C","correctAnswer":"Job title, key responsibilities, required qualifications, salary/benefits range, and how to apply","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective job adverts summarize key details from the job description and person specification alongside application instructions and deadlines.","distractor_reasons":{"A":"Incorrect because directors' private addresses are confidential and irrelevant.","B":"Incorrect because internal tax audits do not belong in recruitment advertisements.","C":"Correct selection.","D":"Incorrect because disclosing past applicants violates privacy and serves no recruitment purpose."}}},{"id":"P1_U2_MCQ_124","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_124","question":"An applicant applying for a Marketing Coordinator position submits a two-page document summarizing their university degree, past internships, digital campaign achievements, and contact details for two referees. What is this document called?","options":{"A":"Job description","B":"Person specification","C":"Contract of employment","D":"Curriculum vitae (CV / résumé)"},"correctOption":"D","correctAnswer":"Curriculum vitae (CV / résumé)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a curriculum vitae (CV) is prepared by a job seeker to showcase their education, work history, skills, and referees.","distractor_reasons":{"A":"Incorrect because a job description is written by the employer to describe the vacancy's duties.","B":"Incorrect because a person specification is written by the employer to list desired candidate traits.","C":"Incorrect because an employment contract is issued by the employer after selecting the winner.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_125","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_125","question":"A management consultancy invites six shortlisted graduate applicants to a full-day assessment center featuring group problem-solving exercises, client role-plays, and case-study presentations. What is a primary advantage of using an assessment center?","options":{"A":"It allows selectors to observe candidates' teamwork, communication, and leadership behaviors in realistic scenarios","B":"It is the cheapest and fastest way to hire seasonal warehouse workers","C":"It completely eliminates the need to verify university degrees or references","D":"It guarantees that selected graduates will never leave the consultancy"},"correctOption":"A","correctAnswer":"It allows selectors to observe candidates' teamwork, communication, and leadership behaviors in realistic scenarios","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assessment centers test practical interpersonal, analytical, and teamwork competencies far more thoroughly than a short interview alone.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because assessment centers are expensive and time-consuming, suited for management/graduate roles rather than seasonal labor.","C":"Incorrect because background and qualification checks are still conducted.","D":"Incorrect because no selection method can permanently prevent future staff turnover."}}},{"id":"P1_U2_MCQ_126","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_126","question":"During a job interview for a Sales Executive role, the interviewer asks every shortlisted candidate the exact same set of competency questions and scores answers using a standardized rating rubric. Why is a structured interview beneficial?","options":{"A":"It prevents candidates from asking any questions about salary or working hours","B":"It ensures fairness, reduces interviewer bias, and enables objective comparison across all candidates","C":"It replaces the need for a written job description","D":"It allows the interviewer to hire candidates without reviewing their CVs"},"correctOption":"B","correctAnswer":"It ensures fairness, reduces interviewer bias, and enables objective comparison across all candidates","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because asking identical questions scored against standardized criteria minimizes personal favoritism and supports equal-opportunity compliance.","distractor_reasons":{"A":"Incorrect because structured interviews still include time at the end for candidate questions.","B":"Correct selection.","C":"Incorrect because structured questions are designed directly from the job description and person specification.","D":"Incorrect because CVs are reviewed during shortlisting before interviews take place."}}},{"id":"P1_U2_MCQ_127","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_127","question":"A pharmaceutical manufacturer advertises a Senior Quality Assurance Chemist role on its internal staff intranet before considering any outside applicants. Why do many firms advertise vacancies internally first?","options":{"A":"External applicants are legally banned from applying for laboratory jobs","B":"Internal candidates always bring brand-new ideas from competing pharmaceutical firms","C":"It saves external advertising costs, speeds up selection, and rewards loyal employees with career progression","D":"It ensures the company never has to train any employees"},"correctOption":"C","correctAnswer":"It saves external advertising costs, speeds up selection, and rewards loyal employees with career progression","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal recruitment is low-cost, fast, builds on known staff reliability, and boosts workforce morale through promotion opportunities.","distractor_reasons":{"A":"Incorrect because external recruitment is completely legal.","B":"Incorrect because external recruits bring outside ideas, whereas internal staff already know internal systems.","C":"Correct selection.","D":"Incorrect because promoted internal staff still require role-specific training."}}},{"id":"P1_U2_MCQ_128","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_128","question":"A parcel delivery company hires 40 part-time sorting operatives working four-hour evening shifts from 6:00 PM to 10:00 PM when parcel volumes peak. How does this benefit the company's cost structure?","options":{"A":"The company avoids paying any hourly wages during the four-hour evening shift","B":"Part-time operatives are legally prohibited from joining trade unions","C":"Training costs per worker are zero for part-time evening shifts","D":"The company pays wages only during peak sorting hours rather than funding idle full-time shifts all day"},"correctOption":"D","correctAnswer":"The company pays wages only during peak sorting hours rather than funding idle full-time shifts all day","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because part-time staffing aligns labor costs tightly with concentrated demand windows, avoiding wasted payroll during quiet daytime hours.","distractor_reasons":{"A":"Incorrect because part-time staff must be paid for all hours worked.","B":"Incorrect because part-time workers have the exact same statutory right to join unions as full-time staff.","C":"Incorrect because part-time staff still require safety and operational training.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_129","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_129","question":"An engineering consultancy employs full-time chartered engineers rather than part-time contractors on multi-year infrastructure projects. What is a primary reason for preferring full-time staff on complex projects?","options":{"A":"Continuity of project knowledge, stronger team communication, and consistent client availability","B":"Full-time engineers do not require paid vacation or sick leave","C":"The consultancy can dismiss full-time engineers without notice whenever a meeting ends","D":"Full-time staff cost less per year than part-time staff working half the hours"},"correctOption":"A","correctAnswer":"Continuity of project knowledge, stronger team communication, and consistent client availability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full-time staff provide uninterrupted continuity, seamless daily collaboration, and reliable availability for long-term client projects.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because full-time employees receive statutory paid leave entitlements.","C":"Incorrect because full-time contracts include formal notice periods and unfair dismissal protections.","D":"Incorrect because full-time annual salaries exceed half-time wages."}}},{"id":"P1_U2_MCQ_130","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_130","question":"When selecting a new Customer Care Team Leader, an HR manager reviews three equally qualified candidates' references and conducts final interviews before sending a formal written job offer. What is the final step in the recruitment and selection process?","options":{"A":"Conducting initial job analysis","B":"Issuing the contract of employment and inducting the successful candidate","C":"Publishing external newspaper advertisements","D":"Shortlisting 50 initial application forms"},"correctOption":"B","correctAnswer":"Issuing the contract of employment and inducting the successful candidate","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because after selecting the best candidate and checking references, the employer issues a formal contract of employment and begins induction.","distractor_reasons":{"A":"Incorrect because job analysis is the very first step before advertising.","B":"Correct selection.","C":"Incorrect because advertising occurs early in the recruitment stage.","D":"Incorrect because shortlisting happens prior to interviewing candidates."}}},{"id":"P1_U2_MCQ_131","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_131","question":"A precision medical-device manufacturer invests heavily in continuous technical training for its assembly operators. How does ongoing employee training improve the manufacturer's competitiveness?","options":{"A":"It allows the manufacturer to pay operators below the national minimum wage","B":"It guarantees that competitors can never develop new medical devices","C":"It reduces product defect rates, lowers material wastage, and increases output per worker","D":"It eliminates the need for any quality assurance inspections"},"correctOption":"C","correctAnswer":"It reduces product defect rates, lowers material wastage, and increases output per worker","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because well-trained workers operate machinery more accurately, make fewer costly mistakes, and achieve higher productivity.","distractor_reasons":{"A":"Incorrect because training never permits paying below statutory minimum wage rates.","B":"Incorrect because internal training improves own capability rather than stopping rival innovation.","C":"Correct selection.","D":"Incorrect because quality inspections remain essential in medical device manufacturing."}}},{"id":"P1_U2_MCQ_132","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_132","question":"A small independent hardware shop hires a new sales assistant and trains them on-the-job by having the store owner demonstrate how to operate the point-of-sale till and mix paint colors during quiet store hours. Why is on-the-job training ideal here?","options":{"A":"The store owner wants to send the assistant away to a university for six months","B":"The shop has a huge HR training budget for external residential seminars","C":"On-the-job training guarantees that the assistant learns advanced corporate finance","D":"It is low-cost, practical, and immediately teaches the exact store equipment without losing the worker off-site"},"correctOption":"D","correctAnswer":"It is low-cost, practical, and immediately teaches the exact store equipment without losing the worker off-site","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because small businesses with limited budgets benefit from inexpensive, hands-on training tailored directly to their specific tools and routines.","distractor_reasons":{"A":"Incorrect because sending staff away to university is off-the-job training.","B":"Incorrect because small shops typically have tight budgets, which is why they avoid costly external courses.","C":"Incorrect because store training focuses on till operation and paint mixing rather than corporate finance.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_133","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_133","question":"After an IT firm spends $8,000 sending a junior cybersecurity specialist on an intensive off-the-job certification course, the specialist resigns two months later to join a higher-paying competitor. Which business risk of training does this illustrate?","options":{"A":"Trained employees become more attractive to rival firms ('poaching') before the employer recovers training costs","B":"Off-the-job training courses are legally invalid unless attended on weekends","C":"Training reduces an employee's skills and makes them unemployable elsewhere","D":"Competitors are legally required to refund the $8,000 tuition fee automatically"},"correctOption":"A","correctAnswer":"Trained employees become more attractive to rival firms ('poaching') before the employer recovers training costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring valuable external qualifications increases an employee's market value, risking resignation to competitors if pay and progression do not keep pace.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because off-the-job courses routinely take place during paid working days.","C":"Incorrect because training enhances skills and employability.","D":"Incorrect because rival employers have no legal obligation to reimburse prior training costs."}}},{"id":"P1_U2_MCQ_134","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_134","question":"A commercial airline introduces self-service baggage drop kiosks at airport terminals, permanently reducing the number of check-in desk agents required. Forty check-in agents lose their jobs and receive severance packages. What caused these redundancies?","options":{"A":"Gross misconduct and repeated lateness by all forty check-in agents","B":"Automation and technological change replacing human labor tasks","C":"Natural wastage through voluntary staff retirements","D":"An increase in statutory minimum wage laws"},"correctOption":"B","correctAnswer":"Automation and technological change replacing human labor tasks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because introducing automated self-service technology eliminates the need for certain manual roles, leading to structural redundancy.","distractor_reasons":{"A":"Incorrect because misconduct leads to dismissal without severance pay, whereas here the roles disappeared due to new kiosks.","B":"Correct selection.","C":"Incorrect because natural wastage does not involve terminating staff with severance packages.","D":"Incorrect because the scenario explicitly identifies self-service kiosks as the cause."}}},{"id":"P1_U2_MCQ_135","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_135","question":"A delivery van driver repeatedly arrives two hours late for shifts despite receiving two formal written warnings and a disciplinary hearing, resulting in the company terminating their contract. Why is this termination classified as fair dismissal rather than redundancy?","options":{"A":"Because the company closed its delivery division permanently","B":"Because the driver voluntarily retired at age 65","C":"Because the job role still exists, and termination resulted from the employee's persistent poor conduct after proper warnings","D":"Because delivery drivers are not protected by employment contracts"},"correctOption":"C","correctAnswer":"Because the job role still exists, and termination resulted from the employee's persistent poor conduct after proper warnings","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fair dismissal occurs when an employer follows proper disciplinary warnings and terminates a worker for unsatisfactory conduct or capability while the job remains needed.","distractor_reasons":{"A":"Incorrect because closing a division causes redundancy, not dismissal.","B":"Incorrect because retirement is voluntary exit rather than disciplinary termination.","C":"Correct selection.","D":"Incorrect because delivery drivers are protected by employment law and contracts."}}},{"id":"P1_U2_MCQ_136","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_136","question":"A marketing agency dismisses an account manager immediately after she informs HR that she is pregnant, claiming she will be 'less available for evening client dinners.' Which employment law protection has the agency violated?","options":{"A":"Health and safety machinery guarding regulations","B":"Statutory minimum wage hourly pay rules","C":"Trade union collective bargaining procedures","D":"Protection against unfair dismissal and gender/pregnancy discrimination"},"correctOption":"D","correctAnswer":"Protection against unfair dismissal and gender/pregnancy discrimination","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dismissing an employee due to pregnancy is automatically unlawful discrimination and unfair dismissal under employment protection legislation.","distractor_reasons":{"A":"Incorrect because machinery guarding relates to physical factory safety.","B":"Incorrect because minimum wage laws regulate pay rates rather than pregnancy dismissal.","C":"Incorrect because the violation concerns pregnancy discrimination rather than union bargaining.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_137","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_137","question":"A customer call center employed an average of 250 agents during the year. Over the 12 months, 55 agents left the company and had to be replaced. What was the call center's annual labor turnover rate?","options":{"A":"22%","B":"55%","C":"4.5%","D":"78%"},"correctOption":"A","correctAnswer":"22%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labor turnover rate = (number of leavers / average workforce) × 100 = (55 / 250) × 100 = 22%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 55 is the raw headcount of leavers, not the percentage rate.","C":"Incorrect because 4.5% divides 250 by 55 (250 / 55 = 4.55).","D":"Incorrect because 78% is the staff retention rate (100% - 22%)."}}},{"id":"P1_U2_MCQ_138","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_138","question":"Following a sharp rise in annual labor turnover from 10% to 32%, a retail warehouse incurs $95,000 in extra expenses. Which operational costs directly increase when labor turnover is high?","options":{"A":"Annual dividend payments to external shareholders","B":"Recruitment advertising, interviewing time, induction training, and lower initial productivity from new hires","C":"Property rent and municipal business rates on existing buildings","D":"Raw material purchase prices from international suppliers"},"correctOption":"B","correctAnswer":"Recruitment advertising, interviewing time, induction training, and lower initial productivity from new hires","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high staff turnover forces repeated spending on job adverts, selection interviews, onboarding training, and lost output while new starters learn the job.","distractor_reasons":{"A":"Incorrect because shareholder dividends are discretionary profit distributions rather than HR turnover costs.","B":"Correct selection.","C":"Incorrect because building rent is a fixed overhead unrelated to staff turnover.","D":"Incorrect because supplier material prices are unaffected by warehouse staff resignations."}}},{"id":"P1_U2_MCQ_139","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_139","question":"Under national employment law, every new employee must receive a written statement of employment particulars detailing pay, hours, holiday entitlement, and notice periods. How does this legal requirement benefit employers as well as employees?","options":{"A":"It allows employers to change agreed salaries downward at any time without consent","B":"It guarantees that employees can never resign from the company","C":"It prevents misunderstandings and costly legal disputes by clearly defining mutual duties and terms from day one","D":"It exempts employers from complying with workplace health and safety standards"},"correctOption":"C","correctAnswer":"It prevents misunderstandings and costly legal disputes by clearly defining mutual duties and terms from day one","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a clear written contract establishes unambiguous expectations regarding duties, hours, and notice periods, protecting both parties in disputes.","distractor_reasons":{"A":"Incorrect because binding contracts prevent unilateral pay cuts without employee agreement.","B":"Incorrect because employees can still resign by giving their contractual notice period.","C":"Correct selection.","D":"Incorrect because health and safety laws remain strictly enforceable."}}},{"id":"P1_U2_MCQ_140","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_140","question":"An advertising agency rejects a highly qualified 58-year-old copywriter solely because managers want 'a younger, under-30 creative team image.' Which legal control over employment is violated by this hiring decision?","options":{"A":"Statutory minimum wage legislation","B":"Health and safety fire-exit regulations","C":"Redundancy severance calculation rules","D":"Anti-discrimination (equal opportunity) legislation"},"correctOption":"D","correctAnswer":"Anti-discrimination (equal opportunity) legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because equal opportunity laws prohibit age discrimination during recruitment, promotion, and dismissal.","distractor_reasons":{"A":"Incorrect because minimum wage laws govern pay floors rather than age bias.","B":"Incorrect because fire-exit regulations are physical safety laws.","C":"Incorrect because the candidate was rejected at hiring rather than made redundant.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_141","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_141","question":"At a regional hospital, the Pharmacy Department notifies the Surgical Ward that a specific anesthetic batch is temporarily out of stock and confirms an approved clinical substitute. Which type of internal communication is taking place?","options":{"A":"Horizontal (lateral) communication between two departments at the same organizational level","B":"External public relations communication to newspaper journalists","C":"Downward communication from the Chief Executive to junior porters","D":"Informal canteen gossip between external visitors"},"correctOption":"A","correctAnswer":"Horizontal (lateral) communication between two departments at the same organizational level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because horizontal communication occurs between peers or different functional departments at the same level of hierarchy to coordinate operations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both departments belong to the same internal hospital organization.","C":"Incorrect because downward communication flows vertically from senior managers to subordinates.","D":"Incorrect because an official clinical stock notification is a formal operational communication."}}},{"id":"P1_U2_MCQ_142","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_142","question":"A food manufacturer discovers a packaging labeling error on a batch of nut-free granola bars and immediately issues an urgent recall notice across national news outlets, supermarkets, and its social media channels. Why is rapid external communication vital here?","options":{"A":"It lowers the factory's monthly electricity expenses","B":"It protects consumer health, fulfills legal safety duties, and preserves long-term brand trust","C":"It eliminates the need to retrain factory packaging operators","D":"It allows the company to increase granola retail prices immediately"},"correctOption":"B","correctAnswer":"It protects consumer health, fulfills legal safety duties, and preserves long-term brand trust","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because swift, transparent external communication during a product recall prevents harm to customers, avoids regulatory penalties, and demonstrates corporate responsibility.","distractor_reasons":{"A":"Incorrect because recall notices do not reduce utility costs.","B":"Correct selection.","C":"Incorrect because internal operator retraining is still needed to prevent future errors.","D":"Incorrect because recalls address safety compliance rather than raising prices."}}},{"id":"P1_U2_MCQ_143","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_143","question":"A retail bank introduces an internal instant-messaging platform so branch advisors can ask quick policy questions to head-office underwriters while a customer is waiting at the desk. What is a primary benefit of this electronic communication tool?","options":{"A":"It guarantees that complex legal contracts never need formal signatures","B":"It works without any internet or network connection","C":"It enables rapid, real-time two-way responses that speed up customer service","D":"It eliminates all risk of confidential customer data being mistyped"},"correctOption":"C","correctAnswer":"It enables rapid, real-time two-way responses that speed up customer service","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal instant messaging provides immediate two-way answers, reducing customer waiting times and improving operational efficiency.","distractor_reasons":{"A":"Incorrect because formal legal agreements still require proper execution.","B":"Incorrect because electronic messaging depends on active network connectivity.","C":"Correct selection.","D":"Incorrect because fast typing still carries human error risks."}}},{"id":"P1_U2_MCQ_144","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_144","question":"An automotive assembly plant installs large digital overhead display boards on the factory floor showing real-time hourly production targets, actual units completed, and defect counts in green and red indicators. Why is this visual communication method effective?","options":{"A":"It replaces the need for assembly workers to receive any safety gear","B":"It provides detailed written legal contracts for every factory worker","C":"It allows workers to hold lengthy verbal debates while operating machinery","D":"Workers can grasp performance status at a single glance without stopping work to read long reports"},"correctOption":"D","correctAnswer":"Workers can grasp performance status at a single glance without stopping work to read long reports","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because color-coded visual dashboards communicate essential operational metrics instantly without interrupting workflow.","distractor_reasons":{"A":"Incorrect because visual boards do not replace physical protective equipment.","B":"Incorrect because display boards show operational metrics rather than employment contracts.","C":"Incorrect because visual boards convey status silently without stopping work for discussions.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_145","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_145","question":"A software company relies heavily on informal communication ('the grapevine') among staff rather than holding regular all-hands updates from senior leadership. What is a major risk of letting the grapevine dominate internal communication?","options":{"A":"Inaccurate rumors and anxiety can spread rapidly, damaging staff morale and productivity","B":"Employees will receive overly detailed, verified financial statements too early","C":"Formal written policies will be stored too securely on company servers","D":"Senior managers will spend too much time listening to staff concerns"},"correctOption":"A","correctAnswer":"Inaccurate rumors and anxiety can spread rapidly, damaging staff morale and productivity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when formal management communication is absent, the informal grapevine fills the vacuum with distorted rumors that lower morale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the grapevine spreads unverified speculation rather than accurate financial reports.","C":"Incorrect because informal gossip is verbal/unrecorded rather than stored securely.","D":"Incorrect because relying on rumors reflects a lack of structured management communication."}}},{"id":"P1_U2_MCQ_146","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_146","question":"A UK-based fashion buyer emails an urgent supplier order to a factory manager in New York at 4:30 PM London time expecting an immediate reply, forgetting that New York is five hours behind and staff are on lunch break. Which barrier to communication delayed the response?","options":{"A":"Excessive use of technical garment-sewing jargon","B":"Geographical distance and international time-zone differences","C":"Hostile industrial strike action by delivery drivers","D":"Lack of written email records"},"correctOption":"B","correctAnswer":"Geographical distance and international time-zone differences","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because operating across distant geographical locations and different time zones delays real-time feedback and coordination.","distractor_reasons":{"A":"Incorrect because the delay resulted from time-zone misalignment rather than unclear vocabulary.","B":"Correct selection.","C":"Incorrect because no strike occurred in the scenario.","D":"Incorrect because an email was sent, creating a written record."}}},{"id":"P1_U2_MCQ_147","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_147","question":"A newly hired Customer Relations Manager notices that angry customers frequently misunderstand terse, one-line email replies sent by support agents. How can the manager best overcome this communication barrier?","options":{"A":"Ban support agents from ever communicating with customers in writing","B":"Add complex legal disclaimers and technical jargon to every email","C":"Train agents to write polite, clear, empathetic responses and use phone calls for sensitive complaints","D":"Increase the chain of command so five managers must approve every email reply"},"correctOption":"C","correctAnswer":"Train agents to write polite, clear, empathetic responses and use phone calls for sensitive complaints","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because adapting message tone and selecting a richer verbal channel (telephone) for emotional complaints prevents misinterpretation and builds customer rapport.","distractor_reasons":{"A":"Incorrect because written emails remain useful for confirming details and records.","B":"Incorrect because adding jargon worsens customer confusion.","C":"Correct selection.","D":"Incorrect because adding approval layers slows down customer response times."}}},{"id":"P1_U2_MCQ_148","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_148","question":"Before sending an important policy announcement about revised remote-working rules to 800 employees, an HR Director asks two department representatives to review the draft memo for clarity. Why is this step effective?","options":{"A":"It converts a written policy into an unrecorded informal rumor","B":"It lengthens the chain of command permanently","C":"It eliminates the need to distribute the memo to remote employees","D":"It identifies ambiguous wording before mass distribution, ensuring the message is clear to receivers"},"correctOption":"D","correctAnswer":"It identifies ambiguous wording before mass distribution, ensuring the message is clear to receivers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because pre-testing a message with representative receivers uncovers confusing phrasing and prevents widespread misunderstanding.","distractor_reasons":{"A":"Incorrect because reviewing a draft improves a formal written policy rather than turning it into gossip.","B":"Incorrect because pre-reviewing does not alter the organizational hierarchy.","C":"Incorrect because all 800 employees still receive the finalized memo.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_149","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_149","question":"A corporate bank experiences a temporary outage of its internal email and intranet servers due to a power surge, halting coordination between head office and 60 regional branches. Which drawback of electronic communication does this highlight?","options":{"A":"Over-reliance on IT infrastructure makes communication vulnerable to technical breakdowns and power failures","B":"Electronic messages are always slower to deliver than postal letters","C":"Intranet systems cannot store written policy manuals","D":"Electronic communication is illegal for multi-branch banks"},"correctOption":"A","correctAnswer":"Over-reliance on IT infrastructure makes communication vulnerable to technical breakdowns and power failures","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because electronic channels depend on electricity, hardware, and network stability; outages can paralyze business operations if no backup exists.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because electronic messages are normally instantaneous compared to postal mail.","C":"Incorrect because intranets are widely used to store policy manuals.","D":"Incorrect because banks routinely use secure electronic networks."}}},{"id":"P1_U2_MCQ_150","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_150","question":"To ensure every employee understands the four essential elements of effective communication, an HR trainer reminds supervisors to check the sender, message, medium, and receiver. Which element is missing if a supervisor sends an email but never checks whether the employee received or understood it?","options":{"A":"Selection of an electronic medium","B":"Feedback from the receiver to the sender","C":"Encoding of the initial text","D":"Formal downward transmission"},"correctOption":"B","correctAnswer":"Feedback from the receiver to the sender","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because feedback closes the communication loop by confirming that the receiver received, decoded, and understood the message as intended.","distractor_reasons":{"A":"Incorrect because email was already chosen as the medium.","B":"Correct selection.","C":"Incorrect because the supervisor already wrote (encoded) the email.","D":"Incorrect because sending the email from supervisor to employee already represents downward transmission."}}},{"id":"P1_U2_MCQ_151","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_151","question":"An engineering firm distributes 10% of annual net profit equally among permanent staff at year-end. What is a limitation of profit-sharing as an individual motivator?","options":{"A":"Staff feel their daily effort barely affects total profit, and rewards are delayed until year-end","B":"Employees receive guaranteed monthly bonuses even during a loss","C":"Profit-sharing eliminates the need to pay monthly salaries","D":"Junior engineers gain shareholder voting control"},"correctOption":"A","correctAnswer":"Staff feel their daily effort barely affects total profit, and rewards are delayed until year-end","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because group profit-sharing weakens the link between individual effort and reward, and annual payouts are delayed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because payouts occur only when the firm makes a profit.","C":"Incorrect because profit-sharing supplements basic salaries.","D":"Incorrect because cash bonuses do not grant voting shares."}}},{"id":"P1_U2_MCQ_152","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_152","question":"A logistics firm moves casual workers onto permanent contracts with pension plans and upgraded safety barriers. According to Maslow's hierarchy, which need is primarily met?","options":{"A":"Self-actualization needs","B":"Safety and security needs","C":"Esteem and status needs","D":"Social belonging needs"},"correctOption":"B","correctAnswer":"Safety and security needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because permanent job security, pensions, and physical protection satisfy safety and security needs.","distractor_reasons":{"A":"Incorrect because self-actualization involves creative fulfillment.","B":"Correct selection.","C":"Incorrect because esteem needs relate to recognition and status.","D":"Incorrect because social needs concern workplace friendships."}}},{"id":"P1_U2_MCQ_153","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_153","question":"A telecom firm simplifies bureaucratic expense rules and trains supervisors to treat staff respectfully, stopping complaints without raising sales effort. How does Herzberg's theory explain this?","options":{"A":"Company policies and supervision are motivators that double output","B":"Employees work harder only when all rules are abolished","C":"Company policies and supervision are hygiene factors that prevent dissatisfaction without motivating","D":"Sales staff have reached physiological survival limits"},"correctOption":"C","correctAnswer":"Company policies and supervision are hygiene factors that prevent dissatisfaction without motivating","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg classifies policies and supervision as hygiene factors that remove dissatisfaction rather than acting as motivators.","distractor_reasons":{"A":"Incorrect because hygiene factors differ from true motivators like achievement.","B":"Incorrect because fair policies prevent dissatisfaction without removing structure.","C":"Correct selection.","D":"Incorrect because physiological survival is a Maslow concept."}}},{"id":"P1_U2_MCQ_154","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_154","question":"A technician earns $12.00 per hour for a 40-hour week, plus 1.5 times basic pay for overtime. If they work 46 hours in one week, what is their gross weekly pay?","options":{"A":"$552.00","B":"$828.00","C":"$516.00","D":"$588.00"},"correctOption":"D","correctAnswer":"$588.00","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because basic pay = 40 × $12 = $480, overtime = 6 × $18 = $108, and total = $588.00.","distractor_reasons":{"A":"Incorrect because $552.00 omits the 1.5x overtime premium.","B":"Incorrect because $828.00 multiplies all 46 hours by $18.","C":"Incorrect because $516.00 adds $36 instead of $108 for overtime.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_155","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_155","question":"An automotive seat maker rotates assembly workers every two hours between foam molding, leather stitching, and frame bolting. How does job rotation benefit the firm?","options":{"A":"It reduces task monotony and builds a multi-skilled workforce able to cover absences","B":"It gives assembly workers authority to set vehicle prices","C":"It eliminates the need to maintain factory machinery","D":"It permanently reduces every worker's hourly wage"},"correctOption":"A","correctAnswer":"It reduces task monotony and builds a multi-skilled workforce able to cover absences","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job rotation relieves boredom and ensures multiple workers can cover each stage during absences.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rotating peer-level tasks does not grant pricing authority.","C":"Incorrect because equipment maintenance remains necessary.","D":"Incorrect because job rotation does not reduce hourly wages."}}},{"id":"P1_U2_MCQ_156","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_156","question":"An electronics firm organizes workers into self-managing teams of eight responsible for assembling, testing, and packaging complete circuit boards. How does teamworking improve motivation?","options":{"A":"It removes all performance targets and quality checks","B":"It fulfills social belonging needs while giving teams shared responsibility for a complete output","C":"It forces every worker to work alone without speaking","D":"It guarantees no employee ever needs technical training"},"correctOption":"B","correctAnswer":"It fulfills social belonging needs while giving teams shared responsibility for a complete output","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because teamworking satisfies social needs and enriches work through collective product ownership.","distractor_reasons":{"A":"Incorrect because teams remain accountable for quality and output targets.","B":"Correct selection.","C":"Incorrect because teamworking relies on collaboration.","D":"Incorrect because team members still require cross-training."}}},{"id":"P1_U2_MCQ_157","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_157","question":"A sales representative earns a $1,200 monthly base salary plus 5% commission on sales. In a month with $18,000 in sales, what are their gross monthly earnings?","options":{"A":"$900","B":"$1,290","C":"$2,100","D":"$3,000"},"correctOption":"C","correctAnswer":"$2,100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because commission = 5% of $18,000 = $900, plus $1,200 base salary = $2,100.","distractor_reasons":{"A":"Incorrect because $900 omits the $1,200 base salary.","B":"Incorrect because $1,290 calculates 0.5% ($90) instead of 5%.","C":"Correct selection.","D":"Incorrect because $3,000 calculates 10% commission instead of 5%."}}},{"id":"P1_U2_MCQ_158","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_158","question":"An urban textile factory raises entry-level wages so workers can afford basic rent, food, and commuting costs. Which level of Maslow's hierarchy is addressed first?","options":{"A":"Esteem needs","B":"Self-actualization needs","C":"Social needs","D":"Physiological needs"},"correctOption":"D","correctAnswer":"Physiological needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because physiological needs form the base of Maslow's pyramid and require income for food and shelter.","distractor_reasons":{"A":"Incorrect because esteem needs involve recognition after basic needs are met.","B":"Incorrect because self-actualization sits at the top of the pyramid.","C":"Incorrect because social needs relate to group belonging.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_159","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_159","question":"During a bonus freeze, a hospital manager writes thank-you notes and praises nurses' care in weekly briefings. Why is this non-financial approach effective?","options":{"A":"Genuine praise fulfills esteem needs and boosts morale without raising payroll costs","B":"Thank-you notes exempt nurses from paying income taxes","C":"Recognition eliminates the need to pay basic salaries","D":"Praise converts nurses into self-employed consultants"},"correctOption":"A","correctAnswer":"Genuine praise fulfills esteem needs and boosts morale without raising payroll costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recognition satisfies esteem needs (Maslow) and acts as a motivator (Herzberg) at minimal cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because praise does not affect income taxes.","C":"Incorrect because basic salaries remain essential.","D":"Incorrect because recognition does not alter employment status."}}},{"id":"P1_U2_MCQ_160","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_160","question":"A video-game studio applies F.W. Taylor's scientific management by paying concept artists a piece rate per sketch drawn. Why is Taylor's approach poorly suited here?","options":{"A":"Concept artists dislike earning money","B":"Creative originality cannot be measured accurately by counting units per hour","C":"Piece-rate pay is illegal in digital entertainment","D":"Taylor's theory forbids reviewing employee work"},"correctOption":"B","correctAnswer":"Creative originality cannot be measured accurately by counting units per hour","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Taylorism suits standardized, repetitive physical tasks, whereas creative work requires quality and originality.","distractor_reasons":{"A":"Incorrect because piece rates simply encourage rushed, low-quality sketches.","B":"Correct selection.","C":"Incorrect because piece-rate pay is legal though unsuitable here.","D":"Incorrect because Taylorism emphasized close supervision."}}},{"id":"P1_U2_MCQ_161","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_161","question":"A conglomerate operates with eleven tiers of management between the CEO and shop-floor staff. What operational problem does this long chain of command cause?","options":{"A":"Senior executives have too few managers reporting to them","B":"Decisions are made too rapidly before supervisors check facts","C":"Messages passing through many layers become distorted and decisions are delayed","D":"Shop-floor staff have wide spans of control over directors"},"correctOption":"C","correctAnswer":"Messages passing through many layers become distorted and decisions are delayed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tall hierarchies with long chains of command slow decision-making and increase message distortion.","distractor_reasons":{"A":"Incorrect because tall hierarchies feature narrow spans of control.","B":"Incorrect because long chains slow decisions down.","C":"Correct selection.","D":"Incorrect because technicians do not supervise directors."}}},{"id":"P1_U2_MCQ_162","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_162","question":"To cut overheads and speed up communication, an insurer removes two layers of middle management (delayering). What is a likely consequence?","options":{"A":"The chain of command becomes much longer","B":"Annual middle-management salary costs rise sharply","C":"Frontline staff lose all opportunities for delegation","D":"Remaining managers face wider spans of control, heavier workloads, and fewer promotion steps"},"correctOption":"D","correctAnswer":"Remaining managers face wider spans of control, heavier workloads, and fewer promotion steps","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delayering widens spans of control, increases remaining managers' workloads, and reduces promotion rungs.","distractor_reasons":{"A":"Incorrect because removing layers shortens the chain of command.","B":"Incorrect because eliminating management tiers reduces salary overheads.","C":"Incorrect because flatter structures increase frontline delegation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_163","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_163","question":"At a chemical plant, the Legal Compliance Officer advises the Production Manager on waste laws but cannot discipline factory operators. Which role is this?","options":{"A":"Staff manager providing specialist advisory support to line managers","B":"Direct line supervisor controlling assembly shift rotas","C":"External trade union shop steward","D":"Chief Executive Officer with ultimate board authority"},"correctOption":"A","correctAnswer":"Staff manager providing specialist advisory support to line managers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because staff managers (HR, Legal, IT) advise line managers rather than commanding production workers directly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because line managers hold direct authority over subordinates.","C":"Incorrect because the Legal Officer is an internal specialist manager.","D":"Incorrect because the CEO holds overarching executive authority."}}},{"id":"P1_U2_MCQ_164","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_164","question":"Before selecting a new cloud system, a Chief Technology Officer holds workshops with engineers and uses their proposals in the final choice. Which leadership style is this?","options":{"A":"Autocratic leadership","B":"Democratic leadership","C":"Paternalistic dictatorial leadership","D":"Coercive micromanagement"},"correctOption":"B","correctAnswer":"Democratic leadership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because democratic leaders consult skilled employees and value two-way input before deciding.","distractor_reasons":{"A":"Incorrect because autocratic leaders issue orders without consulting staff.","B":"Correct selection.","C":"Incorrect because paternalistic leaders decide unilaterally.","D":"Incorrect because micromanagement dictates minor tasks."}}},{"id":"P1_U2_MCQ_165","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_165","question":"When a high-pressure steam pipe ruptures in a food factory, the Safety Supervisor issues rapid evacuation orders. Why is autocratic leadership appropriate here?","options":{"A":"Holding a committee vote would improve morale during the leak","B":"Workers prefer laissez-faire independence during hazardous leaks","C":"Life-threatening emergencies require instant, decisive direction with zero delay","D":"Autocratic leadership is legally mandatory for every office task"},"correctOption":"C","correctAnswer":"Life-threatening emergencies require instant, decisive direction with zero delay","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because urgent safety crises leave no time for debate and demand clear, immediate top-down commands.","distractor_reasons":{"A":"Incorrect because debating options during an emergency endangers lives.","B":"Incorrect because lack of direction during a crisis causes panic.","C":"Correct selection.","D":"Incorrect because leadership style should adapt to the task."}}},{"id":"P1_U2_MCQ_166","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_166","question":"Over 4,000 flight attendants belong to a union that negotiates pay scales and rest rules jointly with airline executives. What is this joint negotiation called?","options":{"A":"Individual performance appraisal","B":"External headhunting","C":"Horizontal job enlargement","D":"Collective bargaining"},"correctOption":"D","correctAnswer":"Collective bargaining","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because collective bargaining occurs when union representatives negotiate pay and conditions on behalf of workers.","distractor_reasons":{"A":"Incorrect because appraisals review an individual worker's performance.","B":"Incorrect because headhunting recruits senior external managers.","C":"Incorrect because job enlargement adds peer-level tasks.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_167","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_167","question":"During a contract dispute, postal workers follow every handbook rule strictly and refuse unpaid flexibility, slowing deliveries without breaching contracts. Which action is this?","options":{"A":"Work-to-rule","B":"All-out walkout strike","C":"Employer lockout","D":"Voluntary redundancy"},"correctOption":"A","correctAnswer":"Work-to-rule","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because work-to-rule slows productivity by strictly obeying every rule while keeping full basic pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an all-out strike stops work entirely and forfeits wages.","C":"Incorrect because a lockout is imposed by management closing the workplace.","D":"Incorrect because redundancy is permanent job elimination."}}},{"id":"P1_U2_MCQ_168","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_168","question":"At quarter-end, a Retail Director reviews store profit reports, identifies three branches 15% below sales targets, and starts coaching to fix the gap. Which management function is this?","options":{"A":"Initial forecasting and planning","B":"Controlling","C":"External recruitment advertising","D":"Delayering"},"correctOption":"B","correctAnswer":"Controlling","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because controlling involves measuring actual performance against targets and taking corrective action.","distractor_reasons":{"A":"Incorrect because planning sets targets before operations begin.","B":"Correct selection.","C":"Incorrect because external advertising attracts job candidates.","D":"Incorrect because delayering removes hierarchy levels."}}},{"id":"P1_U2_MCQ_169","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_169","question":"In a retail hierarchy, 1 Director manages 5 Area Managers; each Area Manager supervises 4 Store Managers; each Store Manager supervises 12 Assistants. How many employees work here?","options":{"A":"240","B":"260","C":"266","D":"22"},"correctOption":"C","correctAnswer":"266","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total staff = 1 Director + 5 Area + (5 × 4 = 20 Store) + (20 × 12 = 240 Assistants) = 266.","distractor_reasons":{"A":"Incorrect because 240 counts only Sales Assistants.","B":"Incorrect because 260 omits the Director and 5 Area Managers.","C":"Correct selection.","D":"Incorrect because 22 adds 1 + 5 + 4 + 12."}}},{"id":"P1_U2_MCQ_170","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_170","question":"When a Marketing Director delegates authority to a Brand Manager to approve ad spending up to $5,000, which condition is essential for delegation to succeed?","options":{"A":"The Marketing Director must withhold all budget figures","B":"The Brand Manager must receive zero clear objectives","C":"The Marketing Director must overturn every minor decision","D":"The Brand Manager must receive clear goals and authority while the Director retains overall accountability"},"correctOption":"D","correctAnswer":"The Brand Manager must receive clear goals and authority while the Director retains overall accountability","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because effective delegation matches responsibility with authority and clear goals without abdicating accountability.","distractor_reasons":{"A":"Incorrect because withholding budget info prevents informed decisions.","B":"Incorrect because delegated tasks require clear objectives.","C":"Incorrect because constant interference undermines delegation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_171","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_171","question":"A logistics company prepares a Job Description for a Warehouse Coordinator vacancy. How does this document help potential applicants?","options":{"A":"It outlines main duties, hours, location, and reporting lines so applicants can assess suitability","B":"It lists private medical records of current warehouse staff","C":"It serves as a signed employment contract confirming hiring","D":"It ranks all shortlisted candidates by interview score"},"correctOption":"A","correctAnswer":"It outlines main duties, hours, location, and reporting lines so applicants can assess suitability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a job description explains what the role entails, helping filter out unsuitable applicants early.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employee medical records are confidential.","C":"Incorrect because a formal contract—not a job description—confirms hiring.","D":"Incorrect because candidate scoring occurs later during selection."}}},{"id":"P1_U2_MCQ_172","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_172","question":"A Person Specification lists 'Spanish fluency' as essential and 'CRM software experience' as desirable. How does this distinction help selectors?","options":{"A":"Selectors can ignore language fluency if an applicant lives nearby","B":"Selectors can reject applicants lacking essential traits while using desirable traits to separate strong contenders","C":"It replaces the need to verify candidates' language skills","D":"It legally forces hiring every candidate meeting desirable criteria"},"correctOption":"B","correctAnswer":"Selectors can reject applicants lacking essential traits while using desirable traits to separate strong contenders","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because separating essential from desirable attributes provides an objective shortlisting benchmark.","distractor_reasons":{"A":"Incorrect because essential criteria are mandatory requirements.","B":"Correct selection.","C":"Incorrect because claimed skills must still be verified.","D":"Incorrect because employers select only the best candidate(s)."}}},{"id":"P1_U2_MCQ_173","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_173","question":"A supermarket chain advertises a Store Section Leader role exclusively on its internal staff portal. What is a primary advantage of internal recruitment?","options":{"A":"It attracts hundreds of external applicants from rival chains","B":"It brings completely new outside management practices into the firm","C":"Advertising costs are minimal and candidates' work ethic and reliability are already known","D":"It guarantees no other store role becomes vacant after promotion"},"correctOption":"C","correctAnswer":"Advertising costs are minimal and candidates' work ethic and reliability are already known","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal recruitment avoids external advertising fees and relies on proven internal performance records.","distractor_reasons":{"A":"Incorrect because internal adverts are visible only to existing staff.","B":"Incorrect because fresh outside ideas come from external recruitment.","C":"Correct selection.","D":"Incorrect because promoting an existing worker leaves their old post vacant."}}},{"id":"P1_U2_MCQ_174","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_174","question":"A new neighborhood grocery store needs eight part-time cashiers living within commuting distance. Where is the most cost-effective place to advertise?","options":{"A":"An international aerospace engineering journal","B":"A national financial broadsheet read by bankers","C":"An overseas executive headhunting agency","D":"A local community newspaper, store window poster, and local job center"},"correctOption":"D","correctAnswer":"A local community newspaper, store window poster, and local job center","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local media and window notices target nearby residents seeking retail work at minimal expense.","distractor_reasons":{"A":"Incorrect because specialist journals reach niche technical professionals.","B":"Incorrect because national financial papers are expensive and target executives.","C":"Incorrect because headhunters are used for senior executive searches.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_175","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_175","question":"After receiving 140 applications for two Junior Accountant roles, HR compares CVs against the person specification to pick eight candidates for interview. What is this stage called?","options":{"A":"Shortlisting","B":"Induction onboarding","C":"Job analysis","D":"Redundancy consultation"},"correctOption":"A","correctAnswer":"Shortlisting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shortlisting narrows a large pool of applicants down to the strongest candidates for interviews.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because induction occurs after a job offer is accepted.","C":"Incorrect because job analysis happens before advertising.","D":"Incorrect because redundancy consultation deals with surplus roles."}}},{"id":"P1_U2_MCQ_176","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_176","question":"A commercial bank requires shortlisted Risk Analyst applicants to complete numerical reasoning and personality tests. What is the purpose of these psychometric tests?","options":{"A":"To check whether applicants hold a truck driving license","B":"To objectively assess analytical aptitude and behavioral traits suited to high-pressure financial roles","C":"To replace the need for a written contract of employment","D":"To teach new hires how to use fire extinguishers"},"correctOption":"B","correctAnswer":"To objectively assess analytical aptitude and behavioral traits suited to high-pressure financial roles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because aptitude and psychometric tests evaluate cognitive ability and personality fit beyond a CV.","distractor_reasons":{"A":"Incorrect because licenses are checked via document verification.","B":"Correct selection.","C":"Incorrect because successful candidates still receive formal contracts.","D":"Incorrect because fire safety belongs to post-hire induction."}}},{"id":"P1_U2_MCQ_177","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_177","question":"During selection for a Pastry Chef vacancy, a hotel asks shortlisted candidates to prepare two desserts in 90 minutes. Why is this practical test valuable?","options":{"A":"It provides free desserts without paying kitchen staff","B":"It eliminates the need to check food hygiene certificates","C":"It directly demonstrates candidates' real technical skill, speed, and hygiene habits under kitchen conditions","D":"It is faster and cheaper than reading an application form"},"correctOption":"C","correctAnswer":"It directly demonstrates candidates' real technical skill, speed, and hygiene habits under kitchen conditions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because practical tests verify hands-on competence rather than relying solely on interview claims.","distractor_reasons":{"A":"Incorrect because practical tests evaluate candidates rather than exploiting labor.","B":"Incorrect because legal hygiene certificates must still be verified.","C":"Correct selection.","D":"Incorrect because practical tests incur ingredient and supervision costs."}}},{"id":"P1_U2_MCQ_178","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_178","question":"A restaurant manager conducts informal, unstructured interviews asking each applicant different casual questions. What is a major drawback of unstructured interviews?","options":{"A":"Candidates are forced to complete standardized numerical tests","B":"Every candidate is scored against identical objective criteria","C":"Unstructured interviews take weeks per candidate to design","D":"High risk of personal interviewer bias and difficulty comparing candidates fairly"},"correctOption":"D","correctAnswer":"High risk of personal interviewer bias and difficulty comparing candidates fairly","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because without consistent questions and scoring rubrics, interviewers can be swayed by personal favoritism.","distractor_reasons":{"A":"Incorrect because aptitude tests are structured selection tools.","B":"Incorrect because objective scoring belongs to structured interviews.","C":"Incorrect because unstructured interviews lack advance preparation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_179","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_179","question":"A fast-food chain employs part-time staff working flexible 15-hour weekly schedules. How does employing part-time staff benefit the chain?","options":{"A":"Management can schedule extra staff during busy meal peaks while keeping wage costs low in quiet periods","B":"Part-time workers are excluded from statutory minimum wage laws","C":"The restaurant never needs to provide food safety training","D":"Part-time workers always show higher commitment than full-time managers"},"correctOption":"A","correctAnswer":"Management can schedule extra staff during busy meal peaks while keeping wage costs low in quiet periods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because part-time contracts allow businesses to match staffing closely to fluctuating customer demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws cover part-time and full-time staff equally.","C":"Incorrect because food hygiene training is mandatory for all staff.","D":"Incorrect because part-time staff often have higher turnover."}}},{"id":"P1_U2_MCQ_180","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_180","question":"A commercial law firm prefers hiring full-time paralegals for complex litigation cases. What is a primary advantage of employing full-time staff?","options":{"A":"Full-time staff do not receive paid annual holidays","B":"Stronger commitment, consistent availability for deadlines, and lower training cost per hour worked","C":"The firm can cut full-time salaries whenever cases are quiet","D":"Full-time staff can be dismissed without notice for any reason"},"correctOption":"B","correctAnswer":"Stronger commitment, consistent availability for deadlines, and lower training cost per hour worked","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because full-time staff work more weekly hours (spreading training costs) and provide reliable continuity.","distractor_reasons":{"A":"Incorrect because full-time staff receive statutory paid holidays.","B":"Correct selection.","C":"Incorrect because fixed salaries remain payable regardless of caseload.","D":"Incorrect because full-time contracts carry statutory notice protections."}}},{"id":"P1_U2_MCQ_181","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_181","question":"On day one at a hospital, a newly hired nurse tours the ward, meets colleagues, reviews fire exits, and learns privacy rules. Which type of training is this?","options":{"A":"Off-the-job university degree sponsorship","B":"Redundancy retraining","C":"Induction training","D":"External executive coaching"},"correctOption":"C","correctAnswer":"Induction training","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because induction training introduces new hires to their workplace, colleagues, safety rules, and procedures.","distractor_reasons":{"A":"Incorrect because university sponsorship is long-term external academic study.","B":"Incorrect because redundancy retraining assists departing workers.","C":"Correct selection.","D":"Incorrect because executive coaching targets senior leaders."}}},{"id":"P1_U2_MCQ_182","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_182","question":"A commercial bakery trains an apprentice inside its kitchen by pairing them with the Head Baker during production. What is a primary advantage of on-the-job training?","options":{"A":"The apprentice never touches real ovens until training ends","B":"The bakery pays high external college tuition fees","C":"The Head Baker's personal output speeds up while instructing","D":"Training is low-cost, tailored to exact equipment, and the trainee produces sellable goods while learning"},"correctOption":"D","correctAnswer":"Training is low-cost, tailored to exact equipment, and the trainee produces sellable goods while learning","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job training avoids external fees, uses real equipment, and generates productive output.","distractor_reasons":{"A":"Incorrect because trainees work directly on real company equipment.","B":"Incorrect because tuition fees apply to off-the-job training.","C":"Incorrect because trainers temporarily slow slightly while instructing.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_183","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_183","question":"An engineering firm sends twelve junior engineers to a two-week external seminar on bridge-modeling software. What is a disadvantage of off-the-job training?","options":{"A":"High course and travel costs plus lost billable output while engineers are away from work","B":"Engineers learn bad habits from untrained warehouse clerks","C":"External courses cannot teach specialist technical concepts","D":"Off-the-job training is illegal for engineering firms"},"correctOption":"A","correctAnswer":"High course and travel costs plus lost billable output while engineers are away from work","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because off-the-job training incurs tuition and travel fees and removes staff from productive duties.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because copying bad habits is an on-the-job training risk.","C":"Incorrect because teaching specialist skills is a strength of off-the-job training.","D":"Incorrect because external professional training is standard and legal."}}},{"id":"P1_U2_MCQ_184","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_184","question":"Beyond raising employer productivity, how does structured skills training directly benefit individual employees?","options":{"A":"It guarantees employees never follow safety rules","B":"It boosts confidence, reduces accidents, and improves promotion and earning prospects","C":"It lowers employees' hourly pay rates permanently","D":"It eliminates written employment contracts"},"correctOption":"B","correctAnswer":"It boosts confidence, reduces accidents, and improves promotion and earning prospects","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because acquiring skills makes employees safer, more confident, and qualified for higher-paid roles.","distractor_reasons":{"A":"Incorrect because training reinforces adherence to safety rules.","B":"Correct selection.","C":"Incorrect because higher skills generally raise earning potential.","D":"Incorrect because employment contracts remain mandatory."}}},{"id":"P1_U2_MCQ_185","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_185","question":"Facing falling demand for printed directories, a publisher cuts its workforce by 15% over two years by not replacing staff who voluntarily retire or resign. What is this called?","options":{"A":"Summary dismissal for misconduct","B":"Compulsory mass redundancy","C":"Natural wastage (attrition)","D":"External headhunting"},"correctOption":"C","correctAnswer":"Natural wastage (attrition)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because natural wastage reduces headcount gradually without compulsory layoffs, saving severance pay.","distractor_reasons":{"A":"Incorrect because summary dismissal fires workers for gross misconduct.","B":"Incorrect because compulsory redundancy terminates workers involuntarily.","C":"Correct selection.","D":"Incorrect because headhunting recruits senior managers."}}},{"id":"P1_U2_MCQ_186","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_186","question":"A cashier is fired without notice after CCTV proves theft, while a warehouse clerk gets severance pay when his depot closes. Why did the cashier get no severance pay?","options":{"A":"Cashiers are excluded from employment laws","B":"Depot closure is classified as gross misconduct","C":"Severance pay is given only to staff who steal","D":"The cashier was fairly dismissed for gross misconduct, whereas the clerk was made redundant due to depot closure"},"correctOption":"D","correctAnswer":"The cashier was fairly dismissed for gross misconduct, whereas the clerk was made redundant due to depot closure","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because theft is gross misconduct justifying dismissal without severance, whereas redundancy compensates lost jobs.","distractor_reasons":{"A":"Incorrect because cashiers are protected by employment laws.","B":"Incorrect because depot closure is economic redundancy, not misconduct.","C":"Incorrect because misconduct forfeits severance entitlement.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_187","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_187","question":"A courier driver is dismissed immediately after reporting faulty vehicle brakes to safety regulators, without any disciplinary hearing. Which legal claim can the driver bring?","options":{"A":"Unfair dismissal","B":"Voluntary redundancy","C":"Piece-rate wage breach","D":"Trade union lockout"},"correctOption":"A","correctAnswer":"Unfair dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because firing a worker for reporting genuine safety hazards without due process constitutes unfair dismissal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because redundancy occurs when a job role is no longer needed.","C":"Incorrect because the dispute concerns termination rather than piece-rate pay.","D":"Incorrect because a lockout is a temporary workplace closure during a labor dispute."}}},{"id":"P1_U2_MCQ_188","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_188","question":"A hotel chain employed an average of 240 staff during the year, and 36 employees left over those 12 months. What was its annual labor turnover rate?","options":{"A":"36%","B":"15%","C":"6.7%","D":"85%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labor turnover = (36 leavers / 240 average staff) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 36 is the number of leavers rather than the percentage.","B":"Correct selection.","C":"Incorrect because 6.7% divides 240 by 36.","D":"Incorrect because 85% is the retention rate (100% - 15%)."}}},{"id":"P1_U2_MCQ_189","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_189","question":"The government raises the statutory minimum wage by 12%. How is this legal control most likely to affect a café chain employing entry-level baristas?","options":{"A":"The café chain can legally ignore the rise if profits fall","B":"Commercial property rent drops by 12% automatically","C":"Payroll costs rise, prompting better staff training, modest price rises, or self-order kiosks","D":"Baristas work 12% fewer hours for zero pay"},"correctOption":"C","correctAnswer":"Payroll costs rise, prompting better staff training, modest price rises, or self-order kiosks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher minimum wages increase labor costs, encouraging productivity gains, automation, or price adjustments.","distractor_reasons":{"A":"Incorrect because minimum wage laws are legally binding.","B":"Incorrect because minimum wage rules do not lower rent.","C":"Correct selection.","D":"Incorrect because staff must be paid for all hours worked."}}},{"id":"P1_U2_MCQ_190","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_190","question":"Under health and safety laws, a woodworking factory must fit saw guards and provide protective eyewear. What happens if the factory refuses to comply?","options":{"A":"The government rewards the factory with lower corporate taxes","B":"Injured carpenters lose legal rights to claim compensation","C":"The factory is exempted from minimum wage laws","D":"Government inspectors can impose heavy fines, halt unsafe operations, and prosecute directors"},"correctOption":"D","correctAnswer":"Government inspectors can impose heavy fines, halt unsafe operations, and prosecute directors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health and safety laws carry strict penalties including prohibition notices, heavy fines, and prosecution.","distractor_reasons":{"A":"Incorrect because non-compliance brings penalties, not tax rewards.","B":"Incorrect because injured workers retain strong compensation rights.","C":"Incorrect because minimum wage laws remain enforceable.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_191","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_191","question":"A building manager mounts illuminated 'Fire Exit' signs and printed evacuation maps in every corridor. Which type of communication is this?","options":{"A":"One-way visual/written communication displaying clear instructions without expecting a reply","B":"Two-way verbal negotiation between staff and firefighters","C":"Informal grapevine rumor spreading","D":"External shareholder financial reporting"},"correctOption":"A","correctAnswer":"One-way visual/written communication displaying clear instructions without expecting a reply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because safety signs transmit standardized one-way instructions without requiring a response.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because signs do not involve two-way conversation.","C":"Incorrect because official safety signs are formal communications.","D":"Incorrect because evacuation maps serve building occupants."}}},{"id":"P1_U2_MCQ_192","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_192","question":"During an annual appraisal, a manager and employee discuss achievements, identify training needs, and agree on targets together. Why is two-way communication vital here?","options":{"A":"It prevents the employee from asking questions","B":"It encourages open dialogue, ensures mutual understanding, and builds employee commitment","C":"It eliminates recording agreed targets in writing","D":"It allows the manager to finish in 30 seconds"},"correctOption":"B","correctAnswer":"It encourages open dialogue, ensures mutual understanding, and builds employee commitment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because two-way communication lets employees voice ideas and contribute to goal-setting, boosting buy-in.","distractor_reasons":{"A":"Incorrect because two-way dialogue invites employee questions.","B":"Correct selection.","C":"Incorrect because appraisal outcomes are still documented.","D":"Incorrect because meaningful dialogue takes longer than a directive."}}},{"id":"P1_U2_MCQ_193","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_193","question":"Sales accepts an urgent order for 200 tables without checking with Production, which lacks enough timber to meet the deadline. Which failure does this show?","options":{"A":"Excessive external public relations spending","B":"Over-reliance on video calls with shareholders","C":"Poor internal horizontal communication between departments causing unfulfilled promises","D":"Strict compliance with minimum wage regulations"},"correctOption":"C","correctAnswer":"Poor internal horizontal communication between departments causing unfulfilled promises","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal communication between sales and production is vital to coordinate stock and delivery dates.","distractor_reasons":{"A":"Incorrect because the failure occurred internally between departments.","B":"Incorrect because shareholder calls are unrelated to stock checks.","C":"Correct selection.","D":"Incorrect because minimum wage rules have no link to scheduling."}}},{"id":"P1_U2_MCQ_194","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_194","question":"A listed supermarket publishes its audited annual financial report on its investor website and sends dividend notices to shareholders. Why is accurate external communication essential?","options":{"A":"It replaces the need to train store cashiers","B":"It allows the supermarket to avoid paying suppliers","C":"It keeps financial results secret from company owners","D":"It fulfills legal governance duties and maintains shareholder confidence and investment"},"correctOption":"D","correctAnswer":"It fulfills legal governance duties and maintains shareholder confidence and investment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders rely on transparent, legally compliant external reports to assess performance.","distractor_reasons":{"A":"Incorrect because investor reports do not replace staff training.","B":"Incorrect because suppliers must still be paid on time.","C":"Incorrect because annual reports share financial results.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_195","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_195","question":"When informing a long-serving worker that their role is at risk of redundancy, an HR Manager holds a private face-to-face meeting instead of sending a text. Why is face-to-face better?","options":{"A":"It shows empathy, allows immediate answers to emotional questions, and uses supportive body language","B":"It automatically creates a printed contract without paperwork","C":"It prevents the employee from asking about severance pay","D":"It is illegal to follow up a redundancy meeting in writing"},"correctOption":"A","correctAnswer":"It shows empathy, allows immediate answers to emotional questions, and uses supportive body language","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sensitive news requires human empathy, non-verbal reassurance, and immediate clarification.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because written redundancy letters are still issued afterward.","C":"Incorrect because face-to-face meetings allow direct questions.","D":"Incorrect because written follow-up is standard practice."}}},{"id":"P1_U2_MCQ_196","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_196","question":"A director sends a 45-page printed manual to warehouse clerks explaining minor box-labeling tweaks, so clerks fail to read it. What is a drawback of lengthy written communication?","options":{"A":"Written documents can never be saved for future reference","B":"Dense text takes time to read, lacks immediate feedback, and is often ignored by busy receivers","C":"Written manuals are distorted by factory machine noise","D":"Written instructions are illegal inside warehouses"},"correctOption":"B","correctAnswer":"Dense text takes time to read, lacks immediate feedback, and is often ignored by busy receivers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overly long written documents overwhelm busy readers and lack immediate feedback checks.","distractor_reasons":{"A":"Incorrect because providing a permanent record is an advantage of written text.","B":"Correct selection.","C":"Incorrect because noise interferes with speech rather than printed text.","D":"Incorrect because written procedures are completely legal."}}},{"id":"P1_U2_MCQ_197","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_197","question":"A retail bank stores updated lending rules and staff handbooks on a secure internal intranet across 300 branches. What is a major advantage of an intranet?","options":{"A":"External competitors can freely edit the bank's lending rules","B":"Branches no longer need computers or network links","C":"All staff across branches access identical up-to-date information instantly, saving printing costs","D":"It guarantees employees never misunderstand complex rules"},"correctOption":"C","correctAnswer":"All staff across branches access identical up-to-date information instantly, saving printing costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an intranet centralizes policies digitally, ensuring instant version updates and cutting paper use.","distractor_reasons":{"A":"Incorrect because an intranet is restricted to authorized staff.","B":"Incorrect because accessing an intranet requires computers and networks.","C":"Correct selection.","D":"Incorrect because digital storage does not guarantee comprehension."}}},{"id":"P1_U2_MCQ_198","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_198","question":"An IT engineer emails store cashiers instructing them to 'flush local DNS cache protocols and reset TCP sockets' when tills freeze, leaving cashiers confused. Which barrier occurred?","options":{"A":"Physical distance across international time zones","B":"Failure of printed postal mail delivery","C":"Excessive use of simple visual diagrams","D":"Use of complex technical jargon inappropriate for non-specialist receivers"},"correctOption":"D","correctAnswer":"Use of complex technical jargon inappropriate for non-specialist receivers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because specialized technical jargon that receivers do not understand blocks accurate decoding.","distractor_reasons":{"A":"Incorrect because confusion stemmed from vocabulary, not time zones.","B":"Incorrect because the message was sent via email.","C":"Incorrect because simple diagrams would have helped comprehension.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_199","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_199","question":"A CEO verbally briefs Vice Presidents on a discount rule, which passes verbally through four more management tiers before reaching cashiers with the discount wrongly doubled. Which barrier caused this?","options":{"A":"A long chain of command with too many intermediary hierarchy tiers distorting the message","B":"Over-use of clear emails sent directly to cashiers","C":"A flat organizational structure with wide spans of control","D":"High staff motivation and strong trust in leadership"},"correctOption":"A","correctAnswer":"A long chain of command with too many intermediary hierarchy tiers distorting the message","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because passing verbal messages through many hierarchy layers causes cumulative misinterpretation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because direct emails preserve exact accuracy.","C":"Incorrect because flat structures have fewer tiers and less distortion.","D":"Incorrect because distortion arose from structural intermediaries."}}},{"id":"P1_U2_MCQ_200","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_200","question":"To stop packers misreading shipping instructions, a manager replaces text-heavy memos with plain-language checklists and diagrams, checking understanding in morning huddles. How does this help?","options":{"A":"It eliminates two-way feedback between supervisors and packers","B":"It adapts language and medium to the audience while building in direct feedback checks","C":"It adds three extra management tiers to approve checklists","D":"It relies on canteen rumors to spread shipping rules"},"correctOption":"B","correctAnswer":"It adapts language and medium to the audience while building in direct feedback checks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because plain language, clear visuals, and verbal feedback loops directly overcome decoding and channel barriers.","distractor_reasons":{"A":"Incorrect because morning huddles actively encourage two-way feedback.","B":"Correct selection.","C":"Incorrect because adding tiers creates communication barriers.","D":"Incorrect because checklists and huddles replace rumors."}}},{"id":"P1_U2_MCQ_201","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_201","question":"A luxury car dealership pays its showroom executives a fixed annual salary with no sales commission. What is a primary advantage of this payment method for the dealership?","options":{"A":"Executives focus on high-pressure hard selling to maximize daily unit volume","B":"Payroll costs are predictable and executives collaborate without fighting over customers","C":"Executives receive zero pay during months with low customer footfall","D":"Wage expenses automatically fall whenever showroom sales decline"},"correctOption":"B","correctAnswer":"Payroll costs are predictable and executives collaborate without fighting over customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fixed salaries make labor costs predictable and encourage customer service and teamwork rather than aggressive commission competition.","distractor_reasons":{"A":"Incorrect because aggressive unit-chasing is linked to high commission or piece-rate pay.","B":"Correct selection.","C":"Incorrect because salaried staff receive their regular monthly pay regardless of sales volume.","D":"Incorrect because annual salaries are fixed overheads that do not fall automatically when sales dip."}}},{"id":"P1_U2_MCQ_202","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_202","question":"A furniture workshop switches from hourly time-rate wages to piece-rate pay per completed chair, causing output to surge while customer defect returns double. Why did quality decline?","options":{"A":"Piece-rate pay eliminates all financial incentives to work quickly","B":"Workers spend too much time inspecting joints and sanding surfaces","C":"Workers rush assembly to maximize unit count and earnings at the expense of craftsmanship","D":"Time-rate wages always produce higher defect rates than piece-rate pay"},"correctOption":"C","correctAnswer":"Workers rush assembly to maximize unit count and earnings at the expense of craftsmanship","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because piece-rate rewards quantity produced, tempting workers to rush tasks and neglect quality unless strict inspection is enforced.","distractor_reasons":{"A":"Incorrect because piece-rate provides a strong financial incentive to increase speed.","B":"Incorrect because spending extra time inspecting would reduce a worker's piece-rate earnings.","C":"Correct selection.","D":"Incorrect because hourly time-rate pay usually allows more careful workmanship than rushed piece-rate pay."}}},{"id":"P1_U2_MCQ_203","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_203","question":"A software company grants senior developers share options allowing them to buy company shares at a discounted fixed price after three years. How does this motivate developers?","options":{"A":"It guarantees developers a fixed cash bonus every Friday afternoon","B":"It removes the need to pay developers any monthly base salary","C":"It allows developers to leave the company immediately without losing unvested shares","D":"It encourages long-term retention and hard work to boost company profitability and share price"},"correctOption":"D","correctAnswer":"It encourages long-term retention and hard work to boost company profitability and share price","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because share ownership aligns employees' financial interests with long-term business growth and encourages them to stay.","distractor_reasons":{"A":"Incorrect because share options vest over years rather than paying weekly cash bonuses.","B":"Incorrect because share schemes supplement regular salaries.","C":"Incorrect because vesting periods require staff to remain employed for a set timeframe.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_204","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_204","question":"A bottling plant pays operators $0.15 per crate packed up to 1,000 crates per week, and $0.25 per crate for any crates packed above 1,000. If an operator packs 1,240 crates in a week, what is their gross weekly wage?","options":{"A":"$210.00","B":"$186.00","C":"$310.00","D":"$240.00"},"correctOption":"A","correctAnswer":"$210.00","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the first 1,000 crates earn 1,000 × $0.15 = $150.00, the extra 240 crates earn 240 × $0.25 = $60.00, and total pay = $210.00.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $186.00 pays all 1,240 crates at $0.15 without the higher bonus tier.","C":"Incorrect because $310.00 pays all 1,240 crates at $0.25.","D":"Incorrect arithmetic."}}},{"id":"P1_U2_MCQ_205","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_205","question":"A pharmaceutical lab lets senior research chemists choose their own experimental methods and pursue innovative drug compounds. Which need in Maslow's hierarchy does this satisfy?","options":{"A":"Physiological survival needs","B":"Self-actualization needs","C":"Basic safety and security needs","D":"Social belonging needs"},"correctOption":"B","correctAnswer":"Self-actualization needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because autonomy, creative problem-solving, and fulfilling one's highest intellectual potential represent self-actualization.","distractor_reasons":{"A":"Incorrect because physiological needs cover basic food, shelter, and survival income.","B":"Correct selection.","C":"Incorrect because safety needs relate to job security and physical protection.","D":"Incorrect because social needs involve friendship and group acceptance."}}},{"id":"P1_U2_MCQ_206","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_206","question":"According to Herzberg's two-factor theory, which change made by a retail bank will act as a genuine 'motivator' rather than merely a 'hygiene factor'?","options":{"A":"Installing brighter LED ceiling lights in back-office rooms","B":"Replacing broken breakroom coffee machines","C":"Giving customer advisors authority to resolve fee disputes and offering clear career progression","D":"Clarifying the written dress-code policy for branch tellers"},"correctOption":"C","correctAnswer":"Giving customer advisors authority to resolve fee disputes and offering clear career progression","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg identifies responsibility, meaningful work, and advancement as true motivators that drive higher effort.","distractor_reasons":{"A":"Incorrect because physical working conditions are hygiene factors.","B":"Incorrect because workplace amenities are hygiene factors.","C":"Correct selection.","D":"Incorrect because company rules and administrative policies are hygiene factors."}}},{"id":"P1_U2_MCQ_207","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_207","question":"Instead of assigning bank clerks solely to check-cashing all day, a branch trains them to handle loan inquiries, account openings, and fraud checks. Which job design method is this?","options":{"A":"Piece-rate incentive pricing","B":"Autocratic task narrowing","C":"External headhunting","D":"Job enrichment"},"correctOption":"D","correctAnswer":"Job enrichment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because job enrichment adds more complex, skilled, and responsible tasks vertically to make a role more challenging and rewarding.","distractor_reasons":{"A":"Incorrect because piece-rate is a financial payment per unit produced.","B":"Incorrect because narrowing tasks reduces variety rather than expanding responsibility.","C":"Incorrect because headhunting recruits senior external managers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_208","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_208","question":"A supermarket checkout operator is given extra peer-level duties such as restocking nearby shelves and printing price tags, without added decision-making authority. What is this called?","options":{"A":"Job enlargement","B":"Job enrichment","C":"Delayering","D":"Collective bargaining"},"correctOption":"A","correctAnswer":"Job enlargement","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enlargement adds more tasks of a similar skill level horizontally to reduce repetition without increasing authority.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because job enrichment involves higher-level responsibility and autonomy.","C":"Incorrect because delayering removes layers of management.","D":"Incorrect because collective bargaining is union-employer negotiation."}}},{"id":"P1_U2_MCQ_209","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_209","question":"A parcel delivery company pays drivers a $250 quarterly bonus if they achieve zero late deliveries and zero customer complaints. What is a potential drawback of this bonus scheme?","options":{"A":"Bonuses permanently replace drivers' basic weekly wages","B":"Drivers may feel demotivated if unavoidable traffic jams disqualify them through no fault of their own","C":"Bonuses cannot be paid to full-time employees","D":"Customer service quality always falls when bonuses are offered"},"correctOption":"B","correctAnswer":"Drivers may feel demotivated if unavoidable traffic jams disqualify them through no fault of their own","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because strict bonus thresholds can cause resentment if external factors beyond workers' control prevent them from qualifying.","distractor_reasons":{"A":"Incorrect because bonuses are extra payments on top of basic pay.","B":"Correct selection.","C":"Incorrect because full-time staff commonly receive performance bonuses.","D":"Incorrect because linking bonuses to zero complaints aims to improve service."}}},{"id":"P1_U2_MCQ_210","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_210","question":"A call center introduces subsidized staff lunches, dental insurance, and a company car for team leaders. What are these non-cash additions to pay called?","options":{"A":"Piece-rate wages","B":"Statutory redundancy payouts","C":"Fringe benefits (perks)","D":"Commission overrides"},"correctOption":"C","correctAnswer":"Fringe benefits (perks)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fringe benefits are non-wage rewards such as health insurance, subsidized meals, and company vehicles that aid recruitment and retention.","distractor_reasons":{"A":"Incorrect because piece-rate pays cash per unit of output.","B":"Incorrect because redundancy pay compensates employees whose jobs end.","C":"Correct selection.","D":"Incorrect because commission is a percentage of sales revenue."}}},{"id":"P1_U2_MCQ_211","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_211","question":"A newly hired junior buyer inspects the company's organizational chart on her first morning. What information does the organizational chart clearly show?","options":{"A":"Each employee's private home address and bank details","B":"The company's exact net profit forecast for the next five years","C":"Every customer's unpaid invoice balance","D":"Formal job titles, departmental groupings, spans of control, and the chain of command"},"correctOption":"D","correctAnswer":"Formal job titles, departmental groupings, spans of control, and the chain of command","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an organizational chart visually maps roles, departments, reporting relationships, and spans of control.","distractor_reasons":{"A":"Incorrect because personal HR data is never published on an organizational chart.","B":"Incorrect because financial forecasts appear in budgets, not org charts.","C":"Incorrect because customer balances belong in accounting ledgers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_212","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_212","question":"In a boutique design agency, one Creative Director directly supervises 14 graphic designers with no intermediate team leaders. How is this structure best described?","options":{"A":"A flat organizational structure with a wide span of control","B":"A tall organizational structure with a narrow span of control","C":"A bureaucratic hierarchy with eleven management layers","D":"An organization with no chain of command"},"correctOption":"A","correctAnswer":"A flat organizational structure with a wide span of control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because having very few hierarchy tiers and 14 direct reports defines a flat structure with a wide span of control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tall structures have many levels and narrow spans (e.g., 3–5 subordinates).","C":"Incorrect because only two levels exist in this agency.","D":"Incorrect because the designers still report directly to the Creative Director."}}},{"id":"P1_U2_MCQ_213","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_213","question":"A nuclear power plant maintains narrow spans of control of three technicians per shift engineer. Why is a narrow span of control suitable in this workplace?","options":{"A":"Technicians require zero technical supervision","B":"High-risk, complex safety procedures demand close monitoring and frequent guidance","C":"Narrow spans eliminate all middle-management salary costs","D":"Narrow spans guarantee instant communication from the boardroom to technicians"},"correctOption":"B","correctAnswer":"High-risk, complex safety procedures demand close monitoring and frequent guidance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complex, safety-critical operations require close supervision that a manager can provide only with few direct reports.","distractor_reasons":{"A":"Incorrect because minimal supervision suits wide spans of control.","B":"Correct selection.","C":"Incorrect because narrow spans require more supervisors, increasing salary costs.","D":"Incorrect because narrow spans create taller structures with longer chains of command."}}},{"id":"P1_U2_MCQ_214","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_214","question":"Ahead of launching an electric scooter, a Operations Manager sets output targets, books factory floor space, and allocates budgets across engineering teams. Which management functions are these?","options":{"A":"External auditing and trade union mediation","B":"Dismissal and statutory redundancy","C":"Planning and organizing","D":"Informal grapevine networking"},"correctOption":"C","correctAnswer":"Planning and organizing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because setting goals (planning) and arranging resources and teams to achieve them (organizing) are core Fayol management functions.","distractor_reasons":{"A":"Incorrect because external auditing is performed by independent accountants.","B":"Incorrect because dismissal and redundancy concern ending employment.","C":"Correct selection.","D":"Incorrect because grapevine networking is unofficial employee chatter."}}},{"id":"P1_U2_MCQ_215","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_215","question":"An Architecture Studio Partner sets project deadlines and budgets, then leaves senior architects completely free to design buildings in their own way. Which leadership style is this?","options":{"A":"Autocratic leadership","B":"Coercive authoritarian leadership","C":"Paternalistic micromanagement","D":"Laissez-faire leadership"},"correctOption":"D","correctAnswer":"Laissez-faire leadership","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because laissez-faire leaders outline broad goals and grant highly skilled professionals freedom to manage their own work.","distractor_reasons":{"A":"Incorrect because autocratic leaders dictate exact methods and closely control staff.","B":"Incorrect because coercive leaders rely on threats and strict orders.","C":"Incorrect because micromanagement monitors every minor step.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_216","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_216","question":"A supermarket chain adopts laissez-faire leadership for newly hired teenage weekend shelf-stackers, resulting in unstocked aisles and missed breaks. Why did this style fail?","options":{"A":"Inexperienced staff lack the training and confidence to work without clear structure and supervision","B":"Laissez-faire leadership forces managers to shout constant orders","C":"Weekend staff are legally forbidden from speaking to supervisors","D":"Laissez-faire leadership works only in military combat units"},"correctOption":"A","correctAnswer":"Inexperienced staff lack the training and confidence to work without clear structure and supervision","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because laissez-faire leadership fails when employees lack experience, self-direction, or clear instructions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shouting constant orders describes autocratic leadership.","C":"Incorrect because no such legal restriction exists.","D":"Incorrect because military emergencies require autocratic command, whereas laissez-faire suits creative/research specialists."}}},{"id":"P1_U2_MCQ_217","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_217","question":"A factory employs 450 production workers. Following a union recruitment drive, 315 workers join the union. What is the union density (percentage membership) at this factory?","options":{"A":"30%","B":"70%","C":"65%","D":"143%"},"correctOption":"B","correctAnswer":"70%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because union density = (315 union members / 450 total workers) × 100 = 70%.","distractor_reasons":{"A":"Incorrect because 30% represents the non-unionized proportion (135 / 450).","B":"Correct selection.","C":"Incorrect arithmetic.","D":"Incorrect because 143% divides 450 by 315."}}},{"id":"P1_U2_MCQ_218","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_218","question":"How can recognizing a single trade union benefit an employer operating a large manufacturing plant?","options":{"A":"It guarantees workers will never ask for higher wages","B":"It allows the employer to ignore statutory health and safety rules","C":"Management negotiates once with union representatives rather than holding hundreds of separate talks","D":"It transfers legal ownership of factory machinery to the union"},"correctOption":"C","correctAnswer":"Management negotiates once with union representatives rather than holding hundreds of separate talks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a single channel of representation saves management time and provides structured communication with the workforce.","distractor_reasons":{"A":"Incorrect because unions regularly negotiate for pay rises.","B":"Incorrect because health and safety laws remain binding.","C":"Correct selection.","D":"Incorrect because union recognition does not transfer company assets."}}},{"id":"P1_U2_MCQ_219","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_219","question":"An overworked Production Manager delegates scheduling of routine maintenance shifts to a senior supervisor, freeing time for supplier negotiations. How does this delegation benefit the manager?","options":{"A":"The manager is no longer accountable if factory maintenance fails","B":"The manager avoids paying the senior supervisor a salary","C":"The manager no longer needs to monitor factory output","D":"The manager focuses on higher-value strategic priorities while developing the supervisor's skills"},"correctOption":"D","correctAnswer":"The manager focuses on higher-value strategic priorities while developing the supervisor's skills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delegation reduces managerial overload on routine tasks and prepares subordinates for future promotion.","distractor_reasons":{"A":"Incorrect because managers retain ultimate accountability for delegated work.","B":"Incorrect because delegated staff still receive their contracted pay.","C":"Incorrect because managers still oversee overall performance.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_220","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_220","question":"A regional transport company centralizes all vehicle purchasing and driver disciplinary decisions at its head office rather than decentralizing them to depot managers. What is a benefit of centralization?","options":{"A":"Consistent policies across all depots and bulk-purchasing economies of scale","B":"Faster local response to sudden depot emergencies without head-office approval","C":"Higher motivation for depot managers to make independent decisions","D":"Complete elimination of head-office administrative staff"},"correctOption":"A","correctAnswer":"Consistent policies across all depots and bulk-purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because centralized control ensures uniform standards and allows bulk buying power across branches.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fast local responsiveness is an advantage of decentralization.","C":"Incorrect because local autonomy motivates decentralized managers.","D":"Incorrect because centralization concentrates decision-making at head office."}}},{"id":"P1_U2_MCQ_221","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_221","question":"When a senior accountant resigns, HR reviews whether her tasks can be redistributed or automated before advertising a replacement. What is this initial step called?","options":{"A":"External headhunting","B":"Job analysis and evaluating whether a vacancy actually needs filling","C":"Induction training","D":"Panel interviewing"},"correctOption":"B","correctAnswer":"Job analysis and evaluating whether a vacancy actually needs filling","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the recruitment process begins by identifying if a genuine vacancy exists and analyzing its tasks.","distractor_reasons":{"A":"Incorrect because headhunting occurs after deciding to recruit externally.","B":"Correct selection.","C":"Incorrect because induction occurs after a new employee is hired.","D":"Incorrect because interviewing happens after shortlisting candidates."}}},{"id":"P1_U2_MCQ_222","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_222","question":"A boutique hotel wants to hire an experienced General Manager capable of introducing modern digital booking strategies used by rival chains. Why is external recruitment preferable?","options":{"A":"External recruitment costs zero money and takes one day","B":"Existing junior receptionists already know rival chains' secret strategies","C":"It brings fresh ideas, industry expertise, and a wider pool of qualified leaders","D":"External hires never require induction training"},"correctOption":"C","correctAnswer":"It brings fresh ideas, industry expertise, and a wider pool of qualified leaders","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because external recruitment widens the talent pool and injects outside expertise and innovation.","distractor_reasons":{"A":"Incorrect because external advertising and selection incur significant time and fees.","B":"Incorrect because internal staff lack external rival experience.","C":"Correct selection.","D":"Incorrect because external hires require thorough induction into company systems."}}},{"id":"P1_U2_MCQ_223","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_223","question":"A hospital promotes an internal Ward Sister to Head of Nursing, causing three unsuccessful internal applicants to feel resentful and uncooperative. What drawback of internal recruitment is shown?","options":{"A":"High external newspaper advertising expenses","B":"Lack of familiarity with hospital safety procedures","C":"Excessive influx of unfamiliar outside management styles","D":"Workplace jealousy and demotivation among passed-over internal colleagues"},"correctOption":"D","correctAnswer":"Workplace jealousy and demotivation among passed-over internal colleagues","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because internal promotions can create rivalry and lower morale among colleagues who were not selected.","distractor_reasons":{"A":"Incorrect because internal promotion avoids external ad fees.","B":"Incorrect because internal candidates already know hospital procedures.","C":"Incorrect because outside styles come from external hires.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_224","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_224","question":"A civil aviation authority needs to recruit three certified air-traffic control radar engineers. Which recruitment medium will reach qualified candidates most effectively?","options":{"A":"A specialist aviation industry trade journal and professional engineering job board","B":"A handwritten postcard in a local bakery window","C":"A flyer handed out at a primary school gate","D":"An internal noticeboard inside a supermarket"},"correctOption":"A","correctAnswer":"A specialist aviation industry trade journal and professional engineering job board","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialist trade publications target niche, accredited professionals directly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local shop windows reach general local jobseekers, not certified radar engineers.","C":"Incorrect because school flyers do not target aviation engineers.","D":"Incorrect because supermarket noticeboards reach retail staff."}}},{"id":"P1_U2_MCQ_225","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_225","question":"A pharmaceutical manufacturer uses a specialist recruitment agency (headhunter) to approach a rival firm's Chief Chemist. Why do firms pay high fees for headhunters?","options":{"A":"To recruit hundreds of seasonal warehouse packers","B":"To discreetly identify and persuade scarce, top-level executives who are not actively job-hunting","C":"To avoid signing written employment contracts with new hires","D":"To replace statutory health and safety inspections"},"correctOption":"B","correctAnswer":"To discreetly identify and persuade scarce, top-level executives who are not actively job-hunting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because headhunters proactively target rare senior talent who rarely browse public job adverts.","distractor_reasons":{"A":"Incorrect because seasonal packers are recruited cheaply via job centers or local ads.","B":"Correct selection.","C":"Incorrect because formal contracts remain legally required.","D":"Incorrect because headhunters handle executive search, not safety audits."}}},{"id":"P1_U2_MCQ_226","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_226","question":"Before offering a childcare worker position at a nursery, HR contacts two former employers listed on the candidate's application form. Why is checking references important?","options":{"A":"To negotiate the candidate's tax rate with the government","B":"To calculate the candidate's annual pension payout","C":"To independently verify past work performance, honesty, attendance, and safeguarding suitability","D":"To advertise other nursery vacancies to rival nurseries"},"correctOption":"C","correctAnswer":"To independently verify past work performance, honesty, attendance, and safeguarding suitability","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because references confirm factual employment history and reliability from neutral past employers.","distractor_reasons":{"A":"Incorrect because tax rates are set by tax authorities.","B":"Incorrect because pension payouts depend on future contributions.","C":"Correct selection.","D":"Incorrect because reference checks evaluate the applicant, not market vacancies."}}},{"id":"P1_U2_MCQ_227","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_227","question":"A multinational consumer goods firm invites 12 graduate management finalists to a full-day assessment center featuring group role-plays, case presentations, and interviews. What is an advantage of assessment centers?","options":{"A":"They are the cheapest and fastest way to hire casual cleaners","B":"They allow a single manager to hire friends without bias","C":"They eliminate the need to write a job description","D":"Multiple assessors observe teamwork, leadership, and problem-solving across realistic tasks, reducing bias"},"correctOption":"D","correctAnswer":"Multiple assessors observe teamwork, leadership, and problem-solving across realistic tasks, reducing bias","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because assessment centers combine varied exercises and multiple scorers to evaluate competencies thoroughly and fairly.","distractor_reasons":{"A":"Incorrect because assessment centers are expensive and time-intensive.","B":"Incorrect because panel scoring reduces single-interviewer bias.","C":"Incorrect because assessment tasks are designed around the job description.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_228","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_228","question":"A software startup requires every applicant to submit a standardized online application form rather than a free-form CV. Why do many employers prefer standardized application forms?","options":{"A":"All candidates provide identical information in the same format, making objective comparison easier","B":"Applicants are forbidden from listing their educational qualifications","C":"Application forms automatically conduct video interviews","D":"Standardized forms eliminate the need to shortlist candidates"},"correctOption":"A","correctAnswer":"All candidates provide identical information in the same format, making objective comparison easier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standardized forms gather consistent data across all applicants, preventing candidates from hiding weak areas.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because qualifications are a standard section on application forms.","C":"Incorrect because forms capture written data rather than live video.","D":"Incorrect because forms are used during shortlisting."}}},{"id":"P1_U2_MCQ_229","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_229","question":"A retail department store relies heavily on part-time sales assistants working 12 hours a week. What is a potential disadvantage of a predominantly part-time workforce?","options":{"A":"Part-time staff must be paid double the hourly rate of full-time staff","B":"Higher induction and training costs per hour worked, plus lower commitment and harder shift communication","C":"Part-time staff are legally allowed to refuse serving customers","D":"Part-time staff cannot work on Saturdays or Sundays"},"correctOption":"B","correctAnswer":"Higher induction and training costs per hour worked, plus lower commitment and harder shift communication","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because training two part-time workers costs more than training one full-time worker for the same total hours, and communication is harder.","distractor_reasons":{"A":"Incorrect because hourly pay rates are comparable to full-time roles.","B":"Correct selection.","C":"Incorrect because part-time staff must fulfill their job duties.","D":"Incorrect because weekend shifts are common for part-time retail staff."}}},{"id":"P1_U2_MCQ_230","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_230","question":"Why should a job advertisement omit irrelevant personal details like 'must be under 25 years old' and instead focus on skills and qualifications from the person specification?","options":{"A":"Younger workers never apply for advertised jobs","B":"Person specifications never mention required qualifications","C":"Restricting applicants by age breaches anti-discrimination laws and excludes capable candidates","D":"Job adverts are legally prohibited from stating salary ranges"},"correctOption":"C","correctAnswer":"Restricting applicants by age breaches anti-discrimination laws and excludes capable candidates","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because arbitrary age restrictions violate employment discrimination legislation and shrink the talent pool unfairly.","distractor_reasons":{"A":"Incorrect because young workers regularly apply for jobs.","B":"Incorrect because qualifications are central to a person specification.","C":"Correct selection.","D":"Incorrect because stating salary ranges in adverts is both legal and helpful."}}},{"id":"P1_U2_MCQ_231","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_231","question":"A supermarket chain skips induction training for new warehouse pickers during December, resulting in high early resignation rates and damaged stock. How does induction prevent this?","options":{"A":"Induction doubles every picker's hourly overtime rate","B":"Induction replaces all written health and safety regulations","C":"Induction allows new hires to work from home","D":"Induction helps new hires settle in quickly, understand safe equipment use, and feel welcomed"},"correctOption":"D","correctAnswer":"Induction helps new hires settle in quickly, understand safe equipment use, and feel welcomed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because structured induction reduces first-week anxiety, prevents avoidable errors, and lowers early labor turnover.","distractor_reasons":{"A":"Incorrect because induction is orientation training, not a pay increase.","B":"Incorrect because induction teaches staff to follow safety regulations.","C":"Incorrect because warehouse picking must be performed on-site.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_232","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_232","question":"A call-center trainee shadows an experienced agent who frequently skips mandatory data-protection verification steps, so the trainee copies the shortcut. Which drawback of on-the-job training is this?","options":{"A":"Trainees may pick up bad habits and unsafe shortcuts from existing staff","B":"External university tuition fees drain company cash flow","C":"Trainees spend months away from the workplace in classrooms","D":"On-the-job training uses outdated simulation software instead of real calls"},"correctOption":"A","correctAnswer":"Trainees may pick up bad habits and unsafe shortcuts from existing staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if the internal mentor has poor work habits, the trainee will replicate those mistakes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external tuition fees apply to off-the-job training.","C":"Incorrect because trainees stay in the workplace during on-the-job training.","D":"Incorrect because trainees work with real workplace systems."}}},{"id":"P1_U2_MCQ_233","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_233","question":"An accounting firm sponsors junior auditors to attend evening classes at a certified institute to learn new international tax rules. Why is off-the-job training necessary here?","options":{"A":"Current staff already know every new international tax rule","B":"Specialist external instructors provide up-to-date expertise not yet held inside the firm","C":"Evening classes produce immediate billable audit output during lessons","D":"Off-the-job training costs zero money for the employer"},"correctOption":"B","correctAnswer":"Specialist external instructors provide up-to-date expertise not yet held inside the firm","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because off-the-job training brings new external knowledge and formal qualifications into the organization.","distractor_reasons":{"A":"Incorrect because external training is needed precisely when internal expertise does not yet exist.","B":"Correct selection.","C":"Incorrect because trainees do not produce output while attending classes.","D":"Incorrect because course fees are a key cost of off-the-job training."}}},{"id":"P1_U2_MCQ_234","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_234","question":"A manufacturing firm invests heavily in training machinists on computerized lathes, only for three trained staff to resign for higher pay at a rival factory. What risk of training does this illustrate?","options":{"A":"Trained workers become less productive on computerized lathes","B":"Training is illegal if competitors operate nearby","C":"Newly skilled employees become more attractive to competitors and may leave unless retained","D":"Machinists lose their statutory employment contracts after training"},"correctOption":"C","correctAnswer":"Newly skilled employees become more attractive to competitors and may leave unless retained","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because transferable skills increase employees' market value, risking poaching by rivals if pay and progression do not keep pace.","distractor_reasons":{"A":"Incorrect because training increases worker productivity.","B":"Incorrect because training is always legal.","C":"Correct selection.","D":"Incorrect because training does not cancel employment contracts."}}},{"id":"P1_U2_MCQ_235","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_235","question":"A high-street bank closes 25 physical branches as customers switch to mobile banking, eliminating 180 cashier roles. What is this workforce reduction called?","options":{"A":"Summary dismissal for misconduct","B":"Internal job rotation","C":"External recruitment","D":"Redundancy"},"correctOption":"D","correctAnswer":"Redundancy","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because redundancy occurs when jobs cease to exist due to technological change, falling demand, or branch closures—not worker fault.","distractor_reasons":{"A":"Incorrect because dismissal results from employee misconduct or incompetence.","B":"Incorrect because job rotation moves workers between active tasks.","C":"Incorrect because external recruitment hires new staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_236","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_236","question":"When choosing which warehouse workers to make redundant during a downturn, a fair employer uses objective criteria like attendance records, skills, and length of service rather than personal favoritism. Why?","options":{"A":"Objective criteria prevent unfair dismissal and discrimination claims while retaining vital skills","B":"Personal favoritism is required by employment legislation","C":"Objective criteria eliminate the need to pay statutory redundancy compensation","D":"Employers must always dismiss their most skilled workers first"},"correctOption":"A","correctAnswer":"Objective criteria prevent unfair dismissal and discrimination claims while retaining vital skills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent, objective redundancy selection protects the business legally and preserves essential operational capability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because biased selection leads to legal tribunals.","C":"Incorrect because eligible redundant employees still receive statutory redundancy pay.","D":"Incorrect because employers aim to retain needed skills."}}},{"id":"P1_U2_MCQ_237","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_237","question":"A newly hired restaurant chef starts work without receiving a written contract of employment, leading to a dispute over holiday pay and notice periods. Why are written contracts legally required?","options":{"A":"They allow the restaurant to change pay rates without the chef's consent","B":"They legally record pay, hours, duties, holiday entitlement, and notice rules, protecting both sides","C":"They exempt the restaurant from health and safety inspections","D":"They prevent the chef from ever resigning"},"correctOption":"B","correctAnswer":"They legally record pay, hours, duties, holiday entitlement, and notice rules, protecting both sides","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a written contract establishes clear, legally enforceable terms and responsibilities for both employer and employee.","distractor_reasons":{"A":"Incorrect because contracts prevent unilateral changes to pay terms.","B":"Correct selection.","C":"Incorrect because safety laws apply regardless of contracts.","D":"Incorrect because employees can resign by giving contractual notice."}}},{"id":"P1_U2_MCQ_238","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_238","question":"A distribution warehouse starts the year with 180 staff, finishes the year with 220 staff, and records 30 leavers during the year. Using average workforce size, what is its annual labor turnover rate?","options":{"A":"13.6%","B":"16.7%","C":"15.0%","D":"30.0%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because average staff = (180 + 220) / 2 = 200, and labor turnover = (30 / 200) × 100 = 15.0%.","distractor_reasons":{"A":"Incorrect because 13.6% divides 30 by year-end staff (220) instead of average staff (200).","B":"Incorrect because 16.7% divides 30 by opening staff (180) instead of average staff (200).","C":"Correct selection.","D":"Incorrect because 30.0% uses raw leavers as a percentage."}}},{"id":"P1_U2_MCQ_239","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_239","question":"A female financial analyst discovers she is paid 20% less than a male colleague performing identical work with identical qualifications. Which legal protection is breached?","options":{"A":"Statutory minimum wage exemption","B":"Redundancy consultation notice","C":"Workplace fire-exit signage rules","D":"Anti-discrimination and equal pay legislation"},"correctOption":"D","correctAnswer":"Anti-discrimination and equal pay legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because discrimination laws prohibit paying employees differently based on gender, race, religion, or disability for equal work.","distractor_reasons":{"A":"Incorrect because minimum wage laws set a statutory floor rather than equal pay for equal roles.","B":"Incorrect because no job is being eliminated.","C":"Incorrect because fire exits relate to health and safety.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_240","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_240","question":"A construction contractor claims that strict legal health and safety rules are purely a cost burden. How does complying with safety laws financially benefit the contractor?","options":{"A":"Fewer workplace accidents reduce sick-pay absences, compensation lawsuits, insurance premiums, and work stoppages","B":"Compliance allows the contractor to pay workers below minimum wage","C":"Safety compliance eliminates the cost of buying building materials","D":"Safety laws forbid workers from taking rest breaks"},"correctOption":"A","correctAnswer":"Fewer workplace accidents reduce sick-pay absences, compensation lawsuits, insurance premiums, and work stoppages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because safe workplaces boost morale, avoid costly fines and project delays, and lower accident-related expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws remain fully binding.","C":"Incorrect because material costs are unaffected.","D":"Incorrect because safety rules mandate adequate rest breaks."}}},{"id":"P1_U2_MCQ_241","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_241","question":"When sending a delivery update to a supplier, a Purchasing Officer states the purchase order number, item quantity, and loading bay gate. Which element of effective communication is the Purchasing Officer?","options":{"A":"The feedback loop","B":"The sender (transmitter)","C":"The external noise barrier","D":"The decoding receiver"},"correctOption":"B","correctAnswer":"The sender (transmitter)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the sender initiates the message, selects the medium, and encodes the information clearly for the receiver.","distractor_reasons":{"A":"Incorrect because feedback is the receiver's response confirming understanding.","B":"Correct selection.","C":"Incorrect because noise is interference that distorts a message.","D":"Incorrect because the supplier is the receiver."}}},{"id":"P1_U2_MCQ_242","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_242","question":"A clothing manufacturer emails a supplier requesting '500 meters of blue cotton fabric' without specifying shade code or delivery date, causing the wrong fabric to arrive late. What failed?","options":{"A":"Excessive use of two-way video conferencing","B":"Over-reliance on formal written contracts","C":"Incomplete and ambiguous encoding of the message by the sender","D":"Too many management layers inside the supplier's factory"},"correctOption":"C","correctAnswer":"Incomplete and ambiguous encoding of the message by the sender","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective communication requires precise, complete details so the receiver can act accurately.","distractor_reasons":{"A":"Incorrect because the order was sent by email, not video call.","B":"Incorrect because a detailed formal contract would have prevented ambiguity.","C":"Correct selection.","D":"Incorrect because the missing specifications were omitted by the buyer."}}},{"id":"P1_U2_MCQ_243","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_243","question":"A food company discovers glass fragments in one batch of pasta sauce and must warn consumers immediately across the country. Which external communication method is most effective?","options":{"A":"Pinning a memo inside the factory canteen","B":"Sending individual postal letters next month","C":"Whispering the warning to delivery drivers","D":"Issuing an urgent press release, social media alerts, and website recall notices"},"correctOption":"D","correctAnswer":"Issuing an urgent press release, social media alerts, and website recall notices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because urgent public safety recalls require fast, broad-reach external media channels.","distractor_reasons":{"A":"Incorrect because a canteen notice reaches internal staff rather than external shoppers.","B":"Incorrect because postal letters are far too slow for an urgent safety recall.","C":"Incorrect because informal word-of-mouth will not reach consumers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_244","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_244","question":"During a board presentation, the Finance Director displays bar charts and line graphs showing five-year revenue and profit trends. Why is visual communication effective here?","options":{"A":"Charts simplify complex numerical trends so directors grasp patterns quickly","B":"Visual charts eliminate the need for any financial data","C":"Charts allow immediate spoken replies without anyone speaking","D":"Visual displays cost nothing to design or project"},"correctOption":"A","correctAnswer":"Charts simplify complex numerical trends so directors grasp patterns quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual aids summarize large datasets clearly and reinforce spoken explanations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because charts are built from underlying financial figures.","C":"Incorrect because spoken feedback comes from verbal discussion.","D":"Incorrect because preparing visual presentations requires time and equipment."}}},{"id":"P1_U2_MCQ_245","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_245","question":"A multinational bank replaces international air travel for weekly regional manager meetings with live video conferencing. What is a primary benefit of video conferencing?","options":{"A":"Managers never experience internet connection drops","B":"Substantial travel cost and time savings while preserving real-time facial expressions and two-way dialogue","C":"Different international time zones disappear automatically","D":"Confidential files can never be hacked online"},"correctOption":"B","correctAnswer":"Substantial travel cost and time savings while preserving real-time facial expressions and two-way dialogue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because video conferencing enables immediate visual and verbal interaction across distances without travel expenses.","distractor_reasons":{"A":"Incorrect because technical glitches and poor internet remain possible drawbacks.","B":"Correct selection.","C":"Incorrect because time-zone differences still require scheduling coordination.","D":"Incorrect because cybersecurity risks still exist online."}}},{"id":"P1_U2_MCQ_246","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_246","question":"Rumors spread through the office grapevine that a factory will close next month, causing skilled engineers to resign prematurely even though no closure is planned. How should management respond?","options":{"A":"Ban employees from speaking during lunch breaks","B":"Ignore the rumors for six months until everyone resigns","C":"Hold a transparent all-staff briefing and issue a clear written statement explaining actual company plans","D":"Send encrypted technical jargon to confuse staff further"},"correctOption":"C","correctAnswer":"Hold a transparent all-staff briefing and issue a clear written statement explaining actual company plans","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because timely, honest formal communication counters destructive informal grapevine speculation.","distractor_reasons":{"A":"Incorrect because banning breakroom conversation is unrealistic and harms morale.","B":"Incorrect because silence fuels further panic and turnover.","C":"Correct selection.","D":"Incorrect because jargon worsens confusion."}}},{"id":"P1_U2_MCQ_247","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_247","question":"A supervisor tries to explain revised machine calibration steps to an operator standing beside a roaring stamping press without ear protection, causing a costly setup error. Which barrier occurred?","options":{"A":"Cultural differences between overseas branches","B":"Information overload from too many emails","C":"Distrust between trade union leaders and directors","D":"Physical environmental noise interfering with verbal communication"},"correctOption":"D","correctAnswer":"Physical environmental noise interfering with verbal communication","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because loud factory noise is a physical barrier that prevents accurate hearing of spoken instructions.","distractor_reasons":{"A":"Incorrect because both staff work at the same machine.","B":"Incorrect because the instruction was spoken, not emailed.","C":"Incorrect because the barrier was acoustic noise, not union distrust.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_248","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_248","question":"Store managers receive 180 internal emails every morning, causing them to miss an urgent price-change alert buried in their inbox. Which communication barrier is this?","options":{"A":"Information overload reducing receivers' ability to spot critical messages","B":"Lack of electronic communication devices in stores","C":"Absence of written records for price changes","D":"Over-use of face-to-face staff briefings"},"correctOption":"A","correctAnswer":"Information overload reducing receivers' ability to spot critical messages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive message volume overwhelms receivers so vital instructions get overlooked.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because managers are receiving emails electronically.","C":"Incorrect because emails provide written records.","D":"Incorrect because the problem was excessive emails, not face-to-face briefings."}}},{"id":"P1_U2_MCQ_249","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_249","question":"A European headquarters emails a translated safety policy to its Asian assembly plant, where a mistranslated phrase tells workers to 'remove' instead of 'inspect' safety guards. How can this barrier be prevented?","options":{"A":"Rely exclusively on machine-translated text without local review","B":"Have bilingual local managers verify translations and use clear visual diagrams","C":"Stop sending safety policies to overseas plants","D":"Increase the chain of command by six layers"},"correctOption":"B","correctAnswer":"Have bilingual local managers verify translations and use clear visual diagrams","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because native verification and universal visual diagrams overcome linguistic and cultural barriers.","distractor_reasons":{"A":"Incorrect because unverified machine translation caused the error.","B":"Correct selection.","C":"Incorrect because withholding safety rules endangers workers.","D":"Incorrect because adding hierarchy tiers increases distortion."}}},{"id":"P1_U2_MCQ_250","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_250","question":"Why is selecting an appropriate medium—such as emailing a routine roster versus holding a meeting for a sensitive grievance—essential for effective business communication?","options":{"A":"Every business message must always be sent by registered postal letter","B":"Written emails are illegal for routine shift schedules","C":"Matching urgency, complexity, and sensitivity to the right channel ensures clarity, speed, and feedback","D":"Choosing the right medium eliminates the need for employees to read messages"},"correctOption":"C","correctAnswer":"Matching urgency, complexity, and sensitivity to the right channel ensures clarity, speed, and feedback","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because different channels offer different strengths in speed, permanent record, and two-way feedback.","distractor_reasons":{"A":"Incorrect because postal mail is too slow for many routine or urgent tasks.","B":"Incorrect because email is ideal for routine schedules.","C":"Correct selection.","D":"Incorrect because receivers must still read or listen to the message."}}},{"id":"P1_U2_MCQ_251","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_251","question":"An electronics assembly plant breaks smartphone production into tiny, repetitive 20-second tasks and pays workers strictly according to units completed, based on F.W. Taylor's scientific management. Why might this approach eventually backfire?","options":{"A":"Extreme repetition causes boredom and alienation, leading to higher absenteeism and labor turnover","B":"Taylor's theory argues that workers are motivated purely by praise rather than money","C":"Breaking tasks into simple steps makes workers impossible to train","D":"Piece-rate pay eliminates all financial motivation to work faster"},"correctOption":"A","correctAnswer":"Extreme repetition causes boredom and alienation, leading to higher absenteeism and labor turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Taylorism assumes workers are motivated solely by money, ignoring social and psychological needs, which often causes monotony and high turnover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Taylor argued that pay (economic self-interest) is the primary motivator.","C":"Incorrect because simplified, specialized tasks are quick and cheap to train.","D":"Incorrect because piece-rate strongly incentivizes faster output."}}},{"id":"P1_U2_MCQ_252","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_252","question":"A textile mill reorganizes weavers into small cohesive teams and consults them before changing rest-break schedules, resulting in higher output even without a pay rise. Which theorist's findings does this support?","options":{"A":"F.W. Taylor's scientific time-and-motion study","B":"Elton Mayo's Hawthorne effect emphasizing social relationships and management interest","C":"Frederick Herzberg's hygiene-only pay model","D":"Autocratic task specialization"},"correctOption":"B","correctAnswer":"Elton Mayo's Hawthorne effect emphasizing social relationships and management interest","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Elton Mayo demonstrated that group belonging, teamwork, and managers showing genuine interest in workers boost productivity.","distractor_reasons":{"A":"Incorrect because Taylor emphasized individual financial incentives rather than social group dynamics.","B":"Correct selection.","C":"Incorrect because Herzberg identified motivators like responsibility and recognition, not a hygiene-only model.","D":"Incorrect because consulting workers on break schedules is participative, not autocratic."}}},{"id":"P1_U2_MCQ_253","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_253","question":"A hotel group introduces a 'Hospitality Star of the Quarter' trophy, a certificate presented by the CEO, and a senior concierge title for top performers. Which level of Maslow's hierarchy does this target?","options":{"A":"Physiological needs","B":"Safety and job security needs","C":"Esteem needs","D":"Basic survival needs"},"correctOption":"C","correctAnswer":"Esteem needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public recognition, status, respect from peers, and prestigious job titles fulfill esteem needs.","distractor_reasons":{"A":"Incorrect because physiological needs relate to basic food, shelter, and survival pay.","B":"Incorrect because safety needs involve physical protection and stable contracts.","C":"Correct selection.","D":"Incorrect because survival needs sit at the very bottom of Maslow's pyramid."}}},{"id":"P1_U2_MCQ_254","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_254","question":"A supermarket chain distributes 6% of its annual net profit equally among all permanent employees at year-end. What is a significant limitation of this profit-sharing scheme as an individual motivator?","options":{"A":"Employees must buy company shares with their own savings first","B":"Profit-sharing is illegal for retail businesses","C":"It guarantees employees a higher basic hourly wage every week","D":"Low-effort workers receive the same payout as high performers, and profits may fall due to external factors"},"correctOption":"D","correctAnswer":"Low-effort workers receive the same payout as high performers, and profits may fall due to external factors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because equal profit-sharing does not reward individual effort directly and pays nothing if external downturns wipe out company profit.","distractor_reasons":{"A":"Incorrect because profit-sharing distributes cash or shares from company profits without requiring employee purchases.","B":"Incorrect because profit-sharing is legal across all industries.","C":"Incorrect because profit-sharing is an annual variable reward, not a weekly base wage increase.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_255","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_255","question":"A real estate agency pays its property negotiators a basic salary of $1,200 per month plus 2.5% commission on completed property sales. If an agent sells properties worth $180,000 in May, what is their gross pay for May?","options":{"A":"$5,700","B":"$4,500","C":"$57,000","D":"$3,000"},"correctOption":"A","correctAnswer":"$5,700","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because commission = 2.5% × $180,000 = $4,500, plus the $1,200 basic salary = $5,700.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $4,500 is only the commission and omits the $1,200 basic salary.","C":"Incorrect because $57,000 misplaces the decimal point (25% instead of 2.5%).","D":"Incorrect arithmetic."}}},{"id":"P1_U2_MCQ_256","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_256","question":"An automotive components factory rotates line operators every two hours between stamping, welding, and packaging stations. What is an operational advantage of job rotation for the factory?","options":{"A":"Operators gain senior management authority to set factory budgets","B":"Workers become multi-skilled to cover unexpected absences while experiencing less task monotony","C":"The factory no longer needs to pay overtime rates for weekend shifts","D":"Training costs fall to zero because every station uses identical tools"},"correctOption":"B","correctAnswer":"Workers become multi-skilled to cover unexpected absences while experiencing less task monotony","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because job rotation builds workforce flexibility across stations and relieves boredom from doing one repetitive task all day.","distractor_reasons":{"A":"Incorrect because adding higher-level authority describes job enrichment, not rotation.","B":"Correct selection.","C":"Incorrect because overtime rules depend on employment contracts and labor laws.","D":"Incorrect because staff must still be trained safely on each station."}}},{"id":"P1_U2_MCQ_257","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_257","question":"A seasonal fruit farm pays pickers barely enough to afford basic food and rent, and attempts to boost output by introducing 'Picker of the Week' certificates instead of raising pay. Why is this likely to fail?","options":{"A":"Agricultural workers never respond to financial rewards","B":"Certificates are only effective in technology companies","C":"According to Maslow, unmet basic physiological needs take priority before esteem recognition can motivate","D":"Raising piece-rate pay always lowers farm output"},"correctOption":"C","correctAnswer":"According to Maslow, unmet basic physiological needs take priority before esteem recognition can motivate","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Maslow's hierarchy states lower-order survival needs must be reasonably satisfied before higher-order esteem rewards motivate behavior.","distractor_reasons":{"A":"Incorrect because seasonal pickers strongly respond to higher piece-rate or hourly pay.","B":"Incorrect because recognition works across sectors once basic pay needs are met.","C":"Correct selection.","D":"Incorrect because fair pay rises typically boost effort and retention."}}},{"id":"P1_U2_MCQ_258","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_258","question":"A parcel sorting depot upgrades its breakroom heating and increases basic hourly pay to match rival depots, stopping complaints but failing to raise sorting speed. How does Herzberg explain this result?","options":{"A":"Pay and working conditions are motivators that permanently double effort","B":"Workers only respond to autocratic threats of dismissal","C":"Breakroom heating is a self-actualization factor","D":"Pay and physical conditions are hygiene factors that remove dissatisfaction but do not actively motivate"},"correctOption":"D","correctAnswer":"Pay and physical conditions are hygiene factors that remove dissatisfaction but do not actively motivate","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Herzberg classifies pay, company policy, and physical conditions as hygiene factors—necessary to prevent dissatisfaction, not true motivators.","distractor_reasons":{"A":"Incorrect because Herzberg distinguishes hygiene factors from true motivators like achievement and responsibility.","B":"Incorrect because Herzberg advocates job enrichment rather than threats.","C":"Incorrect because heating is a basic physical hygiene factor.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_259","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_259","question":"An electronics manufacturer organizes technicians into self-managing production teams responsible for assembling, testing, and troubleshooting complete circuit boards. How does teamworking motivate employees?","options":{"A":"It satisfies social belonging needs and increases ownership over a complete, meaningful product","B":"It removes all accountability for product defects","C":"It eliminates the need for technical skills training","D":"It forces every technician to work in complete isolation"},"correctOption":"A","correctAnswer":"It satisfies social belonging needs and increases ownership over a complete, meaningful product","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because teamworking fosters camaraderie, mutual support, and pride in delivering a complete unit of work.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because teams share collective responsibility for quality.","C":"Incorrect because multi-skilled team members often need cross-training.","D":"Incorrect because teamworking is collaborative rather than isolated."}}},{"id":"P1_U2_MCQ_260","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_260","question":"A software firm holds constructive six-monthly performance appraisals and sponsors engineers to earn advanced cloud-architecture certifications. Why is training an effective non-financial motivator?","options":{"A":"Training reduces an employee's long-term career prospects","B":"Employees feel valued by the employer and gain mastery and confidence for future promotion","C":"Training replaces the need to pay monthly salaries","D":"Training guarantees employees never have to learn new software"},"correctOption":"B","correctAnswer":"Employees feel valued by the employer and gain mastery and confidence for future promotion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because investing in staff development signals long-term commitment and satisfies Herzberg's personal growth and advancement motivators.","distractor_reasons":{"A":"Incorrect because new qualifications expand career opportunities.","B":"Correct selection.","C":"Incorrect because employees still receive regular salaries.","D":"Incorrect because training specifically teaches new tools and skills."}}},{"id":"P1_U2_MCQ_261","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_261","question":"A retail bank removes two tiers of regional middle managers (delayering) to reduce salary overheads and speed up communication. What is a likely drawback of delayering for remaining managers?","options":{"A":"Chains of command become much longer and slower","B":"Middle-management salary costs double immediately","C":"Wider spans of control increase workload and stress while reducing promotion opportunities","D":"Branch staff lose all direct contact with senior executives"},"correctOption":"C","correctAnswer":"Wider spans of control increase workload and stress while reducing promotion opportunities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because removing management layers widens spans of control for surviving managers and removes intermediate career steps.","distractor_reasons":{"A":"Incorrect because delayering shortens the chain of command.","B":"Incorrect because cutting management tiers reduces managerial salary expenses.","C":"Correct selection.","D":"Incorrect because fewer layers bring staff closer to senior leadership."}}},{"id":"P1_U2_MCQ_262","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_262","question":"In an eight-tier department store conglomerate, a cashier's suggestion to fix a checkout barcode glitch passes through six supervisors and takes four months to reach IT. Which structural issue is illustrated?","options":{"A":"An overly flat organizational structure","B":"Excessive delegation to frontline cashiers","C":"Laissez-faire leadership at head office","D":"A long chain of command slowing upward communication and decision-making"},"correctOption":"D","correctAnswer":"A long chain of command slowing upward communication and decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tall hierarchies create long chains of command where messages must pass through many layers, causing delays.","distractor_reasons":{"A":"Incorrect because eight tiers represent a tall hierarchy, not a flat one.","B":"Incorrect because cashiers had no authority to fix the issue themselves.","C":"Incorrect because the delay stems from structural hierarchy layers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_263","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_263","question":"When a pressurized gas valve ruptures at a chemical refinery, the Safety Officer immediately issues strict, non-negotiable evacuation orders without consulting workers. Why is autocratic leadership appropriate here?","options":{"A":"Life-threatening emergencies require instant, decisive direction with zero debate","B":"Autocratic leadership always maximizes worker creativity during routine tasks","C":"Refinery workers are legally forbidden from ever sharing safety ideas","D":"Democratic voting is faster than a single emergency command"},"correctOption":"A","correctAnswer":"Life-threatening emergencies require instant, decisive direction with zero debate","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because crisis situations demand rapid, unambiguous command where consulting staff would waste critical seconds.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because autocratic leadership stifles creativity in routine work.","C":"Incorrect because safety committees regularly invite worker input during normal operations.","D":"Incorrect because group consultation takes longer than immediate instruction."}}},{"id":"P1_U2_MCQ_264","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_264","question":"Before redesigning its store workflow, a specialty coffee chain holds workshops asking baristas for ideas on espresso machine placement and peak-hour roles. What is an advantage of this democratic leadership style?","options":{"A":"Decisions are made in five seconds without any staff meetings","B":"Baristas feel valued and committed to the new workflow, and practical frontline insights improve the design","C":"Managers surrender all final responsibility for store profitability","D":"The company avoids paying baristas for hours spent in workshops"},"correctOption":"B","correctAnswer":"Baristas feel valued and committed to the new workflow, and practical frontline insights improve the design","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because democratic consultation taps into frontline expertise and builds employee buy-in and motivation.","distractor_reasons":{"A":"Incorrect because consultation takes more time than autocratic decrees.","B":"Correct selection.","C":"Incorrect because managers still retain ultimate accountability.","D":"Incorrect because staff are paid for time spent in workplace meetings."}}},{"id":"P1_U2_MCQ_265","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_265","question":"At the end of each month, a Hotel General Manager compares actual housekeeping labor hours against budgeted targets and investigates why overtime exceeded forecast. Which management function is this?","options":{"A":"External recruitment","B":"Informal grapevine networking","C":"Controlling (monitoring performance against targets and taking corrective action)","D":"Collective bargaining"},"correctOption":"C","correctAnswer":"Controlling (monitoring performance against targets and taking corrective action)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because controlling involves measuring actual performance against planned standards and correcting deviations.","distractor_reasons":{"A":"Incorrect because external recruitment hires new applicants.","B":"Incorrect because this is formal financial monitoring.","C":"Correct selection.","D":"Incorrect because collective bargaining negotiates union agreements."}}},{"id":"P1_U2_MCQ_266","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_266","question":"During a pay dispute, airline baggage handlers refuse all voluntary overtime and follow every safety checklist to the letter, slowing flight departures without losing their basic pay. What type of industrial action is this?","options":{"A":"An all-out indefinite strike","B":"Employer lockout","C":"Statutory redundancy","D":"Work-to-rule"},"correctOption":"D","correctAnswer":"Work-to-rule","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because work-to-rule involves employees strictly performing only their contracted duties and rules, slowing output while still being paid.","distractor_reasons":{"A":"Incorrect because striking workers withdraw their labor completely and lose wages.","B":"Incorrect because a lockout is initiated by the employer closing the workplace.","C":"Incorrect because redundancy is job elimination by the employer.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_267","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_267","question":"Six hundred bus drivers belong to a transport trade union that negotiates annual wage increases and rest-break rules with management on their behalf. What is the main benefit of union membership for drivers?","options":{"A":"Collective bargaining gives workers greater negotiating strength and legal representation than acting alone","B":"Union membership exempts drivers from obeying traffic speed limits","C":"Drivers never have to pay monthly union membership subscriptions","D":"Union membership guarantees the bus company can never make a loss"},"correctOption":"A","correctAnswer":"Collective bargaining gives workers greater negotiating strength and legal representation than acting alone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'strength in numbers' enables unions to negotiate better pay, conditions, and legal protection than individual workers could achieve.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because traffic laws apply to all drivers.","C":"Incorrect because union members pay regular membership dues.","D":"Incorrect because unions do not control passenger demand or company profitability."}}},{"id":"P1_U2_MCQ_268","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_268","question":"An HR Specialist advises a Factory Production Manager on legal disciplinary steps for persistent lateness, but has no authority to give direct orders to factory machinists. What role does the HR Specialist hold?","options":{"A":"Chief Executive Officer","B":"A staff (advisory/functional) manager supporting line managers","C":"An external trade union shop steward","D":"A piece-rate production operative"},"correctOption":"B","correctAnswer":"A staff (advisory/functional) manager supporting line managers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because staff managers provide specialist advice and support to line managers, who hold direct chain-of-command authority over operational workers.","distractor_reasons":{"A":"Incorrect because the CEO sits at the top of the entire line hierarchy.","B":"Correct selection.","C":"Incorrect because a shop steward represents unionized employees.","D":"Incorrect because production operatives work on the factory floor."}}},{"id":"P1_U2_MCQ_269","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_269","question":"The founder of a rapidly growing bakery insists on personally approving every routine flour order and delivery route, working 75 hours a week. Why are many managers reluctant to delegate?","options":{"A":"Delegation is illegal in food manufacturing businesses","B":"Delegation permanently transfers legal ownership of the business to subordinates","C":"Managers fear subordinates may make costly mistakes for which the manager remains ultimately accountable","D":"Delegation requires paying subordinates double their normal salary"},"correctOption":"C","correctAnswer":"Managers fear subordinates may make costly mistakes for which the manager remains ultimately accountable","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because managers often lack trust in subordinates' readiness and worry about being held responsible if delegated tasks go wrong.","distractor_reasons":{"A":"Incorrect because delegation is standard practice across all industries.","B":"Incorrect because delegation assigns task authority, not business ownership.","C":"Correct selection.","D":"Incorrect because delegation does not require doubling salaries."}}},{"id":"P1_U2_MCQ_270","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_270","question":"A global fast-food chain grants country directors in India, Japan, and Brazil authority to adapt local menu items and run regional promotions without head-office approval. Which organizational approach is this?","options":{"A":"Strict head-office centralization","B":"Autocratic micromanagement","C":"Job enlargement","D":"Decentralization"},"correctOption":"D","correctAnswer":"Decentralization","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because decentralization disperses decision-making authority to regional or branch managers so they can respond quickly to local market tastes.","distractor_reasons":{"A":"Incorrect because centralization keeps all key decisions at head office.","B":"Incorrect because granting local autonomy is the opposite of micromanagement.","C":"Incorrect because job enlargement adds peer-level tasks to an individual job.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_271","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_271","question":"Before advertising a vacancy, HR writes a document listing the job title ('Logistics Coordinator'), reporting line, daily duties, and working hours. Which recruitment document is this?","options":{"A":"Job description","B":"Person specification","C":"Curriculum vitae (CV)","D":"Letter of reference"},"correctOption":"A","correctAnswer":"Job description","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a job description outlines the tasks, responsibilities, working conditions, and reporting structure of the role itself.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a person specification lists the qualifications, skills, and qualities required of the applicant.","C":"Incorrect because a CV is submitted by an applicant.","D":"Incorrect because a reference is written by a past employer."}}},{"id":"P1_U2_MCQ_272","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_272","question":"A cybersecurity firm states in its recruitment paperwork: 'Essential: Degree in Computer Science and 3 years network security experience; Desirable: Financial sector background.' How is this person specification used?","options":{"A":"To calculate the firm's annual corporate tax liability","B":"To screen applications objectively and shortlist candidates matching the required qualifications and skills","C":"To inform new hires about fire-exit locations during induction","D":"To replace the written contract of employment"},"correctOption":"B","correctAnswer":"To screen applications objectively and shortlist candidates matching the required qualifications and skills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the person specification defines the ideal candidate profile so HR can fairly filter applicants for interview.","distractor_reasons":{"A":"Incorrect because tax calculations belong to finance/accounting.","B":"Correct selection.","C":"Incorrect because safety tours happen during post-hire induction.","D":"Incorrect because a formal employment contract is still required upon hiring."}}},{"id":"P1_U2_MCQ_273","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_273","question":"A supermarket chain promotes an experienced Deputy Store Manager to Store Manager rather than hiring externally. What is a primary advantage of this internal recruitment decision?","options":{"A":"It brings completely unfamiliar ideas from rival supermarkets","B":"It avoids creating any vacancy lower down in the store","C":"The candidate's work ethic and abilities are already proven, and promotion motivates junior staff","D":"External advertising agencies receive larger commission fees"},"correctOption":"C","correctAnswer":"The candidate's work ethic and abilities are already proven, and promotion motivates junior staff","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal promotion lowers hiring risk (known performance), saves external ad fees, and shows staff a clear career path.","distractor_reasons":{"A":"Incorrect because fresh outside ideas come from external recruitment.","B":"Incorrect because promoting a deputy leaves the deputy role vacant to be filled.","C":"Correct selection.","D":"Incorrect because internal recruitment avoids external agency fees."}}},{"id":"P1_U2_MCQ_274","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_274","question":"After receiving 260 applications for two graduate trainee roles, HR compares CVs against the person specification to select 10 candidates to invite for interviews. What is this stage called?","options":{"A":"Induction orientation","B":"External headhunting","C":"Job analysis","D":"Shortlisting"},"correctOption":"D","correctAnswer":"Shortlisting","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shortlisting narrows a large pool of applicants down to the strongest candidates for final selection.","distractor_reasons":{"A":"Incorrect because induction occurs after a job offer is accepted.","B":"Incorrect because headhunting approaches passive senior executives.","C":"Incorrect because job analysis happens before advertising the vacancy.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_275","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_275","question":"An engineering consultancy asks shortlisted graduate applicants to complete numerical reasoning and spatial aptitude tests alongside interviews. Why do employers use aptitude tests?","options":{"A":"They provide objective evidence of specific cognitive and technical skills that interviews alone may miss","B":"They are free to administer and guarantee zero staff turnover","C":"They replace the need to check candidate references","D":"They assess a candidate's physical fitness for heavy lifting"},"correctOption":"A","correctAnswer":"They provide objective evidence of specific cognitive and technical skills that interviews alone may miss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standardized aptitude tests measure actual problem-solving ability rather than relying solely on interview charm.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial aptitude tests cost money and cannot guarantee retention.","C":"Incorrect because reference checks remain vital.","D":"Incorrect because numerical/spatial tests measure cognitive aptitude, not physical strength."}}},{"id":"P1_U2_MCQ_276","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_276","question":"A hospital uses a three-person interview panel (HR Manager, Chief Surgeon, and Ward Matron) asking standardized questions to each nurse applicant. What is an advantage of panel interviews?","options":{"A":"Panel interviews take less total staff time than a single 10-minute chat","B":"Multiple interviewers reduce individual personal bias and assess clinical and interpersonal fit from varied angles","C":"Candidates feel far less nervous facing three interviewers than one","D":"Panel interviews eliminate the need for a person specification"},"correctOption":"B","correctAnswer":"Multiple interviewers reduce individual personal bias and assess clinical and interpersonal fit from varied angles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scoring by several specialists produces fairer, more balanced hiring decisions than a single interviewer.","distractor_reasons":{"A":"Incorrect because involving three senior staff consumes more combined management hours.","B":"Correct selection.","C":"Incorrect because candidates often find panels more intimidating than one-to-one chats.","D":"Incorrect because standardized questions are derived from the person specification."}}},{"id":"P1_U2_MCQ_277","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_277","question":"A multiplex cinema experiences 75% of its ticket sales on Friday nights, Saturdays, and Sundays. Why is hiring part-time ushers advantageous for the cinema?","options":{"A":"Part-time ushers are legally exempt from minimum wage laws","B":"Part-time ushers require zero health and safety training","C":"The cinema can match staffing hours to weekend peaks without paying idle full-time staff on quiet weekday mornings","D":"Part-time staff never resign for other jobs"},"correctOption":"C","correctAnswer":"The cinema can match staffing hours to weekend peaks without paying idle full-time staff on quiet weekday mornings","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because part-time contracts give businesses flexible labor scheduling during fluctuating customer demand.","distractor_reasons":{"A":"Incorrect because statutory minimum wage laws apply equally to part-time workers.","B":"Incorrect because all workers require fire and safety induction.","C":"Correct selection.","D":"Incorrect because part-time turnover can actually be higher."}}},{"id":"P1_U2_MCQ_278","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_278","question":"A local food-packing plant needs to hire 15 general warehouse operatives quickly with minimal recruitment expenditure. Which recruitment channel is most suitable?","options":{"A":"An international executive headhunting agency","B":"A full-page advertisement in a global financial newspaper","C":"Sponsoring a university aerospace engineering conference","D":"A local government job center and local online job boards"},"correctOption":"D","correctAnswer":"A local government job center and local online job boards","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because job centers and local portals reach local semi-skilled jobseekers rapidly at very low or zero cost.","distractor_reasons":{"A":"Incorrect because headhunters are expensive and target scarce senior executives.","B":"Incorrect because national financial press is costly and targets corporate executives.","C":"Incorrect because aerospace conferences target specialized engineers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_279","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_279","question":"A fine-dining restaurant asks shortlisted pastry chef candidates to bake two signature desserts in its kitchen during the selection process. Why is a practical skills test effective here?","options":{"A":"It directly demonstrates technical culinary competence, speed, and hygiene standards under realistic kitchen pressure","B":"It eliminates the need to verify whether the candidate has a legal right to work","C":"It allows the restaurant to sell candidates' test dishes without paying them a salary","D":"It replaces the need for an employment contract after hiring"},"correctOption":"A","correctAnswer":"It directly demonstrates technical culinary competence, speed, and hygiene standards under realistic kitchen pressure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because work-sample tests verify real practical ability rather than relying solely on claims written on a CV.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because right-to-work checks are mandatory.","C":"Incorrect because practical tests are assessment exercises, not free labor.","D":"Incorrect because a written contract is still legally required."}}},{"id":"P1_U2_MCQ_280","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_280","question":"To save time, a logistics firm skips reference checks and hires an unqualified transport coordinator who causes missed deliveries and resigns within two months. What is the main cost to the firm?","options":{"A":"Lower statutory corporate tax rates","B":"Repeated advertising, interviewing, and induction expenses alongside lost customer goodwill","C":"Permanent elimination of HR department salaries","D":"Automatic government grants for high staff turnover"},"correctOption":"B","correctAnswer":"Repeated advertising, interviewing, and induction expenses alongside lost customer goodwill","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because poor selection leads to early turnover, forcing the business to pay recruitment and training costs all over again.","distractor_reasons":{"A":"Incorrect because corporate tax rates are unaffected.","B":"Correct selection.","C":"Incorrect because HR workload actually increases.","D":"Incorrect because governments do not reward high turnover with grants."}}},{"id":"P1_U2_MCQ_281","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_281","question":"On their first morning at a pharmaceutical plant, new hires tour the facility, meet their team leader, learn emergency alarm rules, and set up payroll details. Which type of training is this?","options":{"A":"Off-the-job university degree training","B":"Redundancy retraining","C":"Induction training","D":"Executive headhunting"},"correctOption":"C","correctAnswer":"Induction training","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because induction training introduces new employees to the workplace layout, colleagues, rules, and safety procedures.","distractor_reasons":{"A":"Incorrect because university courses are external off-the-job qualifications.","B":"Incorrect because these are newly hired employees.","C":"Correct selection.","D":"Incorrect because headhunting is a recruitment method."}}},{"id":"P1_U2_MCQ_282","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_282","question":"A busy specialty coffee shop trains a newly hired barista by having them shadow and assist the head barista behind the counter during morning shifts. What is a primary benefit of on-the-job training?","options":{"A":"The trainee learns in a quiet external college classroom away from customers","B":"External training providers charge high daily tuition fees","C":"The head barista's customer service speed never slows down during coaching","D":"It is relatively inexpensive and the trainee contributes to output while learning on actual equipment"},"correctOption":"D","correctAnswer":"It is relatively inexpensive and the trainee contributes to output while learning on actual equipment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job training avoids external course fees and allows trainees to produce useful work during training.","distractor_reasons":{"A":"Incorrect because external classrooms describe off-the-job training.","B":"Incorrect because internal on-the-job coaching avoids external provider fees.","C":"Incorrect because supervising a trainee temporarily slows down the experienced mentor.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_283","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_283","question":"An airline sends newly recruited pilots to a specialized off-site flight-simulator center for six months before flying commercial passengers. Why is off-the-job training essential here?","options":{"A":"Pilots can safely practice rare engine-failure emergencies without endangering passengers or aircraft","B":"Off-the-job simulator training costs less than watching a coworker on a live flight","C":"Simulator training generates immediate passenger ticket revenue","D":"Pilots do not need any practical flying skills"},"correctOption":"A","correctAnswer":"Pilots can safely practice rare engine-failure emergencies without endangering passengers or aircraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-risk professions require controlled off-the-job environments where mistakes carry zero real-world danger.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flight simulators are very expensive.","C":"Incorrect because trainees produce no commercial output during off-the-job training.","D":"Incorrect because simulator training builds intensive practical flying skills."}}},{"id":"P1_U2_MCQ_284","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_284","question":"An HR Director forecasts upcoming staff retirements, expansion into three new stores, and new self-checkout technology over the next three years to determine hiring and retraining needs. What is this process?","options":{"A":"Summary dismissal","B":"Workforce planning","C":"Collective bargaining","D":"Piece-rate wage setting"},"correctOption":"B","correctAnswer":"Workforce planning","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because workforce planning assesses the number and skills of employees a business will need in the future.","distractor_reasons":{"A":"Incorrect because dismissal terminates an individual for misconduct.","B":"Correct selection.","C":"Incorrect because collective bargaining is union-management negotiation.","D":"Incorrect because piece-rate is a payment method."}}},{"id":"P1_U2_MCQ_285","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_285","question":"A commercial truck driver is terminated immediately after failing a mandatory workplace alcohol test while on duty, breaching safety rules. How is this termination classified?","options":{"A":"Voluntary redundancy","B":"Natural wastage","C":"Dismissal for gross misconduct","D":"Internal job rotation"},"correctOption":"C","correctAnswer":"Dismissal for gross misconduct","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dismissal ends employment due to the employee's own serious breach of rules or misconduct (unlike redundancy, where the job disappears).","distractor_reasons":{"A":"Incorrect because redundancy occurs when the job role itself is no longer needed.","B":"Incorrect because natural wastage occurs when employees retire or resign voluntarily.","C":"Correct selection.","D":"Incorrect because job rotation moves workers between tasks."}}},{"id":"P1_U2_MCQ_286","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_286","question":"A warehouse operator with three years' clean service is fired without warning solely because she joined a legally recognized trade union. Which legal claim can she bring against the employer?","options":{"A":"Breach of piece-rate bonus rules","B":"Statutory redundancy entitlement","C":"Violation of span-of-control limits","D":"Unfair dismissal"},"correctOption":"D","correctAnswer":"Unfair dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because firing an employee for lawful trade union membership or without fair disciplinary procedure constitutes unfair dismissal.","distractor_reasons":{"A":"Incorrect because the issue is unlawful termination, not bonus calculation.","B":"Incorrect because her job was not eliminated; she was fired for union membership.","C":"Incorrect because spans of control are management choices, not laws.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_287","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_287","question":"The government raises the statutory national minimum wage by 12%, affecting a fast-food chain employing 900 entry-level crew members. How might the business respond to higher wage costs?","options":{"A":"Invest in self-service ordering kiosks, raise menu prices slightly, or improve staff productivity and retention","B":"Continue paying existing crew below the new legal minimum wage","C":"Replace all written contracts with verbal agreements to bypass the law","D":"Deduct the 12% pay rise from employees' statutory holiday pay"},"correctOption":"A","correctAnswer":"Invest in self-service ordering kiosks, raise menu prices slightly, or improve staff productivity and retention","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher minimum wages raise labor costs, prompting firms to boost productivity, automate routine tasks, or adjust prices while benefiting from lower turnover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying below the statutory minimum wage is illegal.","C":"Incorrect because minimum wage laws apply regardless of whether contracts are written or verbal.","D":"Incorrect because statutory holiday pay is legally protected."}}},{"id":"P1_U2_MCQ_288","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_288","question":"A maintenance technician earns $18.00 per hour for a standard 38-hour week, and overtime is paid at 1.5 times the basic hourly rate. If the technician works 44 hours in a week, what is their gross weekly pay?","options":{"A":"$792.00","B":"$846.00","C":"$1,188.00","D":"$828.00"},"correctOption":"B","correctAnswer":"$846.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because basic pay = 38 × $18.00 = $684.00, overtime = 6 hours × ($18.00 × 1.5 = $27.00) = $162.00, and total pay = $846.00.","distractor_reasons":{"A":"Incorrect because $792.00 pays all 44 hours at the basic $18.00 rate without the overtime premium.","B":"Correct selection.","C":"Incorrect because $1,188.00 pays all 44 hours at the overtime rate of $27.00.","D":"Incorrect arithmetic."}}},{"id":"P1_U2_MCQ_289","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_289","question":"An automotive plant installs robotic welding arms, reducing required body-shop workers from 260 to 210 over two years. How can the firm reduce headcount gradually without compulsory redundancies?","options":{"A":"Dismiss 50 workers without notice or compensation","B":"Cut hourly wages below the legal minimum until 50 staff quit","C":"Use natural wastage (not replacing retiring or resigning staff) alongside voluntary retraining into other departments","D":"Ban all employees from taking annual leave"},"correctOption":"C","correctAnswer":"Use natural wastage (not replacing retiring or resigning staff) alongside voluntary retraining into other departments","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because natural wastage and internal redeployment lower workforce size smoothly while preserving morale and avoiding redundancy payouts.","distractor_reasons":{"A":"Incorrect because summary dismissal without cause is unlawful unfair dismissal.","B":"Incorrect because cutting pay below statutory minimums is illegal.","C":"Correct selection.","D":"Incorrect because statutory paid leave is legally mandated."}}},{"id":"P1_U2_MCQ_290","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_290","question":"An IT consultancy rejects a highly qualified wheelchair-using software architect solely because of her physical disability, even though the office has elevators and the role is desk-based. Which law is breached?","options":{"A":"Minimum wage overtime regulations","B":"Trade union ballot notice laws","C":"Health and safety fire-drill frequency rules","D":"Anti-discrimination employment legislation"},"correctOption":"D","correctAnswer":"Anti-discrimination employment legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because anti-discrimination laws prohibit rejecting qualified candidates on grounds of disability, gender, race, religion, or age.","distractor_reasons":{"A":"Incorrect because no wage rate dispute occurred.","B":"Incorrect because union ballots are unrelated to hiring discrimination.","C":"Incorrect because this concerns equal opportunity in hiring.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_291","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_291","question":"A Finance Director emails audited annual accounts and a cash-flow forecast to the company's commercial bank manager to renew a credit line. How is this communication classified?","options":{"A":"Formal external communication","B":"Informal internal grapevine communication","C":"One-way visual advertising","D":"Upward internal staff feedback"},"correctOption":"A","correctAnswer":"Formal external communication","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sending official financial reports to an outside stakeholder (a bank) is formal external communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the bank manager is an external stakeholder and the report is official.","C":"Incorrect because financial statements to a lender are not consumer advertisements.","D":"Incorrect because the bank is outside the organization."}}},{"id":"P1_U2_MCQ_292","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_292","question":"A warehouse manager pins a printed notice on the canteen wall announcing new shift-swapping rules without holding a briefing. What is a drawback of this one-way written notice?","options":{"A":"It provides no permanent written record of the new rules","B":"There is no immediate feedback to confirm workers read and understood the rules or to answer questions","C":"Printing a single notice costs more than flying all staff to a conference","D":"Written notices are legally invalid inside warehouses"},"correctOption":"B","correctAnswer":"There is no immediate feedback to confirm workers read and understood the rules or to answer questions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because one-way communication lacks a feedback loop to verify comprehension or clarify ambiguities.","distractor_reasons":{"A":"Incorrect because a printed notice does create a written record.","B":"Correct selection.","C":"Incorrect because noticeboard posters are very cheap.","D":"Incorrect because noticeboards are valid internal channels."}}},{"id":"P1_U2_MCQ_293","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_293","question":"After a disciplinary hearing, an HR Manager issues a formal written warning letter stating required attendance targets and review dates. Why is written communication essential here?","options":{"A":"Written letters allow immediate facial-expression feedback","B":"Written warnings are faster than speaking in person","C":"It creates an exact, permanent legal record that can be referenced if further action is needed","D":"Written letters guarantee the employee will never be late again"},"correctOption":"C","correctAnswer":"It creates an exact, permanent legal record that can be referenced if further action is needed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because formal HR procedures require documented evidence proving clear standards and fair warnings were communicated.","distractor_reasons":{"A":"Incorrect because body language cues occur in face-to-face verbal meetings.","B":"Incorrect because drafting a formal letter takes longer than speaking.","C":"Correct selection.","D":"Incorrect because documentation supports fair procedure rather than guaranteeing behavior."}}},{"id":"P1_U2_MCQ_294","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_294","question":"A team leader notices a usually reliable engineer looking stressed and making errors, so she invites him for a private one-to-one conversation. Why is face-to-face verbal communication best here?","options":{"A":"It broadcasts the engineer's personal problems to the entire factory","B":"It automatically generates a signed legal contract","C":"It eliminates the need to listen to the engineer's reply","D":"It allows empathetic tone, body-language cues, and sensitive two-way discussion"},"correctOption":"D","correctAnswer":"It allows empathetic tone, body-language cues, and sensitive two-way discussion","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delicate personal or performance issues benefit from immediate two-way dialogue and non-verbal empathy.","distractor_reasons":{"A":"Incorrect because a private meeting protects confidentiality.","B":"Incorrect because spoken chats do not automatically create written contracts.","C":"Incorrect because effective two-way dialogue depends on active listening.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_295","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_295","question":"During a coffee break, a warehouse supervisor casually mentions to a sales rep that a major component delivery is delayed by snow, allowing the rep to warn clients early. What does this illustrate?","options":{"A":"Informal communication channels rapidly sharing practical operational updates across departments","B":"Formal downward communication from the Board of Directors","C":"External press-release marketing","D":"A communication barrier caused by autocratic leadership"},"correctOption":"A","correctAnswer":"Informal communication channels rapidly sharing practical operational updates across departments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because informal workplace conversations often transmit useful information faster than formal cross-departmental memos.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a breakroom chat is unofficial, not a board directive.","C":"Incorrect because the conversation happened internally between two staff members.","D":"Incorrect because the informal chat facilitated coordination rather than blocking it."}}},{"id":"P1_U2_MCQ_296","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_296","question":"An IT Manager sends an email full of technical acronyms ('DNS propagation, SSL handshake timeout, API latency') to non-technical store cashiers, who ignore it. Which barrier occurred?","options":{"A":"Physical factory machinery noise","B":"Use of technical jargon that receivers cannot understand or decode","C":"Lack of electronic email access","D":"Excessive use of visual charts and diagrams"},"correctOption":"B","correctAnswer":"Use of technical jargon that receivers cannot understand or decode","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because specialist jargon alienates non-specialist receivers and prevents accurate decoding of the message.","distractor_reasons":{"A":"Incorrect because the message was sent via email, not spoken over loud machinery.","B":"Correct selection.","C":"Incorrect because cashiers received the email.","D":"Incorrect because plain visuals would have helped clarify the message."}}},{"id":"P1_U2_MCQ_297","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_297","question":"A CEO's verbal instruction 'offer free coffee if lobby check-in exceeds 10 minutes' passes down six management tiers and reaches receptionists as 'give free dinners to all hotel guests'. Which barrier is this?","options":{"A":"External cultural differences with overseas suppliers","B":"Failure of electronic internet servers","C":"Message distortion caused by a long chain of command with too many intermediaries","D":"Lack of piece-rate financial incentives"},"correctOption":"C","correctAnswer":"Message distortion caused by a long chain of command with too many intermediaries","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because every extra hierarchy layer in a long chain of command increases the risk of Chinese-whispers distortion.","distractor_reasons":{"A":"Incorrect because this occurred internally within the hotel hierarchy.","B":"Incorrect because the instruction was passed verbally across tiers.","C":"Correct selection.","D":"Incorrect because pay methods do not cause verbal message distortion."}}},{"id":"P1_U2_MCQ_298","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_298","question":"Factory workers ignore management's newsletter promising 'future profit-sharing if productivity rises' because management previously broke promises on overtime pay. Which communication barrier is this?","options":{"A":"Wrong choice of paper color for the newsletter","B":"Excessively flat organizational structure","C":"Information overload from too many video calls","D":"Breakdown of trust and poor industrial relations causing receivers to disbelieve the sender"},"correctOption":"D","correctAnswer":"Breakdown of trust and poor industrial relations causing receivers to disbelieve the sender","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because attitudinal barriers and distrust cause employees to dismiss management messages regardless of how clearly they are written.","distractor_reasons":{"A":"Incorrect because formatting does not overcome broken trust.","B":"Incorrect because structural flatness is unrelated to broken promises.","C":"Incorrect because the issue was a printed newsletter, not video calls.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_299","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_299","question":"A retail chain posts urgent next-day shift changes exclusively on a mobile chat app at 10:00 PM, causing part-time staff without smartphones or who silence late alerts to miss shifts. What drawback is shown?","options":{"A":"Electronic messaging depends on receiver device access and risks missed alerts outside working hours","B":"Mobile chat apps are slower than sending international postal letters","C":"Electronic messages can never be read by more than one person","D":"Mobile apps permanently delete all messages after two seconds"},"correctOption":"A","correctAnswer":"Electronic messaging depends on receiver device access and risks missed alerts outside working hours","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying solely on late electronic alerts assumes constant connectivity and blurs work-life boundaries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because electronic messaging transmits instantaneously.","C":"Incorrect because group chats broadcast to many recipients.","D":"Incorrect because chat histories remain stored."}}},{"id":"P1_U2_MCQ_300","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_300","question":"An e-commerce retailer sends automated order confirmations, live parcel-tracking links, and fast live-chat support to shoppers. How does effective external communication benefit the retailer?","options":{"A":"It eliminates the need to hold any warehouse inventory","B":"It builds customer trust, reduces repetitive complaint calls, and encourages repeat purchases","C":"It allows the retailer to charge higher corporate tax rates","D":"It replaces internal communication between warehouse packers"},"correctOption":"B","correctAnswer":"It builds customer trust, reduces repetitive complaint calls, and encourages repeat purchases","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because proactive, accurate external communication enhances customer satisfaction, loyalty, and brand reputation.","distractor_reasons":{"A":"Incorrect because physical products still require inventory management.","B":"Correct selection.","C":"Incorrect because businesses do not choose their own tax rates.","D":"Incorrect because internal warehouse coordination is still required."}}},{"id":"P1_U2_MCQ_301","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_301","question":"A telecommunications call center offers its customer retention agents a 5% commission on every annual contract renewal they secure, on top of a modest base salary. What is a potential disadvantage of this commission structure?","options":{"A":"Agents may pressure reluctant customers into unsuitable plans, damaging long-term brand reputation","B":"Payroll expenses remain completely fixed even when contract renewals drop to zero","C":"Agents receive no extra reward when they work harder to close more renewals","D":"Commission payments eliminate the need to track individual sales figures"},"correctOption":"A","correctAnswer":"Agents may pressure reluctant customers into unsuitable plans, damaging long-term brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heavy commission incentives can encourage aggressive selling tactics that prioritize short-term payouts over genuine customer satisfaction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commission is a variable labor cost that falls when sales decline.","C":"Incorrect because commission directly rewards higher renewal volume.","D":"Incorrect because calculating commission requires accurate tracking of each agent's sales."}}},{"id":"P1_U2_MCQ_302","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_302","question":"A packaging factory introduces F.W. Taylor's piece-rate system after timing the fastest workers, setting a target of 80 boxes per hour. Why might older or newly hired operators oppose this approach?","options":{"A":"Piece-rate pay guarantees everyone identical weekly wages regardless of output","B":"Workers who cannot match the fastest benchmark suffer lower earnings and heightened physical stress","C":"Taylor's approach bans the use of specialized tools on assembly lines","D":"Piece-rate pay prevents skilled workers from earning more than slow workers"},"correctOption":"B","correctAnswer":"Workers who cannot match the fastest benchmark suffer lower earnings and heightened physical stress","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Taylorism ties pay strictly to individual physical speed, penalizing slower workers and creating anxiety over fluctuating income.","distractor_reasons":{"A":"Incorrect because piece-rate creates variable earnings based on individual output.","B":"Correct selection.","C":"Incorrect because Taylor advocated standardized tools and methods to maximize efficiency.","D":"Incorrect because fast workers earn higher wages under piece-rate."}}},{"id":"P1_U2_MCQ_303","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_303","question":"A construction company replaces short-term zero-hour casual agreements with permanent full-time contracts, safety helmets, and an occupational pension plan. Which level of Maslow's hierarchy is primarily satisfied?","options":{"A":"Self-actualization needs","B":"Esteem and status needs","C":"Safety and security needs","D":"Social friendship needs"},"correctOption":"C","correctAnswer":"Safety and security needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because stable employment contracts, workplace safety protection, and pension security fulfill Maslow's safety needs.","distractor_reasons":{"A":"Incorrect because self-actualization involves creative fulfillment and reaching full potential.","B":"Incorrect because esteem needs relate to recognition, promotion, and status.","C":"Correct selection.","D":"Incorrect because social needs involve teamwork and interpersonal belonging."}}},{"id":"P1_U2_MCQ_304","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_304","question":"A regional accounting firm struggles with low morale among junior clerks despite paying competitive salaries and providing modern air-conditioned offices. Based on Herzberg's theory, what should partners introduce next?","options":{"A":"Further increases to breakroom snack budgets","B":"Stricter dress-code rules and longer daily supervision logs","C":"Another minor inflation adjustment to basic monthly salaries","D":"Meaningful client-facing responsibilities, recognition for accuracy, and clear promotion pathways"},"correctOption":"D","correctAnswer":"Meaningful client-facing responsibilities, recognition for accuracy, and clear promotion pathways","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because once hygiene factors (pay and office conditions) are adequate, Herzberg states true motivation comes from achievement, recognition, responsibility, and advancement.","distractor_reasons":{"A":"Incorrect because office perks are hygiene factors that prevent dissatisfaction rather than motivating.","B":"Incorrect because heavy supervision and rigid policies can worsen dissatisfaction.","C":"Incorrect because Herzberg classifies pay as a hygiene factor rather than a long-term motivator.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_305","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_305","question":"A boutique hotel empowers front-desk receptionists to authorize complimentary room upgrades or meal vouchers up to $75 whenever a guest experiences a check-in delay. Which non-financial motivator is this?","options":{"A":"Delegation and empowerment","B":"Job rotation","C":"Piece-rate wage pricing","D":"Autocratic micromanagement"},"correctOption":"A","correctAnswer":"Delegation and empowerment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegating decision-making authority trusts frontline staff to solve customer problems independently, boosting motivation and job satisfaction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because job rotation switches workers between different tasks without necessarily adding authority.","C":"Incorrect because piece-rate is a financial payment per unit produced.","D":"Incorrect because micromanagement removes employee discretion."}}},{"id":"P1_U2_MCQ_306","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_306","question":"A clothing manufacturer pays garment finishers a basic wage of $320 per week plus a piece-rate bonus of $1.40 for every coat finished above 150 coats. If a finisher completes 215 coats in a week, what is their gross weekly pay?","options":{"A":"$621.00","B":"$411.00","C":"$301.00","D":"$530.00"},"correctOption":"B","correctAnswer":"$411.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because extra coats above threshold = 215 − 150 = 65 coats; bonus = 65 × $1.40 = $91.00; total pay = $320.00 + $91.00 = $411.00.","distractor_reasons":{"A":"Incorrect because $621.00 pays the $1.40 piece-rate on all 215 coats ($301) on top of the $320 base.","B":"Correct selection.","C":"Incorrect because $301.00 multiplies all 215 coats by $1.40 and omits the $320 base wage.","D":"Incorrect arithmetic."}}},{"id":"P1_U2_MCQ_307","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_307","question":"A mid-sized engineering company introduces a profit-sharing bonus paid once every December, but notices factory productivity barely changes during spring and summer. Why is the motivational impact weak early in the year?","options":{"A":"Engineers are legally forbidden from receiving year-end bonuses","B":"Profit-sharing permanently reduces workers' basic hourly pay","C":"The reward is too distant in time from daily effort and depends on overall company profit rather than individual output","D":"Profit-sharing forces workers to buy company shares at above-market prices"},"correctOption":"C","correctAnswer":"The reward is too distant in time from daily effort and depends on overall company profit rather than individual output","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because annual profit-sharing has a delayed link between daily effort and payout, and individual workers feel little direct control over total annual profit.","distractor_reasons":{"A":"Incorrect because engineers can legally participate in profit-sharing schemes.","B":"Incorrect because profit-sharing is paid on top of regular wages or salaries.","C":"Correct selection.","D":"Incorrect because profit-sharing distributes profits rather than forcing expensive share purchases."}}},{"id":"P1_U2_MCQ_308","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_308","question":"An e-commerce fulfillment warehouse introduces cross-functional 'quality circles' where packers, pickers, and forklift drivers meet weekly to solve shipping bottlenecks. Which motivational need does this fulfill?","options":{"A":"Basic physiological food and shelter needs","B":"Statutory minimum wage protection","C":"Autocratic compliance with top-down orders","D":"Social belonging and esteem through teamwork and having ideas valued by management"},"correctOption":"D","correctAnswer":"Social belonging and esteem through teamwork and having ideas valued by management","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because collaborative problem-solving satisfies social needs (Elton Mayo/Maslow) and boosts esteem when management acts on worker suggestions.","distractor_reasons":{"A":"Incorrect because physiological needs are met via basic wages.","B":"Incorrect because minimum wage is a legal baseline, not a quality-circle benefit.","C":"Incorrect because quality circles rely on employee participation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_309","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_309","question":"A retail pharmacy chain offers store managers private medical insurance, a subsidized gym membership, and an employee merchandise discount instead of raising taxable cash salaries. What is an advantage of these fringe benefits?","options":{"A":"They strengthen staff loyalty and wellbeing while often being cost-effective for the employer to provide in bulk","B":"They completely replace the legal requirement to pay basic monthly salaries","C":"They guarantee zero absenteeism across every pharmacy branch","D":"They allow the pharmacy to ignore statutory overtime rules"},"correctOption":"A","correctAnswer":"They strengthen staff loyalty and wellbeing while often being cost-effective for the employer to provide in bulk","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because corporate perks improve retention and recruitment appeal while costing the firm less per employee than equivalent cash raises.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because perks supplement regular cash salaries.","C":"Incorrect because perks reduce turnover and sick days rather than eliminating all absence.","D":"Incorrect because employment laws remain binding."}}},{"id":"P1_U2_MCQ_310","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_310","question":"A bank redesigns loan-officer roles so each officer handles a client's application from initial consultation through credit assessment to final approval, rather than processing isolated forms. Which job design concept is this?","options":{"A":"Job rotation across identical clerical desks","B":"Job enrichment creating complete, meaningful units of work with greater responsibility","C":"Taylorist division of labor into micro-tasks","D":"Horizontal job enlargement without extra authority"},"correctOption":"B","correctAnswer":"Job enrichment creating complete, meaningful units of work with greater responsibility","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because giving an employee end-to-end ownership and decision-making authority over a complete process is a classic form of job enrichment.","distractor_reasons":{"A":"Incorrect because rotation moves staff between separate jobs.","B":"Correct selection.","C":"Incorrect because Taylorism breaks jobs into tiny repetitive fragments.","D":"Incorrect because approving loans adds higher-level authority, which is enrichment rather than mere enlargement."}}},{"id":"P1_U2_MCQ_311","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_311","question":"In a manufacturing company's organizational chart, solid vertical lines connect the Operations Director to three Factory Managers, and each Factory Manager to five Shift Supervisors. What do these vertical lines represent?","options":{"A":"Informal breakroom friendships between employees","B":"External trade union negotiation channels","C":"The formal chain of command showing lines of authority and reporting accountability","D":"Customer complaint hotline routes"},"correctOption":"C","correctAnswer":"The formal chain of command showing lines of authority and reporting accountability","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because vertical lines on an organizational chart depict the formal chain of command through which instructions flow down and accountability flows up.","distractor_reasons":{"A":"Incorrect because informal social networks are not mapped on formal org charts.","B":"Incorrect because trade unions are independent employee organizations.","C":"Correct selection.","D":"Incorrect because org charts map internal employee hierarchy, not external customer hotlines."}}},{"id":"P1_U2_MCQ_312","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_312","question":"A supermarket regional manager oversees 18 store managers across a wide geographic territory, leaving little time to coach newly appointed store managers. Which organizational problem is occurring?","options":{"A":"The chain of command has too many intermediate vice-presidents","B":"The span of control is too wide for effective supervision and support","C":"The business is overly centralized at the checkout level","D":"Autocratic leadership prevents store managers from opening their stores"},"correctOption":"B","correctAnswer":"The span of control is too wide for effective supervision and support","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because supervising 18 geographically dispersed managers exceeds a practical span of control, reducing guidance and control.","distractor_reasons":{"A":"Incorrect because wide spans occur when there are few intermediate layers.","B":"Correct selection.","C":"Incorrect because wide spans typically accompany decentralized autonomy.","D":"Incorrect because the problem is insufficient managerial capacity to supervise 18 direct reports."}}},{"id":"P1_U2_MCQ_313","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_313","question":"A rapidly growing fashion retailer reorganizes from a functional structure (Marketing, Finance, Operations) into regional divisions (North America, Europe, Asia-Pacific) as overseas tastes diverge. Why does a regional structure help?","options":{"A":"It eliminates all duplicate marketing roles across continents","B":"It prevents regional managers from making any local pricing adjustments","C":"Each division can tailor product ranges and promotions quickly to local cultural and seasonal demand","D":"It removes the need for a Chief Executive Officer"},"correctOption":"C","correctAnswer":"Each division can tailor product ranges and promotions quickly to local cultural and seasonal demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because geographical divisions enable faster responsiveness to local market preferences and regulations.","distractor_reasons":{"A":"Incorrect because regional divisions often duplicate functional specialists, raising overhead costs.","B":"Incorrect because regional structures empower local adaptation.","C":"Correct selection.","D":"Incorrect because a CEO still oversees the entire company."}}},{"id":"P1_U2_MCQ_314","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_314","question":"A Logistics Director notices delivery fuel costs are rising, so she brings warehouse supervisors, drivers, and route planners together to align schedules and resolve bottlenecks. Which Fayol management function is this?","options":{"A":"External auditing","B":"Statutory redundancy consultation","C":"Job rotation","D":"Coordinating (integrating activities across teams so departments work smoothly toward common goals)"},"correctOption":"D","correctAnswer":"Coordinating (integrating activities across teams so departments work smoothly toward common goals)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because coordinating ensures different operational groups harmonize their efforts rather than working at cross-purposes.","distractor_reasons":{"A":"Incorrect because external auditing checks financial statements.","B":"Incorrect because no jobs are being eliminated.","C":"Incorrect because job rotation swaps individual workers between stations.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_315","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_315","question":"A family-owned manufacturing firm's Managing Director treats workers like extended family—providing interest-free hardship loans and subsidized meals—while making all major business decisions himself. Which leadership style is this?","options":{"A":"Paternalistic leadership","B":"Laissez-faire leadership","C":"Democratic consensus leadership","D":"Collective trade union bargaining"},"correctOption":"A","correctAnswer":"Paternalistic leadership","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paternalistic leaders act like a 'father figure'—caring for employee welfare and loyalty while retaining centralized decision-making power.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because laissez-faire leaders leave employees to make their own decisions.","C":"Incorrect because democratic leaders share decision-making power with staff.","D":"Incorrect because collective bargaining is union-employer negotiation."}}},{"id":"P1_U2_MCQ_316","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_316","question":"During a severe cash-flow crisis, a software company must cut operating expenses within 48 hours to avoid insolvency. Why might the CEO temporarily adopt an autocratic style instead of a democratic one?","options":{"A":"Autocratic leadership always produces higher long-term employee creativity","B":"Urgent survival decisions require immediate action without lengthy consultation meetings","C":"Employees are legally prohibited from voting during financial downturns","D":"Democratic leadership cannot be used in technology firms"},"correctOption":"B","correctAnswer":"Urgent survival decisions require immediate action without lengthy consultation meetings","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because crisis turnarounds require rapid, decisive leadership when time is too short for broad consultation.","distractor_reasons":{"A":"Incorrect because autocratic leadership usually lowers creativity.","B":"Correct selection.","C":"Incorrect because no such legal prohibition exists.","D":"Incorrect because tech firms frequently use democratic styles during normal operations."}}},{"id":"P1_U2_MCQ_317","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_317","question":"An automotive assembly plant signs a 'single-union agreement' recognizing one trade union to represent all 1,200 shop-floor technicians. How does a single-union agreement help management?","options":{"A":"It guarantees technicians can never go on strike under any circumstances","B":"It allows management to pay below the statutory minimum wage","C":"Management avoids conflicting demands and inter-union disputes by negotiating with one unified body","D":"It transfers responsibility for factory quality control to union officials"},"correctOption":"C","correctAnswer":"Management avoids conflicting demands and inter-union disputes by negotiating with one unified body","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dealing with one union simplifies collective bargaining and prevents rival unions from competing with escalating pay demands.","distractor_reasons":{"A":"Incorrect because a single union can still ballot members for lawful industrial action.","B":"Incorrect because minimum wage laws remain strictly enforceable.","C":"Correct selection.","D":"Incorrect because operations management remains responsible for quality control."}}},{"id":"P1_U2_MCQ_318","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_318","question":"After wage talks stall, unionized dockworkers stage a 48-hour strike, halting container loading at a major port. What is a direct financial consequence for the striking workers?","options":{"A":"They receive double overtime pay from the port operator during the strike","B":"They are automatically promoted to supervisory roles","C":"They receive full normal salaries plus profit-sharing bonuses while not working","D":"They lose wages for the days they withhold their labor, risking financial hardship"},"correctOption":"D","correctAnswer":"They lose wages for the days they withhold their labor, risking financial hardship","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employers do not pay wages during a strike, meaning workers sacrifice income to exert bargaining pressure.","distractor_reasons":{"A":"Incorrect because striking workers are not paid by the employer during work stoppages.","B":"Incorrect because strikes do not grant automatic promotions.","C":"Incorrect because wages stop during a strike.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_319","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_319","question":"A Marketing Director delegates social-media campaign scheduling to a junior coordinator, but fails to provide brand guidelines or check the posts before launch, resulting in an embarrassing public typo. What went wrong?","options":{"A":"The director confused delegation with abdication—failing to provide clear parameters, support, and monitoring","B":"Delegation is never allowed in marketing departments","C":"The junior coordinator is now legally the sole owner of the company","D":"Delegation requires removing all brand guidelines"},"correctOption":"A","correctAnswer":"The director confused delegation with abdication—failing to provide clear parameters, support, and monitoring","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective delegation requires clear instructions, appropriate training/resources, and periodic oversight—not abandoning responsibility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delegation is widely used in marketing.","C":"Incorrect because delegation assigns task authority, not company ownership.","D":"Incorrect because clear guidelines are essential for successful delegation."}}},{"id":"P1_U2_MCQ_320","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_320","question":"A national chain of 90 dental clinics centralizes clinical hygiene protocols and bulk equipment purchasing at head office, while decentralizing local appointment scheduling and community outreach to clinic managers. Why is this hybrid structure effective?","options":{"A":"It eliminates all head-office managers and all clinic managers","B":"It combines safety consistency and bulk-buying savings with local customer responsiveness","C":"It prevents clinics from booking patient appointments locally","D":"It forces every clinic to buy medical supplies individually at retail prices"},"correctOption":"B","correctAnswer":"It combines safety consistency and bulk-buying savings with local customer responsiveness","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because centralizing high-risk standards and procurement captures economies of scale, while decentralizing day-to-day operations keeps clinics agile.","distractor_reasons":{"A":"Incorrect because both head-office and local managers play distinct roles.","B":"Correct selection.","C":"Incorrect because local scheduling is decentralized to the clinics.","D":"Incorrect because bulk purchasing is centralized at head office."}}},{"id":"P1_U2_MCQ_321","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_321","question":"A supermarket chain advertises a vacant Store Manager post on its internal staff intranet before posting externally. Which benefit does internal advertising offer over external advertising?","options":{"A":"It attracts hundreds of applicants from rival supermarket chains","B":"It requires zero induction or handover time in any department","C":"It saves external recruitment agency fees and shortens the selection timeline","D":"It guarantees no other internal vacancy will be created"},"correctOption":"C","correctAnswer":"It saves external recruitment agency fees and shortens the selection timeline","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal recruitment avoids costly external media/agency charges and candidates are already known to HR.","distractor_reasons":{"A":"Incorrect because an internal intranet is only visible to current employees.","B":"Incorrect because promoted staff still need role-specific handover.","C":"Correct selection.","D":"Incorrect because promoting an existing employee leaves their previous post vacant."}}},{"id":"P1_U2_MCQ_322","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_322","question":"A small family bakery has always promoted from within, but sales are stagnating because staff rely on outdated recipes and manual bookkeeping. Why should the bakery recruit externally for its new Operations Manager?","options":{"A":"External candidates already know the bakery's secret family recipes","B":"External recruitment is always cheaper than promoting an existing baker","C":"External hires never require a written contract of employment","D":"External recruitment brings fresh commercial ideas, modern digital skills, and outside industry experience"},"correctOption":"D","correctAnswer":"External recruitment brings fresh commercial ideas, modern digital skills, and outside industry experience","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because external recruitment injects new perspectives and specialist skills that do not currently exist inside the organization.","distractor_reasons":{"A":"Incorrect because external candidates must learn internal company practices.","B":"Incorrect because external recruitment is typically more expensive than internal promotion.","C":"Incorrect because all employees require employment contracts.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_323","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_323","question":"When drafting recruitment materials for a Bilingual Customer Support Lead, HR distinguishes between daily duties (answering escalated queries, mentoring four agents) and candidate traits (fluency in Spanish, calm temperament). Which two documents are being prepared?","options":{"A":"Job description and person specification","B":"Curriculum vitae and reference letter","C":"Contract of employment and redundancy notice","D":"Organizational chart and balance sheet"},"correctOption":"A","correctAnswer":"Job description and person specification","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the job description specifies role duties, while the person specification defines the skills, qualifications, and personal qualities required.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because CVs come from applicants and references from former employers.","C":"Incorrect because contracts are issued upon hiring and redundancy notices upon job elimination.","D":"Incorrect because org charts show reporting lines and balance sheets show assets/liabilities."}}},{"id":"P1_U2_MCQ_324","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_324","question":"A global hotel chain posts graduate hospitality vacancies on its corporate careers website and major online job portals. What is a disadvantage of online job portals for HR?","options":{"A":"Online adverts take six months to appear publicly","B":"Low application barriers can trigger hundreds of unsuitable applications, increasing shortlisting workload","C":"Online job portals can only be viewed by internal employees","D":"Candidates are unable to attach CVs electronically"},"correctOption":"B","correctAnswer":"Low application barriers can trigger hundreds of unsuitable applications, increasing shortlisting workload","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because one-click online applications often generate high volumes of unqualified applicants that HR must filter through.","distractor_reasons":{"A":"Incorrect because online adverts go live almost instantaneously.","B":"Correct selection.","C":"Incorrect because public job portals reach external jobseekers worldwide.","D":"Incorrect because digital uploads are a standard feature of online portals."}}},{"id":"P1_U2_MCQ_325","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_325","question":"A high-street bank uses psychometric personality questionnaires alongside interviews when hiring branch relationship managers. What do psychometric personality tests aim to measure?","options":{"A":"A candidate's typing speed in words per minute","B":"Whether a candidate holds a valid heavy-goods driving license","C":"Behavioral traits such as teamwork style, emotional resilience, and customer orientation","D":"A candidate's past annual salary tax deductions"},"correctOption":"C","correctAnswer":"Behavioral traits such as teamwork style, emotional resilience, and customer orientation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because psychometric personality assessments evaluate attitudes, interpersonal preferences, and cultural fit for the role.","distractor_reasons":{"A":"Incorrect because typing speed is a practical skills test.","B":"Incorrect because licenses are verified via document checks.","C":"Correct selection.","D":"Incorrect because tax history is unrelated to psychological traits."}}},{"id":"P1_U2_MCQ_326","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_326","question":"During a job interview, a candidate submits a polished Curriculum Vitae (CV) claiming five years of software project leadership. What is a key limitation of relying solely on a candidate's CV?","options":{"A":"CVs never include contact details for the applicant","B":"Employers are legally forbidden from reading CVs before interviews","C":"CVs force every applicant to answer identical standardized questions","D":"Applicants write their own CVs and may exaggerate achievements or omit weaknesses"},"correctOption":"D","correctAnswer":"Applicants write their own CVs and may exaggerate achievements or omit weaknesses","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because CVs are self-written marketing documents that require verification via interviews, tests, and employer references.","distractor_reasons":{"A":"Incorrect because contact details appear at the top of a CV.","B":"Incorrect because CVs are routinely used during shortlisting.","C":"Incorrect because standardized forms—not free-form CVs—enforce identical prompts.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_327","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_327","question":"An accounting consultancy offers experienced senior tax advisors the option to work part-time (three days a week) instead of losing them when they request flexible schedules. How does this benefit the consultancy?","options":{"A":"It retains scarce specialist expertise and avoids costly external replacement recruitment","B":"Part-time senior advisors work five full days while being paid for three","C":"Part-time advisors require zero professional indemnity insurance","D":"It eliminates all client deadlines during Thursdays and Fridays"},"correctOption":"A","correctAnswer":"It retains scarce specialist expertise and avoids costly external replacement recruitment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because offering part-time flexibility helps retain valuable skilled staff who might otherwise resign.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because part-time staff work reduced hours proportional to their pay.","C":"Incorrect because professional standards and insurance still apply.","D":"Incorrect because other team members cover client needs across the week."}}},{"id":"P1_U2_MCQ_328","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_328","question":"A toy manufacturer hires 60 temporary production workers from October to December to meet peak holiday gift orders, ending their contracts in January. Why are temporary workers suited to this business?","options":{"A":"Temporary workers are legally prohibited from receiving hourly wages","B":"The firm scales up output for seasonal peaks without paying idle full-time salaries during quiet spring months","C":"Temporary workers never make assembly mistakes","D":"Hiring temporary staff eliminates the need for factory supervisors"},"correctOption":"B","correctAnswer":"The firm scales up output for seasonal peaks without paying idle full-time salaries during quiet spring months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because temporary contracts align labor capacity and wage costs directly with predictable seasonal demand spikes.","distractor_reasons":{"A":"Incorrect because temporary staff must be paid at least the legal minimum wage.","B":"Correct selection.","C":"Incorrect because temporary staff actually have less experience and require close supervision.","D":"Incorrect because supervisors are needed to train and monitor seasonal hires."}}},{"id":"P1_U2_MCQ_329","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_329","question":"When designing a job advertisement for an External Sales Executive, HR includes the job title, key responsibilities, required qualifications, salary package, and application deadline. What is the primary purpose of this advert?","options":{"A":"To serve as the final legally binding employment contract","B":"To evaluate the annual performance of existing sales managers","C":"To attract suitable qualified applicants while deterring unsuitable ones from applying","D":"To notify shareholders of annual dividend payouts"},"correctOption":"C","correctAnswer":"To attract suitable qualified applicants while deterring unsuitable ones from applying","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a well-targeted job advert informs potential candidates about the role and filters self-selection toward qualified applicants.","distractor_reasons":{"A":"Incorrect because a formal contract is drafted after a candidate is selected.","B":"Incorrect because staff performance is assessed through appraisals.","C":"Correct selection.","D":"Incorrect because shareholder dividends are communicated via annual reports."}}},{"id":"P1_U2_MCQ_330","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_330","question":"A logistics firm uses structured interviews—asking every applicant the exact same set of competency questions scored on a 1-to-5 rubric—rather than casual unstructured chats. Why are structured interviews preferred?","options":{"A":"They allow interviewers to hire candidates based purely on shared hobbies","B":"They prevent applicants from speaking about their past work experience","C":"They eliminate the need to check candidate references afterward","D":"They improve fairness, consistency, and legal defensibility by comparing candidates against identical criteria"},"correctOption":"D","correctAnswer":"They improve fairness, consistency, and legal defensibility by comparing candidates against identical criteria","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because standardized questions and scoring reduce unconscious interviewer bias and enable objective candidate comparison.","distractor_reasons":{"A":"Incorrect because structured interviews prevent irrelevant personal bias.","B":"Incorrect because competency questions specifically explore past experience.","C":"Incorrect because reference checks are still conducted before final appointment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_331","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_331","question":"A precision engineering firm invests $45,000 annually in technical training for its machine operators. How does effective employee training improve the firm's competitiveness?","options":{"A":"Higher operator skill reduces material wastage, lowers defect rates, and increases output per worker","B":"Trained operators are legally prohibited from asking for pay raises","C":"Training removes the need to maintain or service factory machines","D":"Training allows the firm to operate without health and safety policies"},"correctOption":"A","correctAnswer":"Higher operator skill reduces material wastage, lowers defect rates, and increases output per worker","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because well-trained workers operate machinery more accurately and efficiently, lowering unit costs and improving product quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skilled workers often negotiate higher pay.","C":"Incorrect because preventive machine maintenance remains essential.","D":"Incorrect because training reinforces health and safety compliance."}}},{"id":"P1_U2_MCQ_332","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_332","question":"A chain of hair salons enrolls apprentice stylists in a one-day-per-week external cosmetology college course while they assist senior stylists in the salon four days a week. What is a drawback of this off-the-job college day?","options":{"A":"Apprentices never learn theoretical hair-coloring chemistry","B":"The salon pays college tuition fees and loses the apprentice's salon labor during study days","C":"Apprentices cannot earn nationally recognized qualifications","D":"Off-the-job training forces apprentices to copy bad habits from salon colleagues"},"correctOption":"B","correctAnswer":"The salon pays college tuition fees and loses the apprentice's salon labor during study days","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because off-the-job training entails external course fees plus the opportunity cost of lost productive work time during classes.","distractor_reasons":{"A":"Incorrect because college courses specifically teach underlying theory.","B":"Correct selection.","C":"Incorrect because external colleges award formal accredited qualifications.","D":"Incorrect because copying workplace shortcuts is a drawback of on-the-job training."}}},{"id":"P1_U2_MCQ_333","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_333","question":"A chemical laboratory provides comprehensive induction training covering hazardous-spill procedures, protective eyewear rules, and emergency shower locations on Day 1. Why is induction legally and operationally vital here?","options":{"A":"It guarantees technicians will never need refresher safety training","B":"It replaces the need for written employment contracts","C":"It protects new staff from serious injury and demonstrates employer compliance with health and safety laws","D":"It allows the laboratory to pay trainees below the minimum wage"},"correctOption":"C","correctAnswer":"It protects new staff from serious injury and demonstrates employer compliance with health and safety laws","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employers have a legal duty of care to train workers on workplace hazards before they begin handling dangerous substances.","distractor_reasons":{"A":"Incorrect because periodic refresher training is still required.","B":"Incorrect because employment contracts remain legally mandatory.","C":"Correct selection.","D":"Incorrect because minimum wage laws still apply."}}},{"id":"P1_U2_MCQ_334","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_334","question":"A print newspaper publisher sees circulation drop by 60% due to digital news apps, forcing it to close two regional printing presses and cut 95 press operators. Why is this redundancy rather than dismissal?","options":{"A":"The press operators were caught stealing printing ink","B":"The publisher is promoting all 95 operators to editorial roles","C":"Redundancy means employees resigned voluntarily for higher pay","D":"The job roles themselves ceased to exist due to falling demand, through no fault of the employees"},"correctOption":"D","correctAnswer":"The job roles themselves ceased to exist due to falling demand, through no fault of the employees","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because redundancy occurs when structural or market changes eliminate the need for specific jobs, whereas dismissal stems from employee fault.","distractor_reasons":{"A":"Incorrect because theft would be dismissal for gross misconduct.","B":"Incorrect because their employment is being terminated, not promoted.","C":"Incorrect because voluntary resignation is natural wastage, not redundancy.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_335","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_335","question":"Before dismissing a retail store assistant for persistent lateness, an HR Manager issues a verbal warning, a first written warning, and a final written warning with time to improve. Why does HR follow this staged disciplinary procedure?","options":{"A":"To ensure procedural fairness, give the employee a genuine chance to improve, and protect against unfair dismissal claims","B":"Because employers are legally forbidden from ever dismissing any employee","C":"To avoid paying the employee for hours already worked","D":"To qualify for statutory redundancy grants from the government"},"correctOption":"A","correctAnswer":"To ensure procedural fairness, give the employee a genuine chance to improve, and protect against unfair dismissal claims","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employment law requires fair, documented warnings and an opportunity to improve before terminating for non-gross misconduct.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employers can lawfully dismiss staff for misconduct or capability if fair steps are followed.","C":"Incorrect because wages earned must always be paid.","D":"Incorrect because disciplinary dismissal is unrelated to redundancy."}}},{"id":"P1_U2_MCQ_336","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_336","question":"A hotel group employs 400 staff on average during the year. Over 12 months, 92 employees leave the company and must be replaced, costing $1,500 per replacement in recruitment and training. What is the hotel group's annual labor turnover rate and total replacement cost?","options":{"A":"20% turnover and $600,000 replacement cost","B":"23% turnover and $138,000 replacement cost","C":"23% turnover and $600,000 replacement cost","D":"4.3% turnover and $138,000 replacement cost"},"correctOption":"B","correctAnswer":"23% turnover and $138,000 replacement cost","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labor turnover = (92 / 400) × 100 = 23%, and total replacement cost = 92 × $1,500 = $138,000.","distractor_reasons":{"A":"Incorrect arithmetic for both turnover percentage and cost.","B":"Correct selection.","C":"Incorrect because $600,000 multiplies total staff (400) instead of leavers (92) by $1,500.","D":"Incorrect because 4.3% divides 400 by 92."}}},{"id":"P1_U2_MCQ_337","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_337","question":"A logistics company discovers its annual labor turnover has climbed to 38%, causing delivery delays and soaring recruitment bills. Which measure would most effectively reduce voluntary staff turnover?","options":{"A":"Canceling induction training for all new warehouse hires","B":"Replacing democratic team briefings with autocratic pay cuts","C":"Conducting exit interviews to fix root causes, improving career progression, and offering competitive pay","D":"Removing written employment contracts so staff feel less restricted"},"correctOption":"C","correctAnswer":"Conducting exit interviews to fix root causes, improving career progression, and offering competitive pay","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because exit interviews uncover why employees leave, enabling targeted improvements in pay, training, supervision, and progression.","distractor_reasons":{"A":"Incorrect because removing induction increases early resignations.","B":"Incorrect because pay cuts and autocratic behavior worsen turnover.","C":"Correct selection.","D":"Incorrect because written contracts are legally required and provide job security."}}},{"id":"P1_U2_MCQ_338","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_338","question":"A clothing factory refuses to provide ventilation fans, fire extinguishers, or machine guards, and locks emergency exits during shifts to prevent theft. Which legal area is the factory violating?","options":{"A":"Minimum wage overtime calculation laws","B":"Anti-discrimination equal pay rules","C":"Trade union recognition ballot laws","D":"Health and safety at work legislation"},"correctOption":"D","correctAnswer":"Health and safety at work legislation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health and safety laws mandate safe machinery, adequate ventilation, fire safety equipment, and unlocked emergency exits.","distractor_reasons":{"A":"Incorrect because the violations concern physical safety hazards, not hourly pay rates.","B":"Incorrect because equal pay rules concern wage fairness across protected groups.","C":"Incorrect because this involves workplace safety, not union ballots.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_339","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_339","question":"A retail chain operates in a country with a strict statutory minimum wage law. How can this legislation benefit the retail chain despite raising hourly payroll expenses?","options":{"A":"Higher entry-level pay boosts staff morale, lowers costly labor turnover, and increases consumer spending power","B":"The retail chain becomes exempt from paying corporate income tax","C":"Suppliers are legally forced to cut wholesale inventory prices by 50%","D":"Managers no longer need to train new sales assistants"},"correctOption":"A","correctAnswer":"Higher entry-level pay boosts staff morale, lowers costly labor turnover, and increases consumer spending power","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because better-paid workers tend to stay longer and work more productively, while higher economy-wide wages lift customer demand.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws do not grant corporate tax exemptions.","C":"Incorrect because supplier prices are determined by market contracts.","D":"Incorrect because staff training remains essential."}}},{"id":"P1_U2_MCQ_340","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_340","question":"A technology firm makes 25 administrative staff redundant after automating invoice processing, paying statutory redundancy compensation based on age, weekly pay, and years of service. Why do governments mandate statutory redundancy pay?","options":{"A":"To punish employees for failing to learn automation software","B":"To provide financial support while displaced workers search for new jobs and discourage reckless hiring/firing","C":"To prevent businesses from ever introducing new technology","D":"To replace regular monthly salaries while employees are still working"},"correctOption":"B","correctAnswer":"To provide financial support while displaced workers search for new jobs and discourage reckless hiring/firing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because statutory redundancy pay cushions workers against sudden job loss due to no fault of their own.","distractor_reasons":{"A":"Incorrect because redundancy is not a punishment; it compensates workers whose roles disappeared.","B":"Correct selection.","C":"Incorrect because firms can still automate provided they follow fair redundancy rules.","D":"Incorrect because redundancy pay is paid upon termination of employment."}}},{"id":"P1_U2_MCQ_341","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_341","question":"A Production Manager emails a revised assembly schedule to shift supervisors and asks each supervisor to reply 'Confirmed' once they have briefed their line operators. Why does the manager request this reply?","options":{"A":"To create an extra layer in the chain of command","B":"To avoid using electronic communication tools","C":"To obtain feedback verifying the message was received, decoded, and acted upon","D":"To turn internal communication into external advertising"},"correctOption":"C","correctAnswer":"To obtain feedback verifying the message was received, decoded, and acted upon","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because feedback closes the communication loop, confirming that the receiver understood the message accurately.","distractor_reasons":{"A":"Incorrect because requesting confirmation does not add management tiers.","B":"Incorrect because the manager is actively using email.","C":"Correct selection.","D":"Incorrect because the communication remains internal between manager and supervisors."}}},{"id":"P1_U2_MCQ_342","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_342","question":"A pharmaceutical manufacturer places an anonymous 'Employee Safety & Process Improvement Suggestion Box' in every laboratory corridor and reviews ideas monthly. Which direction of internal communication is this?","options":{"A":"Downward communication from executives to technicians","B":"External communication with hospital customers","C":"Horizontal communication between rival competitors","D":"Upward communication from frontline staff to management"},"correctOption":"D","correctAnswer":"Upward communication from frontline staff to management","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suggestion boxes channel ideas, concerns, and feedback upward from operational workers to decision-makers.","distractor_reasons":{"A":"Incorrect because downward communication flows from managers to subordinates.","B":"Incorrect because laboratory corridors are internal to the company.","C":"Incorrect because competitors are external entities.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_343","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_343","question":"During a product launch, the Marketing Manager meets with the Production Manager and Finance Manager to coordinate inventory build-up and promotional budgets. Which direction of communication occurs between these peers?","options":{"A":"Horizontal (lateral) communication between managers at the same hierarchical level","B":"Upward communication from factory trainees to the CEO","C":"External communication with government tax inspectors","D":"One-way noticeboard communication"},"correctOption":"A","correctAnswer":"Horizontal (lateral) communication between managers at the same hierarchical level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because communication across different functional departments at an equal organizational level is horizontal communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all three managers are peers at the same departmental-head tier.","C":"Incorrect because all participants work inside the same business.","D":"Incorrect because a cross-departmental meeting is interactive two-way dialogue."}}},{"id":"P1_U2_MCQ_344","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_344","question":"A manufacturing plant installs large digital display boards above each assembly line showing real-time hourly output targets, defect counts, and safety-streak days. What is a primary advantage of this visual method?","options":{"A":"Operators must stop machines for 20 minutes to read lengthy printed reports","B":"Key performance data is understood at a glance across noisy factory floors without interrupting work","C":"Digital boards allow operators to hold private one-to-one HR grievances","D":"Visual boards eliminate the need for team leaders"},"correctOption":"B","correctAnswer":"Key performance data is understood at a glance across noisy factory floors without interrupting work","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because visual dashboards convey live metrics rapidly and clearly even in noisy industrial environments.","distractor_reasons":{"A":"Incorrect because visual displays communicate quickly without halting production.","B":"Correct selection.","C":"Incorrect because confidential HR issues require private face-to-face meetings.","D":"Incorrect because supervisors still guide and support workers."}}},{"id":"P1_U2_MCQ_345","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_345","question":"A construction company sends a formal tender proposal and detailed architectural blueprints by courier and encrypted email to a municipal government bidding for a bridge contract. Why is written/visual documentation crucial here?","options":{"A":"Spoken phone calls are the only legal way to bid for public infrastructure","B":"Written proposals guarantee immediate face-to-face body language feedback","C":"Complex technical specifications, costs, and legal commitments require exact, verifiable permanent records","D":"Blueprints cost nothing to draft or print"},"correctOption":"C","correctAnswer":"Complex technical specifications, costs, and legal commitments require exact, verifiable permanent records","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high-value external contracts demand precise technical details and binding written records to prevent disputes.","distractor_reasons":{"A":"Incorrect because public tenders require formal written submissions.","B":"Incorrect because body-language cues occur in live meetings, not written documents.","C":"Correct selection.","D":"Incorrect because architectural drafting incurs significant professional costs."}}},{"id":"P1_U2_MCQ_346","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_346","question":"An automotive supplier uses an Electronic Data Interchange (EDI) system that automatically alerts its steel vendor whenever coil inventory drops below 20 tons. How does this electronic communication improve efficiency?","options":{"A":"It requires purchasing clerks to type and mail paper letters every afternoon","B":"It eliminates all physical transport trucks between supplier and factory","C":"It prevents suppliers from knowing the factory's inventory needs","D":"Instant, automated data transmission prevents stockouts and eliminates manual order-entry errors"},"correctOption":"D","correctAnswer":"Instant, automated data transmission prevents stockouts and eliminates manual order-entry errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automated electronic links transmit accurate order triggers instantaneously, speeding up supply chains.","distractor_reasons":{"A":"Incorrect because EDI replaces manual paper correspondence.","B":"Incorrect because physical steel coils still require delivery transport.","C":"Incorrect because EDI shares live stock requirements directly with the vendor.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_347","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_347","question":"A retail chain's Finance Director announces a store-restructuring plan using dense accounting terms like 'EBITDA margin compression and leasehold amortization' during a town-hall meeting with sales assistants, leaving staff confused and anxious. How could this barrier be overcome?","options":{"A":"Translate financial concepts into clear, plain everyday language focused on how stores and roles are affected","B":"Send the exact same speech in a 90-page PDF attachment","C":"Cancel all future staff meetings and rely on office rumors","D":"Add two more layers of regional managers to repeat the speech"},"correctOption":"A","correctAnswer":"Translate financial concepts into clear, plain everyday language focused on how stores and roles are affected","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tailoring language to the audience's background removes jargon barriers and ensures clear understanding.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 90-page jargon-filled PDF worsens information overload.","C":"Incorrect because silence fuels damaging grapevine rumors.","D":"Incorrect because adding hierarchy tiers increases message distortion."}}},{"id":"P1_U2_MCQ_348","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_348","question":"A remote software developer working in London emails an urgent bug fix to a colleague in Sydney at 4:00 PM London time, expecting an immediate answer, but receives no reply until the next morning. Which barrier affected this exchange?","options":{"A":"Physical factory machinery noise","B":"Geographic time-zone differences delaying synchronous two-way feedback","C":"Lack of internet connectivity in London and Sydney","D":"Autocratic leadership forbidding email replies"},"correctOption":"B","correctAnswer":"Geographic time-zone differences delaying synchronous two-way feedback","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 4:00 PM in London is the middle of the night in Sydney, delaying real-time response across global offices.","distractor_reasons":{"A":"Incorrect because both developers work remotely on computers.","B":"Correct selection.","C":"Incorrect because the email transmitted successfully; the recipient was asleep.","D":"Incorrect because the delay was due to time zones, not management bans."}}},{"id":"P1_U2_MCQ_349","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_349","question":"During a video conference, a project manager reads emails on a second monitor and interrupts team members mid-sentence, causing engineers to stop sharing risk warnings. Which communication barrier is the manager creating?","options":{"A":"Excessive use of printed postal letters","B":"Too flat an organizational hierarchy","C":"Poor listening skills and dismissive attitude discouraging upward feedback","D":"Language translation errors across countries"},"correctOption":"C","correctAnswer":"Poor listening skills and dismissive attitude discouraging upward feedback","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective communication requires active listening; ignoring or interrupting speakers shuts down valuable upward information.","distractor_reasons":{"A":"Incorrect because the interaction happened during a live video call.","B":"Incorrect because flat structures normally encourage open communication.","C":"Correct selection.","D":"Incorrect because both parties spoke the same language."}}},{"id":"P1_U2_MCQ_350","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_350","question":"A fast-growing logistics company experiences frequent delivery errors because warehouse pickers, dispatchers, and drivers rely on hurried verbal phone calls. What is the most effective solution?","options":{"A":"Ban drivers from contacting the warehouse during shifts","B":"Increase the chain of command by adding four deputy dispatchers","C":"Rely exclusively on informal breakroom gossip to update delivery addresses","D":"Introduce standardized digital dispatch manifests with instant barcode scan confirmations"},"correctOption":"D","correctAnswer":"Introduce standardized digital dispatch manifests with instant barcode scan confirmations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because structured written/electronic records with automated confirmation eliminate verbal mishearings and provide clear accountability.","distractor_reasons":{"A":"Incorrect because blocking communication prevents resolving urgent route issues.","B":"Incorrect because adding intermediaries slows communication and increases distortion.","C":"Incorrect because informal gossip is unreliable for operational logistics.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_351","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_351","question":"A fine-dining restaurant adds a mandatory 10% service charge to every customer bill and pools the funds equally among kitchen chefs, dishwashers, and waiters each week. How does this payment approach benefit restaurant teamwork?","options":{"A":"Waiters compete aggressively to claim high-spending tables from colleagues","B":"Kitchen staff and front-of-house servers cooperate smoothly because everyone shares in overall guest satisfaction","C":"The restaurant no longer needs to pay any basic hourly wages","D":"Individual waiters receive instant cash bonuses even when kitchen food is delayed"},"correctOption":"B","correctAnswer":"Kitchen staff and front-of-house servers cooperate smoothly because everyone shares in overall guest satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pooled service rewards encourage collaboration across kitchen and dining teams rather than individualistic rivalry.","distractor_reasons":{"A":"Incorrect because aggressive table-grabbing occurs under individual commission/tipping rather than equal pooling.","B":"Correct selection.","C":"Incorrect because basic hourly wages remain legally required.","D":"Incorrect because equal pooling links payouts to collective service quality."}}},{"id":"P1_U2_MCQ_352","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_352","question":"An automotive parts manufacturer uses time-rate hourly wages for its quality-control inspectors rather than piece-rate pay per inspected component. Why is time-rate pay more suitable for quality inspectors?","options":{"A":"Time-rate wages guarantee inspectors work twice as fast per hour","B":"Inspectors are legally prohibited from earning piece-rate pay","C":"Inspectors need sufficient time to check tolerances carefully without rushing to hit unit quotas","D":"Time-rate pay automatically decreases when factory output rises"},"correctOption":"C","correctAnswer":"Inspectors need sufficient time to check tolerances carefully without rushing to hit unit quotas","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quality inspection prioritizes accuracy and thoroughness over speed, making hourly time-rate wages far safer than piece-rate.","distractor_reasons":{"A":"Incorrect because hourly time-rate pay does not directly incentivize maximum speed.","B":"Incorrect because piece-rate is legal, just poorly suited to quality inspection.","C":"Correct selection.","D":"Incorrect because hourly wages depend on hours worked rather than output volume."}}},{"id":"P1_U2_MCQ_353","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_353","question":"A software startup is unable to match the high cash salaries offered by tech giants, so it grants every early engineer a 0.5% equity share ownership stake that vests over four years. How does employee share ownership help the startup?","options":{"A":"It guarantees engineers a fixed monthly cash dividend regardless of company losses","B":"It removes the need for engineers to sign written employment contracts","C":"It allows engineers to cash out their full shares on their second day of work","D":"It conserves immediate cash flow while motivating engineers to stay and grow the company's long-term value"},"correctOption":"D","correctAnswer":"It conserves immediate cash flow while motivating engineers to stay and grow the company's long-term value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because share schemes align staff interests with business growth, encourage retention over the vesting period, and preserve startup cash.","distractor_reasons":{"A":"Incorrect because dividends are only paid out of profits when declared by the board.","B":"Incorrect because written employment contracts remain mandatory.","C":"Incorrect because vesting periods require employees to stay for several years.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_354","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_354","question":"According to F.W. Taylor's scientific management principles, how should a factory manager maximize assembly-line productivity?","options":{"A":"Study tasks scientifically to find the single fastest method, train workers to follow it, and link pay directly to output","B":"Allow each worker to invent their own assembly sequence and work at whatever pace feels relaxing","C":"Eliminate financial bonuses and rely exclusively on social coffee breaks","D":"Delegate factory budgeting and hiring decisions to shop-floor operatives"},"correctOption":"A","correctAnswer":"Study tasks scientifically to find the single fastest method, train workers to follow it, and link pay directly to output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Taylor advocated time-and-motion standardization, specialized tasks, and piece-rate financial incentives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because letting workers choose their own methods contradicts Taylor's 'one best way' standardization.","C":"Incorrect because social group factors reflect Elton Mayo, whereas Taylor emphasized money.","D":"Incorrect because Taylor separated managerial planning from manual execution."}}},{"id":"P1_U2_MCQ_355","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_355","question":"A logistics company organizes regional sports leagues, team lunches, and collaborative shift huddles after remote working left new hires feeling isolated. Which level of Maslow's hierarchy is the company addressing?","options":{"A":"Physiological survival needs","B":"Social (love and belonging) needs","C":"Self-actualization needs","D":"Physical safety needs"},"correctOption":"B","correctAnswer":"Social (love and belonging) needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because workplace friendships, camaraderie, and feeling part of a supportive group satisfy Maslow's social needs.","distractor_reasons":{"A":"Incorrect because physiological needs cover basic food, shelter, and survival income.","B":"Correct selection.","C":"Incorrect because self-actualization involves creative mastery and reaching full personal potential.","D":"Incorrect because safety needs concern job security and hazard protection."}}},{"id":"P1_U2_MCQ_356","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_356","question":"A call center suffers from high absenteeism because supervisors micromanage every 30-second bathroom break and enforce rigid scripts, even though hourly wages are above average. Using Herzberg's theory, why are agents dissatisfied?","options":{"A":"Agents have achieved full self-actualization","B":"Hourly pay is classified as a true motivator rather than a hygiene factor","C":"Over-controlling supervision and restrictive company policies are poorly managed hygiene factors causing dissatisfaction","D":"Herzberg states that removing rigid rules has zero effect on employee attitudes"},"correctOption":"C","correctAnswer":"Over-controlling supervision and restrictive company policies are poorly managed hygiene factors causing dissatisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg identifies quality of supervision and company administrative policies as hygiene factors that cause active dissatisfaction when oppressive.","distractor_reasons":{"A":"Incorrect because micromanagement blocks autonomy and self-actualization.","B":"Incorrect because Herzberg classifies pay as a hygiene factor.","C":"Correct selection.","D":"Incorrect because improving hygiene factors removes dissatisfaction."}}},{"id":"P1_U2_MCQ_357","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_357","question":"A supermarket cross-trains grocery assistants so they spend Monday on bakery display, Tuesday on online order picking, and Wednesday on customer service desk duties. Which non-financial motivator is this?","options":{"A":"Piece-rate incentive pricing","B":"Delayering","C":"Autocratic specialization","D":"Job rotation"},"correctOption":"D","correctAnswer":"Job rotation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because job rotation systematically moves workers between different tasks over time to reduce boredom and build multi-skilling.","distractor_reasons":{"A":"Incorrect because piece-rate is a financial payment per unit produced.","B":"Incorrect because delayering removes layers of management.","C":"Incorrect because specialization keeps a worker on one narrow task permanently.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_358","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_358","question":"A garment workshop pays machinists $4.20 per tailored blazer completed. If a machinist completes 95 blazers in a week and earns an extra $35.00 punctuality bonus, what is their gross weekly pay?","options":{"A":"$434.00","B":"$399.00","C":"$469.00","D":"$364.00"},"correctOption":"A","correctAnswer":"$434.00","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because piece-rate earnings = 95 × $4.20 = $399.00, plus the $35.00 bonus = $434.00.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $399.00 omits the $35.00 punctuality bonus.","C":"Incorrect arithmetic.","D":"Incorrect because $364.00 subtracts $35.00 instead of adding it."}}},{"id":"P1_U2_MCQ_359","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_359","question":"A design consultancy holds monthly 'Innovation Fridays' where product designers spend four hours prototyping original furniture concepts and pitching them to directors. Which motivational concept does this best illustrate?","options":{"A":"Taylor's strict time-and-motion supervision","B":"Job enrichment and Maslow's self-actualization through creative autonomy and personal growth","C":"Statutory minimum wage compliance","D":"Horizontal job enlargement of routine filing tasks"},"correctOption":"B","correctAnswer":"Job enrichment and Maslow's self-actualization through creative autonomy and personal growth","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because creative freedom, challenging work, and intellectual growth fulfill self-actualization and Herzberg's motivators.","distractor_reasons":{"A":"Incorrect because Taylorism eliminates worker discretion in favor of rigid standardization.","B":"Correct selection.","C":"Incorrect because this is a non-financial motivational initiative, not minimum wage enforcement.","D":"Incorrect because prototyping original concepts involves high-level creativity rather than peer-level routine chores."}}},{"id":"P1_U2_MCQ_360","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_360","question":"A bank branch manager begins holding brief Monday morning huddles to publicly thank tellers who received positive customer feedback cards during the previous week. What is an advantage of praise and recognition as a motivator?","options":{"A":"Praise permanently eliminates the need to pay competitive salaries","B":"Praise guarantees zero errors in complex financial audits","C":"It costs the business virtually nothing while boosting employee morale, self-esteem, and repeat positive behavior","D":"Praise only motivates senior directors and has no effect on frontline staff"},"correctOption":"C","correctAnswer":"It costs the business virtually nothing while boosting employee morale, self-esteem, and repeat positive behavior","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sincere recognition satisfies esteem needs at minimal financial cost and reinforces good customer service.","distractor_reasons":{"A":"Incorrect because fair pay remains essential as a hygiene factor.","B":"Incorrect because audits require technical training and checks.","C":"Correct selection.","D":"Incorrect because frontline employees strongly value appreciation from managers."}}},{"id":"P1_U2_MCQ_361","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_361","question":"A growing tech startup transitions from an informal founder-led group to a structured functional organization with separate Heads of Engineering, Marketing, Finance, and HR. What is a primary benefit of functional departments?","options":{"A":"Employees with specialist expertise work together, improving technical efficiency and clear career paths","B":"Communication between different departments becomes completely automatic with zero effort","C":"The startup no longer needs a Chief Executive Officer to coordinate strategy","D":"Functional departments eliminate all operational overhead costs"},"correctOption":"A","correctAnswer":"Employees with specialist expertise work together, improving technical efficiency and clear career paths","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grouping specialists by function builds deep expertise, avoids duplicating specialist roles, and clarifies reporting lines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because functional silos can actually hinder cross-departmental communication if not managed.","C":"Incorrect because senior leadership must still coordinate across functions.","D":"Incorrect because specialist departments still incur salaries and overheads."}}},{"id":"P1_U2_MCQ_362","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_362","question":"In a tall corporate hierarchy with nine management levels, a customer refund policy approved by the Board is misunderstood by store staff after passing through seven regional and area managers. Why does a tall hierarchy cause this?","options":{"A":"Wide spans of control prevent managers from talking to anyone","B":"A long chain of command increases the number of intermediaries, slowing down and distorting downward messages","C":"Tall hierarchies abolish all formal job descriptions","D":"Store staff have too much decentralized authority"},"correctOption":"B","correctAnswer":"A long chain of command increases the number of intermediaries, slowing down and distorting downward messages","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because each extra level in a long chain of command adds delay and risks filtering or misinterpreting instructions.","distractor_reasons":{"A":"Incorrect because tall structures typically have narrow spans of control.","B":"Correct selection.","C":"Incorrect because tall bureaucracies usually rely heavily on formal job descriptions.","D":"Incorrect because tall hierarchies tend to centralize authority at the top."}}},{"id":"P1_U2_MCQ_363","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_363","question":"A supermarket chain widens its Store Managers' span of control from 6 department heads to 14 department heads after delayering deputy managers. Which condition makes a wider span of control workable?","options":{"A":"Department heads are brand-new trainees who need step-by-step instructions every 10 minutes","B":"Store tasks involve unpredictable, high-risk nuclear engineering procedures","C":"Department heads are well-trained, experienced, and follow standardized store operating procedures","D":"The Store Manager refuses to delegate any routine scheduling tasks"},"correctOption":"C","correctAnswer":"Department heads are well-trained, experienced, and follow standardized store operating procedures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because competent, experienced subordinates performing standardized tasks require less close supervision, allowing a wider span of control.","distractor_reasons":{"A":"Incorrect because inexperienced trainees require narrow spans and close coaching.","B":"Incorrect because complex, high-risk operations demand narrow spans of control.","C":"Correct selection.","D":"Incorrect because wide spans require effective delegation to function smoothly."}}},{"id":"P1_U2_MCQ_364","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_364","question":"At the start of a new financial year, a Retail Operations Director inspires store teams with a compelling vision for customer service, resolves a dispute between two area managers, and coaches new supervisors. Which management role is this?","options":{"A":"External statutory auditing","B":"Job analysis and CV shortlisting","C":"Redundancy compensation calculation","D":"Commanding / Leading (directing, motivating, and guiding employees toward organizational objectives)"},"correctOption":"D","correctAnswer":"Commanding / Leading (directing, motivating, and guiding employees toward organizational objectives)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inspiring, guiding, and resolving team conflicts represent the leading/commanding function of management.","distractor_reasons":{"A":"Incorrect because external auditing is performed by independent accountants.","B":"Incorrect because recruitment tasks belong to HR selection.","C":"Incorrect because redundancy calculation is an administrative termination task.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_365","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_365","question":"A hospital surgical team faces an unexpected life-threatening complication mid-operation, and the Lead Surgeon gives rapid, unquestioned instructions to nurses and anesthetists. Why is autocratic leadership vital in this moment?","options":{"A":"Time-critical emergencies demand instant, unified action with zero delay from group debate","B":"Autocratic leadership maximizes employee democracy during routine office meetings","C":"Nurses are legally forbidden from ever speaking in a hospital","D":"Laissez-faire leadership is always faster than autocratic leadership in emergencies"},"correctOption":"A","correctAnswer":"Time-critical emergencies demand instant, unified action with zero delay from group debate","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because emergencies leave no time for consultation and require clear, decisive command.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because autocratic leadership excludes staff from decision-making.","C":"Incorrect because surgical staff communicate vital clinical updates continuously.","D":"Incorrect because laissez-faire lacks immediate central direction."}}},{"id":"P1_U2_MCQ_366","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_366","question":"A video-game studio lets its experienced lead programmers and level artists decide their own sprint workflows and creative mechanics, with management reviewing milestone demos monthly. What is a drawback of this laissez-faire leadership?","options":{"A":"Programmers feel suffocated by constant hourly micromanagement","B":"Poor coordination between art and coding teams can cause missed release deadlines if self-discipline falters","C":"Managers spend all day shouting autocratic orders","D":"Laissez-faire leadership forbids creative experimentation"},"correctOption":"B","correctAnswer":"Poor coordination between art and coding teams can cause missed release deadlines if self-discipline falters","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because minimal managerial direction can lead to drift, duplicated effort, or missed deadlines if teams fail to self-coordinate.","distractor_reasons":{"A":"Incorrect because micromanagement is the opposite of laissez-faire leadership.","B":"Correct selection.","C":"Incorrect because shouting orders characterizes autocratic leadership.","D":"Incorrect because laissez-faire encourages maximum creative autonomy."}}},{"id":"P1_U2_MCQ_367","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_367","question":"A pharmaceutical research institute holds town-hall consultations and joint safety-committee votes with lab scientists before adopting new laboratory shift patterns. What is a potential disadvantage of this democratic leadership style?","options":{"A":"Scientists feel completely ignored by senior management","B":"Ideas from frontline lab technicians are never heard","C":"Decision-making takes longer due to meetings and discussions, delaying urgent changes","D":"Democratic leadership eliminates all accountability for lab safety"},"correctOption":"C","correctAnswer":"Decision-making takes longer due to meetings and discussions, delaying urgent changes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consulting staff and building consensus slows down decisions compared with top-down executive decrees.","distractor_reasons":{"A":"Incorrect because democratic leadership actively involves staff.","B":"Incorrect because frontline input is central to democratic consultation.","C":"Correct selection.","D":"Incorrect because managers still retain legal and operational responsibility."}}},{"id":"P1_U2_MCQ_368","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_368","question":"A logistics company employs 600 drivers, of whom 420 belong to a recognized transport union. During a pay dispute, 336 union members vote in favor of a 24-hour strike. What percentage of the total driver workforce voted to strike?","options":{"A":"80%","B":"70%","C":"42%","D":"56%"},"correctOption":"D","correctAnswer":"56%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because (336 strike votes / 600 total drivers) × 100 = 56% of the entire driver workforce.","distractor_reasons":{"A":"Incorrect because 80% is the percentage of union members who voted to strike (336 / 420), not total drivers.","B":"Incorrect because 70% is the overall union membership density (420 / 600).","C":"Incorrect arithmetic.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_369","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_369","question":"A railway operator refuses to negotiate over driver fatigue rules, prompting the rail union to ban all rest-day overtime working during the busy summer travel season. What is this industrial action called?","options":{"A":"Overtime ban","B":"Employer lockout","C":"Compulsory redundancy","D":"Internal job enrichment"},"correctOption":"A","correctAnswer":"Overtime ban","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an overtime ban is a form of industrial action where workers refuse extra hours beyond their standard contract, reducing capacity without losing basic pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a lockout occurs when an employer closes the workplace to lock staff out.","C":"Incorrect because redundancy is job elimination by the employer.","D":"Incorrect because job enrichment is a motivational job design technique."}}},{"id":"P1_U2_MCQ_370","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_370","question":"A Hotel Operations Manager delegates weekly supplier ordering for housekeeping linen to the Head Housekeeper, granting a $5,000 monthly budget and clear quality standards. How does this delegation benefit the Head Housekeeper?","options":{"A":"The Head Housekeeper becomes legally liable for all hotel bank loans","B":"It increases trust, job satisfaction, and managerial experience, preparing the supervisor for future promotion","C":"The Head Housekeeper no longer has to supervise room attendants","D":"Delegation removes all budget limits on linen spending"},"correctOption":"B","correctAnswer":"It increases trust, job satisfaction, and managerial experience, preparing the supervisor for future promotion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because meaningful delegation empowers subordinates, satisfies esteem/self-actualization needs, and builds leadership capability.","distractor_reasons":{"A":"Incorrect because corporate debt liability rests with the company/owners.","B":"Correct selection.","C":"Incorrect because regular supervisory duties continue.","D":"Incorrect because effective delegation sets clear budget parameters ($5,000)."}}},{"id":"P1_U2_MCQ_371","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_371","question":"A regional supermarket chain needs a new Head of Digital Marketing to build its first e-commerce mobile app, a skill nobody in the current store workforce possesses. Why must the chain use external recruitment?","options":{"A":"External recruitment is always cheaper and faster than internal promotion","B":"External hires never require induction training into company culture","C":"Internal candidates lack the specialized technical skills needed, requiring recruitment from the wider labor market","D":"External recruitment guarantees zero resentment from rival supermarket chains"},"correctOption":"C","correctAnswer":"Internal candidates lack the specialized technical skills needed, requiring recruitment from the wider labor market","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when new specialist capabilities do not exist internally, external recruitment accesses a much broader talent pool.","distractor_reasons":{"A":"Incorrect because external recruitment typically costs more and takes longer than internal promotion.","B":"Incorrect because external hires require thorough induction.","C":"Correct selection.","D":"Incorrect because internal resentment—not competitor resentment—is the usual recruitment consideration."}}},{"id":"P1_U2_MCQ_372","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_372","question":"A commercial bank consistently fills branch manager vacancies through internal promotion rather than external hiring. What is a long-term risk of relying exclusively on internal recruitment?","options":{"A":"Excessive spending on external executive headhunters","B":"New managers take years to learn basic bank computer software","C":"Junior tellers feel demotivated because no promotion path exists","D":"Organizational stagnation and 'groupthink' due to a lack of fresh outside ideas and innovation"},"correctOption":"D","correctAnswer":"Organizational stagnation and 'groupthink' due to a lack of fresh outside ideas and innovation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because promoting solely from within limits new perspectives and can entrench outdated practices.","distractor_reasons":{"A":"Incorrect because internal promotion avoids external agency fees.","B":"Incorrect because internal staff already know company systems.","C":"Incorrect because internal promotion actually motivates junior staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_373","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_373","question":"An HR Officer prepares two documents for a vacant Payroll Administrator post: Document 1 states 'Process monthly wages, reconcile tax deductions, report to Finance Manager'; Document 2 states 'AAT accounting qualification, 2 years payroll experience, high attention to detail'. What are Documents 1 and 2?","options":{"A":"Document 1 is the job description; Document 2 is the person specification","B":"Document 1 is the person specification; Document 2 is the job description","C":"Document 1 is a reference letter; Document 2 is a CV","D":"Document 1 is a redundancy notice; Document 2 is an employment contract"},"correctOption":"A","correctAnswer":"Document 1 is the job description; Document 2 is the person specification","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the job description defines the role's duties and reporting line, while the person specification defines candidate qualifications and traits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the two documents.","C":"Incorrect because references and CVs come from external parties during applications.","D":"Incorrect because neither document deals with termination or final contract terms."}}},{"id":"P1_U2_MCQ_374","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_374","question":"A university hospital needs to hire an experienced Pediatric Neurosurgeon—a highly scarce medical specialty. Which recruitment method is most appropriate?","options":{"A":"Placing a handwritten card on a local supermarket community board","B":"Advertising in specialist international medical journals and engaging a medical executive search agency","C":"Distributing flyers at a local shopping mall","D":"Posting on a casual teenage part-time job board"},"correctOption":"B","correctAnswer":"Advertising in specialist international medical journals and engaging a medical executive search agency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rare, highly qualified specialists are reached through accredited professional journals and targeted search agencies.","distractor_reasons":{"A":"Incorrect because local shop boards reach local general jobseekers.","B":"Correct selection.","C":"Incorrect because mall flyers do not target specialist surgeons.","D":"Incorrect because part-time student boards are unsuitable for senior medical specialists."}}},{"id":"P1_U2_MCQ_375","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_375","question":"During selection for a Technical Support Engineer, shortlisted candidates spend 45 minutes diagnosing a simulated server outage while assessors observe their troubleshooting logic and calm communication. What type of selection test is this?","options":{"A":"Physical endurance fitness test","B":"Graphology handwriting test","C":"Practical work-sample / trade simulation test","D":"Criminal background check"},"correctOption":"C","correctAnswer":"Practical work-sample / trade simulation test","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because work-sample tests observe candidates performing realistic job tasks to verify actual competence.","distractor_reasons":{"A":"Incorrect because server troubleshooting tests technical and communication skills, not physical stamina.","B":"Incorrect because graphology analyzes handwriting.","C":"Correct selection.","D":"Incorrect because background checks verify legal history via official records."}}},{"id":"P1_U2_MCQ_376","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_376","question":"A logistics company conducts initial 15-minute video screening interviews with 25 shortlisted applicants before inviting the top 5 for final in-person interviews. Why is video screening useful at this stage?","options":{"A":"It guarantees every candidate has identical home internet speeds","B":"It eliminates the need to check employment references before hiring","C":"It replaces the need for a written job description","D":"It saves travel expenses and manager time while assessing basic communication skills before final-round selection"},"correctOption":"D","correctAnswer":"It saves travel expenses and manager time while assessing basic communication skills before final-round selection","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because initial video interviews efficiently narrow a long shortlist without incurring travel costs for distant candidates.","distractor_reasons":{"A":"Incorrect because uneven internet connections are a potential drawback of video interviews.","B":"Incorrect because reference checks remain vital.","C":"Incorrect because interview questions are based on the job description and person specification.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_377","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_377","question":"A corporate law firm recruits full-time associate solicitors working 40+ hours per week rather than hiring part-time solicitors working 15 hours a week. Why do law firms prefer full-time staff for complex client cases?","options":{"A":"Continuous availability ensures uninterrupted case ownership, easier client communication, and higher return on training investment","B":"Part-time employees are legally forbidden from working in offices","C":"Full-time solicitors never require paid annual vacation","D":"Hiring full-time staff eliminates all employer pension contributions"},"correctOption":"A","correctAnswer":"Continuous availability ensures uninterrupted case ownership, easier client communication, and higher return on training investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full-time staff provide continuity on complex projects, simpler team coordination, and lower training cost per hour worked.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because part-time work is common across office professions.","C":"Incorrect because full-time workers receive statutory paid annual leave.","D":"Incorrect because employers still contribute to full-time staff benefits/pensions."}}},{"id":"P1_U2_MCQ_378","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_378","question":"A luxury department store relies on part-time weekend sales advisors during busy Saturday and Sunday shopping hours. What is a direct benefit of part-time workers for the store?","options":{"A":"Part-time workers never need induction or till training","B":"Greater scheduling flexibility to cover peak trading hours without paying idle staff on quiet weekday mornings","C":"Part-time workers are exempt from statutory health and safety protection","D":"Communication across split shifts is always faster than with a single full-time team"},"correctOption":"B","correctAnswer":"Greater scheduling flexibility to cover peak trading hours without paying idle staff on quiet weekday mornings","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because part-time contracts allow retailers to align labor hours with peak customer footfall, controlling wage costs.","distractor_reasons":{"A":"Incorrect because part-time staff still require full till and safety induction.","B":"Correct selection.","C":"Incorrect because health and safety laws protect all workers equally.","D":"Incorrect because coordinating split shifts can make communication harder."}}},{"id":"P1_U2_MCQ_379","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_379","question":"When placing a job advertisement on a public website, why should an employer include a clear closing date for applications and instructions on how to apply?","options":{"A":"To prevent qualified candidates from submitting CVs electronically","B":"To replace the need for a person specification during shortlisting","C":"To organize the recruitment timetable efficiently so HR can shortlist all candidates together fairly","D":"Because job adverts are legally invalid without a photograph of the CEO"},"correctOption":"C","correctAnswer":"To organize the recruitment timetable efficiently so HR can shortlist all candidates together fairly","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a clear deadline and standardized application method keep the hiring process structured and fair to all applicants.","distractor_reasons":{"A":"Incorrect because clear instructions facilitate electronic submissions.","B":"Incorrect because HR still uses the person specification to shortlist.","C":"Correct selection.","D":"Incorrect because no such requirement exists."}}},{"id":"P1_U2_MCQ_380","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_380","question":"During an interview for a Junior Accountant, the interviewer asks several leading questions and spends 25 of the 30 minutes talking about company history, leaving little time for the candidate to answer. What is the main flaw of this interview?","options":{"A":"The interviewer gathered too much objective evidence of the candidate's accounting skills","B":"The candidate was forced to complete too many practical spreadsheet tests","C":"Panel interviewing caused three managers to disagree on scores","D":"Poor interviewing technique prevented the employer from assessing the candidate's actual suitability and competence"},"correctOption":"D","correctAnswer":"Poor interviewing technique prevented the employer from assessing the candidate's actual suitability and competence","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because interviews fail as a selection tool when untrained interviewers dominate the conversation instead of probing candidate competencies.","distractor_reasons":{"A":"Incorrect because the interviewer barely let the candidate speak.","B":"Incorrect because no practical test was conducted.","C":"Incorrect because this involved a single poorly prepared interviewer.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_381","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_381","question":"A software company introduces a structured two-week induction program pairing every new developer with a 'buddy', setting up security credentials, and explaining product architecture. How does this benefit the company?","options":{"A":"New hires reach full coding productivity faster, make fewer early errors, and feel integrated into the team","B":"Induction eliminates the need for any technical training later in their career","C":"New developers agree to work for 30% below market salary","D":"Induction allows the company to skip written employment contracts"},"correctOption":"A","correctAnswer":"New hires reach full coding productivity faster, make fewer early errors, and feel integrated into the team","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective induction accelerates learning, prevents early mistakes, and reduces costly first-month resignations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ongoing technical training remains important as software evolves.","C":"Incorrect because induction does not reduce contracted salaries.","D":"Incorrect because written contracts remain legally required."}}},{"id":"P1_U2_MCQ_382","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_382","question":"A food-processing factory trains new packaging operators on-the-job by having them work alongside a skilled line leader on an active conveyor belt. What is a potential operational drawback of this method?","options":{"A":"The factory must pay expensive external university tuition fees","B":"The experienced line leader's own output slows down while coaching, and trainee mistakes may waste real packaging materials","C":"Trainees spend three months away from the factory in theoretical lectures","D":"On-the-job trainees cannot use real factory machinery"},"correctOption":"B","correctAnswer":"The experienced line leader's own output slows down while coaching, and trainee mistakes may waste real packaging materials","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because on-the-job coaching diverts the mentor's attention and exposes live production to beginner errors.","distractor_reasons":{"A":"Incorrect because external tuition fees apply to off-the-job training.","B":"Correct selection.","C":"Incorrect because trainees stay on the factory floor during on-the-job training.","D":"Incorrect because trainees train directly on live equipment."}}},{"id":"P1_U2_MCQ_383","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_383","question":"A regional hospital sends nurses to an external university workshop to learn how to operate a newly invented robotic surgical system. What is a primary advantage of this off-the-job training?","options":{"A":"Nurses treat live hospital patients simultaneously while attending the university workshop","B":"Off-the-job university courses are completely free of charge","C":"Specialist external instructors teach cutting-edge techniques in a distraction-free environment without risking patient safety","D":"Nurses never need any practical hospital supervision afterward"},"correctOption":"C","correctAnswer":"Specialist external instructors teach cutting-edge techniques in a distraction-free environment without risking patient safety","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because off-the-job training brings new external expertise into the organization while allowing focused learning away from workplace pressures.","distractor_reasons":{"A":"Incorrect because off-the-job training takes place away from normal duties.","B":"Incorrect because external courses incur tuition fees.","C":"Correct selection.","D":"Incorrect because gradual supervised practice in the hospital still follows."}}},{"id":"P1_U2_MCQ_384","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_384","question":"An automotive manufacturer must cut 120 assembly jobs due to a permanent fall in petrol-engine demand. Rather than firing workers arbitrarily, management offers enhanced voluntary redundancy packages first. Why do firms prefer voluntary redundancy?","options":{"A":"Voluntary redundancy avoids paying any financial compensation to departing workers","B":"It allows management to dismiss trade union leaders without legal notice","C":"Workers who leave voluntarily cannot apply for jobs at other companies","D":"It reduces industrial conflict and preserves morale among remaining staff since departing workers choose to leave"},"correctOption":"D","correctAnswer":"It reduces industrial conflict and preserves morale among remaining staff since departing workers choose to leave","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because voluntary redundancy softens the emotional and industrial-relations impact of downsizing compared with forced layoffs.","distractor_reasons":{"A":"Incorrect because voluntary redundancy usually offers slightly higher payouts to attract volunteers.","B":"Incorrect because targeting union reps is unlawful unfair dismissal.","C":"Incorrect because redundant employees are free to seek new employment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_385","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_385","question":"A supermarket cashier is caught on security cameras taking cash from the till and is dismissed immediately after an investigation hearing. Why is the employer legally entitled to dismiss without normal notice pay here?","options":{"A":"Theft constitutes gross misconduct, which fundamentally breaches the employment contract","B":"Employers never have to give notice to any employee for any reason","C":"The cashier's job role was eliminated by self-checkout machines","D":"Supermarkets are exempt from all employment protection legislation"},"correctOption":"A","correctAnswer":"Theft constitutes gross misconduct, which fundamentally breaches the employment contract","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross misconduct (such as theft, fraud, or violence) justifies summary dismissal without notice pay following a fair investigation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because standard dismissals require contractual notice periods.","C":"Incorrect because job elimination by automation is redundancy, not theft dismissal.","D":"Incorrect because supermarkets must obey all employment laws."}}},{"id":"P1_U2_MCQ_386","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_386","question":"A distribution depot employs 250 staff on average. During the year, 45 employees resign and 15 retire, while 60 new staff are hired to replace them. What is the depot's annual labor turnover rate?","options":{"A":"18%","B":"24%","C":"6%","D":"48%"},"correctOption":"B","correctAnswer":"24%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total leavers = 45 resignations + 15 retirements = 60 leavers; labor turnover = (60 / 250) × 100 = 24%.","distractor_reasons":{"A":"Incorrect because 18% counts only the 45 resignations (45 / 250) and omits the 15 retirements.","B":"Correct selection.","C":"Incorrect because 6% counts only the 15 retirements (15 / 250).","D":"Incorrect because 48% adds both leavers (60) and new hires (60) together (120 / 250)."}}},{"id":"P1_U2_MCQ_387","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_387","question":"A small construction firm employs 12 full-time builders. Which key detail must be included in each builder's written contract of employment?","options":{"A":"The exact net profit the firm expects to earn over the next ten years","B":"The personal home addresses of all the firm's private customers","C":"Job title, rate of pay and payment intervals, contracted hours of work, holiday entitlement, and notice period","D":"A clause forbidding the builder from ever joining a trade union"},"correctOption":"C","correctAnswer":"Job title, rate of pay and payment intervals, contracted hours of work, holiday entitlement, and notice period","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employment contracts legally specify core terms including duties, pay, hours, leave, and termination notice.","distractor_reasons":{"A":"Incorrect because profit forecasts belong in business plans, not individual employment contracts.","B":"Incorrect because customer details are confidential business data.","C":"Correct selection.","D":"Incorrect because employees have a legal right to join a trade union."}}},{"id":"P1_U2_MCQ_388","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_388","question":"A 54-year-old Senior Systems Analyst with top appraisal ratings is passed over for promotion in favor of a less-experienced 27-year-old colleague, with the manager stating 'we want a younger face for the team'. Which law has been breached?","options":{"A":"Health and safety machine-guarding regulations","B":"Statutory minimum wage hourly rate laws","C":"Collective bargaining strike-ballot laws","D":"Anti-discrimination employment legislation (age discrimination)"},"correctOption":"D","correctAnswer":"Anti-discrimination employment legislation (age discrimination)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because anti-discrimination laws protect employees from unfair treatment in promotion, hiring, or pay based on age, gender, race, religion, or disability.","distractor_reasons":{"A":"Incorrect because no physical safety violation occurred.","B":"Incorrect because minimum wage laws set an hourly pay floor.","C":"Incorrect because union ballots are unrelated to promotion bias.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_389","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_389","question":"An industrial warehouse invests in ergonomic lifting hoists, high-visibility vests, and regular forklift safety audits to comply with health and safety laws. What is a secondary business benefit of strong safety standards?","options":{"A":"Enhanced corporate reputation that helps attract skilled workers and win contracts with ethical corporate clients","B":"Legal exemption from paying overtime rates on weekend shifts","C":"Automatic reduction of corporate income tax to 0%","D":"Elimination of the need to insure warehouse buildings"},"correctOption":"A","correctAnswer":"Enhanced corporate reputation that helps attract skilled workers and win contracts with ethical corporate clients","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a strong safety record protects brand image, boosts worker morale, and satisfies supply-chain ethics audits by major clients.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overtime rules remain binding.","C":"Incorrect because safety compliance does not abolish corporate tax.","D":"Incorrect because property insurance remains essential."}}},{"id":"P1_U2_MCQ_390","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_390","question":"A clothing retailer faces a 10% increase in the legal minimum wage for its 500 store assistants. Why might the retailer's total profit fall by less than the full wage bill increase?","options":{"A":"The government reimburses 100% of every retailer's payroll costs","B":"Lower staff turnover reduces recruitment costs, higher morale lifts sales per hour, and economy-wide consumer spending rises","C":"Store assistants are forced to work unpaid overtime hours to offset the raise","D":"Minimum wage increases automatically lower commercial store rents"},"correctOption":"B","correctAnswer":"Lower staff turnover reduces recruitment costs, higher morale lifts sales per hour, and economy-wide consumer spending rises","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because productivity gains, reduced turnover costs, and stronger consumer demand partially offset higher hourly wage rates.","distractor_reasons":{"A":"Incorrect because businesses pay their own wages.","B":"Correct selection.","C":"Incorrect because unpaid overtime that drops effective hourly pay below minimum wage is illegal.","D":"Incorrect because store rents are governed by property leases."}}},{"id":"P1_U2_MCQ_391","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_391","question":"A clothing brand publishes its annual sustainability report and responds to customer inquiries on its official social media pages. Why is effective external communication essential for the brand?","options":{"A":"It replaces the need for managers to speak to factory employees","B":"It guarantees that competitors will stop launching rival products","C":"It builds customer trust, strengthens brand image, and reassures investors and regulators","D":"It eliminates the cost of manufacturing garments"},"correctOption":"C","correctAnswer":"It builds customer trust, strengthens brand image, and reassures investors and regulators","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because transparent, responsive external communication maintains strong relationships with customers, shareholders, suppliers, and the public.","distractor_reasons":{"A":"Incorrect because internal communication with staff remains vital.","B":"Incorrect because external PR does not stop competitors.","C":"Correct selection.","D":"Incorrect because production costs are unaffected."}}},{"id":"P1_U2_MCQ_392","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_392","question":"A Logistics Manager phones a freight driver who is stuck in highway traffic to immediately reroute a perishable food delivery to an alternate cold-storage depot. Why is a phone call (verbal communication) best here?","options":{"A":"Phone calls generate an automatic signed paper contract","B":"Written letters sent by post arrive faster than phone calls","C":"Phone calls allow the driver to view complex 3D architectural blueprints while driving","D":"Urgent operational changes require instant two-way spoken exchange and immediate confirmation"},"correctOption":"D","correctAnswer":"Urgent operational changes require instant two-way spoken exchange and immediate confirmation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because urgent, time-critical situations demand rapid two-way verbal communication to confirm understanding on the spot.","distractor_reasons":{"A":"Incorrect because spoken calls do not automatically create written contracts.","B":"Incorrect because postal mail takes days.","C":"Incorrect because drivers cannot read visual blueprints while driving.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_393","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_393","question":"An HR Department distributes a printed and digital 'Employee Handbook' outlining company sick-pay rules, parental leave policies, and grievance procedures to all 800 employees. What is an advantage of this written method?","options":{"A":"Every employee receives identical, authoritative policy details that can be re-read anytime as a permanent reference","B":"HR receives instant facial-expression feedback from all 800 staff simultaneously","C":"Written handbooks are guaranteed to be read cover-to-cover by 100% of employees on Day 1","D":"Written handbooks cost nothing to write, design, or update"},"correctOption":"A","correctAnswer":"Every employee receives identical, authoritative policy details that can be re-read anytime as a permanent reference","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because written policy documents ensure consistency across a large workforce and provide a permanent reference record.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because facial-expression feedback only happens in face-to-face or video meetings.","C":"Incorrect because a drawback of written documents is that staff may fail to read them thoroughly.","D":"Incorrect because drafting and updating handbooks requires HR time and resources."}}},{"id":"P1_U2_MCQ_394","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_394","question":"An airline prints illustrated safety instruction cards in every seat pocket showing how to fasten seatbelts, use oxygen masks, and locate emergency exits using clear icons rather than dense text. Why is visual communication ideal here?","options":{"A":"Visual icons allow passengers to debate safety rules with the pilot","B":"Clear diagrams overcome language barriers among international passengers and convey life-saving steps rapidly","C":"Printed safety cards are electronic messages sent via email","D":"Visual cards eliminate the need for cabin crew safety announcements"},"correctOption":"B","correctAnswer":"Clear diagrams overcome language barriers among international passengers and convey life-saving steps rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because universal visual symbols are understood instantly across diverse languages and reading levels.","distractor_reasons":{"A":"Incorrect because safety cards are one-way instructional aids.","B":"Correct selection.","C":"Incorrect because seat-pocket cards are printed visual materials.","D":"Incorrect because cabin crew also perform live demonstrations."}}},{"id":"P1_U2_MCQ_395","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_395","question":"A supermarket group launches an internal company intranet where store managers download weekly promotional posters, check HR policies, and submit stock-wastage reports. What is a benefit of an internal intranet?","options":{"A":"External competitors can freely download the supermarket's confidential pricing plans","B":"It completely eliminates the need for internet or computer hardware in stores","C":"Fast, centralized sharing of up-to-date documents across all branches while reducing paper printing costs","D":"It replaces face-to-face coaching for new store trainees"},"correctOption":"C","correctAnswer":"Fast, centralized sharing of up-to-date documents across all branches while reducing paper printing costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an intranet provides secure, instantaneous internal access to current company resources across multiple locations.","distractor_reasons":{"A":"Incorrect because an intranet is a private internal network restricted to authorized employees.","B":"Incorrect because intranets require computers/tablets and network connections.","C":"Correct selection.","D":"Incorrect because hands-on training still requires human coaching."}}},{"id":"P1_U2_MCQ_396","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_396","question":"During a video conference between head office and a regional warehouse, a poor internet connection causes audio lag and frozen video, leading the warehouse manager to mishear 'ship 50 pallets' as 'ship 15 pallets'. Which barrier occurred?","options":{"A":"Excessively long organizational chain of command","B":"Deliberate hostility from a trade union","C":"Cultural differences over national holidays","D":"Technical medium failure (poor signal quality) distorting the message during transmission"},"correctOption":"D","correctAnswer":"Technical medium failure (poor signal quality) distorting the message during transmission","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technical glitches in electronic channels act as physical/channel noise that corrupts message accuracy.","distractor_reasons":{"A":"Incorrect because the two managers were speaking directly to each other.","B":"Incorrect because the error resulted from audio lag, not union conflict.","C":"Incorrect because both worked within the same domestic operation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_397","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_397","question":"A junior warehouse clerk notices a dangerous oil leak near a loading bay but hesitates to report it because the Depot Manager is notoriously aggressive and punishes bearers of bad news. Which communication barrier is this?","options":{"A":"Attitudinal and status barrier (fear of an autocratic manager blocking upward communication)","B":"Information overload from too many safety posters","C":"Geographic time-zone delay between offices","D":"Lack of written stationery in the warehouse"},"correctOption":"A","correctAnswer":"Attitudinal and status barrier (fear of an autocratic manager blocking upward communication)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because intimidating management attitudes create fear, suppressing vital upward safety feedback from junior employees.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the clerk spotted the leak directly and wanted to report it upward.","C":"Incorrect because both work at the same depot.","D":"Incorrect because the barrier is psychological fear, not lack of paper."}}},{"id":"P1_U2_MCQ_398","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_398","question":"A multinational consumer goods firm launches a marketing slogan in an overseas country without consulting local staff, inadvertently using a phrase that sounds offensive in the local dialect. How could this barrier have been avoided?","options":{"A":"By sending the slogan in smaller font on printed posters","B":"By involving local native-speaking employees in reviewing messages to overcome linguistic and cultural barriers","C":"By banning all external advertising in overseas markets","D":"By adding three more layers of head-office executives"},"correctOption":"B","correctAnswer":"By involving local native-speaking employees in reviewing messages to overcome linguistic and cultural barriers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local cultural and linguistic review prevents translation blunders and ensures messages resonate appropriately.","distractor_reasons":{"A":"Incorrect because font size does not fix offensive dialect meanings.","B":"Correct selection.","C":"Incorrect because halting all marketing harms overseas sales.","D":"Incorrect because head-office executives without local dialect knowledge would still miss the error."}}},{"id":"P1_U2_MCQ_399","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_399","question":"A hospital ward notices that crucial patient-handover details are occasionally forgotten when nurses give hurried verbal updates at shift change. Which communication improvement should the Ward Matron introduce?","options":{"A":"Eliminate shift handovers completely so nurses leave five minutes earlier","B":"Rely solely on informal breakroom gossip between nurses","C":"Use a standardized written/digital handover checklist combined with a brief face-to-face confirmation","D":"Send patient updates via public social media posts"},"correctOption":"C","correctAnswer":"Use a standardized written/digital handover checklist combined with a brief face-to-face confirmation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining a structured written record with brief two-way verbal verification prevents omissions and ensures clarity.","distractor_reasons":{"A":"Incorrect because eliminating handovers endangers patient safety.","B":"Incorrect because informal gossip is unstructured and unreliable.","C":"Correct selection.","D":"Incorrect because posting patient details publicly breaches medical confidentiality."}}},{"id":"P1_U2_MCQ_400","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_400","question":"A manufacturing company reduces its management hierarchy from seven tiers to four tiers (delayering) and introduces monthly CEO Q&A video town halls. How do these changes improve internal communication?","options":{"A":"They prevent shop-floor workers from ever asking questions to senior leaders","B":"They increase message distortion by adding more middle managers","C":"They replace all written safety procedures with informal rumors","D":"A shorter chain of command speeds up downward/upward message flow while Q&A sessions encourage two-way feedback"},"correctOption":"D","correctAnswer":"A shorter chain of command speeds up downward/upward message flow while Q&A sessions encourage two-way feedback","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fewer hierarchy tiers reduce filtering/delays, and interactive Q&A forums strengthen upward feedback and trust.","distractor_reasons":{"A":"Incorrect because Q&A sessions specifically invite employee questions.","B":"Incorrect because delayering removes middle managers, reducing distortion.","C":"Incorrect because formal safety procedures remain documented.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_401","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_401","question":"A telecommunications company promotes six senior call-center agents to Team Leaders, moving them from hourly wages to a fixed annual salary. What is a potential disadvantage of fixed salaries for these Team Leaders?","options":{"A":"Their monthly income fluctuates wildly whenever customer call volumes drop","B":"They typically receive no extra overtime pay when staying late to handle shift emergencies","C":"Salaries legally forbid employees from receiving annual paid leave","D":"Salaried employees cannot be promoted to department manager roles"},"correctOption":"B","correctAnswer":"They typically receive no extra overtime pay when staying late to handle shift emergencies","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because salaried staff are paid a set annual sum for fulfilling their role rather than by the hour, meaning extra hours often go uncompensated.","distractor_reasons":{"A":"Incorrect because fixed salaries provide stable, predictable monthly income.","B":"Correct selection.","C":"Incorrect because salaried employees receive statutory paid holiday.","D":"Incorrect because salaried roles typically represent upward career progression."}}},{"id":"P1_U2_MCQ_402","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_402","question":"An IT consultancy awards annual performance-related pay (PRP) bonuses based on line managers' subjective ratings of each consultant's teamwork and client impact. What is a common drawback of this PRP scheme?","options":{"A":"PRP guarantees every consultant receives an identical bonus regardless of effort","B":"PRP permanently eliminates the need to pay basic monthly salaries","C":"Consultants feel resentful and demotivated if appraisal ratings appear biased or favoritism-driven","D":"Consultants are legally prohibited from discussing their career goals during appraisals"},"correctOption":"C","correctAnswer":"Consultants feel resentful and demotivated if appraisal ratings appear biased or favoritism-driven","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because subjective performance evaluations can trigger perceptions of unfairness, damaging morale and team cohesion.","distractor_reasons":{"A":"Incorrect because PRP varies payouts according to individual performance.","B":"Incorrect because PRP bonuses supplement regular base salaries.","C":"Correct selection.","D":"Incorrect because appraisals encourage discussing development goals."}}},{"id":"P1_U2_MCQ_403","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_403","question":"An automotive dealership introduces a 'Master Technician' title, a reserved front-row parking space, and a plaque in the showroom for mechanics who pass advanced diagnostic exams. Which level of Maslow's hierarchy does this target?","options":{"A":"Physiological basic survival needs","B":"Physical safety and shelter needs","C":"Social friendship needs","D":"Esteem needs (status, recognition, and respect from peers and management)"},"correctOption":"D","correctAnswer":"Esteem needs (status, recognition, and respect from peers and management)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because prestigious titles, visible status symbols, and public recognition fulfill Maslow's esteem needs.","distractor_reasons":{"A":"Incorrect because physiological needs are met through basic wages.","B":"Incorrect because safety needs involve job security and protective equipment.","C":"Incorrect because social needs relate to teamwork and belonging.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_404","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_404","question":"During a factory study inspired by Elton Mayo's Hawthorne experiments, managers consult assembly workers about break timings and lighting, observing productivity rise even when lighting is later dimmed. Why did output improve?","options":{"A":"Dim lighting makes tiny electronic components easier to see","B":"Managers threatened to dismiss any worker who slowed down","C":"Mayo's research proved that employees only care about piece-rate cash bonuses","D":"Workers felt valued because managers showed genuine interest in their views and strengthened group team spirit"},"correctOption":"D","correctAnswer":"Workers felt valued because managers showed genuine interest in their views and strengthened group team spirit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Mayo demonstrated that social interaction, group cohesion, and management attention strongly motivate workers.","distractor_reasons":{"A":"Incorrect because lighting changes were merely the experimental variable; human attention drove the productivity gain.","B":"Incorrect because threats represent autocratic coercion, not Mayo's human-relations findings.","C":"Incorrect because Mayo challenged Taylor's purely financial view of motivation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_405","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_405","question":"A frozen-food distribution warehouse launches an 'Employee of the Month' award, yet order pickers remain deeply dissatisfied because broken heating in the packing hall leaves temperatures near freezing. How does Herzberg's theory explain this?","options":{"A":"Recognition awards cannot prevent dissatisfaction when basic working conditions (a hygiene factor) are poor","B":"Working conditions are classified as true motivators that replace the need for wages","C":"Order pickers have already reached full self-actualization","D":"Herzberg states that physical comfort has zero impact on employee dissatisfaction"},"correctOption":"A","correctAnswer":"Recognition awards cannot prevent dissatisfaction when basic working conditions (a hygiene factor) are poor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg argued that hygiene factors like safe, comfortable working conditions must be fixed first to eliminate dissatisfaction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical working conditions are hygiene factors, not motivators.","C":"Incorrect because cold, uncomfortable conditions block higher-level fulfillment.","D":"Incorrect because poor hygiene factors directly cause active dissatisfaction."}}},{"id":"P1_U2_MCQ_406","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_406","question":"A supermarket asks checkout cashiers to also restock nearby impulse-buy shelves and check expiry dates during quiet periods, without granting any extra supervisory authority. Which job design technique is this?","options":{"A":"Job enrichment","B":"Job enlargement (adding horizontal tasks of similar skill level to reduce monotony)","C":"Delayering","D":"Piece-rate specialization"},"correctOption":"B","correctAnswer":"Job enlargement (adding horizontal tasks of similar skill level to reduce monotony)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because adding extra routine tasks at the same level of responsibility widens task variety, which is job enlargement.","distractor_reasons":{"A":"Incorrect because job enrichment adds higher-level decision-making authority and challenge.","B":"Correct selection.","C":"Incorrect because delayering removes management tiers.","D":"Incorrect because specialization narrows a job down to a single repetitive task."}}},{"id":"P1_U2_MCQ_407","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_407","question":"A commercial real estate broker earns a basic salary of $2,100 per month plus a 1.5% commission on completed property sales. In May, the broker closes two sales worth $240,000 and $310,000. What is the broker's total gross pay for May?","options":{"A":"$8,250","B":"$6,750","C":"$10,350","D":"$5,700"},"correctOption":"C","correctAnswer":"$10,350","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total sales = $240,000 + $310,000 = $550,000; commission = 1.5% of $550,000 = $8,250; total gross pay = $2,100 + $8,250 = $10,350.","distractor_reasons":{"A":"Incorrect because $8,250 is only the commission and omits the $2,100 basic salary.","B":"Incorrect because $6,750 calculates 1.5% on $310,000 ($4,650) + $2,100, omitting the $240,000 sale.","C":"Correct selection.","D":"Incorrect because $5,700 calculates 1.5% on $240,000 ($3,600) + $2,100, omitting the $310,000 sale."}}},{"id":"P1_U2_MCQ_408","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_408","question":"An online fashion retailer empowers customer-service advisors to issue instant replacement shipments or refunds up to $60 without waiting for supervisor approval. How does this empowerment benefit the business?","options":{"A":"It eliminates the need to keep warehouse inventory records","B":"Supervisors spend more time approving every small customer refund","C":"Customer complaints are resolved faster while advisors feel trusted and more motivated","D":"Advisors no longer need product or communication training"},"correctOption":"C","correctAnswer":"Customer complaints are resolved faster while advisors feel trusted and more motivated","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegating bounded authority speeds up service recovery for customers and boosts frontline staff ownership and morale.","distractor_reasons":{"A":"Incorrect because replacement shipments still update inventory records.","B":"Incorrect because empowerment frees supervisors from routine approvals.","C":"Correct selection.","D":"Incorrect because training is essential so staff use delegated authority wisely."}}},{"id":"P1_U2_MCQ_409","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_409","question":"Senior biomedical researchers at a pharmaceutical lab already earn high six-figure salaries, yet turnover rises when management cancels conference travel and restricts independent research projects. Why did high pay fail to retain them?","options":{"A":"Once financial and security needs are comfortably met, higher-order needs like autonomy, recognition, and intellectual growth drive motivation","B":"Biomedical scientists are legally prohibited from caring about career advancement","C":"High salaries always decrease employee productivity in laboratories","D":"Conference travel is classified as a basic physiological survival need"},"correctOption":"A","correctAnswer":"Once financial and security needs are comfortably met, higher-order needs like autonomy, recognition, and intellectual growth drive motivation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Maslow and Herzberg both show that once pay is adequate, intrinsic motivators such as autonomy and professional growth sustain engagement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because professionals strongly value career advancement and recognition.","C":"Incorrect because competitive pay prevents dissatisfaction even if it does not guarantee peak creativity.","D":"Incorrect because physiological needs cover basic food, water, and shelter."}}},{"id":"P1_U2_MCQ_410","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_410","question":"A publicly listed supermarket chain allows employees with over one year of service to buy company shares at a 20% discount through monthly payroll deductions. What is an advantage of this employee share-ownership scheme?","options":{"A":"Employees are guaranteed that the stock market share price can never fall","B":"Every part-time cashier automatically gains a seat on the Board of Directors","C":"The supermarket no longer needs to pay statutory minimum wages","D":"Workers gain a personal stake in long-term share-price growth and dividends, reducing labor turnover"},"correctOption":"D","correctAnswer":"Workers gain a personal stake in long-term share-price growth and dividends, reducing labor turnover","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because discounted share schemes encourage employees to think like owners, stay longer, and support sustainable business performance.","distractor_reasons":{"A":"Incorrect because share prices can fall as well as rise.","B":"Incorrect because small retail shareholders vote at AGMs rather than sitting on the board.","C":"Incorrect because minimum wage laws remain binding.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_411","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_411","question":"An insurance corporation removes two layers of regional middle managers (delayering) so branch managers report directly to Divisional Directors. What is a likely operational consequence of this delayering?","options":{"A":"Annual managerial salary costs fall and messages travel faster, though Divisional Directors face a wider span of control","B":"The chain of command becomes two levels longer and slower","C":"Every Divisional Director's span of control shrinks to just one subordinate","D":"Branch managers lose all decision-making delegation"},"correctOption":"A","correctAnswer":"Annual managerial salary costs fall and messages travel faster, though Divisional Directors face a wider span of control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing management layers cuts overheads and shortens the chain of command while widening spans of control for remaining managers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delayering shortens the chain of command.","C":"Incorrect because removing intermediate managers increases the number of direct reports per senior manager.","D":"Incorrect because wider spans usually require more delegation to branch managers."}}},{"id":"P1_U2_MCQ_412","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_412","question":"On a manufacturing firm's organizational chart, a dotted horizontal line connects the Health & Safety Officer to the Plant Manager, whereas solid vertical lines connect the Plant Manager to Shift Supervisors. What does the dotted line indicate?","options":{"A":"The Health & Safety Officer is an external customer","B":"Shift Supervisors report directly to the Health & Safety Officer for daily overtime pay","C":"The Health & Safety Officer holds a specialist advisory (staff) role rather than direct line command over production workers","D":"The Plant Manager has been made redundant"},"correctOption":"C","correctAnswer":"The Health & Safety Officer holds a specialist advisory (staff) role rather than direct line command over production workers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dotted lines represent functional/advisory relationships where specialists provide guidance without exercising direct line authority.","distractor_reasons":{"A":"Incorrect because the Health & Safety Officer is an internal employee.","B":"Incorrect because solid vertical lines denote direct line reporting.","C":"Correct selection.","D":"Incorrect because the Plant Manager remains in the solid line hierarchy."}}},{"id":"P1_U2_MCQ_413","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_413","question":"A global consumer conglomerate organizes its business into three product-based divisions: Beverages, Packaged Snacks, and Pet Nutrition, each with its own marketing and R&D teams. What is a drawback of this product structure?","options":{"A":"Managers cannot track the individual profitability of Beverages versus Pet Nutrition","B":"Product divisions eliminate all competition from rival companies","C":"Divisions are unable to tailor packaging to specific product categories","D":"Duplication of marketing, finance, and HR specialists across divisions increases fixed overhead costs"},"correctOption":"D","correctAnswer":"Duplication of marketing, finance, and HR specialists across divisions increases fixed overhead costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because product-based divisions replicate support functions inside each division, reducing economies of scale.","distractor_reasons":{"A":"Incorrect because product divisions actually make tracking each product line's profit easier.","B":"Incorrect because external market competition continues.","C":"Incorrect because product focus enhances tailored packaging and marketing.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_414","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_414","question":"Every Friday afternoon, a Factory Operations Manager reviews weekly defect rates and unit production costs against quarterly targets, adjusting machine calibration when defects exceed 1.5%. Which management function is this?","options":{"A":"External job advertising","B":"Controlling (monitoring actual performance against standards and taking corrective action)","C":"Collective trade union negotiation","D":"Induction buddy pairing"},"correctOption":"B","correctAnswer":"Controlling (monitoring actual performance against standards and taking corrective action)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because comparing actual results against planned targets and fixing deviations defines the controlling function of management.","distractor_reasons":{"A":"Incorrect because recruitment advertising belongs to HR staffing.","B":"Correct selection.","C":"Incorrect because collective bargaining involves union-employer negotiations.","D":"Incorrect because buddy pairing is part of new-hire induction."}}},{"id":"P1_U2_MCQ_415","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_415","question":"After winning a major municipal catering contract, an Events Manager arranges kitchen equipment, assigns chefs to prep stations, and sets delivery vehicle schedules. Which Fayol management function is demonstrated?","options":{"A":"Organizing (assembling and allocating resources, tasks, and staff to execute the plan)","B":"Dismissing staff for gross misconduct","C":"External financial auditing","D":"Laissez-faire abdication"},"correctOption":"A","correctAnswer":"Organizing (assembling and allocating resources, tasks, and staff to execute the plan)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because structuring roles, equipment, and schedules to carry out operational plans is the organizing function.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no disciplinary termination is taking place.","C":"Incorrect because external audits verify financial statements.","D":"Incorrect because the manager is actively structuring resources."}}},{"id":"P1_U2_MCQ_416","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_416","question":"During peak lunchtime rush at a busy fast-food restaurant, the Shift Manager assigns every crew member to a fixed station (grill, fryer, counter) and insists on strict adherence to standard cooking timers. Why is an autocratic style effective here?","options":{"A":"Customers prefer waiting 45 minutes while staff vote on burger recipes","B":"High-volume, standardized service with young or high-turnover staff requires clear, rapid direction and food-safety compliance","C":"Autocratic leadership encourages every cashier to invent new menu prices","D":"Fast-food restaurants are legally prohibited from holding staff briefings"},"correctOption":"B","correctAnswer":"High-volume, standardized service with young or high-turnover staff requires clear, rapid direction and food-safety compliance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because routine, time-sensitive operations with less experienced staff benefit from unambiguous instructions and standardized control.","distractor_reasons":{"A":"Incorrect because slow consensus would ruin fast-food service speed.","B":"Correct selection.","C":"Incorrect because autocratic leadership enforces central rules rather than individual improvisation.","D":"Incorrect because pre-shift briefings are standard practice."}}},{"id":"P1_U2_MCQ_417","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_417","question":"An advertising agency's Creative Director holds open brainstorming workshops with copywriters, graphic designers, and video editors to shape a client's rebranding pitch. Why does a democratic leadership style suit this agency?","options":{"A":"It prevents creative staff from sharing original campaign concepts","B":"It eliminates the need to meet client pitch deadlines","C":"Tapping specialist creative input improves campaign innovation and strengthens team commitment to executing the pitch","D":"Democratic leadership guarantees the client will never request revisions"},"correctOption":"C","correctAnswer":"Tapping specialist creative input improves campaign innovation and strengthens team commitment to executing the pitch","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because creative industries rely on diverse specialist ideas and high intrinsic motivation fostered by participative leadership.","distractor_reasons":{"A":"Incorrect because democratic leadership actively invites employee ideas.","B":"Incorrect because client deadlines still govern project schedules.","C":"Correct selection.","D":"Incorrect because external clients may still ask for changes."}}},{"id":"P1_U2_MCQ_418","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_418","question":"Over 75% of nurses at a private hospital group join a national healthcare trade union. How does collective bargaining through the union benefit individual nurses?","options":{"A":"Nurses no longer have to follow hospital hygiene protocols","B":"Union membership guarantees automatic promotion to hospital director within six months","C":"The union pays every nurse's full monthly salary out of union funds","D":"Negotiating together gives nurses stronger bargaining power on pay, shift safety, and legal representation than negotiating alone"},"correctOption":"D","correctAnswer":"Negotiating together gives nurses stronger bargaining power on pay, shift safety, and legal representation than negotiating alone","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 'strength in numbers' balances employer power during wage and working-condition negotiations and provides legal support.","distractor_reasons":{"A":"Incorrect because clinical safety protocols remain mandatory.","B":"Incorrect because promotions depend on qualifications and vacancies.","C":"Incorrect because the employer pays wages.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_419","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_419","question":"During a dispute over new parcel-sorting targets, postal union members launch a 'work-to-rule' campaign, performing every safety check slowly and refusing unpaid goodwill tasks. Why do unions often choose work-to-rule before an all-out strike?","options":{"A":"Workers continue receiving their normal contractual pay while still disrupting delivery schedules to pressure management","B":"Work-to-rule increases parcel delivery speed by 50%","C":"Employers are legally forced to double workers' hourly wages during a work-to-rule","D":"Work-to-rule permanently cancels all employee employment contracts"},"correctOption":"A","correctAnswer":"Workers continue receiving their normal contractual pay while still disrupting delivery schedules to pressure management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees are technically fulfilling their written contract rules, so they avoid losing daily wages while slowing employer output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because strict rule adherence slows operations down.","C":"Incorrect because normal contractual pay continues without automatic doubling.","D":"Incorrect because contracts remain intact."}}},{"id":"P1_U2_MCQ_420","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_420","question":"A multinational coffee-shop chain decentralizes store hiring and local seasonal drink promotions to country managers, while keeping espresso machine standards and brand logos centralized at head office. What is a risk of decentralizing local promotions?","options":{"A":"Country managers are unable to respond to local customer tastes","B":"Decentralization prevents country managers from developing leadership skills","C":"Head office becomes overloaded approving every barista's weekly shift","D":"Inconsistent local campaigns could dilute global brand identity or duplicate marketing design costs"},"correctOption":"D","correctAnswer":"Inconsistent local campaigns could dilute global brand identity or duplicate marketing design costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delegating marketing autonomy across regions can create inconsistent messaging and duplicated creative expenses.","distractor_reasons":{"A":"Incorrect because local responsiveness is a benefit, not a risk, of decentralization.","B":"Incorrect because decentralization builds local managerial experience.","C":"Incorrect because store hiring and shifts are decentralized to local managers.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_421","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_421","question":"Before advertising to replace a retiring Senior Quality Chemist, HR observes the outgoing chemist's daily lab tests, software usage, and safety duties. What is this first step in the recruitment process called?","options":{"A":"Exit interview","B":"Induction training","C":"Job analysis","D":"Compulsory redundancy"},"correctOption":"C","correctAnswer":"Job analysis","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job analysis systematically examines the tasks, responsibilities, and skills involved in a role to produce an accurate job description and person specification.","distractor_reasons":{"A":"Incorrect because an exit interview explores why a departing worker is leaving.","B":"Incorrect because induction occurs after a new employee is hired.","C":"Correct selection.","D":"Incorrect because the role is being refilled, not eliminated."}}},{"id":"P1_U2_MCQ_422","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_422","question":"A department store promotes its top Menswear Supervisor to Floor Manager. What immediate staffing issue does this internal promotion create?","options":{"A":"The Floor Manager role must now be advertised in national newspapers","B":"A new vacancy is created at the Menswear Supervisor level that still needs to be filled","C":"The promoted supervisor must undergo six months of basic company induction","D":"All other store supervisors are legally required to resign"},"correctOption":"B","correctAnswer":"A new vacancy is created at the Menswear Supervisor level that still needs to be filled","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because internal promotion fills one vacancy by shifting an existing employee, leaving their previous role vacant.","distractor_reasons":{"A":"Incorrect because the Floor Manager post has just been filled.","B":"Correct selection.","C":"Incorrect because internal hires already know company policies and systems.","D":"Incorrect because internal promotion often motivates colleagues rather than forcing resignations."}}},{"id":"P1_U2_MCQ_423","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_423","question":"In a person specification for a Commercial Airline Pilot, HR lists 'Valid Airline Transport Pilot License (ATPL)' as essential and 'Fluency in a second European language' as desirable. Why is this distinction helpful during shortlisting?","options":{"A":"HR can immediately filter out applicants lacking legally required qualifications while ranking qualified finalists using desirable extras","B":"Desirable criteria allow HR to hire pilots who have never flown an aircraft","C":"Essential criteria are optional suggestions that candidates can ignore","D":"Distinguishing essential and desirable traits eliminates the need for flight simulator tests"},"correctOption":"A","correctAnswer":"HR can immediately filter out applicants lacking legally required qualifications while ranking qualified finalists using desirable extras","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because essential criteria establish mandatory non-negotiables, while desirable criteria help differentiate among strong candidates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because essential qualifications remain mandatory.","C":"Incorrect because essential means compulsory for the job.","D":"Incorrect because practical simulator testing remains crucial for pilots."}}},{"id":"P1_U2_MCQ_424","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_424","question":"An independent neighborhood bistro needs two evening kitchen porters living within commuting distance. Which recruitment advertising channel is most cost-effective?","options":{"A":"A full-page advertisement in an international aviation trade magazine","B":"Hiring a global executive headhunting firm for $25,000","C":"A window poster in the bistro, local community job board, and local town job website","D":"Television commercials broadcast across three neighboring countries"},"correctOption":"C","correctAnswer":"A window poster in the bistro, local community job board, and local town job website","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local, low-cost channels target nearby jobseekers directly without wasting money on national or specialist audiences.","distractor_reasons":{"A":"Incorrect because aviation magazines target aerospace professionals.","B":"Incorrect because executive headhunters are for scarce senior leaders.","C":"Correct selection.","D":"Incorrect because international TV ads are prohibitively expensive and geographically misaligned."}}},{"id":"P1_U2_MCQ_425","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_425","question":"A national supermarket chain requires all graduate management applicants to complete a standardized online application form rather than uploading free-form CVs. Why do large employers prefer application forms?","options":{"A":"Application forms prevent candidates from mentioning their education history","B":"Applicants can hide employment gaps more easily on structured forms than on CVs","C":"Application forms legally replace the need for job interviews","D":"Every candidate provides identical information in the exact same sequence, making objective shortlisting faster and fairer"},"correctOption":"D","correctAnswer":"Every candidate provides identical information in the exact same sequence, making objective shortlisting faster and fairer","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because standardized fields force consistent disclosure of dates, qualifications, and competencies, simplifying side-by-side comparison.","distractor_reasons":{"A":"Incorrect because application forms include dedicated education sections.","B":"Incorrect because structured date fields actually make employment gaps easier to spot.","C":"Incorrect because shortlisted applicants are still interviewed.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_426","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_426","question":"An investment bank administers timed numerical and logical reasoning aptitude tests to university graduates applying for trainee analyst positions. What do aptitude tests assess?","options":{"A":"A candidate's natural capacity to learn new analytical skills and solve unfamiliar problems quickly","B":"Whether a candidate already knows the bank's confidential client passwords","C":"A candidate's physical endurance on a treadmill","D":"The candidate's previous employer's profit margin"},"correctOption":"A","correctAnswer":"A candidate's natural capacity to learn new analytical skills and solve unfamiliar problems quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aptitude tests measure innate cognitive potential (numerical, verbal, or logical reasoning) rather than prior job-specific knowledge.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because confidential systems are only taught after hiring.","C":"Incorrect because treadmill tests assess physical fitness.","D":"Incorrect because aptitude tests evaluate the individual candidate's reasoning."}}},{"id":"P1_U2_MCQ_427","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_427","question":"During an assessment center for Retail Area Manager candidates, groups of six applicants are given 40 minutes to resolve a simulated supply-chain disruption while assessors take notes. What does this group exercise reveal that a one-to-one interview might miss?","options":{"A":"How candidates actually listen, collaborate, influence peers, and handle pressure in a live team setting","B":"Whether the candidate's university degree certificate is genuine","C":"The candidate's exact credit score and bank balance","D":"How fast the candidate can drive a delivery truck"},"correctOption":"A","correctAnswer":"How candidates actually listen, collaborate, influence peers, and handle pressure in a live team setting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because group tasks reveal authentic interpersonal behaviors—such as listening, leadership, and compromise—that candidates might merely claim in interviews.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because degrees are verified via academic transcripts.","C":"Incorrect because financial checks are separate background procedures.","D":"Incorrect because driving skill is tested via practical road assessments."}}},{"id":"P1_U2_MCQ_428","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_428","question":"Before issuing a final employment contract to a Senior Accountant, HR contacts two former employers listed as referees. What is a limitation of employment references?","options":{"A":"Employers are legally forbidden from ever requesting references","B":"References are written before the candidate applies for the job","C":"Former employers often provide brief, cautious factual confirmations (dates and title) to avoid legal disputes","D":"References replace the need to check professional accounting qualifications"},"correctOption":"C","correctAnswer":"Former employers often provide brief, cautious factual confirmations (dates and title) to avoid legal disputes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fear of defamation or legal claims leads many companies to issue standardized, minimal factual references.","distractor_reasons":{"A":"Incorrect because checking references is standard recruitment practice.","B":"Incorrect because references are requested at the final offer stage.","C":"Correct selection.","D":"Incorrect because qualification certificates are verified directly."}}},{"id":"P1_U2_MCQ_429","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_429","question":"A supermarket chain employs 65% of its store cashiers on 16-hour-per-week part-time contracts. What is a potential disadvantage of relying heavily on part-time staff?","options":{"A":"Part-time workers are legally exempt from health and safety rules","B":"Higher induction and training costs per hour worked, plus lower organizational commitment if staff juggle second jobs","C":"Part-time workers can never work on Saturdays or Sundays","D":"The supermarket must pay every part-time worker a full 40-hour salary"},"correctOption":"B","correctAnswer":"Higher induction and training costs per hour worked, plus lower organizational commitment if staff juggle second jobs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because training two 16-hour workers costs roughly twice as much in induction/admin as training one 32-hour worker, and split schedules can weaken team continuity.","distractor_reasons":{"A":"Incorrect because health and safety laws protect all employees.","B":"Correct selection.","C":"Incorrect because weekend shifts are a primary reason retailers hire part-time staff.","D":"Incorrect because part-time staff are paid pro-rata for hours worked."}}},{"id":"P1_U2_MCQ_430","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_430","question":"An event-catering company employs 80 banquet servers on zero-hours (on-call) contracts, offering shifts only when large weddings or conferences are booked. What is a major risk of zero-hours contracts for the employer?","options":{"A":"The company must pay full weekly wages even during months with zero events","B":"Employers cannot train zero-hours staff in food hygiene","C":"Zero-hours workers are legally forbidden from serving food","D":"Servers may decline shifts at short notice or leave for competitors offering guaranteed weekly hours"},"correctOption":"D","correctAnswer":"Servers may decline shifts at short notice or leave for competitors offering guaranteed weekly hours","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when hours are unguaranteed, workers are free to refuse shifts or quit rapidly for stable jobs, causing reliability and turnover issues.","distractor_reasons":{"A":"Incorrect because the employer only pays for hours actually worked.","B":"Incorrect because food-hygiene training is both permitted and legally required.","C":"Incorrect because zero-hours contracts are widely used in hospitality.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_431","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_431","question":"A logistics warehouse cross-trains all order pickers to operate reach forklifts and run inventory-scanning software. How does this multi-skill training improve operational resilience?","options":{"A":"Training removes the need for warehouse safety aisles","B":"Forklift machines never require battery charging or maintenance","C":"Cross-trained workers are legally barred from taking annual vacation","D":"The warehouse can redeploy staff flexibly to cover unexpected sick absences or sudden order surges without bottlenecks"},"correctOption":"D","correctAnswer":"The warehouse can redeploy staff flexibly to cover unexpected sick absences or sudden order surges without bottlenecks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a multi-skilled workforce increases internal labor flexibility, preventing production or dispatch halts when specialists are absent.","distractor_reasons":{"A":"Incorrect because warehouse safety standards remain mandatory.","B":"Incorrect because equipment maintenance remains essential.","C":"Incorrect because paid vacation remains a statutory right.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_432","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_432","question":"A residential real estate agency trains new junior negotiators by having them shadow senior agents during live client home viewings and price negotiations. What is a drawback of this on-the-job shadowing?","options":{"A":"The agency pays expensive university lecture fees","B":"Junior agents never see real houses or real clients during training","C":"The trainee may pick up the senior agent's personal shortcuts or bad communication habits","D":"Shadowing requires closing the agency office for three weeks"},"correctOption":"C","correctAnswer":"The trainee may pick up the senior agent's personal shortcuts or bad communication habits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unstructured on-the-job observation risks passing on a mentor's bad habits alongside good practices.","distractor_reasons":{"A":"Incorrect because internal shadowing incurs no external university tuition fees.","B":"Incorrect because shadowing takes place during live client viewings.","C":"Correct selection.","D":"Incorrect because normal business operations continue during shadowing."}}},{"id":"P1_U2_MCQ_433","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_433","question":"A mid-sized engineering consultancy sponsors a junior engineer's $12,000 external chartered-engineer evening degree, only for a large rival firm to poach the newly qualified engineer two months later. What risk of off-the-job training does this illustrate?","options":{"A":"Externally recognized qualifications increase employees' market value, making them attractive targets for rival recruiters","B":"Off-the-job degrees prevent engineers from learning theoretical physics","C":"Rival firms are legally forbidden from hiring qualified engineers","D":"Off-the-job training never improves an employee's technical knowledge"},"correctOption":"A","correctAnswer":"Externally recognized qualifications increase employees' market value, making them attractive targets for rival recruiters","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because portable, accredited qualifications boost employability, creating a 'poaching' risk unless paired with retention incentives or training-repayment agreements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because university courses specifically teach theoretical principles.","C":"Incorrect because labor markets allow workers to change employers.","D":"Incorrect because off-the-job courses build valuable specialist knowledge."}}},{"id":"P1_U2_MCQ_434","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_434","question":"Which set of activities belongs specifically to a new retail store assistant's Day-1 induction training?","options":{"A":"Conducting an exit interview and calculating statutory redundancy pay","B":"Touring the store, meeting the store manager and team, reviewing fire exits, and setting up till login credentials","C":"Negotiating a national collective bargaining wage agreement with union leaders","D":"Drafting the external job advert and person specification for the CEO"},"correctOption":"B","correctAnswer":"Touring the store, meeting the store manager and team, reviewing fire exits, and setting up till login credentials","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because induction introduces new hires to the workplace layout, colleagues, organizational rules, safety procedures, and basic systems.","distractor_reasons":{"A":"Incorrect because exit interviews and redundancy occur when employment ends.","B":"Correct selection.","C":"Incorrect because union wage negotiations involve senior HR and union officials.","D":"Incorrect because executive recruitment documents are prepared by senior HR/board members."}}},{"id":"P1_U2_MCQ_435","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_435","question":"A B2B software sales executive fails to achieve even 30% of minimum quarterly sales targets for nine consecutive months despite tailored coaching, clear improvement plans, and formal capability warnings, leading to termination. Is this redundancy or dismissal?","options":{"A":"Redundancy, because the software company is closing its entire sales department","B":"Voluntary retirement, because the executive reached age 65","C":"Fair dismissal on grounds of capability/unsatisfactory performance following proper warnings and support","D":"Natural wastage, because the executive resigned to start a rival business"},"correctOption":"C","correctAnswer":"Fair dismissal on grounds of capability/unsatisfactory performance following proper warnings and support","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the sales role still exists and will be refilled; termination stemmed from the individual's persistent inability to meet standards after fair warnings.","distractor_reasons":{"A":"Incorrect because the role itself has not disappeared.","B":"Incorrect because termination resulted from performance capability, not retirement age.","C":"Correct selection.","D":"Incorrect because the employer terminated the contract rather than the employee resigning."}}},{"id":"P1_U2_MCQ_436","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_436","question":"Following a downturn in international air travel, an airline must make 60 flight attendants redundant. Why must HR use objective selection criteria (such as attendance records, performance appraisals, or length of service) rather than manager intuition?","options":{"A":"To ensure legal fairness, avoid discriminatory bias, and prevent costly unfair-dismissal tribunal claims","B":"Because airlines are legally forbidden from paying statutory redundancy compensation","C":"Objective criteria allow HR to target pregnant workers and union representatives first","D":"To eliminate the need to consult employees before announcing redundancies"},"correctOption":"A","correctAnswer":"To ensure legal fairness, avoid discriminatory bias, and prevent costly unfair-dismissal tribunal claims","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent, objective redundancy scoring protects employees from unfair discrimination and protects the employer against legal challenges.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because statutory redundancy pay is legally required for eligible employees.","C":"Incorrect because selecting workers due to pregnancy or union membership is automatically unlawful.","D":"Incorrect because employer consultation is still legally required."}}},{"id":"P1_U2_MCQ_437","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_437","question":"A customer-support center employs an average of 180 agents during the year. Over 12 months, 54 agents leave and are replaced at a cost of $900 per hire for advertising, interviewing, and induction. What is the annual labor turnover rate and total replacement cost?","options":{"A":"30% turnover and $162,000 replacement cost","B":"30% turnover and $48,600 replacement cost","C":"3.3% turnover and $48,600 replacement cost","D":"54% turnover and $48,600 replacement cost"},"correctOption":"B","correctAnswer":"30% turnover and $48,600 replacement cost","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labor turnover = (54 / 180) × 100 = 30%, and replacement cost = 54 × $900 = $48,600.","distractor_reasons":{"A":"Incorrect because $162,000 multiplies total workforce (180) instead of leavers (54) by $900.","B":"Correct selection.","C":"Incorrect because 3.3% divides 180 by 54.","D":"Incorrect because 54% uses the raw headcount of leavers instead of dividing by 180."}}},{"id":"P1_U2_MCQ_438","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_438","question":"A retail chain dismisses a store supervisor immediately after she informs HR that she is pregnant, claiming 'maternity leave will disrupt our holiday roster'. Which legal protection has the employer violated?","options":{"A":"Minimum wage overtime calculation laws","B":"Trade union single-recognition ballot rules","C":"Unfair dismissal and pregnancy/maternity anti-discrimination legislation","D":"Health and safety forklift licensing regulations"},"correctOption":"C","correctAnswer":"Unfair dismissal and pregnancy/maternity anti-discrimination legislation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dismissing an employee due to pregnancy or maternity rights is automatically unfair dismissal and unlawful sex/maternity discrimination.","distractor_reasons":{"A":"Incorrect because the dismissal relates to maternity protection, not hourly wage rates.","B":"Incorrect because union ballots are unrelated.","C":"Correct selection.","D":"Incorrect because no machinery safety rule is involved."}}},{"id":"P1_U2_MCQ_439","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_439","question":"Under workplace health and safety legislation, a metal-fabrication factory provides safety goggles and ear defenders free of charge, but an experienced welder repeatedly refuses to wear them. What legal duty applies to the welder?","options":{"A":"Only employers have safety duties; workers have zero legal responsibility for workplace safety","B":"Health and safety laws only apply to office workers, not factory welders","C":"The welder is legally entitled to double hourly pay whenever refusing protective gear","D":"Employees have a legal duty to take reasonable care of their own and coworkers' safety and use provided protective equipment"},"correctOption":"D","correctAnswer":"Employees have a legal duty to take reasonable care of their own and coworkers' safety and use provided protective equipment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health and safety laws place reciprocal legal obligations on employees to cooperate with safety rules and wear issued PPE.","distractor_reasons":{"A":"Incorrect because employees also carry statutory safety responsibilities.","B":"Incorrect because industrial workplaces are strictly covered by health and safety laws.","C":"Incorrect because refusing PPE is a disciplinary breach, not grounds for bonus pay.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_440","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_440","question":"An audit at a distribution company reveals that female shift supervisors earn $3.50 per hour less than male shift supervisors performing identical duties with equal experience. Which legal principle requires the company to equalize their pay?","options":{"A":"Statutory redundancy pay calculation rules","B":"Equal pay / anti-discrimination legislation prohibiting gender-based wage disparities for equal work","C":"F.W. Taylor's piece-rate scientific management law","D":"Health and safety fire-exit inspection rules"},"correctOption":"B","correctAnswer":"Equal pay / anti-discrimination legislation prohibiting gender-based wage disparities for equal work","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because equal pay and anti-discrimination laws mandate equal remuneration for men and women performing equal or equivalent work.","distractor_reasons":{"A":"Incorrect because redundancy rules apply only when jobs are eliminated.","B":"Correct selection.","C":"Incorrect because Taylorism is a management theory, not employment legislation.","D":"Incorrect because fire-exit rules address physical safety."}}},{"id":"P1_U2_MCQ_441","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_441","question":"An HR Director sends individualized annual salary-review letters as password-protected PDFs directly to each employee's personal work email rather than posting a list on the breakroom noticeboard. Why is this choice of medium essential?","options":{"A":"Breakroom noticeboards are considered external communication with customers","B":"Password-protected direct emails preserve confidentiality for sensitive personal compensation data","C":"Noticeboards provide instant two-way video feedback","D":"Emails never require the sender to check message accuracy"},"correctOption":"B","correctAnswer":"Password-protected direct emails preserve confidentiality for sensitive personal compensation data","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because choosing an appropriate communication medium depends on sensitivity; confidential salary details require private, secure channels.","distractor_reasons":{"A":"Incorrect because staff breakrooms are internal.","B":"Correct selection.","C":"Incorrect because noticeboards are static one-way displays.","D":"Incorrect because senders must still verify accuracy before emailing."}}},{"id":"P1_U2_MCQ_442","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_442","question":"A supermarket manager replaces a static staff-room memo about new self-checkout procedures with a 15-minute interactive team huddle where cashiers ask questions and test the machines. Why is two-way communication superior here?","options":{"A":"Two-way communication eliminates the need for cashiers to learn the new machines","B":"Static memos are legally prohibited in retail stores","C":"Managers can immediately clarify misunderstandings through feedback and boost staff confidence before shifts begin","D":"Two-way huddles take zero minutes of staff time"},"correctOption":"C","correctAnswer":"Managers can immediately clarify misunderstandings through feedback and boost staff confidence before shifts begin","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because two-way dialogue allows receivers to ask questions, confirming true comprehension and increasing engagement.","distractor_reasons":{"A":"Incorrect because the huddle helps cashiers master the new equipment.","B":"Incorrect because memos are legal, just less effective for practical training.","C":"Correct selection.","D":"Incorrect because two-way meetings require time investment, which is their main trade-off."}}},{"id":"P1_U2_MCQ_443","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_443","question":"Which of the following examples represents external communication rather than internal communication?","options":{"A":"A Warehouse Supervisor emailing shift rosters to forklift drivers","B":"The CEO posting a quarterly update on the company's private employee intranet","C":"The Purchasing Manager emailing a formal purchase order and delivery schedule to an external packaging supplier","D":"The Finance Manager holding a budget review meeting with the Marketing Manager"},"correctOption":"C","correctAnswer":"The Purchasing Manager emailing a formal purchase order and delivery schedule to an external packaging supplier","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because external communication takes place between the business and outside stakeholders such as suppliers, customers, banks, or regulators.","distractor_reasons":{"A":"Incorrect because supervisor-to-driver messaging is internal.","B":"Incorrect because a private employee intranet is internal.","C":"Correct selection.","D":"Incorrect because meetings between two managers in the same firm are internal."}}},{"id":"P1_U2_MCQ_444","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_444","question":"A Store Manager conducts a private face-to-face meeting with a sales assistant whose punctuality has slipped, followed by a brief signed summary note. Why is face-to-face verbal communication vital for sensitive performance discussions?","options":{"A":"Face-to-face meetings prevent the employee from explaining any personal difficulties","B":"Face-to-face meetings broadcast the employee's mistakes to the entire store","C":"Spoken conversations automatically create an unalterable legal transcript without taking notes","D":"Tone of voice and body language convey empathy and seriousness, enabling constructive two-way problem-solving"},"correctOption":"D","correctAnswer":"Tone of voice and body language convey empathy and seriousness, enabling constructive two-way problem-solving","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sensitive interpersonal issues benefit from immediate non-verbal cues, supportive tone, and private dialogue—paired with written notes for record-keeping.","distractor_reasons":{"A":"Incorrect because face-to-face dialogue encourages open explanation.","B":"Incorrect because private one-to-one meetings protect employee dignity.","C":"Incorrect because spoken meetings lack a permanent record unless written minutes are kept.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_445","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_445","question":"After negotiating a 12% bulk discount over the phone with a raw-material vendor, a Procurement Officer immediately sends a formal email summarizing the agreed unit prices, quantities, and delivery dates. Why is written follow-up crucial?","options":{"A":"Phone agreements are always faster to read than emails","B":"Written confirmation creates a verifiable permanent audit trail that prevents pricing disputes when invoices arrive","C":"Emails allow the vendor to observe the Procurement Officer's facial expressions","D":"Written emails eliminate the need to inspect delivered raw materials"},"correctOption":"B","correctAnswer":"Written confirmation creates a verifiable permanent audit trail that prevents pricing disputes when invoices arrive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because written records document exact commercial terms, protecting both parties against memory lapses or billing disagreements.","distractor_reasons":{"A":"Incorrect because phone calls are spoken rather than read.","B":"Correct selection.","C":"Incorrect because plain emails do not transmit live facial expressions.","D":"Incorrect because quality inspection of goods still occurs upon delivery."}}},{"id":"P1_U2_MCQ_446","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_446","question":"During an annual investor presentation, a Chief Financial Officer displays a color-coded bar chart comparing five years of regional revenue growth alongside a 40-page financial spreadsheet. Why is the visual bar chart effective?","options":{"A":"Visual charts instantly highlight growth trends and regional comparisons that are hard to spot in dense raw tables","B":"Bar charts replace the legal requirement to publish audited financial statements","C":"Visual slides guarantee that investors will never ask critical questions","D":"Charts require zero accurate underlying financial data"},"correctOption":"A","correctAnswer":"Visual charts instantly highlight growth trends and regional comparisons that are hard to spot in dense raw tables","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual graphics simplify complex quantitative trends, aiding rapid comprehension and retention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because audited accounts remain legally mandatory.","C":"Incorrect because investors still ask questions during Q&A.","D":"Incorrect because charts must be built from verified data."}}},{"id":"P1_U2_MCQ_447","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_447","question":"An engineering firm switches its monthly cross-continental project reviews from international flights to high-definition video conferencing. What is a major benefit of video conferencing over in-person international travel?","options":{"A":"It eliminates all time-zone differences between Tokyo, London, and New York","B":"It cuts executive airfare/hotel expenses and travel downtime while preserving live facial-expression and screen-sharing interaction","C":"Video calls never experience internet bandwidth interruptions","D":"It allows engineers to physically inspect overseas factory machinery by touch"},"correctOption":"B","correctAnswer":"It cuts executive airfare/hotel expenses and travel downtime while preserving live facial-expression and screen-sharing interaction","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because video conferencing saves substantial travel costs and carbon/time overhead while retaining visual and verbal cues.","distractor_reasons":{"A":"Incorrect because geographic time zones still require scheduling coordination.","B":"Correct selection.","C":"Incorrect because technical connection glitches remain a potential risk.","D":"Incorrect because physical hands-on inspection requires on-site presence."}}},{"id":"P1_U2_MCQ_448","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_448","question":"Store managers at a retail chain receive an average of 95 'Reply-All' corporate emails every day, causing an urgent product-recall notice to be missed until two days later. Which communication barrier occurred?","options":{"A":"Information overload (excessive volume of routine messages burying critical instructions)","B":"Lack of internet access across retail stores","C":"Foreign language translation errors","D":"Overly narrow span of control"},"correctOption":"A","correctAnswer":"Information overload (excessive volume of routine messages burying critical instructions)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flooding recipients with too many low-priority messages overwhelms attention and causes vital alerts to be overlooked.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because emails were arriving continuously.","C":"Incorrect because all messages were in the same corporate language.","D":"Incorrect because narrow spans do not generate 95 daily chain emails."}}},{"id":"P1_U2_MCQ_449","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_449","question":"On a busy commercial construction site, crane operators and ground signalers struggle to hear verbal instructions over roaring excavators and jackhammers. How should the Site Manager overcome this physical noise barrier?","options":{"A":"Send lengthy printed multi-page memos to the crane cabin every hour","B":"Add four layers of off-site head-office managers to relay messages","C":"Rely on informal breakroom rumors to coordinate crane lifts","D":"Equip teams with noise-canceling two-way headsets combined with standardized visual hand signals"},"correctOption":"D","correctAnswer":"Equip teams with noise-canceling two-way headsets combined with standardized visual hand signals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because noise-canceling radio headsets and universally recognized visual hand signals bypass ambient environmental noise safely and instantaneously.","distractor_reasons":{"A":"Incorrect because printed memos are impractical during live crane maneuvers.","B":"Incorrect because off-site intermediaries would slow down urgent lift commands.","C":"Incorrect because informal rumors would be life-threatening in crane operations.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_450","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_450","question":"During corporate merger negotiations, senior executives remain silent for three months, sparking panicked rumors along the office 'grapevine' that half the workforce will be fired—prompting top engineers to resign. How can management prevent destructive grapevine rumors?","options":{"A":"Ban employees from speaking to each other during lunch breaks","B":"Provide regular, honest, and timely official updates via town halls and staff newsletters even when some details are still pending","C":"Increase the chain of command by adding three tiers of deputy directors","D":"Send dense 120-page legal merger contracts to every factory cleaner"},"correctOption":"B","correctAnswer":"Provide regular, honest, and timely official updates via town halls and staff newsletters even when some details are still pending","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because informal rumors thrive in an information vacuum; proactive, transparent communication reassures employees and preserves trust.","distractor_reasons":{"A":"Incorrect because banning breakroom conversation is unenforceable and worsens distrust.","B":"Correct selection.","C":"Incorrect because lengthening the hierarchy slows official communication further.","D":"Incorrect because 120-page legal filings create jargon and information overload."}}},{"id":"P1_U2_MCQ_451","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_451","question":"A national electronics retailer introduces an annual profit-sharing scheme that distributes 8% of company net profit equally among all 3,000 store and warehouse employees. What is a common limitation of this scheme for motivating individual staff?","options":{"A":"Individual store assistants may feel their personal daily effort barely affects overall company profit, reducing direct motivation","B":"Profit-sharing schemes are legally prohibited in retail businesses","C":"Employees must pay back part of their basic hourly wage if company profits fall","D":"Profit sharing eliminates all need for store managers to supervise staff"},"correctOption":"A","correctAnswer":"Individual store assistants may feel their personal daily effort barely affects overall company profit, reducing direct motivation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in large organizations, an individual worker sees only a tiny connection between their own effort and total corporate profit, weakening the motivational link.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit sharing is a widely used legal financial incentive.","C":"Incorrect because profit-sharing bonuses are paid on top of guaranteed basic wages.","D":"Incorrect because regular management and coordination remain necessary."}}},{"id":"P1_U2_MCQ_452","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_452","question":"A pharmaceutical firm offers senior engineers fringe benefits including private family health insurance, a subsidized on-site gym, and a company electric vehicle instead of an equivalent cash raise. How do fringe benefits help the firm?","options":{"A":"Fringe benefits guarantee zero absenteeism across all factory departments","B":"Fringe benefits legally replace the need to pay any monthly salary","C":"They enhance the total recruitment and retention package, often with tax advantages, while promoting employee wellbeing","D":"Employees can freely resell company vehicles for personal cash"},"correctOption":"C","correctAnswer":"They enhance the total recruitment and retention package, often with tax advantages, while promoting employee wellbeing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-cash perks improve employee loyalty, wellbeing, and status while often costing the firm less after tax than an equivalent salary hike.","distractor_reasons":{"A":"Incorrect because no benefit package eliminates all illness or absence.","B":"Incorrect because fringe benefits supplement core salaries.","C":"Correct selection.","D":"Incorrect because company-owned vehicles remain corporate property."}}},{"id":"P1_U2_MCQ_453","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_453","question":"A handcrafted wooden furniture workshop switches cabinetmakers from hourly wages to piece-rate pay per completed dining chair. Within two months, customer returns surge due to uneven sanding and loose joints. Why did this happen?","options":{"A":"Piece-rate pay slows workers down so much that wood dries out","B":"Cabinetmakers are legally forbidden from inspecting their own chairs","C":"Piece-rate incentives encourage workers to rush assembly to maximize volume at the expense of craftsmanship","D":"Hourly wages always cause higher defect rates than piece-rate pay"},"correctOption":"C","correctAnswer":"Piece-rate incentives encourage workers to rush assembly to maximize volume at the expense of craftsmanship","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because linking pay strictly to output quantity tempts workers to cut corners on quality unless strict inspection is enforced.","distractor_reasons":{"A":"Incorrect because piece-rate speeds workers up rather than slowing them down.","B":"Incorrect because self-inspection is permitted, though rushed workers skip careful checks.","C":"Correct selection.","D":"Incorrect because hourly time-rate pay removes the financial pressure to rush."}}},{"id":"P1_U2_MCQ_454","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_454","question":"A maintenance technician earns a basic time-rate wage of $14.00 per hour for a standard 38-hour week, with overtime paid at 1.5 times the basic hourly rate. During a busy week, the technician works 44 hours in total. What is their gross weekly pay?","options":{"A":"$616.00","B":"$798.00","C":"$532.00","D":"$658.00"},"correctOption":"D","correctAnswer":"$658.00","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because basic pay = 38 × $14.00 = $532.00; overtime hours = 44 - 38 = 6 hours at $21.00/hr ($14.00 × 1.5) = $126.00; total = $532.00 + $126.00 = $658.00.","distractor_reasons":{"A":"Incorrect because $616.00 pays all 44 hours at the basic $14.00 rate without the 1.5x overtime premium.","B":"Incorrect because $798.00 multiplies all 38 basic hours by $21.00.","C":"Incorrect because $532.00 includes only the 38 basic hours and omits the 6 overtime hours.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_455","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_455","question":"A parcel-delivery firm converts its gig-economy couriers from unpredictable daily contracts onto permanent full-time contracts with paid sick leave and a company pension plan. Which level of Maslow's hierarchy does this satisfy?","options":{"A":"Social belonging needs","B":"Self-actualization needs","C":"Safety and security needs (protection against income loss, illness, and job instability)","D":"Esteem and status needs"},"correctOption":"C","correctAnswer":"Safety and security needs (protection against income loss, illness, and job instability)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because permanent job security, sick-pay protection, and pension stability directly fulfill Maslow's safety needs.","distractor_reasons":{"A":"Incorrect because social needs involve team camaraderie and workplace friendships.","B":"Incorrect because self-actualization involves creative autonomy and reaching full potential.","C":"Correct selection.","D":"Incorrect because esteem needs focus on recognition, titles, and respect."}}},{"id":"P1_U2_MCQ_456","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_456","question":"According to Herzberg's two-factor theory, which management action acts as a true 'motivator' rather than merely a 'hygiene factor'?","options":{"A":"Installing brighter fluorescent lights in the staff locker room","B":"Giving customer-account executives responsibility for managing key client portfolios and recognizing their achievements","C":"Updating the dress-code section of the HR administrative policy manual","D":"Ensuring monthly salaries are deposited on time without payroll errors"},"correctOption":"B","correctAnswer":"Giving customer-account executives responsibility for managing key client portfolios and recognizing their achievements","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Herzberg identifies responsibility, meaningful achievement, recognition, and personal growth as intrinsic motivators.","distractor_reasons":{"A":"Incorrect because physical working conditions are a hygiene factor.","B":"Correct selection.","C":"Incorrect because company administrative policies are hygiene factors.","D":"Incorrect because pay administration is a hygiene factor that prevents dissatisfaction without actively motivating."}}},{"id":"P1_U2_MCQ_457","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_457","question":"A modern software-development studio rejects F.W. Taylor's scientific management approach for its UX designers and programmers. Why is Taylorism poorly suited to creative knowledge work?","options":{"A":"Software developers do not receive any financial salaries","B":"Scientific management forbids measuring output or setting targets","C":"Taylor advocated giving every worker complete freedom to choose their own working hours","D":"Taylorism assumes workers are motivated solely by money and reduces jobs to repetitive tasks, stifling creativity and problem-solving"},"correctOption":"D","correctAnswer":"Taylorism assumes workers are motivated solely by money and reduces jobs to repetitive tasks, stifling creativity and problem-solving","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because breaking creative work into rigid, repetitive micro-tasks ignores intrinsic motivation and suppresses innovation.","distractor_reasons":{"A":"Incorrect because developers receive competitive salaries.","B":"Incorrect because Taylor relied heavily on time-and-motion output targets.","C":"Incorrect because Taylor enforced strict managerial standardization.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_458","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_458","question":"A commercial bank trains its branch loan officers to assess credit applications, approve small-business loans up to $25,000 independently, and mentor new trainees. Which non-financial motivator is this?","options":{"A":"Horizontal job enlargement","B":"Piece-rate commission","C":"Job enrichment (vertical expansion adding decision-making authority, skill variety, and accountability)","D":"Autocratic micromanagement"},"correctOption":"C","correctAnswer":"Job enrichment (vertical expansion adding decision-making authority, skill variety, and accountability)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because granting higher-level responsibility, autonomy, and coaching duties vertically enriches the role.","distractor_reasons":{"A":"Incorrect because job enlargement adds routine tasks of the same low skill level.","B":"Incorrect because piece-rate is a financial payment per unit.","C":"Correct selection.","D":"Incorrect because micromanagement removes autonomy rather than granting it."}}},{"id":"P1_U2_MCQ_459","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_459","question":"An electric-bicycle manufacturer reorganizes its assembly line into autonomous 8-person production teams responsible for building complete bikes, rotating tasks, and running quality checks together. How does team-working motivate staff?","options":{"A":"It eliminates the need to pay any basic wages to team members","B":"It prevents workers from ever speaking to colleagues during shifts","C":"It guarantees that defective bicycles can never occur","D":"It fulfills social belonging and esteem needs through shared ownership, mutual support, and collective pride in finished products"},"correctOption":"D","correctAnswer":"It fulfills social belonging and esteem needs through shared ownership, mutual support, and collective pride in finished products","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because autonomous cell/team-working strengthens social bonds, shared responsibility, and intrinsic pride in completing a whole unit.","distractor_reasons":{"A":"Incorrect because regular wages/salaries remain paid.","B":"Incorrect because teamwork relies on active peer communication.","C":"Incorrect because quality improves, though defects are not mathematically impossible.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_460","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_460","question":"A hotel group funds accredited hospitality-management diplomas and leadership workshops for promising receptionists and housekeeping supervisors. How does training act as a non-financial motivator?","options":{"A":"It demonstrates employer investment in staff career progression, boosting competence, self-esteem, and long-term loyalty","B":"Training forces employees to accept a 20% pay cut after graduating","C":"Training removes all operational duties from supervisors permanently","D":"Herzberg classifies training as a hygiene factor that causes dissatisfaction"},"correctOption":"A","correctAnswer":"It demonstrates employer investment in staff career progression, boosting competence, self-esteem, and long-term loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because developing employee skills builds confidence, opens promotion pathways, and satisfies esteem and growth needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because upskilling normally supports career advancement and higher pay.","C":"Incorrect because trained supervisors apply their new skills on the job.","D":"Incorrect because personal growth and advancement are Herzberg motivators."}}},{"id":"P1_U2_MCQ_461","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_461","question":"A multinational food-delivery platform structures its operations into three regional divisions: Europe, Asia-Pacific, and Latin America. What is a primary advantage of a geographic organizational structure?","options":{"A":"It eliminates all local tax and labor-law differences across countries","B":"Global headquarters never needs to communicate with regional directors","C":"It avoids duplicating marketing or HR teams across different regions","D":"Regional managers can tailor menus, marketing, and courier operations rapidly to local customer preferences and regulations"},"correctOption":"D","correctAnswer":"Regional managers can tailor menus, marketing, and courier operations rapidly to local customer preferences and regulations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because geographic divisions place decision-making closer to local markets, improving cultural and regulatory responsiveness.","distractor_reasons":{"A":"Incorrect because local laws still differ and must be obeyed.","B":"Incorrect because headquarters still coordinates global strategy.","C":"Incorrect because duplication of support functions is actually a disadvantage of regional structures.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_462","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_462","question":"At a chemical plant, the HR Specialist (a staff manager) introduces a new appraisal form, but Plant Shift Managers (line managers) complain it slows down shift handovers. What is the difference between line and staff roles?","options":{"A":"Staff managers have direct authority to fire factory operatives without consulting line managers","B":"Line managers only advise external shareholders and never manage workers","C":"Line managers hold direct authority over core operational teams, whereas staff managers provide specialist advice and support","D":"Line and staff managers are external government inspectors"},"correctOption":"C","correctAnswer":"Line managers hold direct authority over core operational teams, whereas staff managers provide specialist advice and support","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because line managers sit in the direct chain of command over core output, while staff managers (HR, Legal, IT) offer specialist expertise.","distractor_reasons":{"A":"Incorrect because staff specialists advise rather than exercise direct line command.","B":"Incorrect because line managers directly supervise operational staff.","C":"Correct selection.","D":"Incorrect because both are internal employees of the business."}}},{"id":"P1_U2_MCQ_463","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_463","question":"A Regional Retail Director delegates store-level inventory ordering to newly promoted Store Managers, who over-order seasonal stock, causing warehouse congestion. What key principle of delegation does this illustrate?","options":{"A":"Managers can delegate authority to perform tasks, but ultimate accountability for results still rests with the manager","B":"Once a task is delegated, the senior manager has zero responsibility if anything goes wrong","C":"Delegation works best when subordinates receive zero training or budget guidelines","D":"Store Managers are legally immune from following inventory budgets"},"correctOption":"A","correctAnswer":"Managers can delegate authority to perform tasks, but ultimate accountability for results still rests with the manager","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegation transfers task authority, not final managerial accountability, making proper training and clear limits essential.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because senior managers remain accountable to the board for departmental performance.","C":"Incorrect because successful delegation requires training and clear parameters.","D":"Incorrect because Store Managers must operate within company budgets."}}},{"id":"P1_U2_MCQ_464","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_464","question":"A national pharmacy chain keeps all supplier purchasing, prescription-safety protocols, and retail pricing centralized at head office. What is a major benefit of centralization for this pharmacy chain?","options":{"A":"Individual branch pharmacists can invent their own medicine prices every morning","B":"Bulk purchasing at head office secures lower supplier unit costs while ensuring uniform safety standards across every branch","C":"Branch managers gain complete freedom to source unapproved drugs locally","D":"Centralization guarantees zero communication delays during local emergencies"},"correctOption":"B","correctAnswer":"Bulk purchasing at head office secures lower supplier unit costs while ensuring uniform safety standards across every branch","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because centralization unlocks bulk-buying economies of scale and enforces strict, consistent quality and safety control.","distractor_reasons":{"A":"Incorrect because centralized pricing keeps prices uniform across branches.","B":"Correct selection.","C":"Incorrect because centralized procurement prevents unauthorized local sourcing.","D":"Incorrect because slow local response is a potential drawback of centralization."}}},{"id":"P1_U2_MCQ_465","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_465","question":"Every October, the senior leadership team of a sportswear company forecasts next year's demand, sets a 12% revenue growth target, and allocates capital budgets for three new flagship stores. Which Fayol management function is this?","options":{"A":"Conducting exit interviews","B":"Dismissing underperforming store staff","C":"Planning (setting future objectives and determining the strategies and resources needed to achieve them)","D":"Industrial collective bargaining"},"correctOption":"C","correctAnswer":"Planning (setting future objectives and determining the strategies and resources needed to achieve them)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because looking ahead, defining organizational targets, and mapping resource allocation constitute the planning function.","distractor_reasons":{"A":"Incorrect because exit interviews occur when employees leave.","B":"Incorrect because disciplinary dismissal is an HR operational action.","C":"Correct selection.","D":"Incorrect because collective bargaining involves union negotiations."}}},{"id":"P1_U2_MCQ_466","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_466","question":"Before launching a new smartphone, a tech company holds weekly cross-departmental meetings so R&D hardware engineers, factory production planners, and marketing executives align their launch schedules. Which management function is this?","options":{"A":"Coordinating (bringing together the efforts of different departments so everyone works harmoniously toward shared goals)","B":"External statutory auditing","C":"Calculating statutory redundancy payouts","D":"Autocratic task specialization"},"correctOption":"A","correctAnswer":"Coordinating (bringing together the efforts of different departments so everyone works harmoniously toward shared goals)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because synchronizing activities across functional silos so launches succeed without bottlenecks is the coordinating function.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external audits verify financial statements.","C":"Incorrect because redundancy calculation is an HR termination task.","D":"Incorrect because cross-functional alignment is collaborative coordination."}}},{"id":"P1_U2_MCQ_467","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_467","question":"A head chef normally uses a democratic style when developing seasonal tasting menus with sous-chefs, but switches to an autocratic style during Saturday dinner service when 200 orders arrive simultaneously. Why is this shift effective?","options":{"A":"Effective leaders adapt their style to the situation—using collaboration for creative planning and decisive command under intense time pressure","B":"Sous-chefs forget how to cook on Saturday evenings","C":"Democratic leadership is illegal in commercial restaurant kitchens","D":"Autocratic leadership encourages every cook to change dish recipes mid-service"},"correctOption":"A","correctAnswer":"Effective leaders adapt their style to the situation—using collaboration for creative planning and decisive command under intense time pressure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because situational leadership matches style to context: participative input enriches menu design, while rapid command prevents chaos during peak service.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sous-chefs remain skilled, but peak service requires centralized timing.","C":"Incorrect because leadership style is a managerial choice, not a legal restriction.","D":"Incorrect because autocratic direction enforces strict consistency during service."}}},{"id":"P1_U2_MCQ_468","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_468","question":"At an advanced artificial-intelligence research institute, senior PhD scientists set their own research hypotheses and experimental timelines, meeting the Director only twice a year for funding reviews. Why can laissez-faire leadership succeed here?","options":{"A":"The scientists are brand-new apprentices who need constant step-by-step supervision","B":"The institute has no budget limits or research objectives","C":"Laissez-faire leadership forces scientists to follow rigid hourly factory bells","D":"Highly qualified, self-motivated experts performing original research thrive when given maximum intellectual autonomy"},"correctOption":"D","correctAnswer":"Highly qualified, self-motivated experts performing original research thrive when given maximum intellectual autonomy","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because laissez-faire leadership works best with deeply skilled, trustworthy, self-directed professionals in creative or research fields.","distractor_reasons":{"A":"Incorrect because inexperienced apprentices require close guidance.","B":"Incorrect because high-level objectives and funding reviews still exist.","C":"Incorrect because rigid control characterizes autocratic management.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_469","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_469","question":"An automotive assembly plant signs a 'single-union agreement' recognizing one trade union to represent all factory technicians and operatives. How does this benefit the employer?","options":{"A":"Employees are legally banned from ever requesting pay rises","B":"The trade union pays 50% of the factory's electricity and steel bills","C":"Management negotiates with just one representative body, saving time and avoiding rival inter-union disputes","D":"Single-union agreements eliminate all health and safety inspections"},"correctOption":"C","correctAnswer":"Management negotiates with just one representative body, saving time and avoiding rival inter-union disputes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dealing with a single recognized union streamlines collective bargaining and prevents leapfrogging pay demands between competing unions.","distractor_reasons":{"A":"Incorrect because annual pay negotiations still take place.","B":"Incorrect because unions represent members and do not fund corporate operating bills.","C":"Correct selection.","D":"Incorrect because statutory safety inspections continue."}}},{"id":"P1_U2_MCQ_470","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_470","question":"A packaging factory normally produces 2,400 boxes per day. During a union 'go-slow' protest over shift allowances, daily output drops by 35%. How many boxes does the factory produce per day during the go-slow?","options":{"A":"840 boxes","B":"1,560 boxes","C":"3,240 boxes","D":"2,365 boxes"},"correctOption":"B","correctAnswer":"1,560 boxes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 35% reduction removes 2,400 × 0.35 = 840 boxes, leaving 2,400 - 840 = 1,560 boxes per day.","distractor_reasons":{"A":"Incorrect because 840 is the number of lost boxes, not the remaining daily output.","B":"Correct selection.","C":"Incorrect because 3,240 adds 35% instead of subtracting it.","D":"Incorrect because 2,365 subtracts 35 units rather than 35%."}}},{"id":"P1_U2_MCQ_471","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_471","question":"A regional logistics company posts a Warehouse Team Leader vacancy on its internal staff intranet before advertising externally. What is a major advantage of internal recruitment regarding selection risk?","options":{"A":"Internal applicants never require an interview","B":"Internal hires are legally required to work for minimum wage","C":"Internal recruitment brings fresh ideas from rival logistics companies","D":"Managers already know the candidate's work ethic, reliability, and cultural fit, reducing the risk of a poor hiring decision"},"correctOption":"D","correctAnswer":"Managers already know the candidate's work ethic, reliability, and cultural fit, reducing the risk of a poor hiring decision","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because existing employees have a proven performance track record within the firm, lowering uncertainty compared with external strangers.","distractor_reasons":{"A":"Incorrect because internal candidates should still be interviewed fairly.","B":"Incorrect because promotions typically carry higher pay grades.","C":"Incorrect because bringing outside perspectives is an advantage of external recruitment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_472","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_472","question":"An accounting firm recruits an external candidate for a Senior Audit Manager post rather than promoting one of three long-serving internal audit seniors. What is a likely negative consequence?","options":{"A":"External recruitment costs nothing in advertising or interview time","B":"The new manager already knows every client file and internal software shortcut on Day 1","C":"Passed-over internal seniors may feel demotivated and resign due to perceived blocked career progression","D":"External recruitment reduces the total pool of applicants"},"correctOption":"C","correctAnswer":"Passed-over internal seniors may feel demotivated and resign due to perceived blocked career progression","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because appointing outsiders above ambitious internal staff can breed resentment and increase voluntary turnover.","distractor_reasons":{"A":"Incorrect because external hiring involves significant advertising, agency, and induction costs.","B":"Incorrect because external hires need time to learn internal procedures.","C":"Correct selection.","D":"Incorrect because external recruitment expands the applicant pool."}}},{"id":"P1_U2_MCQ_473","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_473","question":"How does publishing a clear, detailed job description alongside a vacancy advertisement help both the employer and prospective applicants?","options":{"A":"It enables applicants to judge whether the duties and conditions match their interests, discouraging unsuitable applications","B":"It legally binds the employer to hire every person who downloads the document","C":"It replaces the need to verify candidates' academic qualifications","D":"It lists the private medical histories of current department staff"},"correctOption":"A","correctAnswer":"It enables applicants to judge whether the duties and conditions match their interests, discouraging unsuitable applications","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transparent role duties, hours, and reporting lines allow candidates to self-select accurately and provide a clear benchmark for performance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because downloading a job description creates no hiring obligation.","C":"Incorrect because qualifications are specified in the person specification and verified separately.","D":"Incorrect because medical data is strictly confidential."}}},{"id":"P1_U2_MCQ_474","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_474","question":"Which of the following items belongs in a person specification rather than a job description?","options":{"A":"Salary range of $42,000–$46,000 per year and 25 days paid holiday","B":"Reporting directly to the Head of Customer Operations","C":"Bachelor's degree in Supply Chain Management, fluency in Mandarin, and strong analytical problem-solving skills","D":"Main duty: Scheduling weekly container shipments across three ports"},"correctOption":"C","correctAnswer":"Bachelor's degree in Supply Chain Management, fluency in Mandarin, and strong analytical problem-solving skills","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the person specification outlines the qualifications, skills, experience, and personal attributes required of the ideal candidate.","distractor_reasons":{"A":"Incorrect because pay and holiday terms belong to the job description/contract.","B":"Incorrect because reporting lines are part of the job description.","C":"Correct selection.","D":"Incorrect because core duties and tasks belong in the job description."}}},{"id":"P1_U2_MCQ_475","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_475","question":"A growing 45-employee manufacturing business has no dedicated HR department and needs to hire a qualified Production Planner quickly. Why might it use a specialist recruitment agency?","options":{"A":"Recruitment agencies work completely free of charge for employers","B":"The agency already maintains a database of vetted candidates and handles advertising and initial shortlisting, saving management time","C":"Recruitment agencies guarantee the hired employee can never resign","D":"Using an agency exempts the manufacturer from employment contracts"},"correctOption":"B","correctAnswer":"The agency already maintains a database of vetted candidates and handles advertising and initial shortlisting, saving management time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because agencies leverage existing candidate networks and handle screening logistics, saving time for smaller firms without specialist HR teams.","distractor_reasons":{"A":"Incorrect because recruitment agencies charge substantial placement fees.","B":"Correct selection.","C":"Incorrect because employees still retain the right to resign with notice.","D":"Incorrect because the employer must still issue a compliant employment contract."}}},{"id":"P1_U2_MCQ_476","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_476","question":"A digital-marketing agency asks applicants for a Senior Graphic Designer role to submit a tailored Curriculum Vitae (CV) and portfolio link rather than a rigid standardized form. Why is a CV useful here?","options":{"A":"CVs prevent candidates from describing past design awards","B":"CVs make it impossible for candidates to exaggerate weak areas","C":"Candidates can structure their layout creatively to showcase visual design flair and highlight relevant campaign achievements","D":"CVs are always faster for HR to score than standardized tick-box forms"},"correctOption":"C","correctAnswer":"Candidates can structure their layout creatively to showcase visual design flair and highlight relevant campaign achievements","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because CVs give applicants flexibility to emphasize standout accomplishments and creative presentation—especially valuable in design roles.","distractor_reasons":{"A":"Incorrect because CVs highlight awards and achievements.","B":"Incorrect because omitting weaknesses is actually a drawback of free-form CVs.","C":"Correct selection.","D":"Incorrect because varying layouts make CVs slower to compare than standardized forms."}}},{"id":"P1_U2_MCQ_477","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_477","question":"A university hospital uses a three-person interview panel (Head of Nursing, Senior Ward Matron, and HR Manager) to interview shortlisted Ward Sister candidates. What is a primary benefit of a panel interview?","options":{"A":"It intimidates candidates so they forget their clinical training","B":"It reduces individual interviewer bias and allows specialists to assess both clinical competence and HR fit in one session","C":"Panel interviews eliminate the need to check nursing licenses","D":"It uses fewer management hours than a single one-to-one interview"},"correctOption":"B","correctAnswer":"It reduces individual interviewer bias and allows specialists to assess both clinical competence and HR fit in one session","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because multiple interviewers compare notes objectively, minimizing personal prejudice while evaluating diverse criteria simultaneously.","distractor_reasons":{"A":"Incorrect because intimidating candidates is an unintended risk to manage, not a benefit.","B":"Correct selection.","C":"Incorrect because professional registration checks remain mandatory.","D":"Incorrect because three interviewers consume more total management hours than one."}}},{"id":"P1_U2_MCQ_478","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_478","question":"An international airline administers psychometric personality questionnaires to pilot applicants alongside technical simulator tests. What are psychometric personality tests designed to evaluate?","options":{"A":"Whether the applicant owns a private airplane","B":"The applicant's past salary at previous airlines","C":"The applicant's eyesight and blood pressure","D":"Behavioral traits such as emotional stability, teamwork orientation, and decision-making under stress"},"correctOption":"D","correctAnswer":"Behavioral traits such as emotional stability, teamwork orientation, and decision-making under stress","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because personality tests explore behavioral tendencies and temperament to assess suitability for high-responsibility team environments.","distractor_reasons":{"A":"Incorrect because personal asset ownership is irrelevant.","B":"Incorrect because past pay is unrelated to psychometric testing.","C":"Incorrect because eyesight and blood pressure are checked via medical examinations.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_479","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_479","question":"A call center needs 480 total agent hours per week. Option 1 hires 12 full-time agents (40 hrs/week each); Option 2 hires 24 part-time agents (20 hrs/week each). Both pay $15/hour, and initial induction costs $350 per new hire. How much more does Option 2 cost in initial induction?","options":{"A":"$4,200","B":"$8,400","C":"$3,600","D":"$0"},"correctOption":"A","correctAnswer":"$4,200","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Option 1 induction = 12 × $350 = $4,200; Option 2 induction = 24 × $350 = $8,400; extra induction cost = $8,400 - $4,200 = $4,200.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $8,400 is Option 2's total induction cost rather than the difference.","C":"Incorrect arithmetic.","D":"Incorrect because total weekly wage bills are equal ($7,200), whereas headcount-based induction doubles."}}},{"id":"P1_U2_MCQ_480","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_480","question":"An alpine ski resort hires 150 lift operators and rental technicians on fixed-term seasonal contracts from December through March. Why are temporary seasonal contracts ideal for the resort?","options":{"A":"Seasonal staff never require ski-lift safety training","B":"The resort matches staffing to winter peak demand and avoids paying wages or redundancy compensation during summer closure","C":"Seasonal workers are legally barred from receiving hourly pay","D":"Temporary staff always show higher long-term loyalty than permanent managers"},"correctOption":"B","correctAnswer":"The resort matches staffing to winter peak demand and avoids paying wages or redundancy compensation during summer closure","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fixed-term seasonal contracts align labor costs with predictable seasonal demand spikes without permanent overhead.","distractor_reasons":{"A":"Incorrect because full safety induction remains mandatory.","B":"Correct selection.","C":"Incorrect because seasonal staff are paid contracted wages.","D":"Incorrect because temporary workers often have lower commitment than permanent staff."}}},{"id":"P1_U2_MCQ_481","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_481","question":"A precision-engineering firm invests heavily in ongoing technical training for its CNC machine operators. How does this training benefit the employer over the medium term?","options":{"A":"Machines never require spare parts or electricity","B":"Trained operators are legally forbidden from asking for pay rises","C":"Higher productivity per worker, lower scrap/defect wastage, fewer workplace accidents, and reduced supervision costs","D":"Training eliminates all competition from overseas manufacturers"},"correctOption":"C","correctAnswer":"Higher productivity per worker, lower scrap/defect wastage, fewer workplace accidents, and reduced supervision costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because skilled workers operate equipment more efficiently and safely, cutting unit costs and quality defects.","distractor_reasons":{"A":"Incorrect because physical machinery maintenance continues.","B":"Incorrect because skilled workers often negotiate higher pay.","C":"Correct selection.","D":"Incorrect because training improves competitiveness rather than eliminating rivals."}}},{"id":"P1_U2_MCQ_482","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_482","question":"A boutique hotel trains new front-desk receptionists on-the-job by having the Head Receptionist coach them on the hotel's specific reservation software during quiet afternoon hours. Why is on-the-job training chosen here?","options":{"A":"It teaches theoretical macroeconomics unrelated to hotel check-ins","B":"On-the-job training guarantees the Head Receptionist has zero extra workload","C":"External colleges offer free courses on every boutique hotel's custom software","D":"It is low-cost, tailored directly to the hotel's proprietary booking system, and allows trainees to contribute immediately"},"correctOption":"D","correctAnswer":"It is low-cost, tailored directly to the hotel's proprietary booking system, and allows trainees to contribute immediately","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job coaching avoids external course fees and teaches exact company-specific systems in real working conditions.","distractor_reasons":{"A":"Incorrect because on-the-job training focuses on practical job tasks.","B":"Incorrect because coaching does add temporary workload to the trainer.","C":"Incorrect because external providers rarely teach proprietary internal software.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_483","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_483","question":"An international airline requires trainee pilots to complete 80 hours in a full-motion off-the-job flight simulator practicing engine-failure landings before flying commercial passenger jets. Why is off-the-job simulation essential here?","options":{"A":"Flight simulators are cheaper than paying pilots any salary","B":"Trainees can safely practice high-risk emergency scenarios repeatedly without endangering passengers or multi-million-dollar aircraft","C":"Simulators eliminate the need for commercial aviation licenses","D":"Off-the-job simulators never require electricity or maintenance"},"correctOption":"B","correctAnswer":"Trainees can safely practice high-risk emergency scenarios repeatedly without endangering passengers or multi-million-dollar aircraft","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because off-the-job simulation replicates extreme emergencies in a zero-risk environment where mistakes are safe learning opportunities.","distractor_reasons":{"A":"Incorrect because simulators are expensive capital investments used alongside salaries.","B":"Correct selection.","C":"Incorrect because simulator hours count toward strict licensing requirements.","D":"Incorrect because simulators require specialized technical maintenance."}}},{"id":"P1_U2_MCQ_484","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_484","question":"A courier company skips induction training during peak December rush, handing new drivers van keys on their first morning with no route-scanner walkthrough or safety briefing. What is the most likely outcome?","options":{"A":"New drivers deliver parcels 40% faster than veteran drivers on Day 1","B":"Frequent mis-deliveries, scanner errors, higher accident rates, and frustrated new hires quitting within weeks","C":"Customer satisfaction reaches an all-time record high","D":"The courier company saves money on fuel and van repairs"},"correctOption":"B","correctAnswer":"Frequent mis-deliveries, scanner errors, higher accident rates, and frustrated new hires quitting within weeks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because neglecting induction leaves new hires disoriented and unsupported, causing costly operational errors and early labor turnover.","distractor_reasons":{"A":"Incorrect because unfamiliarity slows new drivers down.","B":"Correct selection.","C":"Incorrect because mis-deliveries lower customer satisfaction.","D":"Incorrect because navigation errors and accidents increase fuel and repair costs."}}},{"id":"P1_U2_MCQ_485","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_485","question":"A beverage bottling plant installs fully automated robotic palletizers, eliminating the need for 35 manual pallet-stacking roles. Which form of workforce reduction applies to those 35 workers?","options":{"A":"Summary dismissal for gross misconduct","B":"Lateral job rotation","C":"Unfair dismissal for joining a trade union","D":"Redundancy (job roles no longer exist due to technological automation)"},"correctOption":"D","correctAnswer":"Redundancy (job roles no longer exist due to technological automation)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when new technology replaces human tasks so the jobs disappear through no fault of the workers, it is redundancy.","distractor_reasons":{"A":"Incorrect because the workers committed no misconduct.","B":"Incorrect because the roles are being eliminated rather than rotated.","C":"Incorrect because termination is driven by automation, not union activity.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_486","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_486","question":"A traditional print newspaper needs to reduce its editorial and printing workforce by 15% over two years as readers shift online, so it freezes external hiring and does not replace staff who retire or resign. What is this strategy called?","options":{"A":"Natural wastage (allowing normal retirements and voluntary resignations to shrink headcount gradually without forced layoffs)","B":"Summary gross-misconduct dismissal","C":"Employer lockout","D":"External headhunting"},"correctOption":"A","correctAnswer":"Natural wastage (allowing normal retirements and voluntary resignations to shrink headcount gradually without forced layoffs)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because natural wastage avoids redundancy compensation payouts and protects morale by letting attrition reduce staff numbers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no employee disciplinary breaches occurred.","C":"Incorrect because a lockout is an industrial-dispute tactic.","D":"Incorrect because the firm has frozen external hiring."}}},{"id":"P1_U2_MCQ_487","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_487","question":"A warehouse operative reports an unguarded conveyor belt to the national Health and Safety Executive after management ignores internal warnings, and is fired the next day. Why is this dismissal unlawful?","options":{"A":"Reporting legitimate workplace safety hazards (whistleblowing) is legally protected, making the firing an unfair dismissal","B":"Warehouse operatives are legally exempt from all safety laws","C":"The employer forgot to pay piece-rate overtime bonuses","D":"Firing whistleblowers is only illegal if the worker has 20 years of service"},"correctOption":"A","correctAnswer":"Reporting legitimate workplace safety hazards (whistleblowing) is legally protected, making the firing an unfair dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employment protection laws forbid dismissing employees for asserting statutory health and safety rights or whistleblowing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because health and safety laws protect all warehouse workers.","C":"Incorrect because the illegality stems from retaliatory dismissal.","D":"Incorrect because whistleblowing protection applies from Day 1 of employment."}}},{"id":"P1_U2_MCQ_488","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_488","question":"A commercial office-cleaning company where wages represent 72% of total operating costs faces a sharp rise in the statutory national minimum wage. Which strategic response is the company most likely to consider?","options":{"A":"Pay cleaners 25% below the legal minimum wage and omit it from payslips","B":"Renegotiate higher contract prices with corporate clients, invest in automated floor-scrubbing machines, and improve route scheduling","C":"Eliminate all paid annual holidays for part-time cleaners","D":"Switch from commercial cleaning to offshore oil drilling overnight"},"correctOption":"B","correctAnswer":"Renegotiate higher contract prices with corporate clients, invest in automated floor-scrubbing machines, and improve route scheduling","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labor-intensive firms respond to higher statutory wage floors by passing on justifiable price increases or investing in labor-saving productivity.","distractor_reasons":{"A":"Incorrect because paying below statutory minimum wage is illegal.","B":"Correct selection.","C":"Incorrect because statutory paid holiday cannot be legally removed.","D":"Incorrect because abandoning core expertise overnight is unrealistic."}}},{"id":"P1_U2_MCQ_489","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_489","question":"A financial services firm adopts 'blind CV screening', removing applicants' names, ages, genders, and photographs before hiring managers score applications against the person specification. What is the purpose of this policy?","options":{"A":"To prevent managers from ever interviewing any applicants","B":"To reduce unconscious demographic bias and promote equal opportunity in shortlisting","C":"To hide candidates' accounting qualifications and work experience","D":"Because employment law forbids candidates from ever stating their names at interviews"},"correctOption":"B","correctAnswer":"To reduce unconscious demographic bias and promote equal opportunity in shortlisting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because anonymizing personal identifiers ensures shortlisting focuses strictly on merit, skills, and qualifications rather than conscious or unconscious bias.","distractor_reasons":{"A":"Incorrect because shortlisted candidates are still invited to interviews.","B":"Correct selection.","C":"Incorrect because qualifications and relevant experience remain visible for scoring.","D":"Incorrect because names are revealed once interview invitations are issued."}}},{"id":"P1_U2_MCQ_490","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_490","question":"A furniture factory spends $45,000 installing industrial sawdust extraction units and automatic saw guards to meet updated health and safety laws. How does this compliance protect long-term profitability?","options":{"A":"It eliminates the need to buy timber raw materials","B":"It exempts the factory from paying corporate income tax","C":"Sawdust extractors automatically double the retail price of sofas","D":"It prevents costly regulatory fines, worker injury compensation claims, sick-leave disruption, and forced plant shutdowns"},"correctOption":"D","correctAnswer":"It prevents costly regulatory fines, worker injury compensation claims, sick-leave disruption, and forced plant shutdowns","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because upfront safety investment avoids far larger financial and reputational losses from accidents, litigation, and production halts.","distractor_reasons":{"A":"Incorrect because raw timber is still required.","B":"Incorrect because corporate taxes remain payable.","C":"Incorrect because product prices depend on market demand and value.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_491","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_491","question":"An Operations Manager emails a revised delivery schedule to a supplier, but the supplier never replies and ships goods on the old date. Which essential element of effective communication was missing?","options":{"A":"The sender (transmitter)","B":"Feedback (confirmation from the receiver that the message was received, understood, and acted upon)","C":"An electronic medium","D":"A tall organizational hierarchy"},"correctOption":"B","correctAnswer":"Feedback (confirmation from the receiver that the message was received, understood, and acted upon)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because without feedback confirming receipt and comprehension, the sender cannot verify that communication actually succeeded.","distractor_reasons":{"A":"Incorrect because the Operations Manager acted as the sender.","B":"Correct selection.","C":"Incorrect because email is an electronic medium.","D":"Incorrect because a tall hierarchy is not required for effective communication."}}},{"id":"P1_U2_MCQ_492","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_492","question":"When a chemical leak sensor triggers inside a manufacturing plant, automated loudspeakers broadcast a pre-recorded evacuation alarm directing all staff to Assembly Point B. Why is one-way communication appropriate here?","options":{"A":"Two-way communication is legally banned in chemical factories","B":"One-way alarms allow workers to negotiate which exit door they prefer","C":"Urgent life-safety alerts require instant, unmistakable action across the whole site without pause for discussion","D":"One-way messages always produce detailed written feedback reports"},"correctOption":"C","correctAnswer":"Urgent life-safety alerts require instant, unmistakable action across the whole site without pause for discussion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because emergency warnings prioritize speed and universal compliance over dialogue.","distractor_reasons":{"A":"Incorrect because two-way communication is widely used in normal operations.","B":"Incorrect because debating exits during an emergency wastes life-saving seconds.","C":"Correct selection.","D":"Incorrect because one-way broadcasts do not solicit receiver replies."}}},{"id":"P1_U2_MCQ_493","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_493","question":"A supermarket chain introduces an anonymous digital suggestion portal and quarterly 'Listen to Store Staff' roundtables with regional directors. How does strong upward communication benefit senior management?","options":{"A":"It prevents store assistants from ever talking to their local branch manager","B":"Upward communication eliminates the need for directors to set corporate strategy","C":"Frontline staff spot customer complaints, stock bottlenecks, and process flaws early, giving leaders practical ideas to improve operations","D":"It guarantees that every employee suggestion will be implemented immediately"},"correctOption":"C","correctAnswer":"Frontline staff spot customer complaints, stock bottlenecks, and process flaws early, giving leaders practical ideas to improve operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because frontline employees interact directly with customers and daily workflows, offering valuable operational intelligence and boosting morale when heard.","distractor_reasons":{"A":"Incorrect because upward channels complement rather than replace local branch communication.","B":"Incorrect because senior directors still formulate overall strategy.","C":"Correct selection.","D":"Incorrect because management evaluates feasibility rather than adopting every idea automatically."}}},{"id":"P1_U2_MCQ_494","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_494","question":"The Marketing Manager and Production Manager at a snack-food company hold bi-weekly coordination meetings to align promotional discounts with factory baking capacity. Which direction of internal communication is this?","options":{"A":"Downward communication","B":"Horizontal (lateral) communication between peers at the same management level across different departments","C":"External shareholder communication","D":"Upward communication from operatives to the CEO"},"correctOption":"B","correctAnswer":"Horizontal (lateral) communication between peers at the same management level across different departments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because communication between colleagues of equal rank in separate functional departments is horizontal (lateral) communication.","distractor_reasons":{"A":"Incorrect because downward communication flows from superiors to subordinates.","B":"Correct selection.","C":"Incorrect because both managers work inside the same firm.","D":"Incorrect because upward communication flows from junior staff to senior managers."}}},{"id":"P1_U2_MCQ_495","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_495","question":"An interior-design studio agrees to three custom cabinetry changes during a casual phone call with a homeowner, without sending a written quote update. When the final invoice arrives, the client disputes the extra $4,500 charge. What drawback of verbal communication caused this?","options":{"A":"Phone calls take too long to connect","B":"Phone calls are classified as visual communication","C":"Verbal communication prevents the client from asking questions","D":"Spoken conversations leave no permanent, verifiable written record of exact agreed terms"},"correctOption":"D","correctAnswer":"Spoken conversations leave no permanent, verifiable written record of exact agreed terms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because verbal agreements rely on memory and are vulnerable to misunderstanding or denial unless backed up in writing.","distractor_reasons":{"A":"Incorrect because speed is actually an advantage of phone calls.","B":"Incorrect because voice calls are verbal.","C":"Incorrect because phone calls allow immediate two-way questioning.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_496","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_496","question":"A project manager sends a short, blunt text-only email reading 'Send the revised Q3 budget now' to an overseas colleague, who interprets the message as angry and hostile. Which limitation of written electronic messages does this show?","options":{"A":"Written emails cannot be saved for future reference","B":"Lack of vocal tone and facial expressions can cause brief written messages to be misread as rude or aggressive","C":"Emails take three weeks to travel across international borders","D":"Written messages always cause information overload"},"correctOption":"B","correctAnswer":"Lack of vocal tone and facial expressions can cause brief written messages to be misread as rude or aggressive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because plain text strips out non-verbal cues (body language, warmth of tone), increasing the risk of emotional misinterpretation.","distractor_reasons":{"A":"Incorrect because emails create an automatic digital record.","B":"Correct selection.","C":"Incorrect because emails transmit almost instantaneously.","D":"Incorrect because a single short email is not information overload."}}},{"id":"P1_U2_MCQ_497","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_497","question":"An automotive assembly plant uses color-coded floor walkways, step-by-step illustrated assembly diagrams at workstations, and green/red quality status lights. Why is visual communication highly effective on the factory floor?","options":{"A":"Visual cues communicate standards instantly at a glance across noisy environments and diverse worker languages","B":"Visual diagrams replace the need to train assembly technicians","C":"Floor markings allow workers to hold two-way budget debates","D":"Visual signs are legally exempt from health and safety inspections"},"correctOption":"A","correctAnswer":"Visual cues communicate standards instantly at a glance across noisy environments and diverse worker languages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clear visual indicators bypass background machinery noise and language barriers, reinforcing accuracy and safety continuously.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hands-on training remains essential alongside visual aids.","C":"Incorrect because signs and lights are one-way visual cues.","D":"Incorrect because safety signage is actively inspected under safety regulations."}}},{"id":"P1_U2_MCQ_498","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_498","question":"An online electronics retailer introduces automated SMS and email dispatch alerts with live parcel-tracking links for customers. What is a major benefit of this external electronic communication?","options":{"A":"Customers receive real-time delivery updates automatically, improving satisfaction while reducing customer-service call volume","B":"It eliminates the physical need for delivery vans to transport parcels","C":"Automated emails completely eliminate all cybersecurity and phishing risks","D":"Retailers no longer need to maintain accurate warehouse stock levels"},"correctOption":"A","correctAnswer":"Customers receive real-time delivery updates automatically, improving satisfaction while reducing customer-service call volume","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automated digital updates keep external customers informed at minimal marginal cost and free support agents for complex queries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because physical logistics remain necessary.","C":"Incorrect because electronic systems still face cybersecurity/phishing threats.","D":"Incorrect because accurate inventory control remains vital."}}},{"id":"P1_U2_MCQ_499","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_499","question":"The IT Security Team emails a notice to non-technical retail store cashiers instructing them to 're-authenticate VPN tokens and purge DNS caches before POS synchronization', resulting in widespread confusion and inaction. Which communication barrier occurred?","options":{"A":"Semantic / technical jargon barrier (using specialist acronyms unfamiliar to the target audience)","B":"Physical acoustic noise inside a quiet office","C":"Trade union overtime ban","D":"Excessively wide span of control"},"correctOption":"A","correctAnswer":"Semantic / technical jargon barrier (using specialist acronyms unfamiliar to the target audience)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical jargon prevents receivers outside that specialty from decoding the intended action.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the barrier was incomprehensible vocabulary, not loud noise.","C":"Incorrect because no industrial action occurred.","D":"Incorrect because the problem was message wording rather than hierarchy span."}}},{"id":"P1_U2_MCQ_500","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_500","question":"In hospital pharmacies and aviation control towers, staff must repeat critical verbal dosage or altitude instructions back to the sender ('read-back protocol'). How does this overcome communication barriers?","options":{"A":"It eliminates the need for any written medical or flight records","B":"It replaces face-to-face teamwork with anonymous suggestion boxes","C":"It adds four extra layers of management between doctors and pharmacists","D":"Mandatory verbal feedback immediately verifies accurate decoding and catches misheard numbers before dangerous errors occur"},"correctOption":"D","correctAnswer":"Mandatory verbal feedback immediately verifies accurate decoding and catches misheard numbers before dangerous errors occur","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because structured two-way feedback closes the communication loop, ensuring the message received matches the message sent.","distractor_reasons":{"A":"Incorrect because written logs remain mandatory in healthcare and aviation.","B":"Incorrect because read-back is real-time operational verification.","C":"Incorrect because read-back occurs directly between sender and receiver.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_501","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_501","question":"What is meant by the term 'motivation' in a business context?","options":{"A":"The reason why employees want to work hard and work effectively for the business","B":"The legal requirement for employers to pay a statutory minimum hourly wage","C":"The formal process of passing authority down the chain of command to subordinates","D":"The total output produced by a workforce divided by the number of employees"},"correctOption":"A","correctAnswer":"The reason why employees want to work hard and work effectively for the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because motivation refers to the internal and external factors that stimulate employees to work hard and perform effectively for an organisation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this describes minimum wage legislation, which is a legal control rather than motivation.","C":"Incorrect because passing authority to subordinates defines delegation.","D":"Incorrect because output divided by number of employees defines labour productivity, which is an outcome of motivation rather than its definition."}}},{"id":"P1_U2_MCQ_502","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_502","question":"Which of the following is a direct benefit to a business of having a well-motivated workforce?","options":{"A":"Lower labour productivity and higher unit costs of production","B":"Higher rates of employee absenteeism across operational departments","C":"Lower labour turnover, which reduces recruitment and induction training costs","D":"Increased resistance from employees toward new methods of working"},"correctOption":"C","correctAnswer":"Lower labour turnover, which reduces recruitment and induction training costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because well-motivated employees are more satisfied and committed, leading to lower labour turnover and reduced hiring and training expenses.","distractor_reasons":{"A":"Incorrect because a well-motivated workforce increases labour productivity and lowers unit costs.","B":"Incorrect because high motivation reduces absenteeism rather than increasing it.","C":"Correct selection.","D":"Incorrect because motivated staff show greater willingness to accept change and new working methods."}}},{"id":"P1_U2_MCQ_503","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_503","question":"According to F.W. Taylor's theory of scientific management, what is the primary factor that motivates employees to work harder?","options":{"A":"Opportunities for creative self-actualisation and independent decision-making","B":"Strong social friendships and informal teamwork on the factory floor","C":"Financial reward, particularly paying workers according to the quantity of output they produce","D":"Public recognition awards such as 'Employee of the Month'"},"correctOption":"C","correctAnswer":"Financial reward, particularly paying workers according to the quantity of output they produce","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Taylor argued that workers are motivated mainly by money and advocated linking pay directly to output through piece-rate systems.","distractor_reasons":{"A":"Incorrect because self-actualisation is the highest level of Maslow's hierarchy, not Taylor's theory.","B":"Incorrect because social needs belong to Maslow's hierarchy and Mayo's human relations ideas rather than Taylorism.","C":"Correct selection.","D":"Incorrect because non-financial praise and recognition are linked to Maslow's esteem needs and Herzberg's motivators."}}},{"id":"P1_U2_MCQ_504","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_504","question":"In Maslow's hierarchy of needs, which level is satisfied when an employee receives recognition, status, and respect from colleagues and managers?","options":{"A":"Physiological needs","B":"Safety and security needs","C":"Social needs","D":"Esteem needs"},"correctOption":"D","correctAnswer":"Esteem needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because esteem needs in Maslow's hierarchy involve self-respect, recognition for achievements, status, and respect from others.","distractor_reasons":{"A":"Incorrect because physiological needs cover basic survival essentials such as food, shelter, and basic pay.","B":"Incorrect because safety needs involve job security, safe working conditions, and protection against income loss.","C":"Incorrect because social needs focus on belonging, friendship, and acceptance within a team rather than status or recognition.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_505","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_505","question":"According to Herzberg's two-factor theory, what is the role of 'hygiene factors' such as pay, supervision, and physical working conditions?","options":{"A":"They prevent job dissatisfaction when adequate, but do not create long-term positive motivation on their own","B":"They act as the sole intrinsic motivators that drive employees to exceed performance targets","C":"They correspond to the top level of self-actualisation in Maslow's hierarchy","D":"They only apply to senior directors and have no effect on manual workers"},"correctOption":"A","correctAnswer":"They prevent job dissatisfaction when adequate, but do not create long-term positive motivation on their own","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg stated that poor hygiene factors cause dissatisfaction, whereas improving them only removes dissatisfaction without acting as true motivators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because intrinsic factors like achievement, recognition, and responsibility are motivators, not hygiene factors.","C":"Incorrect because hygiene factors align more closely with lower-level physiological and safety needs.","D":"Incorrect because hygiene factors affect all employees across an organisation."}}},{"id":"P1_U2_MCQ_506","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_506","question":"Which financial method of motivation pays employees a fixed amount for each unit of output they produce?","options":{"A":"Time-based wage","B":"Fringe benefits","C":"Annual salary","D":"Piece-rate pay"},"correctOption":"D","correctAnswer":"Piece-rate pay","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because piece-rate pay rewards workers directly per unit produced, incentivising higher output speed.","distractor_reasons":{"A":"Incorrect because time-based pay rewards employees according to the number of hours worked rather than units produced.","B":"Incorrect because fringe benefits are non-cash perks such as a company car or health insurance.","C":"Incorrect because a salary is a fixed annual payment divided into monthly instalments, unrelated to unit output.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_507","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_507","question":"What is a major disadvantage of using commission as the sole method of paying sales staff?","options":{"A":"Sales staff have no financial incentive to increase customer sales","B":"Employees face income insecurity during periods of low consumer demand and may use aggressive selling tactics","C":"Commission is paid regardless of whether any sales are actually achieved","D":"It is illegal to pay commission in tertiary-sector retail businesses"},"correctOption":"B","correctAnswer":"Employees face income insecurity during periods of low consumer demand and may use aggressive selling tactics","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because pure commission creates unpredictable earnings when market demand falls and can encourage high-pressure selling that harms customer relationships.","distractor_reasons":{"A":"Incorrect because commission provides a strong direct incentive to maximize sales volume or value.","B":"Correct selection.","C":"Incorrect because commission is calculated strictly as a percentage of sales achieved; a fixed payment is a salary.","D":"Incorrect because commission is a standard, legal payment method in sales roles."}}},{"id":"P1_U2_MCQ_508","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_508","question":"How does 'profit sharing' differ from an individual performance 'bonus'?","options":{"A":"Profit sharing distributes a proportion of the company's overall profits among employees, whereas a bonus rewards specific individual or team targets","B":"Profit sharing is a non-financial motivator, whereas a bonus is a financial motivator","C":"Profit sharing is paid every hour, whereas a bonus is only paid upon retirement","D":"Profit sharing requires employees to purchase company shares at full market price"},"correctOption":"A","correctAnswer":"Profit sharing distributes a proportion of the company's overall profits among employees, whereas a bonus rewards specific individual or team targets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit sharing links rewards to total business profitability across the workforce, while bonuses are tied to achieving specific performance goals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both profit sharing and bonuses are financial methods of motivation.","C":"Incorrect because profit sharing is typically distributed annually after profits are calculated, not hourly.","D":"Incorrect because profit sharing is usually paid as cash or free shares out of profits, distinct from a share-purchase scheme."}}},{"id":"P1_U2_MCQ_509","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_509","question":"What is the key difference between 'job enrichment' and 'job rotation' as non-financial methods of motivation?","options":{"A":"Job enrichment adds higher-level responsibilities and decision-making authority, whereas job rotation involves switching employees between different tasks at the same skill level","B":"Job enrichment is a financial reward, whereas job rotation is a disciplinary penalty","C":"Job enrichment reduces the number of tasks a worker performs, whereas job rotation increases working hours","D":"Job enrichment only applies to part-time workers, whereas job rotation only applies to senior executives"},"correctOption":"A","correctAnswer":"Job enrichment adds higher-level responsibilities and decision-making authority, whereas job rotation involves switching employees between different tasks at the same skill level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enrichment vertically expands a role with greater autonomy and challenge, while job rotation moves workers horizontally across routine tasks to reduce boredom.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both job enrichment and job rotation are non-financial motivators.","C":"Incorrect because job enrichment adds meaningful tasks and authority rather than reducing tasks.","D":"Incorrect because both methods can be applied across different levels and contract types."}}},{"id":"P1_U2_MCQ_510","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_510","question":"Which of the following is classified as a 'fringe benefit' rather than a non-financial motivator?","options":{"A":"Receiving verbal praise from a line manager","B":"Being named 'Employee of the Month'","C":"Receiving a company car, private medical insurance, or subsidised meals","D":"Being given opportunities for internal promotion"},"correctOption":"C","correctAnswer":"Receiving a company car, private medical insurance, or subsidised meals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fringe benefits (perks) are non-cash financial rewards that carry monetary value for the employee and cost for the employer.","distractor_reasons":{"A":"Incorrect because verbal praise is a non-financial motivator.","B":"Incorrect because 'Employee of the Month' is a non-financial recognition method.","C":"Correct selection.","D":"Incorrect because opportunities for promotion are a non-financial motivator."}}},{"id":"P1_U2_MCQ_511","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_511","question":"What is meant by the term 'chain of command' in an organisational structure?","options":{"A":"The number of subordinates reporting directly to a single manager","B":"The removal of a whole layer of middle management to flatten a hierarchy","C":"The structure in an organisation which allows instructions to be passed down from senior management to lower levels of management","D":"The process of grouping employees into functional departments such as finance and marketing"},"correctOption":"C","correctAnswer":"The structure in an organisation which allows instructions to be passed down from senior management to lower levels of management","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the chain of command is the formal vertical line of authority through which orders and instructions flow downward from top to bottom.","distractor_reasons":{"A":"Incorrect because the number of direct subordinates defines the span of control.","B":"Incorrect because removing a layer of management defines delayering.","C":"Correct selection.","D":"Incorrect because grouping by specialist activity describes functional departmentalisation."}}},{"id":"P1_U2_MCQ_512","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_512","question":"What does 'span of control' refer to on an organisational chart?","options":{"A":"The total number of levels of hierarchy between the Chief Executive Officer and shop-floor workers","B":"The maximum budget a department manager is permitted to spend without board approval","C":"The geographic distance between a company's head office and its branch stores","D":"The number of subordinates working directly under a manager"},"correctOption":"D","correctAnswer":"The number of subordinates working directly under a manager","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because span of control measures how many employees report directly to one manager or supervisor.","distractor_reasons":{"A":"Incorrect because the number of levels defines the height of the hierarchy and length of the chain of command.","B":"Incorrect because spending authority relates to financial delegation limits rather than span of control.","C":"Incorrect because span of control is an organisational reporting relationship, not a physical distance.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_513","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_513","question":"What is a direct structural consequence when a business carries out 'delayering'?","options":{"A":"The chain of command becomes longer and spans of control become narrower","B":"The chain of command becomes shorter and managers' spans of control become wider","C":"Additional layers of middle management are created to increase supervision","D":"All functional departments are abolished and replaced by sole traders"},"correctOption":"B","correctAnswer":"The chain of command becomes shorter and managers' spans of control become wider","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because removing a tier of management shortens the chain of command, speeds up communication, and requires remaining managers to supervise more direct reports.","distractor_reasons":{"A":"Incorrect because delayering shortens the chain of command and widens spans of control rather than the reverse.","B":"Correct selection.","C":"Incorrect because delayering removes management layers rather than adding them.","D":"Incorrect because functional departments still exist within a flatter hierarchy."}}},{"id":"P1_U2_MCQ_514","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_514","question":"Which of the following is a disadvantage of having a 'tall' organisational structure with a long chain of command?","options":{"A":"Managers have excessively wide spans of control and cannot supervise staff closely","B":"There are very few opportunities for internal promotion within the hierarchy","C":"Communication from senior management to lower levels is slow and messages may become distorted","D":"Subordinates receive zero guidance or supervision from line managers"},"correctOption":"C","correctAnswer":"Communication from senior management to lower levels is slow and messages may become distorted","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because passing messages through many hierarchical layers slows down decision-making and increases the risk of misinterpretation.","distractor_reasons":{"A":"Incorrect because tall structures typically feature narrow spans of control, allowing close supervision.","B":"Incorrect because multiple hierarchical tiers actually provide clear promotion pathways.","C":"Correct selection.","D":"Incorrect because narrow spans of control allow close managerial guidance."}}},{"id":"P1_U2_MCQ_515","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_515","question":"What is meant by 'delegation' in management?","options":{"A":"Transferring final legal accountability for departmental failure onto junior employees","B":"Consulting trade union representatives before changing shift schedules","C":"Dismissing surplus workers when technology replaces manual tasks","D":"Giving a subordinate the authority to perform particular tasks while the manager retains ultimate responsibility"},"correctOption":"D","correctAnswer":"Giving a subordinate the authority to perform particular tasks while the manager retains ultimate responsibility","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delegation empowers subordinates with the authority to carry out specific duties, though the manager remains accountable for the final outcome.","distractor_reasons":{"A":"Incorrect because managers can delegate authority, never ultimate accountability.","B":"Incorrect because consulting unions is collective negotiation rather than delegation.","C":"Incorrect because dismissing surplus workers due to automation describes redundancy.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_516","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_516","question":"Which function of management involves setting aims and targets for the future and determining the resources needed to achieve them?","options":{"A":"Commanding","B":"Controlling","C":"Planning","D":"Coordinating"},"correctOption":"C","correctAnswer":"Planning","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because planning sets future objectives and maps out the strategies and resources required to reach them.","distractor_reasons":{"A":"Incorrect because commanding involves guiding, leading, and instructing employees in their daily duties.","B":"Incorrect because controlling involves measuring actual performance against targets and taking corrective action.","C":"Correct selection.","D":"Incorrect because coordinating brings together people and departments so their efforts align harmoniously."}}},{"id":"P1_U2_MCQ_517","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_517","question":"Which function of management involves monitoring and measuring actual performance against planned targets and taking corrective action if necessary?","options":{"A":"Organising","B":"Controlling","C":"Commanding","D":"Planning"},"correctOption":"B","correctAnswer":"Controlling","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because controlling checks whether tasks are being performed according to plan and corrects deviations.","distractor_reasons":{"A":"Incorrect because organising involves delegating tasks and arranging resources so plans can be executed.","B":"Correct selection.","C":"Incorrect because commanding involves directing and supervising subordinates.","D":"Incorrect because planning sets initial future objectives rather than checking ongoing results."}}},{"id":"P1_U2_MCQ_518","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_518","question":"Which characteristic best describes an 'autocratic' leadership style?","options":{"A":"The leader encourages two-way communication and involves employees in making major decisions","B":"The leader makes all decisions alone without consulting staff and expects instructions to be obeyed without question","C":"The leader sets broad objectives and leaves employees completely free to decide how to organise their own work","D":"The leader delegates all strategic authority to trade union shop stewards"},"correctOption":"B","correctAnswer":"The leader makes all decisions alone without consulting staff and expects instructions to be obeyed without question","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because autocratic leaders retain full decision-making power and rely on one-way downward communication.","distractor_reasons":{"A":"Incorrect because involving employees and encouraging two-way communication describes democratic leadership.","B":"Correct selection.","C":"Incorrect because giving employees wide autonomy to make their own decisions describes laissez-faire leadership.","D":"Incorrect because autocratic leaders do not hand strategic control to unions."}}},{"id":"P1_U2_MCQ_519","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_519","question":"What is a primary advantage of a 'democratic' leadership style?","options":{"A":"Decisions are always made instantaneously during emergencies without any discussion","B":"Managers never need to communicate with subordinates","C":"Employees feel valued because their ideas are consulted, leading to better decisions and higher motivation","D":"Employees have total freedom to ignore company goals and set their own pay"},"correctOption":"C","correctAnswer":"Employees feel valued because their ideas are consulted, leading to better decisions and higher motivation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because democratic leadership draws on employee expertise and participation, boosting morale and decision quality.","distractor_reasons":{"A":"Incorrect because consultation takes time, making democratic leadership slower than autocratic leadership in emergencies.","B":"Incorrect because democratic leadership relies heavily on two-way communication.","C":"Correct selection.","D":"Incorrect because democratic leaders still guide the team toward business objectives rather than permitting anarchy."}}},{"id":"P1_U2_MCQ_520","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_520","question":"What is a 'trade union'?","options":{"A":"A government ministry that inspects factories for environmental pollution","B":"A private recruitment agency that supplies temporary staff to businesses","C":"An association of rival companies formed to fix market prices","D":"A group of employees who have joined together to ensure their interests are protected"},"correctOption":"D","correctAnswer":"A group of employees who have joined together to ensure their interests are protected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a trade union is an organisation formed by workers to protect and improve their pay, working conditions, and employment rights through collective representation.","distractor_reasons":{"A":"Incorrect because government regulatory bodies enforce laws rather than representing employees.","B":"Incorrect because a recruitment agency is a commercial staffing intermediary.","C":"Incorrect because price-fixing among rival firms describes an illegal cartel, not a trade union.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_521","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_521","question":"What is the purpose of carrying out a 'job analysis' as the first step in the recruitment process?","options":{"A":"To identify and record the responsibilities and tasks relating to a job","B":"To negotiate redundancy payments for departing employees","C":"To compare the annual salaries paid by rival firms in different countries","D":"To conduct psychometric personality tests on shortlisted candidates"},"correctOption":"A","correctAnswer":"To identify and record the responsibilities and tasks relating to a job","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job analysis examines what a role actually involves so that an accurate job description and person specification can be prepared.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because redundancy occurs during downsizing rather than recruitment.","C":"Incorrect because external salary benchmarking is not the definition of job analysis.","D":"Incorrect because psychometric testing takes place later during the selection stage."}}},{"id":"P1_U2_MCQ_522","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_522","question":"Which recruitment document outlines the responsibilities and duties to be carried out by someone employed to do a specific job?","options":{"A":"Person specification","B":"Curriculum vitae (CV)","C":"Job description","D":"Letter of reference"},"correctOption":"C","correctAnswer":"Job description","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a job description details the job title, main duties, responsibilities, working conditions, and reporting lines of the role.","distractor_reasons":{"A":"Incorrect because a person specification lists the qualifications, skills, and qualities required of the applicant.","B":"Incorrect because a CV is prepared by the applicant summarizing their own education and work history.","C":"Correct selection.","D":"Incorrect because a reference is a report on a candidate's past performance from a previous employer or referee."}}},{"id":"P1_U2_MCQ_523","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_523","question":"Which of the following items is included in a 'person specification' rather than a 'job description'?","options":{"A":"The specific daily tasks and machinery the employee will operate","B":"The name of the line manager to whom the employee will report","C":"The department to which the job belongs and the job title","D":"The qualifications, experience, personal characteristics, and skills required from applicants"},"correctOption":"D","correctAnswer":"The qualifications, experience, personal characteristics, and skills required from applicants","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the person specification defines the attributes of the ideal person needed to perform the job effectively.","distractor_reasons":{"A":"Incorrect because daily tasks and duties belong in the job description.","B":"Incorrect because reporting lines are specified in the job description.","C":"Incorrect because job title and department are features of the job description.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_524","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_524","question":"What is meant by 'internal recruitment'?","options":{"A":"Filling a vacancy with someone who is already employed by the business","B":"Advertising a vacancy on public job websites and in national newspapers","C":"Hiring a specialist external recruitment agency to headhunt managers","D":"Recruiting part-time workers on temporary seasonal contracts"},"correctOption":"A","correctAnswer":"Filling a vacancy with someone who is already employed by the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal recruitment appoints an existing employee to the vacant role, often through promotion or internal transfer.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising to the public outside the organisation is external recruitment.","C":"Incorrect because using an agency to source outside applicants is external recruitment.","D":"Incorrect because contract duration does not define internal versus external recruitment."}}},{"id":"P1_U2_MCQ_525","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_525","question":"Which of the following is an advantage of 'external recruitment' over 'internal recruitment'?","options":{"A":"It is always cheaper and faster because no external advertising is needed","B":"It brings new ideas, fresh perspectives, and wider experience into the business","C":"The applicant's reliability and work ethic are already directly known by managers","D":"It eliminates the need to provide any induction training"},"correctOption":"B","correctAnswer":"It brings new ideas, fresh perspectives, and wider experience into the business","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external hires come from outside the firm and can introduce fresh skills, innovative practices, and broader industry experience.","distractor_reasons":{"A":"Incorrect because lower cost and speed are advantages of internal recruitment, whereas external recruitment is more expensive.","B":"Correct selection.","C":"Incorrect because direct prior knowledge of the worker is an advantage of internal recruitment.","D":"Incorrect because external recruits actually require more induction training than internal hires."}}},{"id":"P1_U2_MCQ_526","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_526","question":"What is a key advantage to an employer of asking candidates to complete a standardised 'application form' rather than submitting only a free-form CV?","options":{"A":"Application forms allow candidates to hide gaps in their employment history","B":"Application forms replace the need to conduct job interviews","C":"All candidates provide information in the same format, making it easier and fairer for the employer to compare applicants","D":"Application forms are legally binding employment contracts once submitted"},"correctOption":"C","correctAnswer":"All candidates provide information in the same format, making it easier and fairer for the employer to compare applicants","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because standardised forms ask every candidate identical questions, enabling objective side-by-side comparison against the person specification.","distractor_reasons":{"A":"Incorrect because hiding weak areas is a drawback of free-form CVs, whereas application forms require specific fields to be completed.","B":"Incorrect because application forms are used for shortlisting prior to interviews.","C":"Correct selection.","D":"Incorrect because an application form is an expression of interest, not an employment contract."}}},{"id":"P1_U2_MCQ_527","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_527","question":"Why do employers request 'references' during the employee selection process?","options":{"A":"To test the candidate's physical stamina and manual dexterity","B":"To comply with statutory minimum wage calculations","C":"To advertise upcoming vacancies to other businesses","D":"To obtain an independent, confidential opinion on the candidate's character, reliability, and past work performance"},"correctOption":"D","correctAnswer":"To obtain an independent, confidential opinion on the candidate's character, reliability, and past work performance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because references verify the accuracy of a candidate's claims and provide insight into their past conduct and suitability from previous employers or tutors.","distractor_reasons":{"A":"Incorrect because physical or practical skills are evaluated through aptitude/practical tests.","B":"Incorrect because references have nothing to do with minimum wage laws.","C":"Incorrect because references assess a specific applicant rather than advertising roles.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_528","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_528","question":"What is the main purpose of using 'assessment centres' during the selection of candidates?","options":{"A":"To assess candidates over one or more days using a combination of group exercises, presentations, role-plays, and interviews","B":"To provide retired workers with free career counselling","C":"To negotiate collective wage agreements with trade unions","D":"To store unsold finished goods inventory before dispatch"},"correctOption":"A","correctAnswer":"To assess candidates over one or more days using a combination of group exercises, presentations, role-plays, and interviews","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assessment centres observe how shortlisted candidates perform across realistic multi-task exercises, teamwork, and interviews.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because assessment centres are used to evaluate job applicants during selection.","C":"Incorrect because union wage negotiations are part of industrial relations.","D":"Incorrect because storing finished goods is a warehouse operations activity."}}},{"id":"P1_U2_MCQ_529","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_529","question":"Which of the following is an advantage to a business of employing 'part-time' employees rather than 'full-time' employees?","options":{"A":"Lower total induction training costs per hour worked because fewer staff need to be trained","B":"Greater staffing flexibility to cover peak trading hours or weekends without paying for idle time during quiet periods","C":"Part-time workers always show higher commitment and require less communication than full-time workers","D":"Part-time employees are excluded from all health and safety and minimum wage protections"},"correctOption":"B","correctAnswer":"Greater staffing flexibility to cover peak trading hours or weekends without paying for idle time during quiet periods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because part-time contracts allow businesses to match labour supply precisely to busy periods and extend operating hours flexibly.","distractor_reasons":{"A":"Incorrect because hiring more part-time workers to cover the same total hours increases recruitment and induction costs.","B":"Correct selection.","C":"Incorrect because part-time workers can be harder to communicate with and may feel less committed.","D":"Incorrect because employment laws protect part-time and full-time employees alike."}}},{"id":"P1_U2_MCQ_530","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_530","question":"What is a potential disadvantage to an employer of offering 'home working' as a flexible working arrangement?","options":{"A":"Higher office rent and utility expenses for the business","B":"The business is limited to recruiting only people living within walking distance of the office","C":"Employees spend significantly more time commuting to the workplace","D":"It is more difficult for managers to supervise staff closely and maintain team cohesion"},"correctOption":"D","correctAnswer":"It is more difficult for managers to supervise staff closely and maintain team cohesion","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because remote work reduces face-to-face interaction, making direct supervision, performance monitoring, and team bonding harder.","distractor_reasons":{"A":"Incorrect because home working typically reduces office space and utility costs.","B":"Incorrect because home working widens the geographic pool of potential recruits.","C":"Incorrect because home working eliminates commuting time.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_531","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_531","question":"What is the main purpose of 'induction training'?","options":{"A":"To introduce a new employee to the business, its procedures, health and safety rules, and fellow workers","B":"To retrain long-serving employees for external jobs before making them redundant","C":"To send senior managers to external universities for postgraduate degrees","D":"To test shortlisted job applicants before offering them a contract"},"correctOption":"A","correctAnswer":"To introduce a new employee to the business, its procedures, health and safety rules, and fellow workers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because induction training helps new recruits settle quickly, understand workplace policies and safety regulations, and become productive sooner.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because induction is provided at the start of employment, not upon redundancy.","C":"Incorrect because external university courses are an example of off-the-job training.","D":"Incorrect because induction occurs after a candidate has accepted the job offer."}}},{"id":"P1_U2_MCQ_532","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_532","question":"Which of the following is an advantage of 'on-the-job training'?","options":{"A":"Employees learn in a quiet classroom away from workplace distractions","B":"Trainees are guaranteed to learn the latest industry techniques from independent specialists","C":"It is relatively low-cost because no external course fees or travel expenses are required, and output is still produced","D":"The experienced trainer's own productivity never slows down while coaching"},"correctOption":"C","correctAnswer":"It is relatively low-cost because no external course fees or travel expenses are required, and output is still produced","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because on-the-job training uses internal staff and equipment at the workplace, keeping direct training costs low while maintaining some output.","distractor_reasons":{"A":"Incorrect because learning away from workplace distractions is an advantage of off-the-job training.","B":"Incorrect because on-the-job training relies on internal staff, who may pass on existing bad habits rather than external innovations.","C":"Correct selection.","D":"Incorrect because the experienced worker's output usually decreases while supervising the trainee."}}},{"id":"P1_U2_MCQ_533","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_533","question":"What is a major disadvantage of 'off-the-job training' for a business?","options":{"A":"Trainees are likely to pick up bad working habits from existing factory colleagues","B":"It is expensive due to external course fees, and the business loses the employee's output while they are away training","C":"It cannot teach any theoretical knowledge or accredited qualifications","D":"Customers are directly disrupted by trainees making mistakes on the shop floor"},"correctOption":"B","correctAnswer":"It is expensive due to external course fees, and the business loses the employee's output while they are away training","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external courses involve direct fees and travel costs plus the opportunity cost of lost working hours.","distractor_reasons":{"A":"Incorrect because picking up bad habits from coworkers is a drawback of on-the-job training.","B":"Correct selection.","C":"Incorrect because teaching broad theory and accredited qualifications is a strength of off-the-job training.","D":"Incorrect because shop-floor disruption and customer errors occur during on-the-job training."}}},{"id":"P1_U2_MCQ_534","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_534","question":"How does 'redundancy' differ from 'dismissal'?","options":{"A":"Redundancy occurs because the job role is no longer needed by the business, whereas dismissal occurs when an employee's contract is ended due to unsatisfactory behaviour or performance","B":"Redundancy is a punishment for gross misconduct, whereas dismissal occurs when a business closes a factory","C":"Redundancy only applies to part-time workers, whereas dismissal only applies to full-time managers","D":"Redundancy never entitles workers to financial compensation, whereas dismissal always includes a large bonus"},"correctOption":"A","correctAnswer":"Redundancy occurs because the job role is no longer needed by the business, whereas dismissal occurs when an employee's contract is ended due to unsatisfactory behaviour or performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because redundancy happens through no fault of the worker when the position ceases to exist, whereas dismissal is due to the employee's conduct or capability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the two definitions.","C":"Incorrect because both redundancy and dismissal apply across all contract types and levels.","D":"Incorrect because redundant workers are often entitled to statutory redundancy pay, whereas dismissed workers are not."}}},{"id":"P1_U2_MCQ_535","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_535","question":"Which of the following is a common reason why a business may need to downsize and reduce the size of its workforce?","options":{"A":"A rapid surge in customer orders that exceeds maximum factory capacity","B":"Expansion into profitable new international retail markets","C":"An increase in government grants to hire extra apprentices","D":"Introduction of automation and new technology that replaces manual labour"},"correctOption":"D","correctAnswer":"Introduction of automation and new technology that replaces manual labour","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automating production processes reduces the number of human workers required, alongside falling demand or the need to cut costs.","distractor_reasons":{"A":"Incorrect because surging demand requires hiring more staff or overtime, not downsizing.","B":"Incorrect because expanding into new markets typically increases staffing needs.","C":"Incorrect because hiring grants encourage workforce expansion.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_536","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_536","question":"Which of the following is a standard main content of a written 'contract of employment'?","options":{"A":"The business's confidential five-year marketing budget and competitor pricing data","B":"A list of all shareholders and the market value of their shares","C":"The employee's duties and responsibilities, working hours, holiday entitlement, and sick pay terms","D":"The personal home addresses and bank details of all customers"},"correctOption":"C","correctAnswer":"The employee's duties and responsibilities, working hours, holiday entitlement, and sick pay terms","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an employment contract is a legally binding agreement setting out the rights and obligations of both employer and employee, including duties, hours, holidays, and sick pay.","distractor_reasons":{"A":"Incorrect because strategic marketing budgets are internal financial documents, not employment contract terms.","B":"Incorrect because shareholder registers belong to company secretarial records.","C":"Correct selection.","D":"Incorrect because customer data is protected under data privacy laws and unrelated to employment contracts."}}},{"id":"P1_U2_MCQ_537","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_537","question":"How does a written contract of employment benefit an employer?","options":{"A":"It guarantees that employees can never resign or join a trade union","B":"It clearly defines the duties, hours, and standards expected from the employee, helping resolve disputes legally","C":"It exempts the employer from complying with health and safety laws","D":"It allows the employer to cut wages below the statutory minimum without notice"},"correctOption":"B","correctAnswer":"It clearly defines the duties, hours, and standards expected from the employee, helping resolve disputes legally","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a clear written contract establishes enforceable expectations regarding job duties, notice periods, and conduct.","distractor_reasons":{"A":"Incorrect because employees retain the legal right to resign with notice and join trade unions.","B":"Correct selection.","C":"Incorrect because statutory health and safety obligations cannot be contracted out of.","D":"Incorrect because contracts cannot override statutory minimum wage laws."}}},{"id":"P1_U2_MCQ_538","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_538","question":"Under employment legislation, which of the following constitutes 'unfair dismissal'?","options":{"A":"Dismissing an employee for stealing company funds after a fair disciplinary investigation","B":"Dismissing an employee who repeatedly refuses to follow safety rules despite formal warnings","C":"Making an employee redundant with statutory compensation after their factory closes down","D":"Dismissing an employee for joining a trade union or for becoming pregnant"},"correctOption":"D","correctAnswer":"Dismissing an employee for joining a trade union or for becoming pregnant","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employment protection laws prohibit ending an employee's contract for discriminatory or protected reasons such as pregnancy or union membership.","distractor_reasons":{"A":"Incorrect because theft is gross misconduct and constitutes fair dismissal when properly investigated.","B":"Incorrect because persistent refusal to obey safety rules after warnings justifies fair dismissal.","C":"Incorrect because genuine redundancy following factory closure is lawful.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_539","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_539","question":"What is the primary purpose of anti-discrimination legislation in employment?","options":{"A":"To ensure employers treat applicants and workers fairly regardless of characteristics such as gender, race, age, religion, or disability","B":"To force businesses to hire unqualified applicants regardless of the person specification","C":"To require all employees in every department to be paid the exact same salary","D":"To ban businesses from conducting job interviews or aptitude tests"},"correctOption":"A","correctAnswer":"To ensure employers treat applicants and workers fairly regardless of characteristics such as gender, race, age, religion, or disability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because anti-discrimination laws require recruitment, pay, training, and promotion decisions to be based on merit rather than protected personal characteristics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employers still select candidates based on relevant qualifications and skills.","C":"Incorrect because pay can legally vary by role, skill, and seniority, provided there is equal pay for equal work.","D":"Incorrect because objective interviews and job-related tests remain completely lawful."}}},{"id":"P1_U2_MCQ_540","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_540","question":"What is a likely economic effect on a business when the government introduces or increases a 'legal minimum wage'?","options":{"A":"Wage costs increase for businesses employing low-paid staff, which may encourage investment in labour-saving machinery or higher prices","B":"Total labour costs fall automatically because overtime pay is abolished","C":"All employees become exempt from paying income tax","D":"Employee motivation and living standards fall across the entire economy"},"correctOption":"A","correctAnswer":"Wage costs increase for businesses employing low-paid staff, which may encourage investment in labour-saving machinery or higher prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a higher statutory wage floor raises payroll expenses for labour-intensive firms, prompting productivity improvements, automation, or price adjustments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws increase rather than reduce wage rates.","C":"Incorrect because income tax rules are separate from minimum wage legislation.","D":"Incorrect because higher minimum wages raise the earnings and living standards of low-paid workers."}}},{"id":"P1_U2_MCQ_541","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_541","question":"When is communication considered to be 'effective' in a business?","options":{"A":"When the sender transmits an email using the fastest possible internet connection","B":"When the message is received, accurately understood by the receiver, and acted upon with appropriate feedback to the sender","C":"When a manager issues written instructions without allowing any questions from staff","D":"When the message is sent simultaneously through at least five different media channels"},"correctOption":"B","correctAnswer":"When the message is received, accurately understood by the receiver, and acted upon with appropriate feedback to the sender","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because effective communication requires accurate transmission, comprehension by the receiver, and confirmation via feedback.","distractor_reasons":{"A":"Incorrect because fast transmission alone does not guarantee the receiver understood or acted on the message.","B":"Correct selection.","C":"Incorrect because blocking feedback prevents the sender from verifying understanding.","D":"Incorrect because repeating messages across many channels can cause information overload."}}},{"id":"P1_U2_MCQ_542","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_542","question":"In the communication process, what is the role of the 'medium' (or channel)?","options":{"A":"The person or department initiating the message","B":"The reply sent back by the recipient to confirm understanding","C":"The method used to send the message, such as a face-to-face meeting, email, telephone call, or noticeboard","D":"The technical jargon that distorts the meaning of the message"},"correctOption":"C","correctAnswer":"The method used to send the message, such as a face-to-face meeting, email, telephone call, or noticeboard","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the medium is the vehicle or channel through which the sender transmits information to the receiver.","distractor_reasons":{"A":"Incorrect because the person initiating the message is the sender (transmitter).","B":"Incorrect because the recipient's reply is feedback.","C":"Correct selection.","D":"Incorrect because technical jargon is a communication barrier, not the medium."}}},{"id":"P1_U2_MCQ_543","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_543","question":"Which of the following is an example of 'external communication'?","options":{"A":"A supervisor briefing factory workers on daily production targets","B":"A company sending an order confirmation email to a raw-material supplier or advertising a product to customers","C":"The Finance Director emailing monthly departmental budgets to the Marketing Manager","D":"An employee posting a shift-swap notice in the staff canteen"},"correctOption":"B","correctAnswer":"A company sending an order confirmation email to a raw-material supplier or advertising a product to customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external communication takes place between the business and outside stakeholders such as customers, suppliers, banks, or the government.","distractor_reasons":{"A":"Incorrect because communication between a supervisor and workers inside the firm is internal communication.","B":"Correct selection.","C":"Incorrect because communication between two managers in the same company is internal horizontal communication.","D":"Incorrect because staff canteen notices are internal communication."}}},{"id":"P1_U2_MCQ_544","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_544","question":"What is the key difference between 'one-way communication' and 'two-way communication'?","options":{"A":"One-way communication does not allow for feedback from the receiver, whereas two-way communication involves a response or discussion between sender and receiver","B":"One-way communication is always written, whereas two-way communication is always visual","C":"One-way communication is used exclusively with external customers, whereas two-way communication is only used internally","D":"One-way communication is slower than two-way communication because it requires formal meetings"},"correctOption":"A","correctAnswer":"One-way communication does not allow for feedback from the receiver, whereas two-way communication involves a response or discussion between sender and receiver","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because one-way communication flows in a single direction without expecting a reply, whereas two-way communication completes the loop with receiver feedback.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both one-way and two-way communication can be spoken, written, or electronic.","C":"Incorrect because both forms occur internally and externally.","D":"Incorrect because one-way communication is generally faster precisely because it skips discussion."}}},{"id":"P1_U2_MCQ_545","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_545","question":"What is meant by 'horizontal communication' within an organisation?","options":{"A":"Orders passed downward from the Managing Director to frontline operatives","B":"Press releases issued by the company to external journalists","C":"Suggestions sent upward from shop-floor employees to senior directors","D":"Messages exchanged between people at the same level of authority in the organisation, such as two department managers"},"correctOption":"D","correctAnswer":"Messages exchanged between people at the same level of authority in the organisation, such as two department managers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because horizontal (lateral) communication occurs across the same hierarchical tier, enabling coordination between departments.","distractor_reasons":{"A":"Incorrect because messages flowing from top to bottom represent downward communication.","B":"Incorrect because press releases to journalists are external communication.","C":"Incorrect because messages flowing from lower tiers to senior management represent upward communication.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_546","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_546","question":"What is a major advantage of 'written communication' (such as formal letters, reports, or emails) compared with 'verbal communication'?","options":{"A":"It always provides immediate body-language cues and vocal tone","B":"It provides permanent documentary evidence that can be referred back to later and copied accurately to many recipients","C":"It guarantees that every recipient reads and understands the message instantly","D":"It is impossible for written messages to be misunderstood or lost"},"correctOption":"B","correctAnswer":"It provides permanent documentary evidence that can be referred back to later and copied accurately to many recipients","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because written records create an auditable trail of exact wording and details that can be reviewed whenever needed.","distractor_reasons":{"A":"Incorrect because body language and tone of voice are advantages of face-to-face verbal communication, not written text.","B":"Correct selection.","C":"Incorrect because recipients may delay reading emails or letters, and feedback is not immediate.","D":"Incorrect because written messages can still suffer from poor wording, jargon, or overload."}}},{"id":"P1_U2_MCQ_547","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_547","question":"Which advantage is specific to 'face-to-face meetings' compared with written emails or text messages?","options":{"A":"A permanent word-for-word written record is automatically created without taking minutes","B":"It requires zero travel time or scheduling coordination across time zones","C":"Participants can observe facial expressions and body language while asking questions for immediate two-way feedback","D":"Messages can be broadcast instantaneously to millions of external followers"},"correctOption":"C","correctAnswer":"Participants can observe facial expressions and body language while asking questions for immediate two-way feedback","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because face-to-face interaction combines spoken words with non-verbal cues and instant clarification.","distractor_reasons":{"A":"Incorrect because face-to-face meetings leave no automatic written record unless minutes are recorded.","B":"Incorrect because coordinating schedules and travel is a disadvantage of physical meetings.","C":"Correct selection.","D":"Incorrect because mass instant broadcasting is a feature of social media or electronic alerts."}}},{"id":"P1_U2_MCQ_548","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_548","question":"Why are 'visual methods of communication' (such as charts, diagrams, posters, and safety signs) effective in a business?","options":{"A":"They can present complex data or safety instructions clearly and attractively so they are understood quickly","B":"They allow detailed two-way negotiation between managers and suppliers","C":"They completely eliminate the need for any written employment contracts","D":"They require no design effort and are always free to produce"},"correctOption":"A","correctAnswer":"They can present complex data or safety instructions clearly and attractively so they are understood quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual aids simplify trends and instructions at a glance, overcoming language barriers and capturing attention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because visual displays like posters and charts are typically one-way rather than interactive negotiations.","C":"Incorrect because legal contracts require formal written terms.","D":"Incorrect because producing clear graphics and signage requires time and cost."}}},{"id":"P1_U2_MCQ_549","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_549","question":"What is a key disadvantage of using 'electronic communication' such as emails and instant messaging in the workplace?","options":{"A":"Messages take several days to reach recipients in the same building","B":"Employees may suffer from information overload due to excessive messages, and systems face cybersecurity risks","C":"Electronic messages cannot include attachments or charts","D":"It is impossible to send an email to more than one person at a time"},"correctOption":"B","correctAnswer":"Employees may suffer from information overload due to excessive messages, and systems face cybersecurity risks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high volumes of emails and messages can overwhelm staff so important items are missed, alongside risks of hacking or technical failure.","distractor_reasons":{"A":"Incorrect because electronic messages transmit almost instantaneously.","B":"Correct selection.","C":"Incorrect because emails easily carry documents, spreadsheets, and visual files.","D":"Incorrect because group mailing lists allow sending to many recipients simultaneously."}}},{"id":"P1_U2_MCQ_550","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_550","question":"How can a business reduce communication barriers caused by the use of complex technical 'jargon'?","options":{"A":"By lengthening the chain of command so more managers edit the message","B":"By sending the same technical acronyms twice as frequently","C":"By switching strictly to one-way noticeboards and banning employee questions","D":"By ensuring messages are written or spoken in clear, simple language appropriate to the audience's background"},"correctOption":"D","correctAnswer":"By ensuring messages are written or spoken in clear, simple language appropriate to the audience's background","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because avoiding specialist jargon and tailoring language to the receiver ensures the message is accurately decoded.","distractor_reasons":{"A":"Incorrect because lengthening the chain of command increases message distortion.","B":"Incorrect because repeating incomprehensible jargon does not clarify meaning.","C":"Incorrect because banning questions prevents feedback and worsens misunderstanding.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_551","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_551","question":"What is meant by the term 'motivation' in a business context?","options":{"A":"The number of subordinates directly accountable to a single line manager","B":"The legal minimum hourly wage rate set by the government for all adult workers","C":"The reason why employees want to work hard and work effectively for the business","D":"The formal process of terminating an employee's contract due to gross misconduct"},"correctOption":"C","correctAnswer":"The reason why employees want to work hard and work effectively for the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because motivation refers to the internal and external factors that stimulate employees' desire and commitment to perform their jobs well.","distractor_reasons":{"A":"Incorrect because the number of direct subordinates defines the span of control.","B":"Incorrect because a statutory pay floor is the national minimum wage rather than motivation.","C":"Correct selection.","D":"Incorrect because terminating a contract for misconduct defines dismissal."}}},{"id":"P1_U2_MCQ_552","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_552","question":"Which motivational theorist proposed the 'Scientific Management' approach, arguing that workers are motivated primarily by money and should be paid according to output?","options":{"A":"Abraham Maslow","B":"Frederick Winslow Taylor","C":"Frederick Herzberg","D":"Douglas McGregor"},"correctOption":"B","correctAnswer":"Frederick Winslow Taylor","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because F.W. Taylor argued that employees are driven mainly by financial gain and advocated dividing tasks into simple steps paid via piece-rate wages.","distractor_reasons":{"A":"Incorrect because Maslow proposed the five-level Hierarchy of Needs.","B":"Correct selection.","C":"Incorrect because Herzberg developed the Two-Factor Theory of hygiene factors and motivators.","D":"Incorrect because McGregor formulated Theory X and Theory Y assumptions about worker attitudes."}}},{"id":"P1_U2_MCQ_553","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_553","question":"In Abraham Maslow's Hierarchy of Needs, which level sits immediately above 'safety/security needs'?","options":{"A":"Physiological needs","B":"Social (love and belonging) needs","C":"Esteem needs","D":"Self-actualisation needs"},"correctOption":"B","correctAnswer":"Social (love and belonging) needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Maslow's hierarchy ascends from physiological needs to safety needs, then social needs, esteem needs, and finally self-actualisation.","distractor_reasons":{"A":"Incorrect because physiological needs form the base level below safety needs.","B":"Correct selection.","C":"Incorrect because esteem needs sit above social needs rather than directly above safety needs.","D":"Incorrect because self-actualisation is the highest level at the top of the pyramid."}}},{"id":"P1_U2_MCQ_554","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_554","question":"According to Maslow's Hierarchy of Needs, how can an employer satisfy an employee's 'esteem needs'?","options":{"A":"By providing basic heating, lighting, and meal breaks at work","B":"By issuing a written contract guaranteeing protection against unfair dismissal","C":"By organising informal social clubs and team lunches","D":"By offering formal recognition, status, praise, and promotion for good performance"},"correctOption":"D","correctAnswer":"By offering formal recognition, status, praise, and promotion for good performance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because esteem needs involve self-respect, recognition from others, status, and achievement.","distractor_reasons":{"A":"Incorrect because basic physical comforts address physiological needs.","B":"Incorrect because job protection and safe conditions address safety/security needs.","C":"Incorrect because friendship and group belonging address social needs.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_555","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_555","question":"In Herzberg's Two-Factor Theory, what is the role of 'hygiene factors' (such as pay, company policy, and working conditions)?","options":{"A":"They eliminate the need for managers to provide any financial remuneration","B":"They directly inspire employees to exert maximum creative effort through job satisfaction","C":"They prevent employee dissatisfaction when adequate, but do not create long-term positive motivation on their own","D":"They represent the highest level of personal growth and self-fulfilment"},"correctOption":"C","correctAnswer":"They prevent employee dissatisfaction when adequate, but do not create long-term positive motivation on their own","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg found that poor hygiene factors cause dissatisfaction, whereas improving them merely removes dissatisfaction without acting as true motivators.","distractor_reasons":{"A":"Incorrect because pay itself is classified by Herzberg as an essential hygiene factor.","B":"Incorrect because inspiring intrinsic job satisfaction is the role of 'motivators' such as achievement and responsibility.","C":"Correct selection.","D":"Incorrect because personal growth is an intrinsic motivator (and Maslow's self-actualisation), not a hygiene factor."}}},{"id":"P1_U2_MCQ_556","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_556","question":"What is a major disadvantage of using a 'piece-rate' financial payment system?","options":{"A":"Employees may rush their work to maximise output, leading to lower product quality and higher waste","B":"Workers have no financial incentive to increase their daily output","C":"Labour costs become completely fixed regardless of how much output is produced","D":"It can only be used for senior managers whose individual output cannot be counted"},"correctOption":"A","correctAnswer":"Employees may rush their work to maximise output, leading to lower product quality and higher waste","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying per unit produced encourages speed over care, requiring stricter quality inspections.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because piece-rate directly links earnings to output volume, strongly incentivising speed.","C":"Incorrect because piece-rate wages vary directly with output, making them a variable cost.","D":"Incorrect because piece-rate requires measurable physical units and is unsuited to managerial roles."}}},{"id":"P1_U2_MCQ_557","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_557","question":"How does 'commission' differ from a standard 'salary' as a financial motivator?","options":{"A":"Commission is paid as a percentage of the value of sales made, whereas a salary is a fixed annual amount usually paid monthly","B":"Commission is paid only in non-cash perks, whereas a salary is paid in company shares","C":"Commission is guaranteed regardless of sales performance, whereas a salary varies every hour","D":"Commission is paid exclusively to factory machine operators, whereas salaries are paid only to part-time cleaners"},"correctOption":"A","correctAnswer":"Commission is paid as a percentage of the value of sales made, whereas a salary is a fixed annual amount usually paid monthly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because commission rewards sales staff in proportion to revenue generated, while a salary is a fixed periodic payment not directly tied to hours or units.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-cash perks are fringe benefits rather than commission.","C":"Incorrect because this reverses the stability of a fixed salary and the variable nature of commission.","D":"Incorrect because commission is used in sales roles and salaries are common in administrative and managerial roles."}}},{"id":"P1_U2_MCQ_558","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_558","question":"What is meant by 'fringe benefits' (perks) in employee remuneration?","options":{"A":"Extra hourly wages paid for working on public holidays","B":"Non-cash rewards given to employees in addition to their normal wage or salary, such as a company car, health insurance, or staff discounts","C":"Lump-sum statutory compensation paid when an employee's job ceases to exist","D":"The basic hourly rate earned before any overtime is worked"},"correctOption":"B","correctAnswer":"Non-cash rewards given to employees in addition to their normal wage or salary, such as a company car, health insurance, or staff discounts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fringe benefits are non-monetary extras provided alongside direct pay to attract, retain, and motivate staff.","distractor_reasons":{"A":"Incorrect because extra hourly cash pay for additional hours is overtime pay.","B":"Correct selection.","C":"Incorrect because compensation for job loss is redundancy pay.","D":"Incorrect because basic hourly pay is a time-rate wage."}}},{"id":"P1_U2_MCQ_559","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_559","question":"What is the key difference between 'job enlargement' and 'job enrichment'?","options":{"A":"Job enlargement involves moving workers between different departments every week, whereas job enrichment demotes staff to simpler roles","B":"Job enlargement reduces the number of hours worked per week, whereas job enrichment increases basic hourly pay","C":"Job enlargement adds more tasks of a similar skill level to reduce boredom, whereas job enrichment adds more challenging tasks involving greater responsibility and decision-making","D":"Job enlargement applies only to senior directors, whereas job enrichment applies only to unpaid interns"},"correctOption":"C","correctAnswer":"Job enlargement adds more tasks of a similar skill level to reduce boredom, whereas job enrichment adds more challenging tasks involving greater responsibility and decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job enlargement widens a role horizontally with extra tasks at the same level, while job enrichment deepens a role vertically with autonomy and complexity.","distractor_reasons":{"A":"Incorrect because switching workers periodically between different tasks describes job rotation, not enlargement.","B":"Incorrect because neither concept refers to shorter working hours or direct pay rises.","C":"Correct selection.","D":"Incorrect because both job redesign methods are widely used for operational and clerical staff."}}},{"id":"P1_U2_MCQ_560","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_560","question":"Which non-financial motivational method involves employees switching periodically from one task to another at the same skill level?","options":{"A":"Job rotation","B":"Profit sharing","C":"Autocratic supervision","D":"Delayering"},"correctOption":"A","correctAnswer":"Job rotation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job rotation moves workers systematically across different tasks to relieve monotony and build multi-skilled flexibility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit sharing is a financial incentive distributing a proportion of company profits to staff.","C":"Incorrect because autocratic supervision is a top-down leadership style rather than a task-switching motivator.","D":"Incorrect because delayering removes tiers of management from an organisational hierarchy."}}},{"id":"P1_U2_MCQ_561","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_561","question":"What is meant by the 'chain of command' in an organisational structure?","options":{"A":"The structure in an organisation that allows instructions to be passed down from senior management to lower levels of management","B":"The total number of employees working across all branches of a multinational firm","C":"The informal friendship groups formed by employees during lunch breaks","D":"The sequence of stages used to recruit and select new employees"},"correctOption":"A","correctAnswer":"The structure in an organisation that allows instructions to be passed down from senior management to lower levels of management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the chain of command defines the formal line of authority through which orders flow downward and accountability flows upward.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because total headcount measures business size rather than the line of authority.","C":"Incorrect because social groups form the informal communication network.","D":"Incorrect because hiring stages belong to the recruitment and selection process."}}},{"id":"P1_U2_MCQ_562","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_562","question":"What is the relationship between 'span of control' and 'chain of command' when a business removes middle management layers (delayering)?","options":{"A":"The chain of command becomes longer and the average span of control becomes narrower","B":"The chain of command becomes shorter and the average span of control becomes wider","C":"Both the chain of command and the span of control are completely eliminated","D":"The chain of command stays unchanged while the span of control shrinks to zero"},"correctOption":"B","correctAnswer":"The chain of command becomes shorter and the average span of control becomes wider","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because removing levels of hierarchy shortens the vertical chain of command and leaves remaining managers supervising more direct subordinates (a wider span).","distractor_reasons":{"A":"Incorrect because a longer chain and narrower span occur when adding layers to create a taller hierarchy.","B":"Correct selection.","C":"Incorrect because remaining managers still retain authority and direct reports.","D":"Incorrect because removing a tier directly shortens the chain and widens spans."}}},{"id":"P1_U2_MCQ_563","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_563","question":"Which of the following is a key advantage of a 'short (flat) organisational structure'?","options":{"A":"There are many frequent opportunities for vertical promotion up numerous management tiers","B":"Managers have very narrow spans of control and can closely supervise every minor task","C":"Communication between senior managers and shop-floor workers is faster and less prone to distortion","D":"Decision-making is strictly centralised at the very top of a ten-tier hierarchy"},"correctOption":"C","correctAnswer":"Communication between senior managers and shop-floor workers is faster and less prone to distortion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fewer management layers reduce communication delays and distortion between top executives and frontline staff.","distractor_reasons":{"A":"Incorrect because fewer tiers actually reduce vertical promotion steps, which is a disadvantage of flat structures.","B":"Incorrect because narrow spans and tight supervision characterise tall hierarchies.","C":"Correct selection.","D":"Incorrect because flat structures typically encourage greater delegation due to wider spans of control."}}},{"id":"P1_U2_MCQ_564","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_564","question":"What does 'delegation' mean in management?","options":{"A":"Refusing to allow subordinates to make any decisions without written approval","B":"Transferring full legal ownership of a company to its customers","C":"Giving a subordinate the authority to perform particular tasks while the manager retains overall responsibility for the outcome","D":"Dismissing underperforming middle managers to reduce overhead costs"},"correctOption":"C","correctAnswer":"Giving a subordinate the authority to perform particular tasks while the manager retains overall responsibility for the outcome","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegation entrusts authority for specific tasks to junior staff, freeing up managerial time and motivating subordinates, though ultimate accountability remains with the manager.","distractor_reasons":{"A":"Incorrect because refusing subordinate autonomy describes centralisation or micromanagement.","B":"Incorrect because transferring ownership describes selling shares or privatisation.","C":"Correct selection.","D":"Incorrect because removing management tiers is delayering or redundancy."}}},{"id":"P1_U2_MCQ_565","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_565","question":"Why might a manager be reluctant to delegate tasks to subordinates?","options":{"A":"The manager fears subordinates might fail at the task—or perform it better than the manager—and the manager still bears final responsibility","B":"Delegation automatically reduces the manager's basic salary by half","C":"Delegation is illegal under international employment legislation","D":"Delegation increases the number of hierarchical layers in the business"},"correctOption":"A","correctAnswer":"The manager fears subordinates might fail at the task—or perform it better than the manager—and the manager still bears final responsibility","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers often worry about loss of control, subordinate errors, or feeling threatened by capable staff.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delegating tasks does not reduce a manager's pay.","C":"Incorrect because delegation is a standard, lawful management practice.","D":"Incorrect because delegation redistributes authority within existing layers rather than adding tiers."}}},{"id":"P1_U2_MCQ_566","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_566","question":"Which classic function of management involves setting future aims and objectives and determining the strategies and resources needed to achieve them?","options":{"A":"Controlling","B":"Planning","C":"Coordinating","D":"Commanding"},"correctOption":"B","correctAnswer":"Planning","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because planning establishes clear goals and charts the course of action required to reach them.","distractor_reasons":{"A":"Incorrect because controlling involves measuring actual performance against targets and taking corrective action.","B":"Correct selection.","C":"Incorrect because coordinating brings people and departments together to work toward common goals.","D":"Incorrect because commanding involves guiding, leading, and instructing staff to carry out tasks."}}},{"id":"P1_U2_MCQ_567","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_567","question":"Which leadership style is characterised by the manager making all decisions alone without consulting employees and expecting orders to be obeyed without question?","options":{"A":"Laissez-faire leadership","B":"Democratic leadership","C":"Autocratic leadership","D":"Participative leadership"},"correctOption":"C","correctAnswer":"Autocratic leadership","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because autocratic leaders centralise decision-making and rely on one-way downward communication.","distractor_reasons":{"A":"Incorrect because laissez-faire leaders set broad objectives and leave employees to make most decisions independently.","B":"Incorrect because democratic leaders consult workers and encourage two-way discussion before deciding.","C":"Correct selection.","D":"Incorrect because participative leadership is synonymous with democratic involvement of staff."}}},{"id":"P1_U2_MCQ_568","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_568","question":"In which situation is 'autocratic leadership' most appropriate?","options":{"A":"In a scientific research laboratory staffed by highly qualified specialists","B":"In a creative advertising agency where experienced designers thrive on brainstorming new ideas","C":"During an urgent workplace emergency or crisis where rapid, decisive action is essential","D":"When aiming to boost intrinsic motivation through worker empowerment and two-way feedback"},"correctOption":"C","correctAnswer":"During an urgent workplace emergency or crisis where rapid, decisive action is essential","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because emergencies leave no time for lengthy consultation and require immediate top-down direction.","distractor_reasons":{"A":"Incorrect because skilled researchers perform best with high autonomy (laissez-faire or democratic).","B":"Incorrect because creative agencies benefit from democratic or laissez-faire collaboration.","C":"Correct selection.","D":"Incorrect because empowerment requires democratic rather than autocratic leadership."}}},{"id":"P1_U2_MCQ_569","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_569","question":"What is a potential disadvantage of 'laissez-faire leadership'?","options":{"A":"Poor coordination and lack of clear direction can arise if employees lack self-discipline or experience","B":"Employees may feel demotivated because managers constantly micromanage every detail","C":"Decision-making becomes completely impossible unless the chief executive approves every minor step","D":"Communication flows strictly downward with zero opportunity for employee initiative"},"correctOption":"A","correctAnswer":"Poor coordination and lack of clear direction can arise if employees lack self-discipline or experience","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because laissez-faire leaders take a hands-off approach, which can lead to confusion or missed deadlines if staff need structure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because micromanagement is the opposite of laissez-faire leadership.","C":"Incorrect because top-level approval for every step describes extreme autocratic centralisation.","D":"Incorrect because laissez-faire leadership maximises employee autonomy rather than one-way orders."}}},{"id":"P1_U2_MCQ_570","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_570","question":"What is the primary purpose of a 'trade union'?","options":{"A":"A recruitment agency that supplies temporary staff to factories","B":"A government department that collects corporate income taxes from limited companies","C":"An association of rival firms formed to fix high selling prices for consumers","D":"A group of employees who have joined together to ensure their interests—such as fair pay and safe working conditions—are protected"},"correctOption":"D","correctAnswer":"A group of employees who have joined together to ensure their interests—such as fair pay and safe working conditions—are protected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade unions represent workers collectively in negotiations with employers over wages, hours, safety, and job security.","distractor_reasons":{"A":"Incorrect because staffing agencies are commercial employment businesses, not worker unions.","B":"Incorrect because tax collection is carried out by a national revenue authority.","C":"Incorrect because price-fixing among rival businesses is an illegal cartel.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_571","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_571","question":"What is the correct order of the initial stages in the recruitment and selection process when a job vacancy arises?","options":{"A":"Conduct job analysis -> Draw up job description and person specification -> Advertise the vacancy","B":"Offer the job to a candidate -> Conduct interviews -> Write the job description","C":"Advertise the vacancy -> Induct the new employee -> Shortlist applicants","D":"Shortlist applicants -> Conduct job analysis -> Receive application forms"},"correctOption":"A","correctAnswer":"Conduct job analysis -> Draw up job description and person specification -> Advertise the vacancy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an employer must first examine the duties and skills needed (job analysis), document them in a job description and person specification, and then advertise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because job offers and interviews happen after advertising and shortlisting.","C":"Incorrect because induction occurs after selection and job acceptance, not before shortlisting.","D":"Incorrect because applications cannot be shortlisted before job analysis and advertising occur."}}},{"id":"P1_U2_MCQ_572","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_572","question":"How does a 'job description' differ from a 'person specification'?","options":{"A":"A job description lists the candidate's past employers, whereas a person specification states the company's annual profit","B":"A job description outlines the responsibilities and duties of the role itself, whereas a person specification lists the qualifications, skills, and qualities required of the ideal candidate","C":"A job description is written by the applicant, whereas a person specification is written by a trade union","D":"A job description is used only for external recruitment, whereas a person specification is used only for redundancy"},"correctOption":"B","correctAnswer":"A job description outlines the responsibilities and duties of the role itself, whereas a person specification lists the qualifications, skills, and qualities required of the ideal candidate","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the job description defines what the job entails (title, tasks, reporting lines), while the person specification defines who is suited to do it.","distractor_reasons":{"A":"Incorrect because past employment history appears on a candidate's CV or application form.","B":"Correct selection.","C":"Incorrect because both documents are prepared by the employer's HR or line management.","D":"Incorrect because both documents are used together for internal and external recruitment."}}},{"id":"P1_U2_MCQ_573","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_573","question":"Which of the following is an advantage of 'internal recruitment' (filling a vacancy from within the existing workforce)?","options":{"A":"It brings fresh outside ideas and new industry experience into the business","B":"It avoids creating any secondary vacancy elsewhere in the organisation","C":"It creates a wider pool of thousands of applicants from across the country","D":"It is quicker and cheaper than external advertising, and the employee's abilities and work ethic are already known to management"},"correctOption":"D","correctAnswer":"It is quicker and cheaper than external advertising, and the employee's abilities and work ethic are already known to management","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because internal recruitment saves external advertising costs, reduces induction time, and motivates existing staff through promotion prospects.","distractor_reasons":{"A":"Incorrect because bringing in fresh ideas is a key advantage of external recruitment.","B":"Incorrect because promoting an existing worker leaves their previous post vacant to be filled.","C":"Incorrect because a large nationwide applicant pool is a benefit of external recruitment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_574","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_574","question":"What is a common disadvantage of 'internal recruitment'?","options":{"A":"High fees paid to external recruitment agencies and national newspapers","B":"No new ideas or external perspectives enter the organisation, and unsuccessful internal candidates may feel jealous or demotivated","C":"The chosen candidate takes months to learn basic company rules and layout","D":"Management has zero prior knowledge of the candidate's punctuality or reliability"},"correctOption":"B","correctAnswer":"No new ideas or external perspectives enter the organisation, and unsuccessful internal candidates may feel jealous or demotivated","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because relying purely on internal promotions can cause stagnation and workplace resentment among colleagues passed over for the role.","distractor_reasons":{"A":"Incorrect because high external advertising and agency fees apply to external recruitment.","B":"Correct selection.","C":"Incorrect because internal hires already know the organisation's systems and culture.","D":"Incorrect because internal candidates already have an established track record with the employer."}}},{"id":"P1_U2_MCQ_575","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_575","question":"Where would a business most appropriately advertise a vacancy for a highly specialised senior aerospace engineer?","options":{"A":"A specialist engineering trade journal and professional online job platforms","B":"A local supermarket noticeboard","C":"A flyer posted through doors in a single residential street","D":"An internal staff canteen poster only"},"correctOption":"A","correctAnswer":"A specialist engineering trade journal and professional online job platforms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialist technical journals and targeted professional networks reach qualified candidates with niche expertise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local shop noticeboards suit low-skilled local jobs rather than niche senior engineers.","C":"Incorrect because local flyers would fail to reach a nationwide or global pool of aerospace specialists.","D":"Incorrect because restricting the advert to an internal canteen limits reach if external expertise is needed."}}},{"id":"P1_U2_MCQ_576","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_576","question":"Why do many large employers require job applicants to complete a standardised 'application form' rather than submitting only a Curriculum Vitae (CV)?","options":{"A":"Application forms collect identical information in a uniform format, making it easier to compare candidates fairly against the person specification","B":"Application forms legally guarantee that every applicant will be offered an interview","C":"Application forms eliminate the need for employers to check references","D":"Application forms are designed solely by candidates to highlight only what they choose"},"correctOption":"A","correctAnswer":"Application forms collect identical information in a uniform format, making it easier to compare candidates fairly against the person specification","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employer-designed application forms ensure consistent data across all candidates for objective shortlisting.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shortlisting narrows down applicants; not everyone is interviewed.","C":"Incorrect because employers still request and verify references for shortlisted candidates.","D":"Incorrect because a CV is formatted by the candidate, whereas an application form is structured by the employer."}}},{"id":"P1_U2_MCQ_577","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_577","question":"What is the purpose of using 'aptitude tests' or 'skills tests' during employee selection?","options":{"A":"To replace the need for a written contract of employment once hired","B":"To measure objectively whether shortlisted candidates possess the practical abilities or potential needed to perform the job","C":"To negotiate trade union wage rates across the whole industry","D":"To determine how much redundancy compensation a departing worker will receive"},"correctOption":"B","correctAnswer":"To measure objectively whether shortlisted candidates possess the practical abilities or potential needed to perform the job","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because practical skills and aptitude tests verify claimed competencies beyond what is stated in an interview or CV.","distractor_reasons":{"A":"Incorrect because a legal contract of employment must still be issued upon hiring.","B":"Correct selection.","C":"Incorrect because wage negotiation is collective bargaining.","D":"Incorrect because selection tests evaluate job applicants prior to hiring."}}},{"id":"P1_U2_MCQ_578","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_578","question":"Why do employers request 'references' before confirming a job offer?","options":{"A":"To calculate the exact amount of income tax the employee paid ten years ago","B":"To obtain an independent check on the candidate's character, reliability, and past work performance from previous employers or referees","C":"To allow the candidate to design their own salary package","D":"To avoid having to carry out any induction training"},"correctOption":"B","correctAnswer":"To obtain an independent check on the candidate's character, reliability, and past work performance from previous employers or referees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because references help verify the accuracy of the candidate's claims and assess past reliability.","distractor_reasons":{"A":"Incorrect because referees provide character and employment feedback, not historical tax audits.","B":"Correct selection.","C":"Incorrect because remuneration is determined by the employer's pay structure or negotiation.","D":"Incorrect because new hires still require induction regardless of strong references."}}},{"id":"P1_U2_MCQ_579","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_579","question":"Which of the following is an advantage to a business of employing 'part-time workers'?","options":{"A":"Part-time workers are always more committed to long-term career progression than full-time staff","B":"Part-time workers never require any training or supervision","C":"Greater workforce flexibility to cover peak trading periods (such as weekends or lunchtimes) without paying for idle full-time hours","D":"Communication across shifts is automatically simpler than with a small full-time team"},"correctOption":"C","correctAnswer":"Greater workforce flexibility to cover peak trading periods (such as weekends or lunchtimes) without paying for idle full-time hours","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because part-time contracts let businesses match staffing levels closely to fluctuating customer demand and attract workers who prefer flexible hours.","distractor_reasons":{"A":"Incorrect because part-time staff may sometimes have lower attachment to the firm than full-time career staff.","B":"Incorrect because part-time employees still require proper induction and job training.","C":"Correct selection.","D":"Incorrect because coordinating more part-time staff across shifts often makes communication harder, not easier."}}},{"id":"P1_U2_MCQ_580","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_580","question":"What is a potential disadvantage of relying heavily on 'part-time employees' rather than 'full-time employees'?","options":{"A":"It reduces the business's ability to extend opening hours into evenings and weekends","B":"Part-time workers cannot legally be given a written statement of employment terms","C":"Part-time employees are prohibited from working in retail or hospitality businesses","D":"Induction and training costs per hour worked are higher because more workers must be trained to cover the same total hours"},"correctOption":"D","correctAnswer":"Induction and training costs per hour worked are higher because more workers must be trained to cover the same total hours","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employing two part-time staff instead of one full-time worker doubles recruitment and training administration for the same total labour hours.","distractor_reasons":{"A":"Incorrect because part-time staffing actually makes covering evenings and weekends easier.","B":"Incorrect because part-time workers are entitled to written employment terms and statutory rights.","C":"Incorrect because retail and hospitality rely extensively on part-time staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_581","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_581","question":"What is the primary purpose of 'induction training'?","options":{"A":"To familiarise a newly recruited employee with the workplace layout, company rules, health and safety procedures, and colleagues so they settle in quickly","B":"To send experienced senior executives to an external university for an MBA degree","C":"To retrain redundant workers for jobs in completely different industries","D":"To evaluate candidates before deciding whom to offer a job"},"correctOption":"A","correctAnswer":"To familiarise a newly recruited employee with the workplace layout, company rules, health and safety procedures, and colleagues so they settle in quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because induction training welcomes new starters, explains policies and safety rules, and helps them become productive rapidly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external university courses are off-the-job development for existing staff.","C":"Incorrect because induction is for new hires joining the firm, not departing redundant staff.","D":"Incorrect because candidate evaluation occurs during selection before a job offer is accepted."}}},{"id":"P1_U2_MCQ_582","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_582","question":"What is a key advantage of 'on-the-job training'?","options":{"A":"Employees learn completely away from workplace distractions in a dedicated college classroom","B":"It is relatively inexpensive because training occurs at the normal workstation using existing equipment, and some output is still produced during training","C":"It guarantees that experienced workers never pass on any bad working habits","D":"It brings brand-new external academic theories into the company"},"correctOption":"B","correctAnswer":"It is relatively inexpensive because training occurs at the normal workstation using existing equipment, and some output is still produced during training","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because on-the-job training avoids external course and travel fees while keeping the trainee active in the real work environment.","distractor_reasons":{"A":"Incorrect because learning away from the workplace describes off-the-job training.","B":"Correct selection.","C":"Incorrect because passing on existing bad habits is actually a classic disadvantage of on-the-job training.","D":"Incorrect because new external theories are typically introduced via off-the-job courses."}}},{"id":"P1_U2_MCQ_583","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_583","question":"What is a major disadvantage of 'on-the-job training'?","options":{"A":"The experienced trainer's own productivity drops while demonstrating tasks, and trainees may pick up the trainer's bad habits","B":"High external college tuition fees and overnight hotel costs","C":"The skills taught are completely irrelevant to the company's actual machinery","D":"Trainees must leave the company for two full years before starting work"},"correctOption":"A","correctAnswer":"The experienced trainer's own productivity drops while demonstrating tasks, and trainees may pick up the trainer's bad habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shadowing an experienced colleague slows down the mentor's output and risks replicating informal shortcuts or errors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external tuition and travel fees are drawbacks of off-the-job training.","C":"Incorrect because on-the-job training uses the exact equipment and procedures of the workplace.","D":"Incorrect because on-the-job training takes place immediately at the workplace."}}},{"id":"P1_U2_MCQ_584","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_584","question":"Which of the following is a benefit of 'off-the-job training'?","options":{"A":"It costs the employer nothing in course fees or travel expenses","B":"No output is lost because trainees continue working full-time on the factory line during classes","C":"Specialist instructors can teach a broad range of modern skills without workplace interruptions, often leading to recognised qualifications","D":"Trainees are guaranteed never to leave the business for a competitor afterwards"},"correctOption":"C","correctAnswer":"Specialist instructors can teach a broad range of modern skills without workplace interruptions, often leading to recognised qualifications","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because off-the-job training provides structured instruction from external experts away from daily operational pressures.","distractor_reasons":{"A":"Incorrect because off-the-job training usually incurs course fees and travel costs.","B":"Incorrect because trainees are absent from production during off-the-job training, which reduces short-term output.","C":"Correct selection.","D":"Incorrect because gaining external qualifications can actually make workers more attractive to rival firms."}}},{"id":"P1_U2_MCQ_585","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_585","question":"What is meant by 'workforce planning'?","options":{"A":"Writing an annual financial balance sheet for shareholders","B":"Calculating the daily electricity consumption of factory machinery","C":"Designing the layout of a retail store to maximise impulse purchases","D":"Establishing the workforce needed by the business for the foreseeable future in terms of the number and skills of employees required"},"correctOption":"D","correctAnswer":"Establishing the workforce needed by the business for the foreseeable future in terms of the number and skills of employees required","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because workforce planning forecasts future staffing requirements—both headcount and competencies—to meet strategic objectives.","distractor_reasons":{"A":"Incorrect because balance sheets belong to financial accounting.","B":"Incorrect because utility usage belongs to operations cost management.","C":"Incorrect because store layout belongs to retail marketing and operations.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_586","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_586","question":"How does 'redundancy' differ from 'dismissal'?","options":{"A":"Redundancy occurs when a job ceases to exist (for example due to falling demand or automation) through no fault of the worker, whereas dismissal occurs because the worker is unsatisfactory or breaks rules","B":"Redundancy occurs only when an employee steals from the company, whereas dismissal occurs when a factory closes down","C":"Redundancy means an employee voluntarily resigns to retire, whereas dismissal means an employee is promoted","D":"Redundancy is illegal in all countries, whereas dismissal requires no warning or reason"},"correctOption":"A","correctAnswer":"Redundancy occurs when a job ceases to exist (for example due to falling demand or automation) through no fault of the worker, whereas dismissal occurs because the worker is unsatisfactory or breaks rules","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because redundancy is caused by changes in business needs (eliminating the role), while dismissal stems from employee misconduct or persistent incompetence.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because theft is gross misconduct leading to dismissal, whereas factory closure causes redundancy.","C":"Incorrect because voluntary retirement is resignation, not redundancy.","D":"Incorrect because lawful redundancy is permitted with proper consultation/compensation, while unfair dismissal is restricted by law."}}},{"id":"P1_U2_MCQ_587","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_587","question":"Which of the following is a common reason for 'redundancy' (retrenchment) in a manufacturing business?","options":{"A":"An employee voluntarily leaving to take a higher-paid job elsewhere","B":"An employee repeatedly arriving two hours late despite formal written warnings","C":"An employee assaulting a supervisor on the shop floor","D":"Introduction of new automated robotics that replaces manual assembly roles"},"correctOption":"D","correctAnswer":"Introduction of new automated robotics that replaces manual assembly roles","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because automation removes the need for certain manual jobs, making those roles redundant.","distractor_reasons":{"A":"Incorrect because leaving voluntarily is resignation.","B":"Incorrect because persistent lateness after warnings is a ground for dismissal.","C":"Incorrect because workplace violence is gross misconduct resulting in summary dismissal.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_588","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_588","question":"What is a 'contract of employment'?","options":{"A":"A trade union's annual financial report to its members","B":"An informal verbal promise made by a customer to buy goods next year","C":"A document listing only the educational qualifications of job applicants","D":"A legally binding agreement between an employer and an employee setting out the terms and conditions of work, such as pay, hours, and duties"},"correctOption":"D","correctAnswer":"A legally binding agreement between an employer and an employee setting out the terms and conditions of work, such as pay, hours, and duties","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a contract of employment establishes legal rights and obligations for both employer and employee.","distractor_reasons":{"A":"Incorrect because union financial accounts are internal union records.","B":"Incorrect because customer purchase agreements are sales contracts, not employment contracts.","C":"Incorrect because applicant qualifications belong to a CV or person specification.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_589","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_589","question":"Which situation would legally constitute 'unfair dismissal' in most jurisdictions?","options":{"A":"Dismissing an employee for repeated negligence after following full disciplinary warnings","B":"Dismissing an employee who was caught stealing cash from the company safe","C":"Sacking an employee solely because they joined a trade union or became pregnant","D":"Making staff redundant when the branch permanently closes due to bankruptcy"},"correctOption":"C","correctAnswer":"Sacking an employee solely because they joined a trade union or became pregnant","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employment laws protect workers against discriminatory dismissal or dismissal for lawful union membership.","distractor_reasons":{"A":"Incorrect because dismissal following fair warnings for persistent poor performance is lawful.","B":"Incorrect because theft is gross misconduct and justifies fair summary dismissal.","C":"Correct selection.","D":"Incorrect because genuine business closure is a valid reason for redundancy."}}},{"id":"P1_U2_MCQ_590","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_590","question":"How do 'health and safety laws' affect employers in the workplace?","options":{"A":"Employers must provide safe machinery, protective equipment, safety training, and hygienic working conditions, increasing compliance costs but reducing accidents and absenteeism","B":"Employers are allowed to ignore unsafe equipment if workers agree to work faster","C":"Health and safety laws abolish all rest breaks and maximum working-hour limits","D":"Health and safety laws apply exclusively to self-employed sole traders working from home"},"correctOption":"A","correctAnswer":"Employers must provide safe machinery, protective equipment, safety training, and hygienic working conditions, increasing compliance costs but reducing accidents and absenteeism","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because health and safety legislation legally obliges employers to protect workers from physical harm, which entails compliance spending but lowers injury downtime.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because statutory safety duties cannot be waived for higher output speed.","C":"Incorrect because employment laws enforce rest breaks and safe working limits rather than abolishing them.","D":"Incorrect because health and safety laws protect employees across workplaces."}}},{"id":"P1_U2_MCQ_591","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_591","question":"When is communication considered 'effective' in a business?","options":{"A":"Only when communication takes place face-to-face without any written record","B":"Whenever a manager sends a lengthy email to all staff regardless of whether anyone reads or understands it","C":"When the message is sent by the transmitter, received and accurately understood by the receiver, and acted upon with appropriate feedback","D":"Whenever a message contains technical jargon that confuses junior employees"},"correctOption":"C","correctAnswer":"When the message is sent by the transmitter, received and accurately understood by the receiver, and acted upon with appropriate feedback","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective communication requires accurate comprehension by the intended recipient and confirmation via feedback or action.","distractor_reasons":{"A":"Incorrect because written and electronic channels can also be highly effective when clearly understood.","B":"Incorrect because merely transmitting an unread or misunderstood message is ineffective communication.","C":"Correct selection.","D":"Incorrect because confusing jargon acts as a barrier to effective communication."}}},{"id":"P1_U2_MCQ_592","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_592","question":"Which of the following is an example of 'external communication'?","options":{"A":"Two sales assistants discussing stock levels in the staff room","B":"A production manager emailing shift schedules to factory supervisors","C":"A human resources director posting safety rules on the internal staff noticeboard","D":"A company sending an invoice to a customer or publishing an advertisement in a national newspaper"},"correctOption":"D","correctAnswer":"A company sending an invoice to a customer or publishing an advertisement in a national newspaper","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because external communication takes place between the business and outside stakeholders such as customers, suppliers, banks, or the public.","distractor_reasons":{"A":"Incorrect because conversations between colleagues inside the firm are internal communication.","B":"Incorrect because communication between a manager and supervisors within the same firm is internal.","C":"Incorrect because an internal staff noticeboard communicates only with employees inside the business.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_593","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_593","question":"What is the key difference between 'one-way communication' and 'two-way communication'?","options":{"A":"One-way communication always involves video conferencing, whereas two-way communication uses only posters","B":"One-way communication is always written, whereas two-way communication is always spoken","C":"One-way communication is used only with external customers, whereas two-way communication is used only with suppliers","D":"One-way communication does not allow the receiver to respond or give feedback, whereas two-way communication involves a response from the receiver back to the sender"},"correctOption":"D","correctAnswer":"One-way communication does not allow the receiver to respond or give feedback, whereas two-way communication involves a response from the receiver back to the sender","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because feedback is the defining feature that turns one-way transmission into two-way dialogue.","distractor_reasons":{"A":"Incorrect because video conferencing is two-way and posters are one-way.","B":"Incorrect because spoken announcements over a loudspeaker are one-way, while written email exchanges are two-way.","C":"Incorrect because both forms occur internally and externally.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_594","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_594","question":"Which of the following is a major advantage of 'two-way communication' for managers and employees?","options":{"A":"It eliminates the need for employees to listen carefully to instructions","B":"It is always faster than issuing a single one-way command during an immediate fire alarm","C":"The sender can verify that the message was understood accurately, and employees feel more motivated because their views are heard","D":"It ensures managers never have to answer questions from subordinates"},"correctOption":"C","correctAnswer":"The sender can verify that the message was understood accurately, and employees feel more motivated because their views are heard","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because feedback confirms comprehension and promotes employee involvement and morale.","distractor_reasons":{"A":"Incorrect because active listening is essential in two-way communication.","B":"Incorrect because two-way discussion takes longer than an urgent one-way instruction.","C":"Correct selection.","D":"Incorrect because two-way communication specifically invites questions and responses."}}},{"id":"P1_U2_MCQ_595","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_595","question":"What is meant by 'horizontal communication' within an organisation?","options":{"A":"Press releases sent to external journalists","B":"Instructions sent downward from the Chief Executive Officer to factory trainees","C":"Feedback reports sent upward from shop-floor workers to the Board of Directors","D":"Communication between people at the same level of the organisational hierarchy, such as between the Marketing Manager and Production Manager"},"correctOption":"D","correctAnswer":"Communication between people at the same level of the organisational hierarchy, such as between the Marketing Manager and Production Manager","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because horizontal (lateral) communication occurs across departments among peers of equal status to coordinate activities.","distractor_reasons":{"A":"Incorrect because press releases to journalists are external communication.","B":"Incorrect because communication from senior to junior levels is downward communication.","C":"Incorrect because communication from junior to senior levels is upward communication.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_596","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_596","question":"Which of the following is a primary advantage of 'written communication' (such as a formal letter, contract, or policy document)?","options":{"A":"It guarantees instant facial-expression and body-language feedback from the reader","B":"It provides permanent hard evidence that can be referred back to later and reduces the risk of message distortion across multiple recipients","C":"It is always the quickest way to resolve an urgent machine breakdown on the factory floor","D":"It requires zero literacy skills from either the sender or receiver"},"correctOption":"B","correctAnswer":"It provides permanent hard evidence that can be referred back to later and reduces the risk of message distortion across multiple recipients","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because written records serve as permanent proof, allow complex details to be re-read carefully, and ensure identical wording for all recipients.","distractor_reasons":{"A":"Incorrect because non-verbal body language cues are only available in face-to-face or video communication.","B":"Correct selection.","C":"Incorrect because urgent situations are usually resolved faster through direct verbal communication.","D":"Incorrect because written communication requires reading and writing proficiency."}}},{"id":"P1_U2_MCQ_597","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_597","question":"What is a common disadvantage of 'verbal (oral) communication' such as a telephone call or unrecorded meeting?","options":{"A":"It is completely impossible to receive immediate feedback or ask clarifying questions","B":"There is no permanent written record of what was agreed, and listeners may forget or misremember details","C":"It takes several weeks for a spoken message to reach someone in the same room","D":"Tone of voice and emphasis cannot be conveyed when speaking"},"correctOption":"B","correctAnswer":"There is no permanent written record of what was agreed, and listeners may forget or misremember details","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unless minutes or recordings are kept, oral agreements lack verifiable proof and rely on human memory.","distractor_reasons":{"A":"Incorrect because immediate feedback is actually a major advantage of verbal communication.","B":"Correct selection.","C":"Incorrect because spoken communication is instantaneous.","D":"Incorrect because vocal tone and body language actively reinforce spoken messages."}}},{"id":"P1_U2_MCQ_598","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_598","question":"Why is 'visual communication' (such as charts, graphs, diagrams, and safety posters) often used alongside written reports?","options":{"A":"It is cheaper than sending a two-word text message","B":"It replaces the need for any internet connection or electricity in modern offices","C":"It automatically guarantees two-way spoken feedback from every viewer","D":"It presents complex numerical trends or safety instructions clearly and attractively, making information easier and quicker to understand"},"correctOption":"D","correctAnswer":"It presents complex numerical trends or safety instructions clearly and attractively, making information easier and quicker to understand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because visual aids simplify complex data, capture attention, and overcome minor language barriers.","distractor_reasons":{"A":"Incorrect because designing high-quality graphics or posters can be more expensive than brief text.","B":"Incorrect because modern digital visuals often rely on computers and screens.","C":"Incorrect because visual displays like posters are typically one-way unless paired with discussion.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_599","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_599","question":"Which of the following is a recognised 'barrier to effective communication' related to the medium/channel?","options":{"A":"Maintaining a short chain of command with minimal intermediaries","B":"Using clear, simple language tailored to the receiver's level of knowledge","C":"Encouraging receivers to ask questions to confirm understanding","D":"Sending an urgent safety warning via a slow internal postal memo instead of an immediate verbal announcement"},"correctOption":"D","correctAnswer":"Sending an urgent safety warning via a slow internal postal memo instead of an immediate verbal announcement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because selecting an inappropriate or slow channel delays critical messages and causes communication breakdown.","distractor_reasons":{"A":"Incorrect because a short chain of command reduces message distortion.","B":"Incorrect because clear language removes barriers rather than creating them.","C":"Incorrect because encouraging feedback improves communication accuracy.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_600","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_600","question":"How can a business overcome the communication barrier caused by a long chain of command where messages get distorted as they pass through many managers?","options":{"A":"By replacing simple everyday English with complex legal and technical jargon","B":"By adding three extra levels of assistant supervisors between senior directors and workers","C":"By delayering the organisational hierarchy or using direct communication channels such as company-wide emails or briefings","D":"By banning employees from giving feedback or asking clarifying questions"},"correctOption":"C","correctAnswer":"By delayering the organisational hierarchy or using direct communication channels such as company-wide emails or briefings","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reducing intermediate layers or communicating directly with staff prevents 'Chinese whispers' distortion.","distractor_reasons":{"A":"Incorrect because technical jargon creates a language barrier.","B":"Incorrect because adding layers lengthens the chain of command and worsens distortion.","C":"Correct selection.","D":"Incorrect because banning feedback prevents errors from being detected and corrected."}}},{"id":"P1_U2_MCQ_601","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_601","question":"Which of the following is a direct benefit to a business of having a well-motivated workforce?","options":{"A":"Complete elimination of all fixed overhead expenses","B":"Guaranteed monopoly power over all competitors in the market","C":"Higher labour productivity, lower absenteeism, and reduced labour turnover","D":"Automatic exemption from national health and safety regulations"},"correctOption":"C","correctAnswer":"Higher labour productivity, lower absenteeism, and reduced labour turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because motivated employees work more efficiently, take fewer unscheduled days off, and are less likely to leave the firm.","distractor_reasons":{"A":"Incorrect because fixed costs like rent and insurance remain payable regardless of staff motivation.","B":"Incorrect because market dominance depends on competitive positioning and barriers to entry rather than internal motivation alone.","C":"Correct selection.","D":"Incorrect because statutory safety laws apply to all employers irrespective of workforce morale."}}},{"id":"P1_U2_MCQ_602","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_602","question":"What is meant by 'labour turnover'?","options":{"A":"The total sales revenue generated by a business in one financial year","B":"The rate at which employees leave a business over a given period of time","C":"The practice of moving workers between different machines every week","D":"The total number of hours of overtime worked by factory employees"},"correctOption":"B","correctAnswer":"The rate at which employees leave a business over a given period of time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour turnover measures the proportion of staff leaving an organisation and needing replacement.","distractor_reasons":{"A":"Incorrect because total sales revenue is business turnover, not labour turnover.","B":"Correct selection.","C":"Incorrect because switching workers across tasks is job rotation.","D":"Incorrect because extra working hours are overtime rather than staff departures."}}},{"id":"P1_U2_MCQ_603","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_603","question":"Why is high 'absenteeism' often an indicator of low employee motivation?","options":{"A":"Absenteeism is caused exclusively by a short chain of command","B":"Absenteeism only occurs when a business pays excessive annual bonuses","C":"High absenteeism proves that workers have reached Maslow's self-actualisation stage","D":"Demotivated workers feel less committed to their jobs and are more likely to take unscheduled time off work"},"correctOption":"D","correctAnswer":"Demotivated workers feel less committed to their jobs and are more likely to take unscheduled time off work","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dissatisfied or bored employees lack enthusiasm to attend regularly, disrupting production schedules.","distractor_reasons":{"A":"Incorrect because a short chain of command usually improves communication and morale.","B":"Incorrect because financial bonuses typically encourage attendance rather than absence.","C":"Incorrect because self-actualised employees are deeply engaged rather than frequently absent.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_604","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_604","question":"According to F.W. Taylor's Scientific Management theory, how should production work be organised to maximise efficiency?","options":{"A":"Managers should focus solely on social clubs and team-building retreats","B":"Workers should be given complete autonomy to design their own schedules without supervision","C":"All employees should receive identical fixed salaries regardless of output","D":"Tasks should be broken down into simple, repetitive steps with close supervision and payment based on units produced"},"correctOption":"D","correctAnswer":"Tasks should be broken down into simple, repetitive steps with close supervision and payment based on units produced","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Taylor believed workers dislike work, are motivated mainly by money, and perform fastest when tasks are standardised and closely monitored.","distractor_reasons":{"A":"Incorrect because social belonging belongs to Maslow's hierarchy rather than Taylor's economic-man model.","B":"Incorrect because high worker autonomy aligns with laissez-faire leadership and Herzberg's motivators, not Taylor.","C":"Incorrect because Taylor rejected flat time rates in favour of output-linked piece-rate pay.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_605","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_605","question":"What is a major limitation of applying F.W. Taylor's motivational theory in modern workplaces?","options":{"A":"It ignores non-financial motivators such as job satisfaction, and many service or creative jobs do not have easily measurable physical output","B":"It assumes employees refuse to accept any financial payment for their work","C":"It requires every employee to hold a university degree before starting work","D":"It prohibits managers from measuring worker productivity"},"correctOption":"A","correctAnswer":"It ignores non-financial motivators such as job satisfaction, and many service or creative jobs do not have easily measurable physical output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Taylor overlooked social and psychological needs, and piece-rate pay cannot easily be applied to teachers, nurses, or managers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Taylor assumed money was the sole motivator, not that workers reject pay.","C":"Incorrect because Taylor advocated breaking jobs into simple tasks requiring minimal prior training.","D":"Incorrect because Taylor championed scientific measurement of work rates."}}},{"id":"P1_U2_MCQ_606","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_606","question":"In Maslow's Hierarchy of Needs, how does an employer help satisfy an employee's 'physiological needs'?","options":{"A":"By awarding an 'Employee of the Month' trophy at an annual ceremony","B":"By paying a wage high enough to afford basic essentials such as food, clothing, and shelter, and providing rest and meal breaks","C":"By delegating strategic corporate budgeting to junior staff","D":"By creating cross-departmental project teams to foster workplace friendships"},"correctOption":"B","correctAnswer":"By paying a wage high enough to afford basic essentials such as food, clothing, and shelter, and providing rest and meal breaks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because physiological needs are basic survival requirements at the base of Maslow's pyramid.","distractor_reasons":{"A":"Incorrect because public awards and recognition satisfy esteem needs.","B":"Correct selection.","C":"Incorrect because challenging strategic responsibility satisfies esteem or self-actualisation needs.","D":"Incorrect because workplace friendship and teamwork address social needs."}}},{"id":"P1_U2_MCQ_607","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_607","question":"Which workplace provision directly addresses 'safety/security needs' in Maslow's Hierarchy of Needs?","options":{"A":"A permanent contract of employment, safe machinery with protective equipment, and a company pension scheme","B":"Opportunities to lead innovative creative projects independently","C":"Informal after-work sports teams and staff parties","D":"A prestigious corner office and senior job title"},"correctOption":"A","correctAnswer":"A permanent contract of employment, safe machinery with protective equipment, and a company pension scheme","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because safety needs include physical protection from workplace hazards as well as financial and job security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because creative autonomy relates to self-actualisation.","C":"Incorrect because social gatherings satisfy love and belonging (social) needs.","D":"Incorrect because status symbols like senior titles address esteem needs."}}},{"id":"P1_U2_MCQ_608","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_608","question":"According to Maslow's Hierarchy of Needs, what happens once a lower-level need (such as safety) has been largely satisfied?","options":{"A":"The employee drops back down to focus exclusively on physiological needs","B":"The employee immediately stops working and resigns from the business","C":"That need ceases to be a primary motivator and the employee seeks to satisfy the next level up (social needs)","D":"Money becomes completely useless for any purpose whatsoever"},"correctOption":"C","correctAnswer":"That need ceases to be a primary motivator and the employee seeks to satisfy the next level up (social needs)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Maslow argued that needs progress sequentially up the pyramid once lower levels are reasonably met.","distractor_reasons":{"A":"Incorrect because progression moves upward unless lower needs are newly threatened.","B":"Incorrect because meeting lower needs motivates workers to pursue higher-order workplace needs rather than quitting.","C":"Correct selection.","D":"Incorrect because higher pay can still contribute to status (esteem) at higher levels."}}},{"id":"P1_U2_MCQ_609","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_609","question":"What does 'self-actualisation' represent at the top of Maslow's Hierarchy of Needs?","options":{"A":"Being accepted into an informal workplace friendship group","B":"Receiving statutory sick pay and protection against unfair dismissal","C":"Earning enough hourly pay to afford basic groceries and rent","D":"Reaching one's full personal potential through challenging, creative, and fulfilling work"},"correctOption":"D","correctAnswer":"Reaching one's full personal potential through challenging, creative, and fulfilling work","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because self-actualisation is the desire for personal growth, mastery, and realising one's full capabilities.","distractor_reasons":{"A":"Incorrect because group acceptance addresses social needs.","B":"Incorrect because sick pay and job protection relate to safety/security needs.","C":"Incorrect because affording food and shelter addresses basic physiological needs.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_610","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_610","question":"Which of the following is a recognised criticism of Maslow's Hierarchy of Needs?","options":{"A":"It claims that financial pay is the only factor that ever motivates workers","B":"It assumes human beings have no need for food, shelter, or physical safety","C":"Not all individuals share the exact same order of needs, and it can be difficult for managers to identify which level each worker has reached","D":"It applies exclusively to self-employed sole traders with zero employees"},"correctOption":"C","correctAnswer":"Not all individuals share the exact same order of needs, and it can be difficult for managers to identify which level each worker has reached","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because people prioritise needs differently (e.g., valuing esteem over social belonging) and individual needs shift over time.","distractor_reasons":{"A":"Incorrect because exclusive focus on money describes Taylor's theory, not Maslow's.","B":"Incorrect because physiological and safety needs form the bottom two tiers of Maslow's model.","C":"Correct selection.","D":"Incorrect because Maslow's model is widely used to analyse employee motivation in organisations."}}},{"id":"P1_U2_MCQ_611","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_611","question":"According to Herzberg's Two-Factor Theory, which set of factors consists entirely of 'motivators'?","options":{"A":"Basic salary, company administrative policies, and quality of supervision","B":"Achievement, recognition, responsibility, and opportunities for advancement","C":"Working conditions, job security, and relationships with peers","D":"Paid holiday entitlement, canteen facilities, and statutory sick pay"},"correctOption":"B","correctAnswer":"Achievement, recognition, responsibility, and opportunities for advancement","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Herzberg defined motivators as intrinsic factors rooted in the content and challenge of the job itself.","distractor_reasons":{"A":"Incorrect because salary, policies, and supervision are extrinsic hygiene factors.","B":"Correct selection.","C":"Incorrect because working conditions, job security, and peer relations are hygiene factors.","D":"Incorrect because fringe conditions and statutory benefits are hygiene factors."}}},{"id":"P1_U2_MCQ_612","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_612","question":"According to Herzberg, what will happen if a business offers a well-enriched job with high responsibility, but pays an unfairly low wage in unsafe working conditions?","options":{"A":"Employees will be fully satisfied and motivated because hygiene factors have zero impact on workers","B":"Employees will still experience dissatisfaction because the hygiene factors have not been adequately met","C":"The business will automatically achieve zero labour turnover","D":"Unsafe working conditions will act as a positive motivator"},"correctOption":"B","correctAnswer":"Employees will still experience dissatisfaction because the hygiene factors have not been adequately met","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Herzberg emphasised that adequate hygiene factors are necessary to prevent dissatisfaction before motivators can operate effectively.","distractor_reasons":{"A":"Incorrect because poor hygiene factors actively cause job dissatisfaction.","B":"Correct selection.","C":"Incorrect because dissatisfied workers in unsafe, underpaid conditions are likely to resign.","D":"Incorrect because working conditions are a hygiene factor, not a motivator."}}},{"id":"P1_U2_MCQ_613","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_613","question":"Which motivational theorist's work is most closely linked to the practice of 'job enrichment'?","options":{"A":"Elton Mayo","B":"Frederick Winslow Taylor","C":"Henri Fayol","D":"Frederick Herzberg"},"correctOption":"D","correctAnswer":"Frederick Herzberg","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Herzberg recommended redesigning jobs to include greater responsibility, autonomy, and personal growth (job enrichment).","distractor_reasons":{"A":"Incorrect because Mayo is associated with the Hawthorne Studies on social group dynamics.","B":"Incorrect because Taylor advocated narrow, repetitive task specialisation rather than job enrichment.","C":"Incorrect because Fayol is known for defining the classical functions of management.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_614","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_614","question":"What is an advantage to an employer of paying workers using a 'time-rate' wage system (payment per hour worked)?","options":{"A":"Workers automatically produce the maximum possible physical output every hour without supervision","B":"Workers are less likely to rush tasks, helping maintain high product quality, and wages are simple to calculate","C":"Labour costs fall to zero whenever customer orders decline during normal working hours","D":"High-performing fast workers always earn double the hourly rate of slow workers"},"correctOption":"B","correctAnswer":"Workers are less likely to rush tasks, helping maintain high product quality, and wages are simple to calculate","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hourly pay removes the pressure to sacrifice accuracy for speed and is straightforward for payroll administration.","distractor_reasons":{"A":"Incorrect because time-rate pay offers no direct output incentive and requires supervision to prevent slow work.","B":"Correct selection.","C":"Incorrect because hourly wages must still be paid for all hours worked regardless of output volume.","D":"Incorrect because standard time-rate pays the same hourly rate to all workers at that grade."}}},{"id":"P1_U2_MCQ_615","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_615","question":"What is a major disadvantage of a 'time-rate' payment system?","options":{"A":"Payroll staff must count every single item produced by every worker daily","B":"It causes workers to rush assembly work and produce defective products","C":"It can never be used for retail shop assistants or office receptionists","D":"Good and bad workers receive the same hourly pay, so there is little financial incentive to work faster or harder"},"correctOption":"D","correctAnswer":"Good and bad workers receive the same hourly pay, so there is little financial incentive to work faster or harder","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because paying purely for attendance time fails to reward superior effort or speed.","distractor_reasons":{"A":"Incorrect because counting physical items is required for piece-rate systems, not time-rate.","B":"Incorrect because rushing output is a drawback of piece-rate pay, not time-rate pay.","C":"Incorrect because retail and service roles very commonly use hourly time-rate wages.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_616","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_616","question":"What is meant by a 'bonus' as a financial motivator?","options":{"A":"A lump sum paid to workers in addition to their basic wage or salary, usually when specific output, sales, or quality targets are met","B":"A percentage deduction taken from an employee's salary to pay for company uniforms","C":"A non-cash perk such as free gym membership or subsidised canteen meals","D":"Statutory compensation paid when an employee's role becomes redundant"},"correctOption":"A","correctAnswer":"A lump sum paid to workers in addition to their basic wage or salary, usually when specific output, sales, or quality targets are met","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bonus is an extra cash reward contingent on achieving agreed performance goals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a bonus adds to earnings rather than deducting from pay.","C":"Incorrect because non-cash extras are fringe benefits.","D":"Incorrect because job-loss compensation is redundancy pay."}}},{"id":"P1_U2_MCQ_617","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_617","question":"What is an advantage of 'profit sharing' as a financial incentive scheme?","options":{"A":"It encourages employees to care about the overall profitability and cost control of the entire business","B":"It guarantees employees a fixed monthly payout even if the company makes a heavy financial loss","C":"It completely replaces the need to pay any basic wages or salaries","D":"It ensures every individual worker sees an immediate hourly reward for personal speed"},"correctOption":"A","correctAnswer":"It encourages employees to care about the overall profitability and cost control of the entire business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking a portion of reward to company profits aligns staff goals with business success and reduces 'us versus them' attitudes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit-share payouts depend on profit being earned and fall to zero in loss-making years.","C":"Incorrect because profit sharing is paid in addition to normal wages or salaries.","D":"Incorrect because individual effort is diluted across the whole workforce and paid annually rather than hourly."}}},{"id":"P1_U2_MCQ_618","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_618","question":"What is a disadvantage of 'profit sharing' as a motivator for an individual shop-floor employee?","options":{"A":"It forces employees to buy shares at double the stock market price","B":"Profit sharing is illegal for public limited companies","C":"One worker's extra effort has very little noticeable impact on total company profit, and payouts may drop due to external factors beyond workers' control","D":"It immediately increases direct variable labour costs per unit when profits are zero"},"correctOption":"C","correctAnswer":"One worker's extra effort has very little noticeable impact on total company profit, and payouts may drop due to external factors beyond workers' control","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the link between individual daily effort and annual firm-wide profit is distant, and economic downturns can wipe out bonuses despite hard work.","distractor_reasons":{"A":"Incorrect because profit sharing distributes a cash share of profits rather than forcing expensive share purchases.","B":"Incorrect because profit sharing is lawful and widely used by public limited companies.","C":"Correct selection.","D":"Incorrect because if profits are zero, no profit-share payout is triggered."}}},{"id":"P1_U2_MCQ_619","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_619","question":"How does an 'employee share ownership scheme' aim to motivate staff?","options":{"A":"By giving or selling company shares to employees, giving them a direct financial stake as part-owners who benefit from dividends and rising share prices","B":"By allowing employees to take home unsold factory inventory instead of cash wages","C":"By rotating employees between different factory departments every fortnight","D":"By placing employees under strict autocratic supervision"},"correctOption":"A","correctAnswer":"By giving or selling company shares to employees, giving them a direct financial stake as part-owners who benefit from dividends and rising share prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because share ownership fosters long-term loyalty and commitment to improving business value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because giving physical stock instead of cash is payment in kind, not share ownership.","C":"Incorrect because switching tasks across departments is job rotation.","D":"Incorrect because autocratic supervision is a leadership style rather than an ownership incentive."}}},{"id":"P1_U2_MCQ_620","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_620","question":"How does 'teamworking' act as a non-financial motivator in a business?","options":{"A":"It guarantees that every team member receives piece-rate pay based purely on solo output","B":"It isolates every worker in a separate room so they never speak to colleagues","C":"It satisfies social needs for belonging and allows team members to share responsibility and problem-solving, boosting esteem","D":"It removes all accountability for product quality from the workforce"},"correctOption":"C","correctAnswer":"It satisfies social needs for belonging and allows team members to share responsibility and problem-solving, boosting esteem","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working in autonomous teams meets Maslow's social and esteem needs and enriches work through shared decision-making.","distractor_reasons":{"A":"Incorrect because teamworking is a non-financial motivator focused on group collaboration.","B":"Incorrect because teamworking promotes collaboration rather than isolation.","C":"Correct selection.","D":"Incorrect because self-managed teams usually take greater collective ownership of quality."}}},{"id":"P1_U2_MCQ_621","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_621","question":"What is meant by 'organisational structure'?","options":{"A":"The levels of management and division of responsibilities within an organisation","B":"The physical architectural layout of a company's head office building","C":"The legal classification of a business as a sole trader or partnership","D":"The external distribution channels used to deliver products to retailers"},"correctOption":"A","correctAnswer":"The levels of management and division of responsibilities within an organisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organisational structure defines roles, authority relationships, and departmental divisions inside a business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because building layout is physical facility design rather than management structure.","C":"Incorrect because legal status refers to business ownership type.","D":"Incorrect because delivery routes belong to marketing channels of distribution."}}},{"id":"P1_U2_MCQ_622","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_622","question":"Which of the following information can be directly identified by examining a business's 'organisational chart'?","options":{"A":"The annual net profit margin and cash-flow forecast of the business","B":"The hierarchy levels, chain of command, functional departments, and each manager's span of control","C":"The exact hourly wage rate paid to every individual worker","D":"The market share of the business's main external competitors"},"correctOption":"B","correctAnswer":"The hierarchy levels, chain of command, functional departments, and each manager's span of control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an organisational chart visually maps reporting lines, managerial tiers, departmental groupings, and direct subordinates.","distractor_reasons":{"A":"Incorrect because profit and cash flow appear in financial statements, not organisational charts.","B":"Correct selection.","C":"Incorrect because pay rates are specified in employment contracts and payroll records.","D":"Incorrect because competitor market share is derived from external market research."}}},{"id":"P1_U2_MCQ_623","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_623","question":"What is meant by 'hierarchy' in an organisation?","options":{"A":"The total number of external suppliers selling raw materials to the firm","B":"The levels of management in any organisation, ranked from the highest level of authority to the lowest","C":"The informal social club organised by factory workers","D":"The process of advertising job vacancies in national newspapers"},"correctOption":"B","correctAnswer":"The levels of management in any organisation, ranked from the highest level of authority to the lowest","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a hierarchy arranges roles in descending tiers of authority and responsibility.","distractor_reasons":{"A":"Incorrect because external vendors are part of the supply chain, not internal hierarchy.","B":"Correct selection.","C":"Incorrect because social clubs are informal employee groups.","D":"Incorrect because advertising vacancies belongs to recruitment."}}},{"id":"P1_U2_MCQ_624","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_624","question":"What is the correct definition of 'span of control'?","options":{"A":"The number of years a chief executive remains in office","B":"The total number of levels of management from the CEO to the shop floor","C":"The number of subordinates working directly under a manager","D":"The geographical distance between a company's head office and its factories"},"correctOption":"C","correctAnswer":"The number of subordinates working directly under a manager","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because span of control counts only the direct reports accountable to a specific manager.","distractor_reasons":{"A":"Incorrect because tenure length is unrelated to organisational span.","B":"Incorrect because the number of vertical tiers defines the length of the chain of command/hierarchy.","C":"Correct selection.","D":"Incorrect because physical distance between sites is geographical dispersion."}}},{"id":"P1_U2_MCQ_625","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_625","question":"Which factor would allow a manager to effectively manage a 'wider span of control'?","options":{"A":"Subordinates are highly skilled, experienced, and performing routine or well-defined tasks","B":"Subordinates are newly hired trainees performing highly complex, dangerous tasks","C":"The manager lacks experience and works in a different country from all subordinates","D":"Every minor operational decision requires lengthy one-to-one approval from the manager"},"correctOption":"A","correctAnswer":"Subordinates are highly skilled, experienced, and performing routine or well-defined tasks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competent, independent staff carrying out clear tasks require less constant supervision, enabling a wider span.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inexperienced trainees on complex tasks need close guidance and a narrow span.","C":"Incorrect because an inexperienced manager separated geographically struggles with a wide span.","D":"Incorrect because tight micromanagement restricts how many people one manager can supervise."}}},{"id":"P1_U2_MCQ_626","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_626","question":"What is a common disadvantage of a 'tall organisational structure' with many levels of hierarchy?","options":{"A":"There are zero opportunities for internal promotion between management tiers","B":"Managers have excessively wide spans of control and cannot supervise subordinates closely","C":"Messages take longer to pass up and down the long chain of command and may become distorted","D":"Junior workers make all strategic corporate decisions without consulting senior directors"},"correctOption":"C","correctAnswer":"Messages take longer to pass up and down the long chain of command and may become distorted","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tall hierarchies create multiple communication bottlenecks and higher administrative salary overheads.","distractor_reasons":{"A":"Incorrect because numerous tiers actually create many incremental promotion steps.","B":"Incorrect because tall structures typically feature narrow spans of control.","C":"Correct selection.","D":"Incorrect because tall hierarchies tend to centralise authority at upper levels."}}},{"id":"P1_U2_MCQ_627","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_627","question":"What is a potential disadvantage of a 'wide span of control' in a flat organisational structure?","options":{"A":"Communication from top management to frontline staff takes several weeks to pass through intermediaries","B":"The chain of command becomes excessively long with ten layers of middle managers","C":"Senior directors are forced to pay salaries for unnecessary layers of assistant supervisors","D":"A manager may have too many subordinates to supervise effectively, leading to loss of control or increased mistakes"},"correctOption":"D","correctAnswer":"A manager may have too many subordinates to supervise effectively, leading to loss of control or increased mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because stretching a manager across too many direct reports reduces individual guidance and oversight.","distractor_reasons":{"A":"Incorrect because fewer layers make downward communication faster.","B":"Incorrect because wide spans correspond to short chains of command in flat structures.","C":"Incorrect because flat structures have fewer management layers and lower managerial overhead.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_628","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_628","question":"What is meant by 'delayering' in an organisation?","options":{"A":"Removing one or more whole levels of middle management from the organisational hierarchy","B":"Hiring additional assistant managers to narrow every supervisor's span of control","C":"Outsourcing raw material transport to an external logistics company","D":"Dividing a factory assembly line into smaller single-person workstations"},"correctOption":"A","correctAnswer":"Removing one or more whole levels of middle management from the organisational hierarchy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delayering flattens the hierarchy to cut managerial salary costs, speed up communication, and encourage delegation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding management tiers makes the structure taller, the opposite of delayering.","C":"Incorrect because hiring external logistics providers is subcontracting/outsourcing.","D":"Incorrect because splitting tasks on a production line is division of labour."}}},{"id":"P1_U2_MCQ_629","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_629","question":"Which of the following is a disadvantage of 'delayering'?","options":{"A":"An immediate increase in total annual middle-management salary bills","B":"A longer chain of command that slows down communication between directors and workers","C":"One-off redundancy costs and increased workload and stress for remaining managers with wider spans of control","D":"Less delegation and reduced responsibility for lower-level employees"},"correctOption":"C","correctAnswer":"One-off redundancy costs and increased workload and stress for remaining managers with wider spans of control","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cutting management tiers triggers redundancy payouts, reduces promotion opportunities, and stretches remaining managers.","distractor_reasons":{"A":"Incorrect because delayering reduces ongoing managerial salary expenses in the long run.","B":"Incorrect because delayering shortens the chain of command rather than lengthening it.","C":"Correct selection.","D":"Incorrect because wider spans force managers to delegate more responsibility downward."}}},{"id":"P1_U2_MCQ_630","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_630","question":"How do 'line managers' differ from 'staff managers' in a large organisation?","options":{"A":"Line managers have direct authority over subordinates in core operational departments, whereas staff managers are specialists (such as HR or IT) who provide advice and support","B":"Line managers work exclusively part-time, whereas staff managers are unpaid external consultants","C":"Line managers are elected by trade unions, whereas staff managers are appointed by customers","D":"Line managers have zero authority to give instructions, whereas staff managers command the entire factory"},"correctOption":"A","correctAnswer":"Line managers have direct authority over subordinates in core operational departments, whereas staff managers are specialists (such as HR or IT) who provide advice and support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because line managers hold direct line authority in the chain of command, while staff managers offer functional expertise.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both line and staff managers are normally full-time salaried employees of the firm.","C":"Incorrect because senior management appoints both line and staff managers.","D":"Incorrect because this reverses line authority and specialist advisory roles."}}},{"id":"P1_U2_MCQ_631","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_631","question":"Which management function involves allocating resources, assigning tasks to individuals, and delegating authority so work is completed without duplication?","options":{"A":"Planning","B":"Controlling","C":"Organising","D":"Forecasting"},"correctOption":"C","correctAnswer":"Organising","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because organising arranges people, equipment, and responsibilities efficiently to carry out plans.","distractor_reasons":{"A":"Incorrect because planning sets objectives and overall strategy prior to organising.","B":"Incorrect because controlling monitors results against standards and corrects deviations.","C":"Correct selection.","D":"Incorrect because forecasting predicts future trends such as sales or staffing needs."}}},{"id":"P1_U2_MCQ_632","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_632","question":"Which management function focuses on bringing different departments and employees together so their efforts work smoothly toward common business goals?","options":{"A":"Retrenching","B":"Delayering","C":"Dismissing","D":"Coordinating"},"correctOption":"D","correctAnswer":"Coordinating","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because coordinating ensures marketing, production, finance, and HR align their activities without conflict.","distractor_reasons":{"A":"Incorrect because retrenching means making workers redundant to cut costs.","B":"Incorrect because delayering removes tiers of management from the hierarchy.","C":"Incorrect because dismissing terminates an individual's contract for misconduct or incompetence.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_633","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_633","question":"What does the management function of 'commanding' involve?","options":{"A":"Issuing company shares on a public stock exchange","B":"Auditing annual financial statements for external tax authorities","C":"Conducting market research surveys among external consumers","D":"Guiding, leading, and supervising employees to ensure they know their tasks and meet deadlines"},"correctOption":"D","correctAnswer":"Guiding, leading, and supervising employees to ensure they know their tasks and meet deadlines","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because commanding entails directing, motivating, and instructing staff in daily operations.","distractor_reasons":{"A":"Incorrect because issuing shares is corporate equity financing.","B":"Incorrect because financial auditing is performed by external accountants.","C":"Incorrect because consumer surveys belong to market research.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_634","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_634","question":"What is involved in the management function of 'controlling'?","options":{"A":"Measuring and evaluating actual performance against targets and taking corrective action if standards are not met","B":"Encouraging employees to ignore quality standards in order to finish early","C":"Writing initial job advertisements for external newspapers","D":"Negotiating collective wage agreements on behalf of a trade union"},"correctOption":"A","correctAnswer":"Measuring and evaluating actual performance against targets and taking corrective action if standards are not met","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because controlling checks whether plans are on track and intervenes when variances occur.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because controlling enforces standards rather than ignoring them.","C":"Incorrect because writing job adverts is part of recruitment.","D":"Incorrect because representing workers in wage talks is the role of a trade union."}}},{"id":"P1_U2_MCQ_635","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_635","question":"How does effective 'delegation' benefit a subordinate?","options":{"A":"It removes all accountability for completing the delegated task","B":"It develops new skills, shows that management trusts them, and increases job satisfaction and motivation","C":"It guarantees an immediate doubling of the subordinate's hourly wage","D":"It allows the subordinate to avoid doing any work at all"},"correctOption":"B","correctAnswer":"It develops new skills, shows that management trusts them, and increases job satisfaction and motivation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because entrusted authority enriches the subordinate's role and prepares them for future promotion.","distractor_reasons":{"A":"Incorrect because the subordinate is accountable to the manager for carrying out the delegated task properly.","B":"Correct selection.","C":"Incorrect because delegation assigns responsibility rather than automatically doubling pay.","D":"Incorrect because delegation adds meaningful tasks to the subordinate's role."}}},{"id":"P1_U2_MCQ_636","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_636","question":"Which leadership style encourages employees to participate in decision-making through two-way communication before the manager makes the final decision?","options":{"A":"Autocratic leadership","B":"Democratic leadership","C":"Laissez-faire leadership","D":"Authoritarian leadership"},"correctOption":"B","correctAnswer":"Democratic leadership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because democratic leaders consult staff, value their ideas, and foster engagement.","distractor_reasons":{"A":"Incorrect because autocratic leaders decide alone without employee input.","B":"Correct selection.","C":"Incorrect because laissez-faire leaders leave employees to make decisions independently with minimal managerial direction.","D":"Incorrect because authoritarian leadership is synonymous with autocratic top-down control."}}},{"id":"P1_U2_MCQ_637","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_637","question":"What is a key disadvantage of 'democratic leadership'?","options":{"A":"Communication flows strictly downward in one direction only","B":"Employees feel alienated because their opinions are completely ignored","C":"Managers never receive any creative suggestions from frontline workers","D":"Decision-making can be slow because consulting employees and discussing options takes time, making it unsuitable in emergencies"},"correctOption":"D","correctAnswer":"Decision-making can be slow because consulting employees and discussing options takes time, making it unsuitable in emergencies","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consultation slows down urgent decisions and is unsuitable when confidential matters (such as redundancies) are discussed.","distractor_reasons":{"A":"Incorrect because democratic leadership relies on two-way communication.","B":"Incorrect because ignoring employee views describes autocratic leadership.","C":"Incorrect because generating frontline ideas is a major advantage of democratic leadership.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_638","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_638","question":"In which business environment is 'laissez-faire leadership' most likely to succeed?","options":{"A":"A team of highly skilled, self-motivated software architects or fashion designers working on creative projects","B":"A factory assembly line staffed by newly recruited unskilled trainees handling hazardous machinery","C":"An emergency fire-and-rescue response team during an active building fire","D":"A workplace where employees lack basic training and require constant step-by-step instructions"},"correctOption":"A","correctAnswer":"A team of highly skilled, self-motivated software architects or fashion designers working on creative projects","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because experienced, creative specialists thrive when given broad objectives and freedom to innovate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unskilled staff near hazards require close supervision and clear rules.","C":"Incorrect because emergencies demand rapid autocratic command.","D":"Incorrect because inexperienced workers lacking direction struggle under hands-off leadership."}}},{"id":"P1_U2_MCQ_639","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_639","question":"Which of the following is a benefit to an employee of belonging to a 'trade union'?","options":{"A":"Stronger collective bargaining power over pay and working conditions, plus legal support if unfairly treated","B":"Guaranteed automatic promotion to Chief Executive Officer within one year","C":"Exemption from having to follow workplace health and safety rules","D":"Ownership of 100% of the employer's company shares"},"correctOption":"A","correctAnswer":"Stronger collective bargaining power over pay and working conditions, plus legal support if unfairly treated","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'strength in numbers' enables a union to negotiate better terms and represent individual members in grievances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because promotions are decided by management based on merit and vacancies.","C":"Incorrect because trade unions actively promote strict compliance with safety rules.","D":"Incorrect because trade unions represent workers' interests rather than owning the business."}}},{"id":"P1_U2_MCQ_640","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_640","question":"How can recognising a single 'trade union' benefit an employer?","options":{"A":"It allows the employer to pay below the statutory minimum wage","B":"It legally guarantees that workers will never request a pay rise","C":"Managers can negotiate pay and conditions with one representative body rather than bargaining separately with hundreds of individual workers","D":"It eliminates the need for the business to have any human resources policies"},"correctOption":"C","correctAnswer":"Managers can negotiate pay and conditions with one representative body rather than bargaining separately with hundreds of individual workers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collective bargaining through one recognised union saves negotiation time and provides a clear channel for resolving disputes.","distractor_reasons":{"A":"Incorrect because statutory minimum wage laws cannot be overridden by union agreements.","B":"Incorrect because trade unions routinely negotiate for higher pay and improved benefits.","C":"Correct selection.","D":"Incorrect because businesses still need formal HR policies and contracts."}}},{"id":"P1_U2_MCQ_641","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_641","question":"What is the distinction between 'recruitment' and 'selection'?","options":{"A":"Recruitment is the process of attracting suitable candidates to apply for a vacancy, whereas selection is choosing the best candidate from those who applied","B":"Recruitment applies only to part-time workers, whereas selection applies only to full-time managers","C":"Recruitment takes place after a worker is hired, whereas selection happens when a worker retires","D":"Recruitment is carried out by trade unions, whereas selection is carried out by customers"},"correctOption":"A","correctAnswer":"Recruitment is the process of attracting suitable candidates to apply for a vacancy, whereas selection is choosing the best candidate from those who applied","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recruitment builds a pool of qualified applicants, while selection evaluates and picks the most suitable person.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both recruitment and selection apply to all job types and levels.","C":"Incorrect because both processes occur before a new employee starts work (followed by induction).","D":"Incorrect because employers manage both recruitment and selection."}}},{"id":"P1_U2_MCQ_642","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_642","question":"What is meant by 'job analysis'?","options":{"A":"Dismissing an employee after three formal written warnings","B":"Calculating the total profit earned by a company over the past five years","C":"Identifying and recording the responsibilities, duties, and tasks relating to a specific job","D":"Evaluating customer satisfaction with a newly launched product"},"correctOption":"C","correctAnswer":"Identifying and recording the responsibilities, duties, and tasks relating to a specific job","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job analysis examines what a role involves so accurate job descriptions and person specifications can be drafted.","distractor_reasons":{"A":"Incorrect because terminating employment for misconduct is disciplinary dismissal.","B":"Incorrect because profit measurement belongs to financial accounting.","C":"Correct selection.","D":"Incorrect because measuring customer feedback is market research."}}},{"id":"P1_U2_MCQ_643","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_643","question":"Which item would normally be included in a 'job description'?","options":{"A":"The applicant's personal hobbies, home address, and school exam grades","B":"The job title, main duties and responsibilities, department, and who the job holder reports to","C":"A list of all rival businesses operating in the same industry","D":"The medical history of the previous person who held the job"},"correctOption":"B","correctAnswer":"The job title, main duties and responsibilities, department, and who the job holder reports to","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a job description defines the scope, tasks, and hierarchical position of the role.","distractor_reasons":{"A":"Incorrect because personal details and grades belong on an applicant's CV or application form.","B":"Correct selection.","C":"Incorrect because competitor lists are irrelevant to defining a job's duties.","D":"Incorrect because confidential medical records are never placed in a job description."}}},{"id":"P1_U2_MCQ_644","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_644","question":"Which item belongs in a 'person specification' rather than a 'job description'?","options":{"A":"The titles of the subordinates whom the manager will supervise","B":"The daily opening and closing hours of the company's warehouse","C":"Essential and desirable qualifications, relevant work experience, skills, and personal qualities required of the applicant","D":"The physical address of the factory where the role is based"},"correctOption":"C","correctAnswer":"Essential and desirable qualifications, relevant work experience, skills, and personal qualities required of the applicant","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a person specification sets out the human attributes needed to perform the job effectively.","distractor_reasons":{"A":"Incorrect because reporting lines and subordinates are part of the job description.","B":"Incorrect because working hours and site routines relate to the job description or contract.","C":"Correct selection.","D":"Incorrect because workplace location is a feature of the job description."}}},{"id":"P1_U2_MCQ_645","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_645","question":"What is meant by 'external recruitment'?","options":{"A":"Promoting a current supervisor to become a departmental manager","B":"Filling a job vacancy with someone who is not currently employed by the business","C":"Transferring an existing worker from one branch to another within the same firm","D":"Sending current employees to an external college for off-the-job training"},"correctOption":"B","correctAnswer":"Filling a job vacancy with someone who is not currently employed by the business","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external recruitment brings in candidates from outside the organisation.","distractor_reasons":{"A":"Incorrect because promoting an existing worker is internal recruitment.","B":"Correct selection.","C":"Incorrect because transferring an existing employee between branches is internal recruitment.","D":"Incorrect because training existing staff outside the workplace is off-the-job training."}}},{"id":"P1_U2_MCQ_646","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_646","question":"Which of the following is a key advantage of 'external recruitment'?","options":{"A":"It avoids the need for any induction training when the new starter arrives","B":"It requires zero spending on job advertisements or selection interviews","C":"The employer already has years of firsthand evidence of the candidate's daily work ethic","D":"It brings fresh ideas, new specialist skills, and wider industry experience into the business from a larger pool of applicants"},"correctOption":"D","correctAnswer":"It brings fresh ideas, new specialist skills, and wider industry experience into the business from a larger pool of applicants","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because external hiring injects new perspectives and widens candidate choice beyond existing staff.","distractor_reasons":{"A":"Incorrect because external hires require thorough induction to learn company systems and culture.","B":"Incorrect because external recruitment typically involves higher advertising and interview costs.","C":"Incorrect because firsthand knowledge of work ethic is an advantage of internal recruitment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_647","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_647","question":"What is a major disadvantage of 'external recruitment'?","options":{"A":"No fresh ideas or external perspectives can enter the company","B":"It is more expensive and time-consuming, and there is a greater risk of hiring someone who does not fit the organisation well","C":"It always creates a secondary internal vacancy that must be backfilled","D":"It restricts the business to choosing from only its existing employees"},"correctOption":"B","correctAnswer":"It is more expensive and time-consuming, and there is a greater risk of hiring someone who does not fit the organisation well","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external advertising, screening, and induction are costly, and interviews cannot guarantee long-term job fit.","distractor_reasons":{"A":"Incorrect because lack of fresh ideas is a drawback of internal recruitment.","B":"Correct selection.","C":"Incorrect because creating a secondary vacancy occurs when an internal worker is promoted.","D":"Incorrect because external recruitment opens the vacancy to outside applicants."}}},{"id":"P1_U2_MCQ_648","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_648","question":"Which method would a business use to carry out 'internal recruitment'?","options":{"A":"Paying an international executive headhunting agency","B":"Advertising the vacancy on the company intranet, staff noticeboard, or internal email newsletter","C":"Placing a job advertisement in a national daily newspaper","D":"Listing the vacancy at a government-run public job centre"},"correctOption":"B","correctAnswer":"Advertising the vacancy on the company intranet, staff noticeboard, or internal email newsletter","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because internal channels communicate job openings directly to existing employees.","distractor_reasons":{"A":"Incorrect because headhunters search outside the business for external talent.","B":"Correct selection.","C":"Incorrect because national newspapers target external applicants.","D":"Incorrect because public job centres serve unemployed and external jobseekers."}}},{"id":"P1_U2_MCQ_649","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_649","question":"When is advertising in a 'local newspaper' more appropriate than advertising in a 'national newspaper'?","options":{"A":"When recruiting for unskilled or semi-skilled roles where applicants are expected to live within daily commuting distance","B":"When searching across the entire country for a chief financial officer of a multinational bank","C":"When filling a highly specialised scientific research post where very few qualified people exist nationwide","D":"When the business intends to recruit strictly from its existing internal workforce"},"correctOption":"A","correctAnswer":"When recruiting for unskilled or semi-skilled roles where applicants are expected to live within daily commuting distance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local newspapers are cheaper and reach nearby residents suited to local operational or retail jobs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because senior executive posts require national or international reach.","C":"Incorrect because scarce specialists require national media or specialist trade journals.","D":"Incorrect because internal recruitment uses internal noticeboards or intranets rather than public newspapers."}}},{"id":"P1_U2_MCQ_650","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_650","question":"What is an advantage and a disadvantage of using a private 'recruitment agency' to fill vacancies?","options":{"A":"It saves the employer time by advertising and shortlisting candidates, but charges expensive commission fees","B":"It is completely free of charge to the employer, but never screens any candidates","C":"It guarantees that hired staff will never resign, but is illegal in service industries","D":"It writes the business's annual tax return, but refuses to recommend job applicants"},"correctOption":"A","correctAnswer":"It saves the employer time by advertising and shortlisting candidates, but charges expensive commission fees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agencies maintain databases of pre-screened candidates, reducing HR workload at a significant financial cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private agencies charge substantial fees (whereas government job centres are free).","C":"Incorrect because agencies are lawful and cannot permanently prevent staff from resigning later.","D":"Incorrect because tax returns are handled by accountants, not recruitment agencies."}}},{"id":"P1_U2_MCQ_651","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_651","question":"What is the role of a government-run 'job centre' in the recruitment process?","options":{"A":"A trade union office that organises industrial strike action","B":"A private luxury headhunting firm that recruits only chief executives for global corporations","C":"A free public service where employers can advertise vacancies, typically used for local, manual, or semi-skilled jobs","D":"A college department that awards university engineering degrees"},"correctOption":"C","correctAnswer":"A free public service where employers can advertise vacancies, typically used for local, manual, or semi-skilled jobs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public job centres connect local jobseekers with employers at no advertising fee.","distractor_reasons":{"A":"Incorrect because job centres are state employment offices, not trade unions.","B":"Incorrect because executive search is done by private specialist headhunters.","C":"Correct selection.","D":"Incorrect because degree courses are delivered by universities."}}},{"id":"P1_U2_MCQ_652","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_652","question":"What information is typically included in a candidate's 'Curriculum Vitae (CV)'?","options":{"A":"Personal contact details, educational qualifications, past employment history, key skills, and names of referees","B":"The employer's confidential profit forecasts and pricing strategy","C":"A legally binding contract signed by the company's board of directors","D":"The disciplinary warnings issued to other employees in the company"},"correctOption":"A","correctAnswer":"Personal contact details, educational qualifications, past employment history, key skills, and names of referees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a CV is a candidate's structured summary of background, qualifications, and experience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because company financial forecasts belong to internal management.","C":"Incorrect because an employment contract is issued only after a candidate is selected.","D":"Incorrect because staff disciplinary records are confidential HR files."}}},{"id":"P1_U2_MCQ_653","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_653","question":"What takes place during the 'shortlisting' stage of selection?","options":{"A":"Conducting workplace health and safety tours for newly hired staff","B":"Comparing all received application forms and CVs against the person specification to choose the best candidates to invite for interview","C":"Negotiating redundancy compensation packages with departing employees","D":"Publishing the initial job advertisement in a trade magazine"},"correctOption":"B","correctAnswer":"Comparing all received application forms and CVs against the person specification to choose the best candidates to invite for interview","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shortlisting narrows a large pool of applicants down to those who best meet the essential criteria.","distractor_reasons":{"A":"Incorrect because workplace tours occur during induction after hiring.","B":"Correct selection.","C":"Incorrect because redundancy negotiations involve existing staff whose jobs are ending.","D":"Incorrect because advertising happens before applications are received and shortlisted."}}},{"id":"P1_U2_MCQ_654","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_654","question":"What is the main purpose of conducting 'interviews' during employee selection?","options":{"A":"To avoid having to define a job description or person specification","B":"To guarantee that every applicant receives an immediate job offer","C":"To assess candidates' personality, communication skills, and enthusiasm, and to probe details on their application","D":"To replace the need for any workplace training once hired"},"correctOption":"C","correctAnswer":"To assess candidates' personality, communication skills, and enthusiasm, and to probe details on their application","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interviews allow two-way interaction to judge interpersonal fit and clarify experience.","distractor_reasons":{"A":"Incorrect because interview questions are structured around the job description and person specification.","B":"Incorrect because interviews compare shortlisted candidates so only the most suitable person is chosen.","C":"Correct selection.","D":"Incorrect because successful candidates still require induction and job training."}}},{"id":"P1_U2_MCQ_655","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_655","question":"Why might an employer use a 'panel interview' (multiple interviewers) rather than a 'one-to-one interview'?","options":{"A":"It completely eliminates candidate nervousness during questioning","B":"It is always cheaper because only one manager needs to attend","C":"It reduces the risk of individual interviewer bias and allows specialists from different departments (such as HR and line management) to assess the candidate","D":"It allows the business to hire candidates without checking references"},"correctOption":"C","correctAnswer":"It reduces the risk of individual interviewer bias and allows specialists from different departments (such as HR and line management) to assess the candidate","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining multiple perspectives leads to fairer, more balanced selection decisions.","distractor_reasons":{"A":"Incorrect because facing several interviewers at once often increases candidate nervousness.","B":"Incorrect because having several managers in a panel uses more managerial time than a one-to-one interview.","C":"Correct selection.","D":"Incorrect because reference checks are still conducted alongside interviews."}}},{"id":"P1_U2_MCQ_656","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_656","question":"What are 'psychometric (personality) tests' designed to assess during selection?","options":{"A":"Whether a candidate is a member of a recognised trade union","B":"A candidate's physical lifting strength in a warehouse","C":"The exact amount of corporate income tax the business owes","D":"A candidate's behavioural traits, attitudes, and emotional suitability for the role and team culture"},"correctOption":"D","correctAnswer":"A candidate's behavioural traits, attitudes, and emotional suitability for the role and team culture","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because psychometric tests evaluate psychological characteristics such as leadership style, resilience, and teamwork orientation.","distractor_reasons":{"A":"Incorrect because union membership is protected and not assessed via personality tests.","B":"Incorrect because physical strength is tested via physical fitness assessments.","C":"Incorrect because tax liabilities are calculated by accountants.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_657","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_657","question":"Why do some employers include 'group exercises' in their selection process?","options":{"A":"To replace written contracts of employment with verbal group agreements","B":"To save time by hiring the entire group of applicants simultaneously","C":"To test each candidate's ability to work in complete isolation without speaking","D":"To observe how candidates interact, communicate, cooperate, and show leadership when solving a problem with others"},"correctOption":"D","correctAnswer":"To observe how candidates interact, communicate, cooperate, and show leadership when solving a problem with others","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because group tasks reveal interpersonal and teamwork behaviours that may not emerge in a standard interview.","distractor_reasons":{"A":"Incorrect because individual written employment contracts are still legally required.","B":"Incorrect because group exercises are used to compare and select individual candidates, not hire everyone.","C":"Incorrect because group exercises specifically evaluate collaboration rather than solo isolation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_658","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_658","question":"What defines 'part-time employment'?","options":{"A":"Working fewer hours per week than a standard full-time employee in the same organisation","B":"Working without any legal rights or statutory protection against discrimination","C":"Working exclusively as an unpaid volunteer for a charity","D":"Working 60 hours per week on a permanent managerial contract"},"correctOption":"A","correctAnswer":"Working fewer hours per week than a standard full-time employee in the same organisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because part-time employees are contracted for reduced weekly hours (for example, 15–25 hours rather than 35–40 hours).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because part-time workers enjoy pro-rata employment rights and statutory protections.","C":"Incorrect because part-time staff are paid employees, not unpaid volunteers.","D":"Incorrect because 60 hours per week exceeds full-time working hours."}}},{"id":"P1_U2_MCQ_659","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_659","question":"Which of the following is an advantage to a business of employing 'full-time workers' rather than 'part-time workers'?","options":{"A":"Full-time workers can be dismissed without following any fair disciplinary rules","B":"Full-time workers never require any annual paid holiday entitlement","C":"Consistent continuity of staff presence, easier internal communication, and lower recruitment and training costs per hour worked","D":"Full-time staffing eliminates all wage costs during quiet trading hours"},"correctOption":"C","correctAnswer":"Consistent continuity of staff presence, easier internal communication, and lower recruitment and training costs per hour worked","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fewer full-time workers are needed to cover operating hours, simplifying scheduling and training.","distractor_reasons":{"A":"Incorrect because full-time employees are protected by unfair dismissal legislation.","B":"Incorrect because full-time employees are legally entitled to paid annual leave.","C":"Correct selection.","D":"Incorrect because full-time staff must be paid for their full contracted hours even during quiet periods."}}},{"id":"P1_U2_MCQ_660","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_660","question":"Why do many workers prefer 'part-time employment'?","options":{"A":"Part-time workers always earn a higher total annual income than full-time directors","B":"It provides greater flexibility to balance paid work with childcare, studying, or personal commitments","C":"Part-time employment guarantees automatic promotion every six months","D":"Part-time workers do not have to pay any income tax regardless of how much they earn"},"correctOption":"B","correctAnswer":"It provides greater flexibility to balance paid work with childcare, studying, or personal commitments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reduced, flexible hours enable students, parents, and semi-retired workers to participate in the labour market.","distractor_reasons":{"A":"Incorrect because working fewer hours normally results in lower total weekly/annual pay than full-time roles.","B":"Correct selection.","C":"Incorrect because promotion opportunities are sometimes narrower for part-time staff.","D":"Incorrect because income tax depends on total taxable earnings, not full-time versus part-time status."}}},{"id":"P1_U2_MCQ_661","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_661","question":"Which of the following is an overall benefit to a business of investing in employee training?","options":{"A":"Complete elimination of the need to pay any wages or salaries","B":"Higher labour productivity, improved product quality with fewer mistakes, and a more flexible, multi-skilled workforce","C":"Guaranteed immunity from all economic recessions","D":"Immediate reduction of fixed capital equipment costs to zero"},"correctOption":"B","correctAnswer":"Higher labour productivity, improved product quality with fewer mistakes, and a more flexible, multi-skilled workforce","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because skilled workers operate machinery more efficiently, make fewer errors, and can cover different tasks.","distractor_reasons":{"A":"Incorrect because trained workers often command higher wages rather than working unpaid.","B":"Correct selection.","C":"Incorrect because external macroeconomic downturns still affect customer demand.","D":"Incorrect because machinery depreciation and equipment costs still apply."}}},{"id":"P1_U2_MCQ_662","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_662","question":"Why might a business be reluctant to spend heavily on training its employees?","options":{"A":"Training forces the business to lengthen its chain of command","B":"Training always reduces employee productivity and increases workplace accidents","C":"Training is prohibited by government employment legislation","D":"Training is expensive, output is lost while staff are being trained, and newly trained workers may leave to join competitors"},"correctOption":"D","correctAnswer":"Training is expensive, output is lost while staff are being trained, and newly trained workers may leave to join competitors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employers face upfront training costs, short-term production disruption, and the risk of 'poaching' by rivals.","distractor_reasons":{"A":"Incorrect because training builds skills without adding managerial tiers.","B":"Incorrect because training improves productivity and safety rather than worsening them.","C":"Incorrect because governments actively encourage and often mandate workplace training.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_663","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_663","question":"Which of the following activities is normally part of 'induction training'?","options":{"A":"Interviewing external applicants before a job offer is made","B":"Sending a senior director to an overseas business conference","C":"Conducting disciplinary hearings for long-serving staff","D":"Showing the new employee around the premises, explaining health and safety rules, and introducing them to colleagues and line managers"},"correctOption":"D","correctAnswer":"Showing the new employee around the premises, explaining health and safety rules, and introducing them to colleagues and line managers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because induction integrates a newly hired employee smoothly into the workplace environment and procedures.","distractor_reasons":{"A":"Incorrect because interviews occur during selection prior to recruitment completion.","B":"Incorrect because external conferences are off-the-job development for existing managers.","C":"Incorrect because disciplinary hearings address misconduct rather than welcoming new hires.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_664","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_664","question":"What is a likely consequence if a business fails to provide proper 'induction training' to new recruits?","options":{"A":"The business permanently eliminates all labour turnover","B":"New starters immediately achieve higher output than experienced supervisors","C":"New starters may feel anxious, make avoidable mistakes, breach safety rules, and leave the business early","D":"New employees require zero supervision from their first day"},"correctOption":"C","correctAnswer":"New starters may feel anxious, make avoidable mistakes, breach safety rules, and leave the business early","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because throwing new employees straight into work without orientation causes confusion, lower initial productivity, and early resignations.","distractor_reasons":{"A":"Incorrect because poor onboarding increases early staff departures.","B":"Incorrect because unfamiliarity with systems slows down new recruits.","C":"Correct selection.","D":"Incorrect because uninducted hires need extra supervision to correct mistakes."}}},{"id":"P1_U2_MCQ_665","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_665","question":"Which of the following is an example of 'on-the-job training'?","options":{"A":"A sales manager attending a three-day seminar at a conference hotel","B":"An accountant attending an evening degree course at a local university","C":"A pilot training in an external flight simulator centre located in another city","D":"A trainee machine operator shadowing and being coached by an experienced operator on the factory floor"},"correctOption":"D","correctAnswer":"A trainee machine operator shadowing and being coached by an experienced operator on the factory floor","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job training takes place at the normal workplace while performing actual work tasks.","distractor_reasons":{"A":"Incorrect because external hotel seminars are off-the-job training.","B":"Incorrect because university courses are off-the-job training.","C":"Incorrect because external simulator facilities are off-the-job training.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_666","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_666","question":"Which of the following is an example of 'off-the-job training'?","options":{"A":"A factory worker rotating between two assembly stations on the same production line","B":"A new cashier being watched and guided by a supervisor at the supermarket checkout","C":"Employees attending a specialist software workshop run by external trainers at a technical college","D":"A trainee chef learning knife skills in the restaurant kitchen during lunch service"},"correctOption":"C","correctAnswer":"Employees attending a specialist software workshop run by external trainers at a technical college","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because off-the-job training occurs away from the employee's normal workstation using specialist instruction.","distractor_reasons":{"A":"Incorrect because rotating workstations on the line is on-the-job training.","B":"Incorrect because coaching at the checkout is on-the-job training.","C":"Correct selection.","D":"Incorrect because learning in the working kitchen during service is on-the-job training."}}},{"id":"P1_U2_MCQ_667","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_667","question":"What is a major disadvantage of 'off-the-job training' for an employer?","options":{"A":"High course and travel fees, combined with lost output while employees are away from their jobs","B":"Trainees are forced to learn on broken machinery in a noisy factory","C":"Trainees can never earn any recognised external qualifications","D":"Experienced internal mentors lose productivity while demonstrating tasks on the line"},"correctOption":"A","correctAnswer":"High course and travel fees, combined with lost output while employees are away from their jobs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external providers charge tuition fees and the business pays wages while receiving no immediate output during training hours.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because off-the-job training takes place away from factory floor noise.","C":"Incorrect because earning recognised qualifications is an advantage of off-the-job training.","D":"Incorrect because reduced output of an internal mentor is a drawback of on-the-job training."}}},{"id":"P1_U2_MCQ_668","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_668","question":"Which situation would most likely require a business to reduce the size of its workforce through 'redundancy'?","options":{"A":"A sudden surge in export orders requiring double production capacity","B":"A long-term fall in customer demand for the company's products or the closure of a loss-making factory","C":"An individual employee arriving late once due to a traffic jam","D":"The promotion of an assistant manager to store manager"},"correctOption":"B","correctAnswer":"A long-term fall in customer demand for the company's products or the closure of a loss-making factory","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because falling demand or site closures eliminate the business need for existing jobs.","distractor_reasons":{"A":"Incorrect because rising orders require expanding the workforce rather than downsizing.","B":"Correct selection.","C":"Incorrect because minor lateness is a disciplinary matter, not redundancy.","D":"Incorrect because promotion fills a role rather than eliminating jobs."}}},{"id":"P1_U2_MCQ_669","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_669","question":"Which fair criterion might a business use when deciding which employees to make redundant?","options":{"A":"Choosing employees at random without consulting staff or trade unions","B":"Selecting employees solely based on their race, gender, or pregnancy","C":"Dismissing only workers who are active members of a recognised trade union","D":"Retaining workers with essential skills and strong productivity/attendance records, or offering voluntary redundancy first"},"correctOption":"D","correctAnswer":"Retaining workers with essential skills and strong productivity/attendance records, or offering voluntary redundancy first","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because objective operational criteria (skills, performance, attendance) and voluntary redundancy protect business capability and comply with employment law.","distractor_reasons":{"A":"Incorrect because lack of fair criteria and consultation exposes the employer to unfair dismissal claims.","B":"Incorrect because selecting workers based on protected characteristics is illegal discrimination.","C":"Incorrect because targeting union members is unlawful unfair dismissal.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_670","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_670","question":"What is the difference between 'voluntary redundancy' and 'compulsory redundancy'?","options":{"A":"In voluntary redundancy, employees choose to leave in exchange for a financial severance package, whereas in compulsory redundancy, the employer selects workers to leave against their wishes","B":"In voluntary redundancy, employees receive zero compensation, whereas in compulsory redundancy, employees are promoted","C":"Voluntary redundancy occurs when an employee is sacked for theft, whereas compulsory redundancy occurs when a worker retires at age 65","D":"Voluntary redundancy is illegal, whereas compulsory redundancy requires no notice period"},"correctOption":"A","correctAnswer":"In voluntary redundancy, employees choose to leave in exchange for a financial severance package, whereas in compulsory redundancy, the employer selects workers to leave against their wishes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because offering voluntary redundancy softens morale damage by allowing willing staff (such as those nearing retirement) to step forward.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because voluntary redundancy typically offers enhanced severance pay to attract volunteers.","C":"Incorrect because theft results in dismissal and reaching retirement age is retirement.","D":"Incorrect because both voluntary and compulsory redundancy are lawful when conducted fairly."}}},{"id":"P1_U2_MCQ_671","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_671","question":"What is meant by 'resignation'?","options":{"A":"When a job ceases to exist because new machinery replaces human labour","B":"When an employer terminates a worker's contract for gross misconduct","C":"When an employee voluntarily decides to leave their job by giving notice to the employer","D":"When an employee is temporarily suspended on full pay during an investigation"},"correctOption":"C","correctAnswer":"When an employee voluntarily decides to leave their job by giving notice to the employer","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because resignation is initiated voluntarily by the employee rather than the employer.","distractor_reasons":{"A":"Incorrect because job elimination due to automation is redundancy.","B":"Incorrect because employer-initiated termination for misconduct is dismissal.","C":"Correct selection.","D":"Incorrect because suspension is a temporary administrative step, not resignation."}}},{"id":"P1_U2_MCQ_672","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_672","question":"What is meant by 'retirement' in workforce planning?","options":{"A":"When an employee switches from full-time to part-time hours","B":"When an employee is sacked for failing to meet sales targets","C":"When a business closes down a factory due to falling demand","D":"When an employee leaves their job and permanently exits the workforce upon reaching retirement age"},"correctOption":"D","correctAnswer":"When an employee leaves their job and permanently exits the workforce upon reaching retirement age","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retirement marks the end of an employee's working career, often predictable through workforce age profiles.","distractor_reasons":{"A":"Incorrect because reducing weekly hours is changing to part-time work.","B":"Incorrect because being sacked for poor performance is dismissal.","C":"Incorrect because job loss due to factory closure is redundancy.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_673","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_673","question":"Which workplace offence would normally be classified as 'gross misconduct', justifying immediate (summary) dismissal without prior warnings?","options":{"A":"Arriving five minutes late for work on a single occasion","B":"Theft of company property, fraud, or physical violence against a colleague","C":"Asking a supervisor a clarifying question about a new task","D":"Joining a legally recognised trade union"},"correctOption":"B","correctAnswer":"Theft of company property, fraud, or physical violence against a colleague","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because severe breaches of trust or safety destroy the employment relationship immediately.","distractor_reasons":{"A":"Incorrect because minor occasional lateness warrants at most an informal or verbal warning.","B":"Correct selection.","C":"Incorrect because asking questions is healthy two-way communication.","D":"Incorrect because union membership is a protected legal right."}}},{"id":"P1_U2_MCQ_674","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_674","question":"Why must an employer normally follow a formal disciplinary procedure (verbal warning, written warning, final warning) before dismissing an employee for persistent poor performance?","options":{"A":"Because warnings automatically increase the employee's hourly wage rate","B":"Because employment law forbids employers from ever dismissing an underperforming worker","C":"So that the employee can claim statutory redundancy compensation","D":"To give the employee a fair opportunity to improve and to protect the employer against legal claims of unfair dismissal"},"correctOption":"D","correctAnswer":"To give the employee a fair opportunity to improve and to protect the employer against legal claims of unfair dismissal","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fair procedures demonstrate reasonableness and support before an employment tribunal.","distractor_reasons":{"A":"Incorrect because disciplinary warnings do not raise pay.","B":"Incorrect because fair dismissal for persistent incompetence is lawful once proper warnings have been given.","C":"Incorrect because dismissed workers do not receive redundancy pay.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_675","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_675","question":"What is the primary purpose of government 'employment legislation'?","options":{"A":"To guarantee that every private business makes an annual profit","B":"To protect employees from unfair treatment, unsafe working conditions, discrimination, and exploitation by employers","C":"To prevent employees from ever resigning to join a rival company","D":"To eliminate all taxes paid by limited companies"},"correctOption":"B","correctAnswer":"To protect employees from unfair treatment, unsafe working conditions, discrimination, and exploitation by employers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because labour laws establish minimum standards for contracts, pay, health and safety, and fair dismissal.","distractor_reasons":{"A":"Incorrect because business profitability depends on market performance, not labour laws.","B":"Correct selection.","C":"Incorrect because workers retain freedom to resign with proper notice.","D":"Incorrect because employment laws govern workplace rights rather than corporate tax exemptions."}}},{"id":"P1_U2_MCQ_676","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_676","question":"What does 'anti-discrimination legislation' require of employers?","options":{"A":"Employers must pay every employee in the entire company the exact same salary regardless of role or skill","B":"Employers must not treat applicants or employees unfairly in recruitment, pay, training, or promotion on grounds such as gender, race, religion, age, or disability","C":"Employers must hire applicants strictly based on their personal friendship with the manager","D":"Employers are prohibited from testing candidates' practical job skills during selection"},"correctOption":"B","correctAnswer":"Employers must not treat applicants or employees unfairly in recruitment, pay, training, or promotion on grounds such as gender, race, religion, age, or disability","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because equal opportunity laws require employment decisions to be based on merit and job-related criteria.","distractor_reasons":{"A":"Incorrect because different pay for different roles, skills, and seniority is lawful provided equal work receives equal pay.","B":"Correct selection.","C":"Incorrect because favouritism violates merit-based selection.","D":"Incorrect because objective skills testing is lawful and encouraged."}}},{"id":"P1_U2_MCQ_677","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_677","question":"How does complying with 'anti-discrimination laws' benefit a business?","options":{"A":"It eliminates the need to write job descriptions or person specifications","B":"It allows the business to pay lower wages than the national minimum wage","C":"It widens the pool of talented applicants, improves staff morale, and protects the firm from costly legal claims and reputational damage","D":"It guarantees that no employee will ever require training"},"correctOption":"C","correctAnswer":"It widens the pool of talented applicants, improves staff morale, and protects the firm from costly legal claims and reputational damage","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because recruiting from all groups of society accesses the best talent and avoids tribunal penalties.","distractor_reasons":{"A":"Incorrect because clear job descriptions and person specifications are vital to prove objective hiring.","B":"Incorrect because minimum wage laws still apply equally to all workers.","C":"Correct selection.","D":"Incorrect because all new hires still need training."}}},{"id":"P1_U2_MCQ_678","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_678","question":"What is meant by a 'legal minimum wage'?","options":{"A":"The lowest hourly rate of pay that an employer is legally permitted to pay an employee","B":"The maximum annual salary a chief executive is allowed to earn","C":"A voluntary bonus paid only when a company exceeds its profit target","D":"The lump-sum severance payment given to redundant workers"},"correctOption":"A","correctAnswer":"The lowest hourly rate of pay that an employer is legally permitted to pay an employee","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a statutory minimum wage sets a legal pay floor to prevent worker exploitation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it sets a minimum floor for low-paid workers, not a ceiling on executive pay.","C":"Incorrect because minimum wage is mandatory by law rather than a voluntary bonus.","D":"Incorrect because severance compensation is statutory redundancy pay."}}},{"id":"P1_U2_MCQ_679","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_679","question":"What is a likely impact on a labour-intensive business when the government raises the 'legal minimum wage'?","options":{"A":"Total wage costs increase, which may reduce profit margins or force price rises, though low-paid staff may feel more motivated","B":"Total labour costs fall dramatically because workers receive lower hourly pay","C":"The business becomes exempt from paying overtime rates","D":"All employees immediately become part-time workers"},"correctOption":"A","correctAnswer":"Total wage costs increase, which may reduce profit margins or force price rises, though low-paid staff may feel more motivated","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher statutory pay floors raise payroll expenses directly, though improved morale and retention can partially offset costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising the minimum wage increases hourly labour costs.","C":"Incorrect because higher minimum rates do not remove other employment rules.","D":"Incorrect because contract hours do not automatically convert to part-time."}}},{"id":"P1_U2_MCQ_680","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_680","question":"What is the role of an 'employment (industrial) tribunal'?","options":{"A":"A marketing department unit that designs television advertisements","B":"A private recruitment agency that supplies temporary factory workers","C":"An independent legal body that resolves disputes between employers and employees over issues such as unfair dismissal or discrimination","D":"A trade union committee that collects monthly membership fees"},"correctOption":"C","correctAnswer":"An independent legal body that resolves disputes between employers and employees over issues such as unfair dismissal or discrimination","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tribunals hear workplace legal complaints and can award compensation or reinstatement.","distractor_reasons":{"A":"Incorrect because advertising belongs to marketing.","B":"Incorrect because staffing is performed by employment agencies.","C":"Correct selection.","D":"Incorrect because tribunals are independent judicial bodies, not union committees."}}},{"id":"P1_U2_MCQ_681","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_681","question":"What is meant by 'internal communication'?","options":{"A":"Purchase orders emailed by a business to external raw-material suppliers","B":"Advertisements broadcast on national television to attract new consumers","C":"Messages sent between people working within the same business or organisation","D":"Annual financial reports published for external shareholders and banks"},"correctOption":"C","correctAnswer":"Messages sent between people working within the same business or organisation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal communication stays inside the boundaries of the organisation among managers and staff.","distractor_reasons":{"A":"Incorrect because ordering from outside suppliers is external communication.","B":"Incorrect because consumer advertising is external communication.","C":"Correct selection.","D":"Incorrect because reporting to external investors and banks is external communication."}}},{"id":"P1_U2_MCQ_682","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_682","question":"Why is 'effective external communication' essential for business success?","options":{"A":"It allows a business to avoid paying external suppliers on time","B":"It keeps all internal employees completely unaware of company goals","C":"It eliminates the need to produce quality goods or services","D":"It ensures customers receive accurate product and price information, builds a strong brand reputation, and prevents costly order errors with suppliers"},"correctOption":"D","correctAnswer":"It ensures customers receive accurate product and price information, builds a strong brand reputation, and prevents costly order errors with suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because clear external communication underpins customer satisfaction, supplier reliability, and public image.","distractor_reasons":{"A":"Incorrect because external communication supports timely, accurate commercial transactions.","B":"Incorrect because internal staff awareness relies on internal communication.","C":"Incorrect because communication promotes products rather than replacing product quality.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_683","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_683","question":"What are the four core elements required for effective communication to take place?","options":{"A":"Transmitter (sender), medium (channel), receiver, and feedback","B":"Planning, organising, commanding, and controlling","C":"Product, price, place, and promotion","D":"Land, labour, capital, and enterprise"},"correctOption":"A","correctAnswer":"Transmitter (sender), medium (channel), receiver, and feedback","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sender must transmit a message via an appropriate channel to a receiver who confirms understanding via feedback.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because these are the classical functions of management.","C":"Incorrect because these are the four Ps of the marketing mix.","D":"Incorrect because these are the four factors of production."}}},{"id":"P1_U2_MCQ_684","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_684","question":"What is the role of the 'transmitter (sender)' in the communication process?","options":{"A":"Background factory noise that distorts a spoken instruction","B":"The electronic cable or paper memo through which the message travels","C":"The person who interprets the message and sends a reply","D":"The person or group starting the process by sending the message and selecting an appropriate medium"},"correctOption":"D","correctAnswer":"The person or group starting the process by sending the message and selecting an appropriate medium","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the transmitter originates the information and encodes it for the intended recipient.","distractor_reasons":{"A":"Incorrect because background noise is a communication barrier.","B":"Incorrect because the method of transmission is the medium/channel.","C":"Incorrect because the person interpreting the message is the receiver.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_685","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_685","question":"What is the purpose of 'feedback' in the communication process?","options":{"A":"The initial written policy drafted by the senior management team","B":"The reply from the receiver confirming whether the message has been received, understood, and acted upon","C":"The physical distance between the head office and branch stores","D":"The technical jargon used by engineers in a technical manual"},"correctOption":"B","correctAnswer":"The reply from the receiver confirming whether the message has been received, understood, and acted upon","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because feedback closes the communication loop and alerts the sender to any misunderstanding.","distractor_reasons":{"A":"Incorrect because the initial policy is the message sent by the transmitter.","B":"Correct selection.","C":"Incorrect because distance between sites is a potential physical barrier.","D":"Incorrect because technical jargon is a language barrier."}}},{"id":"P1_U2_MCQ_686","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_686","question":"How does 'formal communication' differ from 'informal communication'?","options":{"A":"Formal communication never uses email, whereas informal communication uses only board meetings","B":"Formal communication is always spoken, whereas informal communication is always printed in legal contracts","C":"Formal communication occurs only with customers, whereas informal communication occurs only with banks","D":"Formal communication uses official channels approved by the organisation (such as memos, reports, and scheduled meetings), whereas informal communication occurs through unofficial social networks (the 'grapevine')"},"correctOption":"D","correctAnswer":"Formal communication uses official channels approved by the organisation (such as memos, reports, and scheduled meetings), whereas informal communication occurs through unofficial social networks (the 'grapevine')","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because formal channels follow the recognised organisational structure, whereas informal conversations arise naturally among colleagues.","distractor_reasons":{"A":"Incorrect because official company emails are formal and board meetings are strictly formal.","B":"Incorrect because legal contracts are formal written communication, while casual chats are informal.","C":"Incorrect because both formal and informal communication occur within the workplace.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_687","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_687","question":"What is 'downward communication' used for in a business?","options":{"A":"Coordinating schedules between two managers at the exact same level of authority","B":"Allowing shop-floor workers to submit complaints and suggestions to senior directors","C":"Passing instructions, company policies, targets, and feedback from managers down to subordinates","D":"Sending invoices and promotional brochures to external retail customers"},"correctOption":"C","correctAnswer":"Passing instructions, company policies, targets, and feedback from managers down to subordinates","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because downward communication flows from higher tiers of the hierarchy to lower tiers.","distractor_reasons":{"A":"Incorrect because peer-to-peer communication across the same level is horizontal communication.","B":"Incorrect because messages flowing from junior to senior staff are upward communication.","C":"Correct selection.","D":"Incorrect because messages to customers are external communication."}}},{"id":"P1_U2_MCQ_688","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_688","question":"Why is 'upward communication' valuable to senior managers?","options":{"A":"It allows directors to issue strict autocratic orders without listening to staff","B":"It provides feedback on how well instructions were understood, surfaces frontline problems early, and makes employees feel valued","C":"It replaces the need for any horizontal coordination between departments","D":"It ensures external customers never contact the sales department"},"correctOption":"B","correctAnswer":"It provides feedback on how well instructions were understood, surfaces frontline problems early, and makes employees feel valued","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because upward communication gives management accurate operational feedback and encourages employee participation.","distractor_reasons":{"A":"Incorrect because issuing top-down orders is downward communication.","B":"Correct selection.","C":"Incorrect because departments still need horizontal communication to coordinate daily workflows.","D":"Incorrect because upward communication is internal rather than customer-facing."}}},{"id":"P1_U2_MCQ_689","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_689","question":"Which of the following is an advantage of 'electronic communication' (such as email or an internal company intranet)?","options":{"A":"It works reliably even during a complete power cut and internet outage","B":"Messages can be sent almost instantaneously to large numbers of recipients across multiple locations at very low cost","C":"It guarantees that every recipient immediately reads and understands complex attachments","D":"It is completely immune to cybersecurity threats or accidental forwarding"},"correctOption":"B","correctAnswer":"Messages can be sent almost instantaneously to large numbers of recipients across multiple locations at very low cost","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital channels offer speed, global reach, and low marginal cost per message.","distractor_reasons":{"A":"Incorrect because electronic communication depends on electricity and network connectivity.","B":"Correct selection.","C":"Incorrect because emails can be ignored, misunderstood, or buried in crowded inboxes.","D":"Incorrect because electronic messages carry risks of hacking, viruses, or accidental data leaks."}}},{"id":"P1_U2_MCQ_690","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_690","question":"What is a major advantage of 'video conferencing' for a multinational business?","options":{"A":"It provides a physical paper contract signed in ink automatically","B":"It requires zero internet bandwidth or camera equipment","C":"It eliminates all time-zone differences between continents","D":"Managers in different countries can hold face-to-face discussions with visual body language while saving international travel time and hotel costs"},"correctOption":"D","correctAnswer":"Managers in different countries can hold face-to-face discussions with visual body language while saving international travel time and hotel costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because video conferencing combines visual/verbal cues with substantial travel cost and time savings.","distractor_reasons":{"A":"Incorrect because video calls are audiovisual rather than physical paper documents.","B":"Incorrect because video conferencing requires reliable broadband and audiovisual hardware.","C":"Incorrect because international participants must still coordinate across global time zones.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_691","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_691","question":"What is a common disadvantage of relying heavily on 'email' for internal workplace communication?","options":{"A":"Emails take several weeks to travel from one office floor to another","B":"Employees may suffer from information overload, and the lack of vocal tone or facial expression can cause messages to be misinterpreted","C":"It is impossible to attach documents or spreadsheets to an email","D":"Emails leave zero electronic record of what was sent"},"correctOption":"B","correctAnswer":"Employees may suffer from information overload, and the lack of vocal tone or facial expression can cause messages to be misinterpreted","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because excessive emails clutter inboxes and text-only messages lack non-verbal emotional cues.","distractor_reasons":{"A":"Incorrect because emails are delivered almost instantaneously.","B":"Correct selection.","C":"Incorrect because attaching files is a standard feature of email.","D":"Incorrect because emails create a stored digital record."}}},{"id":"P1_U2_MCQ_692","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_692","question":"Which set of factors should a manager consider when choosing the most appropriate 'communication medium'?","options":{"A":"Urgency/speed required, cost, whether a permanent written record is needed, complexity of details, and confidentiality","B":"The star signs of the employees and the colour of the office carpets","C":"Only the personal preference of the sender, regardless of whether the receiver can access the medium","D":"Whether the medium uses the longest possible chain of command"},"correctOption":"A","correctAnswer":"Urgency/speed required, cost, whether a permanent written record is needed, complexity of details, and confidentiality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching the channel to urgency, sensitivity, detail level, and record-keeping ensures effective communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because irrelevant personal or decorative details do not affect communication effectiveness.","C":"Incorrect because the receiver's access and comprehension are critical to choosing a medium.","D":"Incorrect because shorter, more direct channels are preferred to prevent distortion."}}},{"id":"P1_U2_MCQ_693","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_693","question":"Which communication approach is most appropriate when issuing a formal disciplinary warning to an employee?","options":{"A":"Sending a casual group text message to all employees in the department","B":"Posting the warning on a public noticeboard in the staff canteen","C":"Announcing the employee's mistake over the factory public-address loudspeaker","D":"A private one-to-one meeting to discuss the issue, followed by a formal written letter for permanent legal records"},"correctOption":"D","correctAnswer":"A private one-to-one meeting to discuss the issue, followed by a formal written letter for permanent legal records","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because disciplinary matters require confidentiality, two-way discussion, and documented written evidence.","distractor_reasons":{"A":"Incorrect because group texts violate privacy and lack formal documentation.","B":"Incorrect because public noticeboards breach confidentiality and humiliate the worker.","C":"Incorrect because loudspeaker announcements are public and inappropriate for sensitive HR issues.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_694","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_694","question":"Which of the following is a 'communication barrier' caused directly by the 'sender'?","options":{"A":"Using overly complicated technical jargon or ambiguous wording that the receiver cannot understand","B":"The receiver switching off their mobile phone during a meeting","C":"A sudden national electricity blackout disconnecting office servers","D":"Loud machinery noise in the warehouse drowning out speech"},"correctOption":"A","correctAnswer":"Using overly complicated technical jargon or ambiguous wording that the receiver cannot understand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because poor encoding—such as unclear phrasing or unexplained jargon—originates with the sender.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inattention by the recipient is a receiver barrier.","C":"Incorrect because power failure is a technical/medium barrier.","D":"Incorrect because machinery noise is a physical/environmental medium barrier."}}},{"id":"P1_U2_MCQ_695","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_695","question":"Which of the following is a 'communication barrier' related to the 'medium'?","options":{"A":"A receiver refusing to read a clearly printed safety poster","B":"A manager deliberately hiding bad news from the board of directors","C":"An employee distrusting a supervisor due to past disagreements","D":"A poor internet connection causing video calls to freeze or an email being sent to an outdated address"},"correctOption":"D","correctAnswer":"A poor internet connection causing video calls to freeze or an email being sent to an outdated address","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technical failures or broken channels prevent the message from reaching the receiver intact.","distractor_reasons":{"A":"Incorrect because ignoring a clear poster is a receiver barrier.","B":"Incorrect because withholding information is a sender barrier.","C":"Incorrect because mistrust is an interpersonal/receiver attitude barrier.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_696","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_696","question":"Which of the following is a 'communication barrier' associated with the 'receiver'?","options":{"A":"The company's email server crashes before the message is transmitted","B":"The sender writes a letter in a foreign language the receiver has never studied","C":"The receiver is not listening carefully, is tired, or distrusts the sender and ignores the message","D":"The organisational hierarchy has twelve layers of middle managers"},"correctOption":"C","correctAnswer":"The receiver is not listening carefully, is tired, or distrusts the sender and ignores the message","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inattention, fatigue, or negative attitude on the recipient's part blocks accurate decoding.","distractor_reasons":{"A":"Incorrect because server failure is a medium barrier.","B":"Incorrect because choosing an inappropriate language is a sender barrier.","C":"Correct selection.","D":"Incorrect because excessive hierarchy layers create structural/feedback distortion."}}},{"id":"P1_U2_MCQ_697","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_697","question":"What happens when a communication barrier prevents 'feedback' from reaching the sender?","options":{"A":"Employees feel highly empowered because their views are actively sought","B":"Communication automatically becomes faster and 100% accurate","C":"The message transforms into two-way horizontal dialogue","D":"The sender does not know whether the message was received or understood, allowing errors to go uncorrected"},"correctOption":"D","correctAnswer":"The sender does not know whether the message was received or understood, allowing errors to go uncorrected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because without feedback, misunderstandings remain hidden until costly mistakes occur.","distractor_reasons":{"A":"Incorrect because blocking feedback makes workers feel ignored rather than empowered.","B":"Incorrect because lack of feedback increases the risk of undetected errors.","C":"Incorrect because without feedback, communication remains strictly one-way.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_698","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_698","question":"Why is 'information overload' considered a barrier to effective communication?","options":{"A":"It occurs only when a business uses face-to-face spoken meetings","B":"It means employees receive zero information from management all year","C":"Sending too many excessive messages makes it difficult for receivers to identify and act upon genuinely important instructions","D":"It guarantees that every employee memorises every policy document"},"correctOption":"C","correctAnswer":"Sending too many excessive messages makes it difficult for receivers to identify and act upon genuinely important instructions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bombarding staff with constant emails and memos causes critical updates to be overlooked.","distractor_reasons":{"A":"Incorrect because information overload is especially common with electronic messaging.","B":"Incorrect because receiving no information is under-communication rather than overload.","C":"Correct selection.","D":"Incorrect because excessive volume reduces retention rather than improving it."}}},{"id":"P1_U2_MCQ_699","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_699","question":"How can a business overcome communication barriers caused by 'jargon or language differences'?","options":{"A":"By sending longer memos packed with complex technical terminology","B":"By using clear, simple everyday language, avoiding unexplained abbreviations, and translating key safety notices where needed","C":"By forbidding employees from asking questions if they do not understand","D":"By passing all messages verbally through six intermediate supervisors"},"correctOption":"B","correctAnswer":"By using clear, simple everyday language, avoiding unexplained abbreviations, and translating key safety notices where needed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tailoring language to the audience ensures clarity and prevents misinterpretation.","distractor_reasons":{"A":"Incorrect because technical jargon worsens comprehension barriers.","B":"Correct selection.","C":"Incorrect because encouraging questions helps clarify unfamiliar terms.","D":"Incorrect because adding intermediaries increases distortion."}}},{"id":"P1_U2_MCQ_700","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_700","question":"How can a manager overcome physical barriers such as 'loud factory noise' when giving complex operating instructions?","options":{"A":"Move to a quiet office or meeting room for the briefing and reinforce spoken instructions with clear written or visual diagrams","B":"Whisper the instructions across the noisy factory floor without checking for feedback","C":"Send no instructions at all and let workers guess how to operate the machinery","D":"Turn up the volume of surrounding machinery during the briefing"},"correctOption":"A","correctAnswer":"Move to a quiet office or meeting room for the briefing and reinforce spoken instructions with clear written or visual diagrams","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing background noise and combining verbal briefings with visual/written guides ensures accurate understanding.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because whispering over loud noise guarantees the message will not be heard.","C":"Incorrect because omitting instructions creates serious safety and quality hazards.","D":"Incorrect because increasing noise worsens the physical communication barrier."}}},{"id":"P1_U2_MCQ_701","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_701","question":"What is the primary purpose of a job description in the recruitment process?","options":{"A":"To outline the main duties, responsibilities, working hours, and reporting lines of a vacant post","B":"To list the academic qualifications, skills, and personal qualities required of an applicant","C":"To summarize an applicant's past employment history and educational background","D":"To serve as a legally binding agreement signed after a candidate accepts a job offer"},"correctOption":"A","correctAnswer":"To outline the main duties, responsibilities, working hours, and reporting lines of a vacant post","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a job description defines the tasks, responsibilities, working conditions, and reporting relationships attached to the role itself.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the qualifications, skills, and traits needed by the candidate are detailed in a person specification.","C":"Incorrect because a summary of an applicant's background is a curriculum vitae (CV) or resumé.","D":"Incorrect because a legally binding post-selection agreement is a contract of employment."}}},{"id":"P1_U2_MCQ_702","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_702","question":"Which recruitment document specifies the essential and desirable qualifications, experience, and personal qualities required of an ideal candidate?","options":{"A":"Job description","B":"Contract of employment","C":"Person specification","D":"Induction checklist"},"correctOption":"C","correctAnswer":"Person specification","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a person specification sets out the attributes, skills, qualifications, and experience required of the person performing the job.","distractor_reasons":{"A":"Incorrect because a job description outlines the duties and conditions of the role rather than candidate attributes.","B":"Incorrect because a contract of employment sets out legal terms such as pay, holiday entitlement, and sick pay after hiring.","C":"Correct selection.","D":"Incorrect because an induction checklist is used to orient a new employee after recruitment is complete."}}},{"id":"P1_U2_MCQ_703","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_703","question":"What is the correct first stage in the recruitment and selection process when a vacancy arises?","options":{"A":"Shortlisting applicants and inviting them for interviews","B":"Identifying the vacancy and conducting a job analysis of the tasks and skills required","C":"Advertising the position on external online job portals","D":"Requesting references from candidates' previous employers"},"correctOption":"B","correctAnswer":"Identifying the vacancy and conducting a job analysis of the tasks and skills required","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an employer must first confirm the need to fill the vacancy and analyse the duties and skills involved before drafting recruitment documents.","distractor_reasons":{"A":"Incorrect because shortlisting and interviewing occur after applications have been received.","B":"Correct selection.","C":"Incorrect because advertising takes place only after the job description and person specification are written.","D":"Incorrect because reference checks occur late in the selection process for final candidates."}}},{"id":"P1_U2_MCQ_704","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_704","question":"Which of the following is a major advantage of internal recruitment for a business?","options":{"A":"It brings completely new ideas and outside industry expertise into the organisation","B":"It provides access to a much wider pool of potential applicants","C":"It avoids creating any vacant post elsewhere in the organisation","D":"It saves external advertising costs and the candidate's work ethic is already known"},"correctOption":"D","correctAnswer":"It saves external advertising costs and the candidate's work ethic is already known","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because internal recruitment avoids external advertising expenses, relies on proven employee performance, and motivates other staff through promotion prospects.","distractor_reasons":{"A":"Incorrect because bringing fresh external perspectives is an advantage of external recruitment.","B":"Incorrect because external recruitment provides a larger pool of candidates than internal promotion.","C":"Incorrect because promoting an internal employee still leaves their previous position vacant.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_705","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_705","question":"What is a key disadvantage of relying solely on internal recruitment to fill senior vacancies?","options":{"A":"The selected employee requires extensive induction into company policies","B":"No fresh ideas or external management practices are brought into the business","C":"The business must pay high fees to external recruitment agencies","D":"Existing employees become demotivated due to a lack of promotion pathways"},"correctOption":"B","correctAnswer":"No fresh ideas or external management practices are brought into the business","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because internal recruitment restricts hiring to existing staff, preventing new outside perspectives and specialist external skills from entering the firm.","distractor_reasons":{"A":"Incorrect because internal candidates are already familiar with company policies and culture.","B":"Correct selection.","C":"Incorrect because external agency fees are incurred during external recruitment, not internal recruitment.","D":"Incorrect because internal recruitment actually boosts motivation by offering career advancement."}}},{"id":"P1_U2_MCQ_706","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_706","question":"Which of the following is an advantage of external recruitment?","options":{"A":"It is always faster and cheaper than promoting an existing employee","B":"The new recruit requires minimal induction training to learn internal routines","C":"It eliminates any risk of jealousy among existing employees","D":"It gives the business a wider choice of candidates with new skills and fresh ideas"},"correctOption":"D","correctAnswer":"It gives the business a wider choice of candidates with new skills and fresh ideas","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because external recruitment opens the vacancy to the wider labour market, bringing in diverse talent, specialist skills, and innovative ideas.","distractor_reasons":{"A":"Incorrect because external recruitment is typically slower and more expensive than internal recruitment.","B":"Incorrect because external recruits are unfamiliar with internal procedures and need thorough induction.","C":"Incorrect because hiring externally can still cause resentment among internal staff passed over for promotion.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_707","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_707","question":"What is a primary disadvantage of external recruitment compared with internal recruitment?","options":{"A":"Higher advertising and selection costs alongside a longer settling-in period","B":"A narrower pool of applicants from which to choose","C":"An inability to recruit candidates with specialist technical qualifications","D":"Automatic violation of equal opportunity employment legislation"},"correctOption":"A","correctAnswer":"Higher advertising and selection costs alongside a longer settling-in period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external recruitment incurs advertising and interviewing expenses and takes longer for the new hire to adapt to the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external recruitment offers a wider pool of candidates than internal recruitment.","C":"Incorrect because external recruitment is often used specifically to acquire scarce specialist skills.","D":"Incorrect because external recruitment is completely lawful when conducted fairly."}}},{"id":"P1_U2_MCQ_708","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_708","question":"Why do employers request references during the employee selection process?","options":{"A":"To compare candidates' physical fitness levels under timed conditions","B":"To replace the legal need for a written contract of employment","C":"To obtain independent confirmation of an applicant's past reliability, character, and job performance","D":"To advertise other company vacancies to rival businesses"},"correctOption":"C","correctAnswer":"To obtain independent confirmation of an applicant's past reliability, character, and job performance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because references allow the prospective employer to verify claims on a CV and assess past attendance, honesty, and work quality.","distractor_reasons":{"A":"Incorrect because physical or cognitive abilities are assessed through selection tests, not references.","B":"Incorrect because a contract of employment is still legally required after selection.","C":"Correct selection.","D":"Incorrect because references are confidential checks on the candidate rather than job adverts."}}},{"id":"P1_U2_MCQ_709","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_709","question":"What is the main purpose of using an assessment centre when selecting employees?","options":{"A":"To reduce recruitment expenses to zero when hiring seasonal workers","B":"To eliminate the need to prepare a job description or person specification","C":"To evaluate candidates' teamwork, problem-solving, and leadership skills across realistic tasks","D":"To orient newly hired employees on company fire exits and payroll rules"},"correctOption":"C","correctAnswer":"To evaluate candidates' teamwork, problem-solving, and leadership skills across realistic tasks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because assessment centres use group exercises, role-plays, presentations, and tests to observe multiple competencies objectively.","distractor_reasons":{"A":"Incorrect because assessment centres are expensive and typically used for management or graduate roles rather than seasonal labour.","B":"Incorrect because assessment exercises are designed directly from the job description and person specification.","C":"Correct selection.","D":"Incorrect because introducing new hires to workplace rules and safety is induction training."}}},{"id":"P1_U2_MCQ_710","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_710","question":"Which set of details is typically included as core contents of an employment contract?","options":{"A":"Duties and responsibilities, working hours, holiday entitlement, and sick pay","B":"Company annual profit forecasts, dividend policy, and competitor pricing","C":"Shortlisting scores, interview notes, and rejected applicants' CVs","D":"Customer marketing strategy, brand logo guidelines, and supplier discounts"},"correctOption":"A","correctAnswer":"Duties and responsibilities, working hours, holiday entitlement, and sick pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an employment contract legally records the employee's duties, working hours, pay, holiday entitlement, and sick pay arrangements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because financial forecasts and dividend policies belong in business plans or annual reports.","C":"Incorrect because selection records are internal HR files, not employment contract terms.","D":"Incorrect because marketing and supplier details are operational plans rather than employment terms."}}},{"id":"P1_U2_MCQ_711","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_711","question":"How does a written contract of employment benefit an employer?","options":{"A":"It allows the employer to reduce agreed hourly wages unilaterally without employee consent","B":"It exempts the employer from complying with health and safety legislation","C":"It prevents employees from ever resigning from the business","D":"It clearly defines expected duties, hours, and notice rules, reducing misunderstandings and legal disputes"},"correctOption":"D","correctAnswer":"It clearly defines expected duties, hours, and notice rules, reducing misunderstandings and legal disputes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a written employment contract establishes unambiguous legal obligations for both parties, protecting the employer in disputes.","distractor_reasons":{"A":"Incorrect because a binding contract prevents unilateral pay cuts without mutual agreement.","B":"Incorrect because statutory health and safety laws apply regardless of contract wording.","C":"Incorrect because employees may resign by giving their agreed contractual notice period.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_712","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_712","question":"What is meant by the legal term 'unfair dismissal'?","options":{"A":"Ending a worker's job because falling demand or automation means the role no longer exists","B":"Terminating an employee's contract without a valid legal reason or without following proper disciplinary procedures","C":"Refusing to hire an applicant who lacks the essential qualifications on the person specification","D":"Reducing workforce headcount gradually by not replacing staff who retire voluntarily"},"correctOption":"B","correctAnswer":"Terminating an employee's contract without a valid legal reason or without following proper disciplinary procedures","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unfair dismissal occurs when an employee is sacked for an unlawful reason (such as union membership or pregnancy) or without fair warnings and hearings.","distractor_reasons":{"A":"Incorrect because ending a job when the role disappears due to falling demand or automation is redundancy.","B":"Correct selection.","C":"Incorrect because rejecting unqualified applicants is fair and standard selection practice.","D":"Incorrect because not replacing retiring staff is natural wastage, not dismissal."}}},{"id":"P1_U2_MCQ_713","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_713","question":"What is a legal requirement placed on employers under health and safety at work legislation?","options":{"A":"To guarantee every employee an annual promotion and performance bonus","B":"To pay all staff at least double the national minimum wage","C":"To consult trade unions before setting retail product prices","D":"To provide safe machinery, protective equipment, safety training, and hygienic working conditions"},"correctOption":"D","correctAnswer":"To provide safe machinery, protective equipment, safety training, and hygienic working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because health and safety laws obligate employers to protect workers from physical hazards through safe equipment, training, and protective gear.","distractor_reasons":{"A":"Incorrect because promotions and bonuses are discretionary management decisions, not safety laws.","B":"Incorrect because minimum wage laws require paying at least the statutory floor, not double.","C":"Incorrect because product pricing is set by management rather than trade unions.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_714","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_714","question":"What is meant by the 'chain of command' in an organisation?","options":{"A":"The total number of subordinates who report directly to a single manager","B":"The formal structure through which instructions and orders are passed down from top management to lower levels","C":"The informal network of social friendships and rumours among employees","D":"The process of removing middle-management tiers to create a flatter hierarchy"},"correctOption":"B","correctAnswer":"The formal structure through which instructions and orders are passed down from top management to lower levels","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the chain of command is the vertical line of authority along which decisions and instructions flow downward and accountability flows upward.","distractor_reasons":{"A":"Incorrect because the number of direct subordinates reporting to one manager is the span of control.","B":"Correct selection.","C":"Incorrect because informal employee rumours represent the grapevine rather than the formal chain of command.","D":"Incorrect because removing management tiers is called delayering."}}},{"id":"P1_U2_MCQ_715","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_715","question":"What does the term 'span of control' refer to in business organisation?","options":{"A":"The total number of hierarchical tiers between the Chief Executive and shop-floor workers","B":"The geographical distance between a company's head office and its branch stores","C":"The number of subordinates reporting directly to a specific manager or supervisor","D":"The maximum working hours permitted under an employment contract"},"correctOption":"C","correctAnswer":"The number of subordinates reporting directly to a specific manager or supervisor","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because span of control measures how many direct reports a manager supervises.","distractor_reasons":{"A":"Incorrect because the number of tiers describes levels of hierarchy and the chain of command.","B":"Incorrect because span of control measures direct reporting relationships rather than physical distance.","C":"Correct selection.","D":"Incorrect because working hours are governed by employment contracts and labour laws."}}},{"id":"P1_U2_MCQ_716","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_716","question":"Which structural features typically characterize a 'tall' hierarchical organisation?","options":{"A":"Many levels of hierarchy, a long chain of command, and narrow spans of control","B":"Very few levels of hierarchy, a short chain of command, and wide spans of control","C":"Complete absence of formal authority lines or departmental managers","D":"Equal decision-making voting power for every junior trainee on strategic budgets"},"correctOption":"A","correctAnswer":"Many levels of hierarchy, a long chain of command, and narrow spans of control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tall structures contain numerous management layers, resulting in long vertical chains of command and narrow spans of control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because few hierarchy levels and wide spans of control describe a flat organisational structure.","C":"Incorrect because tall structures have strictly defined formal lines of authority.","D":"Incorrect because tall hierarchies concentrate strategic authority at upper management levels."}}},{"id":"P1_U2_MCQ_717","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_717","question":"What is a major advantage of a 'flat' organisational structure compared with a tall structure?","options":{"A":"Communication between senior managers and frontline workers is faster and less likely to be distorted","B":"Managers have very narrow spans of control and closely supervise only two or three staff","C":"Employees have many intermediate supervisory promotion steps within the hierarchy","D":"Senior executives are completely insulated from operational problems"},"correctOption":"A","correctAnswer":"Communication between senior managers and frontline workers is faster and less likely to be distorted","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fewer management layers shorten the chain of command, speeding up communication and reducing message distortion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flat structures have wide spans of control, not narrow ones.","C":"Incorrect because fewer tiers mean fewer intermediate promotion steps.","D":"Incorrect because shorter chains bring senior managers closer to frontline operations."}}},{"id":"P1_U2_MCQ_718","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_718","question":"Which of the following correctly lists the four main functional areas of a business?","options":{"A":"Primary, secondary, tertiary, and public sectors","B":"Autocratic, democratic, laissez-faire, and paternalistic","C":"Maslow, Taylor, Herzberg, and Fayol","D":"Operations, marketing, finance, and human resources"},"correctOption":"D","correctAnswer":"Operations, marketing, finance, and human resources","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses typically divide specialist tasks across four core functional departments: operations, marketing, finance, and human resources.","distractor_reasons":{"A":"Incorrect because primary, secondary, and tertiary classify economic sectors of industry.","B":"Incorrect because autocratic, democratic, and laissez-faire are leadership styles.","C":"Incorrect because Maslow, Taylor, and Herzberg are motivation theorists.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_719","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_719","question":"What is an advantage to a business of offering flexible working arrangements such as home working?","options":{"A":"It eliminates the need to communicate with employees or monitor work output","B":"It reduces office space and utility overheads while widening the geographic pool of recruits","C":"It legally exempts the employer from paying statutory minimum wages or sick pay","D":"It guarantees stronger informal team bonding across every department"},"correctOption":"B","correctAnswer":"It reduces office space and utility overheads while widening the geographic pool of recruits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because home working lowers premises costs and enables the business to recruit skilled staff who live far from the office.","distractor_reasons":{"A":"Incorrect because remote staff still require regular communication and performance monitoring.","B":"Correct selection.","C":"Incorrect because employment laws apply equally to home-based and office-based employees.","D":"Incorrect because physical separation can actually make team cohesion harder to maintain."}}},{"id":"P1_U2_MCQ_720","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_720","question":"What is a primary advantage to a business of employing part-time employees?","options":{"A":"Training costs per hour worked are significantly lower than for full-time workers","B":"Part-time staff always demonstrate higher long-term commitment than full-time staff","C":"Staffing hours can be scheduled flexibly to cover peak trading periods without paying idle full-time wages","D":"Communication across staggered part-time shifts is simpler than when all staff work full days"},"correctOption":"C","correctAnswer":"Staffing hours can be scheduled flexibly to cover peak trading periods without paying idle full-time wages","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because part-time contracts allow managers to match labour hours closely to busy demand periods and control wage bills during quiet hours.","distractor_reasons":{"A":"Incorrect because fixed induction and training costs are spread over fewer weekly hours, making cost per hour higher.","B":"Incorrect because part-time workers often have higher turnover and lower organizational commitment.","C":"Correct selection.","D":"Incorrect because split shifts often make team communication more difficult."}}},{"id":"P1_U2_MCQ_721","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_721","question":"What is a disadvantage of employing full-time employees compared with part-time employees?","options":{"A":"Full-time staff lack familiarity with business procedures and customers","B":"Training investment per hour worked is higher for full-time staff","C":"Full-time contracts carry higher fixed weekly wage commitments that cannot easily be cut during quiet periods","D":"Full-time staff are less likely to seek career progression or training"},"correctOption":"C","correctAnswer":"Full-time contracts carry higher fixed weekly wage commitments that cannot easily be cut during quiet periods","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because full-time employees are contracted for full working weeks, reducing scheduling flexibility when demand fluctuates.","distractor_reasons":{"A":"Incorrect because full-time staff build deeper product and customer familiarity.","B":"Incorrect because training costs are spread over more hours, lowering cost per hour worked.","C":"Correct selection.","D":"Incorrect because full-time staff typically seek career advancement and training."}}},{"id":"P1_U2_MCQ_722","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_722","question":"Which core management function involves arranging resources, allocating tasks to departments, and delegating authority so plans can be carried out?","options":{"A":"Controlling","B":"Organising","C":"Dismissing","D":"Appraising"},"correctOption":"B","correctAnswer":"Organising","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because organising structures people, equipment, and budgets into coordinated roles to execute business plans.","distractor_reasons":{"A":"Incorrect because controlling monitors actual outcomes against targets after operations begin.","B":"Correct selection.","C":"Incorrect because dismissing refers to terminating an employee's contract.","D":"Incorrect because appraising evaluates an individual employee's performance."}}},{"id":"P1_U2_MCQ_723","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_723","question":"Which management function involves measuring actual business performance against set targets and taking corrective action when deviations occur?","options":{"A":"Planning","B":"Commanding","C":"Coordinating","D":"Controlling"},"correctOption":"D","correctAnswer":"Controlling","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because controlling checks whether objectives are being met and intervenes to fix underperformance.","distractor_reasons":{"A":"Incorrect because planning sets future goals and strategies before operations start.","B":"Incorrect because commanding involves instructing and guiding staff in daily duties.","C":"Incorrect because coordinating aligns activities across different teams and departments.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_724","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_724","question":"What is meant by 'delegation' in management?","options":{"A":"Giving a subordinate the authority to perform a task while the manager retains ultimate accountability","B":"Transferring all legal responsibility for mistakes to a junior employee without oversight","C":"Removing entire layers of middle management from the organisational hierarchy","D":"Making all strategic and operational decisions unilaterally without consulting staff"},"correctOption":"A","correctAnswer":"Giving a subordinate the authority to perform a task while the manager retains ultimate accountability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegation passes task authority downward to build subordinate skills and free up manager time, while ultimate accountability remains with the manager.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because abandoning accountability without guidance is abdication, not effective delegation.","C":"Incorrect because removing management tiers is delayering.","D":"Incorrect because unilateral decision-making without employee involvement is autocratic leadership."}}},{"id":"P1_U2_MCQ_725","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_725","question":"In which situation is an 'autocratic' leadership style most appropriate?","options":{"A":"When managing highly skilled research scientists developing creative new medicines","B":"During an urgent workplace safety emergency requiring immediate, decisive action","C":"When brainstorming innovative marketing campaign ideas with experienced designers","D":"When seeking to maximize employee autonomy and job enrichment"},"correctOption":"B","correctAnswer":"During an urgent workplace safety emergency requiring immediate, decisive action","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because autocratic leadership enables fast, clear top-down commands when crises leave no time for group consultation.","distractor_reasons":{"A":"Incorrect because skilled researchers thrive under democratic or laissez-faire styles.","B":"Correct selection.","C":"Incorrect because creative brainstorming benefits from democratic participation.","D":"Incorrect because autocratic leadership restricts worker autonomy rather than expanding it."}}},{"id":"P1_U2_MCQ_726","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_726","question":"When is communication considered 'effective' in a business?","options":{"A":"When a message is sent accurately, received, understood by the receiver, and confirmed through feedback","B":"Whenever a manager sends a high volume of emails to every employee each day","C":"When instructions are passed through as many hierarchical layers as possible","D":"Whenever one-way posters are displayed without checking whether staff read them"},"correctOption":"A","correctAnswer":"When a message is sent accurately, received, understood by the receiver, and confirmed through feedback","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective communication requires accurate transmission, comprehension by the receiver, and feedback confirming understanding.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because excessive emails often cause information overload rather than effective communication.","C":"Incorrect because long chains of command increase message distortion.","D":"Incorrect because without feedback, the sender cannot confirm the message was understood."}}},{"id":"P1_U2_MCQ_727","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_727","question":"What is the essential role of 'feedback' in the communication process?","options":{"A":"It prevents the receiver from asking questions about unclear instructions","B":"It converts every spoken conversation into a legally binding contract","C":"It confirms to the sender that the message has been received and understood as intended","D":"It eliminates the need to choose an appropriate communication medium"},"correctOption":"C","correctAnswer":"It confirms to the sender that the message has been received and understood as intended","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because feedback closes the communication loop by verifying that the receiver decoded the message accurately.","distractor_reasons":{"A":"Incorrect because feedback encourages clarification and questions.","B":"Incorrect because feedback confirms comprehension rather than creating legal contracts.","C":"Correct selection.","D":"Incorrect because selecting a suitable medium remains vital for clear transmission."}}},{"id":"P1_U2_MCQ_728","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_728","question":"How does 'external communication' differ from 'internal communication'?","options":{"A":"External communication uses only written letters, whereas internal communication is always spoken","B":"External communication occurs only via social media, whereas internal communication uses noticeboards","C":"External communication is always one-way, whereas internal communication is always two-way","D":"External communication occurs between the business and outside stakeholders, whereas internal communication takes place within the same organisation"},"correctOption":"D","correctAnswer":"External communication occurs between the business and outside stakeholders, whereas internal communication takes place within the same organisation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because internal communication connects employees and departments inside the firm, while external communication links the business with customers, suppliers, lenders, and the public.","distractor_reasons":{"A":"Incorrect because both internal and external communication use written, verbal, and digital media.","B":"Incorrect because external communication also includes emails, phone calls, letters, and meetings.","C":"Incorrect because external communication (such as customer service calls) is frequently two-way.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_729","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_729","question":"What distinguishes 'two-way communication' from 'one-way communication'?","options":{"A":"Two-way communication takes place only between two people, whereas one-way involves groups","B":"Two-way communication never uses electronic devices such as email or phone calls","C":"Two-way communication is always faster than posting a one-way safety notice","D":"Two-way communication enables the receiver to respond and provide feedback to the sender"},"correctOption":"D","correctAnswer":"Two-way communication enables the receiver to respond and provide feedback to the sender","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because two-way communication establishes an interactive dialogue where the receiver replies, whereas one-way communication involves no response.","distractor_reasons":{"A":"Incorrect because two-way communication can occur in large team meetings or forums.","B":"Incorrect because phone calls, emails, and virtual meetings are common two-way digital channels.","C":"Incorrect because two-way discussion often takes more time than issuing a one-way directive.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_730","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_730","question":"What is a major advantage of face-to-face meetings as a method of communication?","options":{"A":"They automatically produce a permanent, word-for-word legal record without note-taking","B":"They require zero travel time or cost when participants work in different countries","C":"They allow immediate two-way feedback and observation of body language and tone","D":"They guarantee that every participant remembers all numerical figures weeks later"},"correctOption":"C","correctAnswer":"They allow immediate two-way feedback and observation of body language and tone","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because face-to-face meetings enable instant clarification, rapport-building, and non-verbal cues such as facial expressions.","distractor_reasons":{"A":"Incorrect because spoken meetings leave no automatic permanent record unless minutes are written.","B":"Incorrect because physical meetings across distant sites incur travel costs and time.","C":"Correct selection.","D":"Incorrect because verbal details can be forgotten unless backed up in writing."}}},{"id":"P1_U2_MCQ_731","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_731","question":"What is a primary advantage of virtual meetings (video conferencing) for a business?","options":{"A":"They save travel expenses and time while allowing real-time visual and spoken interaction across locations","B":"They function reliably even during complete internet and power outages","C":"They eliminate all time-zone differences between international branches","D":"They guarantee zero technical glitches during live presentations"},"correctOption":"A","correctAnswer":"They save travel expenses and time while allowing real-time visual and spoken interaction across locations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because virtual meetings connect distant participants rapidly without airfare or hotel costs while preserving visual cues.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because virtual meetings depend on electricity and stable internet connectivity.","C":"Incorrect because international time zones still exist and require scheduling coordination.","D":"Incorrect because audio or network glitches remain a potential drawback."}}},{"id":"P1_U2_MCQ_732","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_732","question":"Which of the following is a key advantage of using email in business communication?","options":{"A":"It conveys empathetic vocal tone and facial expressions for sensitive disciplinary news","B":"It transmits detailed written information rapidly to multiple recipients and creates a permanent record","C":"It prevents receivers from ever experiencing information overload","D":"It is the most effective way to warn workers of an immediate physical fire hazard"},"correctOption":"B","correctAnswer":"It transmits detailed written information rapidly to multiple recipients and creates a permanent record","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because email is fast, low-cost, supports attachments, and stores an automatic written record.","distractor_reasons":{"A":"Incorrect because emails lack non-verbal tone and empathy, making them unsuitable for sensitive news.","B":"Correct selection.","C":"Incorrect because high email volume frequently causes information overload.","D":"Incorrect because alarms and verbal shouts warn of immediate hazards much faster than email."}}},{"id":"P1_U2_MCQ_733","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_733","question":"What is a disadvantage of using text messages (SMS) for formal business communication?","options":{"A":"Character limits restrict detailed explanations and the medium can appear overly informal","B":"Text messages take several days to reach recipients on mobile phones","C":"Text messages cannot be read by employees working away from a desk","D":"Sending text messages costs more than mailing individual registered letters"},"correctOption":"A","correctAnswer":"Character limits restrict detailed explanations and the medium can appear overly informal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because text messages are best suited for brief alerts or reminders rather than complex, formal policy documents.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because SMS messages deliver almost instantaneously.","C":"Incorrect because mobile accessibility is a key strength of text messaging.","D":"Incorrect because text messages are inexpensive compared to postal mail."}}},{"id":"P1_U2_MCQ_734","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_734","question":"How does using social media benefit a business's external communication?","options":{"A":"It keeps all brand announcements completely hidden from competitors","B":"It reaches a wide audience rapidly at low cost and allows interactive customer feedback","C":"It eliminates the need to monitor public comments or manage reputation","D":"It replaces the legal requirement to publish audited annual accounts"},"correctOption":"B","correctAnswer":"It reaches a wide audience rapidly at low cost and allows interactive customer feedback","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social media enables fast, broad customer outreach and direct two-way engagement.","distractor_reasons":{"A":"Incorrect because public social media posts are visible to competitors as well as customers.","B":"Correct selection.","C":"Incorrect because negative public posts can spread quickly and require active moderation.","D":"Incorrect because companies must still meet statutory financial reporting obligations."}}},{"id":"P1_U2_MCQ_735","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_735","question":"What is a primary advantage of using posters and noticeboards for internal workplace communication?","options":{"A":"They guarantee immediate two-way feedback from every employee","B":"They allow confidential salary details to be shared privately with individuals","C":"They are inexpensive and provide continuous visual reminders in shared staff areas","D":"They reach remote employees working from home instantaneously"},"correctOption":"C","correctAnswer":"They are inexpensive and provide continuous visual reminders in shared staff areas","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because posters and noticeboards are low-cost and ideal for ongoing safety rules or general announcements in communal areas.","distractor_reasons":{"A":"Incorrect because posters and noticeboards are one-way communication channels.","B":"Incorrect because public noticeboards lack privacy for confidential information.","C":"Correct selection.","D":"Incorrect because physical noticeboards are visible only to staff on-site."}}},{"id":"P1_U2_MCQ_736","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_736","question":"Which of the following is an example of a communication barrier caused by the choice of medium?","options":{"A":"A manager uses clear diagrams to explain safety steps to multilingual workers","B":"A supervisor holds a private meeting to discuss a sensitive personal grievance","C":"Complex technical specifications are given verbally over a noisy phone line instead of in writing","D":"An HR officer sends an email confirming the time and date of an upcoming interview"},"correctOption":"C","correctAnswer":"Complex technical specifications are given verbally over a noisy phone line instead of in writing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because complex detailed data requires a permanent written medium rather than an easily misheard verbal phone call.","distractor_reasons":{"A":"Incorrect because visual diagrams overcome language barriers effectively.","B":"Incorrect because a private face-to-face meeting is the ideal medium for sensitive grievances.","C":"Correct selection.","D":"Incorrect because email is well suited for confirming interview logistics."}}},{"id":"P1_U2_MCQ_737","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_737","question":"Why does a long chain of command act as a barrier to effective internal communication?","options":{"A":"Messages passing through many management tiers take longer and risk being distorted or filtered","B":"Managers have spans of control that are too wide to supervise staff","C":"Employees receive too much direct feedback from the Chief Executive","D":"Written policies cannot be stored on company computers"},"correctOption":"A","correctAnswer":"Messages passing through many management tiers take longer and risk being distorted or filtered","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each intermediate layer in a tall hierarchy slows transmission and increases the likelihood of altered details.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tall hierarchies with long chains of command feature narrow spans of control.","C":"Incorrect because long chains reduce direct contact between top executives and frontline staff.","D":"Incorrect because digital storage is unrelated to hierarchy length."}}},{"id":"P1_U2_MCQ_738","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_738","question":"How can a sender best overcome communication barriers caused by technical jargon?","options":{"A":"Send the same jargon-filled report twice via two different email accounts","B":"Use clear, plain language tailored to the receiver's level of technical knowledge","C":"Increase the number of management layers reviewing the message","D":"Eliminate all two-way feedback opportunities for receivers"},"correctOption":"B","correctAnswer":"Use clear, plain language tailored to the receiver's level of technical knowledge","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because avoiding specialist acronyms and encoding messages in simple, familiar terms ensures receivers decode the meaning accurately.","distractor_reasons":{"A":"Incorrect because repeating unclear terminology does not improve comprehension.","B":"Correct selection.","C":"Incorrect because adding hierarchy tiers increases distortion.","D":"Incorrect because feedback helps identify and clear up remaining confusion."}}},{"id":"P1_U2_MCQ_739","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_739","question":"What is meant by 'motivation' in a business context?","options":{"A":"The legal minimum hourly wage set by the government","B":"The reason why employees want to work hard and work effectively for the business","C":"The formal line of authority shown on an organisational chart","D":"The process of reducing workforce size when demand declines"},"correctOption":"B","correctAnswer":"The reason why employees want to work hard and work effectively for the business","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because motivation refers to the internal and external factors that stimulate employees' desire and commitment to perform well.","distractor_reasons":{"A":"Incorrect because the statutory pay floor is the legal minimum wage.","B":"Correct selection.","C":"Incorrect because the formal line of authority is the chain of command.","D":"Incorrect because reducing workforce size is downsizing or redundancy."}}},{"id":"P1_U2_MCQ_740","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_740","question":"Which of the following is a direct benefit to a business of having a well-motivated workforce?","options":{"A":"Higher labour productivity, reduced absenteeism, and lower labour turnover","B":"Higher annual recruitment advertising costs and frequent industrial disputes","C":"Increased resistance to new technology and workplace changes","D":"Higher product defect rates and greater raw-material wastage"},"correctOption":"A","correctAnswer":"Higher labour productivity, reduced absenteeism, and lower labour turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because motivated employees work more efficiently, take fewer sick days, stay longer with the firm, and accept change more willingly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower labour turnover reduces recruitment costs and industrial relations improve.","C":"Incorrect because motivated staff show greater willingness to accept new working methods.","D":"Incorrect because motivated workers take greater pride in quality and make fewer mistakes."}}},{"id":"P1_U2_MCQ_741","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_741","question":"Which motivational theorist proposed that workers are motivated primarily by money and should be paid according to output produced?","options":{"A":"Abraham Maslow","B":"F.W. Taylor","C":"Frederick Herzberg","D":"Henri Fayol"},"correctOption":"B","correctAnswer":"F.W. Taylor","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because F.W. Taylor's scientific management argued that financial rewards linked directly to output (such as piece-rate) are the main motivator.","distractor_reasons":{"A":"Incorrect because Maslow proposed a five-level hierarchy of human needs.","B":"Correct selection.","C":"Incorrect because Herzberg classified pay as a hygiene factor rather than a primary motivator.","D":"Incorrect because Fayol defined the core functions of management."}}},{"id":"P1_U2_MCQ_742","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_742","question":"What is a major limitation of F.W. Taylor's motivation theory in modern workplaces?","options":{"A":"It focuses entirely on teamworking and social belonging while ignoring pay","B":"It requires every employee to hold a university management degree","C":"It ignores non-financial motivators and is difficult to apply where output cannot be measured per unit","D":"It prohibits businesses from using division of labour or specialized tools"},"correctOption":"C","correctAnswer":"It ignores non-financial motivators and is difficult to apply where output cannot be measured per unit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Taylorism overlooks psychological needs like job satisfaction and fails in service or creative roles where unit output cannot be counted.","distractor_reasons":{"A":"Incorrect because Taylor emphasized individual financial incentives rather than social teamwork.","B":"Incorrect because Taylor broke jobs into simple, low-skill repetitive tasks.","C":"Correct selection.","D":"Incorrect because Taylor actively promoted task specialization and standardized tools."}}},{"id":"P1_U2_MCQ_743","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_743","question":"In Abraham Maslow's hierarchy of needs, which level sits at the base of the pyramid and requires wages sufficient for food, shelter, and basic survival?","options":{"A":"Physiological needs","B":"Esteem needs","C":"Social needs","D":"Self-actualization needs"},"correctOption":"A","correctAnswer":"Physiological needs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because physiological needs are the foundational survival requirements that must be met first before higher needs motivate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because esteem needs sit near the top of the pyramid and involve status and recognition.","C":"Incorrect because social needs occupy the middle tier and involve friendship and belonging.","D":"Incorrect because self-actualization sits at the very top of Maslow's pyramid."}}},{"id":"P1_U2_MCQ_744","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_744","question":"According to Abraham Maslow's hierarchy of needs, which workplace factor satisfies an employee's 'esteem needs'?","options":{"A":"Basic wages sufficient to buy food and pay rent","B":"Permanent employment contracts and protective safety equipment","C":"Friendly teamwork and social interaction with colleagues","D":"Public recognition, promotion to a senior job title, and respect from others"},"correctOption":"D","correctAnswer":"Public recognition, promotion to a senior job title, and respect from others","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because esteem needs reflect the desire for recognition, status, achievement, and respect within the organisation.","distractor_reasons":{"A":"Incorrect because basic survival wages satisfy physiological needs.","B":"Incorrect because job security and safety gear satisfy safety needs.","C":"Incorrect because workplace friendships satisfy social needs.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_745","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_745","question":"In Frederick Herzberg's two-factor theory, what is the role of 'hygiene factors' such as pay, working conditions, and company policies?","options":{"A":"They actively inspire employees to achieve maximum creativity and effort","B":"They satisfy self-actualization needs at the top of the needs pyramid","C":"They eliminate the need for any supervision or management control","D":"They prevent job dissatisfaction when adequate, but do not on their own motivate higher effort"},"correctOption":"D","correctAnswer":"They prevent job dissatisfaction when adequate, but do not on their own motivate higher effort","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Herzberg showed that poor hygiene factors cause dissatisfaction, whereas improving them merely creates a neutral baseline rather than active motivation.","distractor_reasons":{"A":"Incorrect because true motivators—such as achievement and responsibility—inspire higher effort.","B":"Incorrect because self-actualization belongs to Maslow's hierarchy of needs.","C":"Incorrect because supervision itself is classified by Herzberg as a hygiene factor.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_746","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_746","question":"According to Frederick Herzberg's two-factor theory, which of the following is classified as a 'motivator'?","options":{"A":"Responsibility, personal achievement, and opportunities for advancement","B":"Basic hourly pay and physical office lighting","C":"Company administrative rules and quality of supervision","D":"Job security and friendly relationships with peers"},"correctOption":"A","correctAnswer":"Responsibility, personal achievement, and opportunities for advancement","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg identified intrinsic factors tied to the work itself—achievement, recognition, responsibility, and advancement—as motivators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pay and physical working conditions are extrinsic hygiene factors.","C":"Incorrect because administrative policies and supervision are hygiene factors.","D":"Incorrect because job security and interpersonal relations are hygiene factors."}}},{"id":"P1_U2_MCQ_747","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_747","question":"What is an advantage of paying employees using a 'time-based' wage rate?","options":{"A":"Workers have a strong financial incentive to maximize output speed at all times","B":"Total labour costs automatically fall to zero when production slows down","C":"It is simple to calculate and suits jobs where quality and care matter more than speed","D":"Workers are guaranteed higher pay than under any performance-related system"},"correctOption":"C","correctAnswer":"It is simple to calculate and suits jobs where quality and care matter more than speed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because time-rate wages are easy to administer and remove pressure to rush work, protecting quality in roles where output cannot be measured per unit.","distractor_reasons":{"A":"Incorrect because paying per hour does not directly reward faster output without supervision.","B":"Incorrect because time-based wages must be paid for all hours worked regardless of output volume.","C":"Correct selection.","D":"Incorrect because fast workers often earn more under piece-rate or commission schemes."}}},{"id":"P1_U2_MCQ_748","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_748","question":"What is a common disadvantage of using 'piece-rate' pay as a financial motivator?","options":{"A":"Workers receive identical weekly pay whether they produce ten units or one hundred units","B":"Product quality may fall if workers rush production to maximize unit count, requiring strict inspection","C":"Employers face high fixed wage bills even when zero units are produced","D":"Fast workers feel demotivated because their extra effort is unrewarded"},"correctOption":"B","correctAnswer":"Product quality may fall if workers rush production to maximize unit count, requiring strict inspection","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because piece-rate rewards quantity produced, which can tempt employees to sacrifice craftsmanship for speed.","distractor_reasons":{"A":"Incorrect because piece-rate earnings vary directly with the number of units completed.","B":"Correct selection.","C":"Incorrect because piece-rate is a variable labour cost tied directly to output.","D":"Incorrect because fast workers earn higher wages under piece-rate."}}},{"id":"P1_U2_MCQ_749","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_749","question":"What is meant by 'job enrichment' as a non-financial method of motivation?","options":{"A":"Adding higher-level tasks requiring greater skill, responsibility, and decision-making authority to a role","B":"Moving employees periodically between different routine tasks of the same skill level","C":"Paying employees a lump-sum cash bonus at the end of a profitable financial year","D":"Offering non-cash perks such as private health insurance and subsidized meals"},"correctOption":"A","correctAnswer":"Adding higher-level tasks requiring greater skill, responsibility, and decision-making authority to a role","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enrichment upgrades a job vertically with more challenging, meaningful responsibilities and autonomy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because switching between peer-level tasks is job rotation.","C":"Incorrect because a lump-sum payout is a financial bonus or profit-sharing scheme.","D":"Incorrect because non-cash perks are fringe benefits."}}},{"id":"P1_U2_MCQ_750","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_750","question":"How does 'job rotation' benefit a business and its employees?","options":{"A":"It gives shop-floor workers executive authority over corporate budgets","B":"It guarantees every worker an automatic annual salary promotion","C":"It reduces boredom from repetitive tasks and builds a multi-skilled workforce able to cover absences","D":"It eliminates the need to provide any initial training on different machines"},"correctOption":"C","correctAnswer":"It reduces boredom from repetitive tasks and builds a multi-skilled workforce able to cover absences","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rotating employees across different tasks relieves monotony and ensures colleagues can cover for one another during absences.","distractor_reasons":{"A":"Incorrect because job rotation moves workers across tasks of similar skill level without granting budget authority.","B":"Incorrect because task rotation does not guarantee promotion or higher pay.","C":"Correct selection.","D":"Incorrect because workers must still be trained safely on each station they rotate into."}}},{"id":"P1_U2_MCQ_751","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_751","question":"What is the primary role of an employment agency in the recruitment process?","options":{"A":"To negotiate annual collective pay agreements on behalf of trade unions","B":"To conduct statutory government health and safety inspections in factories","C":"To write legally binding employment contracts for internal promotions","D":"To maintain a database of jobseekers, advertise vacancies, and shortlist candidates for employers"},"correctOption":"D","correctAnswer":"To maintain a database of jobseekers, advertise vacancies, and shortlist candidates for employers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employment agencies save businesses time by sourcing, screening, and matching suitable external candidates to vacancies.","distractor_reasons":{"A":"Incorrect because trade unions represent employees in collective bargaining.","B":"Incorrect because government inspectors enforce health and safety laws.","C":"Incorrect because employers issue contracts directly to hired staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_752","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_752","question":"What is a major advantage of online recruitment compared with advertising in printed newspapers?","options":{"A":"It guarantees that zero unsuitable candidates will apply for the vacancy","B":"It reaches a much wider audience quickly at lower cost and allows rapid digital application","C":"It eliminates the need to interview or check references for shortlisted applicants","D":"It works effectively when targeting jobseekers who have no internet access"},"correctOption":"B","correctAnswer":"It reaches a much wider audience quickly at lower cost and allows rapid digital application","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because online job boards and company websites advertise vacancies instantaneously to broad audiences at relatively low cost.","distractor_reasons":{"A":"Incorrect because online adverts often attract large volumes of applications, including unqualified ones.","B":"Correct selection.","C":"Incorrect because shortlisted online applicants still undergo interviews and reference checks.","D":"Incorrect because offline candidates cannot access digital job portals."}}},{"id":"P1_U2_MCQ_753","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_753","question":"Why do many employers require candidates to complete a standardized application form rather than submitting only a CV/resumé?","options":{"A":"Application forms legally replace the need for a post-hire contract of employment","B":"All applicants provide the same categories of information in a uniform layout, making fair comparison easier","C":"Application forms allow candidates to omit employment dates and qualifications freely","D":"Application forms automatically assess candidates' spoken communication skills"},"correctOption":"B","correctAnswer":"All applicants provide the same categories of information in a uniform layout, making fair comparison easier","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because standardized application forms ensure consistent data across all candidates, simplifying objective shortlisting.","distractor_reasons":{"A":"Incorrect because an application form is a pre-selection document, not a binding employment contract.","B":"Correct selection.","C":"Incorrect because structured forms require specific fields, making it harder to hide gaps than on a free-form CV.","D":"Incorrect because written forms cannot evaluate verbal speaking ability."}}},{"id":"P1_U2_MCQ_754","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_754","question":"What is the main purpose of conducting job interviews during the selection process?","options":{"A":"To avoid checking candidates' academic certificates or past employer references","B":"To identify whether a job vacancy exists before writing a job description","C":"To train newly hired employees on company machinery and safety rules","D":"To assess candidates' verbal communication, personality, and cultural fit alongside their skills"},"correctOption":"D","correctAnswer":"To assess candidates' verbal communication, personality, and cultural fit alongside their skills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because face-to-face or virtual interviews let selectors probe candidates' experience and evaluate interpersonal suitability.","distractor_reasons":{"A":"Incorrect because interviews complement rather than replace qualification and reference checks.","B":"Incorrect because job analysis occurs at the start of recruitment before advertising.","C":"Incorrect because training occurs after the candidate is selected and hired.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_755","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_755","question":"How can an increase in the statutory legal minimum wage affect employers?","options":{"A":"Employers can legally reduce holiday entitlement to offset higher hourly wage bills","B":"Total labour costs automatically fall because workers work fewer hours for free","C":"Wage costs rise for lower-paid workers, encouraging investment in training or technology to boost productivity","D":"Employers are exempted from following health and safety regulations"},"correctOption":"C","correctAnswer":"Wage costs rise for lower-paid workers, encouraging investment in training or technology to boost productivity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because higher minimum wage floors raise payroll costs, prompting firms to increase efficiency, train staff, or adjust prices.","distractor_reasons":{"A":"Incorrect because statutory holiday entitlements remain legally protected.","B":"Incorrect because staff must be paid for all hours worked at or above the new minimum rate.","C":"Correct selection.","D":"Incorrect because health and safety laws remain fully enforceable."}}},{"id":"P1_U2_MCQ_756","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_756","question":"What is the purpose of anti-discrimination legislation in employment?","options":{"A":"To prevent employers from treating applicants or staff unfairly based on gender, race, age, religion, or disability","B":"To force businesses to hire every applicant who submits an application form","C":"To allow employers to pay different wages for identical work based on personal preference","D":"To prohibit businesses from setting minimum educational qualifications in a person specification"},"correctOption":"A","correctAnswer":"To prevent employers from treating applicants or staff unfairly based on gender, race, age, religion, or disability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because anti-discrimination laws ensure equal opportunities in recruitment, pay, training, promotion, and dismissal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employers still select only the most suitable candidate(s) based on merit.","C":"Incorrect because anti-discrimination laws require equal pay for equal work.","D":"Incorrect because genuine job-related qualifications remain completely lawful."}}},{"id":"P1_U2_MCQ_757","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_757","question":"What is a primary benefit of a written contract of employment to an employee?","options":{"A":"It guarantees automatic annual pay increases regardless of company performance","B":"It exempts the employee from following workplace rules or notice periods","C":"It provides legal security and clarity regarding pay, working hours, holiday entitlement, and sick pay","D":"It allows the employee to choose their own working hours without manager approval"},"correctOption":"C","correctAnswer":"It provides legal security and clarity regarding pay, working hours, holiday entitlement, and sick pay","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an employment contract protects the employee's statutory and agreed rights in writing.","distractor_reasons":{"A":"Incorrect because pay rises depend on contract terms or negotiations rather than automatic guarantees.","B":"Incorrect because contracts bind employees to follow reasonable rules and give notice when leaving.","C":"Correct selection.","D":"Incorrect because contracted working hours are agreed between employer and employee."}}},{"id":"P1_U2_MCQ_758","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_758","question":"Why is investing in employee training important for a business?","options":{"A":"It allows the business to pay trained workers below the legal minimum wage","B":"It increases labour productivity, reduces waste and workplace accidents, and improves quality","C":"It guarantees that trained workers will never leave to join a competitor","D":"It eliminates the need for supervision or quality standards"},"correctOption":"B","correctAnswer":"It increases labour productivity, reduces waste and workplace accidents, and improves quality","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because skilled workers operate equipment more efficiently, make fewer errors, and deliver higher customer satisfaction.","distractor_reasons":{"A":"Incorrect because minimum wage laws apply regardless of training.","B":"Correct selection.","C":"Incorrect because newly skilled staff can actually become more attractive to rival employers.","D":"Incorrect because supervision and quality controls remain necessary."}}},{"id":"P1_U2_MCQ_759","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_759","question":"How does workplace training directly benefit individual employees?","options":{"A":"It increases their skills, confidence, workplace safety, and prospects for promotion and higher pay","B":"It removes their legal responsibility to follow health and safety procedures","C":"It guarantees that they will never be affected by economic redundancy","D":"It lowers their contracted holiday and sick-pay entitlements"},"correctOption":"A","correctAnswer":"It increases their skills, confidence, workplace safety, and prospects for promotion and higher pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring new skills boosts job satisfaction, reduces accident risks, and enhances career advancement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees must always follow safety rules.","C":"Incorrect because economic downturns can still cause redundancies despite training.","D":"Incorrect because training does not reduce statutory benefits."}}},{"id":"P1_U2_MCQ_760","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_760","question":"What is the purpose of 'induction training' for a new employee?","options":{"A":"To sponsor the employee for an external university degree away from work","B":"To familiarize the new recruit with the workplace, colleagues, company rules, and health and safety procedures","C":"To retrain departing employees before making them redundant","D":"To evaluate shortlisted applicants before offering them a contract"},"correctOption":"B","correctAnswer":"To familiarize the new recruit with the workplace, colleagues, company rules, and health and safety procedures","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because induction helps new hires settle in quickly, understand workplace routines and safety rules, and become productive sooner.","distractor_reasons":{"A":"Incorrect because external university study is off-the-job training.","B":"Correct selection.","C":"Incorrect because induction is provided at the start of employment, not upon exit.","D":"Incorrect because candidate evaluation occurs during selection before hiring."}}},{"id":"P1_U2_MCQ_761","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_761","question":"Which of the following is an advantage of 'on-the-job' training?","options":{"A":"Trainees learn in an external classroom free from workplace distractions","B":"Trainees never copy bad working habits from existing coworkers","C":"Experienced trainers experience zero slowdown in their own output while instructing","D":"It is relatively inexpensive, tailored to company equipment, and the trainee produces output while learning"},"correctOption":"D","correctAnswer":"It is relatively inexpensive, tailored to company equipment, and the trainee produces output while learning","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because on-the-job training avoids external course fees and teaches practical skills directly relevant to the workplace.","distractor_reasons":{"A":"Incorrect because learning away from workplace distractions is an advantage of off-the-job training.","B":"Incorrect because copying poor habits from coworkers is a drawback of on-the-job training.","C":"Incorrect because supervising a trainee temporarily reduces the mentor's own output.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_762","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_762","question":"What is a major disadvantage of 'off-the-job' training for an employer?","options":{"A":"Trainees cannot learn modern specialist skills that do not yet exist inside the firm","B":"High external course fees and lost employee output while the worker is away from the workplace","C":"Training is constantly interrupted by routine customer queries and machinery noise","D":"Off-the-job training cannot lead to recognized external qualifications"},"correctOption":"B","correctAnswer":"High external course fees and lost employee output while the worker is away from the workplace","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sending staff to external courses incurs tuition/travel expenses and temporarily removes productive workers from operations.","distractor_reasons":{"A":"Incorrect because bringing new specialist expertise into the firm is a key advantage of off-the-job training.","B":"Correct selection.","C":"Incorrect because off-the-job training occurs away from workplace interruptions.","D":"Incorrect because external courses frequently award accredited qualifications."}}},{"id":"P1_U2_MCQ_763","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_763","question":"What information can be directly identified from a simple organisational chart?","options":{"A":"Levels of hierarchy, formal lines of authority, spans of control, and functional departments","B":"The exact annual salary and bonus of each individual employee","C":"The leadership style (autocratic or democratic) practised by each manager","D":"The informal social friendships and grapevine networks among staff"},"correctOption":"A","correctAnswer":"Levels of hierarchy, formal lines of authority, spans of control, and functional departments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an organisational chart visually displays reporting lines, hierarchy levels, spans of control, and departmental divisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because salary figures are confidential HR data not shown on org charts.","C":"Incorrect because leadership style cannot be seen from structural boxes and lines.","D":"Incorrect because org charts map formal authority rather than informal social groups."}}},{"id":"P1_U2_MCQ_764","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_764","question":"Which factor allows a manager to effectively supervise a 'wide' span of control?","options":{"A":"Subordinates are newly hired trainees performing unfamiliar, high-risk tasks","B":"Every task is highly complex and requires constant one-to-one managerial approval","C":"The manager uses a strict autocratic style that forbids any delegation","D":"Tasks are routine and standardized, and subordinates are experienced and well trained"},"correctOption":"D","correctAnswer":"Tasks are routine and standardized, and subordinates are experienced and well trained","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because experienced workers performing standardized duties need minimal close supervision, enabling one manager to oversee many direct reports.","distractor_reasons":{"A":"Incorrect because untrained staff performing risky work require a narrow span of control.","B":"Incorrect because complex tasks needing close monitoring require a narrow span of control.","C":"Incorrect because avoiding delegation overloads a manager with a wide span.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_765","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_765","question":"What is meant by 'flexible hours' (flexitime) as a method of flexible working?","options":{"A":"Allowing employees to vary their start and finish times around agreed core working hours","B":"Employing workers strictly on 40-hour fixed shifts from Monday to Friday","C":"Permitting employees to skip work without notice whenever they choose","D":"Paying workers exclusively on a piece-rate basis per unit produced"},"correctOption":"A","correctAnswer":"Allowing employees to vary their start and finish times around agreed core working hours","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flexible hours give staff autonomy over when they begin and end their workday provided they complete contracted hours and core times.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed 40-hour schedules represent traditional rigid working hours.","C":"Incorrect because staff must still work their agreed total hours and attend core periods.","D":"Incorrect because piece-rate is a financial payment method rather than a scheduling arrangement."}}},{"id":"P1_U2_MCQ_766","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_766","question":"What is a common disadvantage of employing part-time employees for a business?","options":{"A":"The business cannot schedule extra staff during busy weekend or evening periods","B":"Part-time workers are legally excluded from minimum wage protection","C":"Recruitment and training costs per hour worked are higher, and communication across split shifts can be harder","D":"Part-time staff are forbidden from joining trade unions"},"correctOption":"C","correctAnswer":"Recruitment and training costs per hour worked are higher, and communication across split shifts can be harder","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because training two part-time staff costs more than training one full-time worker for the same hours, and staggered shifts complicate team briefings.","distractor_reasons":{"A":"Incorrect because covering peak demand periods is a major advantage of part-time staff.","B":"Incorrect because minimum wage laws cover part-time and full-time staff equally.","C":"Correct selection.","D":"Incorrect because part-time employees have the same statutory right to join trade unions."}}},{"id":"P1_U2_MCQ_767","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_767","question":"Which management function involves setting future objectives for the business and determining the resources needed to achieve them?","options":{"A":"Controlling","B":"Planning","C":"Commanding","D":"Coordinating"},"correctOption":"B","correctAnswer":"Planning","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because planning looks ahead to establish targets, strategies, and resource budgets.","distractor_reasons":{"A":"Incorrect because controlling evaluates actual performance against planned targets.","B":"Correct selection.","C":"Incorrect because commanding guides and directs staff during operations.","D":"Incorrect because coordinating integrates tasks across different departments."}}},{"id":"P1_U2_MCQ_768","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_768","question":"What is the role of the management function known as 'coordinating'?","options":{"A":"Dismissing employees who breach workplace disciplinary rules","B":"Calculating statutory redundancy payouts for surplus workers","C":"Advertising external job vacancies in trade journals","D":"Bringing together people and departments so their activities work smoothly toward shared goals"},"correctOption":"D","correctAnswer":"Bringing together people and departments so their activities work smoothly toward shared goals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because coordinating ensures different functional teams synchronize their schedules and avoid duplicating or conflicting efforts.","distractor_reasons":{"A":"Incorrect because disciplinary dismissal is an HR enforcement procedure.","B":"Incorrect because redundancy payouts relate to workforce downsizing.","C":"Incorrect because job advertising is part of recruitment.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_769","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_769","question":"Which management function focuses on guiding, leading, and instructing employees in their daily work to ensure tasks are carried out?","options":{"A":"Commanding","B":"Forecasting","C":"Auditing","D":"Downsizing"},"correctOption":"A","correctAnswer":"Commanding","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because commanding involves directing and motivating subordinates so operational plans are executed effectively.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because forecasting estimates future trends during planning.","C":"Incorrect because auditing checks financial records.","D":"Incorrect because downsizing reduces workforce size."}}},{"id":"P1_U2_MCQ_770","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_770","question":"What is a potential disadvantage of delegation for a manager?","options":{"A":"The manager gains more time to focus on strategic priorities","B":"Subordinates feel trusted and develop skills for future promotion","C":"Subordinates may make costly mistakes if poorly trained, while the manager remains accountable","D":"Operational decisions can be made faster by staff closer to customers"},"correctOption":"C","correctAnswer":"Subordinates may make costly mistakes if poorly trained, while the manager remains accountable","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delegating without adequate training or support risks errors for which the manager still bears ultimate responsibility.","distractor_reasons":{"A":"Incorrect because freeing up manager time is an advantage of delegation.","B":"Incorrect because motivating and upskilling subordinates is an advantage of delegation.","C":"Correct selection.","D":"Incorrect because faster frontline decision-making is an advantage of delegation."}}},{"id":"P1_U2_MCQ_771","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_771","question":"What is a primary disadvantage of a 'democratic' leadership style?","options":{"A":"Employees feel alienated because their views are completely ignored","B":"Decision-making takes longer because consulting employees and discussing ideas requires time","C":"Managers retain total centralized control over every minor operational detail","D":"Staff turnover increases sharply due to lack of employee participation"},"correctOption":"B","correctAnswer":"Decision-making takes longer because consulting employees and discussing ideas requires time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because involving workers in discussions and consultations slows down decision-making compared with autocratic leadership.","distractor_reasons":{"A":"Incorrect because democratic leadership actively encourages employee input.","B":"Correct selection.","C":"Incorrect because unilateral centralized control describes autocratic leadership.","D":"Incorrect because democratic participation typically improves morale and retention."}}},{"id":"P1_U2_MCQ_772","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_772","question":"Which statement accurately describes a 'laissez-faire' leadership style?","options":{"A":"The leader makes every decision alone and issues strict orders with close supervision","B":"The leader holds formal votes on every minor operational task","C":"The leader sets broad objectives and gives skilled employees high freedom to make their own decisions","D":"The leader eliminates all organisational goals and product quality standards"},"correctOption":"C","correctAnswer":"The leader sets broad objectives and gives skilled employees high freedom to make their own decisions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because laissez-faire leadership delegates extensive autonomy to experienced specialists, making it suitable for creative or research roles.","distractor_reasons":{"A":"Incorrect because issuing strict orders with close control describes autocratic leadership.","B":"Incorrect because group voting describes democratic leadership.","C":"Correct selection.","D":"Incorrect because broad strategic goals still guide the organisation."}}},{"id":"P1_U2_MCQ_773","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_773","question":"What is meant by 'downsizing' in business management?","options":{"A":"Permanently reducing the size of a business's workforce due to falling demand, automation, or the need to lower costs","B":"Moving employees periodically between different tasks of similar skill level","C":"Hiring part-time workers to cover temporary seasonal demand spikes","D":"Expanding into international markets through mergers and takeovers"},"correctOption":"A","correctAnswer":"Permanently reducing the size of a business's workforce due to falling demand, automation, or the need to lower costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because downsizing involves shrinking total headcount—often through redundancy or natural wastage—to cut expenses or adapt to technological change.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rotating workers between peer-level tasks is job rotation.","C":"Incorrect because hiring seasonal staff temporarily increases headcount.","D":"Incorrect because mergers and takeovers represent external business growth."}}},{"id":"P1_U2_MCQ_774","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_774","question":"How does 'redundancy' differ from 'dismissal'?","options":{"A":"Redundancy occurs due to employee theft, whereas dismissal occurs when a factory closes","B":"Redundancy occurs when the job role itself is no longer needed, whereas dismissal results from the employee's unsatisfactory conduct or performance","C":"Redundant workers receive no notice or compensation, whereas dismissed workers receive severance packages","D":"Redundancy is illegal under employment law, whereas summary dismissal is always lawful"},"correctOption":"B","correctAnswer":"Redundancy occurs when the job role itself is no longer needed, whereas dismissal results from the employee's unsatisfactory conduct or performance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because redundancy happens through no fault of the worker when the job disappears, while dismissal terminates an employee for misconduct or incompetence.","distractor_reasons":{"A":"Incorrect because theft causes dismissal, whereas factory closure causes redundancy.","B":"Correct selection.","C":"Incorrect because eligible redundant staff receive redundancy compensation, whereas gross misconduct forfeits severance pay.","D":"Incorrect because redundancy is lawful when fair procedures and compensation rules are followed."}}},{"id":"P1_U2_MCQ_775","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_775","question":"What is a primary benefit to an employee of being a member of a trade union?","options":{"A":"The union guarantees the employee lifetime employment even if the company goes bankrupt","B":"Union membership exempts the employee from obeying workplace health and safety rules","C":"The union provides collective bargaining strength for better pay and conditions, plus legal advice and representation","D":"The union pays the employee's full basic salary every month instead of the employer"},"correctOption":"C","correctAnswer":"The union provides collective bargaining strength for better pay and conditions, plus legal advice and representation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade unions negotiate collectively on behalf of members and support individuals during grievances or disciplinary hearings.","distractor_reasons":{"A":"Incorrect because unions cannot prevent job losses if an employer becomes insolvent.","B":"Incorrect because all workers remain legally bound by workplace safety laws.","C":"Correct selection.","D":"Incorrect because the employer pays wages, while union strike funds offer only limited temporary support during strikes."}}},{"id":"P1_U2_MCQ_776","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_776","question":"Why is effective communication important for the success of a business?","options":{"A":"It eliminates the need to recruit skilled managers or train employees","B":"It guarantees that competitors cannot enter the market","C":"It allows a business to avoid paying statutory minimum wages","D":"It reduces costly mistakes, speeds up decision-making, improves departmental coordination, and boosts morale"},"correctOption":"D","correctAnswer":"It reduces costly mistakes, speeds up decision-making, improves departmental coordination, and boosts morale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because clear internal and external communication ensures accurate execution of tasks, strong customer service, and motivated staff.","distractor_reasons":{"A":"Incorrect because capable managers and trained staff remain essential.","B":"Incorrect because internal communication does not block external competitors.","C":"Incorrect because minimum wage laws remain legally binding.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_777","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_777","question":"Which set correctly lists the five essential elements of the communication process?","options":{"A":"Transmitter (sender), message, medium, receiver, and feedback","B":"Planning, organising, coordinating, commanding, and controlling","C":"Land, labour, capital, enterprise, and added value","D":"Job analysis, job description, person specification, shortlisting, and induction"},"correctOption":"A","correctAnswer":"Transmitter (sender), message, medium, receiver, and feedback","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because communication requires a sender encoding a message, transmitting it through a medium to a receiver, and receiving feedback.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because these are the five functions of management.","C":"Incorrect because these are the four factors of production and added value.","D":"Incorrect because these are stages in recruitment and selection."}}},{"id":"P1_U2_MCQ_778","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_778","question":"When is a formal written 'letter' the most suitable method of business communication?","options":{"A":"When warning factory workers of an immediate fire evacuation","B":"When sending official, confidential, or legal notices requiring a formal permanent record","C":"When holding a rapid brainstorming session across three international offices","D":"When displaying daily canteen menu specials to on-site staff"},"correctOption":"B","correctAnswer":"When sending official, confidential, or legal notices requiring a formal permanent record","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because formal letters convey authority, protect confidentiality, and serve as verifiable legal documentation.","distractor_reasons":{"A":"Incorrect because postal letters are far too slow for emergencies.","B":"Correct selection.","C":"Incorrect because virtual meetings are far faster for interactive brainstorming.","D":"Incorrect because posters or noticeboards suit daily communal announcements."}}},{"id":"P1_U2_MCQ_779","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_779","question":"What is a disadvantage of using phone calls (including mobile calls) for complex business agreements?","options":{"A":"They prevent immediate two-way verbal feedback between caller and receiver","B":"They take several days to connect across different cities","C":"They provide no automatic written record and lack visual body language cues","D":"They cannot be used by employees travelling outside the office"},"correctOption":"C","correctAnswer":"They provide no automatic written record and lack visual body language cues","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because telephone conversations are spoken and unrecorded unless followed up in writing, creating a risk of disputed details.","distractor_reasons":{"A":"Incorrect because immediate verbal two-way feedback is a key advantage of phone calls.","B":"Incorrect because phone calls connect instantaneously.","C":"Correct selection.","D":"Incorrect because mobile calls enable communication while travelling."}}},{"id":"P1_U2_MCQ_780","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_780","question":"What is a disadvantage of virtual meetings compared with face-to-face meetings?","options":{"A":"Virtual meetings require every participant to fly to head office","B":"Virtual meetings cannot include participants from different departments","C":"Virtual meetings completely prevent speakers from sharing visual slides","D":"Technical connectivity issues can disrupt calls and subtle body language is harder to read"},"correctOption":"D","correctAnswer":"Technical connectivity issues can disrupt calls and subtle body language is harder to read","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because video conferencing depends on stable internet bandwidth and offers weaker personal rapport than in-person meetings.","distractor_reasons":{"A":"Incorrect because eliminating travel is a main advantage of virtual meetings.","B":"Incorrect because virtual meetings easily connect cross-functional teams.","C":"Incorrect because screen-sharing allows slides and charts to be displayed.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_781","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_781","question":"What is a common disadvantage of relying heavily on email for internal workplace communication?","options":{"A":"Employees may suffer from information overload and overlook critical messages in crowded inboxes","B":"Emails cannot be sent to more than one recipient at a time","C":"Emails are slower to deliver than standard postal letters","D":"Emails cannot include attached spreadsheets or policy documents"},"correctOption":"A","correctAnswer":"Employees may suffer from information overload and overlook critical messages in crowded inboxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because excessive email volume overwhelms staff, causing urgent instructions to be missed or delayed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because emails can easily be broadcast to large groups.","C":"Incorrect because emails transmit almost instantaneously.","D":"Incorrect because attaching digital files is a standard email feature."}}},{"id":"P1_U2_MCQ_782","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_782","question":"Which problem is directly caused by communication barriers within a business?","options":{"A":"Tasks are completed inaccurately, causing wasted materials, customer dissatisfaction, and lower staff morale","B":"Employees become overly motivated and work faster than target schedules","C":"The business achieves higher profit margins due to fewer staff meetings","D":"External suppliers automatically lower raw-material prices"},"correctOption":"A","correctAnswer":"Tasks are completed inaccurately, causing wasted materials, customer dissatisfaction, and lower staff morale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because breakdowns in communication lead to operational errors, duplicated work, missed deadlines, and demotivated workers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unclear instructions cause confusion and lower productivity.","C":"Incorrect because errors and delays increase costs and reduce profitability.","D":"Incorrect because poor supplier communication causes wrong or late deliveries rather than discounts."}}},{"id":"P1_U2_MCQ_783","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_783","question":"Which of the following is a communication barrier originating with the 'sender'?","options":{"A":"Loud factory machinery drowning out a spoken instruction","B":"A receiver ignoring an email because they dislike the manager","C":"Failure of the company's internet server during a video conference","D":"Sending a vague, incomplete message packed with unfamiliar technical jargon"},"correctOption":"D","correctAnswer":"Sending a vague, incomplete message packed with unfamiliar technical jargon","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the sender is responsible for encoding a clear, complete message in language suited to the receiver.","distractor_reasons":{"A":"Incorrect because machinery noise is a physical environmental barrier.","B":"Incorrect because receiver hostility is an attitudinal barrier on the receiver's side.","C":"Incorrect because server failure is a technical medium breakdown.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_784","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_784","question":"Which of the following represents a communication barrier on the part of the 'receiver'?","options":{"A":"The sender choosing a slow postal letter for an urgent delivery change","B":"Lack of trust in the sender or inattention causing the receiver to ignore or misinterpret the message","C":"Poor mobile phone reception inside an underground warehouse","D":"A tall organisational structure with eight management tiers"},"correctOption":"B","correctAnswer":"Lack of trust in the sender or inattention causing the receiver to ignore or misinterpret the message","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because receiver attitude, distrust, or lack of interest prevents accurate listening and decoding.","distractor_reasons":{"A":"Incorrect because medium selection is a sender error.","B":"Correct selection.","C":"Incorrect because weak signal is a physical/technical channel barrier.","D":"Incorrect because hierarchy layers represent an organisational structure barrier."}}},{"id":"P1_U2_MCQ_785","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_785","question":"Which of the following is an example of a 'physical' barrier to effective communication?","options":{"A":"A manager using complex financial acronyms when briefing shop-floor cleaners","B":"Loud machinery noise, weak cellular reception, or geographical distance across time zones","C":"Distrust between trade union members and senior directors","D":"An employee failing to ask clarifying questions after reading a memo"},"correctOption":"B","correctAnswer":"Loud machinery noise, weak cellular reception, or geographical distance across time zones","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because environmental noise, distance, and poor signal physically interfere with message transmission.","distractor_reasons":{"A":"Incorrect because financial acronyms represent a language/jargon barrier.","B":"Correct selection.","C":"Incorrect because distrust is an attitudinal/interpersonal barrier.","D":"Incorrect because missing feedback is a process/receiver barrier."}}},{"id":"P1_U2_MCQ_786","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_786","question":"How does shortening the chain of command (delayering) help reduce communication barriers?","options":{"A":"It prevents frontline workers from ever contacting senior directors","B":"It forces every message to be sent exclusively by physical letter","C":"Fewer intermediate managers mean messages travel faster with less risk of filtering or distortion","D":"It eliminates the need for two-way feedback in team briefings"},"correctOption":"C","correctAnswer":"Fewer intermediate managers mean messages travel faster with less risk of filtering or distortion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because removing hierarchy layers reduces the number of intermediaries who might omit or alter details.","distractor_reasons":{"A":"Incorrect because shortening the chain brings frontline staff closer to senior leadership.","B":"Incorrect because delayering does not restrict the choice of media.","C":"Correct selection.","D":"Incorrect because two-way feedback remains essential."}}},{"id":"P1_U2_MCQ_787","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_787","question":"How does actively encouraging feedback reduce communication barriers?","options":{"A":"It allows the sender to check whether the receiver understood the message and clarify doubts immediately","B":"It lengthens the chain of command between supervisors and workers","C":"It replaces the need to write clear instructions in the first place","D":"It converts two-way meetings into one-way noticeboard announcements"},"correctOption":"A","correctAnswer":"It allows the sender to check whether the receiver understood the message and clarify doubts immediately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because asking receivers to confirm or restate instructions exposes misunderstandings before costly errors occur.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because direct feedback shortens communication loops rather than adding hierarchy tiers.","C":"Incorrect because clear initial encoding is still necessary.","D":"Incorrect because feedback transforms one-way transmission into two-way communication."}}},{"id":"P1_U2_MCQ_788","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_788","question":"Which set of reasons best explains why people work?","options":{"A":"Strictly to pay corporate taxes and increase shareholder dividends","B":"Exclusively to avoid government fines for unemployment","C":"Only to obtain company cars and overseas business travel","D":"To earn money for needs and wants, gain security, enjoy social contact, achieve esteem, and gain job satisfaction"},"correctOption":"D","correctAnswer":"To earn money for needs and wants, gain security, enjoy social contact, achieve esteem, and gain job satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because people work for both financial rewards (income and security) and psychological/social rewards (belonging, esteem, and self-fulfilment).","distractor_reasons":{"A":"Incorrect because corporate taxes and dividends are business obligations, not personal reasons why employees work.","B":"Incorrect because unemployment is not punished by government fines.","C":"Incorrect because fringe benefits are only one minor factor for certain roles.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_789","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_789","question":"How does a well-motivated workforce help reduce a business's recruitment and training costs?","options":{"A":"Motivated employees are less likely to resign, resulting in lower labour turnover","B":"Motivated employees do not require any induction or skills training when hired","C":"Motivated employees agree to work overtime hours without pay","D":"Motivated employees never retire or take statutory annual leave"},"correctOption":"A","correctAnswer":"Motivated employees are less likely to resign, resulting in lower labour turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher job satisfaction lowers staff turnover, avoiding repeated advertising, interviewing, and induction expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because new hires still require induction and training.","C":"Incorrect because motivated staff still receive contracted overtime pay.","D":"Incorrect because employees still take statutory holidays and eventually retire."}}},{"id":"P1_U2_MCQ_790","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_790","question":"According to Abraham Maslow's hierarchy of needs, what happens once a lower-level need (such as safety and security) has been reasonably satisfied?","options":{"A":"The employee permanently stops seeking any further workplace rewards","B":"The satisfied need no longer motivates, and the next higher level of need becomes the primary motivator","C":"The employee reverts exclusively to basic physiological survival needs","D":"Financial pay automatically becomes a hygiene factor that causes dissatisfaction"},"correctOption":"B","correctAnswer":"The satisfied need no longer motivates, and the next higher level of need becomes the primary motivator","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Maslow's progression principle states that human needs are arranged in ascending order and once one level is met, the next level drives behaviour.","distractor_reasons":{"A":"Incorrect because employees progress upward to social, esteem, and self-actualization needs.","B":"Correct selection.","C":"Incorrect because employees move upward through the hierarchy once lower needs are met.","D":"Incorrect because classifying pay as a hygiene factor is Frederick Herzberg's theory, not Maslow's."}}},{"id":"P1_U2_MCQ_791","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_791","question":"Which level sits at the very top of Abraham Maslow's hierarchy of needs?","options":{"A":"Social needs","B":"Safety and security needs","C":"Esteem needs","D":"Self-actualization needs"},"correctOption":"D","correctAnswer":"Self-actualization needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because self-actualization represents reaching one's full personal and creative potential through challenging, meaningful work.","distractor_reasons":{"A":"Incorrect because social needs occupy the third tier of Maslow's pyramid.","B":"Incorrect because safety needs occupy the second tier.","C":"Incorrect because esteem needs occupy the fourth tier just below self-actualization.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_792","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_792","question":"Which financial payment method rewards employees with a fixed annual amount paid monthly, typically without separate hourly overtime pay?","options":{"A":"Piece-rate wage","B":"Salary","C":"Sales commission","D":"Profit-sharing bonus"},"correctOption":"B","correctAnswer":"Salary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a salary is a fixed yearly sum paid in equal monthly instalments, commonly used for managers and administrative staff.","distractor_reasons":{"A":"Incorrect because piece-rate pays a fixed amount per unit of output produced.","B":"Correct selection.","C":"Incorrect because commission is a percentage of sales revenue generated.","D":"Incorrect because profit-sharing distributes a share of annual company profits."}}},{"id":"P1_U2_MCQ_793","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_793","question":"What is a 'bonus' as a financial method of motivation?","options":{"A":"A fixed hourly rate paid regardless of output volume","B":"A non-cash perk such as a company car or subsidized canteen meal","C":"A percentage of sales value paid exclusively to retail cashiers","D":"An additional lump-sum payment awarded on top of basic pay when specific targets are met"},"correctOption":"D","correctAnswer":"An additional lump-sum payment awarded on top of basic pay when specific targets are met","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a bonus is a one-off or periodic cash reward paid for achieving agreed output, quality, or profit goals.","distractor_reasons":{"A":"Incorrect because a fixed hourly rate is a time-based wage.","B":"Incorrect because non-cash perks are fringe benefits.","C":"Incorrect because a percentage of sales revenue is commission.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_794","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_794","question":"Which financial motivator pays sales employees a percentage of the value of goods or services they sell?","options":{"A":"Time-based wage","B":"Commission","C":"Annual salary","D":"Fringe benefit"},"correctOption":"B","correctAnswer":"Commission","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because commission links sales staff earnings directly to sales revenue generated.","distractor_reasons":{"A":"Incorrect because time-based wages pay per hour worked.","B":"Correct selection.","C":"Incorrect because a salary is a fixed annual sum.","D":"Incorrect because fringe benefits are non-cash perks."}}},{"id":"P1_U2_MCQ_795","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_795","question":"What is the main aim of a 'profit-sharing' scheme as a financial motivator?","options":{"A":"To pay workers a fixed rate for every individual item manufactured","B":"To replace monthly wages with non-cash health insurance perks","C":"To distribute a proportion of company profits among staff so everyone works toward overall profitability","D":"To penalize employees financially whenever external economic recessions occur"},"correctOption":"C","correctAnswer":"To distribute a proportion of company profits among staff so everyone works toward overall profitability","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit sharing gives employees a financial stake in the business's overall net profit.","distractor_reasons":{"A":"Incorrect because paying per unit manufactured is piece-rate pay.","B":"Incorrect because profit-sharing supplements regular wages rather than replacing them.","C":"Correct selection.","D":"Incorrect because profit-sharing rewards profitable years rather than deducting basic wages in downturns."}}},{"id":"P1_U2_MCQ_796","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_796","question":"Which of the following is an example of a 'fringe benefit' used to motivate and retain employees?","options":{"A":"Private medical insurance, a company car, or staff merchandise discounts","B":"An overtime hourly wage premium for working public holidays","C":"A piece-rate payment per completed assembly unit","D":"A statutory redundancy severance payment"},"correctOption":"A","correctAnswer":"Private medical insurance, a company car, or staff merchandise discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fringe benefits (perks) are non-cash rewards provided alongside basic pay to enhance recruitment and loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overtime premiums are cash hourly wages.","C":"Incorrect because piece-rate is a cash output wage.","D":"Incorrect because redundancy pay is compensation upon job loss."}}},{"id":"P1_U2_MCQ_797","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_797","question":"How do 'opportunities for promotion' act as a non-financial motivator?","options":{"A":"They satisfy esteem and achievement needs by offering higher status, responsibility, and career progression","B":"They allow employees to avoid all performance appraisals and accountability","C":"They ensure every worker performs identical repetitive tasks throughout their career","D":"They eliminate the need for any workplace training or supervision"},"correctOption":"A","correctAnswer":"They satisfy esteem and achievement needs by offering higher status, responsibility, and career progression","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clear internal promotion prospects reward hard work with greater responsibility, recognition, and personal growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because senior roles carry greater accountability and regular performance reviews.","C":"Incorrect because promotion moves staff into more challenging, higher-level roles.","D":"Incorrect because promoted staff typically need management training."}}},{"id":"P1_U2_MCQ_798","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_798","question":"Why is 'praise' from a manager considered an effective non-financial motivator?","options":{"A":"It legally exempts employees from paying income tax on their salaries","B":"It guarantees that employees will never request higher pay","C":"It replaces the need for written contracts of employment","D":"It recognizes good effort at zero financial cost and satisfies employees' esteem needs"},"correctOption":"D","correctAnswer":"It recognizes good effort at zero financial cost and satisfies employees' esteem needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because genuine verbal or written praise makes employees feel valued and respected without increasing payroll expenses.","distractor_reasons":{"A":"Incorrect because praise has no impact on tax obligations.","B":"Incorrect because praise complements fair financial pay rather than replacing it.","C":"Incorrect because employment contracts remain legally mandatory.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_799","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_799","question":"What is the purpose of an 'employee of the month' scheme as a non-financial motivator?","options":{"A":"To permanently demote employees who fail to win the award","B":"To publicly recognize outstanding performance, boosting self-esteem and encouraging high effort","C":"To replace basic hourly wages with monthly trophies","D":"To reduce the span of control of senior department directors"},"correctOption":"B","correctAnswer":"To publicly recognize outstanding performance, boosting self-esteem and encouraging high effort","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public recognition awards satisfy esteem needs (Maslow) and act as a motivator (Herzberg) across the team.","distractor_reasons":{"A":"Incorrect because employee of the month rewards top performers rather than punishing others.","B":"Correct selection.","C":"Incorrect because recognition awards supplement regular wages.","D":"Incorrect because recognition awards do not alter organisational structure."}}},{"id":"P1_U2_MCQ_800","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_800","question":"What is the key difference between 'job enrichment' and 'job rotation'?","options":{"A":"Job enrichment is a financial bonus scheme, whereas job rotation is a legal employment control","B":"Job enrichment moves staff between routine tasks of equal skill, whereas job rotation grants managerial authority","C":"Job enrichment adds higher-level responsibility and autonomy, whereas job rotation moves staff between tasks of a similar skill level","D":"Job enrichment is used only in factories, whereas job rotation is used only in banks"},"correctOption":"C","correctAnswer":"Job enrichment adds higher-level responsibility and autonomy, whereas job rotation moves staff between tasks of a similar skill level","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because job enrichment expands a job vertically with more skilled, autonomous duties, while job rotation switches workers horizontally across peer-level tasks.","distractor_reasons":{"A":"Incorrect because both job enrichment and job rotation are non-financial motivators.","B":"Incorrect because this reverses the definitions of the two concepts.","C":"Correct selection.","D":"Incorrect because both techniques can be applied across manufacturing and service businesses."}}},{"id":"P1_U2_MCQ_801","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_801","question":"What is the primary purpose of 'workforce planning' in Human Resource Management?","options":{"A":"Forecasting the number and skill types of employees a business will need in the future to meet its objectives","B":"Calculating the exact hourly overtime pay owed to part-time workers each week","C":"Designing advertising posters to promote new products to retail customers","D":"Conducting disciplinary hearings for employees who breach safety rules"},"correctOption":"A","correctAnswer":"Forecasting the number and skill types of employees a business will need in the future to meet its objectives","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because workforce planning anticipates future labour requirements—considering retirements, expansion, or new technology—so the business recruits or trains staff in advance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because calculating weekly overtime wages is a routine payroll administration task.","C":"Incorrect because designing product adverts is a marketing function.","D":"Incorrect because disciplinary hearings handle immediate employee misconduct rather than long-term staffing forecasts."}}},{"id":"P1_U2_MCQ_802","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_802","question":"How does an 'aptitude test' differ from a 'psychometric (personality) test' during employee selection?","options":{"A":"An aptitude test measures ability to perform specific job-related tasks, whereas a psychometric test assesses behavioural traits and temperament","B":"An aptitude test is completed after hiring, whereas a psychometric test is completed before advertising the vacancy","C":"An aptitude test checks criminal records, whereas a psychometric test checks academic degrees","D":"An aptitude test is used only for internal promotions, whereas a psychometric test is used only for manual labourers"},"correctOption":"A","correctAnswer":"An aptitude test measures ability to perform specific job-related tasks, whereas a psychometric test assesses behavioural traits and temperament","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aptitude tests evaluate practical or cognitive skills (such as numerical reasoning or typing speed), while psychometric tests examine personality fit and attitude.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both types of tests are administered during the selection stage prior to offering a job.","C":"Incorrect because background and qualification checks verify criminal records and academic certificates.","D":"Incorrect because both tests can be used for external or internal candidates across many job levels."}}},{"id":"P1_U2_MCQ_803","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_803","question":"Why might an employer include a group problem-solving exercise during candidate selection?","options":{"A":"To observe how candidates communicate, cooperate, and show leadership under pressure","B":"To avoid checking candidates' written application forms or previous employer references","C":"To reduce the total number of applicants before advertising the vacancy","D":"To replace the need for a written contract of employment once a candidate is chosen"},"correctOption":"A","correctAnswer":"To observe how candidates communicate, cooperate, and show leadership under pressure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because group exercises reveal interpersonal teamwork, listening, and persuasion skills that cannot easily be judged from a CV or one-to-one interview.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because group tasks supplement rather than replace application screening and references.","C":"Incorrect because group exercises occur after advertising and initial shortlisting.","D":"Incorrect because a legal contract of employment is still required upon hiring."}}},{"id":"P1_U2_MCQ_804","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_804","question":"How do HR managers use 'essential' versus 'desirable' criteria in a person specification during shortlisting?","options":{"A":"Applicants lacking essential criteria are rejected first, while desirable criteria distinguish between remaining qualified candidates","B":"Applicants meeting desirable criteria are hired immediately without an interview, while essential criteria are ignored","C":"Essential criteria apply only to part-time workers, while desirable criteria apply only to full-time managers","D":"Both essential and desirable criteria are kept secret until the employee's first annual appraisal"},"correctOption":"A","correctAnswer":"Applicants lacking essential criteria are rejected first, while desirable criteria distinguish between remaining qualified candidates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because essential requirements are mandatory minimum standards for the role, whereas desirable attributes help narrow down a strong pool of eligible applicants.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because essential requirements are mandatory and shortlisted candidates still undergo selection.","C":"Incorrect because both categories apply to any vacancy regardless of full-time or part-time status.","D":"Incorrect because person specification criteria guide shortlisting before interviews take place."}}},{"id":"P1_U2_MCQ_805","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_805","question":"What is the key difference between 'voluntary redundancy' and 'compulsory redundancy'?","options":{"A":"Voluntary redundancy occurs when employees choose to leave in exchange for a severance package, whereas compulsory redundancy occurs when management selects which staff must leave","B":"Voluntary redundancy is caused by employee theft, whereas compulsory redundancy is caused by retirement","C":"Voluntary redundancy pays zero financial compensation, whereas compulsory redundancy doubles basic pay","D":"Voluntary redundancy is illegal under employment law, whereas compulsory redundancy requires no notice period"},"correctOption":"A","correctAnswer":"Voluntary redundancy occurs when employees choose to leave in exchange for a severance package, whereas compulsory redundancy occurs when management selects which staff must leave","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because offering voluntary redundancy allows workers who wish to retire early or change careers to step forward, reducing workplace conflict compared with forced layoffs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employee theft leads to dismissal for misconduct, not redundancy.","C":"Incorrect because voluntary redundancy typically includes an enhanced financial severance incentive.","D":"Incorrect because both forms are lawful when conducted fairly with proper notice and statutory payments."}}},{"id":"P1_U2_MCQ_806","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_806","question":"Which objective criterion is commonly used by employers when deciding which workers to retain during a redundancy exercise?","options":{"A":"Employees' skill sets, productivity records, attendance, and disciplinary history","B":"Employees' age, gender, religion, or trade union membership","C":"Employees' personal friendships with senior company directors","D":"Employees' marital status and family size"},"correctOption":"A","correctAnswer":"Employees' skill sets, productivity records, attendance, and disciplinary history","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fair redundancy selection relies on measurable job-related criteria such as skills needed for future operations, attendance, and performance records.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because selecting staff based on protected characteristics or union membership constitutes unlawful discrimination and unfair dismissal.","C":"Incorrect because favouritism is subjective and exposes the employer to unfair dismissal claims.","D":"Incorrect because personal family status is not a fair operational selection criterion."}}},{"id":"P1_U2_MCQ_807","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_807","question":"What is meant by 'natural wastage' as a method of reducing a business's workforce?","options":{"A":"Choosing not to recruit replacements when existing employees resign or retire voluntarily","B":"Immediately dismissing the lowest-performing 10% of staff each month","C":"Closing an entire factory overnight without giving notice to employees","D":"Converting all full-time permanent staff onto zero-hours contracts"},"correctOption":"A","correctAnswer":"Choosing not to recruit replacements when existing employees resign or retire voluntarily","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because natural wastage gradually shrinks headcount without triggering redundancy payouts or damaging workforce morale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because firing low performers is dismissal rather than natural wastage.","C":"Incorrect because sudden plant closure involves compulsory redundancy.","D":"Incorrect because altering contracts does not reduce headcount through voluntary departures."}}},{"id":"P1_U2_MCQ_808","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_808","question":"What responsibility do employees have under workplace health and safety legislation?","options":{"A":"To take reasonable care of their own safety and that of coworkers, and use protective equipment provided","B":"To purchase their own heavy industrial machinery and fire suppression systems","C":"To write and enforce national health and safety laws for rival companies","D":"To pay fines on behalf of the employer if factory lighting is defective"},"correctOption":"A","correctAnswer":"To take reasonable care of their own safety and that of coworkers, and use protective equipment provided","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because health and safety laws place a legal duty on workers to follow safety training, wear personal protective equipment, and report hazards.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because providing safe equipment and facilities is the employer's legal duty.","C":"Incorrect because governments enact and inspect compliance with national laws.","D":"Incorrect because employers are legally responsible for maintaining safe premises."}}},{"id":"P1_U2_MCQ_809","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_809","question":"What is a potential negative economic effect if a government raises the statutory legal minimum wage significantly above market equilibrium?","options":{"A":"Some businesses may reduce hiring or replace low-skilled workers with automation to control rising wage costs","B":"All employees will voluntarily ask their employers to lower their hourly pay","C":"Businesses will be legally exempted from paying holiday or sick pay","D":"Consumer spending among low-income households will automatically fall to zero"},"correctOption":"A","correctAnswer":"Some businesses may reduce hiring or replace low-skilled workers with automation to control rising wage costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because steep minimum wage increases raise labour expenses, which can cause some firms to cut staff hours, slow recruitment, or automate tasks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers benefit from higher hourly rates and would not request pay cuts.","C":"Incorrect because statutory leave entitlements remain legally binding.","D":"Incorrect because employed workers receiving higher wages actually gain greater disposable income."}}},{"id":"P1_U2_MCQ_810","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_810","question":"Which of the following is generally considered a legally fair reason for dismissing an employee?","options":{"A":"Gross misconduct, such as theft, fraud, or serious deliberate breach of safety rules","B":"Becoming pregnant or requesting statutory maternity leave","C":"Joining a legally recognized trade union","D":"Reporting a dangerous chemical leak to a health and safety inspector"},"correctOption":"A","correctAnswer":"Gross misconduct, such as theft, fraud, or serious deliberate breach of safety rules","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because serious misconduct or persistent failure to improve incompetence after formal warnings are valid grounds for dismissal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dismissing an employee due to pregnancy is automatically unfair dismissal.","C":"Incorrect because employees have a legal right to join a trade union.","D":"Incorrect because whistleblowing on genuine health and safety hazards is legally protected."}}},{"id":"P1_U2_MCQ_811","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_811","question":"Which of the following is a major advantage of 'off-the-job' training?","options":{"A":"Employees learn from specialist instructors in a distraction-free environment and can gain recognized qualifications","B":"The business incurs zero course fees and loses no employee working hours","C":"Training is always tailored exclusively to the company's own bespoke legacy machinery","D":"Trainees continue producing sellable output for customers during every hour of the course"},"correctOption":"A","correctAnswer":"Employees learn from specialist instructors in a distraction-free environment and can gain recognized qualifications","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external courses bring new expertise into the business, provide focused study away from workplace pressures, and often award accredited certificates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external fees and lost output during course attendance are key disadvantages of off-the-job training.","C":"Incorrect because bespoke internal equipment training is an advantage of on-the-job training.","D":"Incorrect because producing output while learning is a feature of on-the-job training."}}},{"id":"P1_U2_MCQ_812","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_812","question":"What is a common disadvantage of 'on-the-job' training?","options":{"A":"The experienced employee acting as trainer becomes less productive while supervising, and may pass on bad habits","B":"The business must pay expensive university tuition fees and hotel accommodation","C":"The trainee learns theoretical concepts that have no relevance to actual workplace equipment","D":"The trainee must travel away from the company premises for several weeks"},"correctOption":"A","correctAnswer":"The experienced employee acting as trainer becomes less productive while supervising, and may pass on bad habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mentoring slows down the trainer's regular work and risks transferring shortcuts or poor habits to the new recruit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tuition and travel expenses apply to off-the-job training.","C":"Incorrect because on-the-job training uses the exact tools and routines of the job.","D":"Incorrect because on-the-job training occurs directly at the workplace."}}},{"id":"P1_U2_MCQ_813","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_813","question":"Which indicator best helps an HR manager evaluate whether a new staff training programme has been successful?","options":{"A":"A measurable rise in output per worker alongside lower product defect rates and reduced workplace accidents","B":"An increase in the number of external recruitment advertisements placed each month","C":"A higher rate of absenteeism and customer complaints after training ends","D":"A longer chain of command across every functional department"},"correctOption":"A","correctAnswer":"A measurable rise in output per worker alongside lower product defect rates and reduced workplace accidents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective training improves employee competence, translating into higher productivity, better quality, and safer working practices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because more job adverts indicate rising staff turnover rather than training success.","C":"Incorrect because higher absenteeism and complaints signal declining morale or poor training.","D":"Incorrect because hierarchy length is an organisational structure feature unrelated to training effectiveness."}}},{"id":"P1_U2_MCQ_814","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_814","question":"How does a 'line manager' differ from a 'staff manager' in an organisation?","options":{"A":"A line manager has direct authority over subordinates in the chain of command, whereas a staff manager provides specialist advice without direct line authority over other departments","B":"A line manager works only on factory assembly lines, whereas a staff manager works only in retail shops","C":"A line manager has zero responsibility for meeting departmental targets, whereas a staff manager approves all budgets","D":"A line manager is elected by trade unions, whereas a staff manager is appointed by customers"},"correctOption":"A","correctAnswer":"A line manager has direct authority over subordinates in the chain of command, whereas a staff manager provides specialist advice without direct line authority over other departments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because line managers directly supervise operational teams and make operational decisions, whereas staff managers (such as legal or IT advisors) offer specialist support.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because line managers exist in all sectors, including retail, banking, and manufacturing.","C":"Incorrect because line managers are directly accountable for achieving departmental performance targets.","D":"Incorrect because both line and staff managers are appointed by senior management."}}},{"id":"P1_U2_MCQ_815","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_815","question":"What is a major financial and operational advantage of 'delayering' an organisation?","options":{"A":"It lowers management salary overheads and speeds up communication between senior leaders and frontline staff","B":"It creates many additional supervisory tiers to closely monitor every junior worker","C":"It narrows managers' spans of control so each supervisor oversees fewer staff","D":"It eliminates the need for any delegation of authority to lower-level employees"},"correctOption":"A","correctAnswer":"It lowers management salary overheads and speeds up communication between senior leaders and frontline staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing one or more middle-management tiers reduces salary costs and shortens the chain of command.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delayering removes management tiers rather than adding them.","C":"Incorrect because removing middle managers widens spans of control.","D":"Incorrect because wider spans of control actually require greater delegation."}}},{"id":"P1_U2_MCQ_816","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_816","question":"What is a potential disadvantage of 'delayering' for a business and its remaining managers?","options":{"A":"Remaining managers face wider spans of control and heavier workloads, while promotion opportunities shrink","B":"The chain of command becomes much longer and slows down urgent decisions","C":"Senior executives become completely isolated from customer feedback","D":"Total middle-management salary costs double immediately"},"correctOption":"A","correctAnswer":"Remaining managers face wider spans of control and heavier workloads, while promotion opportunities shrink","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting middle-management layers leaves remaining managers supervising more staff and reduces upward career steps.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delayering shortens the chain of command.","C":"Incorrect because fewer layers bring senior managers closer to frontline operations.","D":"Incorrect because eliminating management posts reduces salary overheads over time."}}},{"id":"P1_U2_MCQ_817","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_817","question":"What is a key advantage of a 'centralised' organisational structure?","options":{"A":"Senior management maintains tight control, ensuring consistent policies and economies of scale across all branches","B":"Local branch managers have complete freedom to alter product prices and branding independently","C":"Senior executives are freed from making strategic financial decisions","D":"Junior store staff feel highly empowered to redesign company-wide HR policies"},"correctOption":"A","correctAnswer":"Senior management maintains tight control, ensuring consistent policies and economies of scale across all branches","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because keeping decision-making at head office ensures uniform standards, coordinated purchasing, and clear strategic direction.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local autonomy over pricing and menus is a feature of decentralisation.","C":"Incorrect because centralisation concentrates strategic decisions at senior head-office level.","D":"Incorrect because centralisation limits local and junior decision-making authority."}}},{"id":"P1_U2_MCQ_818","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_818","question":"How does a 'decentralised' organisational structure benefit a large multi-branch business?","options":{"A":"Branch managers can respond quickly to local market conditions and feel more motivated by greater authority","B":"Head office approves every minor local stationery order before purchase","C":"All branches are forced to offer identical products regardless of regional customer tastes","D":"The business eliminates the need to hire capable managers at regional branches"},"correctOption":"A","correctAnswer":"Branch managers can respond quickly to local market conditions and feel more motivated by greater authority","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegating authority to regional or branch managers speeds up local decisions, adapts offerings to local demand, and prepares managers for senior roles.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because head-office approval of minor expenses describes centralisation.","C":"Incorrect because decentralisation allows local adaptation to regional preferences.","D":"Incorrect because decentralisation requires skilled, trustworthy local managers."}}},{"id":"P1_U2_MCQ_819","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_819","question":"What is a common disadvantage of 'decentralisation' for a national retail chain?","options":{"A":"Inconsistent customer service or pricing across branches and potential duplication of administrative roles","B":"Local managers cannot react to sudden local competitor promotions without waiting weeks for head office","C":"Senior directors become overloaded with minor daily operational decisions","D":"Branch managers feel demotivated due to having zero decision-making power"},"correctOption":"A","correctAnswer":"Inconsistent customer service or pricing across branches and potential duplication of administrative roles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because giving branches autonomy can weaken uniform brand standards and result in duplicated support functions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because slow local reaction is a disadvantage of centralisation, not decentralisation.","C":"Incorrect because decentralisation relieves senior directors of routine operational choices.","D":"Incorrect because branch managers gain greater authority and motivation under decentralisation."}}},{"id":"P1_U2_MCQ_820","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_820","question":"Which statement best describes a 'paternalistic' leadership style?","options":{"A":"The leader treats employees like family members, making decisions in what they believe are the workers' best interests while expecting loyalty","B":"The leader delegates all strategic and financial decisions entirely to autonomous teams without guidance","C":"The leader uses harsh threats and strict punishment without any concern for employee welfare","D":"The leader holds binding democratic votes among all employees before every operational step"},"correctOption":"A","correctAnswer":"The leader treats employees like family members, making decisions in what they believe are the workers' best interests while expecting loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a paternalistic leader acts like a protective parent—consulting occasionally and caring for staff welfare, yet retaining final decision authority.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because complete hands-off autonomy describes laissez-faire leadership.","C":"Incorrect because harsh, purely task-focused control describes hard autocratic management.","D":"Incorrect because shared group decision-making describes democratic leadership."}}},{"id":"P1_U2_MCQ_821","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_821","question":"What is a primary advantage of adopting a 'democratic' leadership style?","options":{"A":"Employees feel valued when consulted, leading to higher motivation and better decisions informed by frontline ideas","B":"Crisis decisions can be issued instantaneously without consulting anyone","C":"Managers retain sole control over every detail without needing employee trust","D":"Unexperienced trainees receive strict step-by-step orders without having to think independently"},"correctOption":"A","correctAnswer":"Employees feel valued when consulted, leading to higher motivation and better decisions informed by frontline ideas","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because two-way consultation taps into workers' practical knowledge and boosts commitment to agreed decisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rapid unilateral crisis decisions are an advantage of autocratic leadership.","C":"Incorrect because democratic leadership relies on trust and shared participation.","D":"Incorrect because strict step-by-step direction suits autocratic leadership with unskilled staff."}}},{"id":"P1_U2_MCQ_822","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_822","question":"Which combination of factors most strongly influences the most appropriate leadership style in a given situation?","options":{"A":"The urgency of the decision, the skill and experience of the workforce, and the nature of the task","B":"The company's registered postal postcode and the colour of its corporate logo","C":"The age of the company's delivery vans and the price of office stationery","D":"Whether the business sells physical goods or intangible services exclusively on weekends"},"correctOption":"A","correctAnswer":"The urgency of the decision, the skill and experience of the workforce, and the nature of the task","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective leaders adapt their style depending on time pressure (emergencies vs long-term projects), staff expertise, and task complexity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because location and branding do not determine how managers lead staff.","C":"Incorrect because vehicle age and stationery costs are irrelevant to leadership style.","D":"Incorrect because operating days do not govern whether autocratic, democratic, or laissez-faire styles work best."}}},{"id":"P1_U2_MCQ_823","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_823","question":"Which set of responsibilities belongs primarily to the 'Finance' functional department?","options":{"A":"Preparing budgets, keeping accounting records, managing cash flow, and raising capital","B":"Designing television adverts, conducting market research, and setting promotional campaigns","C":"Recruiting new employees, arranging induction training, and maintaining staff records","D":"Scheduling factory assembly lines, managing raw-material inventory, and inspecting product quality"},"correctOption":"A","correctAnswer":"Preparing budgets, keeping accounting records, managing cash flow, and raising capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the Finance department manages money flows, financial reporting, budgeting, and funding sources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising and market research belong to the Marketing department.","C":"Incorrect because recruitment and training belong to the Human Resources department.","D":"Incorrect because production scheduling and quality control belong to the Operations department."}}},{"id":"P1_U2_MCQ_824","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_824","question":"Which responsibility belongs primarily to the 'Operations' functional department?","options":{"A":"Converting raw materials and components into finished goods or delivering services efficiently to quality standards","B":"Auditing annual income statements and negotiating bank overdraft facilities","C":"Negotiating collective wage agreements with national trade union officials","D":"Conducting focus groups to test customer reactions to brand logos"},"correctOption":"A","correctAnswer":"Converting raw materials and components into finished goods or delivering services efficiently to quality standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Operations oversees production processes, stock control, capacity planning, and quality assurance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because auditing accounts and arranging overdrafts are Finance responsibilities.","C":"Incorrect because union wage negotiations are led by Human Resources.","D":"Incorrect because customer focus groups are conducted by Marketing."}}},{"id":"P1_U2_MCQ_825","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_825","question":"How can recognizing a single trade union (a single-union agreement) benefit an employer?","options":{"A":"Management negotiates pay and working conditions with one representative body rather than multiple rival unions, saving time and reducing disputes","B":"Employees are legally forbidden from ever raising workplace health and safety complaints","C":"The trade union pays 50% of the company's monthly factory electricity and wage bills","D":"The employer is exempted from complying with national minimum wage legislation"},"correctOption":"A","correctAnswer":"Management negotiates pay and working conditions with one representative body rather than multiple rival unions, saving time and reducing disputes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dealing with a single union streamlines collective bargaining, improves communication with the workforce, and prevents inter-union rivalry.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because unions actively monitor and raise health and safety concerns.","C":"Incorrect because trade unions do not subsidize business operating expenses.","D":"Incorrect because minimum wage laws apply to all employers regardless of union recognition."}}},{"id":"P1_U2_MCQ_826","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_826","question":"What is the difference between 'downward communication' and 'upward communication'?","options":{"A":"Downward communication sends instructions from managers to subordinates, whereas upward communication carries feedback and suggestions from subordinates to managers","B":"Downward communication uses only emails, whereas upward communication uses only physical posters","C":"Downward communication occurs between external suppliers, whereas upward communication occurs between customers","D":"Downward communication happens between managers of equal rank, whereas upward communication occurs only during emergencies"},"correctOption":"A","correctAnswer":"Downward communication sends instructions from managers to subordinates, whereas upward communication carries feedback and suggestions from subordinates to managers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because downward communication flows down the hierarchy (orders, policies), while upward communication flows up the hierarchy (reports, staff views).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both directions can use spoken, written, or electronic media.","C":"Incorrect because both downward and upward communication are forms of internal organisational communication.","D":"Incorrect because communication between peers of equal rank is horizontal communication."}}},{"id":"P1_U2_MCQ_827","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_827","question":"What is 'horizontal (lateral) communication' within a business?","options":{"A":"Communication between employees or managers at the same hierarchical level across different departments","B":"Instructions passed strictly downward from the Chief Executive to shop-floor trainees","C":"Advertisements broadcast on national television to external consumers","D":"Annual tax filings submitted by the Finance Director to government authorities"},"correctOption":"A","correctAnswer":"Communication between employees or managers at the same hierarchical level across different departments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because horizontal communication connects peers (such as the Marketing Manager and Operations Manager) to coordinate activities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because top-down instructions are downward communication.","C":"Incorrect because consumer advertising is external communication.","D":"Incorrect because tax filings are external regulatory communication."}}},{"id":"P1_U2_MCQ_828","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_828","question":"How does 'informal communication' (the grapevine) differ from 'formal communication'?","options":{"A":"Informal communication occurs through unofficial social conversations among staff, whereas formal communication uses officially approved channels such as memos, meetings, and reports","B":"Informal communication is always written in legal contracts, whereas formal communication is spoken over lunch","C":"Informal communication is strictly controlled by the Board of Directors, whereas formal communication happens by accident","D":"Informal communication occurs only with external banks, whereas formal communication occurs only with factory cleaners"},"correctOption":"A","correctAnswer":"Informal communication occurs through unofficial social conversations among staff, whereas formal communication uses officially approved channels such as memos, meetings, and reports","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because formal channels follow recognised organisational structures, whereas the grapevine consists of unofficial workplace interactions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the characteristics of formal and informal communication.","C":"Incorrect because formal channels are structured by management, while the grapevine arises spontaneously.","D":"Incorrect because both formal and informal communication occur internally among all staff levels."}}},{"id":"P1_U2_MCQ_829","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_829","question":"What is a major risk to a business when employees rely heavily on the informal 'grapevine' for company news?","options":{"A":"Unverified rumours and exaggerated stories can spread rapidly, causing unnecessary anxiety and lower morale","B":"Management gains complete legal documentation of every employee conversation","C":"All official policy updates reach remote workers with 100% accuracy","D":"External competitors are prevented from learning any operational secrets"},"correctOption":"A","correctAnswer":"Unverified rumours and exaggerated stories can spread rapidly, causing unnecessary anxiety and lower morale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because informal gossip often distorts facts (for instance, spreading false redundancy rumours), damaging trust and productivity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because informal conversations leave no official written record.","C":"Incorrect because grapevine messages frequently become inaccurate as they pass from person to person.","D":"Incorrect because loose workplace gossip can actually leak confidential information."}}},{"id":"P1_U2_MCQ_830","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_830","question":"A food manufacturer discovers a dangerous allergen contamination in a batch already sold in supermarkets. Which external communication approach is most effective for alerting thousands of customers immediately?","options":{"A":"Issuing urgent press releases, social media alerts, website notices, and prominent in-store posters","B":"Sending individual hand-written letters via standard second-class post over the next two weeks","C":"Pinning a single small memo on the factory canteen noticeboard","D":"Waiting until the company's next annual shareholders' report is published"},"correctOption":"A","correctAnswer":"Issuing urgent press releases, social media alerts, website notices, and prominent in-store posters","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an urgent public safety recall requires rapid, wide-reaching mass media and point-of-sale communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because standard mail is far too slow and the firm may not have every retail shopper's address.","C":"Incorrect because an internal canteen noticeboard reaches only employees, not external consumers.","D":"Incorrect because delaying until the annual report puts consumers at severe health risk."}}},{"id":"P1_U2_MCQ_831","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_831","question":"Which method of communication is most appropriate when an HR manager issues a formal disciplinary warning to an employee?","options":{"A":"A private face-to-face meeting followed by a formal written letter placed on the employee's personnel file","B":"A public post on the company's external social media page","C":"A brief casual text message (SMS) sent late on a Sunday evening","D":"A colourful poster pinned next to the main staff entrance"},"correctOption":"A","correctAnswer":"A private face-to-face meeting followed by a formal written letter placed on the employee's personnel file","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because disciplinary matters require privacy and sensitivity in person alongside a clear, permanent written record for legal compliance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because publishing disciplinary details publicly breaches confidentiality and employment law.","C":"Incorrect because SMS is overly informal and inappropriate for serious HR procedures.","D":"Incorrect because public noticeboards violate employee privacy."}}},{"id":"P1_U2_MCQ_832","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_832","question":"Two engineering teams located in different countries need to review 3D product blueprints together and resolve design flaws quickly. Which communication method is most suitable?","options":{"A":"A virtual meeting (video conference) with screen-sharing capabilities, followed by written action notes","B":"A one-way audio voicemail message left on a landline telephone","C":"A short text message (SMS) summarizing the entire blueprint in 150 characters","D":"A printed poster displayed in one office lobby"},"correctOption":"A","correctAnswer":"A virtual meeting (video conference) with screen-sharing capabilities, followed by written action notes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because video conferencing with screen-sharing allows real-time visual inspection, instant two-way problem-solving, and zero international travel delay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a voicemail cannot display 3D visual blueprints or allow live dialogue.","C":"Incorrect because SMS cannot transmit complex visual drawings or detailed technical feedback.","D":"Incorrect because a physical poster in one country cannot be viewed by the overseas team."}}},{"id":"P1_U2_MCQ_833","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_833","question":"What is a major advantage of using visual communication (such as charts, graphs, and safety symbols) in business?","options":{"A":"Complex numerical trends or safety rules can be understood quickly and easily across different languages","B":"Visual diagrams completely eliminate the need to collect accurate underlying data","C":"Visual charts always provide exhaustive legal contract terms in fine print","D":"Visual signs can be understood over standard voice-only telephone calls"},"correctOption":"A","correctAnswer":"Complex numerical trends or safety rules can be understood quickly and easily across different languages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because charts and symbols make information memorable, clarify complex patterns, and overcome literacy or language differences.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because accurate data is still essential to construct meaningful charts.","C":"Incorrect because detailed legal terms require formal written text.","D":"Incorrect because visual media cannot be seen on voice-only phone calls."}}},{"id":"P1_U2_MCQ_834","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_834","question":"How does a 'company intranet' benefit internal business communication?","options":{"A":"It provides a secure internal network where employees can quickly access up-to-date policies, directories, and announcements","B":"It broadcasts confidential internal salary records to external competitors and the general public","C":"It replaces the need for face-to-face appraisals or sensitive personal discussions","D":"It functions without requiring computers, smartphones, or network infrastructure"},"correctOption":"A","correctAnswer":"It provides a secure internal network where employees can quickly access up-to-date policies, directories, and announcements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an intranet acts as a centralized, password-protected internal information hub accessible across all company branches.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an intranet is restricted strictly to authorized employees, unlike the public internet.","C":"Incorrect because sensitive HR discussions still require personal face-to-face meetings.","D":"Incorrect because staff need digital devices and network access to view the intranet."}}},{"id":"P1_U2_MCQ_835","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_835","question":"What is a potential drawback of using workplace instant messaging apps for rapid team communication?","options":{"A":"Frequent notifications can interrupt concentration, and important decisions may get lost in fast-moving chat threads","B":"Messages take several hours to deliver to colleagues in the same building","C":"Instant messaging apps prevent two-way replies between team members","D":"Instant messaging cannot be used on mobile devices by remote workers"},"correctOption":"A","correctAnswer":"Frequent notifications can interrupt concentration, and important decisions may get lost in fast-moving chat threads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constant chat alerts distract workers and informal quick replies can lack proper documentation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because instant messages deliver in real time.","C":"Incorrect because instant messaging is specifically designed for rapid two-way dialogue.","D":"Incorrect because mobile apps make instant messaging highly accessible to remote staff."}}},{"id":"P1_U2_MCQ_836","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_836","question":"How can a multinational business best overcome language and cultural barriers when communicating with overseas branches?","options":{"A":"Translate key documents accurately, use plain language without local idioms, and provide cross-cultural training","B":"Send all policies exclusively in complex local slang and technical acronyms","C":"Eliminate all video conferences and rely solely on rapid spoken phone calls","D":"Assume that body language gestures carry the exact same meaning in every country"},"correctOption":"A","correctAnswer":"Translate key documents accurately, use plain language without local idioms, and provide cross-cultural training","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clear translation, simple vocabulary, visual aids, and cultural awareness minimize misinterpretation across borders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because slang and acronyms worsen misunderstanding for non-native speakers.","C":"Incorrect because rapid voice-only calls without visual cues are harder to follow in a second language.","D":"Incorrect because gestures and norms vary widely across cultures."}}},{"id":"P1_U2_MCQ_837","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_837","question":"When employees distrust management and ignore company announcements, which type of communication barrier is occurring and how can it be reduced?","options":{"A":"An attitudinal barrier, which can be reduced by building transparency, consulting staff, and keeping promises","B":"A physical noise barrier, which can be reduced by installing thicker factory ear defenders","C":"A technical software barrier, which can be reduced by upgrading office printers","D":"A geographical distance barrier, which can be reduced by shortening postal addresses"},"correctOption":"A","correctAnswer":"An attitudinal barrier, which can be reduced by building transparency, consulting staff, and keeping promises","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hostility or suspicion between sender and receiver blocks open listening; two-way consultation and consistent honesty rebuild trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ear defenders address acoustic machinery noise, not workplace distrust.","C":"Incorrect because printer hardware does not resolve interpersonal suspicion.","D":"Incorrect because distrust is psychological rather than geographical."}}},{"id":"P1_U2_MCQ_838","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_838","question":"What is 'information overload' as a communication barrier, and how can managers prevent it?","options":{"A":"Receivers receive so many messages that vital details are missed; managers can prevent it by sending concise, targeted messages only to relevant staff","B":"Receivers receive zero instructions from managers; managers can prevent it by removing all company noticeboards","C":"Messages are written in a foreign language; managers can prevent it by speaking louder","D":"Messages are lost due to broken telephones; managers can prevent it by banning all written emails"},"correctOption":"A","correctAnswer":"Receivers receive so many messages that vital details are missed; managers can prevent it by sending concise, targeted messages only to relevant staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because copying every employee into hundreds of routine emails dilutes attention, whereas clear subject lines and targeted distribution keep messages focused.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because information overload involves too much communication rather than too little.","C":"Incorrect because foreign-language confusion is a linguistic barrier rather than volume overload.","D":"Incorrect because hardware failure is a physical/technical breakdown."}}},{"id":"P1_U2_MCQ_839","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_839","question":"A factory manager times workers performing each assembly step, establishes the fastest standardized method, and pays workers per completed unit. Whose motivational theory is being applied?","options":{"A":"F.W. Taylor's scientific management","B":"Abraham Maslow's hierarchy of needs","C":"Frederick Herzberg's two-factor theory","D":"Henri Fayol's administrative theory"},"correctOption":"A","correctAnswer":"F.W. Taylor's scientific management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Taylor advocated time-and-motion studies, standardized tasks, and piece-rate financial incentives to maximize output.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Maslow focused on five progressive levels of human psychological and survival needs.","C":"Incorrect because Herzberg emphasized job enrichment and intrinsic motivators over piece-rate pay.","D":"Incorrect because Fayol categorized the core functions of management."}}},{"id":"P1_U2_MCQ_840","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_840","question":"According to Abraham Maslow's hierarchy of needs, how does an employer satisfy workers' 'safety and security needs'?","options":{"A":"By providing permanent employment contracts, safe working conditions, protective gear, and pension/sick-pay protection","B":"By awarding an 'Employee of the Month' trophy at an annual ceremony","C":"By encouraging staff to form social sports clubs after working hours","D":"By delegating complex strategic research projects to senior specialists"},"correctOption":"A","correctAnswer":"By providing permanent employment contracts, safe working conditions, protective gear, and pension/sick-pay protection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because safety needs require protection against physical workplace hazards and financial insecurity from sudden job loss or illness.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because awards and recognition satisfy esteem needs.","C":"Incorrect because social clubs satisfy social (belonging) needs.","D":"Incorrect because challenging creative autonomy satisfies self-actualization needs."}}},{"id":"P1_U2_MCQ_841","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_841","question":"Which workplace practice directly satisfies 'social needs' in Abraham Maslow's hierarchy of needs?","options":{"A":"Organising staff into collaborative teams and providing communal break areas for friendly interaction","B":"Paying the statutory legal minimum hourly wage to solitary home workers","C":"Issuing strict individual piece-rate quotas where workers are forbidden to speak","D":"Installing emergency fire exits and machine safety guards"},"correctOption":"A","correctAnswer":"Organising staff into collaborative teams and providing communal break areas for friendly interaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social needs reflect the human desire for friendship, belonging, and acceptance within a group.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because basic survival pay addresses physiological needs.","C":"Incorrect because isolating workers prevents social interaction.","D":"Incorrect because fire exits and safety guards address physical safety needs."}}},{"id":"P1_U2_MCQ_842","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_842","question":"What is a recognized limitation of applying Abraham Maslow's hierarchy of needs in business management?","options":{"A":"Not all employees share the same ordering of needs, and identifying each individual's current level is difficult in large workforces","B":"Maslow completely ignored the role of wages in meeting basic survival and security needs","C":"Maslow argued that employees are motivated solely by fear of dismissal","D":"The theory applies only to self-employed sole traders with zero employees"},"correctOption":"A","correctAnswer":"Not all employees share the same ordering of needs, and identifying each individual's current level is difficult in large workforces","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because individuals prioritize needs differently (for example, some seek creative fulfilment even on modest pay) and managers cannot easily tailor jobs to every person's exact tier.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because Maslow explicitly placed physiological and safety needs—which wages help satisfy—at the base of the hierarchy.","C":"Incorrect because Maslow emphasized positive human growth and motivation rather than coercion.","D":"Incorrect because Maslow's framework is widely used to analyze motivation in organisations of all sizes."}}},{"id":"P1_U2_MCQ_843","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_843","question":"According to Frederick Herzberg's two-factor theory, why does giving repetitive assembly-line workers a 5% pay rise often produce only a short-lived boost in effort?","options":{"A":"Because pay is a hygiene factor that removes dissatisfaction temporarily, whereas lasting motivation requires intrinsic motivators like achievement and responsibility","B":"Because workers dislike receiving extra money in their monthly bank accounts","C":"Because higher pay automatically violates national health and safety regulations","D":"Because Herzberg proved that working conditions and supervision are the only true motivators"},"correctOption":"A","correctAnswer":"Because pay is a hygiene factor that removes dissatisfaction temporarily, whereas lasting motivation requires intrinsic motivators like achievement and responsibility","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg argued that hygiene factors prevent dissatisfaction once fair, but true long-term motivation comes from enriching the job itself.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers welcome fair pay, even though it does not redesign boring tasks.","C":"Incorrect because pay rises have no connection to breaching safety regulations.","D":"Incorrect because Herzberg classified working conditions and supervision as hygiene factors, not motivators."}}},{"id":"P1_U2_MCQ_844","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_844","question":"What is meant by 'job enlargement' as a non-financial method of motivation?","options":{"A":"Adding extra tasks of a similar skill level to a worker's role to provide greater variety and reduce monotony","B":"Giving a junior clerk executive authority to approve multi-million-dollar investments","C":"Paying employees an annual cash bonus equal to 10% of company net profit","D":"Reducing an employee's contracted working week from five days to two days"},"correctOption":"A","correctAnswer":"Adding extra tasks of a similar skill level to a worker's role to provide greater variety and reduce monotony","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enlargement expands a job horizontally by combining several peer-level tasks into one broader role.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because adding higher-level authority and responsibility is job enrichment.","C":"Incorrect because a share of company profit is a financial motivator.","D":"Incorrect because cutting working days shifts a worker to part-time status rather than enlarging the job."}}},{"id":"P1_U2_MCQ_845","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_845","question":"How does 'job enrichment' differ from 'job enlargement'?","options":{"A":"Job enrichment adds higher-level responsibility and decision-making autonomy, whereas job enlargement adds more tasks of the same skill level","B":"Job enrichment is a financial wage system, whereas job enlargement is a fringe benefit","C":"Job enrichment reduces a worker's duties, whereas job enlargement promotes a worker to director","D":"Job enrichment applies only to part-time staff, whereas job enlargement applies only to full-time managers"},"correctOption":"A","correctAnswer":"Job enrichment adds higher-level responsibility and decision-making autonomy, whereas job enlargement adds more tasks of the same skill level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job enrichment loads a role vertically with greater challenge and control (Herzberg's motivators), while job enlargement widens tasks horizontally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are non-financial job-redesign techniques.","C":"Incorrect because neither technique reduces duties; enrichment adds higher-level challenge.","D":"Incorrect because both techniques can be applied to full-time or part-time roles."}}},{"id":"P1_U2_MCQ_846","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_846","question":"How does 'teamworking' act as an effective non-financial motivator in a business?","options":{"A":"It satisfies social belonging needs, allows shared responsibility for completing a whole unit of work, and encourages peer support","B":"It guarantees that every employee works in complete isolation without communicating with colleagues","C":"It eliminates the need to pay employees basic wages or salaries","D":"It prevents workers from ever suggesting improvements to production methods"},"correctOption":"A","correctAnswer":"It satisfies social belonging needs, allows shared responsibility for completing a whole unit of work, and encourages peer support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organizing staff into teams builds camaraderie (Maslow's social needs) and gives groups ownership over quality and scheduling.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because teamworking relies on collaboration rather than isolation.","C":"Incorrect because teamworking supplements fair financial pay.","D":"Incorrect because teamworking actively encourages collective problem-solving and ideas."}}},{"id":"P1_U2_MCQ_847","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_847","question":"What is the purpose of 'quality circles' as a motivational and operational tool?","options":{"A":"Small groups of workers meet regularly to identify workplace or product quality problems and recommend solutions to management","B":"External government auditors inspect factory fire exits once every five years","C":"Senior executives calculate annual shareholder dividend payouts behind closed doors","D":"Sales staff compete individually to earn the highest monthly commission"},"correctOption":"A","correctAnswer":"Small groups of workers meet regularly to identify workplace or product quality problems and recommend solutions to management","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quality circles tap into frontline workers' practical expertise, boosting recognition, involvement, and product quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because government inspections are external regulatory checks.","C":"Incorrect because dividend decisions are made by the Board of Directors.","D":"Incorrect because individual sales contests are financial commission incentives."}}},{"id":"P1_U2_MCQ_848","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_848","question":"What is a potential drawback of 'performance-related pay' (PRP) when used to motivate salaried employees?","options":{"A":"Subjective appraisal ratings can cause perceived unfairness and resentment among colleagues, harming teamwork","B":"High-performing employees receive no financial reward for exceeding their targets","C":"The business must pay identical bonuses even when every employee fails to meet targets","D":"Performance-related pay is illegal under international employment conventions"},"correctOption":"A","correctAnswer":"Subjective appraisal ratings can cause perceived unfairness and resentment among colleagues, harming teamwork","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if target assessment relies on a manager's opinion rather than clear metrics, staff may feel treated unfairly and focus on individual goals over team cooperation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because PRP specifically rewards high performers who meet or exceed targets.","C":"Incorrect because PRP links pay rises or bonuses directly to achieving performance goals.","D":"Incorrect because PRP is a lawful and widely used payment system."}}},{"id":"P1_U2_MCQ_849","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_849","question":"How do 'employee share ownership schemes' help motivate and retain staff in a limited company?","options":{"A":"Employees become part-owners who benefit from dividends and rising share values, encouraging long-term loyalty and effort","B":"Employees receive free company products every day instead of a monthly cash salary","C":"Employees gain the legal right to dismiss the Chief Executive whenever share prices dip","D":"Employees are guaranteed zero financial risk even if the share price falls"},"correctOption":"A","correctAnswer":"Employees become part-owners who benefit from dividends and rising share values, encouraging long-term loyalty and effort","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owning company shares aligns employees' financial interests with long-term business profitability and reduces staff turnover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share schemes grant equity shares in addition to regular cash wages.","C":"Incorrect because minority employee shareholders do not unilaterally dismiss executives.","D":"Incorrect because share values can fall as well as rise."}}},{"id":"P1_U2_MCQ_850","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_850","question":"Why is 'delegation' considered a powerful non-financial motivator for junior and middle managers?","options":{"A":"It signals trust in the subordinate's ability and provides greater responsibility and personal achievement","B":"It allows subordinates to avoid all accountability when tasks are left unfinished","C":"It automatically doubles the subordinate's basic hourly wage rate","D":"It removes all deadlines and performance standards from the delegated task"},"correctOption":"A","correctAnswer":"It signals trust in the subordinate's ability and provides greater responsibility and personal achievement","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegating meaningful authority satisfies Maslow's esteem needs and acts as a core motivator (responsibility and growth) in Herzberg's theory.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delegated tasks still carry clear expectations and review.","C":"Incorrect because delegation is a non-financial motivator that does not automatically change wage rates.","D":"Incorrect because effective delegation requires clear targets and deadlines."}}},{"id":"P1_U2_MCQ_851","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_851","question":"A traditional high-street bookshop plans to launch its first mobile shopping app and needs a lead software engineer. Why is 'external recruitment' the best choice?","options":{"A":"Existing retail staff lack specialist app-development skills, so the firm must attract trained talent from the wider labour market","B":"External recruitment is always cheaper and faster than promoting an existing shop assistant","C":"External hires never require any induction into the bookshop's business culture","D":"Employment laws forbid retailers from training internal staff in new digital skills"},"correctOption":"A","correctAnswer":"Existing retail staff lack specialist app-development skills, so the firm must attract trained talent from the wider labour market","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when a business enters a new technical area where no current staff possess the required expertise, external recruitment brings in ready-made specialist skills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external recruitment is typically slower and more expensive than internal hiring.","C":"Incorrect because external hires require thorough induction into company operations.","D":"Incorrect because internal training is completely lawful, though training a novice from scratch would take too long here."}}},{"id":"P1_U2_MCQ_852","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_852","question":"A supermarket chain needs to appoint three new assistant store managers quickly before the busy holiday season. Why might it prefer 'internal recruitment'?","options":{"A":"Candidates already understand store systems, require minimal induction, and can take up the roles rapidly at low cost","B":"Internal recruitment guarantees that zero vacant cashier posts will be created elsewhere in the stores","C":"Internal recruitment brings fresh ideas from rival supermarket chains into the business","D":"Internal candidates are legally barred from requesting a salary increase upon promotion"},"correctOption":"A","correctAnswer":"Candidates already understand store systems, require minimal induction, and can take up the roles rapidly at low cost","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing supervisors already know company procedures and customer routines, enabling fast deployment and boosting staff motivation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because promoting internal staff still leaves their previous junior roles to be filled.","C":"Incorrect because bringing outside competitor ideas is an advantage of external recruitment.","D":"Incorrect because promoted staff normally receive higher pay reflecting greater responsibility."}}},{"id":"P1_U2_MCQ_853","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_853","question":"Why should an HR department prepare both a 'job description' and a 'person specification' before advertising a vacancy?","options":{"A":"The job description clarifies the role's duties for applicants, while the person specification sets objective criteria to shortlist candidates fairly","B":"The job description sets the company's annual profit target, while the person specification replaces the employment contract","C":"The job description is shown only to rejected applicants, while the person specification is kept secret from interviewers","D":"Both documents are required by law to be published in national newspapers for every part-time job"},"correctOption":"A","correctAnswer":"The job description clarifies the role's duties for applicants, while the person specification sets objective criteria to shortlist candidates fairly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because together these documents prevent unsuitable applications and provide a consistent, non-discriminatory benchmark for shortlisting and interviewing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because neither document sets corporate profit targets or replaces the legal contract of employment.","C":"Incorrect because job details are shared with applicants and interviewers rely directly on the person specification.","D":"Incorrect because employers may advertise vacancies through any suitable channel without printing full internal documents in newspapers."}}},{"id":"P1_U2_MCQ_854","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_854","question":"A medium-sized manufacturing firm wants to recruit a qualified Chartered Accountant. Which advertising method is likely to attract the most suitable applicants?","options":{"A":"A specialist accountancy trade journal and a professional online recruitment portal","B":"A hand-written card pinned in the window of a local corner bakery","C":"A poster placed inside the factory's own staff changing room","D":"A loudspeaker announcement in a local shopping mall"},"correctOption":"A","correctAnswer":"A specialist accountancy trade journal and a professional online recruitment portal","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialist journals and professional job boards directly target qualified finance professionals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local shop windows reach general passers-by rather than specialist accountants.","C":"Incorrect because an internal changing-room notice reaches only current factory staff.","D":"Incorrect because shopping mall announcements are untargeted and unprofessional for senior finance roles."}}},{"id":"P1_U2_MCQ_855","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_855","question":"Why might a luxury hotel chain use 'psychometric (personality) tests' when selecting front-desk receptionists?","options":{"A":"To assess whether candidates possess patience, warmth, and emotional stability when dealing with demanding guests","B":"To test how fast candidates can assemble heavy industrial engine parts","C":"To verify whether candidates' university degrees are genuine","D":"To avoid holding face-to-face interviews with shortlisted applicants"},"correctOption":"A","correctAnswer":"To assess whether candidates possess patience, warmth, and emotional stability when dealing with demanding guests","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customer-facing hospitality roles require strong interpersonal temperament and stress tolerance, which psychometric tests help evaluate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because manual assembly speed is measured by a practical aptitude test, not a personality test.","C":"Incorrect because degree authenticity is checked through academic certificates and references.","D":"Incorrect because psychometric tests complement interviews rather than replacing them."}}},{"id":"P1_U2_MCQ_856","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_856","question":"A chemical processing plant requires all newly hired technicians to complete a three-day 'induction training' course before entering the production floor. What is the main reason for this policy?","options":{"A":"To ensure new hires understand strict emergency evacuation procedures, hazard controls, and protective equipment rules to prevent accidents","B":"To sponsor new hires for a three-year external university degree in chemistry","C":"To test whether new hires should be offered a job before signing an employment contract","D":"To prepare retiring employees for life after leaving the company"},"correctOption":"A","correctAnswer":"To ensure new hires understand strict emergency evacuation procedures, hazard controls, and protective equipment rules to prevent accidents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because induction training introduces new recruits to workplace layout, safety regulations, and colleagues so they operate safely from day one.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because university sponsorship is long-term off-the-job training.","C":"Incorrect because induction occurs after selection and contract acceptance.","D":"Incorrect because induction is for incoming recruits rather than departing retirees."}}},{"id":"P1_U2_MCQ_857","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_857","question":"A car manufacturer installs brand-new automated welding robots that none of its current technicians have ever operated. Which training approach is most suitable initially?","options":{"A":"Off-the-job training delivered by specialist engineers from the robotics supplier","B":"On-the-job training led by existing technicians who have never seen the robots before","C":"Skipping training altogether so workers learn by trial and error on customer vehicles","D":"Induction training focused solely on canteen meal times and payroll dates"},"correctOption":"A","correctAnswer":"Off-the-job training delivered by specialist engineers from the robotics supplier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when new specialist technology is introduced that no current employee knows how to use, external expert instruction is essential.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because existing staff cannot teach skills they do not yet possess.","C":"Incorrect because trial and error on expensive robotics causes safety hazards and costly damage.","D":"Incorrect because general orientation does not teach technical robot programming."}}},{"id":"P1_U2_MCQ_858","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_858","question":"A high-street clothing retailer experiences a gradual 12% decline in store sales over two years as shoppers switch online. Why might management choose 'natural wastage' rather than immediate 'compulsory redundancy'?","options":{"A":"It avoids expensive lump-sum redundancy payments and preserves morale among remaining store staff","B":"It reduces the store's wage bill immediately within a single week","C":"It allows management to dismiss senior staff without following any notice rules","D":"It forces every part-time worker to double their weekly working hours"},"correctOption":"A","correctAnswer":"It avoids expensive lump-sum redundancy payments and preserves morale among remaining store staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail typically has steady voluntary staff turnover, allowing the firm to shrink headcount smoothly without severance payouts or industrial unrest.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because natural wastage works gradually as staff voluntarily leave, whereas compulsory redundancy cuts costs faster.","C":"Incorrect because natural wastage involves no dismissals.","D":"Incorrect because reducing headcount due to lower footfall does not require doubling remaining hours."}}},{"id":"P1_U2_MCQ_859","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_859","question":"In which scenario has an employer committed 'unfair dismissal'?","options":{"A":"Sacking an employee immediately after discovering she is pregnant, despite her strong work record","B":"Dismissing a warehouse driver caught on camera stealing valuable electronics after a fair disciplinary hearing","C":"Making ten assembly workers redundant with statutory severance pay after closing an unprofitable factory","D":"Ending the employment of a clerk who failed to improve persistent lateness despite three formal written warnings"},"correctOption":"A","correctAnswer":"Sacking an employee immediately after discovering she is pregnant, despite her strong work record","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dismissing an employee due to pregnancy is unlawful discrimination and automatically unfair dismissal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because theft proven through a fair hearing is gross misconduct (fair dismissal).","C":"Incorrect because genuine factory closure with proper compensation is lawful redundancy.","D":"Incorrect because documented failure to improve after repeated warnings is a fair dismissal."}}},{"id":"P1_U2_MCQ_860","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_860","question":"How must an employer adapt its recruitment process to comply with 'anti-discrimination (equal opportunity) legislation'?","options":{"A":"Ensure job adverts avoid gender- or age-biased wording and ask all interview candidates consistent, job-related questions","B":"Hire equal numbers of men and women regardless of whether candidates hold required medical or engineering licenses","C":"Stop using person specifications or interviewing candidates before making job offers","D":"Ask female applicants about their future marriage and childcare plans during interviews"},"correctOption":"A","correctAnswer":"Ensure job adverts avoid gender- or age-biased wording and ask all interview candidates consistent, job-related questions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because neutral job adverts and standardized, merit-based interview questions ensure fair evaluation regardless of protected characteristics.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because genuine occupational qualifications and licenses remain essential and lawful.","C":"Incorrect because person specifications and interviews are key tools for fair, objective selection.","D":"Incorrect because questioning applicants about family plans is discriminatory and unlawful."}}},{"id":"P1_U2_MCQ_861","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_861","question":"How can complying strictly with 'health and safety legislation' generate long-term financial benefits for a construction firm?","options":{"A":"Fewer workplace accidents reduce sick-pay absences, compensation claims, project delays, and staff turnover","B":"Safety compliance allows the firm to pay construction workers below the legal minimum wage","C":"Safety inspectors award cash grants equal to 100% of the firm's annual wage bill","D":"The firm no longer needs to purchase building materials or insurance"},"correctOption":"A","correctAnswer":"Fewer workplace accidents reduce sick-pay absences, compensation claims, project delays, and staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because although safety gear and training cost money upfront, preventing injuries avoids costly downtime, legal fines, and reputational harm.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because minimum wage laws remain fully enforceable.","C":"Incorrect because regulators do not subsidize company payrolls.","D":"Incorrect because materials and statutory employer insurance remain necessary."}}},{"id":"P1_U2_MCQ_862","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_862","question":"Why is 'high labour turnover' costly for a service business such as a restaurant chain?","options":{"A":"It forces the business to repeatedly spend money on advertising, interviewing, and induction training while losing experienced staff","B":"It automatically increases customer loyalty because diners enjoy seeing unfamiliar waiters every week","C":"It lowers the statutory legal minimum wage that the restaurant must pay new hires","D":"It eliminates the need for supervisors to monitor food hygiene standards"},"correctOption":"A","correctAnswer":"It forces the business to repeatedly spend money on advertising, interviewing, and induction training while losing experienced staff","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constant staff departures drain management time, raise recruitment/training expenses, and reduce service consistency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because frequent staff changes often disrupt service quality and customer rapport.","C":"Incorrect because statutory minimum wages are set by government law, not turnover rates.","D":"Incorrect because new hires actually require closer supervision on hygiene standards."}}},{"id":"P1_U2_MCQ_863","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_863","question":"Which situation represents 'constructive dismissal'?","options":{"A":"An employer makes working conditions intolerable—such as cutting pay unilaterally or bullying—forcing the employee to resign","B":"An employee resigns happily after winning a promotion at another company","C":"An employer builds a brand-new factory and recruits fifty extra engineers","D":"An employee retires at age 65 with a full company pension"},"correctOption":"A","correctAnswer":"An employer makes working conditions intolerable—such as cutting pay unilaterally or bullying—forcing the employee to resign","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constructive dismissal occurs when an employer breaches the employment contract so seriously that the worker feels compelled to quit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leaving voluntarily for career advancement is a normal resignation.","C":"Incorrect because expanding facilities and hiring is business growth.","D":"Incorrect because scheduled retirement is not dismissal."}}},{"id":"P1_U2_MCQ_864","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_864","question":"In a company's organisational chart, the Operations Director directly supervises 4 Factory Managers, and each Factory Manager directly supervises 12 Team Leaders. What is the span of control of each Factory Manager?","options":{"A":"12","B":"4","C":"48","D":"16"},"correctOption":"A","correctAnswer":"12","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because span of control counts only the immediate subordinates reporting directly to that specific manager (12 Team Leaders).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 4 is the Operations Director's span of control.","C":"Incorrect because 48 is the total number of Team Leaders across all four factories combined.","D":"Incorrect because 16 adds the 4 Factory Managers and 12 Team Leaders together."}}},{"id":"P1_U2_MCQ_865","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_865","question":"Following a delayering exercise, a regional bank manager's span of control increases from 5 branch managers to 15 branch managers. What is the most likely immediate challenge?","options":{"A":"The regional manager has less time to coach each branch manager closely, increasing the need for effective delegation","B":"The chain of command between the Chief Executive and branch tellers becomes much longer","C":"Branch managers lose all operational autonomy and must wait longer for basic approvals","D":"Total regional management salary costs increase sharply"},"correctOption":"A","correctAnswer":"The regional manager has less time to coach each branch manager closely, increasing the need for effective delegation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tripling a manager's direct reports stretches supervisory time and requires greater trust and delegation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delayering shortens the chain of command.","C":"Incorrect because wider spans typically force managers to delegate more autonomy downward.","D":"Incorrect because removing a management tier lowers salary costs."}}},{"id":"P1_U2_MCQ_866","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_866","question":"Why is a 'tall' organisational structure with narrow spans of control often preferred in high-risk industries such as nuclear power plants?","options":{"A":"Close supervision and clear lines of accountability help prevent catastrophic safety mistakes","B":"Messages travel upward to the Chief Executive faster than in a flat two-tier startup","C":"Employees enjoy complete laissez-faire freedom to ignore standard operating checklists","D":"Management salary overheads are lower than in flat structures"},"correctOption":"A","correctAnswer":"Close supervision and clear lines of accountability help prevent catastrophic safety mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because narrow spans allow supervisors to monitor complex, safety-critical procedures closely and verify strict compliance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tall structures have longer chains of command and slower vertical communication.","C":"Incorrect because high-risk plants require strict adherence to safety protocols rather than laissez-faire freedom.","D":"Incorrect because multiple management tiers make tall hierarchies more expensive."}}},{"id":"P1_U2_MCQ_867","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_867","question":"An international hotel group allows general managers in each country to set local room rates, design regional restaurant menus, and hire local staff. Which organisational approach is this?","options":{"A":"Decentralisation","B":"Centralisation","C":"Autocratic central command","D":"Job rotation"},"correctOption":"A","correctAnswer":"Decentralisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because decentralisation delegates significant operational decision-making authority away from head office to regional or branch managers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because centralisation keeps pricing, menu, and hiring authority concentrated at head office.","C":"Incorrect because autocratic command centralizes power in a single leader.","D":"Incorrect because job rotation switches staff across peer-level tasks."}}},{"id":"P1_U2_MCQ_868","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_868","question":"A global luxury fashion brand insists that head office approves all window displays, retail prices, and advertising campaigns worldwide. Why does the brand use 'centralisation'?","options":{"A":"To protect an exclusive, uniform global brand image and maintain tight control over pricing","B":"To empower local store clerks to run unapproved discount sales whenever footfall dips","C":"To eliminate the need for senior brand directors at head office","D":"To encourage each store to sell completely different unbranded products"},"correctOption":"A","correctAnswer":"To protect an exclusive, uniform global brand image and maintain tight control over pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because luxury brands depend on consistent prestige, visual standards, and price integrity across every international boutique.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because local discounting is prevented by centralised pricing control.","C":"Incorrect because centralisation strengthens head-office executive control.","D":"Incorrect because centralisation enforces uniform product lines."}}},{"id":"P1_U2_MCQ_869","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_869","question":"How does a 'paternalistic' leader differ from a hard 'autocratic' leader?","options":{"A":"A paternalistic leader shows strong concern for employees' personal welfare and listens to views before deciding, whereas a hard autocratic leader focuses purely on issuing orders","B":"A paternalistic leader delegates 100% of strategic decisions to junior trainees, whereas an autocratic leader uses democratic votes","C":"A paternalistic leader never communicates with employees, whereas an autocratic leader holds daily social parties","D":"A paternalistic leader eliminates all company rules, whereas an autocratic leader bans financial wages"},"correctOption":"A","correctAnswer":"A paternalistic leader shows strong concern for employees' personal welfare and listens to views before deciding, whereas a hard autocratic leader focuses purely on issuing orders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while both retain final decision authority, a paternalistic leader takes a caring, protective interest in staff well-being to foster loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delegating complete autonomy describes laissez-faire leadership.","C":"Incorrect because paternalistic leaders actively engage with staff welfare.","D":"Incorrect because neither style eliminates rules or wages."}}},{"id":"P1_U2_MCQ_870","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_870","question":"A biotechnology firm employs a team of experienced PhD scientists researching new vaccines. Why is a 'laissez-faire' or 'democratic' leadership style likely to work better than an 'autocratic' style?","options":{"A":"Highly skilled specialists thrive when given intellectual autonomy to experiment and contribute ideas rather than following rigid top-down orders","B":"PhD scientists lack technical knowledge and need a supervisor dictating every microscope adjustment","C":"Laissez-faire leadership guarantees that vaccine trials require zero safety documentation","D":"Democratic leadership eliminates the need to pay scientists competitive salaries"},"correctOption":"A","correctAnswer":"Highly skilled specialists thrive when given intellectual autonomy to experiment and contribute ideas rather than following rigid top-down orders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because creative, expert professionals possess deep specialist knowledge and become demotivated under micromanagement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because experienced scientists possess superior technical expertise in their research field.","C":"Incorrect because scientific regulatory standards still apply regardless of leadership style.","D":"Incorrect because non-financial autonomy complements competitive pay rather than replacing it."}}},{"id":"P1_U2_MCQ_871","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_871","question":"A normally democratic retail manager switches to an 'autocratic' style when an electrical fire breaks out in the stockroom. Why is this change justified?","options":{"A":"Life-threatening emergencies require immediate, unambiguous commands rather than time-consuming group discussions","B":"Democratic leadership is illegal during afternoon retail shifts","C":"Autocratic leadership encourages staff to debate the best evacuation route for twenty minutes","D":"Employees prefer to vote on safety procedures while smoke fills the building"},"correctOption":"A","correctAnswer":"Life-threatening emergencies require immediate, unambiguous commands rather than time-consuming group discussions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective managers adapt their leadership style to situational urgency, issuing swift directives when safety is at risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leadership styles are management choices rather than time-of-day laws.","C":"Incorrect because autocratic leadership eliminates debate in favour of instant orders.","D":"Incorrect because rapid evacuation takes priority over consultation."}}},{"id":"P1_U2_MCQ_872","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_872","question":"Why is close coordination between the 'Marketing' and 'Operations' departments vital before launching a heavily advertised new smartphone?","options":{"A":"Operations must produce sufficient inventory on schedule to meet the customer demand generated by Marketing's campaign","B":"Operations sets the national corporation tax rate while Marketing audits the bank statements","C":"Marketing manufactures the smartphone microchips while Operations designs television commercials","D":"Coordination prevents customers from ever purchasing the new smartphone"},"correctOption":"A","correctAnswer":"Operations must produce sufficient inventory on schedule to meet the customer demand generated by Marketing's campaign","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if Marketing stimulates high demand before Operations has enough stock ready, the business suffers stockouts and disappointed customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because taxes are set by government and accounting is handled by Finance.","C":"Incorrect because this reverses the roles of Operations and Marketing.","D":"Incorrect because functional coordination aims to maximize successful sales."}}},{"id":"P1_U2_MCQ_873","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_873","question":"What is 'job sharing' as a flexible working arrangement?","options":{"A":"Two part-time employees split the duties, hours, and pay of a single full-time position between them","B":"One full-time worker performs two separate full-time jobs for two competing firms simultaneously","C":"Every factory worker rotates to a different machine every thirty minutes","D":"Employees share a single monthly wage packet equally across a whole department"},"correctOption":"A","correctAnswer":"Two part-time employees split the duties, hours, and pay of a single full-time position between them","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because job sharing allows a business to retain skilled staff who want part-time hours while ensuring full-time cover for the role.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because working two full-time jobs for competitors is moonlighting/conflict of interest.","C":"Incorrect because switching tasks periodically is job rotation.","D":"Incorrect because job sharers are paid pro-rata for the hours each works."}}},{"id":"P1_U2_MCQ_874","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_874","question":"How does 'work-to-rule' differ from 'strike action' during an industrial dispute?","options":{"A":"In work-to-rule, employees continue working but follow every contract rule and safety check strictly to slow output, whereas in a strike they stop working completely","B":"In work-to-rule, employees resign permanently, whereas in a strike they work unpaid overtime","C":"In work-to-rule, managers lock workers out of the factory, whereas in a strike the government sets product prices","D":"Work-to-rule is used only by company directors, whereas strikes are used only by customers"},"correctOption":"A","correctAnswer":"In work-to-rule, employees continue working but follow every contract rule and safety check strictly to slow output, whereas in a strike they stop working completely","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because work-to-rule reduces productivity while allowing employees to keep earning wages, whereas striking halts production and forfeits pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees neither resign during work-to-rule nor work free overtime during a strike.","C":"Incorrect because management locking workers out is a lockout, not work-to-rule.","D":"Incorrect because both are forms of trade union industrial action by employees."}}},{"id":"P1_U2_MCQ_875","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_875","question":"What is a major negative impact of prolonged 'strike action' on a manufacturing business?","options":{"A":"Lost output and missed delivery deadlines lead to lower sales revenue, damaged customer reputation, and ongoing fixed costs","B":"The business achieves record production output while paying zero raw-material costs","C":"Customer loyalty increases because retailers enjoy empty shelves","D":"Competitors voluntarily pause their own production until the strike ends"},"correctOption":"A","correctAnswer":"Lost output and missed delivery deadlines lead to lower sales revenue, damaged customer reputation, and ongoing fixed costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because halted production stops revenue generation while fixed overheads (rent, loan interest) continue, driving customers to competitors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because production stops during a strike.","C":"Incorrect because stock shortages frustrate customers and harm brand reputation.","D":"Incorrect because rivals capitalize on strikes to capture market share."}}},{"id":"P1_U2_MCQ_876","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_876","question":"A logistics manager emails an urgent weekend shift change to 80 warehouse packers who do not have company computers or smartphones at work, and many fail to turn up. What was the primary communication barrier?","options":{"A":"Choosing an inappropriate communication medium that receivers could not access in time","B":"Using excessive visual diagrams on the warehouse noticeboard","C":"Holding too many face-to-face team briefings before the shift","D":"Over-reliance on two-way verbal feedback"},"correctOption":"A","correctAnswer":"Choosing an inappropriate communication medium that receivers could not access in time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sending an email to non-desk staff without email access prevents the message from reaching the intended receivers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the manager used email rather than visual noticeboards.","C":"Incorrect because a face-to-face briefing would have reached the warehouse staff effectively.","D":"Incorrect because there was no two-way feedback confirming receipt."}}},{"id":"P1_U2_MCQ_877","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_877","question":"A company is introducing a complex new employee pension scheme affecting 400 staff. Which combination of communication methods is most effective?","options":{"A":"Face-to-face or virtual Q&A briefings supported by a clear written guide on the company intranet and email","B":"A single 120-character text message (SMS) sent to staff mobile phones","C":"Relying solely on the informal office grapevine to spread the pension details","D":"A one-line poster pinned in the car park without any contact person for questions"},"correctOption":"A","correctAnswer":"Face-to-face or virtual Q&A briefings supported by a clear written guide on the company intranet and email","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because complex financial policies need permanent written reference material plus two-way briefings so employees can ask questions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an SMS is far too brief to explain complex pension rules.","C":"Incorrect because relying on informal gossip guarantees inaccurate rumours.","D":"Incorrect because a brief poster lacks detail and provides no two-way feedback."}}},{"id":"P1_U2_MCQ_878","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_878","question":"Why do public limited companies present annual financial results using both a detailed written annual report and a live verbal presentation with charts?","options":{"A":"The written report provides a permanent, legally verifiable record of figures, while the presentation highlights key trends and allows live shareholder questions","B":"Written reports cannot include numbers, whereas spoken presentations cannot be understood by investors","C":"Using two methods allows the company to report different profit figures to different shareholders","D":"Live presentations are legally required to be held without any visual slides or handouts"},"correctOption":"A","correctAnswer":"The written report provides a permanent, legally verifiable record of figures, while the presentation highlights key trends and allows live shareholder questions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because combining permanent written documentation with interactive visual presentation maximizes clarity, accuracy, and two-way engagement.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because written reports contain full numerical statements and investors follow presentations readily.","C":"Incorrect because financial figures must be accurate and consistent across all reports.","D":"Incorrect because visual slides and charts are standard tools in shareholder briefings."}}},{"id":"P1_U2_MCQ_879","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_879","question":"Why is 'two-way communication' particularly important when a business plans to reorganize factory shift patterns?","options":{"A":"Employees can raise practical scheduling concerns and feel consulted, reducing resistance and improving implementation","B":"Two-way communication takes less time than pinning up a one-line notice","C":"Two-way communication guarantees that management never has to listen to worker feedback","D":"Two-way communication prevents workers from understanding the new shift hours"},"correctOption":"A","correctAnswer":"Employees can raise practical scheduling concerns and feel consulted, reducing resistance and improving implementation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consulting workers uncovers childcare or transport issues early and builds staff buy-in for organizational change.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because two-way discussion takes longer than a one-way directive, though it yields better cooperation.","C":"Incorrect because two-way communication specifically involves listening to receiver responses.","D":"Incorrect because dialogue clarifies expectations and reduces misunderstandings."}}},{"id":"P1_U2_MCQ_880","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_880","question":"A European clothing retailer coordinates production with suppliers in East Asia. How do geographical distance and time-zone differences create communication barriers?","options":{"A":"Limited overlapping office hours delay live phone or video discussions, slowing down urgent design clarifications","B":"Time-zone differences make it illegal to send international emails or attached files","C":"Geographical distance prevents suppliers from reading written product specifications","D":"International suppliers always refuse to use video conferencing software"},"correctOption":"A","correctAnswer":"Limited overlapping office hours delay live phone or video discussions, slowing down urgent design clarifications","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when one office closes as the other opens, real-time two-way feedback is restricted to narrow windows, extending turnaround times.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because international emails are completely legal and widely used.","C":"Incorrect because written specifications can be transmitted electronically across any distance.","D":"Incorrect because video conferencing is standard in global trade, constrained mainly by time-zone overlap."}}},{"id":"P1_U2_MCQ_881","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_881","question":"An IT supervisor sends a complex 15-step server reboot procedure via a series of rapid SMS text messages instead of a structured email or manual. What is the main risk?","options":{"A":"Messages may arrive out of order or be truncated, causing technical errors during the reboot","B":"SMS messages take three days to reach a technician's mobile phone","C":"The technician will experience excessive face-to-face body language cues","D":"SMS messages cannot contain any numbers or punctuation marks"},"correctOption":"A","correctAnswer":"Messages may arrive out of order or be truncated, causing technical errors during the reboot","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because SMS is designed for brief alerts; multi-step technical instructions require a structured written document or email attachment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because SMS messages deliver almost instantaneously.","C":"Incorrect because text messages contain no visual body language cues.","D":"Incorrect because SMS supports numbers and punctuation, though character limits hinder long manuals."}}},{"id":"P1_U2_MCQ_882","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_882","question":"What is a major risk when a business responds defensively or rudely to a customer complaint on a public social media platform?","options":{"A":"Thousands of potential customers can view and share the negative exchange instantly, damaging brand reputation","B":"The complaint automatically remains completely private between the manager and the single customer","C":"Social media platforms delete all negative customer comments within ten seconds","D":"The business gains statutory immunity from consumer protection laws"},"correctOption":"A","correctAnswer":"Thousands of potential customers can view and share the negative exchange instantly, damaging brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public social media interactions are visible worldwide and can go viral, making polite, rapid resolution essential.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public posts are visible to everyone unless moved to private direct messaging.","C":"Incorrect because platforms do not automatically remove critical customer reviews.","D":"Incorrect because consumer protection laws apply regardless of online responses."}}},{"id":"P1_U2_MCQ_883","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_883","question":"How does combining a 'noticeboard poster' with a short 'team briefing' improve internal workplace communication?","options":{"A":"The briefing allows immediate two-way questions and clarification, while the poster provides a permanent visual reminder afterward","B":"The combination eliminates the need for managers to prepare clear messages","C":"The poster ensures that remote home workers see the notice without logging online","D":"The briefing converts two-way communication into strictly one-way communication"},"correctOption":"A","correctAnswer":"The briefing allows immediate two-way questions and clarification, while the poster provides a permanent visual reminder afterward","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pairing spoken two-way dialogue with a visual permanent reference overcomes the limitations of relying on either medium alone.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because clear message preparation remains vital.","C":"Incorrect because physical workplace posters are not visible to remote home workers.","D":"Incorrect because team briefings add two-way interaction to a one-way poster."}}},{"id":"P1_U2_MCQ_884","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_884","question":"Which of the following is an example of an 'upward communication' channel inside a business?","options":{"A":"An employee suggestion scheme, staff attitude survey, or feedback passed through a trade union representative","B":"A company-wide policy handbook issued by the Board of Directors","C":"A television commercial promoting a summer clearance sale to shoppers","D":"A purchase order sent by the Operations Manager to a raw-material supplier"},"correctOption":"A","correctAnswer":"An employee suggestion scheme, staff attitude survey, or feedback passed through a trade union representative","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suggestion schemes and surveys enable frontline employees to communicate ideas and concerns upward to senior management.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a board-issued policy handbook is downward communication.","C":"Incorrect because a TV advert is external communication to consumers.","D":"Incorrect because a supplier purchase order is external business communication."}}},{"id":"P1_U2_MCQ_885","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_885","question":"Why do middle managers in a tall hierarchy sometimes filter or soften bad news (such as falling factory quality) before passing reports upward to senior directors?","options":{"A":"Fear of blame or damaged promotion prospects leads intermediate managers to distort upward messages, depriving directors of accurate facts","B":"Senior directors prohibit middle managers from ever submitting written reports","C":"Tall hierarchies have spans of control that are too wide for middle managers to read reports","D":"Middle managers are rewarded with bonuses whenever quality defects increase"},"correctOption":"A","correctAnswer":"Fear of blame or damaged promotion prospects leads intermediate managers to distort upward messages, depriving directors of accurate facts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each extra tier in a tall hierarchy creates an opportunity for self-protective filtering, distorting upward communication.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because senior directors rely on regular management reports.","C":"Incorrect because tall hierarchies feature narrow spans of control.","D":"Incorrect because rising defects negatively affect managerial evaluations."}}},{"id":"P1_U2_MCQ_886","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_886","question":"How does a clear 'organisational chart' help reduce internal communication barriers?","options":{"A":"Employees know exactly who holds authority for specific decisions and which manager to report problems to","B":"It replaces the need for face-to-face meetings or written emails across departments","C":"It guarantees that employees never use technical jargon in reports","D":"It eliminates all physical machinery noise on the factory floor"},"correctOption":"A","correctAnswer":"Employees know exactly who holds authority for specific decisions and which manager to report problems to","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because defined reporting lines and departmental roles prevent messages from being sent to the wrong person or ignored.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because staff still use meetings and emails along the defined channels.","C":"Incorrect because avoiding jargon requires careful message encoding.","D":"Incorrect because organisational charts do not affect physical noise levels."}}},{"id":"P1_U2_MCQ_887","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_887","question":"Why can relying exclusively on written emails rather than face-to-face meetings cause misunderstandings during sensitive negotiations?","options":{"A":"Written text lacks facial expressions, vocal tone, and body language, making blunt phrasing easy to misinterpret as hostile","B":"Emails take longer to transmit across an office than sending a courier by train","C":"Receivers are legally forbidden from replying to emails from managers","D":"Emails cannot be saved or printed for future reference"},"correctOption":"A","correctAnswer":"Written text lacks facial expressions, vocal tone, and body language, making blunt phrasing easy to misinterpret as hostile","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-verbal cues convey empathy, humour, or urgency; without them, brief emails can seem cold or aggressive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because emails transmit instantaneously.","C":"Incorrect because two-way email replies are standard practice.","D":"Incorrect because creating a permanent saved record is a key strength of email."}}},{"id":"P1_U2_MCQ_888","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_888","question":"What is a likely operational consequence of poor 'external communication' between a manufacturer's purchasing team and its raw-material suppliers?","options":{"A":"Incorrect component specifications or late deliveries halt assembly lines and delay customer orders","B":"Internal employee morale rises because factory machines stand idle","C":"The manufacturer automatically receives a 20% discount on all future invoices","D":"Marketing campaigns become more accurate without needing product launch dates"},"correctOption":"A","correctAnswer":"Incorrect component specifications or late deliveries halt assembly lines and delay customer orders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inaccurate order details or missed schedule updates disrupt just-in-time supply chains and stop production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because idle production lines cause frustration and lost piece-rate or bonus earnings.","C":"Incorrect because miscommunication leads to costly rework or rush-delivery fees rather than discounts.","D":"Incorrect because production delays disrupt planned marketing launches."}}},{"id":"P1_U2_MCQ_889","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_889","question":"A garment factory introduces piece-rate pay for sewing machinists. Output rises by 25%, but customer returns for loose stitching triple. What does this illustrate about F.W. Taylor's motivation approach?","options":{"A":"Paying strictly per unit encourages speed over craftsmanship, requiring strong quality inspection to prevent defective goods","B":"Workers are never motivated by financial incentives when sewing garments","C":"Piece-rate pay always lowers daily output volume while raising product quality","D":"Taylor's theory focuses exclusively on job enrichment and autonomous teamwork"},"correctOption":"A","correctAnswer":"Paying strictly per unit encourages speed over craftsmanship, requiring strong quality inspection to prevent defective goods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because piece-rate rewards quantity produced, so workers may rush stitching unless strict quality controls reject faulty items.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the 25% output increase shows workers responded strongly to the financial incentive.","C":"Incorrect because piece-rate typically raises output speed while risking lower quality.","D":"Incorrect because job enrichment and autonomous teams reflect Herzberg's ideas rather than Taylor's."}}},{"id":"P1_U2_MCQ_890","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_890","question":"A software company already pays its graduate engineers well and offers permanent contracts and friendly team offices, yet many leave after two years citing lack of challenge. According to Maslow, which needs must the firm now address?","options":{"A":"Esteem and self-actualization needs, through greater creative autonomy, recognition, and promotion pathways","B":"Physiological needs, by providing subsidized bread and water in the office","C":"Safety needs, by issuing hard hats and steel-toe boots to desk programmers","D":"Social needs, by moving engineers into isolated windowless cubicles"},"correctOption":"A","correctAnswer":"Esteem and self-actualization needs, through greater creative autonomy, recognition, and promotion pathways","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once lower-order survival, security, and social needs are met, higher-order recognition and personal fulfilment drive retention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because basic physiological needs are already satisfied by their good salaries.","C":"Incorrect because permanent contracts already meet job security needs and programmers do not face construction hazards.","D":"Incorrect because friendly team offices already satisfy social needs, and isolation would harm them."}}},{"id":"P1_U2_MCQ_891","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_891","question":"Call-centre staff are highly demotivated because the air conditioning is broken, chairs are uncomfortable, and supervisors are rude. According to Frederick Herzberg, what must management fix first?","options":{"A":"These poor hygiene factors (working conditions and supervision) to remove active job dissatisfaction before motivators can work","B":"Introduce an 'Employee of the Month' badge while leaving the broken air conditioning unfixed","C":"Replace all basic salaries with unpaid voluntary job rotation","D":"Lengthen the chain of command by hiring four extra layers of call-centre directors"},"correctOption":"A","correctAnswer":"These poor hygiene factors (working conditions and supervision) to remove active job dissatisfaction before motivators can work","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg emphasized that inadequate physical working conditions and poor supervision create strong dissatisfaction that prevents positive motivation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recognition awards cannot compensate for unhealthy, uncomfortable working conditions.","C":"Incorrect because removing salaries violates minimum wage laws and worsens dissatisfaction.","D":"Incorrect because adding management layers does not repair physical conditions or supervisory behaviour."}}},{"id":"P1_U2_MCQ_892","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_892","question":"To apply Frederick Herzberg's 'motivators' in a customer-service centre, which job redesign would be most effective?","options":{"A":"Empowering agents to resolve customer refunds independently up to $200 without supervisor sign-off, paired with regular feedback on achievements","B":"Installing brighter ceiling lights and repainting the staff breakroom walls","C":"Requiring agents to read a rigid word-for-word script on every phone call","D":"Increasing basic hourly pay by 2% while keeping all tasks identical"},"correctOption":"A","correctAnswer":"Empowering agents to resolve customer refunds independently up to $200 without supervisor sign-off, paired with regular feedback on achievements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because granting decision-making responsibility and recognizing personal achievement directly provide Herzberg's intrinsic motivators.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lighting and breakroom decor are extrinsic hygiene factors.","C":"Incorrect because rigid scripts remove autonomy and increase boredom.","D":"Incorrect because basic pay is classified by Herzberg as a hygiene factor."}}},{"id":"P1_U2_MCQ_893","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_893","question":"Why might a seasonal fruit-picking farm rely primarily on 'piece-rate financial incentives', whereas an advertising agency relies more on 'non-financial motivators' such as creative freedom and recognition?","options":{"A":"Fruit picking has easily measurable unit output suited to short-term pay incentives, whereas advertising requires creative problem-solving that cannot be counted per unit","B":"Advertising executives are legally forbidden from receiving cash salaries or bonuses","C":"Seasonal farm workers do not value earning extra money during harvest weeks","D":"Creative advertising agencies forbid employees from sharing ideas in teams"},"correctOption":"A","correctAnswer":"Fruit picking has easily measurable unit output suited to short-term pay incentives, whereas advertising requires creative problem-solving that cannot be counted per unit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the nature of the task and measurability of output determine whether financial piece-rates or intrinsic creative motivators are effective.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising staff receive competitive salaries alongside non-financial motivators.","C":"Incorrect because seasonal workers strongly value maximizing earnings during short harvest contracts.","D":"Incorrect because creative agencies thrive on collaborative brainstorming."}}},{"id":"P1_U2_MCQ_894","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_894","question":"A car dealership pays its sales staff a very low basic salary plus a high 'commission' on every vehicle sold. What is a major risk of this payment structure?","options":{"A":"Sales staff may use aggressive high-pressure tactics to sell unsuitable cars, harming long-term customer trust and brand reputation","B":"Sales staff have zero financial incentive to approach customers entering the showroom","C":"The dealership faces huge fixed monthly wage bills even when zero cars are sold","D":"Top-performing salespeople earn the exact same monthly income as the lowest performers"},"correctOption":"A","correctAnswer":"Sales staff may use aggressive high-pressure tactics to sell unsuitable cars, harming long-term customer trust and brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heavy reliance on commission can encourage short-term pushy selling at the expense of honest customer service and repeat business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commission creates a strong financial drive to close sales.","C":"Incorrect because low basic pay keeps fixed wage costs low during quiet months.","D":"Incorrect because earnings vary directly with individual sales performance."}}},{"id":"P1_U2_MCQ_895","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_895","question":"Why might a management consultancy introduce a company-wide 'profit-sharing scheme' rather than individual piece-rate bonuses?","options":{"A":"Consultancy projects depend on cooperative teamwork across departments, and profit sharing encourages everyone to help boost overall firm profitability","B":"Profit sharing guarantees payouts even when the consultancy makes a heavy financial loss","C":"Individual piece-rate bonuses work best when output cannot be measured in physical units","D":"Profit sharing eliminates the need to pay consultants a regular monthly salary"},"correctOption":"A","correctAnswer":"Consultancy projects depend on cooperative teamwork across departments, and profit sharing encourages everyone to help boost overall firm profitability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because service consultancies rely on collective knowledge-sharing, which individual piece-rates would undermine.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit-sharing payouts occur only when the business generates a profit.","C":"Incorrect because piece-rates fail when output cannot be counted in uniform physical units.","D":"Incorrect because profit sharing supplements regular salaries."}}},{"id":"P1_U2_MCQ_896","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_896","question":"How do 'fringe benefits' such as subsidized workplace childcare and private health insurance benefit an employer?","options":{"A":"They help attract and retain skilled staff in competitive labour markets and can reduce absenteeism","B":"They allow the employer to pay hourly wages below the national statutory minimum wage","C":"They are completely free for the employer to provide","D":"They replace the need for effective management leadership or safe working conditions"},"correctOption":"A","correctAnswer":"They help attract and retain skilled staff in competitive labour markets and can reduce absenteeism","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tailored perks differentiate the employer from rivals, improve employee well-being, and lower costly staff turnover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because statutory minimum wage floors must still be met in cash pay.","C":"Incorrect because fringe benefits represent a real non-wage cost to the business.","D":"Incorrect because perks supplement rather than replace good management and safety."}}},{"id":"P1_U2_MCQ_897","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_897","question":"An automotive plant introduces 'job rotation' so workers switch between four assembly stations every two hours. What is the main operational trade-off for management?","options":{"A":"Higher training costs to multi-skill workers across four stations, balanced against lower boredom and flexible absence cover","B":"Zero training costs, balanced against workers losing all ability to cover absent colleagues","C":"Lower product quality due to every worker gaining executive budget authority","D":"Higher labour turnover because workers prefer performing one repetitive motion all day"},"correctOption":"A","correctAnswer":"Higher training costs to multi-skill workers across four stations, balanced against lower boredom and flexible absence cover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees must be trained safely on multiple tasks upfront, which pays off through reduced monotony and seamless shift cover.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because multi-skilling requires initial cross-training and directly improves absence cover.","C":"Incorrect because job rotation moves workers across peer-level tasks rather than granting budget authority.","D":"Incorrect because reducing repetitive strain and boredom generally lowers turnover."}}},{"id":"P1_U2_MCQ_898","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_898","question":"A retail bank trains branch clerks to assess and approve small personal loans independently instead of referring every application to the branch manager. Which motivational technique is this?","options":{"A":"Job enrichment","B":"Job rotation","C":"Piece-rate pay","D":"Natural wastage"},"correctOption":"A","correctAnswer":"Job enrichment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adding higher-level decision-making responsibility and skill to a clerk's role vertically enriches the job.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because job rotation switches staff across routine tasks of the same skill level.","C":"Incorrect because piece-rate is a financial wage per physical unit produced.","D":"Incorrect because natural wastage is a method of reducing workforce headcount."}}},{"id":"P1_U2_MCQ_899","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_899","question":"How does an annual 'performance appraisal' interview support both employee motivation and human resource management?","options":{"A":"It recognizes past achievements, sets clear future goals, and identifies training needs for career progression","B":"It serves solely to issue immediate summary dismissals without prior warnings","C":"It replaces the employee's written contract of employment every twelve months","D":"It prevents employees from expressing their career aspirations or feedback to managers"},"correctOption":"A","correctAnswer":"It recognizes past achievements, sets clear future goals, and identifies training needs for career progression","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because constructive appraisals provide recognition (esteem/motivator), align individual targets with business goals, and guide training budgets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because appraisals focus on developmental feedback rather than summary dismissal.","C":"Incorrect because employment contracts remain valid without annual replacement.","D":"Incorrect because effective appraisals encourage two-way dialogue about career growth."}}},{"id":"P1_U2_MCQ_900","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_900","question":"A hotel manager consults housekeeping teams on how to streamline room-cleaning checklists (democratic leadership) and delegates responsibility for final room quality inspections to senior attendants (job enrichment). What is the combined expected outcome?","options":{"A":"Higher intrinsic motivation, stronger accountability for service standards, and lower staff turnover","B":"Longer chains of command and slower communication with hotel guests","C":"Higher recruitment advertising costs due to dissatisfied employees resigning","D":"Complete elimination of fair basic wages as a hygiene factor"},"correctOption":"A","correctAnswer":"Higher intrinsic motivation, stronger accountability for service standards, and lower staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because combining participative consultation with meaningful responsibility satisfies higher-order needs (Maslow) and motivators (Herzberg), boosting quality and retention.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because empowering frontline attendants speeds up operational decisions rather than lengthening the hierarchy.","C":"Incorrect because higher job satisfaction reduces turnover and recruitment costs.","D":"Incorrect because fair pay remains a necessary hygiene factor alongside non-financial motivators."}}},{"id":"P1_U2_MCQ_901","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_901","question":"When is a business most likely to use 'headhunting' (executive search) rather than general online job boards?","options":{"A":"When recruiting fifty seasonal warehouse packers for a two-week holiday rush","B":"When seeking a highly experienced senior executive or rare specialist who may not be actively job-hunting","C":"When filling an entry-level cleaner vacancy at minimum wage","D":"When promoting an internal store supervisor to assistant manager"},"correctOption":"B","correctAnswer":"When seeking a highly experienced senior executive or rare specialist who may not be actively job-hunting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because headhunters proactively identify, approach, and persuade top-performing senior leaders or scarce specialists to apply.","distractor_reasons":{"A":"Incorrect because temporary seasonal labour is recruited far more cheaply via job centres or general adverts.","B":"Correct selection.","C":"Incorrect because high headhunter fees are unjustified for routine entry-level roles.","D":"Incorrect because internal promotion recruits from existing staff without external executive search."}}},{"id":"P1_U2_MCQ_902","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_902","question":"What is a major advantage to a small business of advertising vacancies through a government-run 'job centre'?","options":{"A":"It guarantees that every applicant holds a postgraduate management degree","B":"It automatically conducts legal reference checks and writes employment contracts","C":"It is free or very low-cost and quickly reaches local unemployed jobseekers for routine or semi-skilled roles","D":"It targets senior international executives working at rival multinational corporations"},"correctOption":"C","correctAnswer":"It is free or very low-cost and quickly reaches local unemployed jobseekers for routine or semi-skilled roles","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public job centres advertise vacancies at little or no expense, making them ideal for local retail, hospitality, or factory roles.","distractor_reasons":{"A":"Incorrect because job centres serve a broad local labour pool rather than exclusively postgraduates.","B":"Incorrect because the hiring employer remains responsible for reference checks and employment contracts.","C":"Correct selection.","D":"Incorrect because targeting employed senior rivals requires headhunting or specialist trade media."}}},{"id":"P1_U2_MCQ_903","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_903","question":"Which metric best helps an HR manager evaluate whether a recent recruitment campaign selected the right candidates?","options":{"A":"The total number of views received by the online job advertisement","B":"The length of the written job description in pages","C":"The number of external employment agencies contacted","D":"The proportion of new hires who pass their probation period and remain with the business after one year"},"correctOption":"D","correctAnswer":"The proportion of new hires who pass their probation period and remain with the business after one year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strong probation pass rates and one-year retention prove that hires possessed the required skills and cultural fit.","distractor_reasons":{"A":"Incorrect because high advert views measure reach rather than candidate quality or retention.","B":"Incorrect because document length does not measure hiring success.","C":"Incorrect because agency contacts reflect search effort rather than post-hire performance.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_904","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_904","question":"Why do HR departments use a standardized interview scoring sheet linked to the person specification?","options":{"A":"To reduce interviewer bias, ensure all candidates are judged against identical criteria, and provide legal evidence of fair selection","B":"To avoid asking candidates any questions about their past work experience","C":"To eliminate the need to check shortlisted candidates' references","D":"To ensure that internal applicants are always rejected in favour of external applicants"},"correctOption":"A","correctAnswer":"To reduce interviewer bias, ensure all candidates are judged against identical criteria, and provide legal evidence of fair selection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because structured scoring prevents personal prejudice and demonstrates compliance with anti-discrimination legislation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because structured interviews directly assess relevant past experience.","C":"Incorrect because reference checks remain an important verification step.","D":"Incorrect because fair scoring evaluates internal and external applicants on equal merit."}}},{"id":"P1_U2_MCQ_905","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_905","question":"What is a major advantage to a hospitality business of employing staff on 'zero-hours contracts'?","options":{"A":"Employees show exceptionally high long-term loyalty and low turnover","B":"The business is exempted from paying the statutory minimum wage per hour worked","C":"Management pays wages only for hours actually worked and can scale staffing up or down rapidly with unpredictable customer demand","D":"Staff require zero induction or food-safety training before starting shifts"},"correctOption":"C","correctAnswer":"Management pays wages only for hours actually worked and can scale staffing up or down rapidly with unpredictable customer demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because zero-hours contracts carry no guaranteed minimum weekly hours, giving employers maximum scheduling and wage-cost flexibility.","distractor_reasons":{"A":"Incorrect because income insecurity often leads to higher staff turnover.","B":"Incorrect because minimum wage laws still apply to every hour actually worked.","C":"Correct selection.","D":"Incorrect because all workers still require safety and operational induction."}}},{"id":"P1_U2_MCQ_906","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_906","question":"What is a primary disadvantage of 'zero-hours contracts' for employees and potentially for service quality?","options":{"A":"Workers are forced to work 60 hours every week without holidays","B":"Income instability causes financial stress and lower commitment, and workers may refuse short-notice shifts if they take second jobs","C":"Workers are paid an annual fixed salary regardless of attendance","D":"Employees are legally prohibited from joining a trade union"},"correctOption":"B","correctAnswer":"Income instability causes financial stress and lower commitment, and workers may refuse short-notice shifts if they take second jobs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unpredictable hours make budgeting difficult for workers, reducing morale and availability when the employer suddenly needs cover.","distractor_reasons":{"A":"Incorrect because zero-hours contracts guarantee no fixed weekly hours.","B":"Correct selection.","C":"Incorrect because zero-hours staff are paid only for hours worked rather than a fixed salary.","D":"Incorrect because union membership rights remain protected by law."}}},{"id":"P1_U2_MCQ_907","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_907","question":"Why do ski resorts and theme parks commonly use 'fixed-term temporary contracts'?","options":{"A":"To avoid following workplace health and safety laws during peak season","B":"To eliminate the need for supervising new hires","C":"To pay temporary staff half the statutory minimum wage","D":"To expand workforce capacity during predictable peak seasons without incurring redundancy costs when demand drops"},"correctOption":"D","correctAnswer":"To expand workforce capacity during predictable peak seasons without incurring redundancy costs when demand drops","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed-term contracts end automatically on an agreed date, matching seasonal tourism demand cleanly.","distractor_reasons":{"A":"Incorrect because health and safety laws protect temporary and permanent workers equally.","B":"Incorrect because seasonal recruits require close induction and supervision.","C":"Incorrect because statutory minimum wages apply to temporary staff.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_908","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_908","question":"Why does an employment contract normally specify a 'notice period' that both employer and employee must give before ending employment?","options":{"A":"To give the employer time to recruit a replacement and give the employee time to find alternative work","B":"To prevent employees from ever resigning from the company","C":"To allow the employer to withhold earned wages if an employee retires","D":"To replace statutory redundancy pay when a factory closes"},"correctOption":"A","correctAnswer":"To give the employer time to recruit a replacement and give the employee time to find alternative work","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because notice periods protect operational continuity for the business and financial transition time for the worker.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because employees may resign freely once they serve or give agreed notice.","C":"Incorrect because employees must always be paid for work performed.","D":"Incorrect because redundancy compensation is separate from contractual notice."}}},{"id":"P1_U2_MCQ_909","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_909","question":"What happens if an employee wins an 'unfair dismissal' claim against an employer at an employment tribunal?","options":{"A":"The employee is forced to pay the employer's legal fees","B":"The employer may be ordered to pay financial compensation to the employee or reinstate them, alongside suffering reputational damage","C":"The business is automatically exempted from all future employment regulations","D":"The employee's former colleagues lose their statutory holiday entitlement"},"correctOption":"B","correctAnswer":"The employer may be ordered to pay financial compensation to the employee or reinstate them, alongside suffering reputational damage","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tribunals penalize unlawful dismissal through monetary awards, reinstatement orders, and public rulings that harm employer reputation.","distractor_reasons":{"A":"Incorrect because the losing employer bears compensation and legal costs.","B":"Correct selection.","C":"Incorrect because employment laws continue to bind the business.","D":"Incorrect because coworkers' statutory rights are unaffected."}}},{"id":"P1_U2_MCQ_910","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_910","question":"What is required of employers under 'equal pay legislation'?","options":{"A":"Every employee from the CEO to an entry-level trainee must receive the exact same annual salary","B":"Employers must pay men higher wages than women if they have larger families","C":"Men and women performing the same job or work of equal value must receive equal pay and contractual benefits","D":"Part-time workers must be paid a higher hourly rate than full-time workers doing identical tasks"},"correctOption":"C","correctAnswer":"Men and women performing the same job or work of equal value must receive equal pay and contractual benefits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because equal pay laws prohibit gender-based pay disparities for equivalent work.","distractor_reasons":{"A":"Incorrect because pay differences based on skill, responsibility, or seniority remain lawful.","B":"Incorrect because paying different rates based on gender or family status is unlawful.","C":"Correct selection.","D":"Incorrect because part-time staff are entitled to pro-rata equal hourly pay, not higher rates."}}},{"id":"P1_U2_MCQ_911","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_911","question":"How does 'disability discrimination legislation' affect workplace recruitment and management?","options":{"A":"Employers must reject any applicant with a physical or mental impairment automatically","B":"Employers are forbidden from asking candidates about their ability to perform core job duties","C":"Disabled employees are exempt from following workplace safety rules","D":"Employers must not treat disabled applicants or staff unfavourably and must make reasonable workplace adjustments to remove barriers"},"correctOption":"D","correctAnswer":"Employers must not treat disabled applicants or staff unfavourably and must make reasonable workplace adjustments to remove barriers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because anti-discrimination laws require reasonable adjustments—such as wheelchair ramps or screen-reading software—so qualified disabled staff can work fairly.","distractor_reasons":{"A":"Incorrect because automatic rejection based on disability is unlawful discrimination.","B":"Incorrect because employers may assess genuine job competence once reasonable adjustments are considered.","C":"Incorrect because safety regulations protect all employees.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_912","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_912","question":"A retail store publishes a job advert requesting 'young, energetic school-leavers under 22' for a cashier role. Why is this problematic?","options":{"A":"It breaches age-discrimination laws by excluding older qualified applicants without an objective legal justification","B":"It guarantees that too many retired accountants will apply for the cashier job","C":"Cashiers under 22 are legally forbidden from operating electronic tills","D":"Job adverts are legally required to specify an exact maximum age limit"},"correctOption":"A","correctAnswer":"It breaches age-discrimination laws by excluding older qualified applicants without an objective legal justification","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specifying arbitrary age limits deters older applicants and violates equal opportunity legislation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the wording excludes older candidates rather than attracting them.","C":"Incorrect because young adults can lawfully operate cash registers.","D":"Incorrect because age restrictions are unlawful unless objectively justified."}}},{"id":"P1_U2_MCQ_913","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_913","question":"Why must an office-based software company still conduct regular 'health and safety risk assessments' even though it operates no heavy factory machinery?","options":{"A":"To calculate annual corporate income tax deductions","B":"To identify and prevent office hazards such as electrical faults, fire risks, trailing cables, and ergonomic eye or back strain","C":"To prove to competitors that employees never take lunch breaks","D":"To exempt the company from providing fire extinguishers or first-aid kits"},"correctOption":"B","correctAnswer":"To identify and prevent office hazards such as electrical faults, fire risks, trailing cables, and ergonomic eye or back strain","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because health and safety laws apply to all workplaces, addressing fire safety, workstation ergonomics, and slip/trip hazards.","distractor_reasons":{"A":"Incorrect because risk assessments address worker safety rather than tax accounting.","B":"Correct selection.","C":"Incorrect because rest breaks are required for health and safety.","D":"Incorrect because fire safety and first-aid equipment remain mandatory."}}},{"id":"P1_U2_MCQ_914","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_914","question":"How can a statutory increase in the 'legal minimum wage' create an indirect operational benefit for a retail business?","options":{"A":"It eliminates the need for managers to schedule staff shifts","B":"It lowers the store's total monthly payroll bill automatically","C":"Higher take-home pay can boost worker morale and productivity while reducing costly staff turnover","D":"It allows the store to cancel all employee holiday entitlements"},"correctOption":"C","correctAnswer":"Higher take-home pay can boost worker morale and productivity while reducing costly staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because better-paid workers often feel more valued, work harder, and stay longer, partially offsetting higher hourly wage costs.","distractor_reasons":{"A":"Incorrect because shift scheduling remains essential.","B":"Incorrect because a higher minimum rate increases total payroll costs.","C":"Correct selection.","D":"Incorrect because statutory leave rights remain legally protected."}}},{"id":"P1_U2_MCQ_915","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_915","question":"What is a major disadvantage of using 'Last In, First Out' (LIFO) as the sole criterion for selecting workers for redundancy?","options":{"A":"The business must pay the highest severance packages because long-serving staff leave first","B":"Long-serving employees are automatically disqualified from receiving redundancy compensation","C":"Trade unions always oppose seniority-based rules","D":"The business may lose recently hired employees who possess vital modern technical skills and high productivity"},"correctOption":"D","correctAnswer":"The business may lose recently hired employees who possess vital modern technical skills and high productivity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because LIFO ignores individual performance and modern qualifications, risking the loss of high-potential newer hires.","distractor_reasons":{"A":"Incorrect because newer employees with shorter service receive smaller statutory redundancy payouts.","B":"Incorrect because long-serving staff remain employed under LIFO.","C":"Incorrect because unions often favour objective seniority rules over subjective manager choices.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_916","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_916","question":"A bank installs automated self-service kiosks that reduce teller transactions by 40%. Why might the bank retrain displaced tellers as financial advisors rather than making them redundant?","options":{"A":"Retraining avoids redundancy payouts, retains trusted employees who already know bank customers, and boosts workforce morale","B":"Retraining is completely free and requires zero classroom or coaching time","C":"Banks are legally forbidden from ever making retail branch staff redundant","D":"Financial advisors require no product knowledge or customer communication skills"},"correctOption":"A","correctAnswer":"Retraining avoids redundancy payouts, retains trusted employees who already know bank customers, and boosts workforce morale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because redeployment and upskilling preserve institutional loyalty and avoid the financial and reputational costs of layoffs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retraining requires investment in courses and supervisor time.","C":"Incorrect because redundancy is lawful when genuine, though retraining is often preferable.","D":"Incorrect because advisory roles require strong technical and interpersonal training."}}},{"id":"P1_U2_MCQ_917","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_917","question":"How does thorough 'induction training' reduce early labour turnover among new recruits?","options":{"A":"It doubles new recruits' basic hourly wages during their first week","B":"It helps new hires feel welcomed, understand expectations clearly, and build confidence quickly rather than feeling overwhelmed","C":"It exempts new recruits from following company punctuality rules","D":"It guarantees immediate promotion to senior management after thirty days"},"correctOption":"B","correctAnswer":"It helps new hires feel welcomed, understand expectations clearly, and build confidence quickly rather than feeling overwhelmed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because many resignations occur in the first few weeks when unsupported hires feel lost or isolated.","distractor_reasons":{"A":"Incorrect because induction is an orientation programme rather than a wage bonus.","B":"Correct selection.","C":"Incorrect because induction clarifies workplace rules and expectations.","D":"Incorrect because promotion depends on long-term performance and vacancies."}}},{"id":"P1_U2_MCQ_918","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_918","question":"Which workplace training method involves a newly appointed trainee observing and working alongside an experienced colleague during normal daily duties?","options":{"A":"External university distance learning","B":"Off-the-job residential seminar","C":"On-the-job shadowing and coaching","D":"Mass redundancy consultation"},"correctOption":"C","correctAnswer":"On-the-job shadowing and coaching","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because shadowing lets the trainee learn real workplace routines directly from a skilled practitioner.","distractor_reasons":{"A":"Incorrect because university courses are off-the-job academic training.","B":"Incorrect because residential seminars take place away from the workplace.","C":"Correct selection.","D":"Incorrect because redundancy consultation relates to downsizing."}}},{"id":"P1_U2_MCQ_919","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_919","question":"What is a potential financial risk to an employer that funds expensive 'off-the-job' professional qualifications for its staff?","options":{"A":"Employees lose all practical understanding of how the company operates","B":"The government fines businesses that sponsor employee education","C":"Accredited qualifications reduce employee productivity and motivation","D":"Newly qualified employees become more attractive to rival firms and may leave for higher pay elsewhere"},"correctOption":"D","correctAnswer":"Newly qualified employees become more attractive to rival firms and may leave for higher pay elsewhere","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because portable external qualifications raise a worker's market value, risking poaching by competitors unless paired with good pay and career progression.","distractor_reasons":{"A":"Incorrect because external training enhances theoretical and specialist knowledge.","B":"Incorrect because governments encourage workforce upskilling.","C":"Incorrect because training generally increases competence and motivation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_920","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_920","question":"A logistics company employs an average of 200 staff during the year, and 50 employees leave and need to be replaced. What is its annual labour turnover rate?","options":{"A":"4%","B":"25%","C":"50%","D":"400%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Labour Turnover (%) = (Number of staff leaving / Average number of staff) × 100 = (50 / 200) × 100 = 25%.","distractor_reasons":{"A":"Incorrect because 4 results from dividing 200 by 50 without multiplying by 100.","B":"Correct selection.","C":"Incorrect because 50 is the headcount of leavers rather than the percentage rate.","D":"Incorrect because 400% reverses numerator and denominator."}}},{"id":"P1_U2_MCQ_921","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_921","question":"Which set of internal factors most commonly causes an abnormally high labour turnover rate?","options":{"A":"Uncompetitive pay, poor supervision, monotonous tasks, and lack of promotion opportunities","B":"Competitive salaries, thorough induction training, and supportive democratic leadership","C":"Strong fringe benefits, safe working conditions, and clear career pathways","D":"Regular recognition awards and flexible working hours"},"correctOption":"A","correctAnswer":"Uncompetitive pay, poor supervision, monotonous tasks, and lack of promotion opportunities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low pay, weak management, and stagnant roles push employees to seek better opportunities elsewhere.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competitive pay and supportive leadership improve retention.","C":"Incorrect because good benefits and safety reduce voluntary resignations.","D":"Incorrect because recognition and flexibility boost loyalty."}}},{"id":"P1_U2_MCQ_922","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_922","question":"A supermarket chain plans to open 15 new stores next year. Why must HR begin 'workforce planning' several months in advance?","options":{"A":"To ensure the stores open without hiring any store managers or cashiers","B":"To avoid issuing written contracts of employment to new recruits","C":"To allow sufficient time to recruit, select, and train store managers and staff before opening day","D":"To reduce the legal minimum wage in the regions where new stores open"},"correctOption":"C","correctAnswer":"To allow sufficient time to recruit, select, and train store managers and staff before opening day","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because recruiting and training managers and frontline teams takes months; advance planning prevents understaffed openings.","distractor_reasons":{"A":"Incorrect because stores require trained managers and staff to operate.","B":"Incorrect because contracts remain legally mandatory.","C":"Correct selection.","D":"Incorrect because businesses cannot alter statutory minimum wage rates."}}},{"id":"P1_U2_MCQ_923","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_923","question":"What is a potential disadvantage to an employer of allowing applicants to apply using only a free-form 'CV (resumé)' rather than a company application form?","options":{"A":"CVs are illegal to use when recruiting for private limited companies","B":"CVs cannot be sent electronically via email or online portals","C":"CVs always include confidential references from the candidate's current manager","D":"Candidates format CVs differently and may omit awkward details such as employment gaps, making direct comparison harder"},"correctOption":"D","correctAnswer":"Candidates format CVs differently and may omit awkward details such as employment gaps, making direct comparison harder","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because applicants control what they emphasize or omit on a personal CV, whereas an application form forces standardized answers.","distractor_reasons":{"A":"Incorrect because CVs are widely and lawfully used across all business types.","B":"Incorrect because digital CVs are standard in online recruitment.","C":"Incorrect because references are requested separately from referees.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_924","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_924","question":"Why should employers treat written 'references' cautiously rather than relying on them alone when selecting staff?","options":{"A":"References are written by the applicant themselves without referee approval","B":"Candidates only list supportive referees, and former employers often give brief, overly cautious dates-only replies to avoid legal disputes","C":"References test a candidate's mathematical ability under timed exam conditions","D":"Requesting references violates data protection and equal opportunity laws"},"correctOption":"B","correctAnswer":"Candidates only list supportive referees, and former employers often give brief, overly cautious dates-only replies to avoid legal disputes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because applicants select favourable referees and many companies restrict managers to confirming only job titles and employment dates.","distractor_reasons":{"A":"Incorrect because referees submit references directly to the prospective employer.","B":"Correct selection.","C":"Incorrect because cognitive ability is assessed via aptitude tests.","D":"Incorrect because requesting references with candidate consent is lawful."}}},{"id":"P1_U2_MCQ_925","section":"2","unit":"Unit 2: People in Business","chapter":"2.1 Human resource management (HRM)","questionNumber":"P1_U2_MCQ_925","question":"A fast-growing delivery startup needs 30 drivers immediately, faces tight cash flow, and wants to minimize legal disputes. Which HR approach is best?","options":{"A":"Hire executive headhunters and send drivers on a six-month external university degree","B":"Hire drivers verbally without written contracts or driving-licence checks","C":"Advertise via local online job portals and job centres, verify licences, issue clear written contracts, and provide structured on-the-job induction","D":"Use LIFO redundancy rules to dismiss existing logistics coordinators"},"correctOption":"C","correctAnswer":"Advertise via local online job portals and job centres, verify licences, issue clear written contracts, and provide structured on-the-job induction","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online/job-centre adverts are fast and low-cost, licence checks ensure safety, written contracts prevent legal disputes, and practical induction gets drivers productive quickly.","distractor_reasons":{"A":"Incorrect because headhunters and six-month courses are too slow and costly.","B":"Incorrect because skipping licence checks and contracts creates severe safety and legal risks.","C":"Correct selection.","D":"Incorrect because the expanding startup needs to hire drivers rather than make coordinators redundant."}}},{"id":"P1_U2_MCQ_926","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_926","question":"In an organisation with 6 levels of hierarchy from the Chief Executive down to shop-floor operatives, how many management layers does an instruction pass through to reach operatives?","options":{"A":"One single step directly from CEO to operative","B":"Multiple intermediate tiers along a long chain of command, increasing the risk of delay and distortion","C":"Zero tiers because the structure is completely flat","D":"Exactly 36 tiers regardless of company size"},"correctOption":"B","correctAnswer":"Multiple intermediate tiers along a long chain of command, increasing the risk of delay and distortion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 6-tier tall hierarchy creates a long vertical chain of command where messages pass through several intermediate managers.","distractor_reasons":{"A":"Incorrect because direct CEO-to-operative communication occurs only in a 2-tier flat structure.","B":"Correct selection.","C":"Incorrect because 6 levels represent a tall rather than flat structure.","D":"Incorrect because there is no squaring calculation for hierarchy levels."}}},{"id":"P1_U2_MCQ_927","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_927","question":"For a workforce of fixed size, what is the general relationship between 'span of control' and 'levels of hierarchy'?","options":{"A":"Wider spans of control create a taller hierarchy with more management tiers","B":"Narrower spans of control create a flatter hierarchy with fewer management tiers","C":"Span of control and levels of hierarchy have no connection in organisational design","D":"Wider spans of control reduce the number of management tiers needed, creating a flatter structure"},"correctOption":"D","correctAnswer":"Wider spans of control reduce the number of management tiers needed, creating a flatter structure","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when each manager supervises more direct subordinates, fewer supervisory layers are required.","distractor_reasons":{"A":"Incorrect because wider spans flatten rather than heighten the pyramid.","B":"Incorrect because narrow spans require more supervisors and extra tiers.","C":"Incorrect because the two structural dimensions are inversely related.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_928","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_928","question":"What is the primary role of the 'Chief Executive Officer (CEO) / Managing Director' in a limited company?","options":{"A":"To lead overall corporate strategy, coordinate functional directors, and report to the Board of Directors and shareholders","B":"To personally operate factory assembly machines during night shifts","C":"To represent trade union members in collective wage strikes against the company","D":"To conduct external government tax audits on rival companies"},"correctOption":"A","correctAnswer":"To lead overall corporate strategy, coordinate functional directors, and report to the Board of Directors and shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the CEO sits at the top of the operational chain of command, translating Board objectives into company-wide execution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because frontline production tasks are performed by operatives supervised by line managers.","C":"Incorrect because trade union officials represent employees.","D":"Incorrect because government tax authorities conduct statutory audits."}}},{"id":"P1_U2_MCQ_929","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_929","question":"Which set of core activities belongs to the 'Marketing' functional department?","options":{"A":"Preparing annual balance sheets, managing bank loans, and paying supplier invoices","B":"Recruiting warehouse staff, running induction courses, and handling disciplinary hearings","C":"Conducting market research, developing product features, setting prices, promoting brands, and choosing distribution channels","D":"Maintaining factory machinery, controlling raw-material stock, and inspecting assembly quality"},"correctOption":"C","correctAnswer":"Conducting market research, developing product features, setting prices, promoting brands, and choosing distribution channels","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Marketing identifies customer needs and manages the marketing mix (product, price, place, promotion).","distractor_reasons":{"A":"Incorrect because financial reporting and cash management belong to Finance.","B":"Incorrect because staffing and industrial relations belong to Human Resources.","C":"Correct selection.","D":"Incorrect because production and quality control belong to Operations."}}},{"id":"P1_U2_MCQ_930","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_930","question":"Which set of responsibilities belongs primarily to the 'Human Resources (HR)' department?","options":{"A":"Designing social media product adverts and negotiating supermarket shelf space","B":"Workforce planning, recruitment and selection, training, appraisal systems, and employee/union relations","C":"Forecasting cash-flow statements and auditing branch petty-cash records","D":"Programming automated assembly robots and scheduling freight deliveries"},"correctOption":"B","correctAnswer":"Workforce planning, recruitment and selection, training, appraisal systems, and employee/union relations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because HR manages the entire employee lifecycle from workforce planning and hiring to development and welfare.","distractor_reasons":{"A":"Incorrect because advertising and retail placement belong to Marketing.","B":"Correct selection.","C":"Incorrect because cash-flow forecasting and auditing belong to Finance.","D":"Incorrect because manufacturing automation and logistics belong to Operations."}}},{"id":"P1_U2_MCQ_931","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_931","question":"Why must the 'Human Resources' and 'Finance' departments work closely together during annual pay negotiations?","options":{"A":"Finance designs the company's television commercials while HR manufactures products","B":"HR sets national interest rates while Finance inspects factory fire exits","C":"Coordination ensures that all employees receive zero wage increases every year","D":"HR understands staff retention and union expectations, while Finance calculates whether proposed wage rises are affordable within budgets"},"correctOption":"D","correctAnswer":"HR understands staff retention and union expectations, while Finance calculates whether proposed wage rises are affordable within budgets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because balancing competitive employee pay against payroll affordability and profit margins requires joint HR and Finance planning.","distractor_reasons":{"A":"Incorrect because advertising is Marketing and manufacturing is Operations.","B":"Incorrect because central banks set interest rates and safety officers inspect exits.","C":"Incorrect because pay freezes are not automatic and could trigger high staff turnover.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_932","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_932","question":"How does organizing staff into cross-functional project teams (a matrix approach) benefit an engineering consultancy?","options":{"A":"Specialists from design, finance, and operations collaborate directly, speeding up problem-solving and innovation","B":"It lengthens the vertical chain of command so every minor drawing requires CEO approval","C":"It isolates each department so engineers never speak to finance or marketing staff","D":"It eliminates the need for project deadlines or client budgets"},"correctOption":"A","correctAnswer":"Specialists from design, finance, and operations collaborate directly, speeding up problem-solving and innovation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bringing diverse specialists together on a shared project improves horizontal communication and responsiveness to client needs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cross-functional teams bypass slow vertical approval chains.","C":"Incorrect because matrix teams break down departmental silos.","D":"Incorrect because project teams operate under strict client budgets and schedules."}}},{"id":"P1_U2_MCQ_933","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_933","question":"What is a common disadvantage for employees working within a 'matrix' organisational structure?","options":{"A":"Employees never get to collaborate with colleagues from other departments","B":"The organisation completely lacks specialist functional expertise","C":"Employees report to both a functional manager and a project manager, risking conflicting priorities and stress","D":"Employees are paid only when the company pays annual shareholder dividends"},"correctOption":"C","correctAnswer":"Employees report to both a functional manager and a project manager, risking conflicting priorities and stress","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dual lines of authority violate unity of command and can create competing workload demands.","distractor_reasons":{"A":"Incorrect because cross-departmental collaboration is the core feature of a matrix structure.","B":"Incorrect because staff remain linked to their specialist functional departments.","C":"Correct selection.","D":"Incorrect because staff receive regular contractual wages or salaries."}}},{"id":"P1_U2_MCQ_934","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_934","question":"What is a common disadvantage of permanent 'home working' (teleworking) for employees?","options":{"A":"Higher daily commuting expenses and longer travel times","B":"Feelings of social isolation from colleagues and potential difficulty separating home life from work","C":"Loss of statutory holiday and sick-pay entitlements","D":"Constant physical interruption from noisy factory assembly lines"},"correctOption":"B","correctAnswer":"Feelings of social isolation from colleagues and potential difficulty separating home life from work","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because working remotely reduces casual social contact (Maslow's social needs) and can blur boundaries between work and personal time.","distractor_reasons":{"A":"Incorrect because home working eliminates or drastically reduces commuting time and costs.","B":"Correct selection.","C":"Incorrect because home-based employees retain full statutory employment rights.","D":"Incorrect because home workers operate away from factory premises."}}},{"id":"P1_U2_MCQ_935","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_935","question":"How does a 'compressed working week' (such as working 40 hours across four 10-hour days instead of five 8-hour days) benefit employees?","options":{"A":"Employees receive a 25% pay rise while working 20% fewer total hours","B":"Employees never have to communicate with managers or meet output targets","C":"Employees can take unlimited paid holidays whenever they wish","D":"Employees gain an extra weekday off for personal responsibilities and save commuting costs while keeping full-time pay"},"correctOption":"D","correctAnswer":"Employees gain an extra weekday off for personal responsibilities and save commuting costs while keeping full-time pay","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because compressed hours maintain full contractual output while improving work-life balance and reducing commuting trips.","distractor_reasons":{"A":"Incorrect because total weekly hours and pay remain unchanged.","B":"Incorrect because normal performance and communication standards still apply.","C":"Incorrect because annual holiday entitlement remains governed by contract.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_936","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_936","question":"Why might a business-to-business consultancy assigning dedicated account managers to corporate clients prefer 'full-time' over 'part-time' staff?","options":{"A":"Corporate clients expect continuous weekday availability and consistent relationship continuity from one dedicated manager","B":"Part-time employees are legally forbidden from speaking to corporate clients","C":"Full-time employees never take annual leave or sick days","D":"Full-time contracts carry lower fixed weekly wage obligations than part-time contracts"},"correctOption":"A","correctAnswer":"Corporate clients expect continuous weekday availability and consistent relationship continuity from one dedicated manager","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because full-time presence throughout the business week ensures seamless client communication without handover delays.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because part-time staff can lawfully serve any customer segment.","C":"Incorrect because full-time staff still take statutory leave.","D":"Incorrect because full-time contracts involve higher fixed weekly wage commitments."}}},{"id":"P1_U2_MCQ_937","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_937","question":"What is the key difference between the management functions of 'organising' and 'coordinating'?","options":{"A":"Organising sets future corporate vision, whereas coordinating dismisses underperforming staff","B":"Organising calculates annual tax liabilities, whereas coordinating designs product logos","C":"Organising allocates resources and tasks into roles, whereas coordinating ensures different people and departments synchronize their activities smoothly","D":"Organising applies only to sole traders, whereas coordinating applies only to public limited companies"},"correctOption":"C","correctAnswer":"Organising allocates resources and tasks into roles, whereas coordinating ensures different people and departments synchronize their activities smoothly","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because organising builds the structure of tasks and resources, while coordinating aligns ongoing operations across teams.","distractor_reasons":{"A":"Incorrect because setting future targets is planning, and dismissal is an HR disciplinary action.","B":"Incorrect because taxes belong to Finance and logos belong to Marketing.","C":"Correct selection.","D":"Incorrect because all management functions apply across organisations of any size."}}},{"id":"P1_U2_MCQ_938","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_938","question":"A factory manager reviews weekly quality reports, discovers defect rates have risen from 1% to 4%, and schedules immediate machine recalibration. Which management function is being performed?","options":{"A":"Planning","B":"Controlling","C":"Recruiting","D":"Delayering"},"correctOption":"B","correctAnswer":"Controlling","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because controlling monitors actual results against standards and takes corrective action to fix deviations.","distractor_reasons":{"A":"Incorrect because planning establishes initial targets before production runs.","B":"Correct selection.","C":"Incorrect because recruiting hires new staff.","D":"Incorrect because delayering removes management tiers."}}},{"id":"P1_U2_MCQ_939","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_939","question":"Why are some managers reluctant to 'delegate' important tasks to their subordinates?","options":{"A":"Delegation automatically transfers legal accountability away from the manager","B":"Subordinates always refuse extra responsibility because they dislike learning new skills","C":"Delegation is prohibited in organisations with wide spans of control","D":"Managers fear subordinates may make costly errors for which the manager remains accountable, or fear losing personal control"},"correctOption":"D","correctAnswer":"Managers fear subordinates may make costly errors for which the manager remains accountable, or fear losing personal control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because managers retain ultimate responsibility for delegated work and may lack trust in subordinate readiness.","distractor_reasons":{"A":"Incorrect because ultimate accountability stays with the delegating manager.","B":"Incorrect because many staff welcome trusted responsibility as a motivator.","C":"Incorrect because wide spans of control actually make delegation essential.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_940","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_940","question":"What distinguishes effective 'delegation' from managerial 'abdication'?","options":{"A":"Delegation provides clear objectives, necessary authority, resources, and periodic support, whereas abdication dumps tasks without guidance or oversight","B":"Delegation gives zero decision-making authority to the worker, whereas abdication uses strict micromanagement","C":"Delegation is used only in emergencies, whereas abdication is used for annual budgeting","D":"Delegation reduces subordinate motivation, whereas abdication increases product quality"},"correctOption":"A","correctAnswer":"Delegation provides clear objectives, necessary authority, resources, and periodic support, whereas abdication dumps tasks without guidance or oversight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because successful delegation empowers the subordinate with clarity and backing while the manager monitors progress appropriately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delegation grants genuine authority to complete the task.","C":"Incorrect because delegation is an everyday management practice.","D":"Incorrect because delegation boosts motivation, whereas abdication causes confusion and failure."}}},{"id":"P1_U2_MCQ_941","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_941","question":"What is a major long-term risk of using an 'autocratic' leadership style with experienced, skilled staff?","options":{"A":"Decision-making becomes too slow due to endless group consultations","B":"Subordinates gain excessive freedom and ignore all corporate targets","C":"Employees feel undervalued because their ideas are ignored, leading to low morale, lack of initiative, and higher labour turnover","D":"The leader loses all formal authority within the chain of command"},"correctOption":"C","correctAnswer":"Employees feel undervalued because their ideas are ignored, leading to low morale, lack of initiative, and higher labour turnover","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because constant top-down commands stifle creativity and fail to satisfy higher-order esteem needs.","distractor_reasons":{"A":"Incorrect because slow consultation is a drawback of democratic leadership.","B":"Incorrect because lack of direction is a risk of poorly applied laissez-faire leadership.","C":"Correct selection.","D":"Incorrect because autocratic leaders retain strict formal authority."}}},{"id":"P1_U2_MCQ_942","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_942","question":"How does a 'consultative democratic' leader operate compared with a 'majority-vote democratic' leader?","options":{"A":"A consultative leader refuses to speak with staff, whereas a majority-vote leader ignores election outcomes","B":"A consultative leader actively seeks and considers employee ideas before making the final decision, whereas a majority-vote leader lets the group decide by vote","C":"A consultative leader uses harsh threats, whereas a majority-vote leader delegates everything without goals","D":"Both styles forbid employees from expressing opinions during team meetings"},"correctOption":"B","correctAnswer":"A consultative leader actively seeks and considers employee ideas before making the final decision, whereas a majority-vote leader lets the group decide by vote","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because democratic leadership ranges from two-way consultation prior to decision-making to full group consensus/voting.","distractor_reasons":{"A":"Incorrect because consultative leaders actively invite employee input.","B":"Correct selection.","C":"Incorrect because harsh threats describe hard autocratic control.","D":"Incorrect because both variants encourage employee voice."}}},{"id":"P1_U2_MCQ_943","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_943","question":"What is likely to happen if a manager applies a 'laissez-faire' leadership style to newly hired, inexperienced trainees?","options":{"A":"Trainees immediately master complex machinery without any instruction","B":"Trainees feel overly micromanaged by strict step-by-step commands","C":"Decision-making becomes overly centralized in the Chief Executive's office","D":"Trainees lack clear direction and support, resulting in confusion, low productivity, and safety mistakes"},"correctOption":"D","correctAnswer":"Trainees lack clear direction and support, resulting in confusion, low productivity, and safety mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because laissez-faire leadership relies on self-motivated, expert staff; novices need structured guidance and coaching.","distractor_reasons":{"A":"Incorrect because inexperienced recruits cannot teach themselves complex tasks safely.","B":"Incorrect because laissez-faire provides minimal supervision rather than micromanagement.","C":"Incorrect because laissez-faire decentralizes day-to-day choices.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_944","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_944","question":"Why might a 'paternalistic' leadership style frustrate ambitious, independent professionals in a modern tech firm?","options":{"A":"Although the leader cares about staff welfare, decisions are still made 'for' employees rather than giving them genuine autonomy","B":"Paternalistic leaders show zero concern for employee job security or working conditions","C":"Paternalistic leaders force employees to vote on every minor administrative task","D":"Paternalistic leaders prohibit businesses from offering pension or healthcare benefits"},"correctOption":"A","correctAnswer":"Although the leader cares about staff welfare, decisions are still made 'for' employees rather than giving them genuine autonomy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paternalism treats workers like dependents—well cared for, yet excluded from real strategic empowerment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because protecting staff welfare is central to paternalistic leadership.","C":"Incorrect because group voting characterizes democratic leadership.","D":"Incorrect because paternalistic firms frequently provide generous welfare benefits."}}},{"id":"P1_U2_MCQ_945","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_945","question":"What is meant by 'collective bargaining' between a trade union and an employer?","options":{"A":"Individual workers competing privately against colleagues for secret pay rises","B":"Customers negotiating bulk discounts with a wholesale manufacturer","C":"Trade union representatives negotiating wages and working conditions jointly on behalf of all union members","D":"The government setting statutory corporate tax rates for limited companies"},"correctOption":"C","correctAnswer":"Trade union representatives negotiating wages and working conditions jointly on behalf of all union members","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collective bargaining pools workers' negotiating power through union officials rather than leaving individuals to bargain alone.","distractor_reasons":{"A":"Incorrect because individual pay deals are individual bargaining.","B":"Incorrect because buyer-supplier pricing is commercial procurement.","C":"Correct selection.","D":"Incorrect because taxation is set by government legislation."}}},{"id":"P1_U2_MCQ_946","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_946","question":"How does an 'overtime ban' pressure an employer during a trade union dispute?","options":{"A":"Employees permanently resign and join a rival firm","B":"Employees refuse to work any hours beyond their contracted shift, limiting the employer's ability to meet peak orders or urgent deadlines","C":"Employees block delivery trucks from entering company premises","D":"Employees demand that the union pay their full basic salaries"},"correctOption":"B","correctAnswer":"Employees refuse to work any hours beyond their contracted shift, limiting the employer's ability to meet peak orders or urgent deadlines","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an overtime ban reduces capacity during busy periods without breaching employees' core contractual hours or forfeiting basic pay.","distractor_reasons":{"A":"Incorrect because workers remain employed and work their standard contracted shifts.","B":"Correct selection.","C":"Incorrect because blocking entrances is picketing during a strike.","D":"Incorrect because employees continue receiving their regular basic wages from the employer."}}},{"id":"P1_U2_MCQ_947","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_947","question":"What is the main operational effect of a 'go-slow' form of industrial action on a manufacturing firm?","options":{"A":"Fixed overheads drop to zero while output doubles","B":"All workers leave the factory gates for several weeks","C":"Product quality improves so dramatically that customer complaints vanish","D":"Workers deliberately reduce their pace of work while still being paid, lowering output and raising average unit labour costs"},"correctOption":"D","correctAnswer":"Workers deliberately reduce their pace of work while still being paid, lowering output and raising average unit labour costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because paying full hourly wages for reduced output drives up unit production costs and delays customer deliveries.","distractor_reasons":{"A":"Incorrect because fixed costs remain unchanged while output falls.","B":"Incorrect because walking out completely is a strike.","C":"Incorrect because a go-slow reduces productivity rather than improving quality.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_948","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_948","question":"How can independent 'arbitration' help resolve a deadlocked pay dispute between management and a trade union?","options":{"A":"An impartial third party listens to both sides and makes a binding (or recommended) settlement decision to avoid damaging strikes","B":"The arbitrator dismisses all trade union members and hires replacement agency staff","C":"The arbitrator forces the company to double product prices immediately","D":"The arbitrator bans any communication between managers and workers for twelve months"},"correctOption":"A","correctAnswer":"An impartial third party listens to both sides and makes a binding (or recommended) settlement decision to avoid damaging strikes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because independent arbitration breaks negotiation stalemates fairly, saving both employer and workers from costly strike losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because arbitrators act as neutral dispute resolvers, not company HR managers.","C":"Incorrect because arbitrators focus on the employment dispute rather than commercial pricing.","D":"Incorrect because dispute resolution restores constructive dialogue."}}},{"id":"P1_U2_MCQ_949","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_949","question":"How can maintaining positive, cooperative relations with a recognized trade union benefit an employer?","options":{"A":"The union guarantees that the business will never face competition from foreign imports","B":"The employer no longer needs to provide safe machinery or protective equipment","C":"Union representatives provide a structured upward communication channel, helping introduce new working practices smoothly without strikes","D":"The union pays half of the company's annual corporate tax bill"},"correctOption":"C","correctAnswer":"Union representatives provide a structured upward communication channel, helping introduce new working practices smoothly without strikes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consulting union reps early uncovers workforce concerns and builds trust when implementing operational changes.","distractor_reasons":{"A":"Incorrect because unions cannot block market competition.","B":"Incorrect because statutory safety laws always apply.","C":"Correct selection.","D":"Incorrect because unions do not fund business taxes."}}},{"id":"P1_U2_MCQ_950","section":"2","unit":"Unit 2: People in Business","chapter":"2.2 Organisation and management","questionNumber":"P1_U2_MCQ_950","question":"A national grocery chain removes two layers of regional middle management (delayering) and grants store managers authority to adjust local promotions (decentralisation). What must the chain provide to ensure this succeeds?","options":{"A":"Strict autocratic orders forbidding store managers from making any local choices","B":"Management training, clear brand guidelines, and reliable communication systems so store managers handle wider responsibilities effectively","C":"A complete ban on delegation across all retail stores","D":"Six extra tiers of head-office supervisors to double-check every store price tag"},"correctOption":"B","correctAnswer":"Management training, clear brand guidelines, and reliable communication systems so store managers handle wider responsibilities effectively","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because decentralisation and wider spans of control succeed only when local managers are trained, supported, and aligned with core brand standards.","distractor_reasons":{"A":"Incorrect because autocratic bans contradict decentralisation.","B":"Correct selection.","C":"Incorrect because wider spans require active delegation.","D":"Incorrect because adding head-office tiers reverses delayering."}}},{"id":"P1_U2_MCQ_951","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_951","question":"What is the primary responsibility of the 'transmitter (sender)' in ensuring effective communication?","options":{"A":"To ignore whether the receiver has access to the chosen communication channel","B":"To use as much technical jargon as possible to sound authoritative","C":"To prevent the receiver from asking any follow-up questions","D":"To define the purpose of the message clearly, encode it in simple language, and select an appropriate medium for the receiver"},"correctOption":"D","correctAnswer":"To define the purpose of the message clearly, encode it in simple language, and select an appropriate medium for the receiver","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because clear encoding and suitable medium selection at the source prevent most misunderstandings before transmission.","distractor_reasons":{"A":"Incorrect because the sender must ensure the receiver can access the medium.","B":"Incorrect because jargon creates comprehension barriers.","C":"Incorrect because encouraging feedback verifies understanding.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_952","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_952","question":"What is the role of the 'receiver' in completing an effective communication cycle?","options":{"A":"To delete unread messages immediately to keep their inbox empty","B":"To pay attention, decode the message accurately, and provide clear feedback confirming understanding or asking for clarification","C":"To pass distorted rumours along the office grapevine","D":"To lengthen the chain of command before acting on urgent safety instructions"},"correctOption":"B","correctAnswer":"To pay attention, decode the message accurately, and provide clear feedback confirming understanding or asking for clarification","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because active listening/reading and feedback confirm that the intended meaning was successfully received.","distractor_reasons":{"A":"Incorrect because ignoring messages breaks the communication chain.","B":"Correct selection.","C":"Incorrect because spreading rumours distorts information.","D":"Incorrect because urgent instructions require prompt, direct action."}}},{"id":"P1_U2_MCQ_953","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_953","question":"In which workplace situation is 'one-way communication' appropriate and effective?","options":{"A":"Sounding a fire evacuation alarm or displaying permanent 'Wear Hard Hats' safety signs","B":"Conducting an employee's annual career development appraisal","C":"Negotiating a new shift roster with factory team leaders","D":"Resolving a complex customer complaint about a custom software order"},"correctOption":"A","correctAnswer":"Sounding a fire evacuation alarm or displaying permanent 'Wear Hard Hats' safety signs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because urgent safety warnings and standard mandatory rules require immediate compliance rather than debate.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because appraisals require two-way dialogue.","C":"Incorrect because roster changes benefit from two-way staff consultation.","D":"Incorrect because customer complaints require listening and two-way resolution."}}},{"id":"P1_U2_MCQ_954","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_954","question":"Why does 'two-way communication' improve task accuracy when a manager assigns a complex new project?","options":{"A":"It eliminates the need to write down project deadlines or budgets","B":"It guarantees that the manager never has to answer employee questions","C":"The employee can ask clarifying questions and restate key requirements, catching misunderstandings before work begins","D":"It makes the chain of command longer and more bureaucratic"},"correctOption":"C","correctAnswer":"The employee can ask clarifying questions and restate key requirements, catching misunderstandings before work begins","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interactive feedback verifies shared understanding of technical details and priorities.","distractor_reasons":{"A":"Incorrect because written project specifications remain vital.","B":"Incorrect because two-way dialogue welcomes questions.","C":"Correct selection.","D":"Incorrect because direct two-way communication clarifies expectations efficiently."}}},{"id":"P1_U2_MCQ_955","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_955","question":"Which of the following is an example of 'external communication'?","options":{"A":"A warehouse supervisor briefing packers on morning loading targets","B":"An HR manager emailing an internal holiday policy update to all employees","C":"A production manager discussing machine maintenance with the finance director","D":"A sales manager sending an official price quotation to a prospective corporate customer"},"correctOption":"D","correctAnswer":"A sales manager sending an official price quotation to a prospective corporate customer","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a prospective customer is an outside stakeholder, making the price quote external communication.","distractor_reasons":{"A":"Incorrect because supervisor-to-packer briefings are internal communication.","B":"Incorrect because HR-to-staff policy updates are internal communication.","C":"Incorrect because cross-departmental manager discussions are internal horizontal communication.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_956","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_956","question":"Why do senior directors rely on structured 'written reports' when deciding whether to build a new overseas factory?","options":{"A":"Written reports require zero research or data analysis to prepare","B":"Reports organize detailed financial forecasts, market research, and risk analyses into a permanent document that directors can study carefully before meeting","C":"Reports provide instantaneous spoken body-language feedback","D":"Reports are faster to read than a one-sentence text message"},"correctOption":"B","correctAnswer":"Reports organize detailed financial forecasts, market research, and risk analyses into a permanent document that directors can study carefully before meeting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-value strategic decisions require thorough, well-documented evidence that can be reviewed and referenced accurately.","distractor_reasons":{"A":"Incorrect because formal business reports require extensive data gathering and analysis.","B":"Correct selection.","C":"Incorrect because written reports lack non-verbal cues.","D":"Incorrect because reports are comprehensive documents rather than brief alerts."}}},{"id":"P1_U2_MCQ_957","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_957","question":"What is a 'memorandum (memo)' traditionally used for in business communication?","options":{"A":"Brief, formal written messages circulated internally within an organisation to announce reminders, procedures, or policy updates","B":"Public television commercials aimed at external retail shoppers","C":"Audited annual financial statements filed with government stock exchanges","D":"Live video conferences with international raw-material suppliers"},"correctOption":"A","correctAnswer":"Brief, formal written messages circulated internally within an organisation to announce reminders, procedures, or policy updates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because memos (now often sent electronically) provide concise internal written records across departments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because external consumer adverts are marketing promotions.","C":"Incorrect because audited accounts are formal external statutory reports.","D":"Incorrect because video conferences are virtual spoken meetings."}}},{"id":"P1_U2_MCQ_958","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_958","question":"Why is a 'face-to-face appraisal meeting' superior to an online multiple-choice form when discussing an employee's career aspirations and workplace concerns?","options":{"A":"Face-to-face meetings never require any advance preparation by the manager","B":"Face-to-face meetings automatically generate a verbatim legal transcript without note-taking","C":"Personal dialogue allows empathy, follow-up probing, and non-verbal rapport that build trust and uncover deeper feedback","D":"Online forms cannot be completed by office workers with computer access"},"correctOption":"C","correctAnswer":"Personal dialogue allows empathy, follow-up probing, and non-verbal rapport that build trust and uncover deeper feedback","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sensitive developmental conversations benefit from human warmth, active listening, and nuanced two-way exploration.","distractor_reasons":{"A":"Incorrect because effective appraisal meetings require careful preparation of performance records.","B":"Incorrect because spoken meetings require written summary notes afterward.","C":"Correct selection.","D":"Incorrect because office workers can use online forms, but forms lack personal empathy."}}},{"id":"P1_U2_MCQ_959","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_959","question":"When is making a direct 'phone call' preferable to sending an 'email'?","options":{"A":"When sending a 40-page technical product manual with detailed spreadsheets","B":"When broadcasting a non-urgent holiday calendar update to 500 employees","C":"When creating a legally binding written contract amendment","D":"When an urgent operational issue requires immediate two-way discussion and rapid confirmation"},"correctOption":"D","correctAnswer":"When an urgent operational issue requires immediate two-way discussion and rapid confirmation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a phone call guarantees immediate real-time dialogue, whereas an email might sit unread in a busy inbox.","distractor_reasons":{"A":"Incorrect because large documents and spreadsheets require email or file sharing.","B":"Incorrect because broadcasting announcements to 500 staff is far more efficient via email or intranet.","C":"Incorrect because contract amendments require permanent written documentation.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_960","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_960","question":"Which business communication task is best suited to 'text messages (SMS)'?","options":{"A":"Explaining a complex 12-page employee health insurance policy","B":"Sending brief, time-sensitive appointment reminders to customers or urgent shift-cover alerts to mobile staff","C":"Delivering a formal redundancy dismissal notice to a long-serving manager","D":"Presenting quarterly financial charts to institutional shareholders"},"correctOption":"B","correctAnswer":"Sending brief, time-sensitive appointment reminders to customers or urgent shift-cover alerts to mobile staff","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because SMS messages have very high open rates and deliver concise alerts instantaneously to mobile phones.","distractor_reasons":{"A":"Incorrect because long policy documents exceed SMS character limits.","B":"Correct selection.","C":"Incorrect because redundancy requires sensitive face-to-face consultation and formal letters.","D":"Incorrect because financial charts require reports or visual presentations."}}},{"id":"P1_U2_MCQ_961","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_961","question":"What is a significant security and confidentiality risk associated with using 'email' in business?","options":{"A":"Confidential files can be accidentally forwarded or sent via 'Reply All' to unintended recipients, or intercepted if accounts are hacked","B":"Emails self-delete automatically five seconds after being opened","C":"Emails cannot be sent outside the company's local office building","D":"Emails prevent attachments from being saved on company servers"},"correctOption":"A","correctAnswer":"Confidential files can be accidentally forwarded or sent via 'Reply All' to unintended recipients, or intercepted if accounts are hacked","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because human error in addressing or weak cybersecurity can rapidly expose sensitive commercial or HR data.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because emails persist in inboxes and servers.","C":"Incorrect because email works globally over the internet.","D":"Incorrect because attachments are easily downloaded and stored."}}},{"id":"P1_U2_MCQ_962","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_962","question":"Why must a business assign trained staff to monitor and respond promptly on its 'social media' channels?","options":{"A":"Social media platforms legally require every company post to be approved by government auditors","B":"Unanswered social media posts automatically shut down the company's physical retail stores","C":"Customers expect rapid two-way engagement, and unanswered complaints or misleading posts can quickly harm brand reputation","D":"Social media is strictly an internal communication tool invisible to external consumers"},"correctOption":"C","correctAnswer":"Customers expect rapid two-way engagement, and unanswered complaints or misleading posts can quickly harm brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social media operates in real time and publicly; responsive moderation turns customer feedback into brand loyalty.","distractor_reasons":{"A":"Incorrect because governments do not pre-approve routine corporate social media posts.","B":"Incorrect because online activity does not mechanically close physical stores.","C":"Correct selection.","D":"Incorrect because public social media platforms are external channels."}}},{"id":"P1_U2_MCQ_963","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_963","question":"Why do workplace 'noticeboards' often become ineffective if they are not regularly managed?","options":{"A":"Noticeboards require expensive high-speed broadband connections to display paper posters","B":"Noticeboards allow employees to reply anonymously in real time","C":"Noticeboards are illegal under modern workplace health and safety laws","D":"Outdated flyers clutter the board, causing employees to ignore new, important announcements"},"correctOption":"D","correctAnswer":"Outdated flyers clutter the board, causing employees to ignore new, important announcements","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because visual clutter makes staff walk past noticeboards without reading urgent updates.","distractor_reasons":{"A":"Incorrect because traditional pinboards require no internet connection.","B":"Incorrect because noticeboards are one-way communication channels.","C":"Incorrect because safety laws actually require displaying certain statutory safety notices.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_964","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_964","question":"How do digital display screens in a modern factory improve upon traditional paper 'posters and noticeboards'?","options":{"A":"Digital screens never require electricity or software updates","B":"Live production targets, safety alerts, and shift notices can be updated instantaneously across multiple factory zones","C":"Digital screens automatically conduct two-way salary negotiations with individual workers","D":"Digital screens allow remote home workers to view factory floor displays without logging online"},"correctOption":"B","correctAnswer":"Live production targets, safety alerts, and shift notices can be updated instantaneously across multiple factory zones","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because centralized digital signage eliminates printing delays and keeps visual information dynamic and current.","distractor_reasons":{"A":"Incorrect because digital displays require electrical power and content management.","B":"Correct selection.","C":"Incorrect because display screens remain one-way visual broadcast tools.","D":"Incorrect because on-site screens are visible only to workers physically in the building."}}},{"id":"P1_U2_MCQ_965","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_965","question":"During a team briefing, a manager says 'My door is always open to your ideas,' while crossing their arms, frowning, and checking their watch repeatedly. Which communication issue does this illustrate?","options":{"A":"Contradictory non-verbal body language undermines the spoken message, deterring staff from sharing feedback","B":"Excessive use of technical financial acronyms creates a language barrier","C":"Poor internet bandwidth disrupts a virtual video conference","D":"A flat organisational structure slows down upward communication"},"correctOption":"A","correctAnswer":"Contradictory non-verbal body language undermines the spoken message, deterring staff from sharing feedback","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receivers trust non-verbal cues (impatient posture) over words when the two conflict.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the words used were plain English without acronyms.","C":"Incorrect because this occurred in a face-to-face briefing.","D":"Incorrect because flat structures speed up rather than slow down communication."}}},{"id":"P1_U2_MCQ_966","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_966","question":"What is 'selective perception (filtering)' as a receiver communication barrier?","options":{"A":"A receiver loses an email because their company computer crashes","B":"A sender accidentally sends a memo in the wrong foreign language","C":"A receiver hears only the parts of a message that fit their existing expectations while ignoring unwelcome details","D":"Loud construction drilling outside an office window drowns out a phone call"},"correctOption":"C","correctAnswer":"A receiver hears only the parts of a message that fit their existing expectations while ignoring unwelcome details","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because psychological bias leads receivers to misinterpret or overlook information that challenges their assumptions.","distractor_reasons":{"A":"Incorrect because a computer crash is a technical medium failure.","B":"Incorrect because wrong language choice is a sender encoding error.","C":"Correct selection.","D":"Incorrect because construction noise is a physical environmental barrier."}}},{"id":"P1_U2_MCQ_967","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_967","question":"How can cultural differences between international offices act as a communication barrier even when both offices speak the same language?","options":{"A":"International email servers reject messages sent across national borders","B":"Different countries use completely different mathematical rules for profit calculations","C":"Cultural differences prevent businesses from using virtual meetings or written contracts","D":"Differences in directness, politeness norms, humour, and attitudes toward hierarchy can cause blunt phrasing to seem rude or indirect phrasing to seem vague"},"correctOption":"D","correctAnswer":"Differences in directness, politeness norms, humour, and attitudes toward hierarchy can cause blunt phrasing to seem rude or indirect phrasing to seem vague","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because communication etiquette and implicit social cues vary widely across national cultures.","distractor_reasons":{"A":"Incorrect because global email networks operate seamlessly across borders.","B":"Incorrect because standard arithmetic is universal.","C":"Incorrect because international firms routinely use virtual meetings and contracts.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_968","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_968","question":"Why do 'status differences' within a rigid hierarchy often act as a barrier to upward communication?","options":{"A":"Senior directors have spans of control that are too wide to read emails","B":"Junior employees may feel intimidated by senior executives and hesitate to report operational problems or suggest improvements","C":"Junior employees are legally forbidden from speaking to managers above supervisor level","D":"Senior directors lack access to company telephones or meeting rooms"},"correctOption":"B","correctAnswer":"Junior employees may feel intimidated by senior executives and hesitate to report operational problems or suggest improvements","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fear of appearing incompetent or offending senior authority suppresses honest upward feedback.","distractor_reasons":{"A":"Incorrect because senior directors normally have narrow spans of control.","B":"Correct selection.","C":"Incorrect because there is no legal ban on cross-tier communication.","D":"Incorrect because directors have full access to communication channels."}}},{"id":"P1_U2_MCQ_969","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_969","question":"Which management practice best overcomes 'status barriers' so frontline staff feel comfortable sharing upward feedback?","options":{"A":"Operating an approachable 'open-door' policy, informal walk-arounds, and anonymous staff suggestion schemes","B":"Adding three extra layers of middle management between directors and shop-floor workers","C":"Issuing all policies solely through formal legal letters signed by corporate lawyers","D":"Forbidding frontline workers from attending team briefings"},"correctOption":"A","correctAnswer":"Operating an approachable 'open-door' policy, informal walk-arounds, and anonymous staff suggestion schemes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visible executive approachability and safe anonymous channels encourage honest ideas and early problem reporting.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because extra hierarchy tiers widen status distance.","C":"Incorrect because formal legalistic notices increase intimidation.","D":"Incorrect because excluding staff from briefings blocks upward and downward dialogue."}}},{"id":"P1_U2_MCQ_970","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_970","question":"How can a sender make a long written business report easier for busy managers to decode accurately?","options":{"A":"Write the entire report as a single unbroken 20-page paragraph without headings","B":"Include unrelated personal stories and dense technical acronyms throughout","C":"Start with a concise executive summary, use clear headings, bullet points, and visual charts, and highlight recommended actions","D":"Send the report via 150 separate SMS text messages"},"correctOption":"C","correctAnswer":"Start with a concise executive summary, use clear headings, bullet points, and visual charts, and highlight recommended actions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because logical structure, visual summaries, and clear formatting prevent information overload and aid comprehension.","distractor_reasons":{"A":"Incorrect because unbroken text walls overwhelm readers and obscure key points.","B":"Incorrect because irrelevant details and jargon create noise and confusion.","C":"Correct selection.","D":"Incorrect because SMS is wholly unsuitable for formal reports."}}},{"id":"P1_U2_MCQ_971","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_971","question":"In a noisy bottling plant where workers must wear ear defenders, spoken warnings cannot be heard clearly. How can management overcome this physical communication barrier?","options":{"A":"Ask supervisors to whisper instructions from across the factory floor","B":"Send urgent machine-jam warnings via standard postal letters","C":"Remove workers' protective ear defenders so they can hear better","D":"Install flashing visual warning lights, digital display boards, and noise-cancelling radio headsets"},"correctOption":"D","correctAnswer":"Install flashing visual warning lights, digital display boards, and noise-cancelling radio headsets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because visual signals and integrated protective headsets overcome acoustic noise without compromising hearing safety.","distractor_reasons":{"A":"Incorrect because whispering is inaudible over machinery noise.","B":"Incorrect because postal mail is useless for real-time machine alerts.","C":"Incorrect because removing ear defenders breaches health and safety laws.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_972","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_972","question":"Why is empathetic, two-way external communication vital when handling a customer's product complaint?","options":{"A":"It legally prevents the customer from ever requesting a refund","B":"Listening actively, apologizing sincerely, and confirming a clear solution can turn a dissatisfied buyer into a loyal repeat customer","C":"It eliminates the need for the Operations department to fix manufacturing defects","D":"It allows the business to ignore consumer protection legislation"},"correctOption":"B","correctAnswer":"Listening actively, apologizing sincerely, and confirming a clear solution can turn a dissatisfied buyer into a loyal repeat customer","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because responsive customer service protects brand reputation and provides valuable feedback to improve quality.","distractor_reasons":{"A":"Incorrect because statutory refund rights remain intact.","B":"Correct selection.","C":"Incorrect because recurring complaints should trigger operational quality improvements.","D":"Incorrect because consumer laws remain fully binding."}}},{"id":"P1_U2_MCQ_973","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_973","question":"When a small business applies to a commercial bank for an expansion loan, why is clear, well-structured external communication essential?","options":{"A":"A detailed business plan with realistic cash-flow forecasts reassures the bank that the business is well managed and able to repay the loan","B":"Banks approve all loan applications automatically based on casual phone calls without written figures","C":"Clear communication forces the bank to charge a 0% interest rate","D":"External communication with banks replaces the need to keep internal accounting records"},"correctOption":"A","correctAnswer":"A detailed business plan with realistic cash-flow forecasts reassures the bank that the business is well managed and able to repay the loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders rely on accurate written financial projections to assess lending risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks require formal documentary evidence before lending.","C":"Incorrect because interest rates reflect risk and market rates.","D":"Incorrect because accurate internal accounts are needed to produce the loan proposal."}}},{"id":"P1_U2_MCQ_974","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_974","question":"A software company employs 60 hybrid workers split between home and office. Which communication routine best maintains team coordination without causing email overload?","options":{"A":"Sending 100 individual emails per day to every employee for every minor task update","B":"Relying solely on a physical paper noticeboard in the office kitchen","C":"Holding short scheduled daily video stand-ups alongside a shared online project board where task statuses are updated centrally","D":"Eliminating all meetings and relying on informal phone rumours"},"correctOption":"C","correctAnswer":"Holding short scheduled daily video stand-ups alongside a shared online project board where task statuses are updated centrally","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because structured brief video check-ins foster team connection while a centralized digital board keeps task tracking transparent.","distractor_reasons":{"A":"Incorrect because broadcasting hundreds of emails causes severe information overload.","B":"Incorrect because home-based workers cannot see an office kitchen noticeboard.","C":"Correct selection.","D":"Incorrect because abandoning structured channels causes missed deadlines and confusion."}}},{"id":"P1_U2_MCQ_975","section":"2","unit":"Unit 2: People in Business","chapter":"2.3 Methods of communication","questionNumber":"P1_U2_MCQ_975","question":"Two rival firms announce a merger, and rumours immediately spread via the grapevine that half the workforce will be sacked. How should senior management communicate to stop panic and productivity loss?","options":{"A":"Remain completely silent for six months until all merger plans are finalized","B":"Send a brief two-sentence SMS text message telling staff not to ask questions","C":"Pin a single technical legal document in the head-office lobby","D":"Hold immediate transparent all-staff town-hall briefings (in-person and virtual) with Q&A, backed by regular honest written updates"},"correctOption":"D","correctAnswer":"Hold immediate transparent all-staff town-hall briefings (in-person and virtual) with Q&A, backed by regular honest written updates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because prompt, honest, two-way communication directly from leadership counters false rumours and reassures employees.","distractor_reasons":{"A":"Incorrect because management silence fuels grapevine anxiety and causes top staff to resign.","B":"Incorrect because shutting down questions increases distrust.","C":"Incorrect because jargon-heavy legal notices fail to reach or reassure all sites.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_976","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_976","question":"How does higher employee motivation help reduce a manufacturing business's 'average unit labour cost'?","options":{"A":"Motivated workers voluntarily accept hourly wages below the legal minimum wage","B":"Motivated workers produce more output per hour with fewer defective items, spreading wage costs over more sellable units","C":"Motivated workers never take statutory annual holidays or lunch breaks","D":"Motivated workers eliminate the need to buy raw materials"},"correctOption":"B","correctAnswer":"Motivated workers produce more output per hour with fewer defective items, spreading wage costs over more sellable units","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher labour productivity (output per worker) lowers the labour cost embedded in each unit produced.","distractor_reasons":{"A":"Incorrect because minimum wage laws apply to all workers.","B":"Correct selection.","C":"Incorrect because employees still take statutory leave and rest breaks.","D":"Incorrect because raw materials are still required, though wastage falls."}}},{"id":"P1_U2_MCQ_977","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_977","question":"Why is employee motivation particularly critical in customer-facing tertiary businesses such as airlines, hotels, and retail stores?","options":{"A":"Frontline staff interact directly with customers, so their enthusiasm, politeness, and attentiveness directly shape service quality and repeat sales","B":"Service businesses employ zero managers or supervisors","C":"Customers in hotels and stores never notice whether staff are helpful or rude","D":"Service workers are paid exclusively via piece-rate manufacturing quotas"},"correctOption":"A","correctAnswer":"Frontline staff interact directly with customers, so their enthusiasm, politeness, and attentiveness directly shape service quality and repeat sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in service industries the employee's attitude is an inseparable part of the customer experience.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because service businesses have structured management hierarchies.","C":"Incorrect because customer satisfaction depends heavily on staff demeanour.","D":"Incorrect because service roles rarely use physical unit piece-rates."}}},{"id":"P1_U2_MCQ_978","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_978","question":"Which workplace practice reflects F.W. Taylor's 'scientific management' principles?","options":{"A":"Giving every worker complete freedom to choose their own assembly sequence and working hours","B":"Organizing self-managed quality circles to redesign corporate strategy","C":"Providing private healthcare and subsidized gym memberships instead of piece-rate pay","D":"Breaking production into simple, specialized, repetitive tasks with standardized tools and paying workers per unit completed"},"correctOption":"D","correctAnswer":"Breaking production into simple, specialized, repetitive tasks with standardized tools and paying workers per unit completed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Taylor combined task specialization, time-and-motion standardization, and output-linked financial rewards.","distractor_reasons":{"A":"Incorrect because worker autonomy contradicts Taylor's centralized standardization.","B":"Incorrect because quality circles reflect participative motivation rather than Taylorism.","C":"Incorrect because Taylor focused on direct output pay rather than fringe benefits.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_979","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_979","question":"How do later motivation theorists (such as Maslow and Herzberg) criticize F.W. Taylor's view of workers?","options":{"A":"They argued Taylor placed too much emphasis on teamworking and social belonging","B":"They proved that money has zero importance in paying for food or housing","C":"They argued Taylor treated workers purely as 'economic machines' driven by money, ignoring social belonging, esteem, and job satisfaction","D":"They claimed that division of labour is illegal in modern factories"},"correctOption":"C","correctAnswer":"They argued Taylor treated workers purely as 'economic machines' driven by money, ignoring social belonging, esteem, and job satisfaction","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Maslow and Herzberg demonstrated that psychological growth, recognition, and interesting work are vital motivators alongside fair pay.","distractor_reasons":{"A":"Incorrect because Taylor focused on individual output rather than social teamwork.","B":"Incorrect because both Maslow (physiological/safety) and Herzberg (hygiene) recognized pay's foundational role.","C":"Correct selection.","D":"Incorrect because division of labour remains common, though often enriched to reduce boredom."}}},{"id":"P1_U2_MCQ_980","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_980","question":"In Abraham Maslow's hierarchy of needs, how do 'physiological needs' differ from 'safety and security needs'?","options":{"A":"Physiological needs involve peer friendship, whereas safety needs involve public awards","B":"Physiological needs cover immediate biological survival (food, water, shelter), whereas safety needs cover protection from physical harm and future job/income loss","C":"Physiological needs sit at the top of the pyramid, whereas safety needs sit at the bottom","D":"Physiological needs are met through job enrichment, whereas safety needs are met through quality circles"},"correctOption":"B","correctAnswer":"Physiological needs cover immediate biological survival (food, water, shelter), whereas safety needs cover protection from physical harm and future job/income loss","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because physiological survival forms tier 1, while physical safety and contractual/financial stability form tier 2.","distractor_reasons":{"A":"Incorrect because friendship is social needs and awards are esteem needs.","B":"Correct selection.","C":"Incorrect because physiological needs are at the base and self-actualization is at the top.","D":"Incorrect because job enrichment addresses higher-order esteem and self-actualization needs."}}},{"id":"P1_U2_MCQ_981","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_981","question":"Which workplace opportunity best helps an employee satisfy 'self-actualization needs' at the top of Maslow's pyramid?","options":{"A":"Leading a challenging, creative project that allows the employee to develop new skills and achieve their full personal potential","B":"Receiving a basic hourly wage sufficient to buy groceries","C":"Being issued a high-visibility safety vest on a construction site","D":"Eating lunch in a shared staff canteen with friendly coworkers"},"correctOption":"A","correctAnswer":"Leading a challenging, creative project that allows the employee to develop new skills and achieve their full personal potential","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because self-actualization involves personal growth, creativity, and realizing one's highest capabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because basic wages satisfy physiological needs.","C":"Incorrect because protective gear satisfies safety needs.","D":"Incorrect because social interaction satisfies social needs."}}},{"id":"P1_U2_MCQ_982","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_982","question":"According to Maslow's hierarchy, what is likely to happen if a senior software architect who previously focused on creative self-actualization hears credible news of imminent company bankruptcy and layoffs?","options":{"A":"The employee becomes even more focused on unpaid creative hobbies at work","B":"The employee permanently stops caring about income or employment contracts","C":"The employee moves upward to a sixth tier above self-actualization","D":"Threatened job security pulls the employee's focus back down to lower-level safety and security needs"},"correctOption":"D","correctAnswer":"Threatened job security pulls the employee's focus back down to lower-level safety and security needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when previously satisfied lower needs are threatened, individuals prioritize restoring security before pursuing higher-level goals.","distractor_reasons":{"A":"Incorrect because imminent job loss undermines security and focus.","B":"Incorrect because financial and employment security immediately regain urgency.","C":"Incorrect because Maslow's standard model has five tiers ending with self-actualization.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_983","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_983","question":"In Frederick Herzberg's theory, what is the difference between 'movement' and true 'motivation'?","options":{"A":"Movement refers to job rotation across stations, whereas motivation refers to annual salary reviews","B":"Movement occurs only in factories, whereas motivation occurs only in schools","C":"Movement is short-term compliance driven by external rewards or threats (such as pay rises or fear), whereas motivation is internal willingness to work hard driven by the job itself","D":"Movement lasts permanently without supervision, whereas motivation disappears within twenty-four hours"},"correctOption":"C","correctAnswer":"Movement is short-term compliance driven by external rewards or threats (such as pay rises or fear), whereas motivation is internal willingness to work hard driven by the job itself","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Herzberg argued that external incentives ('kicks') produce temporary compliance, whereas intrinsic job enrichment creates lasting self-drive.","distractor_reasons":{"A":"Incorrect because movement in Herzberg's framework describes extrinsic compliance rather than job rotation.","B":"Incorrect because both concepts apply across all workplaces.","C":"Correct selection.","D":"Incorrect because this reverses the durability of extrinsic movement and intrinsic motivation."}}},{"id":"P1_U2_MCQ_984","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_984","question":"In Herzberg's two-factor theory, why are 'company policies and administration' classified as a hygiene factor?","options":{"A":"Excessive red tape and unfair rules cause deep employee dissatisfaction, while fair, sensible rules merely prevent frustration without actively inspiring extra effort","B":"Complex bureaucratic rules inspire workers to achieve maximum creativity","C":"Company policies satisfy self-actualization at the top of Maslow's pyramid","D":"Fair company rules replace the need to pay employees a salary"},"correctOption":"A","correctAnswer":"Excessive red tape and unfair rules cause deep employee dissatisfaction, while fair, sensible rules merely prevent frustration without actively inspiring extra effort","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bureaucratic obstacles irritate workers (dissatisfaction), whereas smooth administration removes friction without enriching job content.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bureaucracy hinders rather than inspires creativity.","C":"Incorrect because self-actualization is Maslow's concept.","D":"Incorrect because policies do not replace financial pay."}}},{"id":"P1_U2_MCQ_985","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_985","question":"According to Frederick Herzberg, how are 'recognition for achievement' and 'relationships with coworkers' classified respectively?","options":{"A":"Recognition is a motivator, whereas relationships with coworkers are a hygiene factor","B":"Both recognition and coworker relationships are hygiene factors","C":"Recognition is a hygiene factor, whereas coworker relationships are a motivator","D":"Neither factor has any effect on employee attitudes"},"correctOption":"A","correctAnswer":"Recognition is a motivator, whereas relationships with coworkers are a hygiene factor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Herzberg classified recognition tied to task achievement as an intrinsic motivator, while interpersonal workplace relations are an extrinsic hygiene factor.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because recognition is one of Herzberg's core motivators.","C":"Incorrect because this reverses the two classifications.","D":"Incorrect because both shape dissatisfaction or motivation."}}},{"id":"P1_U2_MCQ_986","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_986","question":"What is a potential financial risk for an employer paying factory workers a 'time-based wage' with higher overtime rates?","options":{"A":"Workers have zero financial incentive to work extra hours during rush periods","B":"Total labour costs automatically fall to zero whenever machines break down","C":"Workers earn identical pay whether they work 35 hours or 55 hours","D":"Workers may deliberately work slower during regular shifts so they are paid higher overtime rates to finish the workload"},"correctOption":"D","correctAnswer":"Workers may deliberately work slower during regular shifts so they are paid higher overtime rates to finish the workload","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because time-rate pay rewards hours present rather than output speed, creating a risk of 'stretching' tasks into overtime.","distractor_reasons":{"A":"Incorrect because overtime premiums strongly incentivize working extra hours.","B":"Incorrect because hourly wages must still be paid during machine downtime.","C":"Incorrect because total earnings rise directly with hours worked.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_987","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_987","question":"Why do businesses typically pay administrative, supervisory, and professional staff a fixed monthly 'salary' rather than piece-rate wages?","options":{"A":"Salaried workers are legally forbidden from receiving annual performance appraisals","B":"Salaries vary every single week depending on how many emails an employee sends","C":"Output in office and management roles cannot easily be counted per physical unit, and fixed salaries simplify payroll budgeting while giving staff income security","D":"Salaried employees are exempted from paying personal income tax"},"correctOption":"C","correctAnswer":"Output in office and management roles cannot easily be counted per physical unit, and fixed salaries simplify payroll budgeting while giving staff income security","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because managerial and clerical tasks involve varied, non-unit output where predictable monthly salaries support stability and professional commitment.","distractor_reasons":{"A":"Incorrect because salaried staff regularly undergo performance appraisals.","B":"Incorrect because salaries are fixed annual sums paid in equal monthly instalments.","C":"Correct selection.","D":"Incorrect because salaries are subject to normal income tax."}}},{"id":"P1_U2_MCQ_988","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_988","question":"What is a potential drawback of a fixed 'salary' system if salaried managers are routinely expected to work long unpaid evenings and weekends?","options":{"A":"The business's hourly overtime bill doubles every month","B":"Employees may feel unrewarded for extra effort, leading to burnout, resentment, and higher turnover","C":"Salaried managers receive piece-rate bonuses for every meeting attended","D":"Fixed salaries prevent the Finance department from forecasting annual wage costs"},"correctOption":"B","correctAnswer":"Employees may feel unrewarded for extra effort, leading to burnout, resentment, and higher turnover","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because because salaries typically exclude paid overtime, persistent uncompensated extra hours erode morale unless offset by bonuses or time off.","distractor_reasons":{"A":"Incorrect because salaried contracts generally do not pay hourly overtime.","B":"Correct selection.","C":"Incorrect because piece-rate applies to physical output units.","D":"Incorrect because fixed salaries actually make payroll forecasting easier."}}},{"id":"P1_U2_MCQ_989","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_989","question":"Why can 'piece-rate pay' cause industrial disputes in a factory when machinery breaks down or raw-material deliveries arrive late?","options":{"A":"Workers lose earnings through no fault of their own while waiting for repairs or materials, creating resentment unless a guaranteed base rate is paid","B":"Workers earn double their normal piece-rate pay whenever machines stop working","C":"Piece-rate pay applies only to senior company directors","D":"Machine breakdowns increase the number of completed units workers can produce"},"correctOption":"A","correctAnswer":"Workers lose earnings through no fault of their own while waiting for repairs or materials, creating resentment unless a guaranteed base rate is paid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pure piece-rate ties worker income strictly to completed units, leaving staff vulnerable to operational stoppages outside their control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because pure piece-rate pays zero during idle downtime.","C":"Incorrect because piece-rate is used for manual production rather than directors.","D":"Incorrect because breakdowns halt unit production."}}},{"id":"P1_U2_MCQ_990","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_990","question":"How does a 'team-based bonus' differ from an 'individual bonus' in motivating staff?","options":{"A":"A team-based bonus is paid in non-cash company cars, whereas an individual bonus is paid in cash","B":"A team-based bonus is guaranteed even when the team misses all targets","C":"An individual bonus encourages workers to share every trade secret freely with rivals","D":"A team-based bonus encourages cooperation and mutual help toward shared goals, though high performers may resent sharing rewards with slower teammates"},"correctOption":"D","correctAnswer":"A team-based bonus encourages cooperation and mutual help toward shared goals, though high performers may resent sharing rewards with slower teammates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because team bonuses foster collaboration across interdependent tasks, whereas individual bonuses drive personal output but can create selfish competition.","distractor_reasons":{"A":"Incorrect because both are financial cash rewards.","B":"Incorrect because bonuses depend on meeting agreed targets.","C":"Incorrect because individual bonuses focus on personal targets rather than helping rivals.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_991","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_991","question":"Why do many technology firms pay business-to-business sales representatives a moderate 'base salary' combined with 'sales commission'?","options":{"A":"To ensure sales representatives never attempt to close new customer contracts","B":"To avoid complying with statutory minimum wage legislation","C":"To provide financial security during long enterprise sales cycles while still rewarding high sales performance and discouraging pushy mis-selling","D":"To eliminate the need for customer service after a contract is signed"},"correctOption":"C","correctAnswer":"To provide financial security during long enterprise sales cycles while still rewarding high sales performance and discouraging pushy mis-selling","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because blending fixed salary and commission balances income stability (Maslow's safety needs) with performance drive.","distractor_reasons":{"A":"Incorrect because the commission element actively encourages closing sales.","B":"Incorrect because total pay must always meet or exceed minimum wage laws.","C":"Correct selection.","D":"Incorrect because ongoing customer support remains essential for repeat business."}}},{"id":"P1_U2_MCQ_992","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_992","question":"What is a common limitation of 'profit-sharing schemes' in a large multinational corporation employing 50,000 workers?","options":{"A":"Profit sharing is illegal for public limited companies","B":"Individual employees may feel their personal daily effort has little direct impact on total corporate profit, weakening day-to-day motivation","C":"Employees receive profit-sharing payouts every single Friday afternoon","D":"Profit sharing forces employees to pay company losses out of their personal savings"},"correctOption":"B","correctAnswer":"Individual employees may feel their personal daily effort has little direct impact on total corporate profit, weakening day-to-day motivation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in huge workforces the link between one worker's effort and overall company net profit feels distant and diluted.","distractor_reasons":{"A":"Incorrect because profit sharing is completely lawful and common in PLCs.","B":"Correct selection.","C":"Incorrect because profit shares are usually calculated and paid annually.","D":"Incorrect because employees do not personally underwrite corporate losses."}}},{"id":"P1_U2_MCQ_993","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_993","question":"Why do companies often require employees to stay with the firm for three years before selling shares awarded under an 'employee share ownership scheme'?","options":{"A":"To encourage long-term staff retention and align employees' commitment with multi-year business growth","B":"To prevent employees from ever receiving dividends on their shares","C":"To force employees to work unpaid overtime during those three years","D":"To avoid issuing written contracts of employment"},"correctOption":"A","correctAnswer":"To encourage long-term staff retention and align employees' commitment with multi-year business growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because vesting periods act as 'golden handcuffs,' reducing costly turnover among key staff.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shareholders are entitled to declared dividends.","C":"Incorrect because contractual working hours remain governed by employment contracts.","D":"Incorrect because contracts remain legally mandatory."}}},{"id":"P1_U2_MCQ_994","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_994","question":"Why do some modern employers offer 'flexible fringe benefit packages' where employees choose perks (such as childcare vouchers, extra leave, or gym membership) up to a set value?","options":{"A":"Flexible perks eliminate the need to pay any basic cash salary","B":"Flexible perks are completely free for the business to fund","C":"Flexible perks exempt the employer from health and safety inspections","D":"Different employees value different perks depending on age and family circumstances, maximizing perceived motivational value from the same budget"},"correctOption":"D","correctAnswer":"Different employees value different perks depending on age and family circumstances, maximizing perceived motivational value from the same budget","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a young graduate may value gym or transit passes while a parent values childcare support, increasing satisfaction per dollar spent.","distractor_reasons":{"A":"Incorrect because fringe benefits supplement rather than replace cash salaries.","B":"Incorrect because the employer funds the benefit allowance.","C":"Incorrect because statutory safety laws always apply.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_995","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_995","question":"What is a recognized limitation of 'job rotation' as a long-term motivational strategy?","options":{"A":"Employees permanently lose the ability to perform their original job","B":"Job rotation gives junior workers total control over company bank accounts","C":"If all rotated tasks are equally repetitive and low-skilled, workers may still feel bored and unchallenged over time","D":"Job rotation violates anti-discrimination employment laws"},"correctOption":"C","correctAnswer":"If all rotated tasks are equally repetitive and low-skilled, workers may still feel bored and unchallenged over time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rotating between several monotonous tasks provides variety without adding genuine responsibility or job enrichment.","distractor_reasons":{"A":"Incorrect because rotation maintains competence across multiple tasks.","B":"Incorrect because rotation switches workers across peer-level tasks without granting financial authority.","C":"Correct selection.","D":"Incorrect because fair task rotation is completely lawful."}}},{"id":"P1_U2_MCQ_996","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_996","question":"How can 'job enlargement' backfire if management introduces it poorly?","options":{"A":"Workers may become overly promoted into senior executive board roles","B":"Workers may view adding extra routine tasks of the same skill level simply as an increased workload without extra pay or genuine autonomy","C":"The business's training costs fall to zero while output triples automatically","D":"Workers gain too much strategic decision-making authority over corporate budgets"},"correctOption":"B","correctAnswer":"Workers may view adding extra routine tasks of the same skill level simply as an increased workload without extra pay or genuine autonomy","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because as Herzberg noted, adding one boring task to another boring task fails to create true intrinsic motivation.","distractor_reasons":{"A":"Incorrect because job enlargement adds horizontal peer-level duties rather than vertical promotion.","B":"Correct selection.","C":"Incorrect because workers still require training on any added duties.","D":"Incorrect because vertical budget authority belongs to senior management."}}},{"id":"P1_U2_MCQ_997","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_997","question":"What conditions are necessary for 'job enrichment' to succeed when introduced on a factory production line?","options":{"A":"Workers must receive adequate training, clear quality standards, and genuine delegation of authority rather than empty extra chores","B":"Supervisors must continue micromanaging every tiny movement workers make","C":"Workers must accept a 20% cut in their basic hourly wage","D":"Management must remove all teamworking and two-way feedback channels"},"correctOption":"A","correctAnswer":"Workers must receive adequate training, clear quality standards, and genuine delegation of authority rather than empty extra chores","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because enriching roles with planning, quality inspection, and problem-solving requires equipping staff with the skills and trust to succeed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because micromanagement destroys the autonomy required for job enrichment.","C":"Incorrect because cutting pay violates contracts and destroys hygiene factors.","D":"Incorrect because feedback and collaboration reinforce enriched work."}}},{"id":"P1_U2_MCQ_998","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_998","question":"What is a potential drawback of 'teamworking' if individual responsibilities within a group are poorly defined?","options":{"A":"Employees experience extreme social isolation from all coworkers","B":"Employees receive no feedback from team peers","C":"Teams complete every project in half the expected time without effort","D":"Some members may put in less effort ('social loafing') while relying on hardworking teammates to carry the group, causing conflict"},"correctOption":"D","correctAnswer":"Some members may put in less effort ('social loafing') while relying on hardworking teammates to carry the group, causing conflict","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unclear individual accountability can allow free-riding, which demotivates conscientious team members.","distractor_reasons":{"A":"Incorrect because teamworking increases social interaction.","B":"Incorrect because peer interaction provides regular feedback.","C":"Incorrect because free-riding slows down team performance.","D":"Correct selection."}}},{"id":"P1_U2_MCQ_999","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_999","question":"Why does 'praise and recognition' lose its motivational impact if a manager hands out generic compliments indiscriminately regardless of actual effort?","options":{"A":"Employees legally lose their statutory holiday pay when praised too often","B":"Generic praise increases the company's corporate income tax rate","C":"Recognition feels insincere and unfair to top performers when outstanding work is not distinguished from average effort","D":"Praise converts non-financial motivation into piece-rate wages"},"correctOption":"C","correctAnswer":"Recognition feels insincere and unfair to top performers when outstanding work is not distinguished from average effort","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because meaningful recognition must be specific, timely, and genuinely earned to satisfy esteem needs.","distractor_reasons":{"A":"Incorrect because praise has no effect on holiday entitlements.","B":"Incorrect because verbal praise does not affect tax rates.","C":"Correct selection.","D":"Incorrect because praise remains a non-financial motivator."}}},{"id":"P1_U2_MCQ_1000","section":"2","unit":"Unit 2: People in Business","chapter":"2.4 Motivating employees","questionNumber":"P1_U2_MCQ_1000","question":"Synthesizing Taylor, Maslow, and Herzberg, which overall human resource strategy is most effective for sustaining high workforce motivation and low turnover?","options":{"A":"Pay workers strictly piece-rate wages in unsafe conditions while forbidding all communication or promotion","B":"Provide competitive pay, job security, and safe working conditions (hygiene/lower needs), combined with enriched roles, teamwork, training, and recognition (motivators/higher needs)","C":"Eliminate financial salaries completely and rely solely on monthly recognition certificates","D":"Maintain a 10-tier autocratic hierarchy where managers never delegate or consult employees"},"correctOption":"B","correctAnswer":"Provide competitive pay, job security, and safe working conditions (hygiene/lower needs), combined with enriched roles, teamwork, training, and recognition (motivators/higher needs)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustainable motivation requires satisfying foundational financial and security needs first, then building intrinsic engagement through autonomy, growth, and recognition.","distractor_reasons":{"A":"Incorrect because unsafe conditions and zero autonomy breach laws and cause severe dissatisfaction.","B":"Correct selection.","C":"Incorrect because employees work primarily to earn income for living and security needs.","D":"Incorrect because tall autocratic hierarchies slow communication and stifle higher-order motivation."}}}];
